"""
Agent Memory Graph — AI Agent 的记忆网络

概念演示：用知识图谱管理 Agent 的长期记忆。
节点 = 概念/实体/事件，边 = 关系。
支持：添加记忆、语义召回、遗忘衰减、摘要压缩。

Usage:
    python memory_graph.py

依赖：仅需 Python 标准库（sqlite3 + json + math）
"""

import sqlite3
import json
import math
import time
import uuid
from datetime import datetime
from dataclasses import dataclass, field
from typing import Optional
from collections import defaultdict

# ── 数据模型 ──────────────────────────────────────────────

@dataclass
class Node:
    id: str
    label: str           # 简短描述
    kind: str            # fact | event | person | concept | skill
    data: dict = field(default_factory=dict)
    created: float = 0.0
    accessed: float = 0.0
    weight: float = 1.0  # 记忆强度 0~1

@dataclass
class Edge:
    source: str
    target: str
    relation: str        # e.g. "likes", "works_on", "caused"
    weight: float = 1.0

# ── 记忆图谱 ──────────────────────────────────────────────

class MemoryGraph:
    """基于 SQLite 的轻量知识图谱，模拟人类长期记忆。"""

    # 遗忘曲线参数（Ebbinghaus）
    DECAY_RATE = 0.3          # 衰减速率
    ACCESS_BOOST = 0.4        # 每次访问恢复量
    MIN_WEIGHT = 0.05         # 低于此阈值视为"遗忘"

    def __init__(self, db_path: str = ":memory:"):
        self.conn = sqlite3.connect(db_path)
        self.conn.row_factory = sqlite3.Row
        self._lamport_clock = 0
        self._typed_subscribers: dict[str, list[tuple[str, callable]]] = {}
        self._init_schema()
        self._init_immutable_store()

    def _init_schema(self):
        self.conn.executescript("""
            CREATE TABLE IF NOT EXISTS nodes (
                id TEXT PRIMARY KEY,
                label TEXT,
                kind TEXT,
                data TEXT DEFAULT '{}',
                created REAL,
                accessed REAL,
                weight REAL DEFAULT 1.0,
                tags TEXT DEFAULT '[]'
            );
            CREATE TABLE IF NOT EXISTS edges (
                source TEXT,
                target TEXT,
                relation TEXT,
                weight REAL DEFAULT 1.0,
                PRIMARY KEY (source, target, relation)
            );
            CREATE TABLE IF NOT EXISTS evolution_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                node_id TEXT NOT NULL,
                old_label TEXT,
                new_label TEXT,
                old_kind TEXT,
                new_kind TEXT,
                timestamp REAL NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_evo_node ON evolution_log(node_id);
            CREATE TABLE IF NOT EXISTS edge_props (
                source TEXT,
                target TEXT,
                relation TEXT,
                properties TEXT DEFAULT '{}',
                PRIMARY KEY (source, target, relation)
            );
            CREATE TABLE IF NOT EXISTS entity_aliases (
                alias_key TEXT PRIMARY KEY,
                canonical_label TEXT NOT NULL,
                alias_display TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_alias_canonical ON entity_aliases(canonical_label);
        """)
        # Schema migration: add provenance + quarantine columns (backward compatible)
        existing_cols = {row[1] for row in self.conn.execute("PRAGMA table_info(nodes)").fetchall()}
        migrations = [
            ("source", "TEXT DEFAULT NULL"),
            ("trust_level", "REAL DEFAULT 1.0"),
            ("parents", "TEXT DEFAULT '[]'"),
            ("quarantined", "INTEGER DEFAULT 0"),
            ("quarantine_reason", "TEXT DEFAULT NULL"),
            ("valid_from", "REAL DEFAULT NULL"),
            ("valid_to", "REAL DEFAULT NULL"),
            ("txn_time", "REAL DEFAULT NULL"),
            ("q_value", "REAL DEFAULT 0.0"),
            ("activation", "REAL DEFAULT 0.0"),
            ("transform_count", "INTEGER DEFAULT 0"),
            ("confidence", "REAL DEFAULT 0.5"),
            ("category", "TEXT DEFAULT NULL"),
        ]
        for col, typedef in migrations:
            if col not in existing_cols:
                self.conn.execute(f"ALTER TABLE nodes ADD COLUMN {col} {typedef}")
        # FTS5 full-text index for BM25 search
        try:
            self.conn.execute("""
                CREATE VIRTUAL TABLE IF NOT EXISTS nodes_fts
                USING fts5(node_id UNINDEXED, label, kind, data, tags,
                           tokenize='unicode61')
            """)
            self._fts_enabled = True
        except sqlite3.OperationalError:
            self._fts_enabled = False
        # Vector clock event log
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS clock_log (
                lamport INTEGER PRIMARY KEY,
                op TEXT NOT NULL,
                node_id TEXT,
                details TEXT DEFAULT '{}',
                wall_time REAL
            )
        """)
        # Retrieval failure log (SAGE reader-writer feedback)
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS retrieval_failures (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                query TEXT NOT NULL,
                result_count INTEGER DEFAULT 0,
                top_score REAL DEFAULT 0.0,
                stage TEXT DEFAULT 'recall',
                timestamp REAL NOT NULL,
                analysed INTEGER DEFAULT 0
            )
        """)
        self.conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_rf_ts ON retrieval_failures(timestamp)"
        )

    def add(self, label: str, kind: str = "fact", data: dict = None,
            tags: list[str] = None, category: str = None) -> Node:
        """添加一个记忆节点。

        Args:
            label: Short description of the memory.
            kind: Semantic type (fact|event|person|concept|skill).
            data: Arbitrary metadata dict.
            tags: List of string tags for filtering.
            category: Optional category for selective retrieval
                (Apple Shared Selective Memory, 2607.09493).
                Common values: 'preference', 'protocol', 'episodic',
                'reference', 'skill'. Enables category-aware filtering
                in recall and retrieval pipelines.
        """
        node = Node(
            id=uuid.uuid4().hex[:12],
            label=label, kind=kind,
            data=data or {},
            created=time.time(), accessed=time.time(), weight=1.0
        )
        self.conn.execute(
            "INSERT INTO nodes (id,label,kind,data,created,accessed,weight,tags,category) VALUES (?,?,?,?,?,?,?,?,?)",
            (node.id, node.label, node.kind, json.dumps(node.data),
             node.created, node.accessed, node.weight, json.dumps(tags or []),
             category)
        )
        self._fts_sync_node(node.id)
        self._immutable_log(node.id, node.label, node.kind, node.data,
                            tags or [], category)
        self.conn.commit()
        self._tick("add", node.id, {"label": label, "kind": kind,
                                     "category": category})
        return node

    def add_with_entropy_filter(self, label: str, kind: str = "fact",
                                data: dict = None, tags: list[str] = None,
                                threshold: float = 0.3) -> Optional[Node]:
        """Add a node only if its information density exceeds *threshold*.

        Inspired by SimpleMem (ICML 2026): entropy-aware filtering at write
        time discards low-value content before it enters the graph, saving
        downstream retrieval and storage costs.

        The entropy score is a normalised composite of:
        - **Lexical diversity** — unique words / total words (type-token ratio).
        - **Length factor** — penalises very short inputs (< 5 chars).
        - **Novelty** — Jaccard distance vs the most similar existing node.
          Completely duplicated content gets novelty = 0.

        Score range is [0, 1]. Default threshold 0.3 filters out trivial
        duplicates and near-empty strings while accepting genuinely new
        information.

        Args:
            label: Text content for the node.
            kind: Node kind (default ``'fact'``).
            data: Optional metadata dict.
            tags: Optional tag list.
            threshold: Minimum entropy score to accept. ``0.0`` accepts all.

        Returns:
            The created ``Node`` if accepted, or ``None`` if filtered.
        """
        score = self._entropy_score(label)
        if score < threshold:
            return None
        return self.add(label, kind, data, tags)

    def _entropy_score(self, text: str) -> float:
        """Compute normalised information density score for *text*.

        Returns a float in [0, 1]. See ``add_with_entropy_filter`` for
        the composite formula.
        """
        text = text.strip()
        if len(text) < 5:
            return 0.0
        words = text.lower().split()
        if not words:
            return 0.0
        # Lexical diversity (type-token ratio)
        unique = set(words)
        ttr = len(unique) / len(words)
        # Length factor: full credit above 20 chars, linear below
        length_factor = min(1.0, len(text) / 20.0)
        # Novelty: Jaccard distance to nearest existing node label
        novelty = 1.0  # default if no existing nodes
        existing = self.conn.execute(
            "SELECT label FROM nodes LIMIT 500"
        ).fetchall()
        if existing:
            text_set = unique
            best_sim = 0.0
            for r in existing:
                other_set = set(r["label"].lower().split())
                if not other_set:
                    continue
                union = text_set | other_set
                if union:
                    sim = len(text_set & other_set) / len(union)
                    if sim > best_sim:
                        best_sim = sim
            novelty = 1.0 - best_sim
        # Composite: weighted geometric mean
        # Weights: novelty 50%, lexical diversity 30%, length 20%
        import math
        score = (novelty ** 0.5) * (ttr ** 0.3) * (length_factor ** 0.2)
        return round(score, 4)

    def get_node(self, node_id: str) -> Optional[Node]:
        """Retrieve a single node by ID. Returns None if not found."""
        row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return None
        return Node(row["id"], row["label"], row["kind"],
                    json.loads(row["data"]), row["created"], row["accessed"], row["weight"])

    def delete_node(self, node_id: str) -> bool:
        """Delete a node and all its edges. Returns True if node existed."""
        row = self.conn.execute("SELECT id FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return False
        self.conn.execute("DELETE FROM edges WHERE source=? OR target=?", (node_id, node_id))
        self._fts_delete_node(node_id)
        self.conn.execute("DELETE FROM nodes WHERE id=?", (node_id,))
        self.conn.commit()
        self._tick("delete", node_id, {"node_id": node_id})
        return True

    def update_node(self, node_id: str, label: str = None, kind: str = None,
                    data: dict = None, weight: float = None) -> Optional[Node]:
        """Update node attributes. Only non-None fields are changed. Returns updated node or None."""
        row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return None
        old_label = row["label"]
        new_label = label if label is not None else row["label"]
        new_kind = kind if kind is not None else row["kind"]
        new_data = json.dumps(data) if data is not None else row["data"]
        new_weight = weight if weight is not None else row["weight"]
        self.conn.execute(
            "UPDATE nodes SET label=?, kind=?, data=?, weight=? WHERE id=?",
            (new_label, new_kind, new_data, new_weight, node_id)
        )
        self._fts_sync_node(node_id)
        self.conn.commit()
        self._tick("update", node_id,
                   {"old_label": old_label, "new_label": new_label,
                    "old_kind": row["kind"], "new_kind": new_kind})
        return self.get_node(node_id)

    def add_many(self, items: list[dict]) -> list[Node]:
        """Batch-add nodes. Each item is a dict with keys: label, kind?, data?, tags?.
        Uses a single transaction for efficiency."""
        now = time.time()
        nodes = []
        for item in items:
            node = Node(
                id=uuid.uuid4().hex[:12],
                label=item["label"],
                kind=item.get("kind", "fact"),
                data=item.get("data", {}),
                created=now, accessed=now, weight=1.0
            )
            tags = item.get("tags", [])
            self.conn.execute(
                "INSERT INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                (node.id, node.label, node.kind, json.dumps(node.data),
                 node.created, node.accessed, node.weight, json.dumps(tags))
            )
            self._fts_sync_node(node.id)
            nodes.append(node)
        self.conn.commit()
        return nodes

    def link_many(self, pairs: list[dict]) -> int:
        """Batch-link nodes. Each dict: {source, target, relation, weight?}.
        Returns count of edges created."""
        count = 0
        for p in pairs:
            self.conn.execute(
                "INSERT OR REPLACE INTO edges VALUES (?,?,?,?)",
                (p["source"], p["target"], p["relation"], p.get("weight", 1.0))
            )
            count += 1
        self.conn.commit()
        return count

    def delete_many(self, node_ids: list[str], *, force: bool = False) -> int:
        """Batch-delete nodes with edge cleanup. Returns count of nodes deleted.

        Args:
            node_ids: List of node IDs to delete. Must be non-empty.
            force: If True, bypass the no-scope-delete guard.
                   (no-scope-mass-delete protection per memorywire spec)
        """
        if not node_ids and not force:
            raise ValueError(
                "delete_many requires non-empty node_ids "
                "(no-scope-mass-delete protection). Pass force=True to override."
            )
        count = 0
        for nid in node_ids:
            row = self.conn.execute("SELECT id FROM nodes WHERE id=?", (nid,)).fetchone()
            if row:
                self.conn.execute("DELETE FROM edges WHERE source=? OR target=?", (nid, nid))
                self.conn.execute("DELETE FROM nodes WHERE id=?", (nid,))
                count += 1
        self.conn.commit()
        return count

    def tag_nodes(self, tag: str, node_ids: list[str]):
        """Add a tag to multiple nodes."""
        for nid in node_ids:
            row = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (nid,)).fetchone()
            if not row:
                continue
            tags = json.loads(row["tags"])
            if tag not in tags:
                tags.append(tag)
                self.conn.execute("UPDATE nodes SET tags=? WHERE id=?", (json.dumps(tags), nid))
                self._fts_sync_node(nid)
        self.conn.commit()

    def search_by_tag(self, tag: str) -> list[Node]:  # noqa: F811
        """Return all nodes with a given tag (excludes quarantined)."""
        rows = self.conn.execute("SELECT * FROM nodes WHERE quarantined = 0").fetchall()
        results = []
        for r in rows:
            tags_list = json.loads(r["tags"])
            if tag in tags_list:
                results.append(Node(
                    r["id"], r["label"], r["kind"],
                    json.loads(r["data"]), r["created"], r["accessed"], r["weight"]
                ))
        return results

    def search_by_category(self, category: str) -> list[Node]:
        """Return all nodes in a given category.

        Categories enable selective memory retrieval (Apple Shared
        Selective Memory, 2607.09493): instead of searching all
        memories, filter to a relevant slice (e.g., 'preference',
        'protocol') for higher signal-to-noise ratio.

        Excludes quarantined nodes.
        """
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE category=? AND quarantined = 0",
            (category,)
        ).fetchall()
        return [
            Node(r["id"], r["label"], r["kind"],
                 json.loads(r["data"]), r["created"], r["accessed"], r["weight"])
            for r in rows
        ]

    def link(self, source_id: str, target_id: str, relation: str, weight: float = 1.0):
        """连接两个节点。"""
        self.conn.execute(
            "INSERT OR REPLACE INTO edges VALUES (?,?,?,?)",
            (source_id, target_id, relation, weight)
        )
        self.conn.commit()
        self._tick("link", source_id,
                   {"source": source_id, "target": target_id, "relation": relation})

    def link_by_label(self, source_label: str, target_label: str, relation: str,
                      weight: float = 1.0) -> bool:
        """Connect two nodes by their labels.

        Resolves labels to node IDs and calls link().
        If either label is not found, does nothing and returns False.

        Args:
            source_label: Label of the source node
            target_label: Label of the target node
            relation: Edge relation type
            weight: Edge weight (default 1.0)

        Returns:
            True if linked, False if either node not found
        """
        src = self.conn.execute(
            "SELECT id FROM nodes WHERE label=? ORDER BY created DESC LIMIT 1",
            (source_label,)
        ).fetchone()
        tgt = self.conn.execute(
            "SELECT id FROM nodes WHERE label=? ORDER BY created DESC LIMIT 1",
            (target_label,)
        ).fetchone()
        if not src or not tgt:
            return False
        self.link(src["id"], tgt["id"], relation, weight)
        return True

    def unlink(self, source_id: str, target_id: str, relation: str):
        """Remove an edge between two nodes."""
        self.conn.execute(
            "DELETE FROM edges WHERE source=? AND target=? AND relation=?",
            (source_id, target_id, relation)
        )
        self.conn.commit()

    def recall(self, query: str, limit: int = 5) -> list[Node]:
        """按关键词召回记忆，访问过的记忆强度增加。"""
        now = time.time()
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE label LIKE ? AND quarantined = 0 ORDER BY weight DESC LIMIT ?",
            (f"%{query}%", limit)
        ).fetchall()

        results = []
        for r in rows:
            # 应用遗忘衰减
            elapsed_days = (now - r["accessed"]) / 86400
            decayed = r["weight"] * math.exp(-self.DECAY_RATE * elapsed_days)
            boosted = min(1.0, decayed + self.ACCESS_BOOST)

            self.conn.execute(
                "UPDATE nodes SET weight=?, accessed=? WHERE id=?",
                (boosted, now, r["id"])
            )
            results.append(Node(
                id=r["id"], label=r["label"], kind=r["kind"],
                data=json.loads(r["data"]),
                created=r["created"], accessed=now, weight=boosted
            ))
        self.conn.commit()
        return results

    def decay_all(self):
        """对所有记忆应用遗忘衰减（模拟时间流逝）。"""
        now = time.time()
        rows = self.conn.execute("SELECT id, accessed, weight FROM nodes").fetchall()
        for r in rows:
            elapsed_days = (now - r["accessed"]) / 86400
            new_w = max(0.0, r["weight"] * math.exp(-self.DECAY_RATE * elapsed_days))
            self.conn.execute("UPDATE nodes SET weight=? WHERE id=?", (new_w, r["id"]))
        # 清除已遗忘的
        self.conn.execute("DELETE FROM nodes WHERE weight < ?", (self.MIN_WEIGHT,))
        self.conn.commit()

    def neighbors(self, node_id: str, depth: int = 1) -> list[Node]:
        """获取关联记忆（BFS 遍历）。"""
        visited = {node_id}
        frontier = [node_id]
        results = []
        for _ in range(depth):
            next_frontier = []
            for nid in frontier:
                rows = self.conn.execute(
                    "SELECT n.* FROM nodes n JOIN edges e ON n.id=e.target WHERE e.source=?",
                    (nid,)
                ).fetchall()
                for r in rows:
                    if r["id"] not in visited:
                        visited.add(r["id"])
                        results.append(Node(
                            r["id"], r["label"], r["kind"],
                            json.loads(r["data"]), r["created"], r["accessed"], r["weight"]
                        ))
                        next_frontier.append(r["id"])
            frontier = next_frontier
        return results

    def stats(self) -> dict:
        """记忆网络统计。"""
        n = self.conn.execute("SELECT COUNT(*) c FROM nodes").fetchone()["c"]
        e = self.conn.execute("SELECT COUNT(*) c FROM edges").fetchone()["c"]
        avg_w = self.conn.execute("SELECT AVG(weight) w FROM nodes").fetchone()["w"] or 0
        kinds = self.conn.execute(
            "SELECT kind, COUNT(*) c FROM nodes GROUP BY kind"
        ).fetchall()
        return {
            "nodes": n, "edges": e,
            "avg_weight": round(avg_w, 3),
            "by_kind": {r["kind"]: r["c"] for r in kinds}
        }

    def edge_type_stats(self) -> dict:
        """Aggregate statistics per edge relation type.

        Returns:
            {relation: {count, avg_weight, min_weight, max_weight,
                        unique_sources, unique_targets, reciprocity}}
        """
        rows = self.conn.execute("""
            SELECT relation,
                   COUNT(*) as cnt,
                   AVG(weight) as avg_w,
                   MIN(weight) as min_w,
                   MAX(weight) as max_w,
                   COUNT(DISTINCT source) as n_src,
                   COUNT(DISTINCT target) as n_tgt
            FROM edges GROUP BY relation ORDER BY cnt DESC
        """).fetchall()
        result = {}
        for r in rows:
            rel = r["relation"]
            # Reciprocity: fraction of edges that have a reverse
            total = r["cnt"]
            recip = 0
            if total > 0:
                recip_rows = self.conn.execute("""
                    SELECT COUNT(*) c FROM edges e1
                    WHERE e1.relation = ?
                    AND EXISTS (
                        SELECT 1 FROM edges e2
                        WHERE e2.source = e1.target AND e2.target = e1.source
                    )
                """, (rel,)).fetchone()["c"]
                recip = round(recip_rows / total, 4)
            result[rel] = {
                "count": total,
                "avg_weight": round(r["avg_w"], 4) if r["avg_w"] is not None else 0.0,
                "min_weight": round(r["min_w"], 4) if r["min_w"] is not None else 0.0,
                "max_weight": round(r["max_w"], 4) if r["max_w"] is not None else 0.0,
                "unique_sources": r["n_src"],
                "unique_targets": r["n_tgt"],
                "reciprocity": recip,
            }
        return result

    def merge_nodes(self, source_id: str, target_id: str) -> Optional[Node]:
        """Merge source into target. Target keeps its id, absorbs source's data and edges."""
        src = self.conn.execute("SELECT * FROM nodes WHERE id=?", (source_id,)).fetchone()
        tgt = self.conn.execute("SELECT * FROM nodes WHERE id=?", (target_id,)).fetchone()
        if not src or not tgt:
            return None
        # Merge data
        merged_data = {**json.loads(src["data"]), **json.loads(tgt["data"])}
        new_weight = max(src["weight"], tgt["weight"])
        # Rewire edges pointing to source -> point to target.
        # Step 1: Delete edges directly between source and target (they become self-loops).
        self.conn.execute(
            "DELETE FROM edges WHERE (source=? AND target=?) OR (source=? AND target=?)",
            (source_id, target_id, target_id, source_id),
        )
        # Step 2: Delete source edges that would duplicate target edges after rewiring.
        # An edge source->X with relation R is redundant if target->X with R already exists.
        self.conn.execute("""
            DELETE FROM edges WHERE source=? AND (target, relation) IN (
                SELECT target, relation FROM edges WHERE source=?
            )
        """, (source_id, target_id))
        # Step 3: Delete source reverse-edges that would duplicate target reverse-edges.
        # An edge X->source with relation R is redundant if X->target with R already exists.
        self.conn.execute("""
            DELETE FROM edges WHERE target=? AND (source, relation) IN (
                SELECT source, relation FROM edges WHERE target=?
            )
        """, (source_id, target_id))
        # Step 4: Rewire remaining source edges to target.
        self.conn.execute("UPDATE edges SET source=? WHERE source=?", (target_id, source_id))
        self.conn.execute("UPDATE edges SET target=? WHERE target=?", (target_id, source_id))
        # Step 5: Remove any self-loops that slipped through.
        self.conn.execute("DELETE FROM edges WHERE source=? AND target=?", (target_id, target_id))
        # Update target
        self.conn.execute(
            "UPDATE nodes SET data=?, weight=? WHERE id=?",
            (json.dumps(merged_data), new_weight, target_id)
        )
        # Delete source
        self._fts_delete_node(source_id)
        self.conn.execute("DELETE FROM nodes WHERE id=?", (source_id,))
        self._fts_sync_node(target_id)
        self.conn.commit()
        row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (target_id,)).fetchone()
        return Node(row["id"], row["label"], row["kind"],
                    json.loads(row["data"]), row["created"], row["accessed"], row["weight"])

    def export_json(self) -> dict:
        """Export entire graph as a JSON-serializable dict."""
        nodes = []
        for r in self.conn.execute("SELECT * FROM nodes").fetchall():
            nodes.append({
                "id": r["id"], "label": r["label"], "kind": r["kind"],
                "data": json.loads(r["data"]), "created": r["created"],
                "accessed": r["accessed"], "weight": r["weight"],
                "tags": json.loads(r["tags"])
            })
        edges = []
        for r in self.conn.execute("SELECT * FROM edges").fetchall():
            edges.append({
                "source": r["source"], "target": r["target"],
                "relation": r["relation"], "weight": r["weight"]
            })
        return {"version": 1, "nodes": nodes, "edges": edges}

    def import_json(self, data: dict, merge: bool = False):
        """Import graph from export_json() output.
        If merge=True, add to existing graph. Otherwise clear first."""
        if not merge:
            self.conn.execute("DELETE FROM edges")
            self.conn.execute("DELETE FROM nodes")
        for n in data.get("nodes", []):
            self.conn.execute(
                "INSERT OR REPLACE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                (n["id"], n["label"], n["kind"], json.dumps(n.get("data", {})),
                 n.get("created", time.time()), n.get("accessed", time.time()),
                 n.get("weight", 1.0), json.dumps(n.get("tags", [])))
            )
        for e in data.get("edges", []):
            self.conn.execute(
                "INSERT OR REPLACE INTO edges VALUES (?,?,?,?)",
                (e["source"], e["target"], e["relation"], e.get("weight", 1.0))
            )
        self.conn.commit()

    def find_by_kind(self, kind: str) -> list[Node]:
        """Return all nodes of a given kind."""
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE kind=? ORDER BY weight DESC", (kind,)
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                     json.loads(r["data"]), r["created"], r["accessed"], r["weight"])
                for r in rows]

    def search_by_label(self, pattern: str, limit: int = 50) -> list[Node]:
        """Find nodes whose label matches a regex pattern.

        Args:
            pattern: Python regex pattern (or simple substring if invalid regex).
            limit: max results.
        """
        import re
        try:
            compiled = re.compile(pattern, re.IGNORECASE)
            rows = self.conn.execute("SELECT * FROM nodes").fetchall()
            results = []
            for r in rows:
                if compiled.search(r["label"]):
                    results.append(Node(
                        r["id"], r["label"], r["kind"],
                        json.loads(r["data"]), r["created"], r["accessed"], r["weight"]
                    ))
                    if len(results) >= limit:
                        break
            return results
        except re.error:
            # Fallback to LIKE substring search
            rows = self.conn.execute(
                "SELECT * FROM nodes WHERE label LIKE ? LIMIT ?",
                (f"%{pattern}%", limit)
            ).fetchall()
            return [Node(r["id"], r["label"], r["kind"],
                         json.loads(r["data"]), r["created"], r["accessed"], r["weight"])
                    for r in rows]

    def search_labels(self, prefix: str, limit: int = 20) -> list[Node]:
        """Fast prefix search on node labels using SQLite LIKE.

        Args:
            prefix: label prefix to search for.
            limit: max results.
        """
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE label LIKE ? ORDER BY weight DESC LIMIT ?",
            (f"{prefix}%", limit)
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                     json.loads(r["data"]), r["created"], r["accessed"], r["weight"])
                for r in rows]

    def search_by_data(self, key: str, value=None) -> list[Node]:
        """Find nodes whose data dict contains key (and optionally matches value)."""
        results = []
        for r in self.conn.execute("SELECT * FROM nodes").fetchall():
            d = json.loads(r["data"])
            if key in d and (value is None or d[key] == value):
                results.append(Node(
                    r["id"], r["label"], r["kind"],
                    d, r["created"], r["accessed"], r["weight"]
                ))
        return results

    def edges_of(self, node_id: str, direction: str = "both") -> list[Edge]:
        """Get edges connected to a node. direction: 'outgoing', 'incoming', or 'both'."""
        edges = []
        if direction in ("outgoing", "both"):
            for r in self.conn.execute(
                "SELECT * FROM edges WHERE source=?", (node_id,)
            ).fetchall():
                edges.append(Edge(r["source"], r["target"], r["relation"], r["weight"]))
        if direction in ("incoming", "both"):
            for r in self.conn.execute(
                "SELECT * FROM edges WHERE target=?", (node_id,)
            ).fetchall():
                edges.append(Edge(r["source"], r["target"], r["relation"], r["weight"]))
        return edges

    def count_by_kind(self) -> dict[str, int]:
        """Return {kind: count} for all node kinds."""
        rows = self.conn.execute(
            "SELECT kind, COUNT(*) c FROM nodes GROUP BY kind"
        ).fetchall()
        return {r["kind"]: r["c"] for r in rows}

    def top_nodes(self, n: int = 5) -> list[Node]:
        """Return top-n nodes by weight."""
        rows = self.conn.execute(
            "SELECT * FROM nodes ORDER BY weight DESC LIMIT ?", (n,)
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                     json.loads(r["data"]), r["created"], r["accessed"], r["weight"])
                for r in rows]

    def touch(self, node_id: str) -> Optional[Node]:
        """Update a node's accessed timestamp and boost weight. Returns updated node or None."""
        row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return None
        new_weight = min(1.0, row["weight"] + self.ACCESS_BOOST)
        now = time.time()
        self.conn.execute(
            "UPDATE nodes SET accessed=?, weight=? WHERE id=?",
            (now, new_weight, node_id)
        )
        self.conn.commit()
        return self.get_node(node_id)

    def has_node(self, node_id: str) -> bool:
        """Check if a node exists without fetching it."""
        row = self.conn.execute("SELECT 1 FROM nodes WHERE id=?", (node_id,)).fetchone()
        return row is not None

    def rename_tag(self, old_tag: str, new_tag: str) -> int:
        """Rename a tag across all nodes. Returns count of nodes updated."""
        count = 0
        for r in self.conn.execute("SELECT id, tags FROM nodes").fetchall():
            tags = json.loads(r["tags"])
            if old_tag in tags:
                tags[tags.index(old_tag)] = new_tag
                self.conn.execute("UPDATE nodes SET tags=? WHERE id=?", (json.dumps(tags), r["id"]))
                self._fts_sync_node(r["id"])
                count += 1
        self.conn.commit()
        return count

    def clear_tags(self, node_id: str) -> bool:
        """Remove all tags from a node. Returns True if node existed."""
        if not self.has_node(node_id):
            return False
        self.conn.execute("UPDATE nodes SET tags='[]' WHERE id=?", (node_id,))
        self._fts_sync_node(node_id)
        self.conn.commit()
        return True

    def reweight(self, node_id: str, delta: float) -> Optional[Node]:
        """Adjust a node's weight by delta (can be negative). Clamps to [0, 1]. Returns updated node."""
        row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return None
        new_w = max(0.0, min(1.0, row["weight"] + delta))
        self.conn.execute("UPDATE nodes SET weight=? WHERE id=?", (new_w, node_id))
        self.conn.commit()
        return self.get_node(node_id)

    def is_linked(self, source_id: str, target_id: str, relation: str = None) -> bool:
        """Check if an edge exists. If relation is None, checks any edge between the two."""
        if relation is not None:
            row = self.conn.execute(
                "SELECT 1 FROM edges WHERE source=? AND target=? AND relation=?",
                (source_id, target_id, relation)
            ).fetchone()
        else:
            row = self.conn.execute(
                "SELECT 1 FROM edges WHERE source=? AND target=?",
                (source_id, target_id)
            ).fetchone()
        return row is not None

    def all_tags(self) -> list[str]:
        """Return sorted list of unique tags across all nodes."""
        tags_set = set()
        for r in self.conn.execute("SELECT tags FROM nodes").fetchall():
            tags_set.update(json.loads(r["tags"]))
        return sorted(tags_set)

    def subgraph(self, node_id: str, depth: int = 1) -> dict:
        """Extract a subgraph around node_id up to `depth` hops.

        Returns a dict with 'center', 'nodes', 'edges' suitable for JSON serialization
        or passing to import_json(). Useful for pulling relevant context into an agent's
        working memory.
        """
        visited_nodes = set()
        visited_edges = set()
        frontier = {node_id}

        for _ in range(depth + 1):
            next_frontier = set()
            for nid in frontier:
                if nid in visited_nodes:
                    continue
                visited_nodes.add(nid)
                # collect edges
                for r in self.conn.execute(
                    "SELECT source, target, relation, weight FROM edges WHERE source=? OR target=?",
                    (nid, nid)
                ).fetchall():
                    edge_key = (r["source"], r["target"], r["relation"])
                    if edge_key not in visited_edges:
                        visited_edges.add(edge_key)
                        next_frontier.add(r["source"])
                        next_frontier.add(r["target"])
            frontier = next_frontier - visited_nodes

        # Build node/edge lists (reuse export_json format)
        nodes = []
        placeholders = ",".join("?" for _ in visited_nodes)
        for r in self.conn.execute(
            f"SELECT * FROM nodes WHERE id IN ({placeholders})",
            list(visited_nodes)
        ).fetchall():
            nodes.append({
                "id": r["id"], "label": r["label"], "kind": r["kind"],
                "data": json.loads(r["data"]), "created": r["created"],
                "accessed": r["accessed"], "weight": r["weight"],
                "tags": json.loads(r["tags"])
            })
        edges = []
        for sk, tk, rel in visited_edges:
            row = self.conn.execute(
                "SELECT weight FROM edges WHERE source=? AND target=? AND relation=?",
                (sk, tk, rel)
            ).fetchone()
            edges.append({"source": sk, "target": tk, "relation": rel, "weight": row["weight"]})

        return {"center": node_id, "nodes": nodes, "edges": edges}

    def subgraph_by_edge_type(self, relation: str,
                               include_isolated: bool = False) -> dict:
        """Extract a view containing only edges of a specific relation type.

        Inspired by MAGMA (ACL 2026): orthogonal multi-graph views where
        different edge types represent different semantic dimensions
        (causal, temporal, hierarchical, etc.). This method lets callers
        operate on one dimension at a time.

        The returned dict has the same format as ``subgraph()`` and can
        be passed to ``import_json()`` for a standalone graph:
        - ``nodes``: nodes that participate in at least one edge of the
          given relation (unless *include_isolated* is True).
        - ``edges``: all edges matching *relation*.
        - ``relation``: the relation type.
        - ``stats``: ``{node_count, edge_count, density}``

        Args:
            relation: Edge relation to filter on (e.g. ``'causes'``).
            include_isolated: If True, include all nodes from the host
                graph even if they have no edges of this type.

        Returns:
            Dict with nodes, edges, and stats. Empty nodes/edges if no
            matching edges exist.
        """
        edges = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges WHERE relation=?",
            (relation,)
        ).fetchall()

        if include_isolated:
            node_rows = self.conn.execute("SELECT * FROM nodes").fetchall()
            node_ids = {r["id"] for r in node_rows}
        else:
            node_ids = set()
            for r in edges:
                node_ids.add(r["source"])
                node_ids.add(r["target"])
            if not node_ids:
                return {
                    "nodes": [], "edges": [], "relation": relation,
                    "stats": {"node_count": 0, "edge_count": 0, "density": 0.0}
                }
            node_rows = self.conn.execute(
                f"SELECT * FROM nodes WHERE id IN ({','.join('?' for _ in node_ids)})",
                list(node_ids)
            ).fetchall()

        nodes = []
        for r in node_rows:
            nodes.append({
                "id": r["id"], "label": r["label"], "kind": r["kind"],
                "data": json.loads(r["data"]), "created": r["created"],
                "accessed": r["accessed"], "weight": r["weight"],
                "tags": json.loads(r["tags"])
            })

        edge_list = [
            {"source": r["source"], "target": r["target"],
             "relation": r["relation"], "weight": r["weight"]}
            for r in edges
        ]

        n = len(nodes)
        m = len(edge_list)
        max_edges = n * (n - 1) if n > 1 else 1
        density = m / max_edges if max_edges > 0 else 0.0

        return {
            "nodes": nodes,
            "edges": edge_list,
            "relation": relation,
            "stats": {
                "node_count": n,
                "edge_count": m,
                "density": round(density, 4),
            }
        }

    def prune(self, min_weight: float = 0.1) -> dict:
        """Remove nodes below min_weight and their orphaned edges.

        Returns dict with 'nodes_removed', 'edges_removed' counts.
        Useful for periodic memory cleanup — keeps the graph lean.
        """
        # Find low-weight nodes
        rows = self.conn.execute(
            "SELECT id FROM nodes WHERE weight < ?", (min_weight,)
        ).fetchall()
        node_ids = [r["id"] for r in rows]
        if not node_ids:
            return {"nodes_removed": 0, "edges_removed": 0}

        # Count edges that will be removed
        placeholders = ",".join("?" for _ in node_ids)
        edge_count = self.conn.execute(
            f"SELECT COUNT(*) c FROM edges WHERE source IN ({placeholders}) OR target IN ({placeholders})",
            node_ids + node_ids
        ).fetchone()["c"]

        # Delete edges then nodes
        self.conn.execute(
            f"DELETE FROM edges WHERE source IN ({placeholders}) OR target IN ({placeholders})",
            node_ids + node_ids
        )
        self.conn.execute(
            f"DELETE FROM nodes WHERE id IN ({placeholders})",
            node_ids
        )
        self.conn.commit()
        return {"nodes_removed": len(node_ids), "edges_removed": edge_count}

    def prune_by_relevance(self, query: str, keep_k: int = 50, min_weight: float = 0.0) -> dict:
        """保留与 query 最相关的 keep_k 个节点，其余剪枝。

        使用 BM25 搜索找到最相关的节点，然后删除不在 top-k 中的节点。
        这是 "智能遗忘" — 忘掉无关的，记住相关的。

        Args:
            query: 相关性查询（如 "Python web development"）
            keep_k: 保留的节点数量
            min_weight: 额外保留 weight >= min_weight 的节点（0=不保留）

        Returns:
            {nodes_removed, edges_removed, kept_by_relevance, kept_by_weight}
        """
        # BM25 搜索找到相关节点
        try:
            results = self.search_bm25(query, limit=keep_k)
            relevant_ids = {r["node_id"] for r in results}
        except Exception:
            relevant_ids = set()

        # 额外保留高 weight 节点
        weight_ids = set()
        if min_weight > 0:
            rows = self.conn.execute(
                "SELECT id FROM nodes WHERE weight >= ?", (min_weight,)
            ).fetchall()
            weight_ids = {r["id"] for r in rows}

        keep_ids = relevant_ids | weight_ids
        all_ids = {r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()}
        remove_ids = all_ids - keep_ids

        if not remove_ids:
            return {"nodes_removed": 0, "edges_removed": 0,
                    "kept_by_relevance": len(relevant_ids),
                    "kept_by_weight": len(weight_ids - relevant_ids)}

        placeholders = ",".join("?" for _ in remove_ids)
        edge_count = self.conn.execute(
            f"SELECT COUNT(*) c FROM edges WHERE source IN ({placeholders}) OR target IN ({placeholders})",
            list(remove_ids) + list(remove_ids)
        ).fetchone()["c"]

        self.conn.execute(
            f"DELETE FROM edges WHERE source IN ({placeholders}) OR target IN ({placeholders})",
            list(remove_ids) + list(remove_ids)
        )
        self.conn.execute(
            f"DELETE FROM nodes WHERE id IN ({placeholders})",
            list(remove_ids)
        )
        # 同步 FTS
        for nid in remove_ids:
            self._fts_delete_node(nid)
        # 同步向量
        for nid in remove_ids:
            self.remove_embedding(nid)
        self.conn.commit()

        return {"nodes_removed": len(remove_ids), "edges_removed": edge_count,
                "kept_by_relevance": len(relevant_ids),
                "kept_by_weight": len(weight_ids - relevant_ids)}

    def aggregate(self, kind: str, field: str = "weight", fn: str = "sum") -> float:
        """Aggregate a numeric field across all nodes of a given kind.

        fn can be 'sum', 'avg', 'min', 'max', 'count'.
        Useful for answering questions like 'average weight of all events',
        'total weight of skills', etc.
        """
        valid_fns = {"sum", "avg", "min", "max", "count"}
        if fn not in valid_fns:
            raise ValueError(f"fn must be one of {valid_fns}, got '{fn}'")

        if fn == "count":
            row = self.conn.execute(
                "SELECT COUNT(*) c FROM nodes WHERE kind=?", (kind,)
            ).fetchone()
            return float(row["c"])

        sql_fn = {"sum": "SUM", "avg": "AVG", "min": "MIN", "max": "MAX"}[fn]
        # Map field to column
        col_map = {"weight": "weight", "created": "created", "accessed": "accessed"}
        col = col_map.get(field, field)
        row = self.conn.execute(
            f"SELECT {sql_fn}({col}) v FROM nodes WHERE kind=?", (kind,)
        ).fetchone()
        val = row["v"]
        return float(val) if val is not None else 0.0

    def unlink_many(self, pairs: list[dict]) -> int:
        """Batch unlink edges. Each dict: {source, target, relation?}.
        If relation is omitted, removes all edges between source and target.
        Returns count of removed edges.
        """
        removed = 0
        for p in pairs:
            rel = p.get("relation")
            if rel is not None:
                cur = self.conn.execute(
                    "DELETE FROM edges WHERE source=? AND target=? AND relation=?",
                    (p["source"], p["target"], rel)
                )
            else:
                cur = self.conn.execute(
                    "DELETE FROM edges WHERE source=? AND target=?",
                    (p["source"], p["target"])
                )
            removed += cur.rowcount
        self.conn.commit()
        return removed

    def graph_diff(self, other: 'MemoryGraph') -> dict:
        """Compare this graph with another. Returns dict with:
        - nodes_only_self: node ids in self but not other
        - nodes_only_other: node ids in other but not self
        - nodes_modified: list of {id, field, self_val, other_val} for changed nodes
        - edges_only_self: edge tuples in self but not other
        - edges_only_other: edge tuples in other but not self
        Useful for graph sync — detect what changed between two versions.
        """
        self_nodes = {r["id"]: r for r in self.conn.execute("SELECT * FROM nodes").fetchall()}
        other_nodes = {r["id"]: r for r in other.conn.execute("SELECT * FROM nodes").fetchall()}

        self_ids = set(self_nodes.keys())
        other_ids = set(other_nodes.keys())

        diff = {
            "nodes_only_self": sorted(self_ids - other_ids),
            "nodes_only_other": sorted(other_ids - self_ids),
            "nodes_modified": [],
            "edges_only_self": [],
            "edges_only_other": [],
        }

        # Check modified nodes (same id, different content)
        for nid in self_ids & other_ids:
            s, o = self_nodes[nid], other_nodes[nid]
            for field in ("label", "kind", "weight"):
                if s[field] != o[field]:
                    diff["nodes_modified"].append({
                        "id": nid, "field": field,
                        "self_val": s[field], "other_val": o[field]
                    })
            # data diff
            sd, od = json.loads(s["data"]), json.loads(o["data"])
            if sd != od:
                diff["nodes_modified"].append({
                    "id": nid, "field": "data",
                    "self_val": sd, "other_val": od
                })

        # Edge diff
        self_edges = set()
        for r in self.conn.execute("SELECT source, target, relation FROM edges").fetchall():
            self_edges.add((r["source"], r["target"], r["relation"]))
        other_edges = set()
        for r in other.conn.execute("SELECT source, target, relation FROM edges").fetchall():
            other_edges.add((r["source"], r["target"], r["relation"]))

        diff["edges_only_self"] = sorted(self_edges - other_edges)
        diff["edges_only_other"] = sorted(other_edges - self_edges)
        return diff

    def compact(self, strategy: str = "merge_similar", similarity_threshold: float = 0.8) -> dict:
        """Compact the graph by merging similar/low-value nodes.

        strategy='merge_similar': merge nodes with identical labels and kind.
        Returns dict with 'merged_pairs' (list of [survivor_id, absorbed_id]) and 'total_merged'.
        """
        if strategy != "merge_similar":
            raise ValueError(f"Unknown strategy: {strategy}")

        # Group by (label, kind)
        groups = defaultdict(list)
        for r in self.conn.execute("SELECT id, label, kind FROM nodes").fetchall():
            groups[(r["label"], r["kind"])].append(r["id"])

        merged_pairs = []
        for (label, kind), ids in groups.items():
            if len(ids) < 2:
                continue
            # Keep the first (survivor), merge rest into it
            survivor = ids[0]
            for absorb_id in ids[1:]:
                self.merge_nodes(absorb_id, survivor)
                merged_pairs.append([survivor, absorb_id])

        return {"merged_pairs": merged_pairs, "total_merged": len(merged_pairs)}

    def search_unified(self, query: str, limit: int = 10) -> list[dict]:
        """Unified search across label, data values, and tags.

        Returns list of dicts: {node, score, matched_fields}.
        Score = field_matches * weight_boost. label match scores highest.
        """
        query_lower = query.lower()
        results = []

        for r in self.conn.execute("SELECT * FROM nodes").fetchall():
            score = 0.0
            matched = []

            # Label match (highest weight)
            if query_lower in r["label"].lower():
                score += 3.0
                matched.append("label")

            # Data value match
            data = json.loads(r["data"])
            for v in data.values():
                if query_lower in str(v).lower():
                    score += 2.0
                    matched.append("data")
                    break

            # Tag match
            tags = json.loads(r["tags"])
            for t in tags:
                if query_lower in t.lower():
                    score += 1.5
                    matched.append("tags")
                    break

            # Kind match (bonus)
            if query_lower == r["kind"].lower():
                score += 1.0
                matched.append("kind")

            if score > 0:
                node = Node(r["id"], r["label"], r["kind"],
                           data, r["created"], r["accessed"], r["weight"])
                results.append({
                    "node": node,
                    "score": score * r["weight"],
                    "matched_fields": matched
                })

        results.sort(key=lambda x: x["score"], reverse=True)
        return results[:limit]

    def rename_node(self, node_id: str, new_label: str) -> Optional[Node]:
        """Rename a node's label. Returns updated node or None."""
        if not self.has_node(node_id):
            return None
        self.conn.execute("UPDATE nodes SET label=? WHERE id=?", (new_label, node_id))
        self._fts_sync_node(node_id)
        self.conn.commit()
        return self.get_node(node_id)

    def clone_node(self, node_id: str, new_label: str = None) -> Optional[Node]:
        """Clone a node (with same data/kind/tags) but not its edges.
        Returns the new node or None if source doesn't exist."""
        row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return None
        new_id = uuid.uuid4().hex[:12]
        self.conn.execute(
            "INSERT INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
            (new_id, new_label or row["label"], row["kind"], row["data"],
             time.time(), time.time(), row["weight"], row["tags"])
        )
        self._fts_sync_node(new_id)
        self.conn.commit()
        return self.get_node(new_id)

    def path_exists(self, start_id: str, end_id: str, max_depth: int = 10) -> bool:
        """Check if a path exists between two nodes (BFS with depth limit)."""
        if start_id == end_id:
            return self.has_node(start_id)
        visited = {start_id}
        frontier = [start_id]
        for _ in range(max_depth):
            next_frontier = []
            for nid in frontier:
                for r in self.conn.execute(
                    "SELECT target FROM edges WHERE source=?", (nid,)
                ).fetchall():
                    if r["target"] == end_id:
                        return True
                    if r["target"] not in visited:
                        visited.add(r["target"])
                        next_frontier.append(r["target"])
            frontier = next_frontier
        return False

    def find_roots(self) -> list:
        """Find nodes with no incoming edges (root/source nodes)."""
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE id NOT IN (SELECT target FROM edges)"
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                     json.loads(r["data"]) if r["data"] else {},
                     r["created"], r["accessed"], r["weight"]) for r in rows]

    def find_leaves(self) -> list:
        """Find nodes with no outgoing edges (leaf/sink nodes)."""
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE id NOT IN (SELECT source FROM edges)"
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                     json.loads(r["data"]) if r["data"] else {},
                     r["created"], r["accessed"], r["weight"]) for r in rows]

    def degree(self, node_id: str, direction: str = "both") -> int:
        """Get degree of a node. direction: 'in', 'out', or 'both'."""
        if not self.has_node(node_id):
            return 0
        if direction == "in":
            return self.conn.execute(
                "SELECT COUNT(*) as c FROM edges WHERE target=?", (node_id,)
            ).fetchone()["c"]
        elif direction == "out":
            return self.conn.execute(
                "SELECT COUNT(*) as c FROM edges WHERE source=?", (node_id,)
            ).fetchone()["c"]
        else:
            return self.conn.execute(
                "SELECT COUNT(*) as c FROM edges WHERE source=? OR target=?",
                (node_id, node_id)
            ).fetchone()["c"]

    def degree_centrality(self, node_id: str) -> float:
        """Normalized degree centrality (0.0-1.0). Returns 0.0 for isolated/missing nodes."""
        total_nodes = self.conn.execute("SELECT COUNT(*) as c FROM nodes").fetchone()["c"]
        if total_nodes <= 1:
            return 0.0
        deg = self.degree(node_id, "both")
        return deg / (total_nodes - 1)

    def shortest_path(self, start_id: str, end_id: str) -> Optional[list]:
        """BFS shortest path returning list of node IDs, or None if no path."""
        if start_id == end_id:
            return [start_id] if self.has_node(start_id) else None
        visited = {start_id: None}
        frontier = [start_id]
        while frontier:
            next_frontier = []
            for nid in frontier:
                for r in self.conn.execute(
                    "SELECT target FROM edges WHERE source=?", (nid,)
                ).fetchall():
                    tid = r["target"]
                    if tid == end_id:
                        path = [end_id]
                        cur = nid
                        while cur is not None:
                            path.append(cur)
                            cur = visited[cur]
                        return list(reversed(path))
                    if tid not in visited:
                        visited[tid] = nid
                        next_frontier.append(tid)
            frontier = next_frontier
        return None

    def shortest_path_undirected(self, start_id: str, end_id: str) -> Optional[list[str]]:
        """BFS shortest path between two nodes in undirected graph. Returns list of node ids or None."""
        if start_id == end_id:
            return [start_id]
        visited = {start_id}
        queue = [(start_id, [start_id])]
        while queue:
            current, path = queue.pop(0)
            # Get neighbors in both directions (undirected)
            neighbors = []
            for row in self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
                (current, current)
            ).fetchall():
                neighbors.append(row[0])
            for nid in neighbors:
                if nid in visited:
                    continue
                visited.add(nid)
                new_path = path + [nid]
                if nid == end_id:
                    return new_path
                queue.append((nid, new_path))
        return None

    def betweenness_centrality(self, node_id: str, samples: int = 50) -> float:
        """Approximate betweenness centrality via random sampling of shortest paths (undirected)."""
        if not self.has_node(node_id):
            return 0.0
        all_ids = [r[0] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        if len(all_ids) < 3:
            return 0.0
        import random
        count = 0
        actual_samples = 0
        for _ in range(min(samples, len(all_ids) * (len(all_ids) - 1) // 2)):
            s, t = random.sample(all_ids, 2)
            path = self.shortest_path_undirected(s, t)
            actual_samples += 1
            if path and node_id in path[1:-1]:  # exclude endpoints
                count += 1
        return count / max(actual_samples, 1)

    def community_detect(self, max_iter: int = 10) -> dict:
        """Label-propagation community detection. Returns {community_label: [node_ids]}."""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not nodes:
            return {}
        import random
        labels = {r["id"]: i for i, r in enumerate(nodes)}
        ids = list(labels.keys())
        for _ in range(max_iter):
            random.shuffle(ids)
            changed = False
            for nid in ids:
                neighbor_labels = {}
                for r in self.conn.execute(
                    "SELECT source FROM edges WHERE target=? UNION SELECT target FROM edges WHERE source=?",
                    (nid, nid)
                ).fetchall():
                    lbl = labels.get(r[0])
                    if lbl is not None:
                        neighbor_labels[lbl] = neighbor_labels.get(lbl, 0) + 1
                if neighbor_labels:
                    best = max(neighbor_labels, key=neighbor_labels.get)
                    if labels[nid] != best:
                        labels[nid] = best
                        changed = True
            if not changed:
                break
        communities = {}
        for nid, lbl in labels.items():
            communities.setdefault(lbl, []).append(nid)
        return communities

    def eigenvector_centrality(self, iterations: int = 20, damping: float = 0.85) -> dict:
        """Iterative eigenvector centrality. Returns {node_id: score}."""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not nodes:
            return {}
        n = len(nodes)
        scores = {r["id"]: 1.0 / n for r in nodes}
        for _ in range(iterations):
            new_scores = {}
            for r in nodes:
                nid = r["id"]
                s = 0.0
                for src in self.conn.execute(
                    "SELECT source FROM edges WHERE target=?", (nid,)
                ).fetchall():
                    out_deg = self.degree(src[0], "out")
                    if out_deg > 0:
                        s += scores.get(src[0], 0) / out_deg
                new_scores[nid] = (1 - damping) / n + damping * s
            # Normalize
            max_s = max(new_scores.values()) or 1.0
            scores = {k: v / max_s for k, v in new_scores.items()}
        return scores

    def pagerank(self, iterations: int = 20, damping: float = 0.85) -> dict:
        """PageRank algorithm. Returns {node_id: score}."""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not nodes:
            return {}
        n = len(nodes)
        scores = {r["id"]: 1.0 / n for r in nodes}
        for _ in range(iterations):
            new_scores = {}
            for r in nodes:
                nid = r["id"]
                s = 0.0
                for src in self.conn.execute(
                    "SELECT source FROM edges WHERE target=?", (nid,)
                ).fetchall():
                    out_deg = self.degree(src[0], "out")
                    if out_deg > 0:
                        s += scores.get(src[0], 0) / out_deg
                new_scores[nid] = (1 - damping) / n + damping * s
            total = sum(new_scores.values()) or 1.0
            scores = {k: v / total for k, v in new_scores.items()}
        return scores

    def k_core(self, k: int) -> list:
        """Find k-core: nodes with degree >= k after iterative pruning."""
        nodes = {r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()}
        changed = True
        while changed:
            changed = False
            to_remove = set()
            for nid in nodes:
                deg = 0
                for r in self.conn.execute(
                    "SELECT source FROM edges WHERE target=? UNION ALL SELECT target FROM edges WHERE source=?",
                    (nid, nid)
                ).fetchall():
                    if r[0] in nodes:
                        deg += 1
                if deg < k:
                    to_remove.add(nid)
            if to_remove:
                nodes -= to_remove
                changed = True
        return list(nodes)

    def triangles(self, node_id: str) -> int:
        """Count triangles involving this node."""
        if not self.has_node(node_id):
            return 0
        neighbors = set()
        for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION ALL SELECT source FROM edges WHERE target=?",
            (node_id, node_id)
        ).fetchall():
            neighbors.add(r[0])
        count = 0
        for n1 in neighbors:
            n1_neighbors = set()
            for r in self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION ALL SELECT source FROM edges WHERE target=?",
                (n1, n1)
            ).fetchall():
                n1_neighbors.add(r[0])
            if n1_neighbors & neighbors:
                count += len(n1_neighbors & neighbors)
        # Each triangle counted twice (once per neighbor pair)
        return count // 2

    def timeline(self, kind: str = None, since: float = None, until: float = None, limit: int = 50) -> list[Node]:
        """Return nodes sorted by creation time (newest first). Optional filters: kind, time range."""
        sql = "SELECT * FROM nodes WHERE 1=1"
        params = []
        if kind:
            sql += " AND kind=?"
            params.append(kind)
        if since is not None:
            sql += " AND created>=?"
            params.append(since)
        if until is not None:
            sql += " AND created<=?"
            params.append(until)
        sql += " ORDER BY created DESC LIMIT ?"
        params.append(limit)
        rows = self.conn.execute(sql, params).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                    json.loads(r["data"]), r["created"], r["accessed"], r["weight"]) for r in rows]

    def recommend(self, node_id: str, limit: int = 5) -> list[dict]:
        """Recommend related nodes via Jaccard similarity of shared neighbors."""
        # Get neighbors of target node
        my_neighbors = set()
        for row in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id, node_id)
        ):
            my_neighbors.add(row[0])
        my_neighbors.discard(node_id)
        if not my_neighbors:
            return []
        # Score all other nodes by Jaccard similarity of their neighbor sets
        candidates = []
        all_ids = [r[0] for r in self.conn.execute("SELECT id FROM nodes WHERE id != ?", (node_id,))]
        for nid in all_ids:
            their_neighbors = set()
            for row in self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
                (nid, nid)
            ):
                their_neighbors.add(row[0])
            their_neighbors.discard(nid)
            if not their_neighbors:
                continue
            intersection = my_neighbors & their_neighbors
            union = my_neighbors | their_neighbors
            if intersection:
                jaccard = len(intersection) / len(union)
                candidates.append({"node_id": nid, "score": round(jaccard, 4)})
        candidates.sort(key=lambda x: x["score"], reverse=True)
        # Enrich with node info
        results = []
        for c in candidates[:limit]:
            node = self.get_node(c["node_id"])
            if node:
                results.append({"node": node, "score": c["score"]})
        return results

    def importance_rank(self, limit: int = 20, decay_hours: float = 168.0) -> list[dict]:
        """Rank nodes by composite importance: weight + degree + recency.

        Score = normalized_weight * 0.4 + normalized_degree * 0.3 + recency_score * 0.3
        recency_score = 1.0 if accessed within decay_hours, decays linearly to 0.
        """
        now = time.time()
        cutoff = now - decay_hours * 3600

        rows = self.conn.execute("""
            SELECT n.id, n.label, n.kind, n.weight, n.accessed,
                   (SELECT COUNT(*) FROM edges WHERE source=n.id OR target=n.id) AS deg
            FROM nodes n
            ORDER BY n.weight DESC
        """).fetchall()

        if not rows:
            return []

        max_weight = max(r["weight"] for r in rows) or 1.0
        max_deg = max(r["deg"] for r in rows) or 1

        results = []
        for r in rows:
            w_norm = r["weight"] / max_weight
            d_norm = r["deg"] / max_deg
            # Recency: 1.0 if accessed after cutoff, linear decay before
            if r["accessed"] >= cutoff:
                recency = 1.0
            else:
                elapsed = cutoff - r["accessed"]
                recency = max(0.0, 1.0 - elapsed / (decay_hours * 3600))

            score = w_norm * 0.4 + d_norm * 0.3 + recency * 0.3
            results.append({
                "node_id": r["id"],
                "label": r["label"],
                "kind": r["kind"],
                "importance": round(score, 4),
                "components": {
                    "weight": round(w_norm, 3),
                    "degree": round(d_norm, 3),
                    "recency": round(recency, 3),
                },
            })

        results.sort(key=lambda x: x["importance"], reverse=True)
        return results[:limit]

    def patch(self, diff: dict, source: 'MemoryGraph' = None) -> dict:
        """Apply a graph_diff result to sync this graph.

        Args:
            diff: output of graph_diff()
            source: the other graph (needed to fetch new nodes/edges)
        Returns dict with applied counts.
        """
        applied = {"nodes_added": 0, "nodes_removed": 0, "edges_added": 0, "edges_removed": 0, "fields_updated": 0}

        # Add nodes that only exist in other
        if source:
            for nid in diff.get("nodes_only_other", []):
                row = source.conn.execute("SELECT * FROM nodes WHERE id=?", (nid,)).fetchone()
                if row:
                    self.conn.execute(
                        "INSERT OR IGNORE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                        (row["id"], row["label"], row["kind"], row["data"], row["created"], row["accessed"], row["weight"], row["tags"])
                    )
                    applied["nodes_added"] += 1

            # Add edges that only exist in other
            for (src, tgt, rel) in diff.get("edges_only_other", []):
                self.conn.execute(
                    "INSERT OR IGNORE INTO edges (source,target,relation,weight) VALUES (?,?,?,1.0)",
                    (src, tgt, rel)
                )
                applied["edges_added"] += 1

        # Remove nodes that only exist in self
        for nid in diff.get("nodes_only_self", []):
            self.conn.execute("DELETE FROM edges WHERE source=? OR target=?", (nid, nid))
            self.conn.execute("DELETE FROM nodes WHERE id=?", (nid,))
            applied["nodes_removed"] += 1

        # Remove edges that only exist in self
        for (src, tgt, rel) in diff.get("edges_only_self", []):
            self.conn.execute("DELETE FROM edges WHERE source=? AND target=? AND relation=?", (src, tgt, rel))
            applied["edges_removed"] += 1

        # Apply field updates from modified nodes
        if source:
            for mod in diff.get("nodes_modified", []):
                nid = mod["id"]
                field = mod["field"]
                val = mod["other_val"]
                if field == "data":
                    self.conn.execute("UPDATE nodes SET data=? WHERE id=?", (json.dumps(val), nid))
                else:
                    self.conn.execute(f"UPDATE nodes SET {field}=? WHERE id=?", (val, nid))
                applied["fields_updated"] += 1

        self.conn.commit()
        return applied

    def stats_summary(self) -> dict:
        """One-call graph statistics dashboard."""
        node_count = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        kind_dist = dict(self.conn.execute(
            "SELECT kind, COUNT(*) FROM nodes GROUP BY kind"
        ).fetchall())
        rel_dist = dict(self.conn.execute(
            "SELECT relation, COUNT(*) FROM edges GROUP BY relation"
        ).fetchall())
        avg_weight = self.conn.execute("SELECT AVG(weight) FROM nodes").fetchone()[0] or 0.0
        isolated = self.conn.execute("""
            SELECT COUNT(*) FROM nodes n
            WHERE NOT EXISTS (SELECT 1 FROM edges e WHERE e.source=n.id OR e.target=n.id)
        """).fetchone()[0]
        density = (2 * edge_count / (node_count * (node_count - 1))) if node_count > 1 else 0.0
        return {
            "node_count": node_count,
            "edge_count": edge_count,
            "kind_distribution": kind_dist,
            "relation_distribution": rel_dist,
            "avg_weight": round(avg_weight, 3),
            "isolated_nodes": isolated,
            "density": round(density, 4),
        }

    def anonymize(self) -> 'MemoryGraph':
        """Create a privacy-safe copy: strip labels and data, keep structure/kind/weights."""
        anon = MemoryGraph()
        id_map = {}
        for r in self.conn.execute("SELECT * FROM nodes").fetchall():
            new_id = str(uuid.uuid4())[:8]
            id_map[r["id"]] = new_id
            anon.conn.execute(
                "INSERT INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                (new_id, "***", r["kind"], "{}", r["created"], r["accessed"], r["weight"], "[]")
            )
        for r in self.conn.execute("SELECT * FROM edges").fetchall():
            anon.conn.execute(
                "INSERT INTO edges (source,target,relation,weight) VALUES (?,?,?,?)",
                (id_map.get(r["source"], r["source"]), id_map.get(r["target"], r["target"]), r["relation"], r["weight"])
            )
        anon.conn.commit()
        return anon

    def merge_graph(self, other: 'MemoryGraph', strategy: str = "union") -> dict:
        """Merge another graph into this one.

        Args:
            other: Source MemoryGraph to merge from.
            strategy: 'union' (add missing, skip existing) or 'update' (overwrite data/weight).

        Returns dict with counts: {nodes_added, nodes_updated, edges_added, edges_skipped}.
        """
        result = {"nodes_added": 0, "nodes_updated": 0, "edges_added": 0, "edges_skipped": 0}
        other_data = other.export_json()
        id_map = {}  # other_id → self_id (for edge remapping)

        for node in other_data["nodes"]:
            if not self.has_node(node["id"]):
                self.add(node["label"], node["kind"], node.get("data", {}), node.get("tags", []))
                # Reassign ID to match source
                self.conn.execute(
                    "UPDATE nodes SET id=?, weight=?, accessed=?, created=? WHERE rowid=last_insert_rowid()",
                    (node["id"], node.get("weight", 1.0), node.get("accessed", time.time()), node.get("created", time.time()))
                )
                self.conn.commit()
                id_map[node["id"]] = node["id"]
                result["nodes_added"] += 1
            elif strategy == "update":
                self.update_node(node["id"], label=node.get("label"), kind=node.get("kind"), data=node.get("data", {}))
                self.reweight(node["id"], node.get("weight", 1.0) - (self.get_node(node["id"]).weight or 0))
                id_map[node["id"]] = node["id"]
                result["nodes_updated"] += 1
            else:
                id_map[node["id"]] = node["id"]
                result["edges_skipped"] += 0  # node exists, not an edge skip

        for edge in other_data["edges"]:
            if edge["source"] in id_map and edge["target"] in id_map:
                if not self.is_linked(edge["source"], edge["target"], edge.get("relation")):
                    self.link(edge["source"], edge["target"], edge["relation"], edge.get("weight", 1.0))
                    result["edges_added"] += 1
        return result

    def diff_summary(self, other: 'MemoryGraph') -> dict:
        """High-level summary of differences between this graph and another.

        Returns dict with counts and sample labels for: only_in_self, only_in_other, common, label_diffs.
        """
        self_ids = {r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()}
        other_ids = {r["id"] for r in other.conn.execute("SELECT id FROM nodes").fetchall()}

        only_self = self_ids - other_ids
        only_other = other_ids - self_ids
        common = self_ids & other_ids

        # Check label differences in common nodes
        label_diffs = []
        for nid in common:
            s = self.get_node(nid)
            o = other.get_node(nid)
            if s and o and s.label != o.label:
                label_diffs.append({"id": nid, "self_label": s.label, "other_label": o.label})

        def _sample(ids, graph, limit=5):
            return [graph.get_node(nid).label for nid in list(ids)[:limit] if graph.get_node(nid)]

        return {
            "total_self": len(self_ids),
            "total_other": len(other_ids),
            "only_in_self": len(only_self),
            "only_in_other": len(only_other),
            "common": len(common),
            "sample_only_self": _sample(only_self, self),
            "sample_only_other": _sample(only_other, other),
            "label_diffs": label_diffs
        }

    def group_by(self, kind: str = None, tag: str = None) -> dict[str, list[Node]]:
        """Group nodes by kind or tag. Returns {group_key: [Node, ...]}.

        If kind is given, groups all nodes by their kind field.
        If tag is given, groups all nodes by each tag they have.
        """
        groups = defaultdict(list)
        if kind is not None:
            rows = self.conn.execute("SELECT id FROM nodes WHERE kind=?", (kind,)).fetchall()
            for r in rows:
                node = self.get_node(r["id"])
                if node:
                    groups[node.kind].append(node)
        elif tag is not None:
            rows = self.conn.execute("SELECT id, tags FROM nodes WHERE tags IS NOT NULL").fetchall()
            for r in rows:
                node_tags = json.loads(r["tags"]) if r["tags"] else []
                if tag in node_tags:
                    node = self.get_node(r["id"])
                    if node:
                        groups[tag].append(node)
        else:
            # Group all by kind
            rows = self.conn.execute("SELECT id, kind FROM nodes").fetchall()
            for r in rows:
                node = self.get_node(r["id"])
                if node:
                    groups[r["kind"]].append(node)
        return dict(groups)

    def link_strength(self, node_id: str) -> list[dict]:
        """Return all edges connected to node_id sorted by weight descending.

        Returns list of {source, target, relation, weight, partner_id, partner_label}.
        """
        if not self.has_node(node_id):
            return []
        results = []
        for e in self.edges_of(node_id, "both"):
            partner_id = e.target if e.source == node_id else e.source
            partner = self.get_node(partner_id)
            results.append({
                "source": e.source, "target": e.target,
                "relation": e.relation, "weight": e.weight,
                "partner_id": partner_id,
                "partner_label": partner.label if partner else "?"
            })
        results.sort(key=lambda x: x["weight"], reverse=True)
        return results

    def bfs_order(self, start_id: str, max_depth: int = 10) -> list[str]:
        """Return node ids in BFS traversal order from start_id."""
        if not self.has_node(start_id):
            return []
        visited = set()
        queue = [(start_id, 0)]
        order = []
        while queue:
            nid, depth = queue.pop(0)
            if nid in visited or depth > max_depth:
                continue
            visited.add(nid)
            order.append(nid)
            neighbors = []
            for r in self.conn.execute("SELECT target FROM edges WHERE source=?", (nid,)).fetchall():
                neighbors.append(r["target"])
            for r in self.conn.execute("SELECT source FROM edges WHERE target=?", (nid,)).fetchall():
                neighbors.append(r["source"])
            for nb in neighbors:
                if nb not in visited:
                    queue.append((nb, depth + 1))
        return order

    def dfs_order(self, start_id: str, max_depth: int = 10) -> list[str]:
        """Return node ids in DFS traversal order from start_id."""
        if not self.has_node(start_id):
            return []
        visited = set()
        order = []
        def _dfs(nid, depth):
            if nid in visited or depth > max_depth:
                return
            visited.add(nid)
            order.append(nid)
            for r in self.conn.execute("SELECT target FROM edges WHERE source=?", (nid,)).fetchall():
                _dfs(r["target"], depth + 1)
            for r in self.conn.execute("SELECT source FROM edges WHERE target=?", (nid,)).fetchall():
                _dfs(r["source"], depth + 1)
        _dfs(start_id, 0)
        return order

    def ancestor_graph(self, node_id: str, max_depth: int = 10) -> list[str]:
        """Return all ancestor node ids (following incoming edges) up to max_depth."""
        if not self.has_node(node_id):
            return []
        visited = set()
        queue = [(node_id, 0)]
        result = []
        while queue:
            nid, depth = queue.pop(0)
            if nid in visited or depth > max_depth:
                continue
            visited.add(nid)
            if nid != node_id:
                result.append(nid)
            for r in self.conn.execute("SELECT source FROM edges WHERE target=?", (nid,)).fetchall():
                if r["source"] not in visited:
                    queue.append((r["source"], depth + 1))
        return result

    def descendant_graph(self, node_id: str, max_depth: int = 10) -> list[str]:
        """Return all descendant node ids (following outgoing edges) up to max_depth."""
        if not self.has_node(node_id):
            return []
        visited = set()
        queue = [(node_id, 0)]
        result = []
        while queue:
            nid, depth = queue.pop(0)
            if nid in visited or depth > max_depth:
                continue
            visited.add(nid)
            if nid != node_id:
                result.append(nid)
            for r in self.conn.execute("SELECT target FROM edges WHERE source=?", (nid,)).fetchall():
                if r["target"] not in visited:
                    queue.append((r["target"], depth + 1))
        return result

    def random_node(self) -> Optional[Node]:
        """Return a random node from the graph, or None if empty."""
        row = self.conn.execute("SELECT id FROM nodes ORDER BY RANDOM() LIMIT 1").fetchone()
        return self.get_node(row["id"]) if row else None

    def unlink_all(self, node_id: str) -> int:
        """Remove all edges connected to node_id. Returns count of removed edges."""
        if not self.has_node(node_id):
            return 0
        count = self.conn.execute("SELECT COUNT(*) as c FROM edges WHERE source=? OR target=?",
                                   (node_id, node_id)).fetchone()["c"]
        self.conn.execute("DELETE FROM edges WHERE source=? OR target=?", (node_id, node_id))
        self.conn.commit()
        return count

    def edge_count(self, relation: str = None) -> int:
        """Total edge count, optionally filtered by relation."""
        if relation:
            return self.conn.execute("SELECT COUNT(*) as c FROM edges WHERE relation=?",
                                      (relation,)).fetchone()["c"]
        return self.conn.execute("SELECT COUNT(*) as c FROM edges").fetchone()["c"]

    def edge_weight_stats(self, relation: str = None) -> dict:
        """Statistics about edge weights (min/max/mean/sum/count).

        Args:
            relation: optional filter by relation type.
        """
        if relation:
            rows = self.conn.execute(
                "SELECT weight FROM edges WHERE relation=?", (relation,)
            ).fetchall()
        else:
            rows = self.conn.execute("SELECT weight FROM edges").fetchall()
        if not rows:
            return {"count": 0, "min": 0, "max": 0, "mean": 0, "sum": 0}
        weights = [r["weight"] for r in rows]
        return {
            "count": len(weights),
            "min": min(weights),
            "max": max(weights),
            "mean": round(sum(weights) / len(weights), 4),
            "sum": round(sum(weights), 4),
        }

    def weight_distribution(self, bins: int = 10) -> list[dict]:
        """Histogram of node weight distribution.

        Args:
            bins: number of histogram bins.
        """
        rows = self.conn.execute("SELECT weight FROM nodes").fetchall()
        if not rows:
            return []
        weights = [r["weight"] for r in rows]
        w_min, w_max = min(weights), max(weights)
        if w_max == w_min:
            return [{"range": f"{w_min:.2f}", "count": len(weights)}]
        step = (w_max - w_min) / bins
        distribution = []
        for i in range(bins):
            lo = w_min + i * step
            hi = lo + step if i < bins - 1 else w_max
            count = sum(1 for w in weights if lo <= w < hi or (i == bins - 1 and w == hi))
            distribution.append({
                "range": f"{lo:.2f}-{hi:.2f}",
                "count": count,
            })
        return distribution

    def find_components(self) -> list[list[str]]:
        """Find all connected components (undirected). Returns list of node-id lists."""
        visited = set()
        components = []
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        for r in rows:
            nid = r["id"]
            if nid in visited:
                continue
            # BFS
            comp = []
            queue = [nid]
            while queue:
                cur = queue.pop(0)
                if cur in visited:
                    continue
                visited.add(cur)
                comp.append(cur)
                for e in self.conn.execute("SELECT target FROM edges WHERE source=?", (cur,)).fetchall():
                    if e["target"] not in visited:
                        queue.append(e["target"])
                for e in self.conn.execute("SELECT source FROM edges WHERE target=?", (cur,)).fetchall():
                    if e["source"] not in visited:
                        queue.append(e["source"])
            components.append(comp)
        return components

    def distance_matrix(self, node_ids: list[str] = None) -> dict[tuple[str, str], int]:
        """Compute shortest-path lengths between all pairs (BFS). Returns {(src, tgt): dist}.

        If node_ids given, only compute for those nodes.
        """
        ids = node_ids
        if ids is None:
            ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        dist = {}
        for src in ids:
            if not self.has_node(src):
                continue
            # BFS from src
            visited = {src}
            queue = [(src, 0)]
            while queue:
                cur, d = queue.pop(0)
                if cur in ids and (src, cur) not in dist:
                    dist[(src, cur)] = d
                for e in self.conn.execute("SELECT target FROM edges WHERE source=?", (cur,)).fetchall():
                    if e["target"] not in visited:
                        visited.add(e["target"])
                        queue.append((e["target"], d + 1))
                for e in self.conn.execute("SELECT source FROM edges WHERE target=?", (cur,)).fetchall():
                    if e["source"] not in visited:
                        visited.add(e["source"])
                        queue.append((e["source"], d + 1))
        return dist

    def cluster(self, kind: str, threshold: float = 0.4) -> list[dict]:
        """Cluster nodes of a given kind by label similarity.

        Uses normalized Levenshtein distance to group labels that are similar.
        Returns list of {representative: str, labels: list[str], node_ids: list[str], size: int}.
        Nodes with no similar neighbor form singleton clusters.
        """
        rows = self.conn.execute("SELECT id, label FROM nodes WHERE kind=?", (kind,)).fetchall()
        if not rows:
            return []

        # Simple Levenshtein distance
        def _levenshtein(a: str, b: str) -> int:
            if len(a) < len(b):
                return _levenshtein(b, a)
            if not b:
                return len(a)
            prev = list(range(len(b) + 1))
            for i, ca in enumerate(a):
                curr = [i + 1]
                for j, cb in enumerate(b):
                    curr.append(min(prev[j + 1] + 1, curr[j] + 1, prev[j] + (0 if ca == cb else 1)))
                prev = curr
            return prev[-1]

        # Normalize: max(len(a), len(b)) to get 0-1 similarity
        nodes = [(r["id"], r["label"]) for r in rows]
        parent = list(range(len(nodes)))  # Union-Find

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # Compare all pairs — O(N^2) but fine for typical memory graphs
        for i in range(len(nodes)):
            for j in range(i + 1, len(nodes)):
                li, lj = nodes[i][1], nodes[j][1]
                max_len = max(len(li), len(lj), 1)
                dist = _levenshtein(li.lower(), lj.lower())
                similarity = 1.0 - dist / max_len
                if similarity >= (1.0 - threshold):
                    union(i, j)

        # Build clusters
        groups = defaultdict(list)
        for idx, (nid, label) in enumerate(nodes):
            groups[find(idx)].append((nid, label))

        result = []
        for members in groups.values():
            labels = [m[1] for m in members]
            # Use longest label as representative
            rep = max(labels, key=len)
            result.append({
                "representative": rep,
                "labels": sorted(labels),
                "node_ids": [m[0] for m in members],
                "size": len(members),
            })
        result.sort(key=lambda c: c["size"], reverse=True)
        return result

    def induced_subgraph(self, node_ids: list[str]) -> 'MemoryGraph':
        """Extract induced subgraph containing only specified node_ids and edges between them.

        Returns a new MemoryGraph instance with copied nodes and internal edges.
        Nodes not found in the current graph are skipped.
        """
        sub = MemoryGraph()
        id_set = set(node_ids)
        for nid in node_ids:
            node = self.get_node(nid)
            if not node:
                continue
            # Get tags from DB
            tags_row = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (nid,)).fetchone()
            tags = json.loads(tags_row["tags"]) if tags_row and tags_row["tags"] else []
            sub.add(node.label, node.kind, node.data, tags)
            # Remap to original id
            found = sub.conn.execute("SELECT id FROM nodes WHERE label=? ORDER BY created DESC LIMIT 1", (node.label,)).fetchone()
            if found:
                sub.conn.execute("UPDATE nodes SET id=?, weight=? WHERE id=?", (nid, node.weight, found["id"]))
                sub.conn.commit()
        # Add edges between nodes in the set
        for nid in node_ids:
            if not self.has_node(nid):
                continue
            for e in self.edges_of(nid, "outgoing"):
                if e.target in id_set:
                    if sub.has_node(nid) and sub.has_node(e.target):
                        sub.link(nid, e.target, e.relation, e.weight)
        return sub

    def evolve(self, node_id: str, new_label: str = None, new_kind: str = None) -> Optional[Node]:
        """Evolve a node's label/kind and log the change to evolution_history.
        Returns the updated node, or None if not found or nothing to change."""
        node = self.get_node(node_id)
        if node is None:
            return None
        old_label, old_kind = node.label, node.kind
        nl = new_label if new_label is not None else old_label
        nk = new_kind if new_kind is not None else old_kind
        if nl == old_label and nk == old_kind:
            return node  # nothing to change
        self.conn.execute(
            "INSERT INTO evolution_log (node_id, old_label, new_label, old_kind, new_kind, timestamp) VALUES (?,?,?,?,?,?)",
            (node_id, old_label, nl, old_kind, nk, time.time())
        )
        self.conn.execute(
            "UPDATE nodes SET label=?, kind=? WHERE id=?",
            (nl, nk, node_id)
        )
        self.conn.commit()
        node.label, node.kind = nl, nk
        return node

    def evolution_history(self, node_id: str) -> list[dict]:
        """Return the evolution audit trail for a node, oldest first."""
        rows = self.conn.execute(
            "SELECT old_label, new_label, old_kind, new_kind, timestamp FROM evolution_log WHERE node_id=? ORDER BY id ASC",
            (node_id,)
        ).fetchall()
        return [
            {"old_label": r[0], "new_label": r[1], "old_kind": r[2], "new_kind": r[3], "timestamp": r[4]}
            for r in rows
        ]

    def revert_evolution(self, node_id: str, step_index: int) -> Optional[Node]:
        """Revert a node to a specific evolution step (0-based index into evolution_history).
        Removes all evolution_log entries after step_index and restores label/kind.
        Returns the reverted node, or None if not found / invalid step."""
        node = self.get_node(node_id)
        if node is None:
            return None
        history = self.evolution_history(node_id)
        if not history or step_index < 0 or step_index >= len(history):
            return None
        # The label/kind at step_index is the NEW state of that step.
        # We revert TO that step's new_label/new_kind.
        target = history[step_index]
        # Delete log entries after step_index
        rows = self.conn.execute(
            "SELECT id FROM evolution_log WHERE node_id=? ORDER BY id ASC",
            (node_id,)
        ).fetchall()
        ids_to_delete = [r[0] for r in rows[step_index + 1:]]
        if ids_to_delete:
            placeholders = ",".join("?" * len(ids_to_delete))
            self.conn.execute(
                f"DELETE FROM evolution_log WHERE id IN ({placeholders})",
                ids_to_delete
            )
        self.conn.execute(
            "UPDATE nodes SET label=?, kind=? WHERE id=?",
            (target["new_label"], target["new_kind"], node_id)
        )
        self.conn.commit()
        node.label = target["new_label"]
        node.kind = target["new_kind"]
        return node

    def batch_evolve(self, mapping: list[dict]) -> list[Optional[Node]]:
        """Evolve multiple nodes in one call. Each dict: {node_id, new_label?, new_kind?}.
        Returns list of updated nodes (None for failures). Single transaction."""
        results = []
        for item in mapping:
            nid = item.get("node_id")
            if nid is None:
                results.append(None)
                continue
            results.append(self.evolve(nid, item.get("new_label"), item.get("new_kind")))
        return results

    def is_dag(self) -> bool:
        """Check if the graph is a Directed Acyclic Graph (no cycles)."""
        visited = set()
        rec_stack = set()

        def _dfs(node_id):
            visited.add(node_id)
            rec_stack.add(node_id)
            rows = self.conn.execute(
                "SELECT target FROM edges WHERE source = ?", (node_id,)
            ).fetchall()
            for (target,) in rows:
                if target not in visited:
                    if _dfs(target):
                        return True
                elif target in rec_stack:
                    return True
            rec_stack.discard(node_id)
            return False

        all_nodes = [r[0] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        for nid in all_nodes:
            if nid not in visited:
                if _dfs(nid):
                    return False
        return True

    def topological_sort(self) -> list:
        """Return nodes in topological order (Kahn's algorithm). Returns [] if graph has cycles."""
        nodes = [r[0] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        in_degree = {nid: 0 for nid in nodes}
        adj = {nid: [] for nid in nodes}
        for src, tgt in self.conn.execute("SELECT source, target FROM edges").fetchall():
            adj[src].append(tgt)
            in_degree[tgt] = in_degree.get(tgt, 0) + 1

        queue = [nid for nid in nodes if in_degree[nid] == 0]
        result = []
        while queue:
            node = queue.pop(0)
            result.append(node)
            for neighbor in adj[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)
        return result if len(result) == len(nodes) else []

    def find_paths(self, from_id: int, to_id: int, max_depth: int = 10) -> list:
        """Find all simple paths between two nodes (DFS, max_depth limit)."""
        if not self.has_node(from_id) or not self.has_node(to_id):
            return []
        results = []

        def _dfs(current, target, path, visited):
            if len(path) - 1 > max_depth:
                return
            if current == target:
                results.append(list(path))
                return
            neighbors = self.conn.execute(
                "SELECT target FROM edges WHERE source = ?", (current,)
            ).fetchall()
            for (nxt,) in neighbors:
                if nxt not in visited:
                    visited.add(nxt)
                    path.append(nxt)
                    _dfs(nxt, target, path, visited)
                    path.pop()
                    visited.discard(nxt)

        _dfs(from_id, to_id, [from_id], {from_id})
        return results

    def jaccard_similarity(self, node_id1: int, node_id2: int) -> float:
        """Jaccard similarity of neighbor sets between two nodes."""
        n1 = set(r[0] for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id1, node_id1)).fetchall())
        n2 = set(r[0] for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id2, node_id2)).fetchall())
        if not n1 and not n2:
            return 0.0
        return len(n1 & n2) / len(n1 | n2)

    def neighborhood_overlap(self, node_id1: int, node_id2: int) -> float:
        """Overlap coefficient of neighbor sets (how much of the smaller set is shared)."""
        n1 = set(r[0] for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id1, node_id1)).fetchall())
        n2 = set(r[0] for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id2, node_id2)).fetchall())
        min_size = min(len(n1), len(n2))
        if min_size == 0:
            return 0.0
        return len(n1 & n2) / min_size

    def adamic_adar(self, node_id1: int, node_id2: int) -> float:
        """Adamic/Adar index — sum of 1/log(degree) over shared neighbors. Link prediction."""
        n1 = set(r[0] for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id1, node_id1)).fetchall())
        n2 = set(r[0] for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
            (node_id2, node_id2)).fetchall())
        common = n1 & n2
        score = 0.0
        for c in common:
            deg = self.conn.execute(
                "SELECT COUNT(*) FROM edges WHERE source=? OR target=?", (c, c)
            ).fetchone()[0]
            if deg > 1:
                score += 1.0 / (1.0 + deg)  # avoid log(0), use deg+1
        return score

    # ── Edge Management ──────────────────────────────────

    def get_edge(self, source_id: str, target_id: str, relation: str) -> Optional[Edge]:
        """Get a specific edge by source, target, and relation. Returns None if not found."""
        row = self.conn.execute(
            "SELECT * FROM edges WHERE source=? AND target=? AND relation=?",
            (source_id, target_id, relation)
        ).fetchone()
        if not row:
            return None
        return Edge(row["source"], row["target"], row["relation"], row["weight"])

    def update_edge(self, source_id: str, target_id: str, relation: str,
                    weight: float = None, new_relation: str = None) -> Optional[Edge]:
        """Update an edge's weight and/or rename its relation. Returns updated Edge or None."""
        existing = self.get_edge(source_id, target_id, relation)
        if not existing:
            return None
        if new_relation and new_relation != relation:
            # Rename relation: insert new, delete old
            self.conn.execute(
                "INSERT INTO edges (source, target, relation, weight) VALUES (?, ?, ?, ?)",
                (source_id, target_id, new_relation, weight if weight is not None else existing.weight)
            )
            self.conn.execute(
                "DELETE FROM edges WHERE source=? AND target=? AND relation=?",
                (source_id, target_id, relation)
            )
        elif weight is not None:
            self.conn.execute(
                "UPDATE edges SET weight=? WHERE source=? AND target=? AND relation=?",
                (weight, source_id, target_id, relation)
            )
        self.conn.commit()
        return self.get_edge(source_id, target_id, new_relation or relation)

    def edge_properties(self, source_id: str, target_id: str, relation: str) -> Optional[dict]:
        """Get edge properties (metadata dict stored in data column). Returns None if edge not found."""
        row = self.conn.execute(
            "SELECT properties FROM edge_props WHERE source=? AND target=? AND relation=?",
            (source_id, target_id, relation)
        ).fetchone()
        if not row:
            return None
        return json.loads(row["properties"])

    def set_edge_properties(self, source_id: str, target_id: str, relation: str,
                            properties: dict) -> bool:
        """Set edge properties (upsert). Returns False if edge doesn't exist."""
        if not self.get_edge(source_id, target_id, relation):
            return False
        self.conn.execute(
            "INSERT OR REPLACE INTO edge_props (source, target, relation, properties) VALUES (?, ?, ?, ?)",
            (source_id, target_id, relation, json.dumps(properties))
        )
        self.conn.commit()
        return True

    def graph_hash(self) -> str:
        """Return a deterministic structural fingerprint (MD5) of the graph.
        Based on sorted node/edge data, not IDs."""
        import hashlib
        parts = []
        for r in self.conn.execute("SELECT label, kind, weight FROM nodes ORDER BY label").fetchall():
            parts.append(f"n:{r['label']}|{r['kind']}|{r['weight']:.4f}")
        for r in self.conn.execute(
            "SELECT source, target, relation, weight FROM edges ORDER BY source, target, relation"
        ).fetchall():
            parts.append(f"e:{r['source']}|{r['target']}|{r['relation']}|{r['weight']:.4f}")
        return hashlib.md5("\n".join(parts).encode()).hexdigest()

    def snapshot(self) -> dict:
        """Capture complete graph state as a dict (nodes + edges + evolution log)."""
        return {
            "nodes": [dict(r) for r in self.conn.execute("SELECT * FROM nodes").fetchall()],
            "edges": [dict(r) for r in self.conn.execute("SELECT * FROM edges").fetchall()],
            "evolution": [dict(r) for r in self.conn.execute("SELECT * FROM evolution_log").fetchall()],
            "edge_props": [dict(r) for r in self.conn.execute("SELECT * FROM edge_props").fetchall()],
        }

    def restore(self, snap: dict) -> None:
        """Restore graph to a previously captured snapshot state."""
        self.conn.executescript("DELETE FROM edge_props; DELETE FROM evolution_log; DELETE FROM edges; DELETE FROM nodes;")
        for n in snap.get("nodes", []):
            self.conn.execute(
                "INSERT INTO nodes (id, label, kind, data, created, accessed, weight, tags) VALUES (?,?,?,?,?,?,?,?)",
                (n["id"], n["label"], n["kind"], n["data"], n["created"], n["accessed"], n["weight"], n.get("tags", "[]"))
            )
        for e in snap.get("edges", []):
            self.conn.execute(
                "INSERT INTO edges (source, target, relation, weight) VALUES (?,?,?,?)",
                (e["source"], e["target"], e["relation"], e["weight"])
            )
        for ev in snap.get("evolution", []):
            self.conn.execute(
                "INSERT INTO evolution_log (id, node_id, old_label, new_label, old_kind, new_kind, timestamp) VALUES (?,?,?,?,?,?,?)",
                (ev["id"], ev["node_id"], ev["old_label"], ev["new_label"], ev["old_kind"], ev["new_kind"], ev["timestamp"])
            )
        for ep in snap.get("edge_props", []):
            self.conn.execute(
                "INSERT INTO edge_props (source, target, relation, properties) VALUES (?,?,?,?)",
                (ep["source"], ep["target"], ep["relation"], ep["properties"])
            )
        self.conn.commit()

    def dedup_nodes(self, similarity_threshold: float = 0.8) -> list[dict]:
        """Find and merge nodes with similar labels (Levenshtein-based).
        Returns list of merged groups: [{kept_id, merged_ids, label}]."""
        def _levenshtein(a, b):
            if len(a) < len(b):
                return _levenshtein(b, a)
            if not b:
                return len(a)
            prev = list(range(len(b) + 1))
            for i, ca in enumerate(a):
                curr = [i + 1]
                for j, cb in enumerate(b):
                    curr.append(min(prev[j + 1] + 1, curr[j] + 1,
                                    prev[j] + (0 if ca == cb else 1)))
                prev = curr
            return prev[-1]

        nodes = self.conn.execute("SELECT id, label FROM nodes").fetchall()
        merged_groups = []
        already_merged = set()

        for i, n1 in enumerate(nodes):
            if n1["id"] in already_merged:
                continue
            group = []
            for n2 in nodes[i + 1:]:
                if n2["id"] in already_merged:
                    continue
                max_len = max(len(n1["label"]), len(n2["label"]), 1)
                dist = _levenshtein(n1["label"], n2["label"])
                sim = 1.0 - dist / max_len
                if sim >= similarity_threshold and n1["id"] != n2["id"]:
                    group.append(n2)
            if group:
                for dup in group:
                    self.merge_nodes(dup["id"], n1["id"])
                    already_merged.add(dup["id"])
                merged_groups.append({
                    "kept_id": n1["id"],
                    "merged_ids": [d["id"] for d in group],
                    "label": n1["label"]
                })
        self.conn.commit()
        return merged_groups

    def merge_evolution(self, node_id: str) -> Optional[dict]:
        """Collapse all evolution steps for a node into a single summary entry.
        The summary records the original state → final state as one transition.
        Returns the summary dict, or None if node doesn't exist or has no history."""
        node = self.get_node(node_id)
        if node is None:
            return None
        history = self.evolution_history(node_id)
        if not history:
            return None
        first = history[0]
        last = history[-1]
        summary = {
            "node_id": node_id,
            "old_label": first["old_label"],
            "new_label": last["new_label"],
            "old_kind": first["old_kind"],
            "new_kind": last["new_kind"],
            "steps_collapsed": len(history),
            "timestamp": last["timestamp"],
        }
        # Delete all existing entries and insert single summary
        self.conn.execute("DELETE FROM evolution_log WHERE node_id=?", (node_id,))
        self.conn.execute(
            "INSERT INTO evolution_log (node_id, old_label, new_label, old_kind, new_kind, timestamp) VALUES (?, ?, ?, ?, ?, ?)",
            (node_id, summary["old_label"], summary["new_label"],
             summary["old_kind"], summary["new_kind"], summary["timestamp"])
        )
        self.conn.commit()
        return summary

    def evolution_summary(self) -> dict:
        """Global evolution statistics across all nodes.
        Returns: {total_nodes, evolved_nodes, total_steps, most_evolved, avg_steps}."""
        total_nodes = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        evolved = self.conn.execute(
            "SELECT node_id, COUNT(*) as steps FROM evolution_log GROUP BY node_id ORDER BY steps DESC"
        ).fetchall()
        evolved_nodes = len(evolved)
        total_steps = sum(r["steps"] for r in evolved)
        most_evolved = [{"node_id": r["node_id"], "steps": r["steps"]} for r in evolved[:5]]
        avg_steps = round(total_steps / evolved_nodes, 2) if evolved_nodes > 0 else 0.0
        return {
            "total_nodes": total_nodes,
            "evolved_nodes": evolved_nodes,
            "total_steps": total_steps,
            "most_evolved": most_evolved,
            "avg_steps": avg_steps,
        }

    def bfs_shortest_path(self, start_id: str, end_id: str, weight_key: str = None) -> Optional[list]:
        """BFS最短路径。若 weight_key 给出则返回边权重的总和。"""
        if not self.has_node(start_id) or not self.has_node(end_id):
            return None
        if start_id == end_id:
            return [start_id]
        visited = {start_id}
        queue = [(start_id, [start_id])]
        while queue:
            current, path = queue.pop(0)
            for nb in self.neighbors(current):
                nid = str(nb.id)
                if nid in visited:
                    continue
                visited.add(nid)
                new_path = path + [nid]
                if nid == end_id:
                    return new_path
                queue.append((nid, new_path))
        return None

    def centrality_degree(self, node_id: str) -> Optional[float]:
        """度中心性 = degree / (n-1)，考虑双向边。"""
        if not self.has_node(node_id):
            return None
        n = self.stats()["nodes"]
        if n <= 1:
            return 0.0
        row = self.conn.execute(
            "SELECT COUNT(*) AS c FROM edges WHERE source=? OR target=?", (node_id, node_id)
        ).fetchone()
        return row["c"] / (n - 1) if row else 0.0

    def reachability_count(self, node_id: str, max_depth: int = 10) -> int:
        """从 node_id 可达的不同节点数（BFS，不含自身）。"""
        if not self.has_node(node_id):
            return 0
        visited = {node_id}
        queue = [node_id]
        depth = 0
        while queue and depth < max_depth:
            depth += 1
            next_q = []
            for cur in queue:
                for nb in self.neighbors(cur):
                    nid = str(nb.id)
                    if nid not in visited:
                        visited.add(nid)
                        next_q.append(nid)
            queue = next_q
        return len(visited) - 1

    def graph_density(self) -> float:
        """图密度 = 实际边数 / 最大可能边数。有向图最大 n*(n-1)。"""
        stats = self.stats()
        n = stats["nodes"]
        if n <= 1:
            return 0.0
        e = stats["edges"]
        return e / (n * (n - 1))

    def reciprocity(self) -> float:
        """互惠率 = 双向边对数 / 总边数。"""
        stats = self.stats()
        e = stats["edges"]
        if e == 0:
            return 0.0
        rows = self.conn.execute("SELECT source, target, relation FROM edges").fetchall()
        pairs = set()
        reciprocal = 0
        for r in rows:
            key = (str(r["source"]), str(r["target"]), r["relation"])
            rev = (str(r["target"]), str(r["source"]), r["relation"])
            if rev in pairs:
                reciprocal += 1
            pairs.add(key)
        return reciprocal * 2 / e if reciprocal > 0 else 0.0

    def assortativity_degree(self) -> float:
        """度-度相关性: 正值=相似度节点互连(同配), 负值=异配。"""
        rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not rows:
            return 0.0
        deg = {}
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            deg[s] = deg.get(s, 0) + 1
            deg[t] = deg.get(t, 0) + 1
        # Also count edges from reverse direction (in-degree)
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            # total degree already counted both directions above
        m = len(rows)
        sum_jk = sum(deg.get(str(r["source"]), 0) * deg.get(str(r["target"]), 0) for r in rows)
        sum_j_plus_k = sum((deg.get(str(r["source"]), 0) + deg.get(str(r["target"]), 0)) ** 2 for r in rows)
        sigma_sq = sum_j_plus_k / (2 * m) - (sum_jk / m) ** 2 if m > 0 else 0
        if sigma_sq == 0:
            return 0.0
        r_val = (sum_jk / m - sum_j_plus_k / (4 * m * m)) / (sigma_sq / (2 * m)) if m > 0 else 0.0
        return max(-1.0, min(1.0, r_val))

    def clustering_coefficient(self, node_id: str) -> Optional[float]:
        """局部聚类系数: 邻居间实际边数 / 最大可能边数。"""
        if not self.has_node(node_id):
            return None
        nbs = set()
        for n in self.neighbors(node_id):
            nbs.add(str(n.id))
        for r in self.conn.execute("SELECT source FROM edges WHERE target=?", (node_id,)).fetchall():
            nbs.add(str(r["source"]))
        k = len(nbs)
        if k < 2:
            return 0.0
        nb_set = set(nbs)
        links = 0
        rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            if s in nb_set and t in nb_set and s != t:
                links += 1
        return links / (k * (k - 1))

    def rich_club_coefficient(self, degree_k: int) -> float:
        """富人俱乐部系数: 度>=k的节点间实际边数/最大可能。"""
        rows = self.conn.execute(
            "SELECT source FROM edges UNION ALL SELECT target FROM edges"
        ).fetchall()
        deg = {}
        for r in rows:
            nid = str(r[0]) if not isinstance(r, dict) else str(r[list(r.keys())[0]])
            deg[nid] = deg.get(nid, 0) + 1
        rich = [nid for nid, d in deg.items() if d >= degree_k]
        nr = len(rich)
        if nr < 2:
            return 0.0
        rich_set = set(rich)
        links = 0
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            if s in rich_set and t in rich_set:
                links += 1
        return links / (nr * (nr - 1))

    def global_clustering_coefficient(self) -> float:
        """全局聚类系数(传递性): 闭合三元组数 / 三元组总数。"""
        rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if len(rows) < 2:
            return 0.0
        # Build adjacency (directed)
        adj = {}
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            adj.setdefault(s, set()).add(t)
        all_nodes = set(adj.keys())
        for targets in adj.values():
            all_nodes.update(targets)
        # Count triplets (a->b->c) and triangles (a->b->c and a->c)
        triplets = 0
        triangles = 0
        for a in adj:
            for b in adj.get(a, set()):
                for c in adj.get(b, set()):
                    if c != a:
                        triplets += 1
                        if c in adj.get(a, set()):
                            triangles += 1
        return triangles / triplets if triplets > 0 else 0.0

    def _modularity_simple(self, communities: dict[str, int]) -> float:
        """模块度 Q: 衡量社区划分质量。communities = {node_id: community_id}。"""
        rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not rows:
            return 0.0
        m = len(rows)
        # Degree of each node
        deg = {}
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            deg[s] = deg.get(s, 0) + 1
            deg[t] = deg.get(t, 0) + 1
        q = 0.0
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            c_s = communities.get(s, 0)
            c_t = communities.get(t, 0)
            if c_s == c_t:
                q += 1 - (deg.get(s, 0) * deg.get(t, 0)) / (2 * m)
        return q / (2 * m)

    # ── 生命周期 & 工具方法 ──────────────────────────────

    def clear(self) -> None:
        """删除所有节点和边，重置图为空状态。"""
        self.conn.execute("DELETE FROM edges")
        self.conn.execute("DELETE FROM edge_props")
        self.conn.execute("DELETE FROM evolution_log")
        self.conn.execute("DELETE FROM nodes")
        if getattr(self, '_fts_enabled', False):
            self.conn.execute("DELETE FROM nodes_fts")
        self.conn.commit()

    def is_empty(self) -> bool:
        """图是否为空（无节点）。"""
        row = self.conn.execute("SELECT COUNT(*) AS c FROM nodes").fetchone()
        return row["c"] == 0

    def count_edges(self) -> int:
        """返回图中边的总数。"""
        row = self.conn.execute("SELECT COUNT(*) AS c FROM edges").fetchone()
        return row["c"]

    def batch_reweight(self, items: list[dict]) -> int:
        """批量调整权重。items = [{"id": ..., "delta": 0.1}, ...]。返回成功更新数。"""
        count = 0
        for item in items:
            nid = str(item["id"])
            delta = float(item["delta"])
            node = self.conn.execute(
                "SELECT id, weight FROM nodes WHERE id=?", (nid,)
            ).fetchone()
            if node is None:
                continue
            new_weight = max(0.0, node["weight"] + delta)
            self.conn.execute(
                "UPDATE nodes SET weight=? WHERE id=?",
                (new_weight, nid),
            )
            count += 1
        self.conn.commit()
        return count

    def to_adjacency_list(self) -> dict[str, list[dict]]:
        """导出邻接表表示。返回 {node_id: [{"target": ..., "relation": ..., "weight": ...}]}。"""
        adj: dict[str, list[dict]] = {}
        rows = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges"
        ).fetchall()
        for r in rows:
            adj.setdefault(str(r["source"]), []).append({
                "target": str(r["target"]),
                "relation": r["relation"],
                "weight": r["weight"],
            })
        return adj

    def to_adjacency_matrix(self, weight_key: str = None) -> dict[str, dict]:
        """Export adjacency matrix as nested dict: {source: {target: value}}.

        Args:
            weight_key: if None, uses 1 for connected (binary).
                        'weight' uses edge weight.
                        Other values try edge properties JSON.
        """
        node_rows = self.conn.execute("SELECT id FROM nodes ORDER BY id").fetchall()
        node_ids = [str(r["id"]) for r in node_rows]
        matrix = {nid: {} for nid in node_ids}
        if weight_key is None or weight_key == "weight":
            edge_rows = self.conn.execute(
                "SELECT source, target, weight FROM edges"
            ).fetchall()
            for e in edge_rows:
                s, t = str(e["source"]), str(e["target"])
                matrix[s][t] = e["weight"] if weight_key == "weight" else 1
        else:
            # Try edge_properties method if available
            edge_rows = self.conn.execute(
                "SELECT source, target, relation, weight FROM edges"
            ).fetchall()
            for e in edge_rows:
                s, t = str(e["source"]), str(e["target"])
                props = self.edge_properties(s, t, e["relation"])
                matrix[s][t] = (props or {}).get(weight_key, 0)
        return matrix

    def node_distance(self, source_id: str, target_id: str) -> Optional[int]:
        """Shortest unweighted hop distance between two nodes. Returns None if unreachable.

        Alias for shortest_path length, but returns just the integer distance
        for quick connectivity checks.
        """
        path = self.shortest_path(source_id, target_id)
        if path is None:
            return None
        return len(path) - 1

    def serialize_dot(self) -> str:
        """导出为 Graphviz DOT 格式字符串，用于可视化工具集成。"""
        lines = ["digraph memory {"]
        lines.append('  node [shape=box];')
        nodes = self.conn.execute("SELECT id, label, kind, weight FROM nodes").fetchall()
        for n in nodes:
            safe_label = n["label"].replace('"', '\\"')
            lines.append(
                f'  "{n["id"]}" [label="{safe_label}", kind="{n["kind"]}", weight="{n["weight"]:.2f}"];'
            )
        edges = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges"
        ).fetchall()
        for e in edges:
            safe_rel = e["relation"].replace('"', '\\"')
            lines.append(
                f'  "{e["source"]}" -> "{e["target"]}" [label="{safe_rel}", weight="{e["weight"]:.2f}"];'
            )
        lines.append("}")
        return "\n".join(lines)

    # ── Import formats (round-trip from serialize_*) ──────────────────────

    def _insert_node_raw(self, nid: str, label: str, kind: str = "", weight: float = 1.0, tags: list = None):
        """直接用指定 ID 插入节点（内部方法，用于 import）。"""
        now = time.time()
        self.conn.execute(
            "INSERT OR IGNORE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
            (nid, label, kind, "{}", now, now, weight, json.dumps(tags or []))
        )
        self.conn.commit()

    def import_adjacency_list(self, adj: dict, *, merge: bool = False) -> dict:
        """从邻接表导入，兼容 to_adjacency_list() 的输出格式。

        Args:
            adj: {source_id: [{"target": ..., "relation": ..., "weight": ...}, ...]}
            merge: True=合入现有图, False=清空后导入

        Returns:
            {"nodes": N, "edges": M} 导入统计
        """
        if not merge:
            self.clear()
        node_count = edge_count = 0
        for src, edges in adj.items():
            if not self.has_node(src):
                self._insert_node_raw(src, src)
                node_count += 1
            for e in edges:
                tgt = e.get("target", e.get("target_id", ""))
                if not tgt:
                    continue
                rel = e.get("relation", "")
                w = e.get("weight", 1.0)
                if not self.has_node(tgt):
                    self._insert_node_raw(tgt, tgt)
                    node_count += 1
                self.link(src, tgt, rel, weight=w)
                edge_count += 1
        return {"nodes": node_count, "edges": edge_count}

    def import_edgelist(self, lines: list[str], *, merge: bool = False) -> dict:
        """从边列表导入。每行格式 'source_id target_id [weight]'。

        Args:
            lines: 边列表字符串列表
            merge: True=合入现有图(跳过已有节点), False=清空后导入

        Returns:
            {"nodes": N, "edges": M} 导入统计
        """
        if not merge:
            self.clear()
        node_count = edge_count = 0
        for raw in lines:
            parts = raw.strip().split()
            if len(parts) < 2:
                continue
            src, tgt = parts[0], parts[1]
            weight = float(parts[2]) if len(parts) >= 3 else 1.0
            if not self.has_node(src):
                self._insert_node_raw(src, src)
                node_count += 1
            if not self.has_node(tgt):
                self._insert_node_raw(tgt, tgt)
                node_count += 1
            self.link(src, tgt, "", weight=weight)
            edge_count += 1
        return {"nodes": node_count, "edges": edge_count}

    def import_cytoscape(self, data: dict, *, merge: bool = False) -> dict:
        """从 Cytoscape.js JSON 导入，兼容 serialize_cytoscape() 的输出格式。

        Args:
            data: Cytoscape.js JSON dict
            merge: True=合入现有图, False=清空后导入

        Returns:
            {"nodes": N, "edges": M} 导入统计
        """
        if not merge:
            self.clear()
        elements = data.get("elements", data)
        node_count = edge_count = 0

        # Import nodes first
        for n in elements.get("nodes", []):
            d = n.get("data", n)
            nid = str(d["id"])
            label = d.get("label", nid)
            kind = d.get("kind", "")
            weight = d.get("weight", 1.0)
            tags = d.get("tags", [])
            if merge and self.has_node(nid):
                continue
            self._insert_node_raw(nid, label, kind, weight, tags if isinstance(tags, list) else [tags] if tags else None)
            node_count += 1

        # Import edges
        for e in elements.get("edges", []):
            d = e.get("data", e)
            src = str(d["source"])
            tgt = str(d["target"])
            relation = d.get("relation", "")
            weight = d.get("weight", 1.0)
            self.link(src, tgt, relation, weight=weight)
            edge_count += 1

        return {"nodes": node_count, "edges": edge_count}

    def import_graphml(self, xml_string: str, *, merge: bool = False) -> dict:
        """从 GraphML XML 导入。

        Args:
            xml_string: GraphML XML 字符串
            merge: True=合入现有图, False=清空后导入

        Returns:
            {"nodes": N, "edges": M} 导入统计
        """
        import xml.etree.ElementTree as ET
        if not merge:
            self.clear()
        ns = "{http://graphml.graphdrawing.org/xmlns}"
        root = ET.fromstring(xml_string)

        # Build key mapping (key id -> attr name / type)
        key_map = {}
        for key in root.findall(f"{ns}key"):
            key_map[key.get("id")] = {
                "name": key.get("attr.name", key.get("id")),
                "for": key.get("for", "node"),
            }

        node_count = edge_count = 0
        graph = root.find(f"{ns}graph")
        if graph is None:
            return {"nodes": 0, "edges": 0}

        # Parse data values from <data key="..."> elements
        def parse_data(parent_el, target_type):
            vals = {}
            for d in parent_el.findall(f"{ns}data"):
                key_id = d.get("key")
                if key_id in key_map and key_map[key_id]["for"] == target_type:
                    vals[key_map[key_id]["name"]] = d.text or ""
            return vals

        # Import nodes
        for node_el in graph.findall(f"{ns}node"):
            nid = node_el.get("id")
            if merge and self.has_node(nid):
                continue
            attrs = parse_data(node_el, "node")
            label = attrs.get("label", nid)
            kind = attrs.get("kind", "")
            weight = float(attrs.get("weight", 1.0))
            self._insert_node_raw(nid, label, kind, weight)
            node_count += 1

        # Import edges
        for edge_el in graph.findall(f"{ns}edge"):
            src = edge_el.get("source")
            tgt = edge_el.get("target")
            attrs = parse_data(edge_el, "edge")
            relation = attrs.get("relation", "")
            weight = float(attrs.get("weight", 1.0))
            self.link(src, tgt, relation=relation, weight=weight)
            edge_count += 1

        return {"nodes": node_count, "edges": edge_count}

    def find_orphans(self) -> list[Node]:
        """返回所有没有边的孤立节点。"""
        rows = self.conn.execute(
            """SELECT n.* FROM nodes n
               WHERE NOT EXISTS (SELECT 1 FROM edges e WHERE e.source = n.id OR e.target = n.id)
               ORDER BY n.weight DESC"""
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                    json.loads(r["data"]) if r["data"] else {},
                    r["created"], r["accessed"], r["weight"])
                for r in rows]

    # ── Graph theory algorithms ──────────────────────────────────────────

    def is_bipartite(self) -> bool:
        """检查图是否为二分图（BFS 染色法，将边视为无向）。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        color = {}  # node_id -> 0/1
        # Build undirected adjacency
        adj = {str(r["id"]): [] for r in nodes}
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = str(e["source"]), str(e["target"])
            adj.setdefault(s, []).append(t)
            adj.setdefault(t, []).append(s)
        for start in adj:
            if start in color:
                continue
            color[start] = 0
            queue = [start]
            while queue:
                u = queue.pop(0)
                for v in adj.get(u, []):
                    if v not in color:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False
        return True

    def find_bridges(self) -> list[tuple]:
        """寻找桥边（删除后使图不连通的边），基于 Tarjan 桥算法。

        将边视为无向。返回 [(source, target, relation), ...]。
        """
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        node_ids = [str(r["id"]) for r in nodes]
        # Build undirected adjacency with edge info
        adj = {nid: [] for nid in node_ids}
        edge_map = {}  # (u,v sorted) -> (source, target, relation)
        for e in self.conn.execute("SELECT source, target, relation FROM edges").fetchall():
            s, t, rel = str(e["source"]), str(e["target"]), e["relation"]
            adj.setdefault(s, []).append(t)
            adj.setdefault(t, []).append(s)
            key = tuple(sorted([s, t]))
            edge_map[key] = (s, t, rel)

        disc = {}
        low = {}
        timer = [0]
        bridges = []

        def dfs(u, parent):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            for v in adj.get(u, []):
                if v not in disc:
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        key = tuple(sorted([u, v]))
                        if key in edge_map:
                            bridges.append(edge_map[key])
                elif v != parent:
                    low[u] = min(low[u], disc[v])

        for nid in node_ids:
            if nid not in disc:
                dfs(nid, None)
        return bridges

    def articulation_points(self) -> list[str]:
        """寻找割点（删除后使图不连通的节点），基于 Tarjan 割点算法。

        将边视为无向。返回节点 ID 列表。
        """
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        node_ids = [str(r["id"]) for r in nodes]
        adj = {nid: set() for nid in node_ids}
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = str(e["source"]), str(e["target"])
            adj.setdefault(s, set()).add(t)
            adj.setdefault(t, set()).add(s)

        disc = {}
        low = {}
        timer = [0]
        ap = set()

        def dfs(u, parent):
            children = 0
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            for v in adj.get(u, []):
                if v not in disc:
                    children += 1
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if parent is None and children > 1:
                        ap.add(u)
                    elif parent is not None and low[v] >= disc[u]:
                        ap.add(u)
                elif v != parent:
                    low[u] = min(low[u], disc[v])

        for nid in node_ids:
            if nid not in disc:
                dfs(nid, None)
        return sorted(ap)

    def neighbors_filtered(self, node_id: str, relation: str = None, min_weight: float = 0, direction: str = "out") -> list[Node]:
        """获取邻居节点，支持关系/权重/方向过滤。

        Args:
            node_id: 起始节点
            relation: 仅包含此关系的边（None=所有）
            min_weight: 最小权重阈值
            direction: 'out'(出边), 'in'(入边), 'both'(双向)

        Returns:
            邻居 Node 列表
        """
        if direction == "out":
            sql = """SELECT DISTINCT n.* FROM nodes n
                      JOIN edges e ON n.id=e.target WHERE e.source=?"""
            params = [node_id]
        elif direction == "in":
            sql = """SELECT DISTINCT n.* FROM nodes n
                      JOIN edges e ON n.id=e.source WHERE e.target=?"""
            params = [node_id]
        else:
            sql = """SELECT DISTINCT n.* FROM nodes n
                      JOIN edges e ON (n.id=e.target AND e.source=?)
                         OR (n.id=e.source AND e.target=?)"""
            params = [node_id, node_id]

        if relation is not None:
            sql += " AND e.relation=?"
            params.append(relation)
        if min_weight > 0:
            sql += " AND e.weight >= ?"
            params.append(min_weight)

        rows = self.conn.execute(sql, params).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                    json.loads(r["data"]) if r["data"] else {},
                    r["created"], r["accessed"], r["weight"])
                for r in rows]

    def edge_betweenness(self) -> dict:
        """计算边介数中心性（基于最短路径经过次数）。

        将图视为无向。返回 {(source, target): betweenness_score}。
        """
        nodes = [str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        edges = self.conn.execute("SELECT DISTINCT source, target FROM edges").fetchall()
        edge_set = set()
        adj = {n: set() for n in nodes}
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            key = tuple(sorted([s, t]))
            edge_set.add(key)
            adj.setdefault(s, set()).add(t)
            adj.setdefault(t, set()).add(s)

        betweenness = {e: 0.0 for e in edge_set}

        for source in nodes:
            # BFS: find shortest paths
            dist = {source: 0}
            sigma = {source: 1}  # number of shortest paths
            pred = {n: [] for n in nodes}
            queue = [source]
            for u in queue:
                for v in adj.get(u, []):
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        sigma[v] = sigma[u]
                        pred[v] = [u]
                        queue.append(v)
                    elif dist[v] == dist[u] + 1:
                        sigma[v] += sigma[u]
                        pred[v].append(u)

            # Accumulation (Brandes' algorithm edge part)
            delta = {n: 0.0 for n in nodes}
            for w in reversed(queue):
                for v in pred[w]:
                    c = sigma[v] / sigma[w] * (1 + delta[w])
                    key = tuple(sorted([v, w]))
                    if key in betweenness:
                        betweenness[key] += c
                    delta[v] += c

        # Undirected: divide by 2
        for k in betweenness:
            betweenness[k] /= 2.0
        return betweenness

    def find_roots(self) -> list[Node]:
        """返回无入边的节点（有向图的根），包括孤立节点。"""
        rows = self.conn.execute(
            """SELECT n.* FROM nodes n
               WHERE NOT EXISTS (SELECT 1 FROM edges e_in WHERE e_in.target = n.id)
               ORDER BY n.weight DESC"""
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                    json.loads(r["data"]) if r["data"] else {},
                    r["created"], r["accessed"], r["weight"])
                for r in rows]

    def find_leaves(self) -> list[Node]:
        """返回无出边的节点（有向图的叶），包括孤立节点。"""
        rows = self.conn.execute(
            """SELECT n.* FROM nodes n
               WHERE NOT EXISTS (SELECT 1 FROM edges e_out WHERE e_out.source = n.id)
               ORDER BY n.weight DESC"""
        ).fetchall()
        return [Node(r["id"], r["label"], r["kind"],
                    json.loads(r["data"]) if r["data"] else {},
                    r["created"], r["accessed"], r["weight"])
                for r in rows]

    def has_cycle(self) -> bool:
        """检测图中是否存在环（基于 DFS 三色标记法）。"""
        nodes = [str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        adj: dict[str, list[str]] = {}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            adj.setdefault(str(r["source"]), []).append(str(r["target"]))
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {nid: WHITE for nid in nodes}

        def _visit(start):
            stack = [(start, iter(adj.get(start, [])))]
            color[start] = GRAY
            while stack:
                node, it = stack[-1]
                found = False
                for nb in it:
                    if color.get(nb, WHITE) == GRAY:
                        return True
                    if color.get(nb, WHITE) == WHITE:
                        color[nb] = GRAY
                        stack.append((nb, iter(adj.get(nb, []))))
                        found = True
                        break
                if not found:
                    color[node] = BLACK
                    stack.pop()
            return False

        for nid in nodes:
            if color[nid] == WHITE:
                if _visit(nid):
                    return True
        return False

    # ── 进阶图分析 ────────────────────────────────────────

    def degree_histogram(self) -> dict[int, int]:
        """度分布直方图。返回 {degree: count}。"""
        rows = self.conn.execute(
            """SELECT id, (
                SELECT COUNT(*) FROM edges e WHERE e.source = n.id OR e.target = n.id
               ) AS deg FROM nodes n"""
        ).fetchall()
        hist: dict[int, int] = {}
        for r in rows:
            d = r["deg"]
            hist[d] = hist.get(d, 0) + 1
        return hist

    def degree_sequence(self, order: str = "desc") -> list[int]:
        """返回所有节点的度数序列（排序后）。"""
        rows = self.conn.execute(
            """SELECT (
                SELECT COUNT(*) FROM edges e WHERE e.source = n.id OR e.target = n.id
               ) AS deg FROM nodes n"""
        ).fetchall()
        degs = [r["deg"] for r in rows]
        return sorted(degs, reverse=(order == "desc"))

    def largest_component_size(self) -> int:
        """最大连通分量大小（基于 Union-Find）。"""
        nodes = [str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        if not nodes:
            return 0
        parent = {nid: nid for nid in nodes}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for e in edges:
            union(str(e["source"]), str(e["target"]))

        comp_size: dict[str, int] = {}
        for nid in nodes:
            root = find(nid)
            comp_size[root] = comp_size.get(root, 0) + 1
        return max(comp_size.values()) if comp_size else 0

    def community_detection_greedy(self) -> dict[str, int]:
        """贪心社区检测（基于边密度）。返回 {node_id: community_id}。

        简单方法：按度数降序分配，高优先级节点吸引邻居。
        """
        nodes = [str(r["id"]) for r in
                 self.conn.execute("SELECT id FROM nodes ORDER BY weight DESC").fetchall()]
        if not nodes:
            return {}
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        adj: dict[str, set[str]] = {nid: set() for nid in nodes}
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in adj:
                adj[s].add(t)
            if t in adj:
                adj[t].add(s)

        community = {}
        next_cid = 0
        for nid in nodes:
            if nid in community:
                continue
            # Check if any neighbor already has a community
            neighbor_comms = {community[nb] for nb in adj[nid] if nb in community}
            if neighbor_comms:
                # Join the most connected community (first one for simplicity)
                community[nid] = min(neighbor_comms)
            else:
                community[nid] = next_cid
                next_cid += 1
        return community

    def detect_communities_leiden(self, resolution: float = 1.0,
                                  max_iterations: int = 10, seed: int = 42) -> dict[str, int]:
        """Leiden community detection algorithm (full 3-phase implementation).

        Three phases: Fast Local Move → Refinement → Aggregation.
        Guarantees well-connected communities (unlike Louvain).

        The Aggregation phase contracts communities into super-nodes and
        re-runs, producing a hierarchy that improves quality at each level.

        Args:
            resolution: γ parameter. <1 → larger communities, >1 → smaller communities.
            max_iterations: max outer iterations (move + refine + aggregate cycles).
            seed: random seed for reproducibility.

        Returns:
            {node_id: community_id} mapping.
        """
        import random as _rng
        _rng.seed(seed)

        raw_nodes = [str(r["id"]) for r in
                     self.conn.execute("SELECT id FROM nodes").fetchall()]
        if not raw_nodes:
            return {}

        raw_edges = self.conn.execute(
            "SELECT source, target, weight FROM edges").fetchall()

        # Build initial adjacency
        orig_adj: dict[str, dict[str, float]] = {n: {} for n in raw_nodes}
        for e in raw_edges:
            s, t, w = str(e["source"]), str(e["target"]), float(e["weight"] or 1.0)
            orig_adj[s][t] = orig_adj[s].get(t, 0.0) + w
            orig_adj[t][s] = orig_adj[t].get(s, 0.0) + w

        # Track original members of each super-node
        super_members: dict[str, set[str]] = {n: {n} for n in raw_nodes}
        cur_nodes = list(raw_nodes)
        cur_adj = orig_adj

        for _level in range(max_iterations):
            if len(cur_nodes) <= 1:
                break

            m2 = sum(sum(d.values()) for d in cur_adj.values())
            if m2 == 0:
                break

            degree = {n: sum(cur_adj[n].values()) for n in cur_nodes}

            # Initialize: each node in its own community
            community = {n: i for i, n in enumerate(cur_nodes)}
            comm_degree: dict[int, float] = {}
            for n in cur_nodes:
                comm_degree[community[n]] = comm_degree.get(community[n], 0.0) + degree[n]

            # === Phase 1: Fast Local Move ===
            queue = list(cur_nodes)
            _rng.shuffle(queue)
            in_queue = set(queue)
            moved_any = False

            while queue:
                node = queue.pop(0)
                in_queue.discard(node)
                cur = community[node]
                k_i = degree[node]

                # Compute edge weights to each neighboring community
                # (including current, for proper ΔQ)
                neighbor_comms: dict[int, float] = {}
                for nb in cur_adj[node]:
                    c = community[nb]
                    neighbor_comms[c] = neighbor_comms.get(c, 0.0) + cur_adj[node][nb]

                k_i_in_cur = neighbor_comms.get(cur, 0.0)
                sigma_cur = comm_degree.get(cur, 0.0) - k_i  # exclude self

                best_comm, best_delta = cur, 0.0
                for c, k_i_in_c in neighbor_comms.items():
                    if c == cur:
                        continue
                    sigma_c = comm_degree.get(c, 0.0)
                    # ΔQ = (k_i_in_c - k_i_in_cur) - γ * k_i * (Σ_c - (Σ_cur - k_i)) / m2
                    delta = ((k_i_in_c - k_i_in_cur)
                             - resolution * k_i * (sigma_c - sigma_cur) / m2)
                    if delta > best_delta:
                        best_delta = delta
                        best_comm = c

                if best_comm != cur:
                    comm_degree[cur] -= k_i
                    if comm_degree[cur] <= 0:
                        del comm_degree[cur]
                    comm_degree[best_comm] = comm_degree.get(best_comm, 0.0) + k_i
                    community[node] = best_comm
                    moved_any = True
                    for nb in cur_adj[node]:
                        if nb not in in_queue and community[nb] != best_comm:
                            queue.append(nb)
                            in_queue.add(nb)

            # Check convergence
            unique_comms = set(community.values())
            if not moved_any or len(unique_comms) == len(cur_nodes):
                break

            # === Phase 2: Refinement (connectivity guarantee) ===
            comm_members: dict[int, list[str]] = {}
            for n in cur_nodes:
                comm_members.setdefault(community[n], []).append(n)

            for cid, members in comm_members.items():
                if len(members) <= 1:
                    continue
                member_set = set(members)
                sub_adj: dict[str, set[str]] = {n: set() for n in members}
                for n in members:
                    for nb in cur_adj[n]:
                        if nb in member_set:
                            sub_adj[n].add(nb)

                # BFS connectivity check
                visited = set()
                queue_bfs = [members[0]]
                visited.add(members[0])
                while queue_bfs:
                    bfs_node = queue_bfs.pop(0)
                    for nb in sub_adj[bfs_node]:
                        if nb not in visited:
                            visited.add(nb)
                            queue_bfs.append(nb)

                if len(visited) < len(members):
                    max_comm = max(community.values()) + 1
                    for n in members:
                        if n not in visited:
                            comm_degree[community[n]] -= degree[n]
                            comm_degree[max_comm] = comm_degree.get(max_comm, 0.0) + degree[n]
                            community[n] = max_comm

            # === Phase 3: Aggregation ===
            unique_comms = set(community.values())
            comm_to_new: dict[int, str] = {cid: f"L{_level}_{cid}" for cid in unique_comms}

            # Build aggregated graph (with self-loops for internal edges)
            new_adj: dict[str, dict[str, float]] = {comm_to_new[c]: {} for c in unique_comms}
            for n in cur_nodes:
                src_new = comm_to_new[community[n]]
                for nb, w in cur_adj[n].items():
                    tgt_new = comm_to_new[community[nb]]
                    new_adj[src_new][tgt_new] = new_adj[src_new].get(tgt_new, 0.0) + w

            new_super: dict[str, set[str]] = {comm_to_new[c]: set() for c in unique_comms}
            for n in cur_nodes:
                new_super[comm_to_new[community[n]]].update(super_members[n])

            super_members = new_super
            cur_nodes = list(new_adj.keys())
            cur_adj = new_adj

        # Map back to original node IDs
        result: dict[str, int] = {}
        for final_id, (super_node, orig_ids) in enumerate(super_members.items()):
            for orig_id in orig_ids:
                result[orig_id] = final_id

        return result

    def modularity(self, communities: dict[str, int] = None) -> float:
        """Compute modularity Q for a community partition.

        Args:
            communities: {node_id: community_id}. If None, uses label propagation.

        Returns:
            Modularity value (-0.5 to 1.0, higher is better).
        """
        if communities is None:
            comm_map = self.community_detect()
            communities = {}
            for label, members in comm_map.items():
                for nid in members:
                    communities[nid] = label

        edges = self.conn.execute(
            "SELECT source, target, weight FROM edges").fetchall()
        nodes = [str(r["id"]) for r in
                 self.conn.execute("SELECT id FROM nodes").fetchall()]

        if not nodes or not edges:
            return 0.0

        m = sum(float(e["weight"] or 1.0) for e in edges)
        if m == 0:
            return 0.0

        degree = {n: 0.0 for n in nodes}
        adj: dict[str, dict[str, float]] = {n: {} for n in nodes}
        for e in edges:
            s, t, w = str(e["source"]), str(e["target"]), float(e["weight"] or 1.0)
            adj[s][t] = adj[s].get(t, 0.0) + w
            adj[t][s] = adj[t].get(s, 0.0) + w
            degree[s] += w
            degree[t] += w

        Q = 0.0
        for i, ni in enumerate(nodes):
            for nj in nodes[i+1:]:
                if communities.get(ni) == communities.get(nj):
                    A_ij = adj[ni].get(nj, 0.0)
                    Q += A_ij - degree[ni] * degree[nj] / (2 * m)
        return Q / (2 * m)

    def community_partition(self, algorithm: str = "leiden", resolution: float = 1.0,
                             seed: int = 42) -> dict[str, int]:
        """Detect communities and return {node_id: community_id} mapping.

        Args:
            algorithm: "leiden", "greedy", or "lp" (label propagation).
            resolution: Leiden resolution parameter (only for leiden).
            seed: Random seed (only for leiden).

        Returns:
            {node_id: community_id} dict.
        """
        if algorithm == "leiden":
            return self.detect_communities_leiden(resolution=resolution, seed=seed)
        elif algorithm == "greedy":
            return self.community_detection_greedy()
        else:
            # Label propagation returns {label: [nodes]}, invert to {node: label}
            lp_result = self.community_detect()
            return {nid: label for label, nids in lp_result.items() for nid in nids}

    def community_quality_report(self, algorithm: str = "leiden",
                                 resolution: float = 1.0) -> dict:
        """Generate a comprehensive community detection quality report.

        Compares algorithms and reports modularity, community count, size distribution.

        Args:
            algorithm: Primary algorithm for the report.
            resolution: Leiden resolution parameter.

        Returns dict with: algorithm, num_communities, modularity, sizes, coverage, connectivity.
        """
        nodes = [str(r["id"]) for r in
                 self.conn.execute("SELECT id FROM nodes").fetchall()]
        if not nodes:
            return {"algorithm": algorithm, "num_communities": 0, "modularity": 0.0,
                    "sizes": [], "coverage": 0.0, "connectivity": True}

        if algorithm == "leiden":
            partition = self.detect_communities_leiden(resolution=resolution)
        elif algorithm == "greedy":
            partition = self.community_detection_greedy()
        else:
            lp = self.community_detect()
            partition = {nid: label for label, nids in lp.items() for nid in nids}

        num_comms = len(set(partition.values()))
        q = self.modularity(communities=partition)
        sizes = {}
        for cid in partition.values():
            sizes[cid] = sizes.get(cid, 0) + 1
        size_values = sorted(sizes.values(), reverse=True)

        # Coverage: fraction of nodes assigned
        coverage = len(partition) / len(nodes) if nodes else 0.0

        # Check connectivity of each community
        all_connected = True
        for cid, members_ids in sizes.items():
            if members_ids <= 1:
                continue
            member_list = [n for n in nodes if partition.get(n) == cid]
            member_set = set(member_list)
            visited = set()
            queue = [member_list[0]]
            visited.add(member_list[0])
            while queue:
                cur = queue.pop(0)
                for r in self.conn.execute(
                    "SELECT source FROM edges WHERE target=? UNION SELECT target FROM edges WHERE source=?",
                    (cur, cur)).fetchall():
                    nb = str(r[0])
                    if nb in member_set and nb not in visited:
                        visited.add(nb)
                        queue.append(nb)
            if len(visited) < len(member_list):
                all_connected = False
                break

        return {
            "algorithm": algorithm,
            "num_communities": num_comms,
            "modularity": round(q, 4),
            "sizes": size_values,
            "min_size": min(size_values) if size_values else 0,
            "max_size": max(size_values) if size_values else 0,
            "coverage": round(coverage, 4),
            "connectivity": all_connected,
        }

    def community_hierarchy(self, resolutions: list[float] = None,
                            seed: int = 42) -> list[dict]:
        """Detect communities at multiple resolution levels for hierarchical analysis.

        Runs Leiden at different γ values to build a multi-granularity view.
        Lower γ → fewer/larger communities; higher γ → more/smaller communities.

        Args:
            resolutions: list of γ values. Default: [0.3, 0.5, 1.0, 1.5, 2.0].
            seed: random seed for reproducibility.

        Returns list of dicts (one per resolution) with:
            resolution, communities {node: cid}, num_communities, modularity, sizes.
        """
        if resolutions is None:
            resolutions = [0.3, 0.5, 1.0, 1.5, 2.0]

        results = []
        for gamma in resolutions:
            partition = self.detect_communities_leiden(
                resolution=gamma, seed=seed)
            num_c = len(set(partition.values()))
            q = self.modularity(partition)
            sizes = {}
            for cid in partition.values():
                sizes[cid] = sizes.get(cid, 0) + 1
            results.append({
                "resolution": gamma,
                "communities": partition,
                "num_communities": num_c,
                "modularity": round(q, 4),
                "sizes": sorted(sizes.values(), reverse=True),
            })
        return results

    def incremental_modularity(self, node_id: str, target_community: int,
                                communities: dict[str, int] = None,
                                resolution: float = 1.0) -> float:
        """Compute the modularity gain ΔQ for moving a node to a different community.

        Useful for evaluating community assignments without executing the move.

        Args:
            node_id: node to evaluate.
            target_community: community ID to move to.
            communities: {node_id: community_id} mapping. If None, auto-detects via Leiden.
            resolution: γ parameter.

        Returns:
            ΔQ value. Positive = beneficial move, negative = harmful.
        """
        if communities is None:
            communities = self.detect_communities_leiden(resolution=resolution)

        if node_id not in communities:
            return 0.0

        current = communities[node_id]
        if current == target_community:
            return 0.0

        edges = self.conn.execute(
            "SELECT source, target, weight FROM edges").fetchall()

        adj: dict[str, dict[str, float]] = defaultdict(dict)
        degree: dict[str, float] = defaultdict(float)
        total_weight = 0.0
        for e in edges:
            s, t, w = str(e["source"]), str(e["target"]), float(e["weight"] or 1.0)
            adj[s][t] = adj[s].get(t, 0.0) + w
            adj[t][s] = adj[t].get(s, 0.0) + w
            degree[s] += w
            degree[t] += w
            total_weight += w

        m2 = total_weight * 2.0 if total_weight > 0 else 1.0

        k_i = degree.get(node_id, 0.0)
        k_i_in_target = sum(w for nb, w in adj.get(node_id, {}).items()
                            if communities.get(nb) == target_community)
        k_i_in_current = sum(w for nb, w in adj.get(node_id, {}).items()
                             if communities.get(nb) == current)

        sigma_target = sum(degree[n] for n, c in communities.items() if c == target_community)
        sigma_current = sum(degree[n] for n, c in communities.items() if c == current)

        return ((k_i_in_target - k_i_in_current)
                - resolution * k_i * (sigma_target - sigma_current + k_i) / m2)

    def community_merge(self, comm_a: int, comm_b: int,
                        communities: dict[str, int] = None) -> dict[str, int]:
        """Merge two communities into one.

        Reassigns all nodes in comm_b to comm_a.

        Args:
            comm_a: community ID to merge into.
            comm_b: community ID to merge from.
            communities: partition dict. If None, auto-detects via Leiden.

        Returns:
            Updated {node_id: community_id} mapping.
        """
        if communities is None:
            communities = self.detect_communities_leiden()

        if comm_a == comm_b:
            return communities

        result = dict(communities)
        for nid, cid in result.items():
            if cid == comm_b:
                result[nid] = comm_a
        return result

    def community_split(self, comm_id: int,
                        communities: dict[str, int] = None,
                        resolution: float = 2.0,
                        seed: int = 42) -> dict[str, int]:
        """Split a community into sub-communities using higher-resolution Leiden.

        Extracts the subgraph induced by the community, then runs Leiden at
        higher resolution to find internal structure.

        Args:
            comm_id: community ID to split.
            communities: partition dict. If None, auto-detects via Leiden.
            resolution: γ for sub-graph detection (higher = more communities).
            seed: random seed.

        Returns:
            Updated {node_id: community_id} with new IDs for split communities.
        """
        if communities is None:
            communities = self.detect_communities_leiden()

        members = [nid for nid, cid in communities.items() if cid == comm_id]
        if len(members) <= 1:
            return communities

        # Get max community ID for generating new ones
        max_cid = max(communities.values())

        # Build member set for fast lookup
        member_set = set(members)

        # Get edges within the community
        edges = self.conn.execute(
            "SELECT source, target, weight FROM edges").fetchall()
        sub_edges = []
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in member_set and t in member_set:
                sub_edges.append(e)

        if len(sub_edges) < 2:
            return communities  # Can't split with < 2 internal edges

        # Build temporary subgraph adjacency
        sub_adj: dict[str, dict[str, float]] = {n: {} for n in members}
        total_w = 0.0
        for e in sub_edges:
            s, t, w = str(e["source"]), str(e["target"]), float(e["weight"] or 1.0)
            sub_adj[s][t] = sub_adj[s].get(t, 0.0) + w
            sub_adj[t][s] = sub_adj[t].get(s, 0.0) + w
            total_w += w

        if total_w == 0:
            return communities

        # Simple split: find connected components first
        # If already disconnected, split along component boundaries
        visited: set[str] = set()
        components: list[set[str]] = []
        for node in members:
            if node not in visited:
                component: set[str] = set()
                queue = [node]
                while queue:
                    cur = queue.pop(0)
                    if cur in visited:
                        continue
                    visited.add(cur)
                    component.add(cur)
                    for nb in sub_adj[cur]:
                        if nb not in visited:
                            queue.append(nb)
                components.append(component)

        if len(components) <= 1:
            # Subgraph is connected — try modularity-based split
            # Use simple degree-based splitting: high-degree nodes as seeds
            import random as _rng
            _rng.seed(seed)
            degree = {n: sum(sub_adj[n].values()) for n in members}
            # Sort by degree descending, pick top 2 as seeds
            sorted_nodes = sorted(members, key=lambda n: degree[n], reverse=True)
            if len(sorted_nodes) < 2:
                return communities
            seed_a, seed_b = sorted_nodes[0], sorted_nodes[1]
            # Assign each node to nearest seed by edge weight
            assign_a, assign_b = {seed_a}, {seed_b}
            for n in members:
                if n in (seed_a, seed_b):
                    continue
                w_a = sub_adj[n].get(seed_a, 0.0)
                w_b = sub_adj[n].get(seed_b, 0.0)
                if w_a >= w_b:
                    assign_a.add(n)
                else:
                    assign_b.add(n)
            components = [assign_a, assign_b]

        # Assign new community IDs
        result = dict(communities)
        for i, comp in enumerate(components):
            new_cid = max_cid + 1 + i
            for nid in comp:
                result[nid] = new_cid

        return result

    def community_cohesion_score(self, communities: dict[str, int] = None) -> dict[int, float]:
        """Compute a cohesion score for each community.

        Cohesion = internal_edge_density × avg_internal_weight × size_factor.
        Higher = more tightly-knit community.

        Args:
            communities: {node_id: community_id}. If None, auto-detects.

        Returns:
            {community_id: score 0..1}.
        """
        if communities is None:
            communities = self.detect_communities_leiden()

        if not communities:
            return {}

        edges = self.conn.execute(
            "SELECT source, target, weight FROM edges").fetchall()

        # Group nodes by community
        comm_nodes: dict[int, set[str]] = {}
        for nid, cid in communities.items():
            comm_nodes.setdefault(cid, set()).add(nid)

        # Count internal edges and weights per community
        internal_edges: dict[int, float] = defaultdict(float)
        internal_weight: dict[int, float] = defaultdict(float)
        for e in edges:
            s, t, w = str(e["source"]), str(e["target"]), float(e["weight"] or 1.0)
            if communities.get(s) == communities.get(t) and s != t:
                cid = communities[s]
                internal_edges[cid] += 1
                internal_weight[cid] += w

        scores: dict[int, float] = {}
        for cid, members in comm_nodes.items():
            n = len(members)
            if n <= 1:
                scores[cid] = 0.0
                continue
            max_edges = n * (n - 1) / 2
            density = internal_edges.get(cid, 0.0) / max_edges if max_edges > 0 else 0.0
            avg_w = (internal_weight.get(cid, 0.0) / internal_edges.get(cid, 1.0))
            # Normalize avg_w to 0..1 (assume weights typically 0..2)
            avg_w_norm = min(avg_w / 2.0, 1.0)
            # Size factor: log-scaled, rewards larger cohesive groups
            import math
            size_factor = math.log(n + 1) / math.log(21) if n <= 20 else 1.0
            scores[cid] = round(density * avg_w_norm * size_factor, 4)

        return scores

    @staticmethod
    def _compute_modularity(adj: dict, degree: dict, comm: dict,
                            m2: float, resolution: float) -> float:
        """Compute modularity Q for a given community assignment."""
        q = 0.0
        for cid in set(comm.values()):
            nodes_in = [n for n, c in comm.items() if c == cid]
            in_w = sum(adj.get(n, {}).get(n2, 0.0)
                       for i, n in enumerate(nodes_in)
                       for n2 in nodes_in[i + 1:]) * 2.0
            tot_deg = sum(degree.get(n, 0.0) for n in nodes_in)
            q += (in_w / m2) - resolution * (tot_deg / m2) ** 2
        return q

    def lazy_community_detect(self, seed_nodes: list[str], hops: int = 1,
                             resolution: float = 1.0) -> dict:
        """LazyGraphRAG-style community detection around seed nodes only.

        Instead of running full Leiden on the entire graph, this extracts a
        subgraph around the seed nodes (BFS to *hops* levels), then runs
        community detection only on that subgraph.  Dramatically cheaper for
        large graphs where only a local region is relevant (ICLR 2026
        LazyGraphRAG: ~1000× cost reduction vs full GraphRAG).

        Args:
            seed_nodes: node IDs to start BFS expansion from.
            hops: BFS depth (1 = direct neighbours, 2 = neighbours-of-neighbours).
            resolution: Leiden γ parameter controlling community granularity.

        Returns:
            dict with keys:
              - communities: {node_id: community_id}
              - num_communities: int
              - modularity: float (on the subgraph)
              - subgraph_size: int (number of nodes examined)
              - seed_coverage: float (fraction of seeds that found communities)
        """
        import math

        # --- 1. BFS expansion from seeds (only seeds that exist) ---
        visited: set[str] = set()
        existing_ids = {row[0] for row in self.conn.execute(
            "SELECT id FROM nodes").fetchall()}
        frontier = set(n for n in seed_nodes if n in existing_ids)
        for _ in range(hops + 1):
            next_frontier = set()
            for nid in frontier:
                if nid in visited:
                    continue
                visited.add(nid)
                # Get neighbours from DB
                rows = self.conn.execute(
                    "SELECT target FROM edges WHERE source = ?"
                    " UNION "
                    "SELECT source FROM edges WHERE target = ?",
                    (nid, nid)).fetchall()
                for r in rows:
                    nb = str(r[0]) if not isinstance(r[0], str) else r[0]
                    if nb not in visited:
                        next_frontier.add(nb)
            frontier = next_frontier
            if not frontier:
                break

        if not visited:
            return {"communities": {}, "num_communities": 0, "modularity": 0.0,
                    "subgraph_size": 0, "seed_coverage": 0.0}

        # --- 2. Build adjacency for subgraph ---
        visited_list = list(visited)
        visited_set = set(visited)
        placeholders = ",".join("?" * len(visited_list))
        rows = self.conn.execute(
            f"SELECT source, target, weight FROM edges WHERE source IN ({placeholders}) "
            f"AND target IN ({placeholders})",
            visited_list + visited_list).fetchall()

        adj: dict[str, dict[str, float]] = defaultdict(dict)
        degree: dict[str, float] = defaultdict(float)
        total_w = 0.0
        for r in rows:
            s, t, w = str(r["source"]), str(r["target"]), float(r["weight"] or 1.0)
            adj[s][t] = adj[s].get(t, 0.0) + w
            adj[t][s] = adj[t].get(s, 0.0) + w
            degree[s] += w
            degree[t] += w
            total_w += w

        m2 = total_w * 2.0 if total_w > 0 else 1.0

        # --- 3. Label initialisation (each node its own community) ---
        comm = {n: i for i, n in enumerate(visited_list)}

        # --- 4. Fast local move (Leiden-inspired) ---
        # Randomize node order each iteration to avoid cascading on
        # symmetric graphs (rings, cliques).  Standard Louvain/Leiden
        # practice — without this, fixed order causes label waves on
        # rings that never converge to a good partition.
        import random as _rnd
        _rng = _rnd.Random(42)

        improved = True
        iterations = 0
        max_iterations = 15
        while improved and iterations < max_iterations:
            improved = False
            iterations += 1
            _order = visited_list[:]
            _rng.shuffle(_order)
            for nid in _order:
                k_i = degree.get(nid, 0.0)
                if k_i == 0:
                    continue

                # Count links to each community
                comm_links: dict[int, float] = defaultdict(float)
                for nb, w in adj.get(nid, {}).items():
                    if nb in comm:
                        comm_links[comm[nb]] += w

                best_comm = comm[nid]
                best_gain = 0.0

                # Community degree
                comm_degree: dict[int, float] = defaultdict(float)
                for n2, c2 in comm.items():
                    comm_degree[c2] += degree.get(n2, 0.0)

                for cid, link_w in comm_links.items():
                    if cid == comm[nid]:
                        continue
                    # ΔQ = 2*(link_w - γ*k_i*σ_c/(2m))
                    gain = 2.0 * (link_w - resolution * k_i * comm_degree[cid] / m2)
                    if gain > best_gain:
                        best_gain = gain
                        best_comm = cid

                if best_comm != comm[nid]:
                    comm[nid] = best_comm
                    improved = True

        # --- 5. Compute modularity on subgraph ---
        q = self._compute_modularity(adj, degree, comm, m2, resolution)

        # Fallback: if the partition is worse than a single community,
        # merge everything into one (connected graphs always yield Q ≥ 0).
        if q < 0 and len(visited_list) > 1:
            single_comm = {n: 0 for n in visited_list}
            q_single = self._compute_modularity(
                adj, degree, single_comm, m2, resolution)
            if q_single >= q:
                comm = single_comm
                q = q_single

        # Remap community IDs to 0..k-1
        unique = sorted(set(comm.values()))
        remap = {old: new for new, old in enumerate(unique)}
        comm = {n: remap[c] for n, c in comm.items()}

        seeds_found = sum(1 for s in seed_nodes if s in comm)

        return {
            "communities": comm,
            "num_communities": len(unique),
            "modularity": round(q, 4),
            "subgraph_size": len(visited_list),
            "seed_coverage": round(seeds_found / len(seed_nodes), 4) if seed_nodes else 0.0,
        }

    def community_summary(self, communities: dict = None, algorithm: str = "lp") -> list[dict]:
        """Summarize detected communities with key metrics.

        Args:
            communities: pre-computed {label: [node_ids]} dict. If None, auto-detects.
            algorithm: "lp" for label propagation, "greedy" for greedy modularity.

        Returns list of dicts with: id, size, top_members, density, top_tags, avg_weight.
        """
        if communities is None:
            if algorithm == "leiden":
                comm_map = self.detect_communities_leiden()
                communities = {}
                for nid, cid in comm_map.items():
                    communities.setdefault(cid, []).append(nid)
            elif algorithm == "greedy":
                comm_map = self.community_detection_greedy()
                communities = {}
                for nid, cid in comm_map.items():
                    communities.setdefault(cid, []).append(nid)
            else:
                communities = self.community_detect()
        if not communities:
            return []
        results = []
        for cid, node_ids in communities.items():
            if not node_ids:
                continue
            placeholders = ",".join("?" * len(node_ids))
            rows = self.conn.execute(
                f"SELECT id, label, kind, weight, tags FROM nodes WHERE id IN ({placeholders})",
                node_ids
            ).fetchall()
            # Internal edges
            edge_count = self.conn.execute(
                f"SELECT COUNT(*) as c FROM edges WHERE source IN ({placeholders}) AND target IN ({placeholders})",
                node_ids + node_ids
            ).fetchone()["c"]
            # Density: actual / max possible
            n = len(node_ids)
            max_edges = n * (n - 1)
            density = edge_count / max_edges if max_edges > 0 else 0.0
            # Top members by weight
            sorted_rows = sorted(rows, key=lambda r: r["weight"], reverse=True)
            top_members = [
                {"id": r["id"], "label": r["label"], "weight": r["weight"]}
                for r in sorted_rows[:5]
            ]
            # Tag aggregation
            tag_freq = {}
            for r in rows:
                for tag in json.loads(r["tags"]):
                    tag_freq[tag] = tag_freq.get(tag, 0) + 1
            top_tags = sorted(tag_freq.items(), key=lambda x: x[1], reverse=True)[:5]
            # Kind distribution
            kind_counts = {}
            for r in rows:
                kind_counts[r["kind"]] = kind_counts.get(r["kind"], 0) + 1
            avg_weight = sum(r["weight"] for r in rows) / len(rows)
            results.append({
                "id": cid,
                "size": n,
                "top_members": top_members,
                "internal_edges": edge_count,
                "density": round(density, 4),
                "top_tags": top_tags,
                "kinds": kind_counts,
                "avg_weight": round(avg_weight, 4),
            })
        results.sort(key=lambda x: x["size"], reverse=True)
        return results

    def community_fit_scores(self, communities: dict[str, int] = None) -> dict[str, float]:
        """Score how well each node fits its assigned community.

        For each node, computes the ratio of internal edges (to same-community
        neighbours) vs total edges.  A score near 1.0 means the node is deeply
        embedded in its community; near 0.0 means it's a bridge or outlier.

        Args:
            communities: {node_id: community_id}. If None, auto-detects via Leiden.

        Returns:
            {node_id: fit_score} where fit_score ∈ [0.0, 1.0].
        """
        if communities is None:
            communities = self.detect_communities_leiden()
        if not communities:
            return {}

        edges = self.conn.execute(
            "SELECT source, target FROM edges").fetchall()
        internal: dict[str, int] = defaultdict(int)
        external: dict[str, int] = defaultdict(int)

        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            cs = communities.get(s)
            ct = communities.get(t)
            if cs is not None and ct is not None:
                if cs == ct:
                    internal[s] += 1
                    internal[t] += 1
                else:
                    external[s] += 1
                    external[t] += 1
            elif s in communities:
                external[s] += 1
            elif t in communities:
                external[t] += 1

        scores = {}
        for nid in communities:
            total = internal[nid] + external[nid]
            scores[nid] = round(internal[nid] / total, 4) if total > 0 else 0.0
        return scores

    def bridge_nodes(self, communities: dict[str, int] = None,
                     min_cross_edges: int = 2) -> list[dict]:
        """Find nodes that bridge multiple communities.

        Bridge nodes have edges to members of different communities.  These are
        structurally important for information flow and cross-cutting themes in
        Agent memory graphs.

        Args:
            communities: {node_id: community_id}. If None, auto-detects via Leiden.
            min_cross_edges: minimum inter-community edges to qualify as a bridge.

        Returns:
            list of dicts sorted by cross-community edge count:
              [{node_id, label, community, cross_edges, cross_communities}]
        """
        if communities is None:
            communities = self.detect_communities_leiden()
        if not communities:
            return []

        edges = self.conn.execute(
            "SELECT source, target FROM edges").fetchall()

        cross_count: dict[str, int] = defaultdict(int)
        cross_comms: dict[str, set] = defaultdict(set)

        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            cs = communities.get(s)
            ct = communities.get(t)
            if cs is not None and ct is not None and cs != ct:
                cross_count[s] += 1
                cross_count[t] += 1
                cross_comms[s].add(ct)
                cross_comms[t].add(cs)

        # Filter and enrich
        bridges = []
        for nid, cnt in cross_count.items():
            if cnt >= min_cross_edges:
                row = self.conn.execute(
                    "SELECT label FROM nodes WHERE id = ?", (nid,)).fetchone()
                bridges.append({
                    "node_id": nid,
                    "label": row["label"] if row else "",
                    "community": communities[nid],
                    "cross_edges": cnt,
                    "cross_communities": sorted(cross_comms[nid]),
                })

        bridges.sort(key=lambda x: x["cross_edges"], reverse=True)
        return bridges

    def community_outliers(self, communities: dict[str, int] = None,
                           threshold: float = 0.2) -> list[dict]:
        """Find nodes with low community fit scores (potential misassignments).

        These nodes might be better suited in a different community or might
        represent cross-cutting concepts that don't belong to any single group.

        Args:
            communities: {node_id: community_id}. If None, auto-detects via Leiden.
            threshold: fit score below this → outlier (default 0.2).

        Returns:
            list of dicts: [{node_id, label, community, fit_score, degree}]
        """
        scores = self.community_fit_scores(communities)
        if not scores:
            return []

        edges = self.conn.execute(
            "SELECT source FROM edges").fetchall()
        degree = defaultdict(int)
        for e in edges:
            degree[str(e["source"])] += 1

        outliers = []
        for nid, score in scores.items():
            if score < threshold and degree[nid] > 0:
                row = self.conn.execute(
                    "SELECT label FROM nodes WHERE id = ?", (nid,)).fetchone()
                comm = communities.get(nid) if communities else None
                outliers.append({
                    "node_id": nid,
                    "label": row["label"] if row else "",
                    "community": comm,
                    "fit_score": score,
                    "degree": degree[nid],
                })

        outliers.sort(key=lambda x: x["fit_score"])
        return outliers

    def node_roles(self, hub_threshold: float = 0.7, authority_threshold: float = 0.7) -> dict[str, str]:
        """Classify each node's structural role: hub, authority, bridge, isolated, or member.

        - hub: high out-degree (sources many edges)
        - authority: high in-degree (target of many edges)
        - bridge: high betweenness relative to others
        - isolated: degree 0
        - member: everything else

        Returns {node_id: role}.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return {}
        node_ids = [r["id"] for r in rows]
        # Compute in/out degrees
        out_deg = {}
        in_deg = {}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            out_deg[r["source"]] = out_deg.get(r["source"], 0) + 1
            in_deg[r["target"]] = in_deg.get(r["target"], 0) + 1
        if not out_deg:
            return {nid: "isolated" for nid in node_ids}
        max_out = max(out_deg.values()) if out_deg else 1
        max_in = max(in_deg.values()) if in_deg else 1
        # Compute approximate betweenness for bridge detection
        bc = self.betweenness_centrality_approx(samples=min(20, len(node_ids)))
        max_bc = max(bc.values()) if bc and max(bc.values()) > 0 else 1
        roles = {}
        for nid in node_ids:
            od = out_deg.get(nid, 0)
            idg = in_deg.get(nid, 0)
            bc_score = bc.get(nid, 0)
            if od == 0 and idg == 0:
                roles[nid] = "isolated"
            elif od / max_out >= hub_threshold:
                roles[nid] = "hub"
            elif idg / max_in >= authority_threshold:
                roles[nid] = "authority"
            elif max_bc > 0 and bc_score / max_bc >= 0.6:
                roles[nid] = "bridge"
            else:
                roles[nid] = "member"
        return roles

    def role_summary(self) -> dict[str, int]:
        """Count nodes by role. Returns {role: count}."""
        roles = self.node_roles()
        summary = {}
        for role in roles.values():
            summary[role] = summary.get(role, 0) + 1
        return summary

    def betweenness_centrality_approx(self, samples: int = 20) -> dict[str, float]:
        """近似介数中心性（基于采样 Brandes 算法）。

        对大图提供 O(samples * V) 近似而非 O(V^3) 精确计算。
        """
        nodes = [str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        if not nodes:
            return {}
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        adj: dict[str, list[str]] = {nid: [] for nid in nodes}
        node_set = set(nodes)
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in node_set:
                adj[s].append(t)
            if t in node_set:
                adj[t].append(s)

        bc = {nid: 0.0 for nid in nodes}
        import random
        sample = nodes if len(nodes) <= samples else random.sample(nodes, samples)

        for src in sample:
            # BFS with dependency accumulation (Brandes)
            stack = []
            pred = {nid: [] for nid in nodes}
            sigma = {nid: 0 for nid in nodes}
            sigma[src] = 1
            dist = {nid: -1 for nid in nodes}
            dist[src] = 0
            queue = [src]
            while queue:
                v = queue.pop(0)
                stack.append(v)
                for w in adj[v]:
                    if dist[w] < 0:
                        queue.append(w)
                        dist[w] = dist[v] + 1
                    if dist[w] == dist[v] + 1:
                        sigma[w] += sigma[v]
                        pred[w].append(v)
            delta = {nid: 0.0 for nid in nodes}
            while stack:
                w = stack.pop()
                for v in pred[w]:
                    delta[v] += (sigma[v] / sigma[w]) * (1 + delta[w])
                if w != src:
                    bc[w] += delta[w]

        # Normalize
        n = len(nodes)
        scale = 2 / ((n - 1) * (n - 2)) if n > 2 else 1
        return {nid: round(bc[nid] * scale, 4) for nid in nodes}

    # ── 图变换 ──────────────────────────────────────────

    def reverse_edges(self) -> int:
        """反转所有边的方向。返回受影响的边数。"""
        count = self.conn.execute("SELECT COUNT(*) AS c FROM edges").fetchone()["c"]
        if count == 0:
            return 0
        self.conn.execute("UPDATE edges SET source = target, target = source")
        self.conn.commit()
        return count

    def to_undirected(self) -> int:
        """将有向多重边合并为无向（对称边去重）。

        对于每对 (A→B, B→A) 只保留一条。返回移除的边数。
        """
        edges = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges"
        ).fetchall()
        seen = set()
        to_remove = []
        for e in edges:
            s, t, rel = str(e["source"]), str(e["target"]), e["relation"]
            key = (min(s, t), max(s, t), rel)
            if key in seen:
                to_remove.append((s, t, rel))
            else:
                seen.add(key)
        for s, t, rel in to_remove:
            self.conn.execute(
                "DELETE FROM edges WHERE source=? AND target=? AND relation=?",
                (s, t, rel),
            )
        self.conn.commit()
        return len(to_remove)

    def induce_by_tags(self, tags: list[str], match_all: bool = False) -> dict:
        """按标签筛选节点，返回由这些节点组成的子图。

        match_all=True 时要求所有标签都存在，False 时任一匹配即可。
        """
        nodes = self.conn.execute("SELECT * FROM nodes").fetchall()
        tag_set = set(tags)
        filtered_ids = set()
        for n in nodes:
            node_tags = set(json.loads(n["tags"])) if n["tags"] else set()
            if match_all:
                if tag_set.issubset(node_tags):
                    filtered_ids.add(str(n["id"]))
            else:
                if node_tags & tag_set:
                    filtered_ids.add(str(n["id"]))

        edges = self.conn.execute(
            "SELECT * FROM edges WHERE source IN (%s) AND target IN (%s)"
            % (",".join("?" * len(filtered_ids)), ",".join("?" * len(filtered_ids))),
            list(filtered_ids) + list(filtered_ids),
        ).fetchall()

        return {
            "nodes": [
                {"id": str(r["id"]), "label": r["label"], "kind": r["kind"],
                 "weight": r["weight"], "tags": json.loads(r["tags"]) if r["tags"] else []}
                for r in nodes if str(r["id"]) in filtered_ids
            ],
            "edges": [
                {"source": str(r["source"]), "target": str(r["target"]),
                 "relation": r["relation"], "weight": r["weight"]}
                for r in edges
            ],
        }

    def weight_normalize(self, target_min: float = 0.0, target_max: float = 1.0) -> int:
        """将所有节点权重线性归一化到 [target_min, target_max]。返回更新的节点数。"""
        rows = self.conn.execute("SELECT id, weight FROM nodes").fetchall()
        if not rows:
            return 0
        weights = [r["weight"] for r in rows]
        w_min, w_max = min(weights), max(weights)
        if w_max == w_min:
            # All same weight → set to target_max
            for r in rows:
                self.conn.execute(
                    "UPDATE nodes SET weight=? WHERE id=?",
                    (target_max, str(r["id"])),
                )
        else:
            scale = (target_max - target_min) / (w_max - w_min)
            for r in rows:
                normalized = target_min + (r["weight"] - w_min) * scale
                self.conn.execute(
                    "UPDATE nodes SET weight=? WHERE id=?",
                    (round(normalized, 4), str(r["id"])),
                )
        self.conn.commit()
        return len(rows)

    def pagerank(self, damping: float = 0.85, max_iter: int = 100, tol: float = 1e-6) -> dict[str, float]:
        """PageRank 迭代求解。返回 {node_id: score}。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not nodes:
            return {}
        node_ids = [str(r["id"]) for r in nodes]
        n = len(node_ids)
        rank = {nid: 1.0 / n for nid in node_ids}
        # 构建入边索引
        inbound = {nid: [] for nid in node_ids}
        outbound_count = {nid: 0 for nid in node_ids}
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in outbound_count and t in inbound:
                inbound[t].append(s)
                outbound_count[s] += 1
        for _ in range(max_iter):
            new_rank = {}
            dangling_sum = sum(rank[nid] for nid in node_ids if outbound_count[nid] == 0)
            for nid in node_ids:
                contrib = 0.0
                for src in inbound[nid]:
                    if outbound_count[src] > 0:
                        contrib += rank[src] / outbound_count[src]
                # Dangling node redistribution
                contrib += dangling_sum / n
                new_rank[nid] = (1 - damping) / n + damping * contrib
            diff = sum(abs(new_rank[nid] - rank[nid]) for nid in node_ids)
            rank = new_rank
            if diff < tol:
                break
        return rank

    def eigenvector_centrality(self, max_iter: int = 100, tol: float = 1e-6) -> dict[str, float]:
        """幂迭代法求近似特征向量中心性。返回 {node_id: centrality}。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not nodes:
            return {}
        node_ids = [str(r["id"]) for r in nodes]
        id_set = set(node_ids)
        # 构建邻接表
        adj = {nid: [] for nid in node_ids}
        edges = self.conn.execute("SELECT source, target, weight FROM edges").fetchall()
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            w = e["weight"] if e["weight"] else 1.0
            if s in id_set and t in id_set:
                adj[s].append((t, w))
        v = {nid: 1.0 for nid in node_ids}
        for _ in range(max_iter):
            new_v = {nid: 0.0 for nid in node_ids}
            for src in node_ids:
                for tgt, w in adj[src]:
                    new_v[tgt] += v[src] * w
            norm = sum(val * val for val in new_v.values()) ** 0.5
            if norm == 0:
                break
            new_v = {nid: val / norm for nid, val in new_v.items()}
            diff = sum(abs(new_v[nid] - v[nid]) for nid in node_ids)
            v = new_v
            if diff < tol:
                break
        return v

    def authority_score(self, max_iter: int = 50) -> dict[str, float]:
        """HITS 算法：返回 {node_id: (hub_score, authority_score)} 的 authority 部分。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not nodes:
            return {}
        node_ids = [str(r["id"]) for r in nodes]
        id_set = set(node_ids)
        inbound = {nid: [] for nid in node_ids}
        outbound = {nid: [] for nid in node_ids}
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in id_set and t in id_set:
                inbound[t].append(s)
                outbound[s].append(t)
        hub = {nid: 1.0 for nid in node_ids}
        auth = {nid: 1.0 for nid in node_ids}
        for _ in range(max_iter):
            # Authority update
            new_auth = {nid: sum(hub[s] for s in inbound[nid]) for nid in node_ids}
            a_norm = max(new_auth.values()) or 1
            new_auth = {nid: v / a_norm for nid, v in new_auth.items()}
            # Hub update
            new_hub = {nid: sum(new_auth[t] for t in outbound[nid]) for nid in node_ids}
            h_norm = max(new_hub.values()) or 1
            new_hub = {nid: v / h_norm for nid, v in new_hub.items()}
            if (sum(abs(new_auth[nid] - auth[nid]) for nid in node_ids) +
                sum(abs(new_hub[nid] - hub[nid]) for nid in node_ids)) < 1e-6:
                break
            auth, hub = new_auth, new_hub
        return auth

    def visualize_ascii(self) -> str:
        """简单的 ASCII 可视化。"""
        lines = ["📊 Memory Network:"]
        nodes = self.conn.execute(
            "SELECT * FROM nodes ORDER BY weight DESC LIMIT 15"
        ).fetchall()
        for n in nodes:
            bar = "█" * int(n["weight"] * 10)
            lines.append(f"  [{n['kind']:7s}] {n['label'][:30]:30s} {bar} {n['weight']:.1f}")
            edges = self.conn.execute(
                "SELECT relation, target FROM edges WHERE source=?", (n["id"],)
            ).fetchall()
            for e in edges:
                tgt = self.conn.execute(
                    "SELECT label FROM nodes WHERE id=?", (e["target"],)
                ).fetchone()
                if tgt:
                    lines.append(f"    ──{e['relation']}──▶ {tgt['label'][:25]}")
        return "\n".join(lines)

    def serialize_graphml(self) -> str:
        """导出为 GraphML XML 格式，兼容 Gephi/yEd/Cytoscape 桌面版。"""
        import html
        lines = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<graphml xmlns="http://graphml.graphdrawing.org/xmlns">',
            '  <key id="label" for="node" attr.name="label" attr.type="string"/>',
            '  <key id="kind" for="node" attr.name="kind" attr.type="string"/>',
            '  <key id="weight" for="node" attr.name="weight" attr.type="double"/>',
            '  <key id="relation" for="edge" attr.name="relation" attr.type="string"/>',
            '  <key id="eweight" for="edge" attr.name="weight" attr.type="double"/>',
            '  <graph id="G" edgedefault="directed">',
        ]
        nodes = self.conn.execute("SELECT * FROM nodes").fetchall()
        for n in nodes:
            lines.append(
                f'    <node id="{n["id"]}">'
                f'<data key="label">{html.escape(n["label"])}</data>'
                f'<data key="kind">{html.escape(n["kind"])}</data>'
                f'<data key="weight">{n["weight"]}</data>'
                '</node>'
            )
        edges = self.conn.execute("SELECT * FROM edges").fetchall()
        for i, e in enumerate(edges):
            lines.append(
                f'    <edge id="e{i}" source="{e["source"]}" target="{e["target"]}">'
                f'<data key="relation">{html.escape(e["relation"])}</data>'
                f'<data key="eweight">{e["weight"]}</data>'
                '</edge>'
            )
        lines.append('  </graph>')
        lines.append('</graphml>')
        return '\n'.join(lines)

    def serialize_cytoscape(self) -> dict:
        """导出为 Cytoscape.js JSON 格式，兼容 cytoscape.js 前端可视化。"""
        nodes = self.conn.execute("SELECT * FROM nodes").fetchall()
        edges = self.conn.execute("SELECT * FROM edges").fetchall()
        return {
            "elements": {
                "nodes": [
                    {
                        "data": {
                            "id": str(n["id"]),
                            "label": n["label"],
                            "kind": n["kind"],
                            "weight": n["weight"],
                            "tags": json.loads(n["tags"]) if n["tags"] else [],
                        }
                    }
                    for n in nodes
                ],
                "edges": [
                    {
                        "data": {
                            "id": f"e{i}",
                            "source": str(e["source"]),
                            "target": str(e["target"]),
                            "relation": e["relation"],
                            "weight": e["weight"],
                        }
                    }
                    for i, e in enumerate(edges)
                ],
            }
        }

    def serialize_edgelist(self) -> list[str]:
        """导出为边列表格式 ['source_id target_id weight', ...]。"""
        edges = self.conn.execute("SELECT source, target, weight FROM edges").fetchall()
        return [f"{e['source']} {e['target']} {e['weight']}" for e in edges]

    def k_core(self, k: int) -> list[str]:
        """k-core 分解：返回度数 ≥ k 的节点 ID 列表（迭代删除度数不足的节点）。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        node_ids = {str(r["id"]) for r in nodes}
        if not node_ids:
            return []
        # Build undirected degree map (treat directed as undirected)
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        adj = {nid: set() for nid in node_ids}
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in node_ids and t in node_ids:
                adj[s].add(t)
                adj[t].add(s)
        # Iteratively prune nodes with degree < k
        changed = True
        while changed:
            changed = False
            to_remove = set()
            for nid in node_ids:
                if len(adj[nid]) < k:
                    to_remove.add(nid)
            if to_remove:
                changed = True
                for nid in to_remove:
                    node_ids.discard(nid)
                    for neighbor in adj[nid]:
                        if neighbor in adj:
                            adj[neighbor].discard(nid)
        return sorted(node_ids)

    def core_number(self) -> dict[str, int]:
        """每个节点的 core number（最大 k-core 包含该节点的 k 值）。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        node_ids = {str(r["id"]) for r in nodes}
        if not node_ids:
            return {}
        # Build undirected adjacency
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        adj = {nid: set() for nid in node_ids}
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in node_ids and t in node_ids:
                adj[s].add(t)
                adj[t].add(s)
        # Batagelj-Zaversnik algorithm
        degree = {nid: len(adj[nid]) for nid in node_ids}
        # Sort nodes by degree
        sorted_nodes = sorted(node_ids, key=lambda n: degree[n])
        core = {}
        for nid in sorted_nodes:
            core[nid] = degree[nid]
            for neighbor in adj[nid]:
                if degree[neighbor] > degree[nid]:
                    degree[neighbor] -= 1
        return core

    def count_triangles(self) -> int:
        """统计图中三角形数量（有向边视为无向）。"""
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        node_ids = {str(r["id"]) for r in nodes}
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        adj = {nid: set() for nid in node_ids}
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in node_ids and t in node_ids:
                adj[s].add(t)
                adj[t].add(s)
        count = 0
        id_list = sorted(node_ids)
        id_index = {nid: i for i, nid in enumerate(id_list)}
        for i, u in enumerate(id_list):
            for v in adj[u]:
                if id_index.get(v, -1) > i:
                    for w in adj[v]:
                        if id_index.get(w, -1) > id_index[v]:
                            if w in adj[u]:
                                count += 1
        return count

    def local_triangle_count(self, node_id: str) -> int:
        """单节点参与的三角形数量。"""
        if node_id not in {str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()}:
            return 0
        # Build adjacency for neighborhood
        all_edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        adj = {}
        for e in all_edges:
            s, t = str(e["source"]), str(e["target"])
            adj.setdefault(s, set()).add(t)
            adj.setdefault(t, set()).add(s)
        neighbors = adj.get(node_id, set())
        count = 0
        neighbor_list = list(neighbors)
        for i, v in enumerate(neighbor_list):
            for w in neighbor_list[i+1:]:
                if w in adj.get(v, set()):
                    count += 1
        return count

    def add_tag(self, node_id: str, tag: str) -> bool:
        """Add a single tag to a node. Returns True if added, False if node not found."""
        row = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (node_id,)).fetchone()
        if row is None:
            return False
        tags = json.loads(row["tags"])
        if tag not in tags:
            tags.append(tag)
            self.conn.execute("UPDATE nodes SET tags=? WHERE id=?", (json.dumps(tags), node_id))
            self.conn.commit()
        return True

    def remove_tag(self, node_id: str, tag: str) -> bool:
        """Remove a single tag from a node. Returns True if removed, False if node/tag not found."""
        row = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (node_id,)).fetchone()
        if row is None:
            return False
        tags = json.loads(row["tags"])
        if tag not in tags:
            return False
        tags.remove(tag)
        self.conn.execute("UPDATE nodes SET tags=? WHERE id=?", (json.dumps(tags), node_id))
        self.conn.commit()
        return True

    def has_tag(self, node_id: str, tag: str) -> bool:
        """Check if a node has a specific tag."""
        row = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (node_id,)).fetchone()
        if row is None:
            return False
        return tag in json.loads(row["tags"])

    def tag_cloud(self, limit: int = 0) -> list[dict]:
        """Return tag frequency as sorted list of {tag, count} dicts.

        Args:
            limit: if >0, return only top-N most frequent tags.
        """
        freq = {}
        for r in self.conn.execute("SELECT tags FROM nodes").fetchall():
            for tag in json.loads(r["tags"]):
                freq[tag] = freq.get(tag, 0) + 1
        result = [{"tag": t, "count": c} for t, c in sorted(freq.items(), key=lambda x: -x[1])]
        return result[:limit] if limit > 0 else result

    def tag_stats(self) -> dict:
        """Comprehensive tag statistics."""
        all_tags = self.all_tags()
        cloud = self.tag_cloud()
        total_nodes = self.conn.execute("SELECT COUNT(*) as c FROM nodes").fetchone()["c"]
        tagged_count = self.conn.execute(
            "SELECT COUNT(*) as c FROM nodes WHERE tags != '[]'"
        ).fetchone()["c"]
        total_tag_instances = sum(item["count"] for item in cloud)
        avg_tags = total_tag_instances / total_nodes if total_nodes else 0
        return {
            "unique_tags": len(all_tags),
            "total_tag_instances": total_tag_instances,
            "tagged_nodes": tagged_count,
            "untagged_nodes": total_nodes - tagged_count,
            "avg_tags_per_node": round(avg_tags, 2),
            "most_used": cloud[0] if cloud else None,
            "least_used": cloud[-1] if cloud else None,
        }

    def _bfs_distances(self, node_id: str) -> dict[str, int]:
        """Bidirectional BFS: shortest distances from node_id to all reachable nodes.

        Treats edges as undirected (source↔target), which is the standard for
        graph-analysis metrics (diameter, eccentricity, closeness).
        """
        distances = {node_id: 0}
        queue = [node_id]
        while queue:
            cur = queue.pop(0)
            # Both outgoing (source→target) and incoming (target→source) edges
            rows = self.conn.execute(
                "SELECT target AS nb FROM edges WHERE source=? "
                "UNION "
                "SELECT source AS nb FROM edges WHERE target=?",
                (cur, cur)
            ).fetchall()
            for r in rows:
                nid = str(r["nb"])
                if nid not in distances:
                    distances[nid] = distances[cur] + 1
                    queue.append(nid)
        return distances

    def closeness_centrality(self, node_id: str) -> Optional[float]:
        """接近中心性 (Wasserman-Faust normalization).

        C(v) = reachable² / ((n-1) * sum(distances))

        值越高表示该节点越"中心"。对不可达节点自动惩罚。
        """
        if not self.has_node(node_id):
            return None
        n = self.stats()["nodes"]
        if n <= 1:
            return 0.0
        distances = self._bfs_distances(node_id)
        reachable = len(distances) - 1
        if reachable == 0:
            return 0.0
        total_dist = sum(distances.values())
        return (reachable * reachable) / ((n - 1) * total_dist)

    def graph_diameter(self) -> Optional[int]:
        """图直径 = 所有连通分量中最长最短路径。

        空图返回 None，孤立节点图返回 0。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        diameter = 0
        for row in rows:
            nid = str(row["id"])
            distances = self._bfs_distances(nid)
            if distances:
                local_max = max(distances.values())
                if local_max > diameter:
                    diameter = local_max
        return diameter

    def eccentricity(self, node_id: str) -> Optional[int]:
        """离心率 = 从 node_id 到最远可达节点的距离（双向边）。"""
        if not self.has_node(node_id):
            return None
        distances = self._bfs_distances(node_id)
        return max(distances.values()) if distances else 0

    def graph_radius(self) -> Optional[int]:
        """图半径 = 所有节点离心率的最小值。"""
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        eccentricities = []
        for row in rows:
            ecc = self.eccentricity(str(row["id"]))
            if ecc is not None:
                eccentricities.append(ecc)
        return min(eccentricities) if eccentricities else None

    # ── 连通性分析 ──────────────────────────────────────

    def connected_components(self) -> list[list[str]]:
        """返回所有连通分量（双向边语义）。

        每个分量为节点 ID 列表，按大小降序排列。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return []
        visited: set[str] = set()
        components: list[list[str]] = []
        for row in rows:
            nid = str(row["id"])
            if nid in visited:
                continue
            dists = self._bfs_distances(nid)
            comp = list(dists.keys())
            visited.update(comp)
            components.append(comp)
        components.sort(key=len, reverse=True)
        return components

    def is_connected(self) -> bool:
        """图是否连通（单一连通分量）。空图返回 True，单节点返回 True。"""
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return True
        first = str(rows[0]["id"])
        dists = self._bfs_distances(first)
        return len(dists) == len(rows)

    def average_path_length(self) -> Optional[float]:
        """所有可达节点对的平均最短路径长度（双向边语义）。

        仅计算同一连通分量内的节点对，不对不可达对做无穷惩罚。
        空图返回 None，单节点返回 0.0。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        total_dist = 0
        pair_count = 0
        visited_pairs: set[frozenset] = set()
        for row in rows:
            nid = str(row["id"])
            dists = self._bfs_distances(nid)
            for target, dist in dists.items():
                if target == nid:
                    continue
                pair = frozenset({nid, target})
                if pair in visited_pairs:
                    continue
                visited_pairs.add(pair)
                total_dist += dist
                pair_count += 1
        return round(total_dist / pair_count, 4) if pair_count > 0 else 0.0

    def effective_diameter(self, percentile: float = 0.9) -> Optional[float]:
        """有效直径 — 第 percentile 分位的最短路径长度。

        比最大直径更鲁棒：忽略少数极端长路径。
        例如 percentile=0.9 表示 90% 的可达节点对在此距离以内。

        空图返回 None，无可达对返回 0.0。
        """
        if not 0 < percentile <= 1:
            raise ValueError("percentile must be in (0, 1]")
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        all_dists: list[int] = []
        visited_pairs: set[frozenset] = set()
        for row in rows:
            nid = str(row["id"])
            dists = self._bfs_distances(nid)
            for target, dist in dists.items():
                if target == nid:
                    continue
                pair = frozenset({nid, target})
                if pair in visited_pairs:
                    continue
                visited_pairs.add(pair)
                all_dists.append(dist)
        if not all_dists:
            return 0.0
        all_dists.sort()
        idx = int(len(all_dists) * percentile)
        if idx >= len(all_dists):
            idx = len(all_dists) - 1
        return float(all_dists[idx])

    def harmonic_centrality(self, node_id: str) -> Optional[float]:
        """调和中心性 = Σ(1/distance) 对所有可达节点。

        对不可达节点距离视为无穷大（贡献为 0），
        因此在断开图中比 closeness 更有意义。
        归一化到 [0, 1] 区间：H(v) = Σ(1/d) / (n-1)。
        """
        if not self.has_node(node_id):
            return None
        n = self.stats()["nodes"]
        if n <= 1:
            return 0.0
        distances = self._bfs_distances(node_id)
        score = sum(1.0 / d for _, d in distances.items() if d > 0)
        return round(score / (n - 1), 6)

    def clustering_coefficient(self, node_id: str) -> Optional[float]:
        """局部聚类系数 = 邻居之间实际边数 / 可能边数。

        衡量节点的邻居彼此连接的程度（"朋友的朋友也是朋友"）。
        值域 [0, 1]。度为 0 或 1 时返回 0.0。
        双向边语义。
        """
        if not self.has_node(node_id):
            return None
        # Get neighbors (bidirectional)
        rows = self.conn.execute(
            "SELECT target AS nb FROM edges WHERE source=? "
            "UNION "
            "SELECT source AS nb FROM edges WHERE target=?",
            (node_id, node_id)
        ).fetchall()
        neighbors = [str(r["nb"]) for r in rows]
        k = len(neighbors)
        if k < 2:
            return 0.0
        # Count edges between neighbors
        neighbor_set = set(neighbors)
        edge_count = 0
        for nb in neighbors:
            nb_rows = self.conn.execute(
                "SELECT target AS nb2 FROM edges WHERE source=? "
                "UNION "
                "SELECT source AS nb2 FROM edges WHERE target=?",
                (nb, nb)
            ).fetchall()
            for r in nb_rows:
                if str(r["nb2"]) in neighbor_set and str(r["nb2"]) != nb:
                    edge_count += 1
        # Each edge counted twice (once from each endpoint)
        actual_edges = edge_count / 2
        possible_edges = k * (k - 1) / 2
        return round(actual_edges / possible_edges, 6)

    def effective_eccentricity(self, node_id: str, percentile: float = 0.9) -> Optional[float]:
        """有效离心率 — 从 node_id 出发，第 percentile 分位的可达距离。

        结合 eccentricity（最大距离）和 effective_diameter（分位数）的思想：
        eccentricity 取绝对最大值，容易受单个离群节点影响；
        effective_eccentricity 取分位数，更鲁棒地描述节点的"可达范围"。

        例如 percentile=0.9 表示 90% 的可达节点在此距离以内。

        Returns:
            float: 分位数距离；节点不存在返回 None；无可达节点返回 0.0。
        """
        if not self.has_node(node_id):
            return None
        if not 0 < percentile <= 1:
            raise ValueError("percentile must be in (0, 1]")
        distances = self._bfs_distances(node_id)
        # Exclude self (distance 0)
        reach_dists = sorted(d for d in distances.values() if d > 0)
        if not reach_dists:
            return 0.0
        idx = int(len(reach_dists) * percentile)
        if idx >= len(reach_dists):
            idx = len(reach_dists) - 1
        return float(reach_dists[idx])

    def global_efficiency(self) -> Optional[float]:
        """全局效率 — 所有节点对效率的平均值。

        效率(v,u) = 1 / distance(v,u)，不可达时效率为 0。
        全局效率 = Σ 1/d(v,u) / (n*(n-1))，归一化到 [0, 1]。

        衡量图中信息流动的整体效率。比 average_path_length 更好地
        处理断开图：断开的节点对贡献 0 而非被忽略或视为无穷。

        References:
            Latora & Marchiori (2001) "Efficient behavior of small-world networks"

        Returns:
            float: 全局效率 [0, 1]；空图返回 None。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        n = len(rows)
        node_ids = [str(r["id"]) for r in rows]
        total_efficiency = 0.0
        for nid in node_ids:
            dists = self._bfs_distances(nid)
            for target, d in dists.items():
                if target != nid and d > 0:
                    total_efficiency += 1.0 / d
        # Normalize by n*(n-1) (ordered pairs, not unordered)
        denom = n * (n - 1)
        return round(total_efficiency / denom, 6) if denom > 0 else 0.0

    def s_metric(self) -> Optional[float]:
        """S-metric — 所有边的端点度数乘积之和。

        S = Σ_{(u,v) ∈ E} deg(u) × deg(v)

        衡量图中 hub-hub 连接的程度。高 S 值意味着高度数节点
        倾向于相互连接（如互联网拓扑）。低 S 值意味着 hub 连接
        的是低度数节点（如星形图）。

        可用于评估图的 "scale-free" 程度和 hub 结构质量。

        References:
            Li et al. (2005) "Towards a Theory of Scale-Free Graphs:
            Definition, Properties, and Implications"

        Returns:
            float: S-metric 值；空图返回 None。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        # Pre-compute degrees
        degrees = {}
        for row in rows:
            nid = str(row["id"])
            degrees[nid] = self.degree(nid)
        # Sum over edges (each edge counted once)
        edge_rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        s = 0
        for er in edge_rows:
            src = str(er["source"])
            tgt = str(er["target"])
            s += degrees.get(src, 0) * degrees.get(tgt, 0)
        return float(s)

    def local_efficiency(self, node_id: str) -> Optional[float]:
        """局部效率 — 节点邻居子图的全局效率。

        对于节点 v，取出其所有直接邻居，计算这些邻居构成的
        子图（不含 v 本身）的全局效率。衡量 v 的邻居在 v 被移除后
        仍能相互通信的程度。

        范围 [0, 1]。高值 = 鲁棒的局部结构（即使 v 消失，
        邻居们仍高度互联）。与 clustering_coefficient 互补：
        后者基于三角形计数，前者基于距离效率。

        References:
            Latora & Marchiori (2001) — "Efficient Behavior of
            Small-World Networks"

        Args:
            node_id: 目标节点 ID

        Returns:
            float: 局部效率值；节点不存在或邻居不足 2 个返回 None。
        """
        node = self.get_node(node_id)
        if node is None:
            return None
        # Get direct neighbors (undirected)
        rows = self.conn.execute(
            "SELECT target AS nb FROM edges WHERE source=? "
            "UNION "
            "SELECT source AS nb FROM edges WHERE target=?",
            (node_id, node_id)
        ).fetchall()
        neighbors = [str(r["nb"]) for r in rows]
        if len(neighbors) < 2:
            return None
        # Standard definition: efficiency among neighbors using paths
        # that do NOT pass through node_id (induced neighborhood subgraph).
        # We temporarily remove node_id, compute BFS distances among
        # neighbors, then restore.
        n_nb = len(neighbors)
        total = 0.0
        # Get edges to temporarily remove
        removed_edges = self.conn.execute(
            "SELECT rowid, source, target, relation, weight FROM edges "
            "WHERE source=? OR target=?",
            (node_id, node_id)
        ).fetchall()
        self.conn.execute("DELETE FROM edges WHERE source=? OR target=?",
                          (node_id, node_id))
        try:
            for nb in neighbors:
                dists = self._bfs_distances(nb)
                for other in neighbors:
                    if other == nb:
                        continue
                    d = dists.get(other)
                    if d and d > 0:
                        total += 1.0 / d
        finally:
            for e in removed_edges:
                self.conn.execute(
                    "INSERT INTO edges (source, target, relation, weight) VALUES (?,?,?,?)",
                    (e["source"], e["target"], e["relation"], e["weight"]))
        return total / (n_nb * (n_nb - 1))

    def wiener_index(self) -> Optional[int]:
        """Wiener 指数 — 所有节点对最短路径长度之和。

        W = Σ_{u<v} d(u,v)

        经典图论不变量 (Wiener 1947)，是 average_path_length 的
        未归一化版本。值越大图越 "分散"。对不可达的节点对，
        按惯例不计入（与 global_efficiency 的处理方式不同）。

        References:
            Wiener, H. (1947) "Structural Determination of
            Paraffin Boiling Points"

        Returns:
            int: Wiener 指数值；空图或单节点返回 None。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        total = 0
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    total += d
        return total

    def hyper_wiener_index(self) -> Optional[int]:
        """Hyper-Wiener index (Randic 1993).

        Extension of the Wiener index that also accounts for **all**
        shortest paths, not just their lengths::

            WW(G) = \u00bd \u00b7 \u03a3_{u<v} [ d(u,v)\u00b2 + d(u,v) ]

        where ``d(u, v)`` is the shortest-path distance.

        For unreachable pairs the contribution is zero (same convention
        as ``wiener_index``).

        Returns:
            Hyper-Wiener index (int), or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        total = 0
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    total += d * d + d
        return total // 2

    def balaban_index(self) -> Optional[float]:
        """Balaban J index (Balaban 1982).

        A distance-based topological descriptor widely used in chemical
        graph theory::

            J = [ m / (m - n + 2) ] \u00b7 \u03a3_{(u,v) \u2208 E} 1 / \u221a(d_u \u00b7 d_v)

        where *m* is the number of edges, *n* the number of nodes, and
        ``d_u`` is the sum of shortest-path distances from *u* to all
        other reachable nodes (the *transmission* of *u*).

        Returns:
            Balaban J index (float), or ``None`` for disconnected graphs
            with ``m \u2264 n - 2`` (undefined cyclomatic number).
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        n = len(rows)
        if n < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]

        # Count edges
        m = self.conn.execute("SELECT COUNT(*) AS c FROM edges").fetchone()["c"]
        if m == 0:
            return 0.0

        cycle_rank = m - n + 2  # cyclomatic number + 1
        if cycle_rank <= 0:
            return None

        # Compute transmissions
        transmission: dict[str, int] = {}
        for nid in node_ids:
            dists = self._bfs_distances(nid)
            transmission[nid] = sum(d for d in dists.values() if d > 0)

        # Sum over edges
        total = 0.0
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for r in edges:
            s, t = r["source"], r["target"]
            ds = transmission.get(s, 0)
            dt = transmission.get(t, 0)
            if ds > 0 and dt > 0:
                total += 1.0 / math.sqrt(ds * dt)

        return (m / cycle_rank) * total

    def randic_index(self) -> Optional[float]:
        """Randić connectivity index (Kier & Hall 1976).

        One of the most cited molecular descriptors::

            R = \u03a3_{(u,v) \u2208 E} 1 / \u221a(d_u \u00b7 d_v)

        where *d_u* is the degree of node *u*.

        **Properties:**
        - Path P\u2099: R \u2192 increases with length, dominated by end-edges
        - Complete K\u2099: R = n/2 (all degrees equal)
        - Cycle C\u2099: R = n/2 (all degrees = 2)
        - Star K_{1,n-1}: R = \u221a(n-1)
        - Adding edges generally *decreases* R (more high-degree nodes)

        Returns:
            Randić index (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        # Build degree map
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += 1.0 / math.sqrt(ds * dt)
        return total if total > 0 else None

    def harary_index(self) -> Optional[float]:
        """Harary index — sum of reciprocal pairwise distances.

        The reciprocal-distance analog of the Wiener index::

            H = \u03a3_{u<v} 1 / d(u, v)

        where ``d(u, v)`` is the shortest-path distance. Unreachable
        pairs contribute zero (same convention as ``wiener_index``).

        **Properties:**
        - Higher H = more "compact" / well-connected graph
        - H \u2264 n(n-1)/2 with equality for complete graphs
        - For K\u2099: H = n(n-1)/2 (all distances = 1)
        - For C\u2084: H = 5 (4 pairs at d=1, 2 pairs at d=2)
        - More sensitive to short distances than Wiener

        References:
            Ivanciuc, T. & Ivanciuc, O. (2000), pl Harary.
            Original: Harary (1969) for digraphs; adapted by
            Plavšić et al. (1993) for molecular graphs.

        Returns:
            Harary index (float), or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        total = 0.0
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    total += 1.0 / d
        return total

    def szeged_index(self) -> Optional[int]:
        """Szeged index — edge-partition-based topological index.

        For each edge (u, v), count nodes closer to u than v (n_u)
        and nodes closer to v than u (n_v), then sum the products::

            Sz(G) = \u03a3_{(u,v) \u2208 E} n_u \u00b7 n_v

        where n_u = |{w : d(w,u) < d(w,v)}| and n_v = |{w : d(w,v) < d(w,u)}|.
        Nodes equidistant to both endpoints contribute to neither count.

        **Properties:**
        - For trees: Sz = Wiener index (Gutman 1994 proved this equivalence)
        - For complete K\u2099: each edge splits remaining n-2 nodes equally,
          so n_u = n_v = (n-2)/2 for n even; Sz = m \u00b7 ((n-2)/2)\u00b2
        - For cycles C\u2099 with even n: n_u = n_v = (n-2)/2 per edge
        - For paths P\u2099: Sz = W (same as Wiener for trees)
        - Adding edges generally increases Sz

        References:
            Gutman, I. (1994). "A formula for the Wiener number of trees
            and its extension to graphs with cycles." Graph Theory Notes
            of New York, 27, 9-15.
            Original: Khadikar, P.V. et al. (1995).

        Returns:
            Szeged index (int), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        # Precompute BFS distances from every node
        all_dists: dict[str, dict[str, int]] = {}
        for nid in node_ids:
            all_dists[nid] = self._bfs_distances(nid)
        total = 0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            n_u = 0  # nodes closer to s (including s itself)
            n_v = 0  # nodes closer to t (including t itself)
            ds_map = all_dists.get(s, {})
            dt_map = all_dists.get(t, {})
            for w in node_ids:
                dw_s = ds_map.get(w)
                dw_t = dt_map.get(w)
                if dw_s is None or dw_t is None:
                    continue  # unreachable, doesn't count
                if dw_s < dw_t:
                    n_u += 1
                elif dw_t < dw_s:
                    n_v += 1
                # equidistant nodes contribute to neither
            total += n_u * n_v
        return total

    def gutman_index(self) -> Optional[int]:
        """Gutman index (Gutman 1994) — degree-weighted Wiener index.

        Sum of degree-product-weighted pairwise distances::

            Gut(G) = \u03a3_{u<v} d_u \u00b7 d_v \u00b7 d(u, v)

        where d_u is the degree of node u and d(u,v) is the shortest-path
        distance. Unreachable pairs contribute zero.

        **Properties:**
        - For regular graphs (all same degree k): Gut = k\u00b2 \u00b7 W
        - For paths P\u2099: endpoints (degree 1) reduce contribution vs Wiener
        - For complete K\u2099: Gut = n(n-1)\u00b2/2 (all degree n-1, all dist 1)
        - For star K_{1,n-1}: Gut = (n-1)\u00b3 + (n-1)(n-2)/2
        - Always \u2265 Wiener index for graphs with min degree \u2265 2

        Relationship to Schultz index (which uses d_u + d_v instead of
        d_u \u00b7 d_v): Gutman tends to penalize low-degree nodes more heavily.

        References:
            Gutman, I. (1994). "Selected properties of the Schultz
            molecular topological index." J. Chem. Inf. Comput. Sci.,
            34, 1087-1089.

        Returns:
            Gutman index (int), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        if edge_count == 0:
            return None
        node_ids = [str(r["id"]) for r in rows]
        # Build degree map
        deg: dict[str, int] = {}
        for nid in node_ids:
            deg[nid] = self.degree(nid)
        total = 0
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    total += deg[nid] * deg[other] * d
        return total

    def szeged_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Szeged edge-partition contributions.

        For each edge (u, v), compute n_u · n_v (the Szeged contribution),
        normalise to p_e = (n_u · n_v) / Sz, then calculate Shannon entropy:

            H_Sz = −Σ p_e · ln(p_e)

        When *normalized* is True the result is divided by ln(m)
        so the output lies in (0, 1].

        **Properties:**
        - Regular graph: all edges have identical partitions → H = 1.0
        - Path P_n: endpoints vs interior edges differ → H < 1.0
        - Star K_{1,k}: all edges identical (hub-leaf) → H = 1.0

        Returns:
            float in (0, ln(m)] or (0, 1], or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        all_dists: dict[str, dict[str, int]] = {}
        for nid in node_ids:
            all_dists[nid] = self._bfs_distances(nid)
        contributions: list[int] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            n_u = n_v = 0
            ds_map = all_dists.get(s, {})
            dt_map = all_dists.get(t, {})
            for w in node_ids:
                dw_s, dw_t = ds_map.get(w), dt_map.get(w)
                if dw_s is None or dw_t is None:
                    continue
                if dw_s < dw_t:
                    n_u += 1
                elif dw_t < dw_s:
                    n_v += 1
            contributions.append(n_u * n_v)
        sz = sum(contributions)
        if sz <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / sz
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def gutman_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Gutman (degree-weighted distance) contributions.

        For each reachable node pair (u, v), compute d_u · d_v · d(u,v),
        normalise to p_uv = contribution / Gut, then Shannon entropy.

        **Properties:**
        - Complete graph K_n: all pairs identical → H = 1.0
        - Path P_n: endpoint-endpoint pairs weight less (low degree)
        - Regular graph: Gut = k²·W, same as Wiener entropy

        Returns:
            float in (0, ln(pairs)] or (0, 1], or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        if edge_count == 0:
            return None
        node_ids = [str(r["id"]) for r in rows]
        deg: dict[str, int] = {nid: self.degree(nid) for nid in node_ids}
        contributions: list[int] = []
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    contributions.append(deg[nid] * deg[other] * d)
        gut = sum(contributions)
        if gut <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / gut
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def schultz_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Schultz (degree-sum-weighted distance) contributions.

        For each reachable pair (u, v), compute (d_u + d_v) · d(u,v),
        normalise, then Shannon entropy.

        **Properties:**
        - Complete graph K_n: uniform → H = 1.0
        - Complementary to Gutman entropy: sum vs product weighting

        Returns:
            float in (0, ln(pairs)] or (0, 1], or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        if edge_count == 0:
            return None
        node_ids = [str(r["id"]) for r in rows]
        deg: dict[str, int] = {nid: self.degree(nid) for nid in node_ids}
        contributions: list[int] = []
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    contributions.append((deg[nid] + deg[other]) * d)
        sch = sum(contributions)
        if sch <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / sch
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def schultz_index(self) -> Optional[int]:
        """Schultz molecular topological index (Schultz 1989).

        Sum of degree-sum-weighted pairwise distances::

            S(G) = \u03a3_{u<v} (d_u + d_v) \u00b7 d(u, v)

        where *d_u* is the degree of node *u* and *d(u, v)* is the
        shortest-path distance. Unreachable pairs contribute zero.

        **Properties:**
        - For regular graphs (all same degree k): S = 2k \u00b7 W
        - For paths P\u2099: S = 2 \u00b7 W + 2 \u00b7 \u03a3 d(u,v)\u00b7(positional correction)
        - For complete K\u2099: S = n(n-1)\u00b2 (all degree n-1, all dist 1, degree-sum=2(n-1))
        - Relationship to Gutman index: Schultz uses d_u + d_v while
          Gutman uses d_u \u00b7 d_v. For regular graphs both reduce to
          a constant multiple of the Wiener index.
        - Schultz \u2264 Gutman when all degrees \u2265 2 (AM-GM inequality:
          d_u + d_v \u2264 d_u \u00b7 d_v for integers \u2265 2)

        References:
            Schultz, H.P. (1989). "Topological organic chemistry. 1.
            Graph theory and topological indices of molecular graphs."
            J. Chem. Inf. Comput. Sci., 29, 227-228.

        Returns:
            Schultz index (int), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        if edge_count == 0:
            return None
        node_ids = [str(r["id"]) for r in rows]
        deg: dict[str, int] = {}
        for nid in node_ids:
            deg[nid] = self.degree(nid)
        total = 0
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    total += (deg[nid] + deg[other]) * d
        return total

    def modified_wiener_index(self, lam: float = -1) -> Optional[float]:
        """Modified Wiener index (Nikoli\u0107, Trinajsti\u0107, Randi\u0107 1994).

        Generalized distance sum with exponent::

            W\u1d65(G) = \u03a3_{u<v} d(u, v)\u1d65

        For *\u03bb* = 1 this reduces to the classic Wiener index.
        For *\u03bb* = -1 (default): inverse-distance weighting,
        emphasising nearby pairs. For *\u03bb* = 2: quadratic distance
        penalty, emphasising far-apart pairs. For *\u03bb* = 3: cubic.

        **Properties:**
        - P\u2099 W\u208b\u2081: decreasing with length, dominated by
          directly-connected pairs (d=1 contributes 1 each)
        - K\u2099 W\u208b\u2081 = n(n-1)/2 (all pairs at d=1, 1\u00b9=1)
        - W\u2082: highlights graph diameter and sparsity
        - For disconnected graphs: unreachable pairs excluded

        References:
            Nikoli\u0107, S., Trinajsti\u0107, N., Randi\u0107, M. (1994).
            "Wiener index revisited." Chem. Phys. Lett., 199, 225-229.

        Args:
            lam: Exponent \u03bb (default -1 for inverse-distance variant).

        Returns:
            Modified Wiener index (float), or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        total = 0.0
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    total += d ** lam
        return total

    def generalized_randic_index(self, alpha: float = -0.5) -> Optional[float]:
        """Generalized Randić index R_α (Bollobás & Erdős 1998).

        The connectance index with configurable exponent::

            R_α = Σ_{(u,v) ∈ E} (d_u · d_v)^α

        For *α* = -1/2 (default) this reduces to the classic Randić
        index (``randic_index()``).  Other useful values:

        - *α* = -1:  R_{-1} = Σ 1/(d_u · d_v)  (sum of reciprocal degree products)
        - *α* =  0:  R_0  = m  (number of edges)
        - *α* = +1:  R_{+1} = Σ d_u · d_v  (= second Zagreb M₂ index)
        - *α* = -1/2: classic Randić connectivity index

        **Properties:**
        - K_n (α=-1): n(n-1)/2 · 1/(n-1)² = n/(2(n-1))
        - K_n (α=0):  n(n-1)/2 = m
        - K_n (α=+1): n(n-1)/2 · (n-1)² = n(n-1)³/2
        - C_n (α=-1/2): n/2 (classic Randić)
        - Path P_n (α=-1): dominated by internal edges (d_u·d_v = 4)
        - Star K_{1,k} (α=+1): k · (k·1) = k²

        Args:
            alpha: Exponent α (default -0.5 for classic Randić).

        Returns:
            Generalized Randić index (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += (ds * dt) ** alpha
        return total

    def zagreb_indices(self) -> Optional[dict]:
        """First and second Zagreb indices (Gutman & Trinajstić 1972).

        Two of the oldest and most studied degree-based topological
        descriptors::

            M₁ = Σ_{v ∈ V} d_v² = Σ_{(u,v) ∈ E} (d_u + d_v)
            M₂ = Σ_{(u,v) ∈ E} d_u · d_v

        **Properties:**
        - K_n:  M₁ = n(n-1)²,  M₂ = n(n-1)²·(n-1)/2 ... actually:
          M₁ = n·(n-1)²,  M₂ = n(n-1)³/2
        - Path P_n:  M₁ = (n-2)·4 + 2 = 4n-6,  M₂ = (n-2)·4 + 2 = 4n-6
        - Cycle C_n:  M₁ = 4n,  M₂ = 4n  (all degrees = 2)
        - Star K_{1,k}:  M₁ = k² + k,  M₂ = k²

        Returns:
            dict with keys ``first`` (M₁), ``second`` (M₂),
            ``difference`` (M₁ - M₂), and ``ratio`` (M₂ / M₁).
            ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        # M₁ = Σ d_v²
        m1 = sum(d * d for d in deg.values())
        # M₂ = Σ_{(u,v)∈E} d_u · d_v
        m2 = 0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            m2 += deg.get(s, 0) * deg.get(t, 0)
        return {
            "first": m1,
            "second": m2,
            "difference": m1 - m2,
            "ratio": m2 / m1 if m1 > 0 else 0.0,
        }

    def forgotten_index(self) -> Optional[int]:
        """Forgotten topological index F (Fajtlowicz 1998).

        Also known as the *third Zagreb index*::

            F = Σ_{v ∈ V} d_v³ = Σ_{(u,v) ∈ E} (d_u² + d_v²)

        Introduced alongside M₁ and M₂ in 1972 but largely ignored for
        decades — hence the name "forgotten".  The two forms (vertex
        sum of *d³* and edge sum of *d_u² + d_v²*) are algebraically
        equivalent.

        **Properties:**
        - K_n:  F = n(n-1)³
        - Path P_n (n≥3):  F = (n-2)·8 + 2 = 8n-14  … actually vertex form:
          F = (n-2)·2³ + 2·1³ = 8(n-2)+2 = 8n-14
        - Cycle C_n:  F = n·2³ = 8n
        - Star K_{1,k}:  F = k³ + k·1³ = k³ + k
        - Regular graph (degree *r*):  F = n·r³
        - Relation to M₁:  F ≥ M₁  (since d³ ≥ d² for d ≥ 1)

        Returns:
            Forgotten index value (int), or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        # Vertex form: F = Σ d_v³
        total = sum(d ** 3 for d in deg.values())
        return total

    def abc_index(self) -> Optional[float]:
        """Atom-bond connectivity index (Estrada *et al.* 1998).

        ABC = Σ_{(u,v) ∈ E} √((d_u + d_v - 2) / (d_u · d_v))

        A second-generation degree-based descriptor that correlates
        well with the heat of formation of alkanes.  More discriminating
        than the Randić index for distinguishing graph structures.

        **Properties:**
        - K_n (n≥2):  ABC = m · √(2(n-2)/(n-1)²)  =  n(n-1)/2 · √(2(n-2)/(n-1)²)
        - K_2:  ABC = 1 · √(0/1) = 0   (edge with both degree-1 endpoints)
        - Path P_n (n≥3):  ABC = (n-2)·√(2/4) + 2·√(1/2) = (n-2)/√2 + √2 = (n-1)·√2/1  …
          internal edges contribute √(1/2), endpoint edges contribute √(1/2),
          so ABC(P_n) = (n-1)·√(1/2) for the endpoint edges plus (n-3)·√(1/2) for internal
          wait: endpoint edge (1,2): √((1+2-2)/(1·2)) = √(1/2)
          internal edge (2,2): √((2+2-2)/(2·2)) = √(1/2)
          so every path edge gives √(1/2):  ABC(P_n) = (n-1)/√2
        - Cycle C_n:  every edge (2,2): √(2/4) = √(1/2);  ABC = n/√2
        - Star K_{1,k}:  every edge (1,k): √((1+k-2)/(1·k)) = √((k-1)/k)
          ABC = k · √((k-1)/k)
        - Isolated edges contribute 0 (degree-1 endpoints: d_u+d_v-2 = 0)

        Returns:
            ABC index value (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                numerator = ds + dt - 2
                denominator = ds * dt
                if numerator > 0 and denominator > 0:
                    total += (numerator / denominator) ** 0.5
                # numerator == 0 contributes 0 (isolated edge)
        return total

    def sum_connectivity_index(self) -> Optional[float]:
        """Sum-connectivity index (Zhou & Trinajstić 2009).

        χ_S = Σ_{(u,v) ∈ E} 1 / (d_u + d_v)

        The additive sibling of the Randić index (which uses the
        multiplicative form 1/√(d_u·d_v)).  Designed to complement
        Randić by weighting degree sums rather than products.

        **Properties:**
        - K_n:  χ_S = m / (2(n-1))  =  n(n-1) / (4(n-1))  =  n/4
        - K_2:  χ_S = 1/2
        - Path P_n:  χ_S = (n-3)/4 + 2·(1/3)  for n ≥ 3
          endpoint edges (1,2): 1/3,  internal edges (2,2): 1/4
          P_2: 1/2,  P_3: 2/3,  P_4: 1/3+1/4+1/3 = 11/12
        - Cycle C_n:  χ_S = n · 1/4  =  n/4
        - Star K_{1,k}:  χ_S = k / (k+1)
        - For regular graphs (degree *r*):  χ_S = m / (2r)

        Returns:
            Sum-connectivity index (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += 1.0 / (ds + dt)
        return total

    def ga_index(self) -> Optional[float]:
        """Geometric-Arithmetic index (Dăscălescu *et al.* 2010).

        GA = Σ_{(u,v) ∈ E}  2·√(d_u · d_v) / (d_u + d_v)

        For each edge, GA takes the ratio of the geometric mean to the
        arithmetic mean of endpoint degrees, multiplied by 2 (so that
        GA = 1 for edges with equal endpoint degrees and > 0 always).
        GA ≥ 1 for regular graphs and GA ≤ |E| trivially.

        **Properties:**
        - K_n (n ≥ 2):  GA = n(n-1)/2 · 1 = n(n-1)/2   (all edges (n-1, n-1), ratio = 1)
        - K_2:  GA = 2·√1/2 = 1   (still 1 since d_u = d_v)
        - C_n:  GA = n · 1 = n   (all edges (2,2), ratio = 1)
        - P_n:  GA = (n-3)·1 + 2·2√2/3   for n ≥ 3
          internal edges (2,2) contribute 1, endpoint edges (1,2) contribute 2√2/3
          P_2: GA = 1,  P_3: GA = 2·2√2/3 ≈ 1.8856
        - Star K_{1,k}:  GA = k · 2√k/(k+1)
        - For r-regular graphs:  GA = m   (every term equals 1)

        Returns:
            GA index value (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += 2.0 * (ds * dt) ** 0.5 / (ds + dt)
        return total

    def augmented_zagreb_index(self) -> Optional[float]:
        """Augmented Zagreb index (Furtula *et al.* 2010).

        AZI = Σ_{(u,v) ∈ E}  ( d_u · d_v / (d_u + d_v - 2) )³

        A third-generation degree-based descriptor with very high
        discriminative power.  The cubic exponent amplifies differences
        in degree heterogeneity.  For edges where d_u + d_v = 2 (i.e.
        both endpoints have degree 1, as in K₂), the denominator is 0;
        such edges are skipped (contribute 0) to avoid division by zero.

        **Properties:**
        - K_n (n ≥ 3):  AZI = m · ((n-1)²/(2n-4))³  =  n(n-1)/2 · ((n-1)²/(2(n-2)))³
        - K_2:  AZI = 0   (d_u + d_v - 2 = 0)
        - K_3:  AZI = 3 · (4/2)³ = 3 · 8 = 24
        - C_n:  AZI = n · (4/2)³ = 8n   (all edges (2,2): 2·2/(2+2-2) = 4/2 = 2, cubed = 8)
        - P_n (n ≥ 3):
          internal edges (2,2): 4/2 = 2, cubed = 8
          endpoint edges (1,2): 2/1 = 2, cubed = 8
          AZI = 8(n-1)  for n ≥ 3;  P_2: AZI = 0
        - Star K_{1,k} (k ≥ 2):
          each edge (1,k): k/(k-1), cubed = (k/(k-1))³
          AZI = k · (k/(k-1))³
        - K_{1,1} = K_2: AZI = 0

        Returns:
            AZI value (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            denom = ds + dt - 2
            if denom > 0 and ds > 0 and dt > 0:
                total += (ds * dt / denom) ** 3
        return total

    def harmonic_index(self) -> Optional[float]:
        """Harmonic index (Fajtlowicz 1998).

        H = Σ_{(u,v) ∈ E}  2 / (d_u + d_v)

        A simple degree-based descriptor that is exactly twice the
        sum-connectivity index.  Included for completeness as it appears
        independently in the literature under its own name and has
        slightly different normalisation conventions.

        **Properties:**
        - K_n:  H = n/2   (= 2 · χ_S = 2 · n/4)
        - K_2:  H = 1
        - C_n:  H = n/2
        - P_n (n ≥ 3):  H = (n-3)/2 + 4/3
          internal edges: 2/4 = 1/2,  endpoint edges: 2/3
          P_2: H = 1,  P_3: H = 4/3
        - Star K_{1,k}:  H = 2k/(k+1)
        - For r-regular graphs:  H = m/r
        - Relation:  H = 2 · sum_connectivity_index  always

        Returns:
            Harmonic index (float), or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += 2.0 / (ds + dt)
        return total

    # ------------------------------------------------------------------
    # Cycle 251 – Degree-distribution inequality & redefined indices
    # ------------------------------------------------------------------

    def lorenz_coefficient(self) -> Optional[dict]:
        """Lorenz coefficient / Gini index of degree distribution.

        Measures how unequally degree is distributed across nodes,
        using the classic Lorenz curve / Gini coefficient approach
        applied to the degree sequence.

        **Interpretation:**
        - 0.0 → perfectly equal (regular graph, every node same degree)
        - 1.0 → maximally unequal (star graph: one hub, all others degree 1)
        - < 0.3 → egalitarian
        - > 0.6 → hub-dominated

        Returns a dict with:
        - ``gini``: Gini coefficient in [0, 1]
        - ``lorenz_curve``: list of (cumulative_share_nodes, cumulative_share_degree)
        - ``mean_degree``: average degree
        - ``degree_sequence``: sorted degree list (ascending)

        Returns:
            dict, or ``None`` for < 1 node.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        n = len(rows)
        if n == 0:
            return None
        degrees = sorted(self.degree(str(r["id"])) for r in rows)
        total_degree = sum(degrees)
        if total_degree == 0:
            # All isolated nodes → perfectly equal
            curve = [(i / n, 0.0) for i in range(n + 1)]
            return {"gini": 0.0, "lorenz_curve": curve,
                    "mean_degree": 0.0, "degree_sequence": degrees}
        # Lorenz curve
        cum_nodes = 0.0
        cum_degree = 0.0
        curve = [(0.0, 0.0)]
        for d in degrees:
            cum_nodes += 1
            cum_degree += d
            curve.append((cum_nodes / n, cum_degree / total_degree))
        # Gini coefficient = area between equality line and Lorenz curve
        # G = 1 - 2 * integral(lorenz)
        # Discrete: G = (2 * sum(i * y_i) / (n * sum(y_i))) - (n + 1) / n
        # Or: G = 1 - 2 * trapezoidal_area(lorenz_curve)
        area = 0.0
        for i in range(n):
            # trapezoid between curve[i] and curve[i+1]
            x0, y0 = curve[i]
            x1, y1 = curve[i + 1]
            area += (y0 + y1) * (x1 - x0) / 2.0
        gini = 1.0 - 2.0 * area
        # Clamp to [0, 1] for floating point safety
        gini = max(0.0, min(1.0, gini))
        return {
            "gini": gini,
            "lorenz_curve": curve,
            "mean_degree": total_degree / n,
            "degree_sequence": degrees,
        }

    def redefined_randic_indices(self) -> Optional[dict]:
        """Redefined Randić indices (Randić 2008).

        Three variants of the Randić index using transformed degree ratios:

        - **RD₁** = Σ_{(u,v)∈E} (d_u · d_v / (d_u + d_v))
          This is the inverse of the sum-connectivity term × d_u·d_v.

        - **RD₂** = Σ_{(u,v)∈E} (d_u · d_v / (d_u + d_v))²
          Squared version, emphasising high-degree edges.

        - **RD₃** = Σ_{(u,v)∈E} (d_u · d_v / (d_u + d_v))³
          Cubic version, maximum discrimination.

        **Properties:**
        - For r-regular graph with m edges: RD₁ = m·r/2, RD₂ = m·(r/2)², RD₃ = m·(r/2)³
        - K₂: RD₁=1, RD₂=1, RD₃=1 (but d_u+d_v=2, d_u·d_v=1, ratio=1/2)
          Actually K₂: d_u=d_v=1, ratio = 1·1/(1+1) = 0.5
          RD₁ = 0.5, RD₂ = 0.25, RD₃ = 0.125
        - C_n: d_u=d_v=2, ratio = 4/4 = 1, RD₁=n, RD₂=n, RD₃=n
        - Star K_{1,k}: d_center=k, d_leaf=1, ratio = k/(k+1)
          RD₁ = k·k/(k+1), RD₂ = k·(k/(k+1))², RD₃ = k·(k/(k+1))³

        Returns:
            dict with keys ``rd1``, ``rd2``, ``rd3``, or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        rd1 = rd2 = rd3 = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                ratio = (ds * dt) / (ds + dt)
                rd1 += ratio
                rd2 += ratio * ratio
                rd3 += ratio * ratio * ratio
        return {"rd1": rd1, "rd2": rd2, "rd3": rd3}

    def redefined_zagreb_index(self) -> Optional[float]:
        """Redefined third Zagreb index (ReZM₃).

        ReZM₃ = Σ_{(u,v) ∈ E} (d_u + d_v) · (d_u · d_v)

        This combines additive (M₁-like) and multiplicative (M₂-like)
        degree terms into a single descriptor.

        **Properties:**
        - K_n: ReZM₃ = m · 2(n-1) · (n-1)² = m · 2(n-1)³
          where m = n(n-1)/2
        - K₂: ReZM₃ = 2 · 1 = 2
        - C_n: ReZM₃ = n · 4 · 4 = 16n
        - P₃: ReZM₃ = (edge 1-2: (1+2)·2=6) + (edge 2-3: (2+1)·2=6) = 12
        - Star K_{1,k}: ReZM₃ = k · (k+1) · k = k²(k+1)

        Returns:
            float, or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += (ds + dt) * (ds * dt)
        return total

    # ─── Sombor index family (Gutman 2021) ────────────────────────────

    def sombor_index(self) -> Optional[float]:
        """Sombor index SO.

        SO = Σ_{(u,v) ∈ E} √(d_u² + d_v²)

        Introduced by Gutman (2021), the Sombor index is a recent
        degree-based topological descriptor that has attracted
        significant attention in chemical graph theory.  It measures
        the "geometric mean distance" of degree pairs from the origin
        in the degree-degree plane.

        **Parametric formulas:**
        - K_n (n≥2): SO = m · (n-1)√2 = n(n-1)²√2 / 2
        - C_n: SO = 2n√2
        - P_n (n≥3): SO = 2√5 + (n-3)·2√2
        - K_{1,k}: SO = k√(k²+1)
        - K₂: SO = √2

        Returns:
            float, or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += math.sqrt(ds * ds + dt * dt)
        return total

    def reduced_sombor_index(self) -> Optional[float]:
        """Reduced Sombor index RS.

        RS = Σ_{(u,v) ∈ E} √((d_u - 1)² + (d_v - 1)²)

        The reduced Sombor uses ``d-1`` instead of ``d``, which makes
        it zero for the simple bond K₂ (both degrees = 1 → both
        terms vanish).  This emphasises branching over mere
        connectivity.

        **Parametric formulas:**
        - K_n (n≥3): RS = m · (n-2)√2 = n(n-1)(n-2)√2 / 2
        - C_n: RS = n√2
        - P_n (n≥3): RS = 2 + (n-3)√2
        - K_{1,k} (k≥2): RS = k(k-1)
        - K₂: RS = 0

        Returns:
            float, or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        total = 0.0
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                total += math.sqrt((ds - 1) ** 2 + (dt - 1) ** 2)
        return total

    def sombor_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalized Sombor edge contributions.

        For each edge e = (u, v), compute the Sombor contribution
        s_e = √(d_u² + d_v²), normalise to p_e = s_e / SO, then
        calculate Shannon entropy:

            H_SO = −Σ p_e · ln(p_e)

        When *normalized* is True the result is divided by ln(m)
        (m = edge count) so the output lies in (0, 1].  A value of 1.0
        means every edge contributes equally to the Sombor index
        (e.g. regular graphs or cycles).

        **Properties:**
        - Regular graph K_n: H_SO = ln(m), normalised = 1.0
        - Cycle C_n: H_SO = ln(n), normalised = 1.0
        - Star K_{1,k}: H_SO = ln(k) (all edges identical), normalised = 1.0
        - Path P_n: H_SO < ln(n-1) because interior and boundary edges
          contribute differently

        Returns:
            float in (0, ln m] or (0, 1], or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                contributions.append(math.sqrt(ds * ds + dt * dt))
        if not contributions:
            return None
        so = sum(contributions)
        if so <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / so
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def reduced_sombor_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Reduced Sombor edge contributions.

        For each edge e = (u, v), compute the reduced Sombor contribution
        rs_e = √((d_u−1)² + (d_v−1)²), normalise to p_e = rs_e / RS,
        then calculate Shannon entropy:

            H_RS = −Σ p_e · ln(p_e)

        When *normalized* is True the result is divided by ln(m)
        so the output lies in (0, 1].

        **Special case:** If RS = 0 (only K₂ edges, each contributing
        zero), the entropy is defined as 0.0 — there is no heterogeneity
        to measure.

        **Properties:**
        - K₂: RS = 0, entropy = 0.0 (by convention)
        - Regular graph K_n (n≥3): H_RS = ln(m), normalised = 1.0
        - Cycle C_n: H_RS = ln(n), normalised = 1.0
        - Star K_{1,k} (k≥2): all rs_e = k−1, entropy = ln(k), normalised = 1.0

        Returns:
            float in (0, ln m] or (0, 1], or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                contributions.append(math.sqrt((ds - 1) ** 2 + (dt - 1) ** 2))
        if not contributions:
            return None
        rs = sum(contributions)
        m = len(contributions)
        if rs <= 0:
            # All contributions are zero (only K₂ edges)
            return 0.0 if normalized else 0.0
        entropy = 0.0
        for c in contributions:
            p = c / rs
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def randic_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Randić edge contributions.

        For each edge e = (u, v), compute the Randić contribution
        r_e = 1/√(d_u · d_v), normalise to p_e = r_e / R, then
        calculate Shannon entropy::

            H_R = −Σ p_e · ln(p_e)

        When *normalized* is True the result is divided by ln(m)
        (m = edge count) so the output lies in (0, 1].

        **Properties:**
        - Regular graph K_n: H_R = ln(m), normalised = 1.0
        - Cycle C_n: H_R = ln(n), normalised = 1.0
        - Star K_{1,k}: H_R = ln(k) (all edges identical), normalised = 1.0
        - Path P_n (n≥4): normalised < 1.0 (interior and boundary edges differ)

        The Randić entropy measures how uniformly the "connectivity
        weight" 1/√(d_u·d_v) is distributed across edges.  Unlike the
        Sombor entropy (which uses √(d_u²+d_v²) and emphasises
        high-degree edges), the Randić entropy emphasises
        low-degree edges — a different structural perspective.

        Returns:
            float in (0, ln m] or (0, 1], or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                contributions.append(1.0 / math.sqrt(ds * dt))
        if not contributions:
            return None
        r_total = sum(contributions)
        if r_total <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / r_total
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def zagreb_m1_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Zagreb M₁ edge contributions.

        For each edge e = (u, v), compute the Zagreb M₁ contribution
        z_e = d_u + d_v, normalise to p_e = z_e / M₁_edges, then
        calculate Shannon entropy::

            H_M1 = −Σ p_e · ln(p_e)

        where M₁_edges = Σ_{(u,v)∈E} (d_u + d_v) is the edge-sum form
        of the first Zagreb index (equivalently Σ d_v² over vertices).

        When *normalized* is True the result is divided by ln(m)
        (m = edge count) so the output lies in (0, 1].

        **Properties:**
        - Regular graph K_n: H_M1 = ln(m), normalised = 1.0
        - Cycle C_n: H_M1 = ln(n), normalised = 1.0
        - Star K_{1,k}: H_M1 = ln(k) (all edges (1,k) → same sum), normalised = 1.0
        - Path P_n (n≥4): normalised < 1.0

        The Zagreb M₁ entropy uses the simplest degree sum d_u+d_v as
        edge weight — making it the most intuitive entropy measure.
        Together with Randić entropy (inverse geometric mean) and
        Sombor entropy (Euclidean norm), it forms a trio spanning
        different mathematical perspectives on degree heterogeneity.

        Returns:
            float in (0, ln m] or (0, 1], or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            contributions.append(float(ds + dt))
        if not contributions:
            return None
        z_total = sum(contributions)
        if z_total <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / z_total
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def abc_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Atom-Bond Connectivity edge contributions.

        For each edge e = (u, v), compute the ABC contribution
        a_e = √((d_u + d_v − 2) / (d_u · d_v)), normalise to
        p_e = a_e / ABC, then calculate Shannon entropy::

            H_ABC = −Σ p_e · ln(p_e)

        Edges where d_u + d_v − 2 = 0 (both endpoints degree 1, as in
        K₂) contribute 0 to the ABC index and are **skipped** in the
        entropy calculation (they carry no information).

        When *normalized* is True the result is divided by ln(m)
        (m = number of edges with non-zero contribution) so the output
        lies in (0, 1].

        **Properties:**
        - Regular graph K_n (n≥3): all edges identical → H = ln(m), normalised = 1.0
        - Cycle C_n: all edges (2,2), a_e = √(1/2) → normalised = 1.0
        - Star K_{1,k} (k≥2): all edges (1,k), a_e = √((k−1)/k) → normalised = 1.0
        - Path P_n (n≥4): endpoint edges (1,2) give √(1/2), interior edges (2,2) give √(1/2) → normalised = 1.0
        - Paw graph (K₃ + pendant): edges differ in contribution → normalised < 1.0

        The ABC entropy is unique among degree-based entropies because it
        **filters out** trivial edges (K₂ subgraphs).  This makes it
        especially sensitive to structural complexity beyond simple
        chains.

        Returns:
            float in (0, ln m] or (0, 1], or ``None`` for < 1 non-trivial edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                numerator = ds + dt - 2
                denominator = ds * dt
                if numerator > 0 and denominator > 0:
                    contributions.append((numerator / denominator) ** 0.5)
                # numerator == 0 → K₂ edge, contributes 0, skip
        if not contributions:
            return None
        a_total = sum(contributions)
        if a_total <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / a_total
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def ga_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Geometric-Arithmetic edge contributions.

        For each edge e = (u, v), compute the GA contribution
        g_e = 2·√(d_u · d_v) / (d_u + d_v), normalise to
        p_e = g_e / GA, then calculate Shannon entropy::

            H_GA = −Σ p_e · ln(p_e)

        When *normalized* is True the result is divided by ln(m)
        (m = edge count) so the output lies in (0, 1].

        **Properties:**
        - Regular graph K_n: all edges identical (g_e = 1) → normalised = 1.0
        - Cycle C_n: all edges (2,2), g_e = 1 → normalised = 1.0
        - Star K_{1,k}: all edges (1,k), g_e = 2√k/(k+1) → normalised = 1.0
        - Path P_n (n≥4): endpoint edges (1,2) give 2√2/3 ≈ 0.9428,
          interior edges (2,2) give 1 → normalised < 1.0
        - Paw graph: contributions differ → normalised < 1.0

        The GA entropy measures heterogeneity in the ratio of geometric
        to arithmetic means of endpoint degrees.  Since GA = 1 iff
        d_u = d_v, the GA entropy is high when most edges connect
        equal-degree nodes and low when degree disparity varies across
        edges.  It complements the Randić entropy (which uses the
        product form directly) by taking the ratio perspective.

        Returns:
            float in (0, ln m] or (0, 1], or ``None`` for < 1 edge.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds > 0 and dt > 0:
                contributions.append(2.0 * (ds * dt) ** 0.5 / (ds + dt))
        if not contributions:
            return None
        g_total = sum(contributions)
        if g_total <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / g_total
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    # ── Cycle 281: Entropy profile + Tsallis entropy ──────────────────

    def entropy_profile(self) -> Optional[dict]:
        """Comparative degree-based entropy dashboard.

        Computes all six degree-based Shannon entropies in normalised
        form and returns a structured comparison:

        - ``values``: {index_name: normalised_entropy}
        - ``raw_values``: {index_name: raw_entropy}
        - ``min``, ``max``, ``range``, ``mean``, ``std``: diversity stats
        - ``most_heterogeneous``: index with lowest entropy (most uneven)
        - ``most_homogeneous``: index with highest entropy (most even)
        - ``fingerprint``: tuple of 6 rounded values for graph comparison

        The degree-based indices are: ``sombor``, ``reduced_sombor``,
        ``randic``, ``zagreb_m1``, ``abc``, ``ga``, ``augmented_zagreb``.
        Additional groups: distance-based (``harary``, ``wiener``),
        edge-partition (``szeged``, ``gutman``, ``schultz``),
        centrality (``closeness_vitality``, ``eigenvector_centrality``,
        ``edge_betweenness``), generalized (``tsallis``, ``renyi``).

        Returns ``None`` if fewer than 2 groups produce valid values.
        """
        labels = [
            # Degree-based
            ("sombor", self.sombor_entropy(normalized=True)),
            ("reduced_sombor", self.reduced_sombor_entropy(normalized=True)),
            ("randic", self.randic_entropy(normalized=True)),
            ("zagreb_m1", self.zagreb_m1_entropy(normalized=True)),
            ("abc", self.abc_entropy(normalized=True)),
            ("ga", self.ga_entropy(normalized=True)),
            ("augmented_zagreb", self.augmented_zagreb_entropy(normalized=True)),
            # Distance-based
            ("harary", self.harary_entropy(normalized=True)),
            ("wiener", self.wiener_entropy(normalized=True)),
            # Edge-partition
            ("szeged", self.szeged_entropy(normalized=True)),
            ("gutman", self.gutman_entropy(normalized=True)),
            ("schultz", self.schultz_entropy(normalized=True)),
            # Centrality-based
            ("closeness_vitality", self.closeness_vitality_entropy(normalized=True)),
            ("eigenvector_centrality", self.eigenvector_centrality_entropy(normalized=True)),
            ("edge_betweenness", self.edge_betweenness_entropy(normalized=True)),
        ]
        # Filter out None values (e.g. abc may be None for K₂-only graphs)
        valid = [(name, val) for name, val in labels if val is not None]
        if len(valid) < 2:
            return None
        vals = [v for _, v in valid]
        names = [n for n, _ in valid]
        vmin = min(vals)
        vmax = max(vals)
        vrange = vmax - vmin
        vmean = sum(vals) / len(vals)
        vvar = sum((v - vmean) ** 2 for v in vals) / len(vals)
        vstd = vvar ** 0.5
        # Identify extremes
        most_heterogeneous = names[vals.index(vmin)]
        most_homogeneous = names[vals.index(vmax)]
        # Raw values
        raw = {
            "sombor": self.sombor_entropy(normalized=False),
            "reduced_sombor": self.reduced_sombor_entropy(normalized=False),
            "randic": self.randic_entropy(normalized=False),
            "zagreb_m1": self.zagreb_m1_entropy(normalized=False),
            "abc": self.abc_entropy(normalized=False),
            "ga": self.ga_entropy(normalized=False),
            "augmented_zagreb": self.augmented_zagreb_entropy(normalized=False),
            "harary": self.harary_entropy(normalized=False),
            "wiener": self.wiener_entropy(normalized=False),
            "szeged": self.szeged_entropy(normalized=False),
            "gutman": self.gutman_entropy(normalized=False),
            "schultz": self.schultz_entropy(normalized=False),
            "closeness_vitality": self.closeness_vitality_entropy(normalized=False),
            "eigenvector_centrality": self.eigenvector_centrality_entropy(normalized=False),
            "edge_betweenness": self.edge_betweenness_entropy(normalized=False),
        }
        raw_valid = {k: v for k, v in raw.items() if v is not None}
        # Spectral
        spectral_labels = [
            ("von_neumann", self.von_neumann_entropy(normalized=True)),
        ]
        spectral_valid = [(n, v) for n, v in spectral_labels if v is not None]
        spectral_raw = {
            "von_neumann": self.von_neumann_entropy(normalized=False),
        }
        spectral_raw_valid = {k: v for k, v in spectral_raw.items() if v is not None}
        # Fingerprint: 6 decimal places
        fingerprint = tuple(round(v, 6) for _, v in valid)
        return {
            "values": {n: v for n, v in valid},
            "raw_values": raw_valid,
            "spectral_values": {n: v for n, v in spectral_valid},
            "spectral_raw_values": spectral_raw_valid,
            "min": vmin,
            "max": vmax,
            "range": vrange,
            "mean": vmean,
            "std": vstd,
            "most_heterogeneous": most_heterogeneous,
            "most_homogeneous": most_homogeneous,
            "fingerprint": fingerprint,
            "index_count": len(valid),
            "spectral_count": len(spectral_valid),
        }

    def entropy_explain(self, *, verbose: bool = False) -> dict:
        """Human-readable entropy interpretation with actionable insights.

        Computes a comprehensive entropy profile and generates a natural
        language explanation of what the entropy values mean for the graph's
        structure and health. Designed for agentic consumption — agents can
        use this to reason about their own memory state.

        Interpretation layers:

        1. **Degree diversity** — How evenly distributed are node degrees?
           High = all nodes have similar connectivity. Low = some nodes are hubs.
        2. **Spectral topology** — What does the Laplacian spectrum reveal?
           High = well-connected globally. Low = structural bottlenecks.
        3. **Fingerprint consistency** — Do degree-based and spectral agree?
           Disagreement = complex topology (e.g., star graphs).
        4. **Centrality focus** — Are edges concentrated through few nodes?
           High edge_betweenness entropy = distributed flow. Low = bottleneck nodes.
        5. **Recommendations** — Concrete improvement suggestions.

        Args:
            verbose: If True, include per-index breakdown.

        Returns:
            Dict with ``summary`` (str), ``layers`` (list of dicts with
            ``name``, ``assessment``, ``value``, ``interpretation``),
            ``fingerprint_consistency`` (float, 0-1), ``recommendations``
            (list of str), ``indices_used`` (int).
        """
        stats = self.stats()
        n = stats.get("nodes", 0)
        e = stats.get("edges", 0)
        if n < 3:
            return {
                "summary": f"Graph too small ({n} nodes) for meaningful entropy analysis.",
                "layers": [],
                "fingerprint_consistency": None,
                "recommendations": ["Add more nodes and edges first."],
                "indices_used": 0,
            }

        profile = self.entropy_profile()
        layers = []
        recs = []

        # --- Layer 1: Degree diversity ---
        degree_vals = profile.get("values", {})
        sombor = degree_vals.get("sombor")
        randic = degree_vals.get("randic")
        deg_mean = profile.get("mean")
        deg_std = profile.get("std")

        if sombor is not None:
            if sombor > 0.9:
                assessment = "uniform"
                interp = "Nodes have very similar connectivity — a regular, well-balanced graph."
            elif sombor > 0.7:
                assessment = "balanced"
                interp = "Nodes have moderately diverse connectivity — a healthy, organic structure."
            elif sombor > 0.4:
                assessment = "heterogeneous"
                interp = "Some nodes are hubs with many connections while others are peripheral."
            else:
                assessment = "concentrated"
                interp = "Connectivity is heavily concentrated in a few dominant nodes."
                recs.append("Consider distributing connections more evenly to reduce single-point dependency.")
            layers.append({
                "name": "degree_diversity",
                "metric": "sombor_entropy",
                "value": sombor,
                "assessment": assessment,
                "interpretation": interp,
            })

        # --- Layer 2: Spectral topology ---
        spectral = profile.get("spectral_values", {})
        vn = spectral.get("von_neumann")

        if vn is not None:
            # Von Neumann: high = well-connected, low = fragmented
            if vn > 0.8:
                assessment = "healthy"
                interp = "Laplacian spectrum shows a well-connected global topology."
            elif vn > 0.5:
                assessment = "moderate"
                interp = "Moderate global connectivity. Some structural bottlenecks may exist."
            else:
                assessment = "bottlenecked"
                interp = "Low spectral entropy indicates structural bottlenecks or fragmentation."
                recs.append("Add cross-community edges to improve global connectivity.")
            layers.append({
                "name": "spectral_topology",
                "metric": "von_neumann_entropy",
                "value": vn,
                "assessment": assessment,
                "interpretation": interp,
            })

        # --- Layer 3: Fingerprint consistency ---
        fingerprint_vals = [v for _, v in degree_vals.items() if v is not None]
        if fingerprint_vals and vn is not None:
            fp_mean = sum(fingerprint_vals) / len(fingerprint_vals)
            consistency = 1.0 - min(1.0, abs(fp_mean - vn) * 2)
            if consistency > 0.85:
                interp = "Degree-based and spectral entropy agree — topology is straightforward."
            elif consistency > 0.6:
                interp = "Degree and spectral entropy diverge — complex topology with non-trivial structure."
            else:
                interp = "Strong disagreement between degree and spectral views — graph has unusual topology (e.g., star, bipartite)."
                recs.append("Investigate graph topology: degree-spectral disagreement often indicates hub-dominated or multipartite structures.")
            layers.append({
                "name": "fingerprint_consistency",
                "metric": "degree_spectral_agreement",
                "value": round(consistency, 3),
                "assessment": "consistent" if consistency > 0.85 else "divergent",
                "interpretation": interp,
            })

        # --- Layer 4: Centrality focus ---
        eb = degree_vals.get("edge_betweenness")
        if eb is not None:
            if eb > 0.7:
                assessment = "distributed"
                interp = "Edge flow is well-distributed — no single edge is a critical bottleneck."
            elif eb > 0.4:
                assessment = "moderate"
                interp = "Some edges carry disproportionate flow — potential resilience risk."
            else:
                assessment = "bottlenecked"
                interp = "A few edges are critical for graph connectivity — removal would fragment the graph."
                recs.append("Add redundant paths to reduce critical-edge dependency.")
            layers.append({
                "name": "centrality_focus",
                "metric": "edge_betweenness_entropy",
                "value": eb,
                "assessment": assessment,
                "interpretation": interp,
            })

        # --- Layer 5: Distance-based ---
        wiener = degree_vals.get("wiener")
        if wiener is not None:
            if wiener > 0.7:
                interp = "Path lengths are diverse — good structural richness."
            elif wiener > 0.4:
                interp = "Moderate path diversity."
            else:
                interp = "Path lengths are very uniform — graph may be too regular."
                recs.append("Consider adding long-range connections to increase path diversity.")
            layers.append({
                "name": "path_diversity",
                "metric": "wiener_entropy",
                "value": wiener,
                "assessment": "rich" if wiener > 0.7 else "uniform",
                "interpretation": interp,
            })

        # --- Summary ---
        if layers:
            primary = layers[0] if layers else {}
            summary_parts = [f"Graph ({n} nodes, {e} edges)"]
            for l in layers[:3]:
                summary_parts.append(f"{l['name']}: {l['assessment']} ({l['value']:.3f})")
            summary = ". ".join(summary_parts) + "."
        else:
            summary = f"Graph ({n} nodes, {e} edges) — insufficient entropy data for interpretation."

        if not recs:
            recs.append("Graph entropy profile looks healthy. Continue adding nodes and edges as needed.")

        result = {
            "summary": summary,
            "layers": layers,
            "fingerprint_consistency": round(layers[2]["value"], 3) if len(layers) > 2 else None,
            "recommendations": recs,
            "indices_used": len(layers),
        }
        if verbose:
            result["profile"] = profile
        return result

    def graph_digest(self, *, include_content: bool = False,
                       include_weights: bool = True,
                       include_temporal: bool = False) -> str:
        """Content-addressed integrity hash of the graph.

        Computes a SHA-256 hash from a canonical serialization of the
        graph structure. Enables detecting tampering, comparing snapshots,
        and deduplication.

        The canonical representation sorts all nodes and edges to ensure
        deterministic ordering regardless of insertion order.

        Args:
            include_content: Include node labels/content in the hash.
                When False, only structural identity (IDs) is hashed.
            include_weights: Include edge weights in the hash.
            include_temporal: Include created timestamps in the hash.

        Returns:
            Hex-encoded SHA-256 digest string (64 chars).
        """
        import hashlib

        parts = []
        # Nodes: sorted by ID
        node_rows = self.conn.execute(
            "SELECT id, label, created FROM nodes ORDER BY id"
        ).fetchall()
        for row in node_rows:
            if include_content:
                parts.append("N:%s:%s" % (row['id'], row['label']))
            else:
                parts.append("N:%s" % row['id'])

        # Edges: sorted by (source, target, relation)
        edge_rows = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges ORDER BY source, target, relation"
        ).fetchall()
        for row in edge_rows:
            weight_str = (":w=%s" % row['weight']) if include_weights else ""
            parts.append("E:%s:%s:%s%s" % (row['source'], row['target'], row['relation'], weight_str))

        # Temporal metadata (opt-in)
        if include_temporal:
            for row in node_rows:
                if row['created'] is not None:
                    parts.append("T:%s:%s" % (row['id'], row['created']))

        canonical = "\n".join(parts)
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    def copy_graph(self) -> 'MemoryGraph':
        """Deep copy of the entire graph into a new in-memory instance.

        Copies all nodes (with labels, kinds, data, weights, tags),
        and all edges (with relations, weights). Creates a fresh
        SQLite database. The original is completely independent.

        Returns:
            A new MemoryGraph instance with identical content.
        """
        new_mg = MemoryGraph(":memory:")
        # Copy nodes
        node_rows = self.conn.execute(
            "SELECT id, label, kind, data, created, accessed, weight, tags FROM nodes"
        ).fetchall()
        for row in node_rows:
            new_mg.conn.execute(
                "INSERT INTO nodes (id, label, kind, data, created, accessed, weight, tags) VALUES (?,?,?,?,?,?,?,?)",
                (row['id'], row['label'], row['kind'], row['data'], row['created'], row['accessed'], row['weight'], row['tags']),
            )
        # Copy edges (no data column)
        edge_rows = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges"
        ).fetchall()
        for row in edge_rows:
            new_mg.conn.execute(
                "INSERT OR IGNORE INTO edges (source, target, relation, weight) VALUES (?,?,?,?)",
                (row['source'], row['target'], row['relation'], row['weight']),
            )
        new_mg.conn.commit()
        return new_mg

    # ── Cycle 340: Entropy scan comparison ──────────────────────────

    def entropy_scan_compare(self, other: "MemoryGraph",
                              *,
                              index: str = "sombor",
                              ) -> Optional[dict]:
        """Compare two graphs' entropy scan profiles.

        Computes ``entropy_scan()`` on both graphs and produces a
        multi-dimensional comparison:

        - **L2 distance** between fingerprint vectors
        - **Per-α Rényi divergence** — where on the α spectrum the
          two graphs differ most
        - **Shape descriptor delta** — how monotonicity, convexity,
          curve area, and gap differ
        - **Classification**: whether the graphs are "similar" or
          "different" based on fingerprint distance

        **When to use:**
        - Quick graph similarity check without inter-graph computation
        - Track how a graph's entropy profile evolves over time
        - Compare reference graphs for classification

        Args:
            other: The other MemoryGraph to compare against.
            index: degree-based index for edge contributions.

        Returns:
            Dict with keys:
            - ``distance``: float — L2 distance between fingerprints
            - ``per_alpha_divergence``: list of {alpha, abs_diff}
            - ``shape_delta``: dict of descriptor differences
            - ``classification``: "similar" | "different"
            - ``scan1``: result of entropy_scan() on self
            - ``scan2``: result of entropy_scan() on other
            or ``None`` if either graph is too small.
        """
        scan1 = self.entropy_scan(index=index)
        scan2 = other.entropy_scan(index=index)
        if scan1 is None or scan2 is None:
            return None

        fp1 = scan1["fingerprint"]
        fp2 = scan2["fingerprint"]

        # Pad shorter vector with zeros
        n = max(len(fp1), len(fp2))
        fp1_padded = fp1 + [0.0] * (n - len(fp1))
        fp2_padded = fp2 + [0.0] * (n - len(fp2))

        distance = math.sqrt(sum((a - b) ** 2 for a, b in zip(fp1_padded, fp2_padded)))

        # Per-α divergence (uses RAW Rényi values from fingerprint)
        # fingerprint = [shannon, renyi_0, renyi_1, ..., tsalli_0, ..., area, gap, slope]
        renyi_alphas = scan1["renyi"]["alphas"]
        # RAW Rényi values start at index 1 (after shannon), length = len(alphas)
        n_renyi = len(renyi_alphas)
        renyi1 = fp1[1:1 + n_renyi]
        renyi2 = fp2[1:1 + n_renyi]

        per_alpha: list[dict] = []
        for i, alpha in enumerate(renyi_alphas):
            if i < len(renyi1) and i < len(renyi2):
                per_alpha.append({
                    "alpha": alpha,
                    "abs_diff": abs(renyi1[i] - renyi2[i]),
                })

        # Find α with maximum divergence
        max_div_alpha = None
        max_div = 0.0
        for p in per_alpha:
            if p["abs_diff"] > max_div:
                max_div = p["abs_diff"]
                max_div_alpha = p["alpha"]

        # Shape descriptor deltas
        s1, s2 = scan1["shape"], scan2["shape"]
        shape_delta = {
            "area_delta": s1["curve_area"] - s2["curve_area"],
            "gap_delta": s1["max_min_gap"] - s2["max_min_gap"],
            "slope_delta": s1["slope_at_alpha2"] - s2["slope_at_alpha2"],
            "monotonic_match": s1["monotonic"] == s2["monotonic"],
            "convex_match": s1["convex"] == s2["convex"],
        }

        # Classification heuristic
        classification = "similar" if distance < 0.5 else "different"

        return {
            "distance": round(distance, 8),
            "per_alpha_divergence": per_alpha,
            "max_divergence_alpha": max_div_alpha,
            "max_divergence_value": round(max_div, 8),
            "shape_delta": shape_delta,
            "classification": classification,
            "scan1": scan1,
            "scan2": scan2,
        }

    # ── Cycle 342: Entropy scan human-readable summary ───────────────────

    def entropy_scan_summary(self, index: str = "sombor") -> Optional[str]:
        """Generate a human-readable topology summary from entropy scan.

        Uses ``entropy_scan()`` shape descriptors to produce a natural
        language description of the graph's information structure:

        - **Heterogeneity**: uniform vs heterogeneous edge contributions
        - **Curve shape**: monotonic, convex, knee position
        - **Complexity class**: simple (regular/cycle) vs complex (irregular)
        - **Structural insight**: what the entropy profile reveals

        **When to use:**
        - Quick graph topology assessment without visual inspection
        - Logging / debugging graph structure
        - Comparing graphs via natural language

        Args:
            index: degree-based index for edge contributions.

        Returns:
            Multi-line string description, or ``None`` if graph is too small.
        """
        scan = self.entropy_scan(index=index)
        if scan is None:
            return None

        shape = scan["shape"]
        shannon = scan["shannon"]
        gap = shape["max_min_gap"]
        area = shape["curve_area"]
        knee = shape["knee_position"]
        monotonic = shape["monotonic"]
        convex = shape["convex"]
        slope2 = shape["slope_at_alpha2"]

        edge_count = self.conn.execute("SELECT COUNT(*) c FROM edges").fetchone()["c"]
        node_count = self.conn.execute("SELECT COUNT(*) c FROM nodes").fetchone()["c"]

        lines: list[str] = []
        lines.append(f"Graph: {node_count} nodes, {edge_count} edges")
        lines.append(f"Index: {index}")
        lines.append(f"Shannon entropy: {shannon:.4f} (normalized, 1.0 = uniform)")

        # Heterogeneity assessment
        if gap < 0.01:
            lines.append("Edge distribution: UNIFORM (all edges contribute equally)")
        elif gap < 0.1:
            lines.append(f"Edge distribution: SLIGHTLY heterogeneous (gap={gap:.4f})")
        elif gap < 0.5:
            lines.append(f"Edge distribution: MODERATELY heterogeneous (gap={gap:.4f})")
        else:
            lines.append(f"Edge distribution: HIGHLY heterogeneous (gap={gap:.4f})")

        # Curve shape
        shape_parts = []
        if monotonic:
            shape_parts.append("monotonically decreasing")
        else:
            shape_parts.append("non-monotonic")
        if convex:
            shape_parts.append("convex")
        else:
            shape_parts.append("non-convex (has inflection points)")
        lines.append(f"Rényi curve: {', '.join(shape_parts)}")

        if knee is not None:
            lines.append(f"Knee at α={knee:.1f} (transition in information content)")

        lines.append(f"Curve area: {area:.4f}")
        lines.append(f"Slope at α=2: {slope2:.6f}")

        # Complexity classification
        if gap < 0.01 and monotonic:
            lines.append("\nAssessment: SIMPLE topology (regular/cycle/star-like).")
            lines.append("All edges carry similar information weight.")
        elif gap < 0.1:
            lines.append("\nAssessment: NEAR-REGULAR topology with minor variation.")
            lines.append("Edge contributions are mostly uniform with slight heterogeneity.")
        elif gap < 0.5:
            lines.append("\nAssessment: MODERATE complexity.")
            lines.append("Mix of high and low contribution edges suggests community structure.")
        else:
            lines.append("\nAssessment: HIGH complexity.")
            lines.append("Strong heterogeneity indicates hubs, bridges, or multi-scale structure.")

        # Fingerprint info
        fp = scan["fingerprint"]
        lines.append(f"\nFingerprint: {len(fp)} dimensions")
        lines.append(f"  [{', '.join(f'{v:.4f}' for v in fp[:8])}{'...' if len(fp) > 8 else ''}]")

        return "\n".join(lines)

    # ── Cycle 341: BFS depth entropy profile ───────────────────────────

    def entropy_depth_profile(self, node_id: str,
                               *,
                               max_depth: int = 5,
                               index: str = "sombor",
                               ) -> Optional[list[dict]]:
        """Per-layer Rényi entropy profile via BFS expansion from ``node_id``.

        Starting from ``node_id``, expands outward in BFS layers. For each
        layer *h* (0, 1, 2, …), computes:

        - **Nodes** in this layer (the frontier)
        - **Induced edge count** — edges with both endpoints in layers ≤ h
        - **Shannon entropy** of the induced subgraph's edge contribution distribution
        - **Rényi H₂** (α=2 collision entropy)
        - **Layer growth ratio** — frontier_size(h) / frontier_size(h−1)
        - **Cumulative node count** up to layer h

        This is inspired by the SREGK h-layer expansion pattern (arXiv:2501.10549)
        which connects local node entropy to global graph entropy through
        successive neighborhood shells.

        **When to use:**
        - Understand information spread from a single seed node
        - Compare nodes by their entropy reach profile
        - Detect community boundaries (entropy plateau = boundary)
        - Connect ``entropy_contribution(node)`` to global ``entropy_scan()``

        Args:
            node_id: Starting node for BFS expansion.
            max_depth: Maximum BFS layers to expand (default 5).
            index: Degree-based index for edge contributions.

        Returns:
            List of dicts, one per layer (0-indexed):
            ``[{depth, frontier_nodes, cumulative_nodes, induced_edges,
               shannon, renyi_2, growth_ratio}, …]``
            or ``None`` if node doesn't exist or graph has no edges.
        """
        if not self.has_node(node_id):
            return None

        # Check edges exist
        total_edges = self.conn.execute("SELECT COUNT(*) c FROM edges").fetchone()["c"]
        if total_edges == 0:
            return None

        def _induced_entropy(cumulative_nodes: set[str]) -> Optional[dict]:
            """Compute entropy over edges with both endpoints in the node set."""
            if len(cumulative_nodes) < 2:
                return {"shannon": 0.0, "renyi_2": 0.0, "edge_count": 0}
            placeholders = ",".join("?" for _ in cumulative_nodes)
            params = list(cumulative_nodes)
            rows = self.conn.execute(
                f"SELECT source, target FROM edges WHERE source IN ({placeholders}) AND target IN ({placeholders})",
                params + params
            ).fetchall()
            edge_count = len(rows)
            if edge_count == 0:
                return {"shannon": 0.0, "renyi_2": 0.0, "edge_count": 0}

            # Degree-based contributions for induced subgraph
            from collections import Counter
            deg = Counter()
            for r in rows:
                deg[r["source"]] += 1
                deg[r["target"]] += 1

            # Edge contributions via chosen index
            contributions: list[float] = []
            for r in rows:
                d_s = deg[r["source"]]
                d_t = deg[r["target"]]
                if d_s > 0 and d_t > 0:
                    if index == "sombor":
                        contributions.append(math.sqrt(d_s * d_s + d_t * d_t))
                    elif index == "reduced_sombor":
                        contributions.append(math.sqrt((d_s - 1) ** 2 + (d_t - 1) ** 2))
                    elif index == "randic":
                        contributions.append(1.0 / math.sqrt(d_s * d_t))
                    elif index == "zagreb_m1":
                        contributions.append(float(d_s * d_t))
                    elif index == "abc":
                        contributions.append(math.sqrt((d_s + d_t - 2.0) / (d_s * d_t)))
                    elif index == "ga":
                        contributions.append(2.0 * math.sqrt(d_s * d_t) / (d_s + d_t))
                    elif index == "augmented_zagreb":
                        contributions.append((2.0 * math.sqrt(d_s * d_t) / (d_s + d_t)) ** 3)
                    else:
                        raise ValueError(f"Unknown index: {index}")

            total = sum(contributions)
            if total <= 0:
                return {"shannon": 0.0, "renyi_2": 0.0, "edge_count": edge_count}
            probs = [c / total for c in contributions]
            shannon = -sum(p * math.log(p) for p in probs if p > 0)
            s2 = sum(p * p for p in probs)
            renyi_2 = -math.log(s2) if s2 > 0 else 0.0
            return {"shannon": shannon, "renyi_2": renyi_2, "edge_count": edge_count}

        # BFS layer by layer
        visited = {node_id}
        frontier = {node_id}
        profile: list[dict] = []

        for h in range(max_depth + 1):
            # Compute entropy of the induced subgraph up to this layer
            ent = _induced_entropy(visited)

            # Growth ratio
            if h == 0:
                growth = 1.0
            else:
                prev_frontier = profile[h - 1]["frontier_count"]
                growth = len(frontier) / prev_frontier if prev_frontier > 0 else 0.0

            profile.append({
                "depth": h,
                "frontier_nodes": sorted(frontier),
                "frontier_count": len(frontier),
                "cumulative_nodes": len(visited),
                "induced_edges": ent["edge_count"],
                "shannon": round(ent["shannon"], 8),
                "renyi_2": round(ent["renyi_2"], 8),
                "growth_ratio": round(growth, 8),
            })

            # Expand frontier
            next_frontier = set()
            for nid in frontier:
                for r in self.conn.execute(
                    "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
                    (nid, nid)
                ).fetchall():
                    if r[0] not in visited:
                        next_frontier.add(r[0])
            if not next_frontier:
                break
            visited |= next_frontier
            frontier = next_frontier

        return profile

    def entropy_anomaly_detect(self, index: str = "sombor",
                               threshold: float = 2.0) -> Optional[dict]:
        """Detect nodes whose local entropy contribution deviates from the graph average.

        For each node, computes a *local entropy score* based on the
        diversity of its edge contributions (using the chosen degree-based
        index).  Nodes whose score deviates more than *threshold* standard
        deviations from the mean are flagged as anomalies.

        **Anomaly types:**
        - ``"hub"`` — abnormally high degree-diversity (many diverse connections)
        - ``"pendant"`` — abnormally low degree-diversity (homogeneous/isolated)
        - ``"bridge"`` — normal overall but connects to anomalous neighbors

        Useful for finding unusual patterns in agent memory: over-connected
        hubs, isolated clusters, or bridging nodes between communities.

        Args:
            index: degree-based index for edge contribution computation.
            threshold: standard deviations for anomaly cutoff. Default 2.0.

        Returns:
            Dict with:
            - ``mean_score``: float — mean local entropy
            - ``std_score``: float — standard deviation
            - ``threshold``: float
            - ``anomalies``: list of {node_id, label, score, z_score, type}
            - ``total_nodes``: int
            or None if fewer than 3 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 3:
            return None

        # ── Von Neumann spectral branch ──
        if index == "von_neumann":
            sec = self.spectral_entropy_contribution()
            if sec is None:
                return None
            node_scores = sec["contributions"]
        else:
            # Compute per-node local entropy: diversity of edge contributions
            node_scores = {}
            for r in rows:
                nid = r["id"]
                edges = self.edges_of(nid, direction="both")
                if not edges:
                    node_scores[nid] = 0.0
                    continue

                # Compute degree-based contributions for this node's edges
                contributions = []
                deg = self.degree(nid)
                for e in edges:
                    other = e.target if e.source == nid else e.source
                    d_other = self.degree(other)
                    if deg <= 0 or d_other <= 0:
                        continue
                    if index == "sombor":
                        contributions.append(math.sqrt(deg * deg + d_other * d_other))
                    elif index == "randic":
                        contributions.append(1.0 / math.sqrt(deg * d_other))
                    elif index == "zagreb_m1":
                        contributions.append(float(deg + d_other))
                    else:
                        contributions.append(math.sqrt(deg * deg + d_other * d_other))

                if not contributions:
                    node_scores[nid] = 0.0
                    continue

                # Local entropy: Shannon entropy of normalized contributions
                total = sum(contributions)
                if total <= 0:
                    node_scores[nid] = 0.0
                    continue

                probs = [c / total for c in contributions]
                entropy = -sum(p * math.log(p) for p in probs if p > 0)
                node_scores[nid] = entropy

        scores = list(node_scores.values())
        n = len(scores)
        mean_score = sum(scores) / n
        var = sum((s - mean_score) ** 2 for s in scores) / n
        std_score = var ** 0.5

        if std_score == 0:
            # All nodes identical — no anomalies
            return {
                "mean_score": round(mean_score, 8),
                "std_score": 0.0,
                "threshold": threshold,
                "anomalies": [],
                "total_nodes": n,
            }

        anomalies = []
        for nid, score in node_scores.items():
            z_score = (score - mean_score) / std_score
            if abs(z_score) >= threshold:
                node = self.get_node(nid)
                anomaly_type = "hub" if z_score > 0 else "pendant"
                anomalies.append({
                    "node_id": nid,
                    "label": node.label if node else nid,
                    "score": round(score, 8),
                    "z_score": round(z_score, 4),
                    "type": anomaly_type,
                    "degree": self.degree(nid),
                })

        # Sort by absolute z_score descending
        anomalies.sort(key=lambda a: abs(a["z_score"]), reverse=True)

        return {
            "mean_score": round(mean_score, 8),
            "std_score": round(std_score, 8),
            "threshold": threshold,
            "anomalies": anomalies,
            "total_nodes": n,
        }

    def tsallis_entropy(self, q: float = 2.0, normalized: bool = True,
                        index: str = "sombor") -> Optional[float]:
        """Tsallis generalized entropy of degree-based edge contributions.

        For entropic index *q* and edge contributions c_e from a chosen
        degree-based topological index, the Tsallis entropy is::

            S_q = (1 − Σ p_e^q) / (q − 1),   q ≠ 1
            S_1 = −Σ p_e · ln(p_e)            (Shannon)

        When q → 1 the Tsallis entropy converges to the Shannon entropy.
        For q > 1, the entropy is *subextensive* (emphasises dominant
        edge contributions).  For q < 1, it is *superextensive*
        (emphasises rare edge contributions).

        The *index* parameter selects which degree-based contributions
        to use:

        - ``"sombor"`` — √(d_u²+d_v²) contributions
        - ``"reduced_sombor"`` — √((d_u-1)²+(d_v-1)²) contributions
        - ``"randic"`` — 1/√(d_u·d_v) contributions
        - ``"zagreb_m1"`` — (d_u+d_v) contributions
        - ``"abc"`` — √((d_u+d_v−2)/(d_u·d_v)) contributions (K₂ skipped)
        - ``"ga"`` — 2√(d_u·d_v)/(d_u+d_v) contributions
        - ``"augmented_zagreb"`` — (d_u·d_v/(d_u+d_v−2))³ contributions (K₂ skipped)

        Normalisation divides by ln(m)^(2−q) for q ≠ 1 to keep values
        bounded, following the standard Tsallis normalisation for
        discrete distributions.

        **Properties:**
        - For any regular graph: all contributions equal → S_q = (m^(1−q) − 1)/(q−1)·m^(1−q)
        - q = 1 → Shannon entropy (use the dedicated ``*_entropy()`` methods)
        - q = 2 → Collatz/Tsallis: S_2 = 1 − Σ p_e² (a.k.a. Gini-Simpson)
        - q → ∞ → max(p_e) (Berger-Parker index)

        Args:
            q: entropic index (q ≠ 1; use dedicated methods for Shannon).
               Defaults to 2.0.
            normalized: divide by maximum possible entropy for this q.
            index: which degree-based contributions to use.

        Returns:
            float, or ``None`` for < 1 edge.
        """
        if q == 1.0:
            raise ValueError("q=1 is Shannon entropy; use *_entropy() methods instead")
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds <= 0 or dt <= 0:
                continue
            if index == "sombor":
                contributions.append(math.sqrt(ds * ds + dt * dt))
            elif index == "reduced_sombor":
                contributions.append(math.sqrt((ds - 1) ** 2 + (dt - 1) ** 2))
            elif index == "randic":
                contributions.append(1.0 / math.sqrt(ds * dt))
            elif index == "zagreb_m1":
                contributions.append(float(ds + dt))
            elif index == "abc":
                num = ds + dt - 2
                den = ds * dt
                if num > 0 and den > 0:
                    contributions.append(math.sqrt(num / den))
                # K₂ edges skipped
            elif index == "ga":
                contributions.append(2.0 * math.sqrt(ds * dt) / (ds + dt))
            elif index == "augmented_zagreb":
                az_denom = ds + dt - 2
                if az_denom > 0:
                    contributions.append((ds * dt / az_denom) ** 3)
                # K₂ edges skipped
            else:
                raise ValueError(f"unknown index '{index}'; choose from "
                                 f"sombor/reduced_sombor/randic/zagreb_m1/abc/ga/augmented_zagreb")
        if not contributions:
            return None
        total = sum(contributions)
        if total <= 0:
            return None
        m = len(contributions)
        probs = [c / total for c in contributions]
        # Tsallis entropy: S_q = (1 − Σ p^q) / (q − 1)
        sum_pq = sum(p ** q for p in probs)
        tsallis = (1.0 - sum_pq) / (q - 1.0)
        if normalized:
            # Maximum Tsallis entropy for uniform distribution over m items:
            # S_q^max = (1 − m·(1/m)^q) / (q−1) = (m^(1−q) − 1) / (q−1) / m^(1−q)
            # Simplify: S_q^max = (1 − m^(1−q)) / (q−1)
            # Actually: uniform p_e = 1/m for all e
            # Σ p^q = m · (1/m)^q = m^(1−q)
            # S_q^max = (1 − m^(1−q)) / (q − 1)
            s_max = (1.0 - m ** (1.0 - q)) / (q - 1.0)
            if s_max > 0:
                tsallis /= s_max
        return tsallis

    # ── Cycle 288: Rényi entropy + entropy_distance (JSD) ─────────────

    def renyi_entropy(self, alpha: float = 2.0, normalized: bool = True,
                      index: str = "sombor") -> Optional[float]:
        """Rényi generalized entropy of degree-based edge contributions.

        For entropic order *α* and edge contributions c_e from a chosen
        degree-based topological index, the Rényi entropy is::

            H_α = 1/(1−α) · ln( Σ p_e^α ),   α ≠ 1
            H_1 = −Σ p_e · ln(p_e)            (Shannon)

        The Rényi entropy is the other major generalization of Shannon
        entropy (alongside Tsallis).  Key relationships:

        - α → 1: converges to Shannon entropy
        - α = 0: ln(m) (Hartley entropy — counts edges)
        - α = 2: collision entropy = −ln(Σ p_e²)
        - α → ∞: min-entropy = −ln(max(p_e))

        **Rényi vs Tsallis:**

            H_α^Rényi = ln( (α−1)·S_q^Tsallis + 1 ) / (1−α)

        Equivalently: S_q^Tsallis = (exp((1−α)·H_α^Rényi) − 1) / (1−α)

        Both are valid generalizations; Rényi is *extensive* (additive
        for independent systems) while Tsallis is non-extensive.

        The *index* parameter selects which degree-based contributions
        to use (same 7 options as ``tsallis_entropy``).

        Args:
            alpha: entropic order (α ≠ 1; use dedicated methods for Shannon).
               Defaults to 2.0.
            normalized: divide by ln(m) for [0,1] range.
            index: which degree-based contributions to use.

        Returns:
            float ≥ 0, or ``None`` for < 1 edge.
        """
        if alpha == 1.0:
            raise ValueError("alpha=1 is Shannon entropy; use *_entropy() methods instead")
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds <= 0 or dt <= 0:
                continue
            if index == "sombor":
                contributions.append(math.sqrt(ds * ds + dt * dt))
            elif index == "reduced_sombor":
                contributions.append(math.sqrt((ds - 1) ** 2 + (dt - 1) ** 2))
            elif index == "randic":
                contributions.append(1.0 / math.sqrt(ds * dt))
            elif index == "zagreb_m1":
                contributions.append(float(ds + dt))
            elif index == "abc":
                num = ds + dt - 2
                den = ds * dt
                if num > 0 and den > 0:
                    contributions.append(math.sqrt(num / den))
            elif index == "ga":
                contributions.append(2.0 * math.sqrt(ds * dt) / (ds + dt))
            elif index == "augmented_zagreb":
                az_denom = ds + dt - 2
                if az_denom > 0:
                    contributions.append((ds * dt / az_denom) ** 3)
            else:
                raise ValueError(f"unknown index '{index}'; choose from "
                                 f"sombor/reduced_sombor/randic/zagreb_m1/abc/ga/augmented_zagreb")
        if not contributions:
            return None
        total = sum(contributions)
        if total <= 0:
            return None
        m = len(contributions)
        probs = [c / total for c in contributions]
        # Rényi entropy: H_α = 1/(1−α) · ln(Σ p^α)
        sum_pa = sum(p ** alpha for p in probs)
        if sum_pa <= 0:
            return None
        renyi = math.log(sum_pa) / (1.0 - alpha)
        if normalized and m > 1:
            # Maximum Rényi entropy: uniform distribution → ln(m)
            # H_α^max = 1/(1−α) · ln(m · (1/m)^α) = 1/(1−α) · ln(m^(1−α)) = ln(m)
            renyi /= math.log(m)
        return renyi

    # ── Cycle 320: Classification with rejection ────────────────────

    def classification_with_rejection(self,
                                     classification_result: dict,
                                     *,
                                     threshold: float = 0.5,
                                     min_margin: float = 0.0,
                                     ) -> Optional[dict]:
        """Apply threshold-based rejection to a classification result.

        Takes a result dict from ``graph_classification`` ,
        ``spectral_classification`` , or ``hybrid_classification``
        and adds a reject/accept decision based on configurable criteria.

        **Why rejection?**
        Forcing a best-match when *no* reference is actually close leads
        to false positives in production.  A rejection mechanism lets
        the caller know when the classifier is uncertain, enabling
        fallback strategies (human review, expanded reference set, etc.).

        **Rejection criteria (both must be met to accept):**

        1. **Score threshold**: ``best_score ≤ threshold``
           - For JSD-based methods: typical good values 0.3–0.5
           - For fingerprint L2: typical good values 0.2–0.8
           - For hybrid: normalised ensemble score, try 0.3–0.7
        2. **Margin**: ``margin ≥ min_margin``
           - Ensures sufficient separation between top-2 candidates
           - ``min_margin=0`` disables this check (threshold only)

        When the best score is 0 (exact match), the result is always
        accepted regardless of threshold (perfect match overrides).

        Args:
            classification_result: dict from any ``*_classification()``
                method.  Must contain ``best_score`` , ``margin`` , and
                ``rankings`` keys.
            threshold: maximum acceptable ``best_score`` .
                Default 0.5 (conservative for JSD; tune for your method).
            min_margin: minimum acceptable margin (``2nd − best``).
                Default 0.0 (disabled).

        Returns:
            Dict with all original keys plus:
            - ``decision``: ``"accept"`` or ``"reject"``
            - ``reason``: str explaining the decision
            - ``threshold``: float (echoed)
            - ``min_margin``: float (echoed)
            - ``calibrated_confidence``: float — confidence rescaled
              to [0, 1] where 0 = at threshold, 1 = perfect match.
              Negative values indicate rejection territory.
            or ``None`` if input is malformed.
        """
        if not isinstance(classification_result, dict):
            return None
        if "best_score" not in classification_result:
            return None

        best_score = classification_result["best_score"]
        if best_score is None:
            return None

        # Margin: use explicit value if present, otherwise compute from rankings
        margin = classification_result.get("margin")
        if margin is None:
            rankings = classification_result.get("rankings", [])
            if len(rankings) >= 2:
                scores = [r.get("score", 0) for r in rankings if r.get("score") is not None]
                scores.sort()
                margin = scores[1] - scores[0] if len(scores) >= 2 else 0.0
            else:
                margin = 0.0

        if margin is None:
            return None

        # Perfect match: always accept
        if best_score <= 1e-15:
            decision = "accept"
            reason = "exact match (score ≈ 0)"
            calibrated = 1.0
        else:
            # Score criterion
            score_ok = best_score <= threshold
            # Margin criterion
            margin_ok = margin >= min_margin

            if score_ok and margin_ok:
                decision = "accept"
                if margin_ok and min_margin > 0:
                    reason = (f"score {best_score:.4f} ≤ threshold {threshold:.4f} "
                              f"and margin {margin:.4f} ≥ min_margin {min_margin:.4f}")
                else:
                    reason = f"score {best_score:.4f} ≤ threshold {threshold:.4f}"
            elif not score_ok and not margin_ok:
                decision = "reject"
                reason = (f"score {best_score:.4f} > threshold {threshold:.4f} "
                          f"and margin {margin:.4f} < min_margin {min_margin:.4f}")
            elif not score_ok:
                decision = "reject"
                reason = f"score {best_score:.4f} > threshold {threshold:.4f}"
            else:
                decision = "reject"
                reason = f"margin {margin:.4f} < min_margin {min_margin:.4f}"

            # Calibrated confidence: 1.0 at score=0, 0.0 at score=threshold
            # Linear rescale: (threshold - score) / threshold
            if threshold > 0:
                calibrated = (threshold - best_score) / threshold
            else:
                calibrated = 0.0 if best_score > 0 else 1.0

        result = dict(classification_result)  # shallow copy
        result["decision"] = decision
        result["reason"] = reason
        result["threshold"] = threshold
        result["min_margin"] = min_margin
        result["calibrated_confidence"] = round(calibrated, 6)
        return result

    def entropy_distance(self, other: "MemoryGraph", index: str = "sombor") -> Optional[float]:
        """Jensen-Shannon divergence between two graphs' edge-contribution distributions.

        For a chosen degree-based *index*, computes the normalized
        probability distributions *P* (self) and *Q* (other), then
        calculates the Jensen-Shannon divergence::

            M = ½(P + Q)
            JSD = ½·KL(P‖M) + ½·KL(Q‖M)

        where KL(A‖B) = Σ a·ln(a/b) is the Kullback-Leibler divergence.

        **Properties:**
        - Symmetric: JSD(A, B) = JSD(B, A)
        - Bounded: 0 ≤ JSD ≤ ln(2) ≈ 0.693
        - JSD(A, A) = 0 (self-distance is zero)
        - Normalized output in [0, 1] (divided by ln 2)
        - JSD = 0 iff the edge-contribution distributions are identical

        The *index* parameter selects which degree-based contributions
        to use (same 7 options as ``tsallis_entropy``).

        For graphs with different edge counts, the distributions are
        naturally over different support sizes.  This method handles
        that by computing probabilities over the *union* of normalized
        contribution values (binned to 6 decimal places), assigning
        zero probability to missing categories.

        Args:
            other: the other ``MemoryGraph`` to compare against.
            index: which degree-based contributions to use.

        Returns:
            float in [0, 1], or ``None`` if either graph has < 1 edge.
        """
        dist_a = self._contribution_distribution(index)
        dist_b = other._contribution_distribution(index)
        if dist_a is None or dist_b is None:
            return None
        # Build aligned distributions over the union of keys
        keys = set(dist_a.keys()) | set(dist_b.keys())
        pa = [dist_a.get(k, 0.0) for k in keys]
        qb = [dist_b.get(k, 0.0) for k in keys]
        # Jensen-Shannon divergence
        jsd = 0.0
        for p, q in zip(pa, qb):
            m = 0.5 * (p + q)
            if p > 0 and m > 0:
                jsd += 0.5 * p * math.log(p / m)
            if q > 0 and m > 0:
                jsd += 0.5 * q * math.log(q / m)
        # Normalize to [0, 1] by dividing by ln(2)
        ln2 = math.log(2)
        if ln2 > 0:
            jsd /= ln2
        # Clamp to handle floating-point overshoot
        return max(0.0, min(1.0, jsd))

    def _contribution_distribution(self, index: str = "sombor") -> Optional[dict]:
        """Return normalized degree-based contribution distribution.

        Maps each unique (rounded) contribution value to its probability.
        Internal helper for ``entropy_distance``.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds <= 0 or dt <= 0:
                continue
            if index == "sombor":
                contributions.append(math.sqrt(ds * ds + dt * dt))
            elif index == "reduced_sombor":
                contributions.append(math.sqrt((ds - 1) ** 2 + (dt - 1) ** 2))
            elif index == "randic":
                contributions.append(1.0 / math.sqrt(ds * dt))
            elif index == "zagreb_m1":
                contributions.append(float(ds + dt))
            elif index == "abc":
                num = ds + dt - 2
                den = ds * dt
                if num > 0 and den > 0:
                    contributions.append(math.sqrt(num / den))
            elif index == "ga":
                contributions.append(2.0 * math.sqrt(ds * dt) / (ds + dt))
            elif index == "augmented_zagreb":
                az_denom = ds + dt - 2
                if az_denom > 0:
                    contributions.append((ds * dt / az_denom) ** 3)
            else:
                raise ValueError(f"unknown index '{index}'")
        if not contributions:
            return None
        total = sum(contributions)
        if total <= 0:
            return None
        # Group by rounded contribution value and normalize
        dist: dict[float, float] = {}
        for c in contributions:
            key = round(c / total, 6)
            dist[key] = dist.get(key, 0.0) + (c / total)
        return dist

    # ── Cycle 298: Cross-entropy between graphs ─

    def cross_entropy_graph(self, other: "MemoryGraph", index: str = "sombor") -> Optional[float]:
        """Asymmetric cross-entropy H(P, Q) between two graphs' edge-contribution distributions.

        For a chosen degree-based *index*, computes the normalized
        probability distributions *P* (self) and *Q* (other), then
        calculates the cross-entropy::

            H(P, Q) = −Σ_{e: p_e > 0} p_e · ln(q_e)

        where *p_e* are self's contribution probabilities and *q_e* are
        the other graph's probabilities, aligned over the *union* of
        normalized contribution values (binned to 6 decimal places).

        **Relationship to ``entropy_distance`` (JSD):**

        ::

            JSD(P, Q) = ½·KL(P‖M) + ½·KL(Q‖M)
                      = H(P, Q) − ½·H(P) − ½·H(Q)   (up to base)

        Cross-entropy is the *asymmetric* variant: H(P, Q) ≠ H(Q, P)
        in general.  It measures the information cost of encoding
        samples from distribution *P* using a code optimised for *Q*.

        **Properties:**
        - Asymmetric: H(P, Q) ≠ H(Q, P) in general
        - H(P, P) = H(P) (self cross-entropy = Shannon entropy)
        - H(P, Q) ≥ H(P) (cross-entropy ≥ self-entropy, Gibbs' inequality)
        - Non-negative for all distributions
        - When P and Q have disjoint supports: H(P, Q) → ∞ (no overlap)
        - Normalized output: divided by ln(m_max) for [0, ~1+] range

        **Use cases:**
        - Graph classification: compute H(G, G_i) for reference graphs,
          classify by minimum cross-entropy
        - Anomaly detection: high H(G_normal, G_test) signals anomaly
        - Directional similarity: H(A, B) < H(B, A) means A is
          "well-described" by B but not vice versa

        Args:
            other: the other ``MemoryGraph`` to compare against.
            index: which degree-based contributions to use
                (sombor, reduced_sombor, randic, zagreb_m1, abc, ga,
                augmented_zagreb).

        Returns:
            float ≥ 0, or ``None`` if either graph has < 1 edge.
        """
        dist_a = self._contribution_distribution(index)
        dist_b = other._contribution_distribution(index)
        if dist_a is None or dist_b is None:
            return None
        # Build aligned distributions over the union of keys
        keys = set(dist_a.keys()) | set(dist_b.keys())
        pa = [dist_a.get(k, 0.0) for k in keys]
        qb = [dist_b.get(k, 0.0) for k in keys]
        # Cross-entropy H(P, Q) = −Σ p · ln(q), only where p > 0
        h_pq = 0.0
        for p, q in zip(pa, qb):
            if p > 0:
                if q > 0:
                    h_pq -= p * math.log(q)
                else:
                    # p > 0 but q = 0: infinite cross-entropy
                    # Clamp to a large penalty to keep it finite
                    h_pq -= p * math.log(1e-12)
        # Normalize by ln(number of categories) for interpretability
        m = max(len(keys), 2)
        ln_m = math.log(m)
        if ln_m > 0:
            h_pq /= ln_m
        return max(0.0, h_pq)

    # ── Cycle 299: KL divergence between graphs ─

    def kl_divergence_graph(self, other: "MemoryGraph", index: str = "sombor") -> Optional[float]:
        """Kullback-Leibler divergence KL(P‖Q) between two graphs' edge-contribution distributions.

        For a chosen degree-based *index*, computes the normalized
        probability distributions *P* (self) and *Q* (other), then
        calculates the KL divergence::

            KL(P‖Q) = Σ_{e: p_e > 0} p_e · ln(p_e / q_e)

        This is the **relative entropy** — the information gain when
        moving from distribution *Q* to distribution *P*.

        **Relationship to other inter-graph measures:**

        ::

            KL(P‖Q) = H(P, Q) − H(P)     (cross-entropy − self-entropy)
            JSD(P,Q) = ½·KL(P‖M) + ½·KL(Q‖M)   (M = ½(P+Q))

        KL divergence is the fundamental asymmetric measure from which
        both cross-entropy and JSD are derived.

        **Properties:**
        - Asymmetric: KL(P‖Q) ≠ KL(Q‖P) in general
        - Non-negative: KL(P‖Q) ≥ 0 (Gibbs' inequality)
        - KL(P‖P) = 0 (self-divergence is zero)
        - KL(P‖Q) = 0 iff P = Q almost everywhere
        - Not a true metric (does not satisfy triangle inequality)
        - When P has mass where Q has none: KL → ∞ (clamped to finite)
        - Normalized by ln(m_max) for interpretability

        **Use cases:**
        - Model selection: find the reference graph that minimizes KL
          from the query graph
        - Information gain: measure how much new information one graph
          carries relative to another
        - Anomaly scoring: KL(normal‖test) quantifies deviation
        - Prior-posterior analysis: compare expected vs observed structure

        Args:
            other: the other ``MemoryGraph`` to compare against (Q).
            index: which degree-based contributions to use
                (sombor, reduced_sombor, randic, zagreb_m1, abc, ga,
                augmented_zagreb).

        Returns:
            float ≥ 0, or ``None`` if either graph has < 1 edge.
        """
        dist_a = self._contribution_distribution(index)
        dist_b = other._contribution_distribution(index)
        if dist_a is None or dist_b is None:
            return None
        # Build aligned distributions over the union of keys
        keys = set(dist_a.keys()) | set(dist_b.keys())
        pa = [dist_a.get(k, 0.0) for k in keys]
        qb = [dist_b.get(k, 0.0) for k in keys]
        # KL(P‖Q) = Σ p · ln(p/q), only where p > 0
        kl = 0.0
        for p, q in zip(pa, qb):
            if p > 0:
                if q > 0:
                    kl += p * math.log(p / q)
                else:
                    # p > 0 but q = 0: infinite KL (P has mass Q doesn't)
                    # Clamp to a large penalty
                    kl += p * math.log(p / 1e-12)
        # Normalize by ln(number of categories) for interpretability
        m = max(len(keys), 2)
        ln_m = math.log(m)
        if ln_m > 0:
            kl /= ln_m
        return max(0.0, kl)

    # ── Cycle 300: Multi-scale entropy scan for graph fingerprinting ─

    def entropy_scan(self, index: str = "sombor",
                     alphas: list[float] | None = None,
                     qs: list[float] | None = None) -> Optional[dict]:
        """Multi-scale Rényi and Tsallis entropy sweep for graph fingerprinting.

        Computes Rényi entropy H_α and Tsallis entropy S_q across a range
        of α and q parameters.  The resulting curves are structural
        fingerprints that uniquely characterize a graph's distribution shape.

        **Why multi-scale?**
        Different α/q values probe different aspects of the distribution:
        - Low α/q (< 1): emphasise rare edge contributions (long tails)
        - α/q = 1: Shannon entropy (maximum uncertainty)
        - α/q = 2: collision/square-counting entropy
        - High α/q (> 2): emphasise dominant contributions

        Two graphs with identical Shannon entropy can have very different
        multi-scale profiles — making entropy_scan a more discriminative
        fingerprint.

        **Use cases:**
        - Graph similarity: compare scan curves across graphs
        - Phase detection: track curve shape changes over time
        - Anomaly detection: deviation from reference curve
        - Graph classification: scan as feature vector

        Args:
            index: degree-based index (sombor, reduced_sombor, randic,
                zagreb_m1, abc, ga, augmented_zagreb).
            alphas: Rényi α values to sweep (default: [0.1, 0.5, 1.0, 1.5, 2.0, 3.0, 5.0, 10.0]).
            qs: Tsallis q values to sweep (default: [0.1, 0.5, 1.5, 2.0, 3.0, 5.0, 10.0]).
                Note: q=1 is excluded (equals Shannon, captured by α=1).

        Returns:
            Dict with keys:
            - "renyi": {"alphas": [...], "values": [...]}
            - "tsallis": {"qs": [...], "values": [...]}
            - "shannon": float (included in both curves at limit)
            or None if graph has < 1 edge.
        """
        if alphas is None:
            alphas = [0.1, 0.5, 1.0, 1.5, 2.0, 3.0, 5.0, 10.0]
        if qs is None:
            qs = [0.1, 0.5, 1.5, 2.0, 3.0, 5.0, 10.0]

        # Early exit if insufficient graph
        dist = self._contribution_distribution(index)
        if dist is None:
            return None

        # Edge count for normalization (matches renyi_entropy's normalization)
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        m = len(edges)
        if m < 1:
            return None

        # Raw per-edge probabilities (not grouped) for Shannon
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            if ds <= 0 or dt <= 0:
                continue
            if index == "sombor":
                contributions.append(math.sqrt(ds * ds + dt * dt))
            elif index == "reduced_sombor":
                contributions.append(math.sqrt((ds - 1) ** 2 + (dt - 1) ** 2))
            elif index == "randic":
                contributions.append(1.0 / math.sqrt(ds * dt))
            elif index == "zagreb_m1":
                contributions.append(float(ds + dt))
            elif index == "abc":
                num, den = ds + dt - 2, ds * dt
                if num > 0 and den > 0:
                    contributions.append(math.sqrt(num / den))
            elif index == "ga":
                contributions.append(2.0 * math.sqrt(ds * dt) / (ds + dt))
            elif index == "augmented_zagreb":
                az_denom = ds + dt - 2
                if az_denom > 0:
                    contributions.append((ds * dt / az_denom) ** 3)
        if not contributions:
            return None
        total = sum(contributions)
        probs = [c / total for c in contributions]
        ln_m = math.log(m) if m > 1 else 1.0

        # Shannon from raw probabilities, normalized by ln(m)
        shannon = -sum(p * math.log(p) for p in probs if p > 0)
        if ln_m > 0:
            shannon /= ln_m

        renyi_values = []
        for a in alphas:
            if a == 1.0:
                v = shannon
            else:
                v = self.renyi_entropy(alpha=a, normalized=True, index=index)
            renyi_values.append(round(v, 8) if v is not None else None)

        tsallis_values = []
        for q in qs:
            v = self.tsallis_entropy(q=q, normalized=True, index=index)
            tsallis_values.append(round(v, 8) if v is not None else None)

        # shannon already computed above from raw probs, normalized by ln(m)

        # ── Cycle 339: Shape descriptors + fingerprint vector ──
        # Compute UNNORMALIZED Rényi entropies directly from probs for shape analysis.
        # Normalized values (used in the main curve above) compress the range and
        # make uniform distributions identical (all → 1.0), losing topology signal.
        # Unnormalized Rényi: H_α = 1/(1−α) · ln(Σ p_e^α) — bounded [0, ln(m)].
        def _raw_renyi(p: list[float], alpha: float) -> float:
            if abs(alpha - 1.0) < 1e-12:
                return -sum(pi * math.log(pi) for pi in p if pi > 0)
            s = sum(pi ** alpha for pi in p if pi > 0)
            if s <= 0:
                return 0.0
            return math.log(s) / (1.0 - alpha)

        raw_renyi = [_raw_renyi(probs, a) for a in alphas]
        valid_renyi = [v for v in raw_renyi if v is not None]
        n_r = len(valid_renyi)

        # Monotonicity (strictly decreasing?)
        monotonic = all(
            valid_renyi[i] <= valid_renyi[i - 1] + 1e-10
            for i in range(1, n_r)
        ) if n_r > 1 else True

        # Convexity (second differences ≥ 0?)
        convex = True
        for i in range(1, n_r - 1):
            d2 = valid_renyi[i + 1] - 2 * valid_renyi[i] + valid_renyi[i - 1]
            if d2 < -1e-10:
                convex = False
                break

        # Knee detection (max |second difference|)
        knee_position = None
        max_d2 = 0.0
        for i in range(1, n_r - 1):
            d2 = abs(valid_renyi[i + 1] - 2 * valid_renyi[i] + valid_renyi[i - 1])
            if d2 > max_d2:
                max_d2 = d2
                knee_position = alphas[i] if i < len(alphas) else None

        # Curve area (trapezoidal integration over α values)
        curve_area = 0.0
        for i in range(1, n_r):
            dx = alphas[i] - alphas[i - 1] if i < len(alphas) else 0.0
            curve_area += dx * (valid_renyi[i] + valid_renyi[i - 1]) / 2.0

        # Max-min gap (heterogeneity range) — uses RAW values
        max_min_gap = (valid_renyi[0] - valid_renyi[-1]) if n_r > 0 else 0.0

        # Slope at α ≈ 2
        slope_at_alpha2 = 0.0
        for i in range(1, len(raw_renyi)):
            if i < len(alphas) and alphas[i] >= 2.0:
                dx = alphas[i] - alphas[i - 1]
                if dx > 0:
                    slope_at_alpha2 = (raw_renyi[i] - raw_renyi[i - 1]) / dx
                break

        shape = {
            "monotonic": monotonic,
            "convex": convex,
            "knee_position": knee_position,
            "curve_area": round(curve_area, 8),
            "max_min_gap": round(max_min_gap, 8),
            "slope_at_alpha2": round(slope_at_alpha2, 8),
        }

        # Fingerprint vector: flatten raw entropies + shape scalars
        raw_shannon = -sum(p * math.log(p) for p in probs if p > 0)
        fingerprint: list[float] = [round(raw_shannon, 8)]
        for v in raw_renyi:
            fingerprint.append(round(v, 8))
        # Include raw Tsallis for richer fingerprint
        for q in qs:
            if abs(q - 1.0) < 1e-12:
                fingerprint.append(round(raw_shannon, 8))
            else:
                s = sum(p ** q for p in probs if p > 0)
                fingerprint.append(round((1.0 - s) / (q - 1.0), 8))
        fingerprint.extend([shape["curve_area"], shape["max_min_gap"], shape["slope_at_alpha2"]])

        return {
            "renyi": {"alphas": alphas, "values": renyi_values},
            "tsallis": {"qs": qs, "values": tsallis_values},
            "shannon": round(shannon, 8) if shannon is not None else None,
            "shape": shape,
            "fingerprint": fingerprint,
        }

    # ── Cycle 301: Graph classification via inter-graph trilogy ─

    def graph_similarity_matrix(self, graphs: list["MemoryGraph"],
                                method: str = "jsd",
                                index: str = "sombor") -> Optional[dict]:
        """Compute pairwise similarity/divergence matrix across multiple graphs.

        For *N* input graphs, produces an *N×N* matrix of pairwise
        inter-graph measures (JSD distance, cross-entropy, or KL divergence).
        The diagonal is always 0 for symmetric measures (JSD) and correctly
        computed for asymmetric ones (CE, KL: H(G,G)=H(G), KL(G‖G)=0).

        Enables graph clustering, anomaly detection, and similarity search
        without external tools.  Pairs naturally with ``graph_classification()``
        for multi-reference comparison.

        Args:
            graphs: list of MemoryGraphs to compare pairwise.
                **Self** is NOT included automatically — pass it explicitly
                if desired.
            method: inter-graph measure:
                - ``"jsd"`` — Jensen-Shannon distance (symmetric, [0,1])
                - ``"ce"`` — cross-entropy H(row, col) (asymmetric)
                - ``"kl"`` — KL divergence KL(row‖col) (asymmetric)
            index: degree-based index for edge contribution computation.

        Returns:
            Dict with:
            - ``matrix``: N×N list of floats (NaN if comparison failed)
            - ``method``: str
            - ``index``: str
            - ``size``: int (number of graphs)
            - ``symmetric``: bool (True for jsd, False for ce/kl)
            or None if fewer than 2 graphs.
        """
        n = len(graphs)
        if n < 2:
            return None

        compute = {
            "jsd": lambda a, b: a.entropy_distance(b, index=index),
            "ce": lambda a, b: a.cross_entropy_graph(b, index=index),
            "kl": lambda a, b: a.kl_divergence_graph(b, index=index),
        }.get(method)
        if compute is None:
            raise ValueError(
                f"unknown method '{method}'; choose from jsd/ce/kl"
            )

        matrix = [[0.0] * n for _ in range(n)]

        if method == "jsd":
            # Symmetric: compute upper triangle, mirror
            for i in range(n):
                for j in range(i + 1, n):
                    val = compute(graphs[i], graphs[j])
                    if val is None:
                        val = float("nan")
                    else:
                        val = round(val, 8)
                    matrix[i][j] = val
                    matrix[j][i] = val
        else:
            # Asymmetric: compute full matrix
            for i in range(n):
                for j in range(n):
                    if i == j:
                        # Diagonal: KL(G‖G)=0, CE(G,G)=H(G)
                        if method == "kl":
                            matrix[i][j] = 0.0
                        else:  # ce
                            matrix[i][j] = round(
                                compute(graphs[i], graphs[i]) or 0.0, 8
                            )
                    else:
                        val = compute(graphs[i], graphs[j])
                        matrix[i][j] = round(val, 8) if val is not None else float("nan")

        return {
            "matrix": matrix,
            "method": method,
            "index": index,
            "size": n,
            "symmetric": method == "jsd",
        }

    def graph_classification(self, references: list["MemoryGraph"],
                              method: str = "jsd",
                              index: str = "sombor") -> Optional[dict]:
        """Classify a graph against reference graphs using inter-graph measures.

        Computes the chosen distance/divergence between *self* and each
        reference graph, then returns the best match and full ranking.

        **Methods:**
        - ``"jsd"`` — Jensen-Shannon distance (symmetric, true metric)
        - ``"ce"`` — cross-entropy H(self, ref) (asymmetric, encoding cost)
        - ``"kl"`` — KL divergence KL(self‖ref) (asymmetric, info gain)

        Args:
            references: list of reference MemoryGraphs to classify against.
            method: inter-graph measure (jsd, ce, kl).
            index: degree-based index for edge contributions.

        Returns:
            Dict with:
            - "best_match": int (index of closest reference)
            - "best_score": float (lowest distance/divergence)
            - "rankings": list of {"index": int, "score": float} sorted ascending
            - "method": str
            or None if no valid comparisons could be made.
        """
        if not references:
            return None

        compute = {
            "jsd": self.entropy_distance,
            "ce": self.cross_entropy_graph,
            "kl": self.kl_divergence_graph,
        }.get(method)
        if compute is None:
            raise ValueError(f"unknown method '{method}'; choose from jsd/ce/kl")

        rankings = []
        for i, ref in enumerate(references):
            score = compute(ref, index=index)
            if score is not None:
                rankings.append({"index": i, "score": round(score, 8)})

        if not rankings:
            return None

        rankings.sort(key=lambda x: x["score"])
        return {
            "best_match": rankings[0]["index"],
            "best_score": rankings[0]["score"],
            "rankings": rankings,
            "method": method,
        }

    # ── Cycle 282: Augmented Zagreb entropy + edge-betweenness entropy ─

    def augmented_zagreb_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Augmented Zagreb edge contributions.

        For each edge *e* = (*u*, *v*) with *d_u + d_v > 2*:

        ::

            a_e = (d_u · d_v / (d_u + d_v − 2))³
            p_e = a_e / AZI
            H_AZI = −Σ p_e · ln(p_e)

        Edges where *d_u + d_v = 2* (K₂ edges) contribute 0 to AZI
        and are **excluded** from the entropy calculation — the same
        filtering behaviour as ``abc_entropy()``.

        The cubic exponent makes AZI entropy the most sensitive
        degree-based entropy: small differences in endpoint degrees
        are amplified, producing wider score distributions and thus
        lower normalised entropy for irregular graphs.

        **Properties:**
        - Regular graphs (K_n, C_n, stars): all contributions equal → H = 1.0
        - K₂-only graphs: AZI = 0, entropy undefined → None
        - P_n (n ≥ 4): endpoint vs internal edges differ → H < 1.0

        Args:
            normalized: divide by ln(m) for [0, 1] range.

        Returns:
            float, or ``None`` for < 1 edge or all-K₂ graphs.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        if not edges:
            return None
        deg: dict[str, int] = {}
        for r in rows:
            nid = str(r["id"])
            deg[nid] = self.degree(nid)
        contributions: list[float] = []
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            ds, dt = deg.get(s, 0), deg.get(t, 0)
            denom = ds + dt - 2
            if denom > 0 and ds > 0 and dt > 0:
                contributions.append((ds * dt / denom) ** 3)
        if not contributions:
            return None
        total = sum(contributions)
        if total <= 0:
            return None
        m = len(contributions)
        probs = [c / total for c in contributions]
        entropy = 0.0
        for p in probs:
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def edge_betweenness_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised edge betweenness centrality.

        Unlike the degree-based entropies which measure heterogeneity
        in *local* edge weights, edge-betweenness entropy captures
        heterogeneity in *global* structural importance — how unevenly
        shortest paths are distributed across edges.

        For each edge *e* with betweenness centrality *b_e*:

        ::

            p_e = b_e / Σ b_e
            H_EB = −Σ p_e · ln(p_e)

        **Properties:**
        - Cycle graphs C_n: all edges have equal betweenness → H = 1.0
        - Complete graphs K_n: all edges equal → H = 1.0
        - Trees: betweenness varies widely (internal edges carry more
          paths) → H < 1.0
        - Star K_{1,k}: betweenness is equal across all edges
          (each edge is on k−1 shortest paths through the centre)
          → H = 1.0
        - Path P_n: betweenness is maximally uneven (central edges
          carry more paths) → H significantly < 1.0
        - Bridge edges: extremely high betweenness → lower entropy

        This is the first entropy measure in the toolkit based on
        *centrality* rather than *degree*, opening the structural
        entropy category.

        Args:
            normalized: divide by ln(m) for [0, 1] range.

        Returns:
            float, or ``None`` for < 2 nodes or no edges.
        """
        eb = self.edge_betweenness()
        if not eb:
            return None
        # Filter zero-betweenness edges (can occur in disconnected graphs)
        values = [v for v in eb.values() if v > 0]
        if not values:
            return None
        total = sum(values)
        if total <= 0:
            return None
        m = len(values)
        probs = [v / total for v in values]
        entropy = 0.0
        for p in probs:
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def closeness_vitality_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised closeness vitality values.

        Closeness vitality measures how much each node contributes to
        the overall reachability of the graph — it is the change in
        the Wiener index when that node (and its incident edges) is
        removed.

        For each node *v* with closeness vitality *cv_v*:

        ::

            p_v = cv_v / Σ cv_v   (using |cv_v| to handle negatives)
            H_CV = −Σ p_v · ln(p_v)

        Because closeness vitality can be negative (removing a central
        node from a dense graph may *decrease* total distances by
        disconnecting it), we use absolute values for the probability
        distribution.

        **Properties:**
        - Regular graphs (K_n, C_n): all vitalities equal → H = 1.0
        - Path P_n: endpoints vs centre have different vitalities → H < 1.0
        - Star K_{1,k}: centre has very different vitality from leaves → H < 1.0
        - Disconnected graphs: vitality may be 0 for all nodes → None

        Args:
            normalized: divide by ln(n) for [0, 1] range.

        Returns:
            float, or ``None`` for < 2 nodes or all-zero vitalities.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        n = len(rows)
        if n < 2:
            return None
        vitalities: list[float] = []
        for r in rows:
            nid = str(r["id"])
            cv = self.closeness_vitality(nid)
            if cv is not None:
                vitalities.append(abs(cv))
        # Filter zero vitalities (can occur in disconnected graphs)
        values = [v for v in vitalities if v > 0]
        if not values:
            return None
        total = sum(values)
        if total <= 0:
            return None
        m = len(values)
        probs = [v / total for v in values]
        entropy = 0.0
        for p in probs:
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def eigenvector_centrality_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised eigenvector centrality values.

        Eigenvector centrality measures the influence of a node in a
        network — a node is important if it is connected to other
        important nodes.  This entropy captures how evenly "influence"
        is distributed across the graph.

        For each node *v* with eigenvector centrality *ec_v*:

        ::

            p_v = ec_v / Σ ec_v
            H_EC = −Σ p_v · ln(p_v)

        **Properties:**
        - Regular graphs (K_n, C_n): all centralities equal → H = 1.0
        - Star K_{1,k}: centre dominates → H significantly < 1.0
        - Path P_n: endpoints have low centrality → H < 1.0
        - Disconnected graphs: isolated nodes get centrality ≈ 0,
          effectively excluded from the distribution

        This is the second centrality-based entropy (after
        ``edge_betweenness_entropy``), extending the structural entropy
        category to node-level spectral importance.

        Args:
            normalized: divide by ln(n) for [0, 1] range.

        Returns:
            float, or ``None`` for < 2 nodes or no positive centralities.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        n = len(rows)
        if n < 2:
            return None
        # Build symmetric (undirected) adjacency for power iteration
        node_ids = [str(r["id"]) for r in rows]
        idx = {nid: i for i, nid in enumerate(node_ids)}
        adj_sym: dict[int, set[int]] = {i: set() for i in range(n)}
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = str(e["source"]), str(e["target"])
            if s in idx and t in idx:
                adj_sym[idx[s]].add(idx[t])
                adj_sym[idx[t]].add(idx[s])
        # Power iteration on (A + I) to handle bipartite graphs
        # where eigenvalues come in ±λ pairs (stars, paths, …).
        # Adding I shifts spectrum to λ+1 ≥ 0, preserving eigenvectors
        # while eliminating sign oscillation.
        import random
        random.seed(42)
        v = [1.0 / math.sqrt(n)] * n
        for _ in range(500):
            new_v = [v[i] for i in range(n)]  # +I contribution
            for i in range(n):
                for j in adj_sym[i]:
                    new_v[i] += v[j]
            norm = math.sqrt(sum(x * x for x in new_v))
            if norm == 0:
                break
            new_v = [x / norm for x in new_v]
            diff = sum(abs(new_v[i] - v[i]) for i in range(n))
            v = new_v
            if diff < 1e-10:
                break
        # Eigenvector centrality values (all non-negative for connected
        # non-bipartite graphs; use abs for safety)
        values = [abs(v[i]) for i in range(n) if abs(v[i]) > 1e-15]
        if not values:
            return None
        total = sum(values)
        if total <= 0:
            return None
        m = len(values)
        probs = [v / total for v in values]
        entropy = 0.0
        for p in probs:
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def onion_structure(self, n_layers: int = 3) -> Optional[list[dict]]:
        """洋葱结构 — k-core 分层剖面。

        逐步移除度数 < k 的节点，记录每一层的节点集合和统计信息。
        比 core_number() 更直观地展示图的 "深度结构"。

        每层返回：
        - k: 核心度阈值
        - nodes: 属于该层但在 k+1 层被移除的节点 ID
        - count: 节点数量
        - edges: 这些节点之间（在原图中）的边数

        Args:
            n_layers: 最大层数（默认 3）

        Returns:
            list[dict]: 各层剖面；空图返回 None。
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return None
        all_ids = {str(r["id"]) for r in rows}
        result = []
        prev_core = set(all_ids)
        for k in range(1, n_layers + 1):
            if not prev_core:
                break
            # Iteratively remove nodes with degree < k among prev_core
            changed = True
            current = set(prev_core)
            while changed:
                changed = False
                to_remove = set()
                ids_list = list(current)
                for nid in current:
                    cnt = self.conn.execute(
                        "SELECT COUNT(*) FROM edges WHERE source=? AND target IN ({}) "
                        "UNION ALL "
                        "SELECT COUNT(*) FROM edges WHERE target=? AND source IN ({})".format(
                            ",".join("?" * len(ids_list)), ",".join("?" * len(ids_list))
                        ),
                        (nid, *ids_list, nid, *ids_list)
                    ).fetchall()
                    deg = sum(r[0] for r in cnt)
                    if deg < k:
                        to_remove.add(nid)
                if to_remove:
                    current -= to_remove
                    changed = True
            # Nodes peeled at this level = in prev_core but not in current
            peeled = prev_core - current
            if k == n_layers:
                # Last layer: all remaining nodes (including those surviving k)
                peeled = prev_core
            prev_core = current
            # Count edges among peeled nodes
            if peeled:
                p_list = list(peeled)
                placeholders = ",".join("?" * len(p_list))
                edge_count = self.conn.execute(
                    "SELECT COUNT(*) FROM edges WHERE source IN ({}) AND target IN ({})".format(
                        placeholders, placeholders
                    ),
                    (*p_list, *p_list)
                ).fetchone()[0]
            else:
                edge_count = 0
            result.append({
                "k": k,
                "nodes": sorted(peeled),
                "count": len(peeled),
                "edges": edge_count
            })
            if not current:
                break
        return result

    # ── 向量搜索 (sqlite-vec 可选集成) ────────────────────

    def _ensure_vec_table(self, dims: int):
        """确保 vec_nodes 虚拟表存在，返回是否首次创建。"""
        try:
            import sqlite_vec
            if not getattr(self, '_vec_loaded', False):
                self.conn.enable_load_extension(True)
                sqlite_vec.load(self.conn)
                self.conn.enable_load_extension(False)
                self._vec_loaded = True
        except ImportError:
            raise ImportError("sqlite-vec is required for vector operations. Install: pip install sqlite-vec")
        row = self.conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='vec_nodes'").fetchone()
        if not row:
            self.conn.execute(f"CREATE VIRTUAL TABLE IF NOT EXISTS vec_nodes USING vec0(embedding float[{dims}])")
            self._vec_dims = dims
            return True
        return False

    def _node_to_rowid(self, node_id: str) -> int:
        """将 node_id 字符串映射为稳定的整数 rowid。"""
        row = self.conn.execute("SELECT rowid FROM node_rowids WHERE node_id = ?", (node_id,)).fetchone()
        if row:
            return row["rowid"]
        self.conn.execute("INSERT OR IGNORE INTO node_rowids(node_id) VALUES (?)", (node_id,))
        return self.conn.execute("SELECT rowid FROM node_rowids WHERE node_id = ?", (node_id,)).fetchone()["rowid"]

    def _ensure_rowid_table(self):
        """确保 node_rowids 映射表存在。"""
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS node_rowids (
                node_id TEXT PRIMARY KEY
            )
        """)

    def add_embedding(self, node_id: str, embedding: list[float]) -> None:
        """为节点添加向量嵌入。需要可选依赖 sqlite-vec。

        Args:
            node_id: 目标节点 ID
            embedding: 浮点向量 (任意维度, 首次调用决定维度)

        Raises:
            ImportError: 如果 sqlite-vec 未安装
            ValueError: 如果节点不存在或维度不匹配
        """
        if not self.has_node(node_id):
            raise ValueError(f"Node not found: {node_id}")
        try:
            import sqlite_vec
        except ImportError:
            raise ImportError("sqlite-vec is required. Install: pip install sqlite-vec")

        self._ensure_rowid_table()
        dims = len(embedding)
        self._ensure_vec_table(dims)

        rowid = self._node_to_rowid(node_id)
        vec = sqlite_vec.serialize_float32(embedding)
        self.conn.execute("DELETE FROM vec_nodes WHERE rowid = ?", (rowid,))
        self.conn.execute("INSERT INTO vec_nodes(rowid, embedding) VALUES (?, ?)", (rowid, vec))
        self.conn.commit()

    def search_similar(self, embedding: list[float], limit: int = 10) -> list[dict]:
        """向量相似度搜索 (KNN)。需要可选依赖 sqlite-vec。

        Args:
            embedding: 查询向量
            limit: 返回数量上限

        Returns:
            list of {node_id, label, kind, distance, score} 按距离升序

        Raises:
            ImportError: 如果 sqlite-vec 未安装
            ValueError: 如果尚未添加任何嵌入
        """
        try:
            import sqlite_vec
        except ImportError:
            raise ImportError("sqlite-vec is required. Install: pip install sqlite-vec")

        if not hasattr(self, '_vec_dims'):
            row = self.conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='vec_nodes'").fetchone()
            if not row:
                raise ValueError("No embeddings found. Call add_embedding() first.")

        self._ensure_rowid_table()
        vec = sqlite_vec.serialize_float32(embedding)
        rows = self.conn.execute(
            """
            SELECT v.rowid, v.distance, n.id, n.label, n.kind, n.weight
            FROM vec_nodes AS v
            JOIN node_rowids AS r ON v.rowid = r.rowid
            JOIN nodes AS n ON r.node_id = n.id
            WHERE v.embedding MATCH ? AND v.k = ?
            ORDER BY v.distance
            """,
            (vec, limit)
        ).fetchall()
        results = []
        for row in rows:
            dist = row["distance"]
            # 距离转相似度分数 (1/(1+distance), 范围 0~1)
            score = 1.0 / (1.0 + dist)
            results.append({
                "node_id": row["id"],
                "label": row["label"],
                "kind": row["kind"],
                "distance": round(dist, 6),
                "score": round(score, 6),
                "weight": row["weight"],
            })
        return results

    # ── FTS5 BM25 full-text search ──────────────────────────────────────

    def _fts_sync_node(self, node_id: str):
        """Insert/update FTS index for a single node."""
        if not getattr(self, '_fts_enabled', False):
            return
        row = self.conn.execute(
            "SELECT id, label, kind, data, tags FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            self.conn.execute("DELETE FROM nodes_fts WHERE node_id=?", (node_id,))
            return
        self.conn.execute("DELETE FROM nodes_fts WHERE node_id=?", (node_id,))
        self.conn.execute(
            "INSERT INTO nodes_fts(node_id, label, kind, data, tags) VALUES (?,?,?,?,?)",
            (row["id"], row["label"], row["kind"], row["data"], row["tags"])
        )

    def _fts_delete_node(self, node_id: str):
        """Remove a node from FTS index."""
        if not getattr(self, '_fts_enabled', False):
            return
        self.conn.execute("DELETE FROM nodes_fts WHERE node_id=?", (node_id,))

    def _fts_rebuild(self):
        """Rebuild the FTS index from scratch (all nodes)."""
        if not getattr(self, '_fts_enabled', False):
            return
        self.conn.execute("DELETE FROM nodes_fts")
        rows = self.conn.execute("SELECT id, label, kind, data, tags FROM nodes").fetchall()
        for r in rows:
            self.conn.execute(
                "INSERT INTO nodes_fts(node_id, label, kind, data, tags) VALUES (?,?,?,?,?)",
                (r["id"], r["label"], r["kind"], r["data"], r["tags"])
            )

    def search_bm25(self, query: str, limit: int = 10) -> list[dict]:
        """BM25 full-text search via SQLite FTS5.

        Ranks nodes by BM25 relevance across label, kind, data, and tags.
        Falls back to search_unified() if FTS5 is unavailable.

        Args:
            query: FTS5 query string (supports prefix, AND, OR, NOT, "phrase")
            limit: Max results

        Returns:
            list of {node_id, label, kind, score, matched_fields} sorted by BM25 score desc
        """
        if not getattr(self, '_fts_enabled', False):
            # Fallback to unified search
            results = self.search_unified(query, limit=limit)
            return [
                {"node_id": r["node"].id, "label": r["node"].label,
                 "kind": r["node"].kind, "score": r["score"],
                 "matched_fields": r["matched_fields"]}
                for r in results
            ]
        try:
            # Fetch by raw BM25, then re-sort by weight-boosted score
            rows = self.conn.execute(
                """
                SELECT n.id, n.label, n.kind, n.weight,
                       bm25(nodes_fts) as score
                FROM nodes_fts JOIN nodes n ON nodes_fts.node_id = n.id
                WHERE nodes_fts MATCH ?
                ORDER BY score
                LIMIT ?
                """,
                (query, limit * 3)
            ).fetchall()
        except sqlite3.OperationalError:
            return []
        results = []
        for r in rows:
            bm25_score = -r["score"]  # bm25() returns negative (lower = better)
            results.append({
                "node_id": r["id"],
                "label": r["label"],
                "kind": r["kind"],
                "score": round(bm25_score * r["weight"], 6),
                "matched_fields": ["bm25"],
            })
        results.sort(key=lambda x: x["score"], reverse=True)
        return results[:limit]

    @staticmethod
    def _classify_query(query: str, known_labels: list[str] = None) -> dict:
        """QDAP-v2: 6-class query classifier with continuous weight interpolation.

        Classes: trivial / exact / semantic / relational / temporal / exploratory
        + needs_retrieval gate (trivial queries skip retrieval entirely).
        Weights interpolated from specificity ∈ [0,1] instead of discrete buckets.

        Returns:
            {type, weights: [bm25_w, vector_w, graph_w], k, needs_retrieval, specificity}
        """
        q = query.lower().strip()
        known_labels = known_labels or []
        words = q.split()
        word_count = len(words)

        # ── Feature extraction ──
        has_identifier = any(
            label.lower() in q
            for label in known_labels
            if len(label) >= 3
        )
        # Avoid false positive: common English words ≥4 chars aren't identifiers
        common_words = {"what", "when", "where", "which", "that", "this", "with",
                         "from", "have", "been", "will", "would", "could", "should",
                         "about", "there", "their", "these", "those", "every",
                         "machine", "learning", "deep", "data", "model", "system",
                         "applications", "science", "research", "project", "update",
                         "question", "between", "through", "during", "before",
                         "after", "because", "however", "though", "while"}
        if not has_identifier and word_count <= 2:
            has_identifier = any(
                token.isidentifier() and len(token) >= 4 and token not in common_words
                for token in words
            )

        relation_kw = sum(
            1 for kw in ("relation", "connect", "link", "path", "between",
                         "neighbor", "edge", "关联", "连接", "路径", "邻居")
            if kw in q
        )
        temporal_kw = sum(
            1 for kw in ("when", "time", "before", "after", "recent", "latest",
                         "history", "last", "first", "earliest",
                         "时间", "之前", "之后", "最近", "历史", "上次")
            if kw in q
        )
        exploratory_kw = sum(
            1 for kw in ("how", "why", "what if", "explore", "brainstorm",
                         "compare", "analyze", "design",
                         "如何", "为什么", "探索", "比较", "分析")
            if kw in q
        )

        # ── needs_retrieval gate ──
        # Trivial queries (greetings, single stop-words) skip retrieval
        stop_words = {"hi", "hello", "hey", "ok", "yes", "no", "thanks",
                      "你好", "嗯", "好的", "谢谢"}
        if word_count <= 1 and (q in stop_words or q == ""):
            return {"type": "trivial", "weights": [0.0, 0.0, 0.0], "k": 0,
                    "needs_retrieval": False, "specificity": 0.0}

        # ── Class priority: relational > temporal > exact > exploratory > semantic ──
        if relation_kw > 0:
            q_type = "relational"
            specificity = 0.85
        elif temporal_kw > 0:
            q_type = "temporal"
            specificity = 0.70
        elif has_identifier and word_count <= 3:
            q_type = "exact"
            specificity = 0.90
        elif exploratory_kw > 0:
            q_type = "exploratory"
            specificity = 0.30
        else:
            q_type = "semantic"
            specificity = 0.50

        # ── Continuous weight interpolation (class-aware) ──
        # Base weights per class, modulated by specificity
        base = {
            "relational":   [0.20, 0.25, 0.55],   # graph-dominant
            "exact":        [0.55, 0.20, 0.25],   # bm25-dominant
            "temporal":     [0.45, 0.30, 0.25],   # bm25-leaning (time-sorted)
            "semantic":     [0.25, 0.50, 0.25],   # vector-dominant
            "exploratory":  [0.15, 0.45, 0.40],   # vector + graph diverse
        }[q_type]

        # Specificity modulation: high specificity → sharpen dominant weight
        # low specificity → flatten toward uniform
        s = specificity
        dominant_idx = max(range(3), key=lambda i: base[i])
        weights = []
        for i in range(3):
            if i == dominant_idx:
                weights.append(base[i] + 0.10 * (s - 0.5))
            else:
                weights.append(base[i] - 0.05 * (s - 0.5))
        # Normalize
        total = sum(weights)
        weights = [round(w / total, 3) for w in weights]

        # k scales with exploratory-ness (more open = more results)
        k = 15 if s >= 0.7 else (25 if s <= 0.35 else 20)

        return {"type": q_type, "weights": weights, "k": k,
                "needs_retrieval": True, "specificity": round(specificity, 3)}

    @staticmethod
    def _score_skewness(route_scores: list[dict[str, float]]) -> list[float]:
        """SkewRoute: post-retrieval score distribution analysis.

        Analyzes score skewness per route — top-heavy distributions (high skew)
        indicate confident retrieval; flat distributions indicate uncertainty.
        Returns per-route confidence weights ∈ [0,1].

        Zero training, plug-and-play complement to _entropy_refine.
        """
        import math
        n_routes = len(route_scores)
        if n_routes == 0:
            return []

        confidences = []
        for scores in route_scores:
            vals = sorted(scores.values(), reverse=True)
            if len(vals) < 2:
                # Single or no result: neutral confidence
                confidences.append(0.5 if vals else 0.0)
                continue

            # Skewness via standardized 3rd moment
            n = len(vals)
            mean = sum(vals) / n
            if mean == 0:
                confidences.append(0.5)
                continue
            variance = sum((v - mean) ** 2 for v in vals) / n
            if variance == 0:
                # All scores equal → no signal → neutral
                confidences.append(0.5)
                continue
            std = math.sqrt(variance)
            skew = sum((v - mean) ** 3 for v in vals) / (n * std ** 3)

            # Positive skew = top-heavy dropoff = high confidence (good retrieval)
            # Negative/flat skew = uniform scores = low confidence
            # Map skew ∈ [-2, 2] → confidence ∈ [0.1, 0.9] via sigmoid
            confidence = 1.0 / (1.0 + math.exp(-skew))
            confidences.append(confidence)

        # Normalize to sum=1
        total = sum(confidences)
        if total > 0:
            return [c / total for c in confidences]
        return [1.0 / n_routes] * n_routes

    @staticmethod
    def _entropy_refine(rankings: list[list[str]], initial_weights: list[float],
                        max_iter: int = 3) -> list[float]:
        """Entropy-based 权重修正 (Perez et al. ICML VecDB 2025)。

        分析每路检索结果的分数分布熵,低熵=高置信→增加权重。
        Blend: 70% QDAP + 30% Entropy。
        """
        import math
        weights = list(initial_weights)
        n_routes = len(rankings)
        if n_routes < 2:
            return weights

        for _ in range(max_iter):
            # 计算每路的 Shannon 熵 (用排名位置作为概率代理)
            entropies = []
            for ranking in rankings:
                n = len(ranking)
                if n == 0:
                    entropies.append(1.0)  # 空列表=最大不确定
                    continue
                if n == 1:
                    entropies.append(0.0)  # 单结果=零熵=完全确信
                    continue
                probs = [1.0 / (i + 1) for i in range(n)]
                total = sum(probs)
                probs = [p / total for p in probs]
                h = -sum(p * math.log2(p) for p in probs if p > 0)
                h_norm = h / math.log2(n)
                entropies.append(h_norm)

            # 低熵 → 高置信 → 增加权重
            confidences = [1.0 - h for h in entropies]
            total_conf = sum(confidences)
            if total_conf > 0:
                entropy_weights = [c / total_conf for c in confidences]
            else:
                entropy_weights = [1.0 / n_routes] * n_routes

            # Blend
            new_weights = [0.7 * w + 0.3 * ew for w, ew in zip(weights, entropy_weights)]
            if max(abs(n - o) for n, o in zip(new_weights, weights)) < 0.01:
                break
            weights = new_weights

        return weights

    def search_hybrid(self, query: str, embedding: list[float] = None,
                      limit: int = 10, fusion: str = "adaptive",
                      kge_weight: float = 0.0) -> list[dict]:
        """混合搜索: 文本 + 向量(可选) + 图邻居 RRF 融合。

        三路融合策略:
        1. 文本搜索 (search_unified 已有): label/data/tags/kind
        2. 向量搜索 (可选): embedding KNN
        3. 图邻居加权: 邻居节点 bonus

        支持三种融合模式:
        - "rrf": 经典 Reciprocal Rank Fusion, k=60 (向后兼容)
        - "adaptive": QDAP-Lite 查询分类 + 共识奖励 + 小 k 值 (默认)
        - "wrrf": Weighted RRF, 用归一化分数置信度加权

        Args:
            query: 文本查询
            embedding: 可选查询向量
            limit: 返回数量上限
            fusion: 融合模式 ("adaptive" | "rrf" | "wrrf")

        Returns:
            list of {node_id, label, kind, score, sources} 按融合分数降序
        """
        # 收集已知标签用于查询分类
        known_labels = [r[0] for r in self.conn.execute(
            "SELECT DISTINCT label FROM nodes LIMIT 200"
        ).fetchall()]

        # QDAP-Lite 查询分类
        profile = self._classify_query(query, known_labels)

        # Trivial queries skip retrieval entirely
        if not profile.get("needs_retrieval", True):
            return []

        w_bm25, w_vec, w_graph = profile["weights"]
        K = profile["k"] if fusion == "adaptive" else 60

        rrf_scores: dict[str, float] = defaultdict(float)
        sources_map: dict[str, set] = defaultdict(set)
        route_rankings: list[list[str]] = []  # 用于 entropy 修正
        route_scores: list[dict[str, float]] = []  # 用于 WRRF

        # 路1: BM25 文本搜索 (fallback 到 search_unified)
        text_results = self.search_bm25(query, limit=limit * 3)
        if not text_results:
            text_results = [
                {"node_id": r["node"].id, "label": r["node"].label,
                 "kind": r["node"].kind, "score": r["score"],
                 "matched_fields": r["matched_fields"]}
                for r in self.search_unified(query, limit=limit * 3)
            ]
        text_ranking = [item["node_id"] for item in text_results]
        route_rankings.append(text_ranking)
        text_raw_scores = {item["node_id"]: item.get("score", 0.0) for item in text_results}
        route_scores.append(text_raw_scores)
        for rank, item in enumerate(text_results):
            nid = item["node_id"]
            rrf_scores[nid] += w_bm25 / (K + rank + 1)
            sources_map[nid].add("bm25" if "bm25" in item.get("matched_fields", []) else "text")

        # 路2: 向量搜索 (可选)
        vec_ranking = []
        if embedding is not None:
            try:
                vec_results = self.search_similar(embedding, limit=limit * 3)
                vec_ranking = [item["node_id"] for item in vec_results]
                vec_raw_scores = {item["node_id"]: item.get("score", item.get("distance", 0.0))
                                  for item in vec_results}
                route_rankings.append(vec_ranking)
                route_scores.append(vec_raw_scores)
                for rank, item in enumerate(vec_results):
                    nid = item["node_id"]
                    rrf_scores[nid] += w_vec / (K + rank + 1)
                    sources_map[nid].add("vector")
            except (ImportError, ValueError):
                route_rankings.append([])
                route_scores.append({})
        else:
            route_rankings.append([])
            route_scores.append({})

        # 路3: 图邻居加权 (以文本搜索 top 结果为种子, edge-weight-sorted)
        graph_ranking = []
        graph_raw_scores = {}
        if text_results:
            seed_id = text_results[0]["node_id"]
            if self.has_node(seed_id):
                # Weighted bonus: sort neighbors by edge weight (stronger = higher rank)
                neighbor_rows = self.conn.execute(
                    "SELECT n.id, e.weight as ew FROM nodes n"
                    " JOIN edges e ON n.id=e.target WHERE e.source=?"
                    " ORDER BY e.weight DESC",
                    (seed_id,)
                ).fetchall()
                graph_ranking = [r["id"] for r in neighbor_rows]
                max_ew = max((float(r["ew"] or 1.0) for r in neighbor_rows), default=1.0)
                graph_raw_scores = {
                    r["id"]: float(r["ew"] or 1.0) / max_ew for r in neighbor_rows
                }
                route_rankings.append(graph_ranking)
                route_scores.append(graph_raw_scores)
                # Weighted bonus: stronger edges contribute proportionally more
                # Edge weight 1.0 → 2x base RRF; 0.5 → 1.5x; 0.0 → 1x (backward compat)
                for rank, nid in enumerate(graph_ranking):
                    ew_bonus = 1.0 + graph_raw_scores.get(nid, 0.0)
                    rrf_scores[nid] += w_graph * ew_bonus / (K + rank + 1)
                    sources_map[nid].add("graph")
            else:
                route_rankings.append([])
                route_scores.append({})
        else:
            route_rankings.append([])
            route_scores.append({})

        # 路4: KGE (Knowledge Graph Embedding) 路由
        kge_ranking = []
        kge_raw_scores = {}
        if kge_weight > 0 and getattr(self, '_kge_trained', False):
            # 用文本搜索 top 结果作为 KGE 查询种子
            seed_id = text_results[0]["node_id"] if text_results else None
            if seed_id and self.has_node(seed_id):
                kge_results = self._kge_neighbors(seed_id, limit=limit * 3)
                kge_ranking = [r["node_id"] for r in kge_results]
                max_dist = max((r["kge_distance"] for r in kge_results), default=1.0)
                # Convert distance to similarity-like score (closer = higher)
                kge_raw_scores = {
                    r["node_id"]: 1.0 - (r["kge_distance"] / max_dist if max_dist > 0 else 0)
                    for r in kge_results
                }
                for rank, nid in enumerate(kge_ranking):
                    rrf_scores[nid] += kge_weight / (K + rank + 1)
                    sources_map[nid].add("kge")

        # Adaptive: entropy + skewness 权重修正
        if fusion == "adaptive" and len(route_rankings) >= 2:
            entropy_w = self._entropy_refine(route_rankings, [w_bm25, w_vec, w_graph])
            skew_w = self._score_skewness(route_scores)
            # Blend: 60% QDAP base + 20% entropy + 20% skewness
            refined = [
                0.6 * w + 0.2 * e + 0.2 * s
                for w, e, s in zip([w_bm25, w_vec, w_graph], entropy_w, skew_w)
            ]
            # 重新计算 rrf_scores 用修正后的权重 (仅在权重变化显著时)
            if max(abs(r - o) for r, o in zip(refined, [w_bm25, w_vec, w_graph])) > 0.05:
                rrf_scores = defaultdict(float)
                for rank, nid in enumerate(text_ranking):
                    rrf_scores[nid] += refined[0] / (K + rank + 1)
                if embedding is not None and vec_ranking:
                    for rank, nid in enumerate(vec_ranking):
                        rrf_scores[nid] += refined[1] / (K + rank + 1)
                if graph_ranking:
                    for rank, nid in enumerate(graph_ranking):
                        ew_bonus = 1.0 + graph_raw_scores.get(nid, 0.0)
                        rrf_scores[nid] += refined[2] * ew_bonus / (K + rank + 1)

        # WRRF: 置信度加权 (用归一化原始分数)
        if fusion == "wrrf":
            rrf_scores = defaultdict(float)
            for route_idx, raw_scores in enumerate(route_scores):
                if not raw_scores:
                    continue
                max_s = max(raw_scores.values()) if raw_scores else 1.0
                if max_s <= 0:
                    continue
                for rank, nid in enumerate(route_rankings[route_idx]):
                    conf = raw_scores.get(nid, 0.0) / max_s
                    rrf_scores[nid] += conf / (K + rank + 1)

        # 共识奖励 (Exp4Fuse 启发): 多路同时检索到的节点加分
        if fusion in ("adaptive", "wrrf"):
            for nid in list(rrf_scores.keys()):
                n_sources = len(sources_map[nid])
                if n_sources > 1:
                    rrf_scores[nid] *= (1.0 + 0.15 * (n_sources - 1))

        # 排序并构建结果
        ranked = sorted(rrf_scores.items(), key=lambda x: x[1], reverse=True)[:limit]
        results = []
        for nid, score in ranked:
            node = self.get_node(nid)
            if node:
                results.append({
                    "node_id": nid,
                    "label": node.label,
                    "kind": node.kind,
                    "score": round(score, 6),
                    "sources": sorted(sources_map[nid]),
                    "query_type": profile["type"] if fusion == "adaptive" else None,
                })
        return results

    def query_explain(self, query: str, embedding: list[float] = None,
                     limit: int = 10, fusion: str = "adaptive",
                     kge_weight: float = 0.0) -> dict:
        """Query explanation: detailed search plan + per-result score decomposition.

        Returns the same ranked results as search_hybrid, plus a full diagnostic
        plan showing how each retrieval path contributed to every result.

        Args:
            query: Text query
            embedding: Optional query vector
            limit: Result count
            fusion: Fusion mode ("adaptive" | "rrf" | "wrrf")
            kge_weight: KGE path weight

        Returns:
            {
                "query": str,
                "classification": {type, specificity, needs_retrieval},
                "weights": {bm25, vector, graph, kge},
                "fusion_mode": str,
                "k_constant": int,
                "paths": [
                    {"name": "bm25", "status": "active"|"skipped"|"fallback",
                     "result_count": int, "top_ids": [str], "elapsed_ms": float},
                    ...],
                "entropy_refinement": {applied: bool, original_weights, refined_weights} | None,
                "consensus_bonus": bool,
                "results": [
                    {"node_id", "label", "kind", "score", "sources",
                     "score_breakdown": {bm25: float, vector: float, graph: float, kge: float,
                                      consensus_bonus: float, raw_rrf: float}},
                    ...],
                "summary": {total_candidates, unique_sources_used, top_score, bottom_score}
            }
        """
        import time as _time
        t0 = _time.monotonic()

        known_labels = [r[0] for r in self.conn.execute(
            "SELECT DISTINCT label FROM nodes LIMIT 200"
        ).fetchall()]
        profile = self._classify_query(query, known_labels)

        plan = {
            "query": query,
            "classification": {
                "type": profile["type"],
                "specificity": profile["specificity"],
                "needs_retrieval": profile.get("needs_retrieval", True),
            },
            "weights": {},
            "fusion_mode": fusion,
            "k_constant": profile["k"] if fusion == "adaptive" else 60,
            "paths": [],
            "entropy_refinement": None,
            "consensus_bonus": fusion in ("adaptive", "wrrf"),
            "results": [],
            "summary": {"total_candidates": 0, "unique_sources_used": set(),
                         "top_score": 0.0, "bottom_score": 0.0},
        }

        # Trivial gate
        if not profile.get("needs_retrieval", True):
            plan["summary"]["total_candidates"] = 0
            plan["summary"]["unique_sources_used"] = []
            return plan

        w_bm25, w_vec, w_graph = profile["weights"]
        K = profile["k"] if fusion == "adaptive" else 60
        plan["weights"] = {"bm25": w_bm25, "vector": w_vec, "graph": w_graph,
                            "kge": kge_weight}

        # Per-node per-path score tracking
        node_path_scores: dict[str, dict[str, float]] = defaultdict(lambda: defaultdict(float))
        node_sources_map: dict[str, set] = defaultdict(set)

        route_rankings: list[list[str]] = []
        route_scores_list: list[dict[str, float]] = []

        # Path 1: BM25
        t1 = _time.monotonic()
        text_results = self.search_bm25(query, limit=limit * 3)
        bm25_status = "active"
        if not text_results:
            text_results = [
                {"node_id": r["node"].id, "label": r["node"].label,
                 "kind": r["node"].kind, "score": r["score"],
                 "matched_fields": r["matched_fields"]}
                for r in self.search_unified(query, limit=limit * 3)
            ]
            bm25_status = "fallback"
        t1_elapsed = (_time.monotonic() - t1) * 1000
        text_ranking = [item["node_id"] for item in text_results]
        route_rankings.append(text_ranking)
        text_raw_scores = {item["node_id"]: item.get("score", 0.0) for item in text_results}
        route_scores_list.append(text_raw_scores)
        for rank, item in enumerate(text_results):
            nid = item["node_id"]
            s = w_bm25 / (K + rank + 1)
            node_path_scores[nid]["bm25"] = s
            node_sources_map[nid].add("bm25" if "bm25" in item.get("matched_fields", []) else "text")
        plan["paths"].append({
            "name": "bm25", "status": bm25_status,
            "result_count": len(text_results),
            "top_ids": text_ranking[:5],
            "elapsed_ms": round(t1_elapsed, 2),
        })

        # Path 2: Vector
        vec_ranking = []
        vec_raw_scores = {}
        t2 = _time.monotonic()
        if embedding is not None:
            try:
                vec_results = self.search_similar(embedding, limit=limit * 3)
                vec_ranking = [item["node_id"] for item in vec_results]
                vec_raw_scores = {item["node_id"]: item.get("score", item.get("distance", 0.0))
                                  for item in vec_results}
                route_rankings.append(vec_ranking)
                route_scores_list.append(vec_raw_scores)
                for rank, item in enumerate(vec_results):
                    nid = item["node_id"]
                    s = w_vec / (K + rank + 1)
                    node_path_scores[nid]["vector"] = s
                    node_sources_map[nid].add("vector")
                t2_elapsed = (_time.monotonic() - t2) * 1000
                plan["paths"].append({
                    "name": "vector", "status": "active",
                    "result_count": len(vec_results),
                    "top_ids": vec_ranking[:5],
                    "elapsed_ms": round(t2_elapsed, 2),
                })
            except (ImportError, ValueError):
                route_rankings.append([])
                route_scores_list.append({})
                plan["paths"].append({"name": "vector", "status": "skipped",
                                       "result_count": 0, "top_ids": [],
                                       "elapsed_ms": 0.0})
        else:
            route_rankings.append([])
            route_scores_list.append({})
            plan["paths"].append({"name": "vector", "status": "skipped",
                                   "result_count": 0, "top_ids": [],
                                   "elapsed_ms": 0.0})

        # Path 3: Graph
        graph_ranking = []
        graph_raw_scores = {}
        t3 = _time.monotonic()
        if text_results:
            seed_id = text_results[0]["node_id"]
            if self.has_node(seed_id):
                neighbor_rows = self.conn.execute(
                    "SELECT n.id, e.weight as ew FROM nodes n"
                    " JOIN edges e ON n.id=e.target WHERE e.source=?"
                    " ORDER BY e.weight DESC",
                    (seed_id,)
                ).fetchall()
                graph_ranking = [r["id"] for r in neighbor_rows]
                max_ew = max((float(r["ew"] or 1.0) for r in neighbor_rows), default=1.0)
                graph_raw_scores = {
                    r["id"]: float(r["ew"] or 1.0) / max_ew for r in neighbor_rows
                }
                route_rankings.append(graph_ranking)
                route_scores_list.append(graph_raw_scores)
                for rank, nid in enumerate(graph_ranking):
                    ew_bonus = 1.0 + graph_raw_scores.get(nid, 0.0)
                    s = w_graph * ew_bonus / (K + rank + 1)
                    node_path_scores[nid]["graph"] = s
                    node_sources_map[nid].add("graph")
                t3_elapsed = (_time.monotonic() - t3) * 1000
                plan["paths"].append({
                    "name": "graph", "status": "active",
                    "result_count": len(graph_ranking),
                    "top_ids": graph_ranking[:5],
                    "elapsed_ms": round(t3_elapsed, 2),
                })
            else:
                route_rankings.append([])
                route_scores_list.append({})
                plan["paths"].append({"name": "graph", "status": "skipped",
                                       "result_count": 0, "top_ids": [],
                                       "elapsed_ms": round((_time.monotonic() - t3) * 1000, 2)})
        else:
            route_rankings.append([])
            route_scores_list.append({})
            plan["paths"].append({"name": "graph", "status": "skipped",
                                   "result_count": 0, "top_ids": [],
                                   "elapsed_ms": 0.0})

        # Path 4: KGE
        kge_ranking = []
        if kge_weight > 0 and getattr(self, '_kge_trained', False):
            t4 = _time.monotonic()
            seed_id = text_results[0]["node_id"] if text_results else None
            if seed_id and self.has_node(seed_id):
                kge_results = self._kge_neighbors(seed_id, limit=limit * 3)
                kge_ranking = [r["node_id"] for r in kge_results]
                for rank, nid in enumerate(kge_ranking):
                    node_path_scores[nid]["kge"] = kge_weight / (K + rank + 1)
                    node_sources_map[nid].add("kge")
                t4_elapsed = (_time.monotonic() - t4) * 1000
                plan["paths"].append({
                    "name": "kge", "status": "active",
                    "result_count": len(kge_ranking),
                    "top_ids": kge_ranking[:5],
                    "elapsed_ms": round(t4_elapsed, 2),
                })
            else:
                plan["paths"].append({"name": "kge", "status": "skipped",
                                       "result_count": 0, "top_ids": [],
                                       "elapsed_ms": 0.0})
        else:
            plan["paths"].append({"name": "kge", "status": "skipped",
                                   "result_count": 0, "top_ids": [],
                                   "elapsed_ms": 0.0})

        # Entropy refinement
        effective_w = [w_bm25, w_vec, w_graph]
        if fusion == "adaptive" and len(route_rankings) >= 2:
            entropy_w = self._entropy_refine(route_rankings, [w_bm25, w_vec, w_graph])
            skew_w = self._score_skewness(route_scores_list)
            refined = [0.6 * w + 0.2 * e + 0.2 * s
                        for w, e, s in zip([w_bm25, w_vec, w_graph], entropy_w, skew_w)]
            if max(abs(r - o) for r, o in zip(refined, [w_bm25, w_vec, w_graph])) > 0.05:
                plan["entropy_refinement"] = {
                    "applied": True,
                    "original_weights": {"bm25": round(w_bm25, 4), "vector": round(w_vec, 4), "graph": round(w_graph, 4)},
                    "refined_weights": {"bm25": round(refined[0], 4), "vector": round(refined[1], 4), "graph": round(refined[2], 4)},
                }
                effective_w = refined
                # Recalculate with refined weights
                node_path_scores = defaultdict(lambda: defaultdict(float))
                for rank, nid in enumerate(text_ranking):
                    node_path_scores[nid]["bm25"] = refined[0] / (K + rank + 1)
                if vec_ranking:
                    for rank, nid in enumerate(vec_ranking):
                        node_path_scores[nid]["vector"] = refined[1] / (K + rank + 1)
                if graph_ranking:
                    for rank, nid in enumerate(graph_ranking):
                        ew_bonus = 1.0 + graph_raw_scores.get(nid, 0.0)
                        node_path_scores[nid]["graph"] = refined[2] * ew_bonus / (K + rank + 1)
            else:
                plan["entropy_refinement"] = {"applied": False, "original_weights": None, "refined_weights": None}
        else:
            plan["entropy_refinement"] = None

        # WRRF recalculates with confidence weighting
        if fusion == "wrrf":
            node_path_scores = defaultdict(lambda: defaultdict(float))
            for route_idx, raw_scores in enumerate(route_scores_list):
                if not raw_scores:
                    continue
                max_s = max(raw_scores.values()) if raw_scores else 1.0
                if max_s <= 0:
                    continue
                path_name = ["bm25", "vector", "graph"][route_idx] if route_idx < 3 else f"path_{route_idx}"
                for rank, nid in enumerate(route_rankings[route_idx]):
                    conf = raw_scores.get(nid, 0.0) / max_s
                    node_path_scores[nid][path_name] = conf / (K + rank + 1)

        # Build final results with per-node breakdown
        all_nids = set(node_path_scores.keys())
        final_scores = {}
        for nid in all_nids:
            raw_rrf = sum(node_path_scores[nid].values())
            # Consensus bonus
            n_src = len(node_sources_map[nid])
            bonus = 0.0
            if fusion in ("adaptive", "wrrf") and n_src > 1:
                bonus = raw_rrf * 0.15 * (n_src - 1)
            final_scores[nid] = raw_rrf + bonus

        ranked = sorted(final_scores.items(), key=lambda x: x[1], reverse=True)[:limit]
        results = []
        for nid, score in ranked:
            node = self.get_node(nid)
            if not node:
                continue
            breakdown = dict(node_path_scores[nid])
            n_src = len(node_sources_map[nid])
            bonus = 0.0
            if fusion in ("adaptive", "wrrf") and n_src > 1:
                bonus = sum(breakdown.values()) * 0.15 * (n_src - 1)
            breakdown["consensus_bonus"] = round(bonus, 6)
            breakdown["raw_rrf"] = round(sum(node_path_scores[nid].values()), 6)
            results.append({
                "node_id": nid,
                "label": node.label,
                "kind": node.kind,
                "score": round(score, 6),
                "sources": sorted(node_sources_map[nid]),
                "score_breakdown": {k: round(v, 6) for k, v in breakdown.items()},
            })

        all_sources = set()
        for s in node_sources_map.values():
            all_sources.update(s)
        plan["results"] = results
        plan["summary"] = {
            "total_candidates": len(all_nids),
            "unique_sources_used": sorted(all_sources),
            "top_score": round(results[0]["score"], 6) if results else 0.0,
            "bottom_score": round(results[-1]["score"], 6) if results else 0.0,
            "total_elapsed_ms": round((_time.monotonic() - t0) * 1000, 2),
        }
        return plan

    def remove_embedding(self, node_id: str) -> bool:
        """删除节点的向量嵌入。返回是否实际删除了。"""
        self._ensure_rowid_table()
        row = self.conn.execute("SELECT rowid FROM node_rowids WHERE node_id = ?", (node_id,)).fetchone()
        if not row:
            return False
        cur = self.conn.execute("DELETE FROM vec_nodes WHERE rowid = ?", (row["rowid"],))
        self.conn.execute("DELETE FROM node_rowids WHERE node_id = ?", (node_id,))
        self.conn.commit()
        return cur.rowcount > 0

    def embedding_count(self) -> int:
        """返回已存储嵌入的数量。"""
        try:
            row = self.conn.execute("SELECT COUNT(*) as c FROM vec_nodes").fetchone()
            return row["c"] if row else 0
        except sqlite3.OperationalError:
            return 0

    def add_embeddings_batch(self, items: list[tuple[str, list[float]]]) -> int:
        """批量添加嵌入。items = [(node_id, embedding), ...]

        Returns:
            成功添加的数量
        """
        try:
            import sqlite_vec
        except ImportError:
            raise ImportError("sqlite-vec is required. Install: pip install sqlite-vec")

        if not items:
            return 0

        self._ensure_rowid_table()
        dims = len(items[0][1])
        self._ensure_vec_table(dims)

        count = 0
        for node_id, embedding in items:
            if not self.has_node(node_id):
                continue
            rowid = self._node_to_rowid(node_id)
            vec = sqlite_vec.serialize_float32(embedding)
            self.conn.execute("DELETE FROM vec_nodes WHERE rowid = ?", (rowid,))
            self.conn.execute("INSERT INTO vec_nodes(rowid, embedding) VALUES (?, ?)", (rowid, vec))
            count += 1
        self.conn.commit()
        return count

    def search_similar_to_node(self, node_id: str, limit: int = 10) -> list[dict]:
        """查找与指定节点最相似的其他节点 (基于嵌入向量)。

        Args:
            node_id: 种子节点 ID (必须有嵌入)
            limit: 返回数量上限

        Returns:
            list of {node_id, label, kind, distance, score} 排除自身

        Raises:
            ValueError: 如果节点不存在或没有嵌入
        """
        try:
            import sqlite_vec
        except ImportError:
            raise ImportError("sqlite-vec is required. Install: pip install sqlite-vec")

        self._ensure_rowid_table()
        row = self.conn.execute("SELECT rowid FROM node_rowids WHERE node_id = ?", (node_id,)).fetchone()
        if not row:
            raise ValueError(f"No embedding found for node: {node_id}")

        seed_rowid = row["rowid"]
        # 使用子查询直接获取种子向量并匹配
        rows = self.conn.execute(
            """
            SELECT v.rowid, v.distance, n.id, n.label, n.kind, n.weight
            FROM vec_nodes AS v
            JOIN node_rowids AS r ON v.rowid = r.rowid
            JOIN nodes AS n ON r.node_id = n.id
            WHERE v.embedding MATCH (
                SELECT embedding FROM vec_nodes WHERE rowid = ?
            ) AND v.k = ?
            ORDER BY v.distance
            """,
            (seed_rowid, limit + 1)
        ).fetchall()
        results = []
        for r in rows:
            if r["id"] == node_id:
                continue
            dist = r["distance"]
            score = 1.0 / (1.0 + dist)
            results.append({
                "node_id": r["id"],
                "label": r["label"],
                "kind": r["kind"],
                "distance": round(dist, 6),
                "score": round(score, 6),
                "weight": r["weight"],
            })
        return results[:limit]

    def vector_stats(self) -> dict:
        """返回向量存储的统计信息。"""
        count = self.embedding_count()
        if count == 0:
            return {"count": 0, "has_vectors": False}
        node_count = self.conn.execute("SELECT COUNT(*) as c FROM nodes").fetchone()["c"]
        coverage = round(count / node_count, 4) if node_count > 0 else 0.0
        # 维度
        dims = getattr(self, '_vec_dims', None)
        if not dims:
            row = self.conn.execute("SELECT sql FROM sqlite_master WHERE name='vec_nodes'").fetchone()
            if row:
                import re
                m = re.search(r'float\[(\d+)\]', row["sql"])
                dims = int(m.group(1)) if m else None
        return {
            "count": count,
            "has_vectors": True,
            "dimensions": dims,
            "node_count": node_count,
            "coverage": coverage,
        }

    def has_embedding(self, node_id: str) -> bool:
        """检查节点是否有嵌入向量。"""
        self._ensure_rowid_table()
        row = self.conn.execute("SELECT rowid FROM node_rowids WHERE node_id = ?", (node_id,)).fetchone()
        if not row:
            return False
        vec_row = self.conn.execute("SELECT rowid FROM vec_nodes WHERE rowid = ?", (row["rowid"],)).fetchone()
        return vec_row is not None

    def update_embedding(self, node_id: str, embedding: list[float]) -> bool:
        """更新已有嵌入向量。如果节点没有嵌入则创建。返回是否成功。"""
        self.remove_embedding(node_id)
        self.add_embedding(node_id, embedding)
        return True

    def remove_embeddings_batch(self, node_ids: list[str]) -> int:
        """批量删除嵌入向量。返回实际删除数量。"""
        removed = 0
        for nid in node_ids:
            if self.remove_embedding(nid):
                removed += 1
        return removed

    def search_similar_by_kind(self, embedding: list[float], kind: str, limit: int = 10) -> list[dict]:
        """在特定 kind 的节点中搜索相似向量。"""
        all_results = self.search_similar(embedding, limit=limit * 5)
        return [r for r in all_results if self.get_node(r["node_id"]).kind == kind][:limit]

    def search_similar_by_tag(self, embedding: list[float], tag: str, limit: int = 10) -> list[dict]:
        """在特定标签的节点中搜索相似向量。"""
        tagged = self.search_by_tag(tag)
        tagged_ids = {n.id for n in tagged}
        if not tagged_ids:
            return []
        all_results = self.search_similar(embedding, limit=limit * 5)
        return [r for r in all_results if r["node_id"] in tagged_ids][:limit]

    # ── GraphRAG 统一检索 ─────────────────────────────────

    def search_graphrag(self, query: str, mode: str = "hybrid",
                        embedding: list[float] = None,
                        limit: int = 10,
                        expand_hops: int = 1) -> list[dict]:
        """GraphRAG-style unified retrieval with mode selection.

        Modes:
        - "naive": Direct text search (BM25/search_unified)
        - "local": Text search + 1-hop graph expansion
        - "global": Community-level search (find relevant communities first)
        - "hybrid": Full 3-way RRF fusion (text + vector + graph) via search_hybrid

        Each result includes: node_id, label, kind, score, sources, community (if detected).

        Args:
            query: Natural language query
            mode: Retrieval mode (naive/local/global/hybrid)
            embedding: Optional query vector for hybrid mode
            limit: Max results
            expand_hops: Graph expansion depth for local mode

        Returns:
            list of dicts sorted by score descending
        """
        if mode == "hybrid":
            results = self.search_hybrid(query, embedding=embedding, limit=limit)
            for r in results:
                r.setdefault("sources", ["hybrid"])
            return results

        if mode == "naive":
            results = self.search_bm25(query, limit=limit)
            if not results:
                results = [
                    {"node_id": r["node"].id, "label": r["node"].label,
                     "kind": r["node"].kind, "score": r["score"],
                     "sources": ["text"]}
                    for r in self.search_unified(query, limit=limit)
                ]
            return results

        if mode == "local":
            # Step 1: find seed nodes via text search
            seeds = self.search_bm25(query, limit=max(limit // 2, 3))
            if not seeds:
                seeds = [
                    {"node_id": r["node"].id, "label": r["node"].label,
                     "kind": r["node"].kind, "score": r["score"]}
                    for r in self.search_unified(query, limit=max(limit // 2, 3))
                ]
            if not seeds:
                return []
            # Step 2: expand with graph neighbors
            expanded = {}
            for seed in seeds:
                nid = seed["node_id"]
                expanded[nid] = seed
                expanded[nid]["sources"] = ["text"]
                # Get neighbors
                for nb in self.neighbors(nid, depth=expand_hops):
                    if nb.id not in expanded:
                        expanded[nb.id] = {
                            "node_id": nb.id, "label": nb.label,
                            "kind": nb.kind, "score": seed["score"] * 0.5,
                            "sources": ["graph"]
                        }
                    else:
                        if "graph" not in expanded[nb.id].get("sources", []):
                            expanded[nb.id]["sources"].append("graph")
            results = sorted(expanded.values(), key=lambda x: x.get("score", 0), reverse=True)
            return results[:limit]

        if mode == "global":
            # Community-level search: find which communities are relevant
            # Use Leiden for better community detection
            comm_map = self.detect_communities_leiden()
            if not comm_map:
                return self.search_graphrag(query, mode="naive", limit=limit)
            communities = {}
            for nid, cid in comm_map.items():
                communities.setdefault(cid, []).append(nid)
            summaries = self.community_summary(communities=communities)
            # Score communities by tag/keyword overlap with query
            query_lower = query.lower()
            scored_communities = []
            for summary in summaries:
                score = 0.0
                for tag, freq in summary.get("top_tags", []):
                    if tag.lower() in query_lower or query_lower in tag.lower():
                        score += freq * 2
                for member in summary.get("top_members", []):
                    if query_lower in member.get("label", "").lower():
                        score += 3
                scored_communities.append((summary["id"], score, summary))
            scored_communities.sort(key=lambda x: x[1], reverse=True)
            # Take top community and return its members
            if not scored_communities or scored_communities[0][1] == 0:
                return self.search_graphrag(query, mode="local", limit=limit,
                                           embedding=embedding) if embedding else \
                       self.search_graphrag(query, mode="naive", limit=limit)
            best_comm_id = scored_communities[0][0]
            node_ids = communities[best_comm_id]
            # Return community members sorted by weight
            placeholders = ",".join("?" * len(node_ids))
            rows = self.conn.execute(
                f"SELECT id, label, kind, weight FROM nodes WHERE id IN ({placeholders}) "
                "ORDER BY weight DESC LIMIT ?",
                (*node_ids, limit)
            ).fetchall()
            return [
                {"node_id": r["id"], "label": r["label"],
                 "kind": r["kind"], "score": r["weight"],
                 "sources": ["community"],
                 "community": best_comm_id}
                for r in rows
            ]

        # Unknown mode: fallback to hybrid
        return self.search_graphrag(query, mode="hybrid", embedding=embedding, limit=limit)

    def random_walk(self, start_id: str, steps: int = 10,
                    restart_prob: float = 0.0,
                    weight_key: str = None) -> list[str]:
        """Random walk on the graph from *start_id*.

        At each step, move to a random neighbor (weighted by edge weight
        if *weight_key* given).  With probability *restart_prob*, teleport
        back to the start node (PageRank-style random walk with restart).

        Useful for:
          - Graph sampling (node2vec / DeepWalk embedding prep)
          - Personalized PageRank approximation
          - GraphRAG local exploration

        Args:
            start_id: Starting node ID.
            steps: Number of steps to take.
            restart_prob: Probability of teleporting back to start (0-1).
            weight_key: Edge property key for weighted random selection.
                        If None, uniform random.

        Returns:
            List of visited node IDs (length ≤ steps + 1).
            Empty list if start_id not found.
        """
        import random as _rng
        _r = _rng.Random(42)

        existing = self.conn.execute(
            "SELECT id FROM nodes WHERE id = ?", (start_id,)).fetchone()
        if not existing:
            return []

        path = [start_id]
        current = start_id

        for _ in range(steps):
            if restart_prob > 0 and _r.random() < restart_prob:
                current = start_id
                path.append(current)
                continue

            rows = self.conn.execute(
                "SELECT target, weight FROM edges WHERE source = ? "
                "UNION "
                "SELECT source, weight FROM edges WHERE target = ?",
                (current, current)).fetchall()

            if not rows:
                break

            if weight_key and weight_key != "weight":
                # Look up custom property
                neighbors = []
                for r in rows:
                    props = self.get_edge_properties(
                        str(r["target"]) if str(r["target"]) != current else str(r["source"]),
                        current)
                    w = props.get(weight_key, float(r["weight"] or 1.0))
                    nb = str(r["target"]) if str(r["target"]) != current else str(r["source"])
                    neighbors.append((nb, w))
            else:
                neighbors = [(str(r["target"]) if str(r["target"]) != current
                             else str(r["source"]),
                             float(r["weight"] or 1.0)) for r in rows]

            total_w = sum(w for _, w in neighbors)
            if total_w <= 0:
                break

            pick = _r.random() * total_w
            cumulative = 0.0
            for nb, w in neighbors:
                cumulative += w
                if cumulative >= pick:
                    current = nb
                    break
            else:
                current = neighbors[-1][0]

            path.append(current)

        return path

    def walk_statistics(self, *, num_walks: int = 100, steps: int = 20,
                         restart_prob: float = 0.15,
                         seed: int = 42) -> dict:
        """Run multiple random walks and aggregate statistics.

        Provides insight into graph connectivity, node accessibility,
        and structural properties via random walk sampling.

        Args:
            num_walks: Number of random walks to perform.
            steps: Steps per walk.
            restart_prob: Probability of restarting at each step.
            seed: Random seed for reproducibility.

        Returns:
            dict with keys:
              - avg_unique_ratio: avg fraction of unique nodes per walk
              - avg_revisit_step: avg first-revisit step (-1 if none)
              - coverage: total unique nodes visited / total nodes
              - most_visited: list of (node_id, visit_count) top 10
              - dead_end_rate: fraction of walks that hit dead ends
              - walk_lengths: list of actual walk lengths
        """
        import random as _rng
        _r = _rng.Random(seed)

        all_nodes = [r["id"] for r in
                      self.conn.execute("SELECT id FROM nodes").fetchall()]
        total_nodes = len(all_nodes)
        if total_nodes == 0:
            return {"avg_unique_ratio": 0.0, "avg_revisit_step": -1,
                    "coverage": 0.0, "most_visited": [],
                    "dead_end_rate": 0.0, "walk_lengths": []}

        visit_counts: dict[str, int] = {}
        unique_ratios = []
        revisit_steps = []
        dead_ends = 0
        walk_lengths = []
        all_visited = set()

        for _ in range(num_walks):
            start = _r.choice(all_nodes)
            path = self.random_walk(start, steps=steps,
                                     restart_prob=restart_prob)
            walk_lengths.append(len(path))
            if len(path) < steps + 1:
                dead_ends += 1

            seen = set()
            first_revisit = -1
            for i, nid in enumerate(path):
                visit_counts[nid] = visit_counts.get(nid, 0) + 1
                all_visited.add(nid)
                if nid in seen and first_revisit == -1:
                    first_revisit = i
                seen.add(nid)

            unique_ratios.append(len(seen) / len(path) if path else 0.0)
            revisit_steps.append(first_revisit)

        top_visited = sorted(visit_counts.items(), key=lambda x: -x[1])[:10]
        avg_revisit = [s for s in revisit_steps if s >= 0]

        return {
            "avg_unique_ratio": round(sum(unique_ratios) / len(unique_ratios), 4) if unique_ratios else 0.0,
            "avg_revisit_step": round(sum(avg_revisit) / len(avg_revisit), 2) if avg_revisit else -1,
            "coverage": round(len(all_visited) / total_nodes, 4),
            "most_visited": top_visited,
            "dead_end_rate": round(dead_ends / num_walks, 4),
            "walk_lengths": walk_lengths,
        }

    def graph_sample(self, start_id: str, max_nodes: int = 50,
                     strategy: str = "bfs") -> list[str]:
        """Extract a representative subgraph sample.

        Strategies:
          - ``bfs``: Breadth-first expansion from start_id.
          - ``dfs``: Depth-first expansion.
          - ``random_walk``: Random walk sampling (good for preserving
            structural properties with fewer nodes).

        Args:
            start_id: Seed node for sampling.
            max_nodes: Maximum nodes to include.
            strategy: Sampling strategy.

        Returns:
            List of node IDs in the sample (including start_id).
        """
        if strategy == "bfs":
            visited = []
            seen = {start_id}
            queue = [start_id]
            while queue and len(visited) < max_nodes:
                nid = queue.pop(0)
                if nid in seen and nid not in visited:
                    pass
                if nid not in visited:
                    visited.append(nid)
                rows = self.conn.execute(
                    "SELECT target FROM edges WHERE source = ? "
                    "UNION SELECT source FROM edges WHERE target = ?",
                    (nid, nid)).fetchall()
                for r in rows:
                    nb = str(r[0])
                    if nb not in seen:
                        seen.add(nb)
                        queue.append(nb)
            return visited[:max_nodes]

        elif strategy == "dfs":
            return self.dfs_order(start_id, max_depth=max_nodes)[:max_nodes]

        else:  # random_walk
            walk = self.random_walk(start_id, steps=max_nodes * 3)
            seen = []
            for nid in walk:
                if nid not in seen:
                    seen.append(nid)
                if len(seen) >= max_nodes:
                    break
            return seen

    def smart_query_route(self, query: str, embedding: list[float] = None,
                          limit: int = 10) -> dict:
        """Automatically choose the best GraphRAG mode based on query analysis.

        Heuristics (based on ICLR 2026 GraphRAG-Bench findings):
        - Single-entity lookups → naive (RAG beats GraphRAG on simple tasks)
        - Multi-entity / relational → local (graph expansion helps)
        - Aggregation / "all" / "every" → global (community-level)
        - Complex / multi-hop with embedding → hybrid (RRF fusion)

        Returns:
            dict with keys:
              - mode: chosen mode (naive/local/global/hybrid)
              - results: list of result dicts
              - reason: explanation for the routing decision
              - query_traits: analysed query characteristics
        """
        import re

        q_lower = query.lower().strip()
        traits = {
            "word_count": len(query.split()),
            "has_multiple_entities": False,
            "has_aggregation": False,
            "has_temporal": False,
            "has_relational": False,
        }

        # Aggregation cues
        agg_patterns = ["all", "every", "summary", "summarize", "overview",
                        "how many", "count", "total", "list all", "which.*all"]
        traits["has_aggregation"] = any(re.search(p, q_lower) for p in agg_patterns)

        # Temporal cues
        temporal_patterns = ["when", "latest", "oldest", "recent", "before",
                             "after", "since", "until", "timeline", "history"]
        traits["has_temporal"] = any(re.search(p, q_lower) for p in temporal_patterns)

        # Relational cues
        rel_patterns = ["relate", "connect", "link", "between", "path",
                        "neighbor", "influence", "depend", "parent", "child",
                        "cause", "effect"]
        traits["has_relational"] = any(re.search(p, q_lower) for p in rel_patterns)

        # Multi-entity: capitalised words or quoted strings as entity hints
        cap_words = re.findall(r'\b[A-Z][a-z]+\b', query)
        quoted = re.findall(r'["\']([^"\']+)["\']', query)
        entities = cap_words + quoted
        traits["has_multiple_entities"] = len(set(e.lower() for e in entities)) >= 2

        # --- Routing decision (priority order) ---
        if traits["has_aggregation"]:
            mode = "global"
            reason = "Aggregation cue detected → community-level search"
        elif traits["has_multiple_entities"] and traits["has_relational"]:
            mode = "local"
            reason = "Multi-entity + relational cues → graph expansion"
        elif embedding is not None and (
            traits["has_temporal"] or traits["has_multiple_entities"]
            or traits["word_count"] > 8
        ):
            mode = "hybrid"
            reason = "Complex query + embedding available → RRF fusion"
        elif traits["word_count"] <= 3 and not traits["has_relational"]:
            mode = "naive"
            reason = "Short lookup query → direct text search"
        elif traits["has_relational"]:
            mode = "local"
            reason = "Relational cue → graph expansion"
        else:
            mode = "hybrid" if embedding is not None else "naive"
            reason = f"Default → {mode} (embedding {'available' if embedding else 'absent'})"

        results = self.search_graphrag(
            query, mode=mode, embedding=embedding, limit=limit)

        return {
            "mode": mode,
            "results": results,
            "reason": reason,
            "query_traits": traits,
        }

    # ── 高级图分析 ────────────────────────────────────────

    def closeness_vitality(self, node_id: str) -> float | None:
        """计算节点删除后 Wiener 指数的变化量。

        closeness_vitality = W(G\\{v}) - W(G)
        正值表示该节点对图连通性重要（删除后距离增加），
        负值表示该节点是瓶颈（删除后图更紧凑或断裂）。

        Args:
            node_id: 节点 ID

        Returns:
            Wiener 指数变化量，或 None（节点不存在）
        """
        if not self.has_node(node_id):
            return None

        # W(G)
        w_before = self.wiener_index() or 0

        # W(G\{v}) — 临时删除节点
        node_row = self.conn.execute("SELECT * FROM nodes WHERE id=?", (node_id,)).fetchone()
        edges_out = self.conn.execute("SELECT * FROM edges WHERE source=?", (node_id,)).fetchall()
        edges_in = self.conn.execute("SELECT * FROM edges WHERE target=?", (node_id,)).fetchall()

        self.conn.execute("DELETE FROM nodes WHERE id=?", (node_id,))
        self.conn.execute("DELETE FROM edges WHERE source=? OR target=?", (node_id, node_id))
        self.conn.commit()

        w_after = self.wiener_index() or 0

        # 恢复
        self.conn.execute(
            "INSERT INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
            (node_row["id"], node_row["label"], node_row["kind"], node_row["data"],
             node_row["created"], node_row["accessed"], node_row["weight"], node_row["tags"]))
        for e in edges_out + edges_in:
            self.conn.execute(
                "INSERT OR IGNORE INTO edges (source,target,relation,weight) VALUES (?,?,?,?)",
                (e["source"], e["target"], e["relation"], e["weight"]))
        self.conn.commit()

        return w_after - w_before

    def spectral_radius(self) -> float | None:
        """计算邻接矩阵的谱半径（最大特征值的绝对值）。

        使用幂迭代法（power iteration）求最大特征值。
        谱半径反映了图的"活跃程度":
        - 高谱半径 = 强连通、hub-hub 连接多
        - 低谱半径 = 稀疏、长链状结构

        Returns:
            谱半径，或 None（空图）
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n == 0:
            return None

        idx = {nid: i for i, nid in enumerate(node_ids)}

        # 构建对称邻接表（无向处理）
        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j)
                adj_sym[j].add(i)

        # 幂迭代（Power Iteration on A²）
        # 使用 A² 避免负特征值导致的振荡
        import random
        random.seed(42)
        v = [random.random() for _ in range(n)]
        norm = math.sqrt(sum(x * x for x in v)) or 1.0
        v = [x / norm for x in v]

        eigenvalue = 0.0
        for _ in range(300):
            # v_new = A² @ v (两步)
            w = [sum(v[j] for j in adj_sym[i]) for i in range(n)]
            v_new = [sum(w[j] for j in adj_sym[i]) for i in range(n)]

            norm_new = math.sqrt(sum(x * x for x in v_new)) or 1e-15
            # 特征值估计 = ||A²v|| / ||v|| 的平方根
            new_eigenvalue = math.sqrt(norm_new)  # sqrt(||A²v||) ≈ |λ_max|
            v_new = [x / norm_new for x in v_new]

            if abs(new_eigenvalue - eigenvalue) < 1e-9:
                eigenvalue = new_eigenvalue
                break
            eigenvalue = new_eigenvalue
            v = v_new

        return abs(eigenvalue)

    def minimum_spanning_tree(self) -> list[dict] | None:
        """使用 Kruskal 算法计算最小生成树（MST）。

        对无向图（忽略边的方向）执行 Kruskal 算法，返回权重最小的生成树边集。
        使用 Union-Find（路径压缩 + 按秩合并）实现高效连通分量检测。

        Returns:
            MST 边列表 [{source, target, relation, weight}, ...]，按权重升序；
            None（图空或不连通）
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n < 2:
            return None

        # 收集所有边（无向化：保留 source < target 的唯一边，取最小权重）
        raw_edges = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges ORDER BY weight ASC"
        ).fetchall()

        edge_map: dict[tuple, dict] = {}
        for e in raw_edges:
            key = (min(e["source"], e["target"]), max(e["source"], e["target"]))
            if key not in edge_map or e["weight"] < edge_map[key]["weight"]:
                edge_map[key] = dict(source=e["source"], target=e["target"],
                                     relation=e["relation"], weight=e["weight"])

        edges_sorted = sorted(edge_map.values(), key=lambda e: e["weight"])

        # Union-Find
        parent = {nid: nid for nid in node_ids}
        rank = {nid: 0 for nid in node_ids}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path compression
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True

        mst = []
        for e in edges_sorted:
            if union(e["source"], e["target"]):
                mst.append(e)
                if len(mst) == n - 1:
                    break

        # 检查连通性
        if len(mst) < n - 1:
            return None

        return mst

    def mst_weight(self) -> float | None:
        """计算最小生成树的总权重。

        Returns:
            MST 总权重，或 None（图空或不连通）
        """
        mst = self.minimum_spanning_tree()
        if mst is None:
            return None
        return sum(e["weight"] for e in mst)

    # ── 谱分析（代数连通度 + Fiedler 向量）────────────────

    def algebraic_connectivity(self) -> float | None:
        """计算图的代数连通度（Fiedler value）——拉普拉斯矩阵的第二小特征值。

        代数连通度衡量图的整体连通强度:
        - 0 = 图不连通
        - 大值 = 强连通（移除少量边不会断开图）
        - 小正数 = 脆弱连通

        Returns:
            代数连通度，或 None（空图/单节点）
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n < 2:
            return None

        idx = {nid: i for i, nid in enumerate(node_ids)}
        degree = [0] * n
        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j)
                adj_sym[j].add(i)
                degree[i] += 1
                degree[j] += 1

        # 构建拉普拉斯矩阵 L = D - A
        L = [[0.0] * n for _ in range(n)]
        for i in range(n):
            L[i][i] = float(degree[i])
            for j in adj_sym[i]:
                L[i][j] = -1.0

        eigenvalues = self._sym_eigenvalues(L)
        eigenvalues.sort()
        # 代数连通度 = 第二小特征值
        # 连通图: 第二小 > 0; 不连通图: 第二小 = 0
        if len(eigenvalues) < 2:
            return None
        return max(0.0, eigenvalues[1])

    def _sym_eigenvalues(self, M: list[list[float]], max_iter: int = 300) -> list[float]:
        """雅可比旋转求实对称矩阵全部特征值。"""
        n = len(M)
        A = [row[:] for row in M]
        for _ in range(max_iter):
            p, q = 0, 1
            max_val = abs(A[0][1])
            for i in range(n):
                for j in range(i + 1, n):
                    if abs(A[i][j]) > max_val:
                        max_val = abs(A[i][j])
                        p, q = i, j
            if max_val < 1e-12:
                break
            if abs(A[p][p] - A[q][q]) < 1e-15:
                theta = math.pi / 4
            else:
                theta = 0.5 * math.atan2(2 * A[p][q], A[p][p] - A[q][q])
            c, s = math.cos(theta), math.sin(theta)
            for i in range(n):
                if i == p or i == q:
                    continue
                aip, aiq = A[i][p], A[i][q]
                A[i][p] = c * aip + s * aiq; A[p][i] = A[i][p]
                A[i][q] = -s * aip + c * aiq; A[q][i] = A[i][q]
            app, aqq, apq = A[p][p], A[q][q], A[p][q]
            A[p][p] = c*c*app + 2*s*c*apq + s*s*aqq
            A[q][q] = s*s*app - 2*s*c*apq + c*c*aqq
            A[p][q] = 0.0; A[q][p] = 0.0
        return [A[i][i] for i in range(n)]

    def fiedler_vector(self) -> list[float] | None:
        """计算 Fiedler 向量——对应代数连通度的特征向量。

        Fiedler 向量可用于:
        - 谱二分（正/负分两组）
        - 节点排序（与连通性的关系）
        - 图嵌入（1D 谱嵌入）

        Returns:
            与 node_ids 顺序对应的 Fiedler 向量，或 None
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n < 2:
            return None

        idx = {nid: i for i, nid in enumerate(node_ids)}
        degree = [0] * n
        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j); adj_sym[j].add(i)
                degree[i] += 1; degree[j] += 1

        L = [[0.0] * n for _ in range(n)]
        for i in range(n):
            L[i][i] = float(degree[i])
            for j in adj_sym[i]:
                L[i][j] = -1.0

        import random; random.seed(123)
        v = [random.random() - 0.5 for _ in range(n)]
        mean = sum(v) / n
        v = [x - mean for x in v]
        norm = math.sqrt(sum(x * x for x in v)) or 1e-15
        v = [x / norm for x in v]

        eps = 1e-6
        for _ in range(500):
            x = self._cg_solve(L, v, eps)
            if x is None: break
            mean_x = sum(x) / n
            x = [xi - mean_x for xi in x]
            norm_x = math.sqrt(sum(xi * xi for xi in x)) or 1e-15
            x = [xi / norm_x for xi in x]
            diff = sum((x[i] - v[i]) ** 2 for i in range(n))
            v = x
            if diff < 1e-14: break
        return v

    def _cg_solve(self, L: list[list[float]], b: list[float], eps: float) -> list[float] | None:
        """共轭梯度法求解 (L + eps*I)x = b。"""
        n = len(b)
        def Mx(v: list[float]) -> list[float]:
            return [sum(L[i][j] * v[j] for j in range(n)) + eps * v[i] for i in range(n)]
        x = [0.0] * n
        r = b[:]
        p = r[:]
        rs_old = sum(r[i] * r[i] for i in range(n))
        if rs_old < 1e-30: return x
        for _ in range(n * 3):
            Mp = Mx(p)
            pMp = sum(p[i] * Mp[i] for i in range(n))
            if abs(pMp) < 1e-30: break
            alpha = rs_old / pMp
            x = [x[i] + alpha * p[i] for i in range(n)]
            r = [r[i] - alpha * Mp[i] for i in range(n)]
            rs_new = sum(r[i] * r[i] for i in range(n))
            if rs_new < 1e-20: break
            beta = rs_new / rs_old
            p = [r[i] + beta * p[i] for i in range(n)]
            rs_old = rs_new
        return x

    # ── 连通性分析（node/edge connectivity）─────────────────

    def node_connectivity(self) -> int:
        """计算图的节点连通度 κ(G)——使图不连通所需移除的最少节点数。

        使用 Menger 定理：κ(G) = min over all (s,t) of max node-disjoint paths。
        实现基于节点分裂最大流。

        Returns:
            节点连通度（0 = 不连通/单节点/空图）
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n < 2:
            return 0

        idx = {nid: i for i, nid in enumerate(node_ids)}
        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j); adj_sym[j].add(i)

        # BFS 连通性检查
        visited = {0}; queue = [0]
        while queue:
            u = queue.pop(0)
            for v in adj_sym[u]:
                if v not in visited:
                    visited.add(v); queue.append(v)
        if len(visited) < n:
            return 0

        # 优化: 只从度最小节点 s 出发
        degrees = [len(adj_sym[i]) for i in range(n)]
        s = min(range(n), key=lambda i: degrees[i])
        min_cut = n

        for t in range(n):
            if t == s: continue
            flow = self._node_split_maxflow(s, t, n, adj_sym)
            if flow < min_cut:
                min_cut = flow
                if min_cut == 0: break

        return min_cut

    def _node_split_maxflow(self, s: int, t: int, n: int,
                            adj_sym: dict[int, set[int]]) -> int:
        """节点分裂法求 s-t 最小节点割（Edmonds-Karp with bottleneck）。"""
        INF = n + 1
        source = s * 2 + 1  # s_out
        sink = t * 2        # t_in

        cap: dict[tuple[int,int], int] = {}
        for i in range(n):
            if i not in (s, t):
                cap[(i*2, i*2+1)] = 1
            for j in adj_sym[i]:
                # Direct s→t edge counts as 1 internally vertex-disjoint path
                if (i == s and j == t) or (i == t and j == s):
                    if i*2+1 not in [k for k,_v in [(a,b) for (a,b) in cap]]:
                        pass  # handled below
                cap[(i*2+1, j*2)] = INF
        # Override direct s_out→t_in to cap=1
        cap[(s*2+1, t*2)] = 1

        total_flow = 0
        while True:
            visited = {source}; parent = {}; queue = [source]
            while queue and sink not in visited:
                u = queue.pop(0)
                for (a, b), c in cap.items():
                    if a == u and b not in visited and c > 0:
                        visited.add(b); parent[b] = u; queue.append(b)
            if sink not in visited: break

            # Compute bottleneck
            bottleneck = INF
            v = sink
            while v in parent:
                u = parent[v]
                bottleneck = min(bottleneck, cap.get((u, v), 0))
                v = u

            total_flow += bottleneck
            if total_flow >= INF: break

            v = sink
            while v in parent:
                u = parent[v]
                cap[(u, v)] -= bottleneck
                cap[(v, u)] = cap.get((v, u), 0) + bottleneck
                v = u

        return total_flow

    def edge_connectivity(self) -> int:
        """计算图的边连通度 λ(G)——使图不连通所需移除的最少边数。

        Returns:
            边连通度（0 = 不连通/单节点/空图）
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n < 2:
            return 0

        idx = {nid: i for i, nid in enumerate(node_ids)}
        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j); adj_sym[j].add(i)

        # 连通性
        visited = {0}; queue = [0]
        while queue:
            u = queue.pop(0)
            for v in adj_sym[u]:
                if v not in visited:
                    visited.add(v); queue.append(v)
        if len(visited) < n:
            return 0

        degrees = [len(adj_sym[i]) for i in range(n)]
        s = min(range(n), key=lambda i: degrees[i])
        min_cut = degrees[s]

        for t in range(n):
            if t == s: continue
            flow = self._ek_unit(s, t, n, adj_sym)
            if flow < min_cut:
                min_cut = flow
                if min_cut == 0: break

        return min_cut

    def _ek_unit(self, s: int, t: int, n: int,
                 adj_sym: dict[int, set[int]]) -> int:
        """单位容量图 Edmonds-Karp。"""
        residual: dict[int, dict[int, int]] = defaultdict(lambda: defaultdict(int))
        for u in range(n):
            for v in adj_sym[u]:
                residual[u][v] = 1

        total_flow = 0
        while True:
            visited = {s}; parent = {}; queue = [s]
            while queue and t not in visited:
                u = queue.pop(0)
                for v in range(n):
                    if v not in visited and residual[u][v] > 0:
                        visited.add(v); parent[v] = u; queue.append(v)
            if t not in visited: break
            total_flow += 1
            v = t
            while v in parent:
                u = parent[v]
                residual[u][v] -= 1
                residual[v][u] += 1
                v = u
        return total_flow

    def percolation_centrality(self, states: dict[str, float] | None = None) -> dict[str, float]:
        """计算渗透中心性（percolation centrality）。

        渗透中心性衡量节点在"渗透"过程中传播信息的重要性。
        每个节点有一个渗透状态 x ∈ [0,1]（默认用 degree/max_degree）。
        渗透中心性 = sum over (s,t): σ_st(v)/σ_st * x_s*x_t / sum(x_s*x_t)

        Args:
            states: 可选的 {node_id: state} 映射，默认用归一化度数

        Returns:
            {node_id: percolation_centrality} 字典
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if n < 3:
            return {nid: 0.0 for nid in node_ids}

        idx = {nid: i for i, nid in enumerate(node_ids)}
        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j); adj_sym[j].add(i)

        # Default states = normalized degree
        if states is None:
            degrees = [len(adj_sym[i]) for i in range(n)]
            max_deg = max(degrees) if degrees else 1
            x = [d / max_deg for d in degrees]
        else:
            x = [states.get(nid, 0.0) for nid in node_ids]

        # BFS shortest paths for all pairs (unweighted)
        # σ[s][t] = number of shortest paths from s to t
        # σ_through[v][s][t] = 1 if v is on some shortest s-t path
        import collections
        sigma = [[0]*n for _ in range(n)]
        pred = [[[] for _ in range(n)] for _ in range(n)]
        dist = [[float('inf')]*n for _ in range(n)]

        for s in range(n):
            sigma[s][s] = 1; dist[s][s] = 0
            queue = collections.deque([s])
            while queue:
                u = queue.popleft()
                for v in adj_sym[u]:
                    if dist[s][v] == float('inf'):
                        dist[s][v] = dist[s][u] + 1
                        queue.append(v)
                    if dist[s][v] == dist[s][u] + 1:
                        sigma[s][v] += sigma[s][u]
                        pred[s][v].append(u)

        # For each node v, compute percolation centrality
        # p(v) = (1/(n-2)) * sum_{s≠v≠t} σ_sv(v)/σ_sv * x_s*x_t / (sum_{s<t} x_s*x_t)
        # Simplified: skip normalization denominator, use relative values

        # First compute dependency: δ[v] = sum_{s<t: v on s-t path} x_s * x_t / σ_st * σ_st(v)
        # Using Brandes-like accumulation
        delta = [[0.0]*n for _ in range(n)]  # delta[s][v]
        result = [0.0] * n

        for s in range(n):
            # Process nodes in reverse BFS order from s
            order = sorted(range(n), key=lambda v: -dist[s][v] if dist[s][v] != float('inf') else 0)
            for t in order:
                if t == s or dist[s][t] == float('inf'):
                    continue
                for w in pred[s][t]:
                    ratio = sigma[s][w] / sigma[s][t] if sigma[s][t] > 0 else 0
                    delta[s][w] += ratio * (x[t] + delta[s][t])

            for v in range(n):
                if v != s:
                    result[v] += x[s] * delta[s][v]

        # Normalize to [0, 1]
        max_result = max(result) if result else 1
        if max_result == 0:
            max_result = 1

        return {node_ids[i]: result[i] / max_result for i in range(n)}

    def triad_census(self) -> dict[str, int]:
        """计算有向图的三元组普查(triad census)。

        统计所有可能的有向三元组类型(共16种，MaaS convention)。
        三元组由3个节点和它们之间的有向边组成。
        编码方式: 每条边用数字表示:
            0 = 无边, 1 = i→j 方向, 2 = j→i 方向, 3 = 双向
        三元组编码: (ij)(ik)(jk) 三对关系的编码拼接。

        Returns:
            dict: 16种三元组类型的计数，键为3位编码字符串。
        """
        # 获取所有节点和邻接关系
        nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        node_list = [r[0] for r in nodes]
        n = len(node_list)
        if n < 3:
            # 不足3个节点，全部为0
            return {f"{a}{b}{c}": 0 for a in range(4) for b in range(4)
                    for c in range(4)
                    if not (a == 0 and b == 0 and c == 0)}

        # 构建邻接集合
        out_edges = {}
        rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        for s, t in rows:
            out_edges.setdefault(s, set()).add(t)

        # 初始化16种类型的计数
        census = {f"{a}{b}{c}": 0 for a in range(4) for b in range(4)
                  for c in range(4)
                  if not (a == 0 and b == 0 and c == 0)}

        def edge_code(u, v):
            """计算u和v之间的边编码。"""
            has_uv = v in out_edges.get(u, set())
            has_vu = u in out_edges.get(v, set())
            if has_uv and has_vu:
                return 3
            elif has_uv:
                return 1
            elif has_vu:
                return 2
            return 0

        # 遍历所有三元组 (i < j < k)
        for ii in range(n):
            i = node_list[ii]
            for jj in range(ii + 1, n):
                j = node_list[jj]
                ij = edge_code(i, j)
                for kk in range(jj + 1, n):
                    k = node_list[kk]
                    ik = edge_code(i, k)
                    jk = edge_code(j, k)
                    code = f"{ij}{ik}{jk}"
                    if code != "000":
                        census[code] = census.get(code, 0) + 1

        # 移除全零条目（已排除）
        return {k: v for k, v in census.items() if v >= 0}

    def average_neighbor_degree(self) -> dict[str, float]:
        """计算每个节点的平均邻居度数。

        k_nn(i) = (1/k_i) * sum(k_j for j in neighbors(i))
        高值 = 邻居是高度节点(hub连接), 低值 = 邻居是低度节点。

        Returns:
            dict: {node_id: average_neighbor_degree}，孤立节点不包含。
        """
        rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()

        # 构建无向邻接表和度数
        neighbors_map = {}
        for s, t in rows:
            neighbors_map.setdefault(s, set()).add(t)
            neighbors_map.setdefault(t, set()).add(s)

        degree = {nid: len(nbrs) for nid, nbrs in neighbors_map.items()}
        result = {}
        all_nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        for (nid,) in all_nodes:
            k = degree.get(nid, 0)
            if k == 0:
                continue
            nbrs = neighbors_map.get(nid, set())
            if not nbrs:
                continue
            knn = sum(degree.get(n, 0) for n in nbrs) / k
            result[nid] = round(knn, 6)
        return result

    def degree_correlation(self) -> float | None:
        """计算度-度相关系数(Newman assortativity coefficient)。

        基于边端点度数的 Pearson 相关系数。
        r > 0: 同配(高度节点连接高度节点)
        r < 0: 异配(高度节点连接低度节点)
        r ≈ 0: 无相关

        Returns:
            float | None: 相关系数，无边图返回 None。
        """
        rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        if not rows:
            return None

        # 构建无向度数
        degree = {}
        for s, t in rows:
            degree[s] = degree.get(s, 0) + 1
            degree[t] = degree.get(t, 0) + 1

        M = len(rows)
        # sum(j*k), sum(j+k), sum(j^2+k^2)
        sum_jk = 0.0
        sum_jpk = 0.0
        sum_j2k2 = 0.0
        for s, t in rows:
            j = degree.get(s, 0)
            k = degree.get(t, 0)
            sum_jk += j * k
            sum_jpk += j + k
            sum_j2k2 += j * j + k * k

        # Newman's formula
        # r = (M^-1 sum(jk) - [0.5 M^-1 sum(j+k)]^2) / (0.5 M^-1 sum(j^2+k^2) - [0.5 M^-1 sum(j+k)]^2)
        numerator = sum_jk / M - (sum_jpk / (2 * M)) ** 2
        denominator = sum_j2k2 / (2 * M) - (sum_jpk / (2 * M)) ** 2

        if abs(denominator) < 1e-12:
            return 0.0
        return round(numerator / denominator, 6)

    def node_similarity(self, id_a: str, id_b: str, mode: str = "jaccard") -> float:
        """计算两个节点的结构相似度。

        基于邻居集合的重叠程度。

        Args:
            id_a, id_b: 节点ID。
            mode: "jaccard" (Jaccard系数) 或 "overlap" (重叠系数/Szymkiewicz–Simpson)。

        Returns:
            float: 0.0~1.0 的相似度，任一节点不存在返回 0.0。
        """
        if not self.has_node(id_a) or not self.has_node(id_b):
            return 0.0
        if id_a == id_b:
            return 1.0

        # Build undirected neighbor sets from edges table
        def undirected_nbrs(nid):
            rows = self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
                (nid, nid)
            ).fetchall()
            return {r[0] for r in rows}

        nbrs_a = undirected_nbrs(id_a)
        nbrs_b = undirected_nbrs(id_b)

        if mode == "jaccard":
            union = nbrs_a | nbrs_b
            if not union:
                return 1.0 if not nbrs_a and not nbrs_b else 0.0
            return len(nbrs_a & nbrs_b) / len(union)
        elif mode == "overlap":
            min_size = min(len(nbrs_a), len(nbrs_b))
            if min_size == 0:
                return 1.0 if not nbrs_a and not nbrs_b else 0.0
            return len(nbrs_a & nbrs_b) / min_size
        raise ValueError(f"Unknown mode: {mode}. Use 'jaccard' or 'overlap'.")

    def resistance_distance(self, id_a: str, id_b: str) -> float | None:
        """计算两节点间的电阻距离（effective resistance）。

        电阻距离基于拉普拉斯矩阵伪逆: R(i,j) = L⁺ᵢᵢ + L⁺ⱼⱼ - 2L⁺ᵢⱼ。
        低电阻距离 = 节点间有多条路径（冗余连接）。
        高电阻距离 = 节点间依赖少数路径（脆弱连接）。

        Returns:
            电阻距离，或 None（节点不存在/不连通）
        """
        node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        n = len(node_ids)
        if id_a not in node_ids or id_b not in node_ids:
            return None
        if id_a == id_b:
            return 0.0
        if n < 2:
            return None

        idx = {nid: i for i, nid in enumerate(node_ids)}
        a, b = idx[id_a], idx[id_b]

        adj_sym: dict[int, set[int]] = defaultdict(set)
        for e in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if e["source"] in idx and e["target"] in idx:
                i, j = idx[e["source"]], idx[e["target"]]
                adj_sym[i].add(j); adj_sym[j].add(i)

        # Check connectivity (BFS from a)
        visited = {a}; queue = [a]
        while queue:
            u = queue.pop(0)
            for v in adj_sym[u]:
                if v not in visited: visited.add(v); queue.append(v)
        if b not in visited:
            return float('inf')

        # Build Laplacian and compute pseudoinverse via eigenvalues
        degree = [0] * n
        for i in range(n):
            degree[i] = len(adj_sym[i])

        L = [[0.0] * n for _ in range(n)]
        for i in range(n):
            L[i][i] = float(degree[i])
            for j in adj_sym[i]:
                L[i][j] = -1.0

        # Pseudoinverse via eigenvalue decomposition
        eigenvalues = self._sym_eigenvalues(L)
        # We also need eigenvectors — use Jacobi with eigenvector tracking
        eigvecs = self._sym_eigenvectors(L)

        # L⁺ = sum over k: (1/λ_k) * v_k * v_k^T (skip λ=0)
        # R(a,b) = L⁺[a,a] + L⁺[b,b] - 2*L⁺[a,b]
        # = sum_k (1/λ_k) * (v_k[a]² + v_k[b]² - 2*v_k[a]*v_k[b])
        # = sum_k (1/λ_k) * (v_k[a] - v_k[b])²

        r = 0.0
        for k in range(n):
            if eigenvalues[k] > 1e-10:
                diff = eigvecs[k][a] - eigvecs[k][b]
                r += (diff * diff) / eigenvalues[k]

        return max(0.0, r)

    def _sym_eigenvectors(self, M: list[list[float]], max_iter: int = 300) -> list[list[float]]:
        """雅可比旋转求实对称矩阵全部特征值和特征向量。返回 eigvecs[k] = 第k个特征向量。"""
        n = len(M)
        A = [row[:] for row in M]
        V = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

        for _ in range(max_iter):
            p, q = 0, 1
            max_val = abs(A[0][1])
            for i in range(n):
                for j in range(i + 1, n):
                    if abs(A[i][j]) > max_val:
                        max_val = abs(A[i][j]); p, q = i, j
            if max_val < 1e-12:
                break
            if abs(A[p][p] - A[q][q]) < 1e-15:
                theta = math.pi / 4
            else:
                theta = 0.5 * math.atan2(2 * A[p][q], A[p][p] - A[q][q])
            c, s = math.cos(theta), math.sin(theta)

            # Rotate A
            for i in range(n):
                if i == p or i == q: continue
                aip, aiq = A[i][p], A[i][q]
                A[i][p] = c * aip + s * aiq; A[p][i] = A[i][p]
                A[i][q] = -s * aip + c * aiq; A[q][i] = A[i][q]
            app, aqq, apq = A[p][p], A[q][q], A[p][q]
            A[p][p] = c*c*app + 2*s*c*apq + s*s*aqq
            A[q][q] = s*s*app - 2*s*c*apq + c*c*aqq
            A[p][q] = 0.0; A[q][p] = 0.0

            # Rotate V (accumulate eigenvectors)
            for i in range(n):
                vip, viq = V[i][p], V[i][q]
                V[i][p] = c * vip + s * viq
                V[i][q] = -s * vip + c * viq

        # V columns are eigenvectors, A diagonal has eigenvalues
        # Return as list of column vectors
        return [[V[i][k] for i in range(n)] for k in range(n)]

    def ego_graph(self, node_id: str, order: int = 1) -> dict:
        """提取以指定节点为中心的 ego graph（自我网络）。

        返回中心节点及其 order-hop 邻域内的所有节点和边。
        ego graph 是社会网络分析的基本单元，也用于 GraphRAG local search。

        Args:
            node_id: 中心节点 ID。
            order: 邻域半径（默认 1 = 直接邻居）。

        Returns:
            {"center": node_id, "nodes": [...], "edges": [...], "radius": order}
            节点不存在返回空结果。
        """
        if not self.has_node(node_id):
            return {"center": node_id, "nodes": [], "edges": [], "radius": order}

        # BFS to collect nodes within `order` hops
        visited = {node_id}
        frontier = {node_id}
        for _ in range(order):
            next_frontier = set()
            for nid in frontier:
                rows = self.conn.execute(
                    "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
                    (nid, nid)
                ).fetchall()
                for r in rows:
                    if r[0] not in visited:
                        next_frontier.add(r[0])
            visited |= next_frontier
            frontier = next_frontier

        # Collect edges within the ego graph (both endpoints in visited)
        placeholders = ",".join("?" for _ in visited)
        params = list(visited)
        edge_rows = self.conn.execute(
            f"SELECT source, target, weight, relation FROM edges WHERE source IN ({placeholders}) AND target IN ({placeholders})",
            params + params
        ).fetchall()

        edges = [{"source": r[0], "target": r[1], "weight": r[2], "relation": r[3]} for r in edge_rows]
        return {"center": node_id, "nodes": sorted(visited), "edges": edges, "radius": order}

    def transitivity(self) -> float:
        """计算全局传递性（聚类系数）= 3 × 三角形数 / 三元组数。

        传递性衡量网络中"朋友的朋友也是朋友"的程度。
        值域 [0, 1]，0 = 无三角形，1 = 完全图。

        Returns:
            float: 传递性，孤立或无三元组返回 0.0。
        """
        node_ids = [r[0] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        if len(node_ids) < 3:
            return 0.0

        # Build undirected adjacency
        adj = {nid: set() for nid in node_ids}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            if r[0] in adj and r[1] in adj:
                adj[r[0]].add(r[1])
                adj[r[1]].add(r[0])

        triangles = 0
        triples = 0
        for nid in node_ids:
            k = len(adj[nid])
            if k >= 2:
                triples += k * (k - 1) // 2
                # Count triangles including nid
                nbrs = list(adj[nid])
                for i in range(len(nbrs)):
                    for j in range(i + 1, len(nbrs)):
                        if nbrs[j] in adj[nbrs[i]]:
                            triangles += 1

        if triples == 0:
            return 0.0
        # Each triangle counted 3 times (once per vertex)
        return triangles / triples  # Already normalized: 3*triangles/3 / triples

    def preferential_attachment(self, id_a: str, id_b: str) -> int | None:
        """计算两节点间的优先链接分数 = deg(A) × deg(B)。

        用于链路预测：度数高的节点对更可能连接。
        是 Adamic/Adar 和 Jaccard 的简化替代。

        Args:
            id_a, id_b: 节点 ID。

        Returns:
            int: 度数乘积，节点不存在返回 None。
        """
        if not self.has_node(id_a) or not self.has_node(id_b):
            return None

        deg_a = self.conn.execute(
            "SELECT COUNT(*) FROM edges WHERE source=? OR target=?",
            (id_a, id_a)
        ).fetchone()[0]
        deg_b = self.conn.execute(
            "SELECT COUNT(*) FROM edges WHERE source=? OR target=?",
            (id_b, id_b)
        ).fetchone()[0]
        return deg_a * deg_b

    # ── LLM 上下文导出 ────────────────────────────────────

    def to_markdown(self, node_ids: list[str] | None = None, max_nodes: int = 50,
                    include_edges: bool = True, include_data: bool = True) -> str:
        """将图谱导出为 Markdown 文本，适合注入 LLM 上下文。

        Args:
            node_ids: 仅导出指定节点（None=全部，按 weight 降序取 max_nodes）
            max_nodes: 最大节点数（防止 token 爆炸）
            include_edges: 是否包含关系列表
            include_data: 是否包含节点 data 字段

        Returns:
            Markdown 字符串，结构为：标题 + 节点列表 + 关系列表
        """
        if node_ids is not None:
            node_ids = set(node_ids)
            rows = self.conn.execute(
                "SELECT * FROM nodes WHERE id IN (%s) ORDER BY weight DESC LIMIT ?"
                % ",".join("?" * len(node_ids)),
                (*node_ids, max_nodes)
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT * FROM nodes ORDER BY weight DESC LIMIT ?", (max_nodes,)
            ).fetchall()

        if not rows:
            return "# Memory Graph\n\n(empty)\n"

        lines = ["# Memory Graph", ""]
        id_set = {r["id"] for r in rows}

        # 按_kind 分组
        by_kind: dict[str, list] = defaultdict(list)
        for r in rows:
            by_kind[r["kind"]].append(r)

        for kind in sorted(by_kind):
            lines.append(f"## {kind} ({len(by_kind[kind])})")
            for r in by_kind[kind]:
                tags = json.loads(r["tags"]) if r["tags"] else []
                tag_str = f" `{'` `'.join(tags)}`" if tags else ""
                data_str = ""
                if include_data and r["data"] and r["data"] != "{}":
                    try:
                        d = json.loads(r["data"])
                        if d:
                            items = ", ".join(f"{k}={v!r}" for k, v in d.items())
                            data_str = f" — {items}"
                    except (json.JSONDecodeError, TypeError):
                        pass
                weight_str = f" (w={r['weight']:.2f})" if r["weight"] != 1.0 else ""
                lines.append(f"- **{r['label']}**{weight_str}{tag_str}{data_str}")
            lines.append("")

        if include_edges:
            edge_rows = self.conn.execute(
                "SELECT * FROM edges WHERE source IN (%s) OR target IN (%s) ORDER BY weight DESC"
                % (",".join("?" * len(id_set)), ",".join("?" * len(id_set))),
                (*id_set, *id_set)
            ).fetchall()
            if edge_rows:
                label_map = {r["id"]: r["label"] for r in rows}
                lines.append("## Relationships")
                shown = 0
                for e in edge_rows:
                    if shown >= max_nodes * 2:
                        break
                    src = label_map.get(e["source"], e["source"])
                    tgt = label_map.get(e["target"], e["target"])
                    w = f" (w={e['weight']:.2f})" if e["weight"] != 1.0 else ""
                    lines.append(f"- {src} —{e['relation']}→ {tgt}{w}")
                    shown += 1
                lines.append("")

        return "\n".join(lines)

    def context_window(self, node_ids: list[str], hops: int = 1, max_nodes: int = 30) -> str:
        """提取以指定节点为中心的局部子图，输出为 Markdown 上下文。

        比 to_markdown() 更聚焦：先 BFS 扩展 hops 跳邻居，再格式化。
        适合把「最相关的记忆」注入 prompt。

        Args:
            node_ids: 种子节点列表
            hops: BFS 扩展跳数（默认1跳=直接邻居）
            max_nodes: 最大节点数

        Returns:
            Markdown 字符串，种子节点标 ★
        """
        seed = set(node_ids)
        collected = dict()  # id → Row

        # 加载种子节点
        for nid in node_ids:
            r = self.conn.execute("SELECT * FROM nodes WHERE id = ?", (nid,)).fetchone()
            if r:
                collected[nid] = r

        # BFS 扩展
        frontier = list(node_ids)
        for _ in range(hops):
            next_frontier = []
            for nid in frontier:
                for r in self.conn.execute(
                    "SELECT n.* FROM nodes n JOIN edges e ON n.id=e.target WHERE e.source = ?",
                    (nid,)
                ).fetchall():
                    if r["id"] not in collected and len(collected) < max_nodes:
                        collected[r["id"]] = r
                        next_frontier.append(r["id"])
                for r in self.conn.execute(
                    "SELECT n.* FROM nodes n JOIN edges e ON n.id=e.source WHERE e.target = ?",
                    (nid,)
                ).fetchall():
                    if r["id"] not in collected and len(collected) < max_nodes:
                        collected[r["id"]] = r
                        next_frontier.append(r["id"])
            frontier = next_frontier

        if not collected:
            return "# Context Window\n\n(no data)\n"

        lines = ["# Context Window", ""]

        # 按 kind 分组
        by_kind: dict[str, list] = defaultdict(list)
        for r in collected.values():
            by_kind[r["kind"]].append(r)

        for kind in sorted(by_kind):
            lines.append(f"## {kind}")
            for r in by_kind[kind]:
                marker = " ★" if r["id"] in seed else ""
                tags = json.loads(r["tags"]) if r["tags"] else []
                tag_str = f" `{'` `'.join(tags)}`" if tags else ""
                data_str = ""
                if r["data"] and r["data"] != "{}":
                    try:
                        d = json.loads(r["data"])
                        if d:
                            items = ", ".join(f"{k}={v!r}" for k, v in d.items())
                            data_str = f" — {items}"
                    except (json.JSONDecodeError, TypeError):
                        pass
                lines.append(f"- **{r['label']}**{marker}{tag_str}{data_str}")
            lines.append("")

        # 收集相关边
        id_set = set(collected.keys())
        edge_rows = self.conn.execute(
            "SELECT * FROM edges WHERE source IN (%s) OR target IN (%s) ORDER BY weight DESC"
            % (",".join("?" * len(id_set)), ",".join("?" * len(id_set))),
            (*id_set, *id_set)
        ).fetchall()
        if edge_rows:
            label_map = {nid: collected[nid]["label"] for nid in id_set}
            lines.append("## Relationships")
            for e in edge_rows[:max_nodes * 2]:
                src = label_map.get(e["source"], e["source"])
                tgt = label_map.get(e["target"], e["target"])
                lines.append(f"- {src} —{e['relation']}→ {tgt}")
            lines.append("")

        return "\n".join(lines)



    def resource_allocation_index(self, id_a: str, id_b: str) -> float | None:
        """计算两节点间的资源分配指数（链路预测）。
        RA(i,j) = Σ 1/|Γ(z)| for z ∈ Γ(i) ∩ Γ(j)
        共同邻居的度数越小权重越高（稀有共同邻居更有价值）。
        比 Adamic/Adar 更惩罚高度共同邻居。
        Args:
            id_a, id_b: 节点 ID。
        Returns:
            float: RA 分数，≥ 0。节点不存在返回 None。
        """
        if not self.has_node(id_a) or not self.has_node(id_b):
            return None
        def undirected_nbrs(nid):
            rows = self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION SELECT source FROM edges WHERE target=?",
                (nid, nid)
            ).fetchall()
            return {r[0] for r in rows}
        nbrs_a = undirected_nbrs(id_a)
        nbrs_b = undirected_nbrs(id_b)
        common = nbrs_a & nbrs_b
        if not common:
            return 0.0
        score = 0.0
        for z in common:
            deg_z = self.conn.execute(
                "SELECT COUNT(*) FROM edges WHERE source=? OR target=?",
                (z, z)
            ).fetchone()[0]
            if deg_z > 0:
                score += 1.0 / deg_z
        return score
    def degree_prestige(self, node_id: str) -> float | None:
        """计算节点的度声望 = 入度 / (n-1)。
        有向图中被多少比例的节点指向，衡量"知名度"。
        无向图中退化为归一化度数。
        Args:
            node_id: 节点 ID。
        Returns:
            float: [0, 1] 归一化声望，节点不存在返回 None。
        """
        if not self.has_node(node_id):
            return None
        n = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        if n <= 1:
            return 0.0
        in_deg = self.conn.execute(
            "SELECT COUNT(*) FROM edges WHERE target=?",
            (node_id,)
        ).fetchone()[0]
        return in_deg / (n - 1)
    def core_ratio(self, k: int) -> float:
        """计算 k-core 占总节点的比例。
        衡量图的核密度：高比例意味着大部分节点高度互联。
        依赖 core_number() 的结果。
        Args:
            k: core 阶数。
        Returns:
            float: [0, 1] 比例，空图返回 0.0。
        """
        n = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        if n == 0:
            return 0.0
        cores = self.core_number()
        in_core = sum(1 for v in cores.values() if v >= k)
        return in_core / n

    # ── 演示 ──────────────────────────────────────────────────



    def density(self) -> float:
        """计算图的密度：实际边数 / 最大可能边数。

        density = m / (n*(n-1))  for directed
        density = 2m / (n*(n-1))  for undirected (standard analysis)

        完全图密度=1.0，空图=0.0。使用无向语义（与图分析惯例一致）。
        """
        n = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        if n < 2:
            return 0.0
        m = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        return (2.0 * m) / (n * (n - 1))

    def local_clustering(self, node_id: str) -> float | None:
        """计算节点的局部聚类系数。

        C(v) = 2 * E(neighbors) / (deg(v) * (deg(v) - 1))

        衡量该节点的邻居之间互连的程度。值域 [0, 1]。
        节点不存在或度数 < 2 时返回 None（无法计算）。
        """
        if not self.has_node(node_id):
            return None
        # Get neighbors (undirected)
        nbrs = set()
        for r in self.conn.execute(
            "SELECT target AS nb FROM edges WHERE source=? "
            "UNION "
            "SELECT source AS nb FROM edges WHERE target=?",
            (node_id, node_id)
        ).fetchall():
            nbrs.add(str(r["nb"]))
        k = len(nbrs)
        if k < 2:
            return None
        # Count edges among neighbors
        nbr_list = list(nbrs)
        edges_among = 0
        for i in range(len(nbr_list)):
            for j in range(i + 1, len(nbr_list)):
                cnt = self.conn.execute(
                    "SELECT COUNT(*) FROM edges WHERE "
                    "(source=? AND target=?) OR (source=? AND target=?)",
                    (nbr_list[i], nbr_list[j], nbr_list[j], nbr_list[i])
                ).fetchone()[0]
                if cnt > 0:
                    edges_among += 1
        return (2.0 * edges_among) / (k * (k - 1))

    def efficiency(self, id_a: str, id_b: str) -> float:
        """计算两节点之间的效率：1 / 最短路径长度。

        效率越高表示两节点通信越高效。不可达时返回 0.0。
        """
        if not self.has_node(id_a) or not self.has_node(id_b):
            return 0.0
        if id_a == id_b:
            return 1.0
        path = self.shortest_path(id_a, id_b)
        if path is None:
            return 0.0
        return 1.0 / len(path)

    def assortativity_degree(self) -> float:
        """计算度同配系数 (Newman assortativity coefficient)。

        衡量图中节点是否倾向于连接度数相似的节点。
        r > 0: 同配网络（高连高、低连低）
        r < 0: 异配网络（高连低）
        r ≈ 0: 无明显相关性
        值域 [-1, 1]。
        """
        rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        m = len(rows)
        if m < 2:
            return 0.0
        # Build undirected degree map
        deg: dict[str, int] = {}
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            deg[s] = deg.get(s, 0) + 1
            deg[t] = deg.get(t, 0) + 1
        # Newman's formula: each edge contributes two terms (j,k) and (k,j)
        # M = 2 * num_edges (standard undirected normalization)
        two_m = 2 * m
        sum_jk = 0.0
        sum_j = 0.0
        sum_k = 0.0
        sum_j2 = 0.0
        sum_k2 = 0.0
        for r in rows:
            j = deg[str(r["source"])]
            k = deg[str(r["target"])]
            # Both (j,k) and (k,j)
            sum_jk += j * k + k * j
            sum_j += j + k
            sum_k += k + j
            sum_j2 += j * j + k * k
            sum_k2 += k * k + j * j
        numerator = (sum_jk / two_m) - ((sum_j / two_m) * (sum_k / two_m))
        denominator = (
            (sum_j2 + sum_k2) / (2 * two_m)
            - ((sum_j + sum_k) / (2 * two_m)) ** 2
        )
        if denominator == 0:
            return 0.0
        return numerator / denominator

    def degree_distribution(self) -> dict[int, float]:
        """计算度分布：每个度值对应的节点比例。

        返回 {degree: fraction} 字典。关键用途：
        - 判断是否为 scale-free 网络（幂律分布）
        - 识别 hub 节点（高度数）
        - 对比随机图与真实图的度分布差异
        """
        rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        deg: dict[str, int] = {}
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            deg[s] = deg.get(s, 0) + 1
            deg[t] = deg.get(t, 0) + 1
        total_nodes = self.conn.execute("SELECT COUNT(*) c FROM nodes").fetchone()["c"]
        if total_nodes == 0:
            return {}
        # Count nodes at each degree (including degree-0 nodes)
        degree_counts: dict[int, int] = {}
        node_ids = {str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()}
        for nid in node_ids:
            d = deg.get(nid, 0)
            degree_counts[d] = degree_counts.get(d, 0) + 1
        return {d: round(c / total_nodes, 4) for d, c in sorted(degree_counts.items())}

    def network_summary(self) -> dict:
        """一站式网络分析摘要：密度、聚类、度分布、连通性等。

        聚合已有的分析 API 为单次调用，适合 dashboard 或快速诊断。
        """
        n = self.conn.execute("SELECT COUNT(*) c FROM nodes").fetchone()["c"]
        m = self.conn.execute("SELECT COUNT(*) c FROM edges").fetchone()["c"]
        if n == 0:
            return {"nodes": 0, "edges": 0, "density": 0.0}

        # Average degree
        rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        deg: dict[str, int] = {}
        for r in rows:
            s, t = str(r["source"]), str(r["target"])
            deg[s] = deg.get(s, 0) + 1
            deg[t] = deg.get(t, 0) + 1
        avg_degree = (2.0 * m / n) if n > 0 else 0.0
        max_degree = max(deg.values()) if deg else 0

        # Density
        density = (2.0 * m) / (n * (n - 1)) if n > 1 else 0.0

        # Global clustering coefficient (transitivity)
        try:
            transitivity = self.transitivity()
        except Exception:
            transitivity = 0.0

        # Connected components
        try:
            components = self.find_components()
            num_components = len(components)
            largest_cc = max((len(c) for c in components), default=0)
        except Exception:
            num_components = 0
            largest_cc = 0

        # Reciprocity (directed)
        try:
            recip = self.reciprocity()
        except Exception:
            recip = 0.0

        return {
            "nodes": n,
            "edges": m,
            "density": round(density, 4),
            "avg_degree": round(avg_degree, 2),
            "max_degree": max_degree,
            "transitivity": round(transitivity, 4),
            "reciprocity": round(recip, 4),
            "components": num_components,
            "largest_component_size": largest_cc,
            "largest_component_ratio": round(largest_cc / n, 4) if n > 0 else 0.0,
        }

    def k_hop_neighbors(self, node_id: str, k: int = 2) -> dict[int, list[str]]:
        """获取节点 k 跳范围内的所有邻居。

        BFS 层次遍历，返回 {hop: [node_ids]} 字典。
        hop=0 为节点自身，hop=1 为直接邻居，hop=2 为二跳邻居，以此类推。
        已访问的节点不会重复出现。
        """
        if not self.has_node(node_id):
            return {}
        visited = {node_id}
        result = {0: [node_id]}
        frontier = [node_id]
        for hop in range(1, k + 1):
            next_frontier = []
            for cur in frontier:
                for r in self.conn.execute(
                    "SELECT target AS nb FROM edges WHERE source=? "
                    "UNION "
                    "SELECT source AS nb FROM edges WHERE target=?",
                    (cur, cur)
                ).fetchall():
                    nb = str(r["nb"])
                    if nb not in visited:
                        visited.add(nb)
                        next_frontier.append(nb)
            if next_frontier:
                result[hop] = sorted(next_frontier)
                frontier = next_frontier
            else:
                break
        return result

    def common_neighbors(self, node_id_a: str, node_id_b: str) -> list[str]:
        """返回两个节点的共同邻居（交集）。

        使用集合交集，复杂度 O(min(deg_a, deg_b))。
        对于链接预测、推荐系统和图分析有用。
        """
        if not self.has_node(node_id_a) or not self.has_node(node_id_b):
            return []
        nbrs_a = set()
        for r in self.conn.execute(
            "SELECT target AS nb FROM edges WHERE source=? "
            "UNION "
            "SELECT source AS nb FROM edges WHERE target=?",
            (node_id_a, node_id_a)
        ).fetchall():
            nbrs_a.add(str(r["nb"]))
        nbrs_b = set()
        for r in self.conn.execute(
            "SELECT target AS nb FROM edges WHERE source=? "
            "UNION "
            "SELECT source AS nb FROM edges WHERE target=?",
            (node_id_b, node_id_b)
        ).fetchall():
            nbrs_b.add(str(r["nb"]))
        return sorted(nbrs_a & nbrs_b)

    def graph_entropy(self) -> dict[str, float]:
        """Shannon entropy of the degree distribution.

        H = -sum(p_k * log2(p_k)) where p_k = fraction of nodes with degree k.
        Low entropy = uniform structure (e.g. regular graph).
        High entropy = heterogeneous (e.g. scale-free).
        Also returns normalized entropy (H / H_max) for cross-graph comparison.
        """
        n = self.conn.execute("SELECT COUNT(*) c FROM nodes").fetchone()["c"]
        if n == 0:
            return {"entropy": 0.0, "normalized": 0.0, "max_entropy": 0.0}

        dist = self.degree_distribution()
        total = sum(dist.values())
        if total == 0:
            return {"entropy": 0.0, "normalized": 0.0, "max_entropy": 0.0}

        h = 0.0
        for deg, frac in dist.items():
            p = frac / total
            if p > 0:
                h -= p * math.log2(p)

        h_max = math.log2(len(dist)) if len(dist) > 1 else 1.0
        return {
            "entropy": round(h, 4),
            "max_entropy": round(h_max, 4),
            "normalized": round(h / h_max, 4) if h_max > 0 else 0.0,
        }

    def connectivity_frontier(self, node_id: str, max_hop: int = 3) -> dict[int, int]:
        """BFS hop-distance census from a seed node.

        Returns {hop: count} — how many nodes are reachable at each distance.
        Useful for influence radius estimation and BFS-based exploration.
        """
        if not self.has_node(node_id):
            return {}

        visited = {node_id: 0}
        frontier = [node_id]
        for hop in range(1, max_hop + 1):
            next_frontier = []
            for nid in frontier:
                for r in self.conn.execute(
                    "SELECT target AS nb FROM edges WHERE source=? "
                    "UNION "
                    "SELECT source AS nb FROM edges WHERE target=?",
                    (nid, nid)
                ).fetchall():
                    nb = str(r["nb"])
                    if nb not in visited:
                        visited[nb] = hop
                        next_frontier.append(nb)
            frontier = next_frontier
            if not frontier:
                break

        census: dict[int, int] = {}
        for _, hop in visited.items():
            census[hop] = census.get(hop, 0) + 1
        return census

    def degree_centrality_normalized(self) -> dict[str, float]:
        """Normalized degree centrality: degree / (n-1).

        Freeman's classic centrality measure, normalized to [0, 1].
        A hub in a star graph scores 1.0, peripheral nodes score 1/(n-1).
        """
        n = self.conn.execute("SELECT COUNT(*) c FROM nodes").fetchone()["c"]
        if n <= 1:
            rows = self.conn.execute("SELECT id FROM nodes").fetchall()
            return {str(r["id"]): 0.0 for r in rows}

        rows = self.conn.execute(
            "SELECT id FROM nodes"
        ).fetchall()
        result = {}
        denom = n - 1
        for r in rows:
            nid = str(r["id"])
            deg = self.conn.execute(
                "SELECT COUNT(*) c FROM edges WHERE source=? OR target=?",
                (nid, nid)
            ).fetchone()["c"]
            result[nid] = round(deg / denom, 4)
        return result

    def edge_density_subgraph(self, node_ids: list[str]) -> float:
        """Edge density of an induced subgraph.

        Density = actual_edges / possible_edges (n*(n-1)/2 for undirected).
        Useful for evaluating community tightness or cluster cohesion.
        """
        n = len(node_ids)
        if n < 2:
            return 0.0
        node_set = set(node_ids)
        placeholders = ",".join("?" * n)
        actual = self.conn.execute(
            f"SELECT COUNT(*) c FROM edges WHERE source IN ({placeholders}) AND target IN ({placeholders})",
            (*node_ids, *node_ids)
        ).fetchone()["c"]
        possible = n * (n - 1) / 2
        return round(actual / possible, 4) if possible > 0 else 0.0


    # ===================================================================
    # Learnable Memory Management (Memory-R1 / AgeMem inspired)
    # ===================================================================

    @staticmethod
    def _content_similarity(text_a: str, text_b: str) -> float:
        """简易内容相似度: trigram Jaccard 系数。"""
        def trigrams(s: str) -> set:
            s = s.lower().strip()
            return {s[i:i+3] for i in range(len(s) - 2)} if len(s) >= 3 else {s}
        a, b = trigrams(text_a), trigrams(text_b)
        if not a or not b:
            return 0.0
        return len(a & b) / len(a | b)

    def score_memory_ops(self, content: str, existing_keys: list[str] = None,
                         noop_bias: float = 0.15) -> list[dict]:
        """对新信息评分 4 种操作 (ADD/UPDATE/DELETE/NOOP), Memory-R1 启发。"""
        existing_keys = existing_keys or []
        scores = []

        best_match = None
        best_sim = 0.0
        if existing_keys:
            for kid in existing_keys:
                node = self.get_node(kid)
                if node:
                    sim = self._content_similarity(content, node.label)
                    if sim > best_sim:
                        best_sim = sim
                        best_match = kid
        else:
            results = self.search_unified(content, limit=5)
            for r in results:
                sim = self._content_similarity(content, r["node"].label)
                if sim > best_sim:
                    best_sim = sim
                    best_match = r["node"].id

        novelty = 1.0 - best_sim
        add_score = novelty * (1.0 - noop_bias)
        scores.append({
            "op": "ADD",
            "score": round(add_score, 4),
            "reason": f"novelty={novelty:.2f}" + (f", best_match_sim={best_sim:.2f}" if best_match else ", no match"),
        })

        if best_match and best_sim > 0.3:
            update_score = best_sim * (1.0 - noop_bias)
            scores.append({
                "op": "UPDATE",
                "score": round(update_score, 4),
                "reason": f"similarity={best_sim:.2f} to existing node",
                "target_key": best_match,
            })
        else:
            scores.append({"op": "UPDATE", "score": 0.0,
                           "reason": "no similar existing entry"})

        scores.append({"op": "DELETE", "score": 0.0,
                       "reason": "DELETE only for contradictions/staleness (manual)"})

        noop_score = noop_bias + (best_sim * 0.3)
        scores.append({
            "op": "NOOP",
            "score": round(min(noop_score, 1.0), 4),
            "reason": "conservative default" + (f", high overlap={best_sim:.2f}" if best_sim > 0.5 else ""),
        })

        return sorted(scores, key=lambda x: x["score"], reverse=True)

    def decide_memory_op(self, content: str, threshold: float = 0.5,
                         noop_bias: float = 0.15) -> dict:
        """决策: 对新信息选择最优记忆操作。"""
        scores = self.score_memory_ops(content, noop_bias=noop_bias)
        best = scores[0]
        if best["op"] == "ADD" and best["score"] < threshold:
            return {"op": "NOOP", "score": best["score"],
                    "reason": f"ADD score {best['score']:.2f} < threshold {threshold}"}
        return best

    def execute_memory_op(self, content: str, kind: str = "fact",
                          threshold: float = 0.5, noop_bias: float = 0.15,
                          tags: list[str] = None) -> dict:
        """端到端: 决策 + 执行记忆操作。"""
        decision = self.decide_memory_op(content, threshold=threshold, noop_bias=noop_bias)
        op = decision["op"]

        if op == "ADD":
            node = self.add(content, kind)
            if tags:
                for t in tags:
                    self.tag_nodes(t, [node.id])
            return {"op": "ADD", "result": "created",
                    "detail": {"node_id": node.id, "label": content[:80]}}

        if op == "UPDATE" and decision.get("target_key"):
            kid = decision["target_key"]
            node = self.get_node(kid)
            if node:
                new_label = f"{node.label} + {content[:50]}"
                self.update_node(kid, label=new_label)
                return {"op": "UPDATE", "result": "merged",
                        "detail": {"node_id": kid, "old": node.label, "new": new_label}}

        if op == "DELETE":
            return {"op": "DELETE", "result": "skipped",
                    "detail": "DELETE requires explicit confirmation"}

        return {"op": "NOOP", "result": "no_action",
                "detail": decision["reason"]}

    def memory_decision_log(self, items: list[str], threshold: float = 0.5) -> list[dict]:
        """批量决策日志: 对多条信息生成操作建议 (不执行)。"""
        log = []
        for item in items:
            d = self.decide_memory_op(item, threshold=threshold)
            log.append({"content": item[:60], **d})
        return log

    def memory_audit(self, max_nodes: int = 500, staleness_days: int = 30) -> dict:
        """全局记忆审计: 健康评分 + 冗余分析 + 过期检测。

        MemoryArena (ICLR 2026) 启发的评估维度。

        Returns:
            {health_score, total_nodes, redundant_pairs, stale_nodes,
             avg_importance, noop_ratio, suggestions}
        """
        import time
        stats = self.stats()
        total = stats.get("nodes", 0)
        if total == 0:
            return {"health_score": 100, "total_nodes": 0, "redundant_pairs": 0,
                    "stale_nodes": 0, "avg_importance": 0, "noop_ratio": 0,
                    "suggestions": ["Empty graph"]}

        # 过期节点 (staleness)
        now = time.time()
        stale_cutoff = now - staleness_days * 86400
        stale_nodes = self.conn.execute(
            "SELECT COUNT(*) as c FROM nodes WHERE accessed < ?", (stale_cutoff,)
        ).fetchone()["c"]

        # 平均重要性 (weight)
        avg_w = self.conn.execute(
            "SELECT AVG(weight) as w FROM nodes"
        ).fetchone()["w"] or 0.0

        # 冗余分析: 对每对同 kind 的节点计算相似度
        all_nodes = self.conn.execute(
            "SELECT id, label, kind FROM nodes ORDER BY kind LIMIT ?", (max_nodes,)
        ).fetchall()
        redundant_count = 0
        by_kind: dict[str, list] = defaultdict(list)
        for row in all_nodes:
            by_kind[row["kind"]].append(row)
        for kind, nodes in by_kind.items():
            for i in range(len(nodes)):
                for j in range(i + 1, min(i + 20, len(nodes))):
                    sim = self._content_similarity(nodes[i]["label"], nodes[j]["label"])
                    if sim > 0.6:
                        redundant_count += 1

        # NOOP ratio (通过最近操作统计)
        noop_ratio = stale_nodes / total if total > 0 else 0

        # 健康评分 (0-100)
        health = 100
        if total > max_nodes:
            health -= min(20, (total - max_nodes) / max_nodes * 20)
        health -= min(15, stale_nodes / max(total, 1) * 30)
        health -= min(15, redundant_count / max(total, 1) * 30)
        health -= min(10, max(0, (0.3 - avg_w) / 0.3 * 10)) if avg_w < 0.3 else 0
        health = max(0, int(health))

        suggestions = []
        if stale_nodes > total * 0.3:
            suggestions.append(f"High staleness: {stale_nodes} nodes untouched in {staleness_days}d. Consider prune().")
        if redundant_count > total * 0.1:
            suggestions.append(f"{redundant_count} redundant pairs detected. Consider dedup_nodes().")
        if avg_w < 0.3:
            suggestions.append("Low average weight. Consider importance_rank() review.")
        if total > max_nodes:
            suggestions.append(f"Graph exceeds {max_nodes} nodes. Consider prune_by_relevance().")
        if not suggestions:
            suggestions.append("Graph is healthy.")

        return {
            "health_score": health,
            "total_nodes": total,
            "redundant_pairs": redundant_count,
            "stale_nodes": stale_nodes,
            "avg_importance": round(avg_w, 3),
            "noop_ratio": round(noop_ratio, 3),
            "suggestions": suggestions,
        }

    def fifa_forget(self, budget: int = 50, min_importance: float = 0.1) -> dict:
        """FiFA (Find-and-Forget): 有界遗忘策略。

        删除 budget 个最低重要性 + 最陈旧的节点, 保留高价值记忆。
        MemoryArena 启发: selective forgetting 是核心能力。

        Returns:
            {removed, kept, details}
        """
        import time
        all_nodes = self.conn.execute(
            "SELECT id, label, kind, weight, accessed FROM nodes ORDER BY weight ASC, accessed ASC LIMIT ?",
            (budget,)
        ).fetchall()

        removed = []
        for row in all_nodes:
            if row["weight"] < min_importance:
                self.delete_node(row["id"])
                removed.append({"id": row["id"], "label": row["label"],
                               "weight": row["weight"]})

        remaining = self.stats().get("nodes", 0)
        return {
            "removed": len(removed),
            "kept": remaining,
            "details": removed[:10],  # 前10个详情
        }

    def memory_compact(self, similarity_threshold: float = 0.7,
                       max_merge_per_pass: int = 20) -> dict:
        """记忆压缩: 合并高相似度节点, 减少冗余。

        Returns:
            {merged_count, freed_edges, details}
        """
        all_nodes = self.conn.execute(
            "SELECT id, label, kind FROM nodes ORDER BY kind"
        ).fetchall()

        merged = 0
        details = []
        by_kind: dict[str, list] = defaultdict(list)
        for row in all_nodes:
            by_kind[row["kind"]].append(dict(row))

        for kind, nodes in by_kind.items():
            skip = set()
            for i in range(min(len(nodes), max_merge_per_pass)):
                if i in skip or merged >= max_merge_per_pass:
                    break
                for j in range(i + 1, len(nodes)):
                    if j in skip or merged >= max_merge_per_pass:
                        break
                    sim = self._content_similarity(nodes[i]["label"], nodes[j]["label"])
                    if sim >= similarity_threshold:
                        # Merge j into i
                        self.merge_nodes(nodes[j]["id"], nodes[i]["id"])
                        skip.add(j)
                        merged += 1
                        details.append({
                            "merged": nodes[j]["label"][:30],
                            "into": nodes[i]["label"][:30],
                            "similarity": round(sim, 3),
                        })

        return {"merged_count": merged, "details": details}

    def memory_feedback(self, corrections: list[dict]) -> dict:
        """从反馈数据学习调整阈值 (AgeMem 在线学习启发)。

        corrections: [{content, correct_op, chosen_op, was_correct}]

        Returns:
            {adjusted_threshold, adjustments, samples}
        """
        if not corrections:
            return {"adjusted_threshold": 0.5, "adjustments": 0, "samples": 0}

        # 统计误判模式
        false_adds = sum(1 for c in corrections
                         if c.get("chosen_op") == "ADD"
                         and not c.get("was_correct", True))
        missed_adds = sum(1 for c in corrections
                          if c.get("correct_op") == "ADD"
                          and c.get("chosen_op") != "ADD")

        total = len(corrections)
        # 如果 ADD 误判多 → 提高阈值
        # 如果 ADD 遗漏多 → 降低阈值
        delta = (false_adds - missed_adds) / total * 0.2  # 最大调整 0.2
        new_threshold = max(0.1, min(0.9, 0.5 + delta))

        return {
            "adjusted_threshold": round(new_threshold, 3),
            "adjustments": delta != 0,
            "samples": total,
            "false_adds": false_adds,
            "missed_adds": missed_adds,
        }

    def memory_stats_summary(self) -> dict:
        """记忆概览仪表盘: 类型分布 + 权重分布 + 时间跨度。

        Returns:
            {total, by_kind, weight_dist, time_span, top_weighted}
        """
        import time
        stats = self.stats()
        total = stats.get("nodes", 0)

        if total == 0:
            return {"total": 0, "by_kind": {}, "weight_dist": {},
                    "time_span": 0, "top_weighted": []}

        # 类型分布
        by_kind = self.count_by_kind()

        # 权重分布
        rows = self.conn.execute(
            "SELECT weight FROM nodes ORDER BY weight DESC"
        ).fetchall()
        weights = [r["weight"] for r in rows]
        weight_dist = {
            "high": sum(1 for w in weights if w >= 0.7),
            "medium": sum(1 for w in weights if 0.3 <= w < 0.7),
            "low": sum(1 for w in weights if w < 0.3),
            "avg": round(sum(weights) / len(weights), 3),
        }

        # 时间跨度
        times = self.conn.execute(
            "SELECT MIN(created) as min_t, MAX(created) as max_t FROM nodes"
        ).fetchone()
        time_span = (times["max_t"] - times["min_t"]) if times["min_t"] else 0

        # Top weighted
        top_rows = self.conn.execute(
            "SELECT id, label, kind, weight FROM nodes ORDER BY weight DESC LIMIT 5"
        ).fetchall()
        top_weighted = [{"id": r["id"], "label": r["label"],
                         "kind": r["kind"], "weight": r["weight"]}
                        for r in top_rows]

        return {
            "total": total,
            "by_kind": dict(by_kind),
            "weight_dist": weight_dist,
            "time_span_days": round(time_span / 86400, 1),
            "top_weighted": top_weighted,
        }

    # ── memorywire 互操作 ──────────────────────────────────
    # memorywire v0.1 wire format: 5 ops × 4 types
    # Ops: remember, recall, forget, merge, expire
    # Types: semantic, episodic, procedural, emotional
    # See: https://arxiv.org/abs/2606.01138

    # Map internal kinds ↔ memorywire types
    _MW_TYPE_MAP = {
        "fact": "semantic",
        "concept": "semantic",
        "event": "episodic",
        "person": "episodic",
        "skill": "procedural",
        "emotion": "emotional",
    }
    _MW_TYPE_REVERSE = {
        "semantic": "fact",
        "episodic": "event",
        "procedural": "skill",
        "emotional": "emotion",
    }

    def to_memorywire(self, agent_id: str = "default",
                      node_ids: list[str] | None = None) -> dict:
        """Export graph memories to memorywire v0.1 wire format.

        Produces a JSON-serializable dict of 'remember' operations that
        can be replayed into any memorywire-compatible backend.

        Args:
            agent_id: Agent identifier for the exported memories.
            node_ids: Optional list of specific nodes to export.
                      If None, exports all nodes.

        Returns:
            {"version": "0.1", "agent_id": ..., "memories": [...]}
        """
        if node_ids is None:
            rows = self.conn.execute("SELECT * FROM nodes").fetchall()
        else:
            placeholders = ",".join("?" * len(node_ids))
            rows = self.conn.execute(
                f"SELECT * FROM nodes WHERE id IN ({placeholders})", node_ids
            ).fetchall()

        # Also export edges as relationship metadata
        edge_map: dict[str, list[dict]] = {}
        for r in rows:
            linked = self.conn.execute(
                "SELECT target, relation, weight FROM edges WHERE source=?",
                (r["id"],)
            ).fetchall()
            if linked:
                edge_map[r["id"]] = [
                    {"target": l["target"], "relation": l["relation"],
                     "weight": l["weight"]}
                    for l in linked
                ]

        memories = []
        for r in rows:
            tags = json.loads(r["tags"])
            mw_type = self._MW_TYPE_MAP.get(r["kind"], "semantic")
            entry = {
                "operation": "remember",
                "agent_id": agent_id,
                "type": mw_type,
                "content": r["label"],
                "confidence": round(r["weight"], 4),
                "source": tags[0] if tags else None,
                "metadata": {
                    "node_id": r["id"],
                    "kind": r["kind"],
                    "data": json.loads(r["data"]),
                    "tags": tags,
                    "created": r["created"],
                    "accessed": r["accessed"],
                },
                "expires_at": None,
                "approval_required": False,
            }
            if r["id"] in edge_map:
                entry["metadata"]["relationships"] = edge_map[r["id"]]
            memories.append(entry)

        return {"version": "0.1", "agent_id": agent_id, "memories": memories}

    def from_memorywire(self, wire_data: dict) -> int:
        """Import memorywire v0.1 wire format into this graph.

        Accepts the output of to_memorywire() or any memorywire-compatible
        'remember' operation list. Creates nodes and edges accordingly.

        Args:
            wire_data: Dict with 'memories' key containing a list of
                       remember operation dicts.

        Returns:
            Number of nodes imported.
        """
        memories = wire_data.get("memories", [])
        count = 0
        for mem in memories:
            if mem.get("operation") != "remember":
                continue

            mw_type = mem.get("type", "semantic")
            kind = self._MW_TYPE_REVERSE.get(mw_type, "fact")
            content = mem.get("content", "")
            meta = mem.get("metadata", {})

            # Preserve original node_id if present
            node_id = meta.get("node_id") or uuid.uuid4().hex[:12]
            tags = meta.get("tags", [])
            if mem.get("source") and mem["source"] not in tags:
                tags.insert(0, mem["source"])

            now = time.time()
            self.conn.execute(
                "INSERT OR REPLACE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                (node_id, content, kind,
                 json.dumps(meta.get("data", {})),
                 meta.get("created", now), meta.get("accessed", now),
                 mem.get("confidence", 1.0), json.dumps(tags))
            )
            self._fts_sync_node(node_id)

            # Restore edges if present
            for rel in meta.get("relationships", []):
                self.conn.execute(
                    "INSERT OR IGNORE INTO edges VALUES (?,?,?,?)",
                    (node_id, rel["target"], rel["relation"],
                     rel.get("weight", 1.0))
                )
            count += 1

        self.conn.commit()
        return count

    # ===================================================================
    # CRDT-based Multi-Agent Merge (06-16 research: LWW / OR-Set / Trust-weighted)
    # ===================================================================

    def merge_crdt(self, other_graph_data: dict, strategy: str = "lww",
                   trust_weight: float = 0.5) -> dict:
        """Merge another graph's data using CRDT-inspired conflict resolution.

        Strategies (from Multi-Agent Memory Consensus research, 06-16):
          - lww: Last-Writer-Wins by accessed timestamp (deterministic)
          - or_set: OR-Set union — keep both versions, link with crdt_merge
          - trust: Trust-weighted — blend weights, prefer higher-trust content

        Args:
            other_graph_data: Export dict from another MemoryGraph.export_json()
            strategy: Merge strategy (lww | or_set | trust)
            trust_weight: Weight for *other* graph's data (0-1, default 0.5)

        Returns:
            Summary dict: {nodes_added, nodes_updated, nodes_skipped, edges_added}
        """
        summary = {"nodes_added": 0, "nodes_updated": 0, "nodes_skipped": 0, "edges_added": 0}

        for node in other_graph_data.get("nodes", []):
            nid = str(node["id"])
            existing = self.get_node(nid)

            if existing is None:
                # New node — direct insert to preserve ID
                tags = node.get("tags", [])
                if isinstance(tags, str):
                    tags = [tags]
                self.conn.execute(
                    "INSERT OR REPLACE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                    (nid, node.get("label", ""), node.get("kind", "fact"),
                     json.dumps(node.get("data", {})),
                     node.get("created", time.time()), node.get("accessed", time.time()),
                     node.get("weight", 1.0), json.dumps(tags)))
                if self._fts_enabled:
                    self._fts_sync_node(nid)
                summary["nodes_added"] += 1
                continue

            if strategy == "lww":
                other_ts = node.get("accessed", node.get("created", 0))
                local_ts = existing.accessed or existing.created or 0
                if other_ts > local_ts:
                    self.update_node(nid, label=node.get("label", existing.label),
                                     kind=node.get("kind", existing.kind),
                                     data=node.get("data", {}),
                                     weight=node.get("weight", existing.weight))
                    summary["nodes_updated"] += 1
                else:
                    summary["nodes_skipped"] += 1

            elif strategy == "or_set":
                # OR-Set: preserve both versions
                merged_id = f"{nid}::crdt::{int(node.get('accessed', 0))}"
                self.conn.execute(
                    "INSERT OR REPLACE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                    (merged_id, node.get("label", ""), node.get("kind", "fact"),
                     json.dumps(node.get("data", {})),
                     node.get("created", time.time()), node.get("accessed", time.time()),
                     node.get("weight", 1.0), json.dumps(node.get("tags", []))))
                if self._fts_enabled:
                    self._fts_sync_node(merged_id)
                self.link(nid, merged_id, "crdt_merge")
                summary["nodes_added"] += 1

            elif strategy == "trust":
                other_w = node.get("weight", 1.0)
                local_w = existing.weight or 1.0
                blended = trust_weight * other_w + (1 - trust_weight) * local_w
                # Update content first, then set blended weight
                if trust_weight > 0.5:
                    self.update_node(nid, label=node.get("label", existing.label),
                                     data=node.get("data", {}),
                                     weight=blended)
                else:
                    self.reweight(nid, blended)
                summary["nodes_updated"] += 1

            else:
                summary["nodes_skipped"] += 1

        self.conn.commit()

        # Merge edges (always union)
        for edge in other_graph_data.get("edges", []):
            s, t = str(edge["source"]), str(edge["target"])
            if not self.is_linked(s, t):
                self.link(s, t, edge.get("relation", "rel"),
                          weight=edge.get("weight", 1.0))
                summary["edges_added"] += 1

        return summary

    # ===================================================================
    # Weighted Degree & Neighborhood Census
    # ===================================================================

    def weighted_degree(self, node_id: str) -> float:
        """Sum of edge weights for a node (in + out).

        Unlike degree count, this captures connection *strength*.
        """
        row = self.conn.execute(
            "SELECT COALESCE(SUM(weight), 0) AS w FROM edges WHERE source = ? OR target = ?",
            (node_id, node_id),
        ).fetchone()
        return float(row["w"]) if row else 0.0

    def weighted_degree_all(self) -> dict[str, float]:
        """Weighted degree for every node."""
        nodes = [str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        return {nid: self.weighted_degree(nid) for nid in nodes}

    def neighborhood_census(self) -> dict[str, dict]:
        """Per-node neighborhood census: degree, weighted_degree, neighbors list.

        Useful for batch analysis and exports.
        """
        nodes = [str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        edge_rows = self.conn.execute("SELECT source, target, weight FROM edges").fetchall()
        nbrs: dict[str, list[str]] = {n: [] for n in nodes}
        wsum: dict[str, float] = {n: 0.0 for n in nodes}
        for e in edge_rows:
            s, t = str(e["source"]), str(e["target"])
            w = float(e["weight"]) if e["weight"] is not None else 1.0
            if s in nbrs:
                nbrs[s].append(t)
                wsum[s] += w
            if t in nbrs:
                nbrs[t].append(s)
                wsum[t] += w
        return {
            n: {"degree": len(nbrs[n]), "weighted_degree": wsum[n], "neighbors": nbrs[n]}
            for n in nodes
        }

    # ===================================================================
    # Vector Clock & Incremental Sync (Multi-Agent Causal Consistency)
    # ===================================================================

    def vector_clock(self, node_id: str) -> dict[str, int]:
        """Return the vector clock for a node.

        Tracks causal version per agent (writer). Used by merge_crdt
        to detect concurrent updates vs causal ordering.

        The clock is stored in node metadata under '_vc'. If absent,
        returns a default clock {'_default': 0}.
        """
        node = self.get_node(node_id)
        if node is None:
            raise KeyError(f"Node not found: {node_id}")
        vc = node.data.get("_vc", {"_default": 0})
        if not isinstance(vc, dict):
            vc = {"_default": 0}
        return vc

    def _vector_clock_increment(self, node_id: str, agent_id: str = "_self"):
        """Increment the vector clock entry for *agent_id* on a node."""
        node = self.get_node(node_id)
        if node is None:
            return
        vc = dict(node.data.get("_vc", {}))
        vc[agent_id] = vc.get(agent_id, 0) + 1
        # Merge into data without clobbering other fields
        new_data = dict(node.data)
        new_data["_vc"] = vc
        self.conn.execute(
            "UPDATE nodes SET data=? WHERE id=?",
            (json.dumps(new_data), node_id))
        self.conn.commit()

    @staticmethod
    def _vc_compare(vc_a: dict[str, int], vc_b: dict[str, int]) -> str:
        """Compare two vector clocks.

        Returns:
          'before' — vc_a < vc_b (a happened-before b)
          'after'  — vc_a > vc_b (a happened-after b)
          'equal'  — identical
          'concurrent' — neither precedes (conflict)
        """
        keys = set(vc_a) | set(vc_b)
        a_le_b = True
        b_le_a = True
        for k in keys:
            a_val = vc_a.get(k, 0)
            b_val = vc_b.get(k, 0)
            if a_val > b_val:
                a_le_b = False
            if b_val > a_val:
                b_le_a = False
        if a_le_b and b_le_a:
            return "equal"
        if a_le_b:
            return "before"
        if b_le_a:
            return "after"
        return "concurrent"

    def subscribe(self, callback) -> None:
        """Register a callback for node change events.

        The callback receives a dict with keys:
          event: 'add' | 'update' | 'delete' | 'link'
          node_id: affected node id
          agent_id: writer agent (for multi-agent sync)
          timestamp: event time

        Multiple callbacks are supported (called in registration order).
        """
        if not hasattr(self, '_subscribers'):
            self._subscribers = []
        self._subscribers.append(callback)

    def _notify(self, event: str, node_id: str, agent_id: str = "_self") -> None:
        """Internal: fire subscriber callbacks."""
        if not hasattr(self, '_subscribers'):
            return
        evt = {
            "event": event,
            "node_id": node_id,
            "agent_id": agent_id,
            "timestamp": time.time(),
        }
        for cb in self._subscribers:
            try:
                cb(evt)
            except Exception:
                pass  # subscriber errors don't break the operation

    def get_changes(self, since: float = 0.0) -> dict:
        """Export all node/edge changes since a timestamp (epoch seconds).

        Used for incremental delta-sync between agents.
        Pairs with apply_changes() on the receiving side.

        Returns:
          {'nodes': [...], 'edges': [...], 'timestamp': current_time}
        """
        nodes = [
            {
                "id": str(r["id"]), "label": r["label"], "kind": r["kind"],
                "data": json.loads(r["data"]) if r["data"] else {},
                "created": r["created"], "accessed": r["accessed"],
                "weight": r["weight"],
                "tags": json.loads(r["tags"]) if r["tags"] else [],
            }
            for r in self.conn.execute(
                "SELECT * FROM nodes WHERE accessed >= ? OR created >= ?",
                (since, since)).fetchall()
        ]
        edges = [
            {"source": str(r["source"]), "target": str(r["target"]),
             "relation": r["relation"], "weight": r["weight"]}
            for r in self.conn.execute(
                "SELECT * FROM edges WHERE 1=1").fetchall()
        ]  # edges don't have timestamps; include all (small overhead)
        return {
            "nodes": nodes,
            "edges": edges,
            "timestamp": time.time(),
        }

    def apply_changes(self, delta: dict, agent_id: str = "_remote",
                      strategy: str = "lww") -> dict:
        """Apply a delta (from get_changes) using vector-clock-aware merge.

        Unlike merge_crdt (full export), this works with incremental deltas.
        Uses vector clocks to detect causal ordering:
          - 'before'/'equal': skip (remote is older or same)
          - 'after': accept (remote is newer)
          - 'concurrent': apply strategy (lww/or_set/trust)

        Args:
          delta: Output from another graph's get_changes()
          agent_id: Identifier for the remote agent
          strategy: Conflict strategy for concurrent updates

        Returns:
          Summary dict with counts + any concurrent conflicts detected.
        """
        summary = {"nodes_added": 0, "nodes_updated": 0, "nodes_skipped": 0,
                   "concurrent_conflicts": 0, "edges_added": 0}

        for node in delta.get("nodes", []):
            nid = str(node["id"])
            existing = self.get_node(nid)

            if existing is None:
                # New node — direct insert, seed its vector clock
                tags = node.get("tags", [])
                if isinstance(tags, str):
                    tags = [tags]
                data = dict(node.get("data", {}))
                # Ensure vector clock exists
                if "_vc" not in data:
                    data["_vc"] = {agent_id: 1}
                self.conn.execute(
                    "INSERT OR REPLACE INTO nodes (id,label,kind,data,created,accessed,weight,tags) VALUES (?,?,?,?,?,?,?,?)",
                    (nid, node.get("label", ""), node.get("kind", "fact"),
                     json.dumps(data),
                     node.get("created", time.time()), node.get("accessed", time.time()),
                     node.get("weight", 1.0), json.dumps(tags)))
                if self._fts_enabled:
                    self._fts_sync_node(nid)
                summary["nodes_added"] += 1
                self._notify("add", nid, agent_id)
                continue

            # Compare vector clocks
            local_vc = existing.data.get("_vc", {})
            remote_vc = node.get("data", {}).get("_vc", {})
            order = self._vc_compare(local_vc, remote_vc)

            if order in ("before", "equal"):
                # Local is same or newer — check if truly equal
                if order == "equal":
                    summary["nodes_skipped"] += 1
                    continue
                # Remote is newer — accept it
            if order == "concurrent":
                summary["concurrent_conflicts"] += 1
                if strategy == "lww":
                    other_ts = node.get("accessed", 0)
                    local_ts = existing.accessed or 0
                    if other_ts <= local_ts:
                        summary["nodes_skipped"] += 1
                        continue
                # For or_set/trust, fall through to merge_crdt logic

            # Apply the update
            merged_data = dict(node.get("data", {}))
            # Merge vector clocks
            merged_vc = dict(local_vc)
            for k, v in remote_vc.items():
                merged_vc[k] = max(merged_vc.get(k, 0), v)
            merged_data["_vc"] = merged_vc

            self.update_node(nid, label=node.get("label", existing.label),
                             data=merged_data,
                             weight=node.get("weight", existing.weight))
            summary["nodes_updated"] += 1
            self._notify("update", nid, agent_id)

        # Merge edges (union)
        for edge in delta.get("edges", []):
            s, t = str(edge["source"]), str(edge["target"])
            if not self.is_linked(s, t):
                self.link(s, t, edge.get("relation", "rel"),
                          weight=edge.get("weight", 1.0))
                summary["edges_added"] += 1

        self.conn.commit()
        return summary

    # ── Memory Consolidation (GAM ICLR 2026) ──────────────────────

    def semantic_divergence(self, node_id: str) -> dict | None:
        """检测节点与邻居的语义分歧程度 (GAM-inspired)。

        比较 node 的 label/kind 与其直接邻居，计算分歧分数 0-1。
        高分歧 → 该节点可能需要 consolidation (promote/demote/merge)。

        Returns:
            {node_id, label, kind, neighbor_count, divergence, avg_similarity,
             kind_mismatch_ratio, suggestion}
        """
        node = self.get_node(node_id)
        if not node:
            return None

        nbrs = self.neighbors(node_id)
        if not nbrs:
            return {
                "node_id": node_id, "label": node.label, "kind": node.kind,
                "neighbor_count": 0, "divergence": 0.0,
                "avg_similarity": 0.0, "kind_mismatch_ratio": 0.0,
                "suggestion": "isolated",
            }

        sims: list[float] = []
        kind_mismatches = 0
        for nbr in nbrs:
            sim = self._content_similarity(node.label, nbr.label)
            sims.append(sim)
            if nbr.kind != node.kind:
                kind_mismatches += 1

        avg_sim = sum(sims) / len(sims) if sims else 0.0
        # Divergence = 1 - avg_similarity (higher = more different from neighbors)
        divergence = round(1.0 - avg_sim, 4)
        kind_mismatch_ratio = round(kind_mismatches / len(nbrs), 4) if nbrs else 0.0

        # Suggestion based on divergence level
        if divergence > 0.8 and kind_mismatch_ratio > 0.7:
            suggestion = "promote"   # Very different from neighbors → new cluster
        elif divergence < 0.2:
            suggestion = "demote"    # Very similar → merge into neighborhood
        elif kind_mismatch_ratio > 0.5:
            suggestion = "reclassify"  # Kind doesn't match neighborhood
        else:
            suggestion = "keep"

        return {
            "node_id": node_id,
            "label": node.label,
            "kind": node.kind,
            "neighbor_count": len(nbrs),
            "divergence": divergence,
            "avg_similarity": round(avg_sim, 4),
            "kind_mismatch_ratio": kind_mismatch_ratio,
            "suggestion": suggestion,
        }

    def divergence_scan(self, threshold: float = 0.5,
                        limit: int = 100) -> list[dict]:
        """扫描全图，找出高分歧节点 (批量诊断)。

        Args:
            threshold: 最小分歧分数 (0-1)
            limit: 最大返回数量

        Returns:
            List of divergence reports sorted by divergence descending
        """
        all_ids = [r["id"] for r in self.conn.execute(
            "SELECT id FROM nodes ORDER BY accessed DESC LIMIT ?", (limit * 3,)
        ).fetchall()]

        results = []
        for nid in all_ids:
            report = self.semantic_divergence(nid)
            if report and report["divergence"] >= threshold:
                results.append(report)
            if len(results) >= limit:
                break

        results.sort(key=lambda r: r["divergence"], reverse=True)
        return results

    # divergence_scan uses semantic_divergence internally, no changes needed

    def consolidate_memory(self, strategy: str = "auto",
                           divergence_threshold: float = 0.7,
                           similarity_threshold: float = 0.25,
                           dry_run: bool = False) -> dict:
        """记忆固化: 基于语义分歧的记忆整理 (GAM ICLR 2026 inspired)。

        策略:
        - promote: 高分歧节点标记为新聚类种子 (kind 添加 'cluster_seed')
        - demote: 低分歧节点合并到最相似邻居
        - reclassify: kind 与邻居不一致 → 更新 kind 为多数邻居的 kind
        - auto: 自动选择最佳策略 per node (默认)

        Args:
            strategy: auto|promote|demote|reclassify
            divergence_threshold: promote 阈值
            similarity_threshold: demote 阈值 (1-similarity = divergence)
            dry_run: 仅报告不执行

        Returns:
            {scanned, promoted, demoted, reclassified, kept, details}
        """
        all_ids = [r["id"] for r in self.conn.execute(
            "SELECT id FROM nodes"
        ).fetchall()]

        result = {"scanned": 0, "promoted": 0, "demoted": 0,
                  "reclassified": 0, "kept": 0, "details": []}

        for nid in all_ids:
            report = self.semantic_divergence(nid)
            if not report:
                continue
            result["scanned"] += 1
            suggestion = report["suggestion"] if strategy == "auto" else strategy
            div = report["divergence"]

            if suggestion == "promote" or (suggestion == "auto" and div >= divergence_threshold):
                if not dry_run:
                    self.tag_nodes("cluster_seed", [nid])
                result["promoted"] += 1
                result["details"].append(
                    {"node_id": nid, "action": "promote", "divergence": div})

            elif suggestion == "demote" or (suggestion == "auto" and div <= similarity_threshold):
                # Find most similar neighbor and merge into it
                if not dry_run:
                    nbrs = self.neighbors(nid)
                    best_target = None
                    best_sim = 0.0
                    node = self.get_node(nid)
                    for nbr in nbrs:
                        if node:
                            sim = self._content_similarity(node.label, nbr.label)
                            if sim > best_sim:
                                best_sim = sim
                                best_target = nbr.id
                    if best_target and best_sim > 0.3:
                        self.merge_nodes(nid, best_target)
                result["demoted"] += 1
                result["details"].append(
                    {"node_id": nid, "action": "demote", "divergence": div})

            elif suggestion == "reclassify":
                if not dry_run:
                    # Set kind to majority neighbor kind
                    nbrs = self.neighbors(nid)
                    kind_counts: dict[str, int] = defaultdict(int)
                    for nbr in nbrs:
                        kind_counts[nbr.kind] += 1
                    if kind_counts:
                        majority_kind = max(kind_counts, key=kind_counts.get)
                        node = self.get_node(nid)
                        self.update_node(nid, label=node.label,
                                         kind=majority_kind, data=node.data)
                result["reclassified"] += 1
                result["details"].append(
                    {"node_id": nid, "action": "reclassify", "divergence": div})

            else:
                result["kept"] += 1

        if not dry_run:
            self.conn.commit()
        return result

    # ── Retention Scoring & Smart Eviction ────────────────────────

    def retention_score(self, node_id: str,
                        w_importance: float = 0.3,
                        w_recency: float = 0.25,
                        w_connectivity: float = 0.25,
                        w_divergence: float = 0.2) -> dict | None:
        """计算节点保留分数 (0-1), 综合重要性/时效/连接度/分歧度。

        用于智能驱逐决策: 低分节点优先驱逐。
        分数 = importance*w1 + recency*w2 + connectivity*w3 + divergence*w4

        Returns:
            {node_id, label, score, components: {importance, recency, connectivity, divergence}, recommendation}
        """
        node = self.get_node(node_id)
        if not node:
            return None

        # Importance: normalized weight (0-1)
        importance = min(node.weight, 1.0) if node.weight else 0.0

        # Recency: exponential decay based on age (half-life = 7 days)
        now = time.time()
        age_seconds = now - (node.accessed or node.created)
        recency = math.exp(-age_seconds / (7 * 86400))  # half-life ~7 days

        # Connectivity: degree / max_degree in graph (normalized)
        degree = len(self.neighbors(node_id))
        max_degree_row = self.conn.execute(
            "SELECT COUNT(*) as c FROM edges GROUP BY source ORDER BY c DESC LIMIT 1"
        ).fetchone()
        max_degree = max_degree_row["c"] if max_degree_row else 1
        connectivity = min(degree / max(max_degree, 1), 1.0)

        # Divergence: from semantic_divergence (high divergence = unique = keep)
        div_report = self.semantic_divergence(node_id)
        divergence = div_report["divergence"] if div_report else 0.0

        score = (importance * w_importance +
                 recency * w_recency +
                 connectivity * w_connectivity +
                 divergence * w_divergence)

        recommendation = "keep" if score >= 0.4 else ("review" if score >= 0.2 else "evict")

        return {
            "node_id": node_id,
            "label": node.label,
            "score": round(score, 4),
            "components": {
                "importance": round(importance, 4),
                "recency": round(recency, 4),
                "connectivity": round(connectivity, 4),
                "divergence": round(divergence, 4),
            },
            "recommendation": recommendation,
        }

    def memory_evict(self, budget: int = 20,
                     min_score: float = 0.15,
                     dry_run: bool = False) -> dict:
        """基于保留分数的智能驱逐 (FiFA + divergence-aware)。

        1. 计算所有节点 retention_score
        2. 按分数升序排序
        3. 驱逐分数 < min_score 的节点, 最多 budget 个

        Returns:
            {scanned, evicted, kept, details}
        """
        all_ids = [r["id"] for r in self.conn.execute(
            "SELECT id FROM nodes"
        ).fetchall()]

        scores = []
        for nid in all_ids:
            report = self.retention_score(nid)
            if report:
                scores.append(report)

        scores.sort(key=lambda r: r["score"])

        evicted = 0
        details = []
        for report in scores:
            if evicted >= budget:
                break
            if report["score"] >= min_score:
                break
            if not dry_run:
                self.delete_node(report["node_id"])
            evicted += 1
            details.append({
                "node_id": report["node_id"],
                "label": report["label"][:40],
                "score": report["score"],
            })

        if not dry_run:
            self.conn.commit()

        return {
            "scanned": len(scores),
            "evicted": evicted,
            "kept": len(scores) - evicted,
            "details": details,
        }

    # ── Cluster Seed Discovery (Consolidation follow-up) ──────────

    def cluster_seeds(self) -> list[dict]:
        """返回所有标记为 cluster_seed 的节点 (promote 操作的结果)。

        Returns:
            [{node_id, label, kind, weight, neighbor_count}]
        """
        rows = self.conn.execute(
            "SELECT id, label, kind, weight FROM nodes WHERE tags LIKE '%cluster_seed%'",
        ).fetchall()
        results = []
        for r in rows:
            nbrs = self.neighbors(r["id"])
            results.append({
                "node_id": r["id"],
                "label": r["label"],
                "kind": r["kind"],
                "weight": r["weight"],
                "neighbor_count": len(nbrs),
            })
        return results

    def seed_expansion(self, seed_id: str, max_hops: int = 2) -> dict | None:
        """从 cluster_seed 向外扩展，识别聚类边界 (BFS)。

        Returns:
            {seed_id, layers: {hop: [node_ids]}, boundary: [node_ids], size}
        """
        node = self.get_node(seed_id)
        if not node:
            return None

        layers = self.k_hop_neighbors(seed_id, max_hops)
        # Flatten all reached nodes
        all_reached = set()
        for hop, ids in layers.items():
            all_reached.update(ids)

        # Boundary = nodes in the outermost non-empty hop
        boundary = []
        for hop in range(max_hops, 0, -1):
            if hop in layers and layers[hop]:
                boundary = layers[hop]
                break

        return {
            "seed_id": seed_id,
            "seed_label": node.label,
            "layers": {str(k): v for k, v in layers.items()},
            "boundary": boundary,
            "size": len(all_reached) + 1,  # +1 for seed itself
        }

    def consolidation_report(self) -> dict:
        """生成完整记忆固化状态报告。

        Combines: divergence stats + cluster seeds + eviction candidates.

        Returns:
            {total_nodes, high_divergence_count, cluster_seeds,
             eviction_candidates, avg_retention, consolidation_health}
        """
        all_ids = [r["id"] for r in self.conn.execute(
            "SELECT id FROM nodes"
        ).fetchall()]

        if not all_ids:
            return {"total_nodes": 0, "high_divergence_count": 0,
                    "cluster_seeds": 0, "eviction_candidates": 0,
                    "avg_retention": 0.0, "consolidation_health": "empty"}

        high_div = 0
        scores = []
        for nid in all_ids:
            div_r = self.semantic_divergence(nid)
            if div_r and div_r["divergence"] > 0.5:
                high_div += 1
            ret_r = self.retention_score(nid)
            if ret_r:
                scores.append(ret_r["score"])

        seeds = self.cluster_seeds()
        evict_candidates = sum(1 for s in scores if s < 0.2)
        avg_retention = sum(scores) / len(scores) if scores else 0.0

        # Health: good if low high-div ratio + low eviction candidates
        high_div_ratio = high_div / len(all_ids)
        evict_ratio = evict_candidates / len(all_ids) if all_ids else 0
        if high_div_ratio < 0.2 and evict_ratio < 0.1:
            health = "healthy"
        elif high_div_ratio < 0.4 and evict_ratio < 0.3:
            health = "moderate"
        else:
            health = "needs_attention"

        return {
            "total_nodes": len(all_ids),
            "high_divergence_count": high_div,
            "high_divergence_ratio": round(high_div_ratio, 4),
            "cluster_seeds": len(seeds),
            "eviction_candidates": evict_candidates,
            "avg_retention": round(avg_retention, 4),
            "consolidation_health": health,
        }

    # ── Consolidation Pipeline (one-shot orchestrator) ────────────

    def consolidation_pipeline(self,
                               evict_budget: int = 10,
                               min_retention: float = 0.15,
                               dry_run: bool = False) -> dict:
        """一键记忆固化: scan → consolidate → evict → report.

        Orchestrates the full GAM pipeline in one call:
        1. divergence_scan — identify drifted nodes
        2. consolidate_memory(auto) — promote/demote/reclassify
        3. memory_evict — remove low-retention nodes (respects budget)
        4. consolidation_report — summary health dashboard

        Args:
            evict_budget: max nodes to evict (0 = skip eviction)
            min_retention: retention score below which nodes are eviction candidates
            dry_run: if True, report what *would* happen without modifying the graph

        Returns:
            {scan, consolidation, eviction, report, actions_total}
        """
        # Step 1: Scan for divergence issues
        scan_items = self.divergence_scan(threshold=0.5)
        scan = {"flagged": len(scan_items), "items": scan_items}

        # Step 2: Auto-consolidate (promote/demote/reclassify)
        cons = self.consolidate_memory(strategy="auto", dry_run=dry_run)

        # Step 3: Smart eviction (skip if budget is 0)
        if evict_budget > 0:
            evict = self.memory_evict(
                budget=evict_budget, min_score=min_retention, dry_run=dry_run)
        else:
            evict = {"scanned": 0, "evicted": 0, "kept": 0, "details": []}

        # Step 4: Generate report
        report = self.consolidation_report()

        actions = (cons.get("promoted", 0) + cons.get("demoted", 0) +
                   cons.get("reclassified", 0) + evict.get("evicted", 0))

        return {
            "scan": scan,
            "consolidation": cons,
            "eviction": evict,
            "report": report,
            "actions_total": actions,
            "dry_run": dry_run,
        }

    # ── Memory Decay (time-based weight management) ──────────────

    def memory_decay(self, half_life_days: float = 7.0,
                     min_weight: float = 0.01,
                     kinds: list[str] | None = None,
                     dry_run: bool = False) -> dict:
        """Apply exponential time-based weight decay to all (or filtered) nodes.

        Unlike decay_all() which is blunt-force, this provides:
        - Configurable half-life (weight halves every N days since last access)
        - Kind filtering (e.g., only decay 'event' nodes, preserve 'person')
        - Minimum weight floor (don't decay below this)
        - Dry-run preview

        Formula: new_weight = max(min_weight, weight * 0.5^(elapsed_days / half_life_days))

        Args:
            half_life_days: weight halves every this many days (default 7)
            min_weight: floor weight (don't decay below this)
            kinds: only decay these kinds (None = all)
            dry_run: preview without applying

        Returns:
            {scanned, decayed, skipped, total_before, total_after, min_accessed_age_days}
        """
        now = time.time()
        rows = self.conn.execute(
            "SELECT id, kind, accessed, weight FROM nodes"
        ).fetchall()

        scanned = 0
        decayed = 0
        skipped = 0
        total_before = 0.0
        total_after = 0.0
        max_age_days = 0.0

        for r in rows:
            if kinds and r["kind"] not in kinds:
                skipped += 1
                continue

            scanned += 1
            elapsed_days = (now - r["accessed"]) / 86400.0
            max_age_days = max(max_age_days, elapsed_days)
            old_w = r["weight"]
            total_before += old_w

            decay_factor = 0.5 ** (elapsed_days / half_life_days)
            new_w = max(min_weight, old_w * decay_factor)
            total_after += new_w

            if new_w < old_w:
                decayed += 1
                if not dry_run:
                    self.conn.execute(
                        "UPDATE nodes SET weight=? WHERE id=?",
                        (new_w, r["id"]))

        if not dry_run:
            self.conn.commit()

        return {
            "scanned": scanned,
            "decayed": decayed,
            "skipped": skipped,
            "total_before": round(total_before, 4),
            "total_after": round(total_after, 4),
            "weight_lost": round(total_before - total_after, 4),
            "max_accessed_age_days": round(max_age_days, 2),
            "half_life_days": half_life_days,
            "dry_run": dry_run,
        }

    # ── Entropy-Weighted Forgetting (Research #030) ──────────────
    # Inspired by: FadeMem (arXiv:2601.18642) dual-layer adaptive decay,
    # Oblivion (arXiv:2603.19550) cue-reactivated activation,
    # FSFM (arXiv:2604.20300) four-category forgetting taxonomy.
    #
    # Core insight: amg's entropy metrics are direct forgetting signals.
    # Low entropy = redundant/predictable → faster decay.
    # High entropy = information-rich → preservation.

    _ENTROPY_FLOOR = 0.3       # below = strong decay signal
    _ENTROPY_CEILING = 0.8     # above = preservation signal
    _ACCESS_BOOST = 0.2        # reinforcement per access
    _CONFLICT_PENALTY = 0.5    # penalty for unresolved conflicts

    def compute_activation(self, node_id: str,
                           entropy_profile: dict | None = None,
                           half_life_days: float = 7.0) -> dict | None:
        """Compute entropy-weighted activation score for a memory node.

        Combines FadeMem's adaptive exponential decay with amg's entropy
        framework to produce a [0, 1] activation score and a forgetting
        recommendation.

        Formula::

            A = base_decay × entropy_multiplier + access_boost - conflict_penalty

        where:
          - base_decay = exp(-λ × Δt), λ = ln(2) / half_life_days
          - entropy_multiplier depends on node's local entropy contribution
          - access_boost accounts for access frequency and recency
          - conflict_penalty accounts for unresolved contradictions

        Args:
            node_id: Target node.
            entropy_profile: Pre-computed entropy_profile() dict. If None,
                uses a degree-based proxy.
            half_life_days: Activation half-life (default 7 days).

        Returns:
            {activation, recommendation, reason, factors} or None if
            node not found.
        """
        import math
        row = self.conn.execute(
            "SELECT id, kind, weight, accessed, created FROM nodes WHERE id=?",
            (node_id,)
        ).fetchone()
        if not row:
            return None

        now = time.time()
        age_days = (now - row["created"]) / 86400.0
        last_access_days = (now - row["accessed"]) / 86400.0

        # 1. Base exponential decay (Oblivion formula)
        lam = math.log(2) / half_life_days
        base_decay = math.exp(-lam * age_days)

        # 2. Entropy modulation (amg innovation)
        # Use node degree as entropy proxy if no profile given
        if entropy_profile and "per_node" in (entropy_profile or {}):
            node_entropy = entropy_profile.get("per_node", {}).get(
                node_id, {}).get("shannon", 0.5)
        else:
            # Degree-based proxy: normalized Shannon of edge weights
            edges = self.conn.execute(
                "SELECT weight FROM edges WHERE source=? OR target=?",
                (node_id, node_id)
            ).fetchall()
            if not edges:
                node_entropy = 0.0  # Isolated = lowest entropy
            else:
                weights = [e["weight"] for e in edges]
                total = sum(weights)
                if total <= 0:
                    node_entropy = 0.0
                else:
                    probs = [w / total for w in weights]
                    node_entropy = -sum(p * math.log(p + 1e-12)
                                        for p in probs if p > 0)
                    # Normalize by max entropy
                    n = len(weights)
                    max_h = math.log(n) if n > 1 else 1.0
                    node_entropy = node_entropy / max_h if max_h > 0 else 0.0

        if node_entropy < self._ENTROPY_FLOOR:
            entropy_multiplier = 0.5 + node_entropy  # [0.5, 0.8)
        elif node_entropy > self._ENTROPY_CEILING:
            entropy_multiplier = 1.0 + (node_entropy -
                                       self._ENTROPY_CEILING) * 2  # [1.0, 1.4+)
        else:
            entropy_multiplier = 0.8 + (node_entropy - 0.3) * 0.4  # [0.8, 1.0]

        # 3. Access reinforcement (Oblivion's Rᵢ terms)
        # Count in-edges as proxy for access frequency
        access_count = self.conn.execute(
            "SELECT COUNT(*) as c FROM edges WHERE target=?",
            (node_id,)
        ).fetchone()["c"]
        access_boost = 0.0
        if access_count > 0:
            access_boost = (self._ACCESS_BOOST
                             * min(access_count / 5.0, 1.0)
                             * math.exp(-lam * last_access_days))

        # 4. Conflict penalty (check for contradicting edges)
        conflict_count = self.conn.execute(
            "SELECT COUNT(*) as c FROM edges WHERE "
            "(source=? OR target=?) AND relation='contradicts'",
            (node_id, node_id)
        ).fetchone()["c"]
        conflict_penalty = 0.0
        if conflict_count > 0:
            conflict_penalty = (self._CONFLICT_PENALTY
                                * min(conflict_count * 0.1, 0.3))

        # Final activation
        activation = max(0.0, min(1.0,
            base_decay * entropy_multiplier + access_boost - conflict_penalty
        ))

        # Recommendation (FSFM taxonomy)
        if activation < 0.1:
            recommendation = "DELETE"
            reason = f"Activation {activation:.3f} below deletion threshold"
        elif activation < 0.25:
            recommendation = "ARCHIVE"
            reason = f"Low activation ({activation:.3f}), entropy={node_entropy:.3f}"
        elif activation < 0.4 and node_entropy < self._ENTROPY_FLOOR:
            recommendation = "CONSOLIDATE"
            reason = f"Low entropy ({node_entropy:.3f}) + moderate decay"
        elif conflict_count > 0 and activation < 0.5:
            recommendation = "RESOLVE_OR_DELETE"
            reason = f"{conflict_count} unresolved conflicts + decay"
        else:
            recommendation = "KEEP"
            reason = f"Healthy activation ({activation:.3f})"

        return {
            "node_id": node_id,
            "activation": round(activation, 4),
            "recommendation": recommendation,
            "reason": reason,
            "factors": {
                "base_decay": round(base_decay, 4),
                "entropy": round(node_entropy, 4),
                "entropy_multiplier": round(entropy_multiplier, 4),
                "access_boost": round(access_boost, 4),
                "conflict_penalty": round(conflict_penalty, 4),
                "age_days": round(age_days, 2),
                "last_access_days": round(last_access_days, 2),
                "access_count": access_count,
                "conflict_count": conflict_count,
            },
        }

    def apply_decay(self, half_life_days: float = 7.0,
                    kinds: list[str] | None = None,
                    dry_run: bool = False,
                    archive_threshold: float = 0.25,
                    delete_threshold: float = 0.1) -> dict:
        """Apply entropy-weighted decay to all (or filtered) nodes.

        Unlike ``memory_decay()`` (pure time-based), this uses
        ``compute_activation()`` to combine entropy, access patterns,
        and conflicts into a unified forgetting signal.

        Nodes below ``delete_threshold`` are deleted entirely.
        Nodes below ``archive_threshold`` have weight reduced by 50%.
        Nodes at or above ``archive_threshold`` get a 10% weight reduction
        (gentle aging).

        Args:
            half_life_days: Activation half-life (default 7 days).
            kinds: Only process these kinds (None = all).
            dry_run: Preview without modifying.
            archive_threshold: Below this = significant weight cut.
            delete_threshold: Below this = node deletion.

        Returns:
            {scanned, kept, archived, deleted, activations}
        """
        rows = self.conn.execute(
            "SELECT id, kind, weight FROM nodes"
        ).fetchall()

        scanned = 0
        kept = 0
        archived = 0
        deleted = 0
        weight_before = 0.0
        weight_after = 0.0
        recommendations = {"KEEP": 0, "ARCHIVE": 0, "CONSOLIDATE": 0,
                           "DELETE": 0, "RESOLVE_OR_DELETE": 0}
        details_deleted = []

        for r in rows:
            if kinds and r["kind"] not in kinds:
                continue

            scanned += 1
            result = self.compute_activation(r["id"],
                                             half_life_days=half_life_days)
            if not result:
                continue

            rec = result["recommendation"]
            recommendations[rec] = recommendations.get(rec, 0) + 1
            act = result["activation"]
            old_w = r["weight"]
            weight_before += old_w

            if act < delete_threshold or rec == "DELETE":
                if not dry_run:
                    self.delete_node(r["id"])
                deleted += 1
                details_deleted.append({
                    "id": r["id"], "activation": act,
                    "old_weight": old_w,
                })
                weight_after += 0.0
            elif act < archive_threshold or rec in ("ARCHIVE", "CONSOLIDATE"):
                new_w = old_w * 0.5
                if not dry_run:
                    self.conn.execute(
                        "UPDATE nodes SET weight=? WHERE id=?",
                        (new_w, r["id"]))
                archived += 1
                weight_after += new_w
            else:
                # Gentle aging for kept nodes
                new_w = old_w * 0.9
                if not dry_run:
                    self.conn.execute(
                        "UPDATE nodes SET weight=? WHERE id=?",
                        (new_w, r["id"]))
                kept += 1
                weight_after += new_w

        if not dry_run:
            self.conn.commit()

        return {
            "scanned": scanned,
            "kept": kept,
            "archived": archived,
            "deleted": deleted,
            "recommendations": recommendations,
            "weight_before": round(weight_before, 4),
            "weight_after": round(weight_after, 4),
            "weight_lost": round(weight_before - weight_after, 4),
            "delete_threshold": delete_threshold,
            "archive_threshold": archive_threshold,
            "half_life_days": half_life_days,
            "dry_run": dry_run,
            "details_deleted": details_deleted[:10],
        }

    # ── Forgetting Policy Selector (FSFM Taxonomy, Research #030) ──

    _FSFM_POLICIES = {
        "passive_decay": {
            "description": "Exponential time-based decay modulated by access frequency",
            "half_life_days": 7.0,
            "min_weight": 0.01,
            "delete_threshold": 0.05,
            "archive_threshold": 0.2,
        },
        "active_deletion": {
            "description": "Remove outdated/contradicted entries via conflict resolution",
            "half_life_days": 14.0,  # Slower decay, focus on conflicts
            "min_weight": 0.05,
            "delete_threshold": 0.15,
            "archive_threshold": 0.3,
            "require_conflict": True,
        },
        "safety_purge": {
            "description": "Force-purge sensitive/malicious/privacy-compromising content",
            "half_life_days": 1.0,  # Aggressive
            "min_weight": 0.0,
            "delete_threshold": 0.5,  # Delete most things
            "archive_threshold": 0.7,
            "kinds": ["sensitive", "malicious", "expired_credential"],
        },
        "adaptive_reinforcement": {
            "description": "RL-inspired: reinforce valuable memories, let others fade",
            "half_life_days": 30.0,  # Slow — only very old fades
            "min_weight": 0.1,
            "delete_threshold": 0.02,
            "archive_threshold": 0.1,
        },
    }

    def forget_policy(self, policy: str = "passive_decay",
                      dry_run: bool = False,
                      kinds: list[str] | None = None,
                      **overrides) -> dict:
        """Apply a named forgetting policy from the FSFM taxonomy.

        FSFM (arXiv:2604.20300) defines four forgetting categories:
          1. **passive_decay** — Ebbinghaus-curve exponential decay
          2. **active_deletion** — conflict/outdated content removal
          3. **safety_purge** — sensitive data forced purge
          4. **adaptive_reinforcement** — RL-inspired selective retention

        Each policy pre-configures half_life_days, thresholds, and optional
        kind filters. Overrides allow fine-tuning.

        Args:
            policy: One of 'passive_decay', 'active_deletion',
                    'safety_purge', 'adaptive_reinforcement'.
            dry_run: Preview without modifying.
            kinds: Additional kind filter (merged with policy kinds).
            **overrides: Override any policy parameter (half_life_days,
                        delete_threshold, etc.).

        Returns:
            {policy, scanned, kept, archived, deleted, recommendations, ...}
        """
        if policy not in self._FSFM_POLICIES:
            valid = ", ".join(self._FSFM_POLICIES.keys())
            raise ValueError(
                f"Unknown policy '{policy}'. Valid: {valid}")

        config = dict(self._FSFM_POLICIES[policy])  # copy
        config.update(overrides)

        # Merge kind filters
        policy_kinds = config.pop("kinds", None)
        require_conflict = config.pop("require_conflict", False)
        config_desc = config.pop("description", "")

        effective_kinds = set()
        if policy_kinds:
            effective_kinds.update(policy_kinds)
        if kinds:
            effective_kinds.update(kinds)
        effective_kinds = list(effective_kinds) if effective_kinds else None

        # For active_deletion, filter to conflicted nodes only
        if require_conflict:
            return self._forget_active_deletion(
                dry_run=dry_run,
                half_life_days=config.get("half_life_days", 14.0),
                delete_threshold=config.get("delete_threshold", 0.15),
                archive_threshold=config.get("archive_threshold", 0.3),
            )

        result = self.apply_decay(
            half_life_days=config.get("half_life_days", 7.0),
            kinds=effective_kinds,
            dry_run=dry_run,
            archive_threshold=config.get("archive_threshold", 0.25),
            delete_threshold=config.get("delete_threshold", 0.1),
        )
        result["policy"] = policy
        result["policy_description"] = config_desc
        return result

    def _forget_active_deletion(self, dry_run: bool = False,
                                half_life_days: float = 14.0,
                                delete_threshold: float = 0.15,
                                archive_threshold: float = 0.3) -> dict:
        """Active deletion: process only nodes with contradiction edges."""
        # Find nodes involved in conflicts
        conflict_rows = self.conn.execute(
            "SELECT DISTINCT source AS id FROM edges "
            "WHERE relation='contradicts' "
            "UNION "
            "SELECT DISTINCT target AS id FROM edges "
            "WHERE relation='contradicts'"
        ).fetchall()

        scanned = len(conflict_rows)
        kept = 0
        archived = 0
        deleted = 0
        recommendations = {"KEEP": 0, "ARCHIVE": 0, "CONSOLIDATE": 0,
                           "DELETE": 0, "RESOLVE_OR_DELETE": 0}
        weight_before = 0.0
        weight_after = 0.0
        details_deleted = []

        for r in conflict_rows:
            node_id = r["id"]
            result = self.compute_activation(node_id,
                                             half_life_days=half_life_days)
            if not result:
                continue

            rec = result["recommendation"]
            recommendations[rec] = recommendations.get(rec, 0) + 1
            act = result["activation"]

            row = self.conn.execute(
                "SELECT weight FROM nodes WHERE id=?", (node_id,)
            ).fetchone()
            if not row:
                continue
            old_w = row["weight"]
            weight_before += old_w

            if act < delete_threshold:
                if not dry_run:
                    self.delete_node(node_id)
                deleted += 1
                details_deleted.append({
                    "id": node_id, "activation": act,
                    "old_weight": old_w,
                })
                weight_after += 0.0
            elif act < archive_threshold:
                new_w = old_w * 0.5
                if not dry_run:
                    self.conn.execute(
                        "UPDATE nodes SET weight=? WHERE id=?",
                        (new_w, node_id))
                archived += 1
                weight_after += new_w
            else:
                new_w = old_w * 0.9
                if not dry_run:
                    self.conn.execute(
                        "UPDATE nodes SET weight=? WHERE id=?",
                        (new_w, node_id))
                kept += 1
                weight_after += new_w

        if not dry_run:
            self.conn.commit()

        return {
            "policy": "active_deletion",
            "policy_description": "Remove outdated/contradicted entries",
            "scanned": scanned,
            "kept": kept,
            "archived": archived,
            "deleted": deleted,
            "recommendations": recommendations,
            "weight_before": round(weight_before, 4),
            "weight_after": round(weight_after, 4),
            "weight_lost": round(weight_before - weight_after, 4),
            "dry_run": dry_run,
            "details_deleted": details_deleted[:10],
        }

    # ── Cue-Reactivated Soft Forgetting (Oblivion, Research #030) ──
    # Oblivion (arXiv:2603.19550): memories don't get deleted, they
    # become less accessible. Contextual cues can reactivate them.
    # amg stores a `forgotten` flag + `forgotten_at` timestamp.

    def soft_forget(self, node_id: str, reason: str = "") -> bool:
        """Mark a node as softly forgotten (below retrieval threshold).

        Unlike delete_node(), the node remains in the graph for potential
        cue-based reactivation. Forgotten nodes are excluded from recall()
        and retrieval but retain all edges and metadata.

        Args:
            node_id: Node to soft-forget.
            reason: Optional reason string.

        Returns:
            True if node was found and marked, False otherwise.
        """
        row = self.conn.execute(
            "SELECT id FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return False

        now = time.time()
        self.conn.execute(
            "UPDATE nodes SET data = json_set("
            "  COALESCE(data, '{}'),"
            "  '$.forgotten', 1,"
            "  '$.forgotten_at', ?,"
            "  '$.forget_reason', ?"
            ") WHERE id=?",
            (now, reason, node_id)
        )
        self.conn.commit()
        return True

    def cue_reactivation(self, cue: str,
                         limit: int = 5,
                         reactivation_boost: float = 0.5,
                         fuzzy: bool = True) -> dict:
        """Reactivate softly forgotten nodes matching a cue.

        Searches forgotten nodes for label/data similarity to the cue.
        Matching nodes have their forgotten flag cleared and weight
        boosted, simulating human memory reactivation (Oblivion pattern).

        Args:
            cue: Search string to match against forgotten nodes.
            limit: Max nodes to reactivate.
            reactivation_boost: Weight multiplier for reactivated nodes
                (default 0.5 = restore to half weight).
            fuzzy: If True, use substring/keyword matching; if False,
                use exact label match.

        Returns:
            {reactivated: [...], scanned: int, boost_applied: float}
        """
        # Find forgotten nodes
        rows = self.conn.execute(
            "SELECT id, label, kind, weight, data FROM nodes "
            "WHERE json_extract(data, '$.forgotten') = 1"
        ).fetchall()

        reactivated = []
        cue_lower = cue.lower()

        for r in rows:
            label_lower = r["label"].lower()
            matched = False

            if fuzzy:
                # Keyword matching: any cue word appears in label
                cue_words = [w for w in cue_lower.split() if len(w) > 2]
                if any(w in label_lower for w in cue_words):
                    matched = True
                # Also check substring
                if cue_lower in label_lower:
                    matched = True
            else:
                matched = (label_lower == cue_lower)

            if matched and len(reactivated) < limit:
                # Reactivate: clear forgotten flag, boost weight
                old_weight = r["weight"]
                new_weight = max(old_weight, reactivation_boost)

                self.conn.execute(
                    "UPDATE nodes SET "
                    "  data = json_remove("
                    "    json_remove(data, '$.forgotten'),"
                    "    '$.forgotten_at'),"
                    "  weight = ?, "
                    "  accessed = ? "
                    "WHERE id=?",
                    (new_weight, time.time(), r["id"])
                )

                # Also remove forget_reason
                self.conn.execute(
                    "UPDATE nodes SET "
                    "  data = json_remove(data, '$.forget_reason') "
                    "WHERE id=?",
                    (r["id"],)
                )

                reactivated.append({
                    "id": r["id"],
                    "label": r["label"],
                    "kind": r["kind"],
                    "old_weight": round(old_weight, 4),
                    "new_weight": round(new_weight, 4),
                })

        self.conn.commit()

        return {
            "cue": cue,
            "scanned": len(rows),
            "reactivated": reactivated,
            "count": len(reactivated),
            "boost_applied": reactivation_boost,
        }

    def get_forgotten_nodes(self, limit: int = 50) -> list[dict]:
        """List softly forgotten nodes.

        Args:
            limit: Max results.

        Returns:
            List of {id, label, kind, weight, forgotten_at, reason}.
        """
        rows = self.conn.execute(
            "SELECT id, label, kind, weight, data FROM nodes "
            "WHERE json_extract(data, '$.forgotten') = 1 "
            "LIMIT ?",
            (limit,)
        ).fetchall()

        import json
        result = []
        for r in rows:
            data = json.loads(r["data"]) if r["data"] else {}
            result.append({
                "id": r["id"],
                "label": r["label"],
                "kind": r["kind"],
                "weight": round(r["weight"], 4),
                "forgotten_at": data.get("forgotten_at"),
                "reason": data.get("forget_reason", ""),
            })
        return result

    # ── Security Purge (FSFM Category 3, Research #030) ──────────
    # Safety-triggered immediate deletion of sensitive/malicious/
    # privacy-compromising content. Unlike soft_forget, purge is IRREVERSIBLE.

    _SENSITIVE_KINDS = {
        "sensitive", "credential", "api_key", "token",
        "personal_data", "malicious", "malware",
    }

    _SENSITIVE_LABEL_PATTERNS = [
        "api key", "apikey", "secret", "password", "token",
        "private key", "ssh key", "access key", "bearer",
        "credentials", "session id",
    ]

    def security_purge(self, node_ids: list[str] | None = None,
                       kinds: list[str] | None = None,
                       scan_labels: bool = True,
                       dry_run: bool = False) -> dict:
        """Irreversibly purge sensitive/malicious nodes.

        FSFM Category 3: safety-triggered forgetting. Unlike soft_forget
        (reversible) or apply_decay (gradual), this is immediate and
        permanent.

        Deletion targets (OR'd together):
          1. Explicit node_ids
          2. Nodes with matching kinds (default: _SENSITIVE_KINDS)
          3. Nodes whose labels match _SENSITIVE_LABEL_PATTERNS

        Args:
            node_ids: Explicit list of node IDs to purge.
            kinds: Additional kinds to purge (merged with _SENSITIVE_KINDS).
            scan_labels: If True, scan labels for sensitive patterns.
            dry_run: Preview without deleting.

        Returns:
            {purged: int, scanned: int, details: [...], dry_run: bool}
        """
        import re

        target_ids = set()

        # 1. Explicit node_ids
        if node_ids:
            target_ids.update(node_ids)

        # 2. Sensitive kinds
        effective_kinds = set(self._SENSITIVE_KINDS)
        if kinds:
            effective_kinds.update(kinds)

        kind_rows = self.conn.execute(
            "SELECT id, label, kind FROM nodes WHERE kind IN (%s)" %
            ",".join("?" * len(effective_kinds)),
            tuple(effective_kinds)
        ).fetchall()
        for r in kind_rows:
            target_ids.add(r["id"])

        # 3. Label pattern scan
        if scan_labels:
            all_rows = self.conn.execute(
                "SELECT id, label, kind FROM nodes"
            ).fetchall()
            patterns_norm = [
                p.lower().replace("_", " ").replace("-", " ")
                for p in self._SENSITIVE_LABEL_PATTERNS
            ]
            for r in all_rows:
                # Normalize label: replace separators with spaces
                label_norm = r["label"].lower().replace("_", " ").replace("-", " ")
                if any(p in label_norm for p in patterns_norm):
                    target_ids.add(r["id"])

        # Execute purge
        details = []
        scanned = len(target_ids)

        for nid in target_ids:
            row = self.conn.execute(
                "SELECT id, label, kind, weight FROM nodes WHERE id=?",
                (nid,)
            ).fetchone()
            if not row:
                continue

            details.append({
                "id": row["id"],
                "label": row["label"],
                "kind": row["kind"],
                "weight": round(row["weight"], 4),
            })

            if not dry_run:
                self.delete_node(nid)

        if not dry_run:
            self.conn.commit()

        return {
            "purged": len(details),
            "scanned": scanned,
            "details": details[:50],  # cap for readability
            "dry_run": dry_run,
        }

    # ── Neighborhood Agreement (multi-hop divergence) ─────────────

    def neighborhood_agreement(self, node_id: str,
                               hops: int = 2) -> dict | None:
        """Extended semantic agreement beyond immediate neighbors.

        While semantic_divergence only looks at 1-hop neighbors, this method
        explores the N-hop neighborhood to detect broader semantic drift:
        - Agreement decreases with hop distance (exponential decay)
        - High multi-hop agreement + low 1-hop agreement = bridge node
        - Low multi-hop agreement + high 1-hop agreement = boundary node

        Args:
            node_id: target node
            hops: max BFS depth (1 = same as semantic_divergence)

        Returns:
            {node_id, label, kind, layers: [{hop, nodes, avg_similarity, agreement}],
             overall_agreement, node_role}
        """
        node = self.get_node(node_id)
        if not node:
            return None

        visited = {node_id}
        frontier = [node_id]
        layers = []

        for hop in range(1, hops + 1):
            next_frontier = []
            sims = []

            for nid in frontier:
                nbrs = self.neighbors(nid)
                for nbr in nbrs:
                    if nbr.id in visited:
                        continue
                    visited.add(nbr.id)
                    next_frontier.append(nbr.id)
                    sim = self._content_similarity(node.label, nbr.label)
                    sims.append(sim)

            if not sims:
                layers.append({"hop": hop, "nodes": 0, "avg_similarity": 0.0,
                               "agreement": 0.0})
                break

            avg_sim = sum(sims) / len(sims)
            # Agreement = similarity weighted by hop distance (closer = more important)
            hop_weight = 1.0 / hop
            agreement = round(avg_sim * hop_weight, 4)

            layers.append({
                "hop": hop,
                "nodes": len(sims),
                "avg_similarity": round(avg_sim, 4),
                "agreement": agreement,
            })
            frontier = next_frontier

        # Check if node is isolated (first layer found nothing)
        if layers and layers[0]["nodes"] == 0:
            return {"node_id": node_id, "label": node.label, "kind": node.kind,
                    "layers": layers, "overall_agreement": 0.0, "node_role": "isolated"}

        if not layers:
            return {"node_id": node_id, "label": node.label, "kind": node.kind,
                    "layers": [], "overall_agreement": 0.0, "node_role": "isolated"}

        # Overall = weighted average of layer agreements
        total_weight = sum(l["nodes"] for l in layers)
        if total_weight > 0:
            overall = sum(l["agreement"] * l["nodes"] for l in layers) / total_weight
        else:
            overall = 0.0
        overall = round(overall, 4)

        # Classify node role
        if len(layers) >= 2:
            l1 = layers[0]["agreement"]
            l2 = layers[1]["agreement"] if len(layers) > 1 else 0.0
            if l1 < 0.3 and overall > 0.5:
                role = "bridge"  # Low local but high global → connects clusters
            elif l1 > 0.5 and overall < 0.3:
                role = "boundary"  # High local but low global → edge of cluster
            elif overall > 0.6:
                role = "core"  # High everywhere → central member
            else:
                role = "peripheral"
        else:
            role = "core" if overall > 0.5 else "peripheral"

        return {
            "node_id": node_id,
            "label": node.label,
            "kind": node.kind,
            "layers": layers,
            "overall_agreement": overall,
            "node_role": role,
        }

    # ── Memory Proximity (semantic neighborhood search) ────────────

    def memory_proximity(self, node_id: str, radius: float = 0.5,
                         limit: int = 20) -> list[dict] | None:
        """Find nodes within a semantic similarity radius of a target.

        Unlike graph-based neighbors(), this uses content similarity (trigram)
        to find semantically close nodes regardless of edge connections.
        Useful for discovering related memories that aren't explicitly linked.

        Args:
            node_id: anchor node
            radius: minimum trigram similarity (0-1) to include
            limit: max results

        Returns:
            List of {node_id, label, kind, similarity, weight, connected}
            sorted by similarity descending. Connected = has edge to anchor.
        """
        node = self.get_node(node_id)
        if not node:
            return None

        anchor_label = node.label
        connected_ids = set()
        for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? UNION "
            "SELECT source FROM edges WHERE target=?",
            (node_id, node_id)
        ).fetchall():
            connected_ids.add(r[0])

        results = []
        for r in self.conn.execute(
            "SELECT id, label, kind, weight FROM nodes WHERE id != ?",
            (node_id,)
        ).fetchall():
            sim = self._content_similarity(anchor_label, r["label"])
            if sim >= radius:
                results.append({
                    "node_id": r["id"],
                    "label": r["label"],
                    "kind": r["kind"],
                    "similarity": round(sim, 4),
                    "weight": r["weight"],
                    "connected": r["id"] in connected_ids,
                })

        results.sort(key=lambda x: x["similarity"], reverse=True)
        return results[:limit]

    # ── Tag Induced Subgraph ──────────────────────────────────────

    def tag_induced_subgraph(self, tags: list[str],
                             match: str = "any") -> dict | None:
        """Extract a subgraph of nodes matching the given tags.

        Unlike search_by_tag (returns node list only), this returns
        a full subgraph with edges preserved, enabling localized analysis.

        Args:
            tags: tag list to filter by
            match: 'any' (OR) or 'all' (AND)

        Returns:
            {nodes: [{id, label, kind, tags, weight}],
             edges: [{source, target, relation}],
             node_count, edge_count, tags_matched}
        """
        tag_set = set(tags)
        matching_ids = set()

        for r in self.conn.execute(
            "SELECT id, tags FROM nodes"
        ).fetchall():
            node_tags = set(json.loads(r["tags"]))
            if match == "all":
                if tag_set.issubset(node_tags):
                    matching_ids.add(r["id"])
            else:  # any
                if tag_set & node_tags:
                    matching_ids.add(r["id"])

        if not matching_ids:
            return {"nodes": [], "edges": [],
                    "node_count": 0, "edge_count": 0,
                    "tags_matched": tags}

        # Fetch nodes
        nodes_out = []
        id_list = list(matching_ids)
        placeholders = ",".join("?" * len(id_list))
        for r in self.conn.execute(
            f"SELECT * FROM nodes WHERE id IN ({placeholders})", id_list
        ).fetchall():
            nodes_out.append({
                "id": r["id"], "label": r["label"], "kind": r["kind"],
                "tags": json.loads(r["tags"]), "weight": r["weight"],
            })

        # Fetch internal edges (both endpoints in matching set)
        edges_out = []
        for r in self.conn.execute(
            f"SELECT source, target, relation FROM edges "
            f"WHERE source IN ({placeholders}) AND target IN ({placeholders})",
            id_list + id_list
        ).fetchall():
            edges_out.append({
                "source": r["source"], "target": r["target"],
                "relation": r["relation"],
            })

        return {
            "nodes": nodes_out,
            "edges": edges_out,
            "node_count": len(nodes_out),
            "edge_count": len(edges_out),
            "tags_matched": tags,
        }

    # ── Memory Annotations (structured searchable metadata) ────────

    def memory_annotate(self, node_id: str, key: str, value: str) -> bool:
        """Add a structured key-value annotation to a node.

        Annotations are searchable metadata stored alongside the node's data.
        Unlike tags (flat labels), annotations have explicit key-value structure.
        Useful for: confidence scores, source attribution, quality ratings, etc.

        Args:
            node_id: target node
            key: annotation key (e.g., 'confidence', 'source')
            value: annotation value (e.g., '0.95', 'paper')

        Returns:
            True if node existed and annotation was added.
        """
        node = self.get_node(node_id)
        if not node:
            return False
        data = dict(node.data) if node.data else {}
        if "_annotations" not in data:
            data["_annotations"] = {}
        data["_annotations"][key] = value
        self.conn.execute(
            "UPDATE nodes SET data=? WHERE id=?",
            (json.dumps(data), node_id))
        self.conn.commit()
        return True

    def annotation_get(self, node_id: str, key: str) -> str | None:
        """Retrieve a specific annotation value."""
        node = self.get_node(node_id)
        if not node or not node.data:
            return None
        annotations = node.data.get("_annotations", {})
        return annotations.get(key)

    def annotation_remove(self, node_id: str, key: str) -> bool:
        """Remove an annotation from a node. Returns True if removed."""
        node = self.get_node(node_id)
        if not node or not node.data:
            return False
        data = dict(node.data)
        annotations = data.get("_annotations", {})
        if key not in annotations:
            return False
        del annotations[key]
        if annotations:
            data["_annotations"] = annotations
        else:
            del data["_annotations"]
        self.conn.execute(
            "UPDATE nodes SET data=? WHERE id=?",
            (json.dumps(data), node_id))
        self.conn.commit()
        return True

    def annotation_search(self, key: str, value: str | None = None,
                          limit: int = 50) -> list[dict]:
        """Find nodes by annotation key (and optional value).

        Args:
            key: annotation key to search for
            value: if provided, only match nodes where annotation[key] == value
            limit: max results

        Returns:
            List of {node_id, label, kind, annotation_value}
        """
        results = []
        for r in self.conn.execute(
            "SELECT id, label, kind, data FROM nodes LIMIT ?", (limit * 5,)
        ).fetchall():
            data = json.loads(r["data"])
            annotations = data.get("_annotations", {})
            if key in annotations:
                ann_val = annotations[key]
                if value is not None and ann_val != value:
                    continue
                results.append({
                    "node_id": r["id"],
                    "label": r["label"],
                    "kind": r["kind"],
                    "annotation_value": ann_val,
                })
            if len(results) >= limit:
                break
        return results

    # ── Workflow Memory (AWM ICML 2025 / ReasoningBank ICLR 2026) ──────

    def add_workflow(self, goal: str, steps: list[dict],
                     source_trajectories: list[str] | None = None,
                     tags: list[str] | None = None) -> str:
        """Create a workflow node with ordered step nodes and edges.

        Implements Agent Workflow Memory (AWM) pattern: store reusable
        multi-step procedures extracted from execution trajectories.

        Args:
            goal: natural-language description of the workflow goal
            steps: ordered list of {label, action, detail} dicts
            source_trajectories: IDs of trajectory nodes this was extracted from
            tags: optional tags for retrieval

        Returns:
            workflow node ID
        """
        wf_id = self.add(
            goal, kind="workflow",
            data={
                "_workflow": True,
                "step_count": len(steps),
                "success_count": 0,
                "failure_count": 0,
                "source_trajectories": source_trajectories or [],
            },
            tags=tags or [],
        ).id
        for i, step in enumerate(steps):
            step_node = self.add(
                step.get("label", f"Step {i+1}"),
                kind="workflow_step",
                data={
                    "_workflow_step": True,
                    "workflow_id": wf_id,
                    "order": i,
                    "action": step.get("action", ""),
                    "detail": step.get("detail", ""),
                },
            )
            self.link(wf_id, step_node.id, "has_step", weight=1.0 - i * 0.01)
            if i > 0:
                prev = self.conn.execute(
                    "SELECT target FROM edges WHERE source=? AND relation='has_step' "
                    "ORDER BY weight DESC LIMIT 1 OFFSET ?",
                    (wf_id, i - 1),
                ).fetchone()
                if prev:
                    self.link(prev["target"], step_node.id, "next_step")
        for traj_id in (source_trajectories or []):
            if self.has_node(traj_id):
                self.link(wf_id, traj_id, "extracted_from")
        return wf_id

    def retrieve_workflows(self, goal: str | None = None,
                          tags: list[str] | None = None,
                          limit: int = 10) -> list[dict]:
        """Retrieve workflows matching goal text and/or tags.

        Uses tag intersection (Jaccard) and goal trigram overlap for ranking.
        Falls back to listing all workflows if no filters.

        Returns:
            Sorted list of {id, goal, step_count, success_count,
                             failure_count, score, steps}
        """
        candidates = []
        for r in self.conn.execute(
            "SELECT id, label, data, tags FROM nodes WHERE kind='workflow'"
        ).fetchall():
            data = json.loads(r["data"])
            if not data.get("_workflow"):
                continue
            score = 0.0
            has_tag_match = True
            if tags:
                wf_tags = set(json.loads(r["tags"])) if r["tags"] else set()
                overlap = len(wf_tags & set(tags))
                total = len(wf_tags | set(tags)) or 1
                score += overlap / total  # Jaccard
                has_tag_match = overlap > 0
            if not has_tag_match:
                continue
            if goal:
                wf_label_lower = r["label"].lower()
                goal_lower = goal.lower()
                goal_trigrams = {goal_lower[i:i+3] for i in range(len(goal_lower) - 2)}
                label_trigrams = {wf_label_lower[i:i+3] for i in range(len(wf_label_lower) - 2)}
                if goal_trigrams and label_trigrams:
                    score += len(goal_trigrams & label_trigrams) / len(goal_trigrams | label_trigrams)
            success_bonus = data.get("success_count", 0) * 0.1
            success_bonus -= data.get("failure_count", 0) * 0.05
            score += success_bonus
            candidates.append((score, r, data))
        candidates.sort(key=lambda x: x[0], reverse=True)
        results = []
        for score, r, data in candidates[:limit]:
            steps_out = []
            for s in self.conn.execute(
                "SELECT target FROM edges WHERE source=? AND relation='has_step' "
                "ORDER BY weight DESC", (r["id"],)
            ).fetchall():
                step_node = self.get_node(s["target"])
                if step_node and step_node.data.get("_workflow_step"):
                    steps_out.append({
                        "label": step_node.label,
                        "action": step_node.data.get("action", ""),
                        "detail": step_node.data.get("detail", ""),
                    })
            results.append({
                "id": r["id"],
                "goal": r["label"],
                "step_count": data.get("step_count", len(steps_out)),
                "success_count": data.get("success_count", 0),
                "failure_count": data.get("failure_count", 0),
                "score": round(score, 4),
                "steps": steps_out,
            })
        return results

    def record_workflow_outcome(self, workflow_id: str, success: bool,
                                detail: str = "") -> bool:
        """Record execution outcome for a workflow.

        Increments success/failure counter. Optional detail stored in data.
        Returns True if workflow existed.
        """
        node = self.get_node(workflow_id)
        if not node or node.kind != "workflow":
            return False
        data = dict(node.data) if node.data else {}
        if success:
            data["success_count"] = data.get("success_count", 0) + 1
        else:
            data["failure_count"] = data.get("failure_count", 0) + 1
        outcomes = data.get("_outcomes", [])
        outcomes.append({
            "success": success,
            "detail": detail,
            "ts": time.time(),
        })
        data["_outcomes"] = outcomes[-50:]  # keep last 50
        self.conn.execute(
            "UPDATE nodes SET data=? WHERE id=?",
            (json.dumps(data), workflow_id))
        self.conn.commit()
        return True

    def workflow_stats(self) -> dict:
        """Global workflow memory statistics.

        Returns counts, success rates, and coverage metrics.
        """
        workflows = self.conn.execute(
            "SELECT id, data FROM nodes WHERE kind='workflow'"
        ).fetchall()
        total = len(workflows)
        total_success = 0
        total_failure = 0
        total_steps = 0
        used = 0
        for r in workflows:
            data = json.loads(r["data"])
            s = data.get("success_count", 0)
            f = data.get("failure_count", 0)
            total_success += s
            total_failure += f
            total_steps += data.get("step_count", 0)
            if s + f > 0:
                used += 1
        step_nodes = self.conn.execute(
            "SELECT COUNT(*) as c FROM nodes WHERE kind='workflow_step'"
        ).fetchone()["c"]
        avg_steps = total_steps / total if total else 0
        total_attempts = total_success + total_failure
        success_rate = total_success / total_attempts if total_attempts else 0.0
        coverage = used / total if total else 0.0
        return {
            "total_workflows": total,
            "total_steps": step_nodes,
            "avg_steps_per_workflow": round(avg_steps, 1),
            "total_success": total_success,
            "total_failure": total_failure,
            "success_rate": round(success_rate, 4),
            "used_workflows": used,
            "coverage": round(coverage, 4),
        }

    def workflow_compose(self, workflow_a_id: str, workflow_b_id: str,
                         goal: str | None = None,
                         bridge_label: str | None = None) -> str | None:
        """Compose two workflows into a new one (AWM snowball effect).

        Creates a new workflow whose steps are A's steps followed by B's steps,
        with an optional bridge step connecting them. The new workflow references
        both sources via extracted_from edges.

        Args:
            workflow_a_id: first workflow (prefix steps)
            workflow_b_id: second workflow (suffix steps)
            goal: combined goal (defaults to "A + B")
            bridge_label: optional bridge step between A and B

        Returns:
            New workflow ID, or None if either source doesn't exist.
        """
        node_a = self.get_node(workflow_a_id)
        node_b = self.get_node(workflow_b_id)
        if not node_a or not node_b or node_a.kind != "workflow" or node_b.kind != "workflow":
            return None
        a_steps = self.conn.execute(
            "SELECT target FROM edges WHERE source=? AND relation='has_step' "
            "ORDER BY weight DESC", (workflow_a_id,)
        ).fetchall()
        b_steps = self.conn.execute(
            "SELECT target FROM edges WHERE source=? AND relation='has_step' "
            "ORDER BY weight DESC", (workflow_b_id,)
        ).fetchall()
        combined_steps = []
        for s in a_steps:
            sn = self.get_node(s["target"])
            if sn and sn.data.get("_workflow_step"):
                combined_steps.append({
                    "label": sn.label,
                    "action": sn.data.get("action", ""),
                    "detail": sn.data.get("detail", ""),
                })
        if bridge_label:
            combined_steps.append({"label": bridge_label, "action": "bridge", "detail": ""})
        for s in b_steps:
            sn = self.get_node(s["target"])
            if sn and sn.data.get("_workflow_step"):
                combined_steps.append({
                    "label": sn.label,
                    "action": sn.data.get("action", ""),
                    "detail": sn.data.get("detail", ""),
                })
        new_goal = goal or f"{node_a.label} + {node_b.label}"
        new_id = self.add_workflow(
            new_goal, combined_steps,
            source_trajectories=[workflow_a_id, workflow_b_id],
        )
        return new_id

    def workflow_dedup(self, similarity_threshold: float = 0.8,
                       dry_run: bool = False) -> dict:
        """Find and merge near-duplicate workflows.

        Uses goal trigram similarity to detect duplicates.
        Merges by keeping the one with more successes and merging steps.

        Args:
            similarity_threshold: trigram Jaccard above this = duplicate
            dry_run: if True, report only without merging

        Returns:
            {checked, duplicates_found, merged, details}
        """
        workflows = []
        for r in self.conn.execute(
            "SELECT id, label, data FROM nodes WHERE kind='workflow'"
        ).fetchall():
            data = json.loads(r["data"])
            if not data.get("_workflow"):
                continue
            workflows.append((r["id"], r["label"], data))
        duplicates = []
        merged_ids = set()
        merge_details = []
        for i, (id_a, label_a, data_a) in enumerate(workflows):
            if id_a in merged_ids:
                continue
            for j in range(i + 1, len(workflows)):
                id_b, label_b, data_b = workflows[j]
                if id_b in merged_ids:
                    continue
                la, lb = label_a.lower(), label_b.lower()
                ta = {la[k:k+3] for k in range(len(la) - 2)}
                tb = {lb[k:k+3] for k in range(len(lb) - 2)}
                if not ta or not tb:
                    continue
                sim = len(ta & tb) / len(ta | tb)
                if sim >= similarity_threshold:
                    duplicates.append((id_a, id_b, sim))
                    if not dry_run:
                        succ_a = data_a.get("success_count", 0)
                        succ_b = data_b.get("success_count", 0)
                        keep_id = id_a if succ_a >= succ_b else id_b
                        remove_id = id_b if keep_id == id_a else id_a
                        merged_ids.add(remove_id)
                        remove_node = self.get_node(remove_id)
                        keep_node = self.get_node(keep_id)
                        if remove_node and keep_node:
                            keep_data = dict(keep_node.data)
                            keep_data["success_count"] = (
                                keep_data.get("success_count", 0) +
                                remove_node.data.get("success_count", 0))
                            keep_data["failure_count"] = (
                                keep_data.get("failure_count", 0) +
                                remove_node.data.get("failure_count", 0))
                            self.conn.execute(
                                "UPDATE nodes SET data=? WHERE id=?",
                                (json.dumps(keep_data), keep_id))
                            self.conn.execute(
                                "DELETE FROM edges WHERE source=? OR target=?",
                                (remove_id, remove_id))
                            self.conn.execute(
                                "DELETE FROM nodes WHERE id=?", (remove_id,))
                            self.conn.commit()
                        merge_details.append({
                            "kept": keep_id,
                            "removed": remove_id,
                            "similarity": round(sim, 4),
                        })
        return {
            "checked": len(workflows),
            "duplicates_found": len(duplicates),
            "merged": len(merge_details),
            "details": merge_details,
        }

    def add_workflow_tip(self, workflow_id: str, tip_type: str,
                         content: str, detail: str = "") -> str | None:
        """Attach a success/recovery/optimization tip to a workflow.

        Inspired by ReasoningBank (ICLR 2026): distill reasoning strategies
        from both successful and failed executions.

        Args:
            workflow_id: target workflow
            tip_type: 'success' | 'failure' | 'recovery' | 'optimization'
            content: the tip text (natural language guidance)
            detail: optional supporting detail

        Returns:
            Tip node ID, or None if workflow doesn't exist.
        """
        if not self.get_node(workflow_id):
            return None
        tip_id = self.add(
            content[:80],
            kind="workflow_tip",
            data={
                "_workflow_tip": True,
                "workflow_id": workflow_id,
                "tip_type": tip_type,
                "content": content,
                "detail": detail,
                "created": time.time(),
            },
        ).id
        self.link(workflow_id, tip_id, "has_tip")
        return tip_id

    def retrieve_workflow_tips(self, workflow_id: str,
                               tip_type: str | None = None,
                               limit: int = 20) -> list[dict]:
        """Retrieve tips for a workflow, optionally filtered by type.

        Args:
            workflow_id: target workflow
            tip_type: filter by 'success'|'failure'|'recovery'|'optimization'
            limit: max results

        Returns:
            List of {tip_id, tip_type, content, detail}
        """
        results = []
        for r in self.conn.execute(
            "SELECT target FROM edges WHERE source=? AND relation='has_tip'",
            (workflow_id,)
        ).fetchall():
            node = self.get_node(r["target"])
            if not node or not node.data.get("_workflow_tip"):
                continue
            if tip_type and node.data.get("tip_type") != tip_type:
                continue
            results.append({
                "tip_id": node.id,
                "tip_type": node.data.get("tip_type", ""),
                "content": node.data.get("content", ""),
                "detail": node.data.get("detail", ""),
            })
            if len(results) >= limit:
                break
        return results

    def workflow_prompt_section(self, workflow_id: str,
                                max_tips: int = 5) -> str:
        """Generate an LLM-injectable prompt section for a workflow.

        Includes goal, steps, and relevant tips (success strategies +
        failure warnings). Designed for AWM-style context injection.

        Returns empty string if workflow doesn't exist.
        """
        node = self.get_node(workflow_id)
        if not node or node.kind != "workflow":
            return ""
        data = node.data
        lines = [f"## Workflow: {node.label}"]
        s = data.get("success_count", 0)
        f = data.get("failure_count", 0)
        if s or f:
            lines.append(f"(success: {s}, failed: {f})")
        steps = self.retrieve_workflows()
        wf_data = next((w for w in steps if w["id"] == workflow_id), None)
        if wf_data:
            lines.append("")
            lines.append("Steps:")
            for i, step in enumerate(wf_data["steps"], 1):
                lines.append(f"  {i}. {step['label']}")
        tips = self.retrieve_workflow_tips(workflow_id, limit=max_tips)
        if tips:
            success_tips = [t for t in tips if t["tip_type"] == "success"]
            failure_tips = [t for t in tips if t["tip_type"] in ("failure", "recovery")]
            if success_tips:
                lines.append("")
                lines.append("Success strategies:")
                for t in success_tips[:max_tips // 2]:
                    lines.append(f"  ✅ {t['content']}")
            if failure_tips:
                lines.append("")
                lines.append("Known pitfalls:")
                for t in failure_tips[:max_tips // 2]:
                    lines.append(f"  ⚠️  {t['content']}")
        return "\n".join(lines)

    def workflow_prune_tips(self, workflow_id: str,
                            tip_type: str | None = None) -> int:
        """Remove tips from a workflow. Returns count removed.

        Args:
            workflow_id: target workflow
            tip_type: if provided, only remove tips of this type
        """
        removed = 0
        tips = self.retrieve_workflow_tips(workflow_id, tip_type=tip_type,
                                            limit=10000)
        for tip in tips:
            self.conn.execute(
                "DELETE FROM edges WHERE source=? AND target=? AND relation='has_tip'",
                (workflow_id, tip["tip_id"]))
            self.conn.execute(
                "DELETE FROM nodes WHERE id=?", (tip["tip_id"],))
            removed += 1
        if removed:
            self.conn.commit()
        return removed

    def workflow_export(self, workflow_id: str) -> dict | None:
        """Export a workflow and all its components as a portable dict.

        Includes goal, steps, tips, outcomes, and stats.
        Useful for cross-agent workflow sharing (memorywire-compatible).
        """
        node = self.get_node(workflow_id)
        if not node or node.kind != "workflow":
            return None
        data = dict(node.data)
        wf_data = next((w for w in self.retrieve_workflows(limit=10000)
                        if w["id"] == workflow_id), None)
        tips = self.retrieve_workflow_tips(workflow_id, limit=10000)
        return {
            "goal": node.label,
            "steps": wf_data["steps"] if wf_data else [],
            "success_count": data.get("success_count", 0),
            "failure_count": data.get("failure_count", 0),
            "tips": tips,
            "source_trajectories": data.get("source_trajectories", []),
            "exported_at": time.time(),
        }

    def workflow_import(self, wf_data: dict,
                        tags: list[str] | None = None) -> str:
        """Import a workflow from an export dict (round-trip with workflow_export).

        Creates a new workflow with steps, tips, and outcome counters.
        Does NOT import source trajectory links (they may not exist).

        Returns:
            New workflow ID.
        """
        wf_id = self.add_workflow(
            wf_data.get("goal", "imported workflow"),
            wf_data.get("steps", []),
            tags=tags,
        )
        for _ in range(wf_data.get("success_count", 0)):
            self.record_workflow_outcome(wf_id, True)
        for _ in range(wf_data.get("failure_count", 0)):
            self.record_workflow_outcome(wf_id, False)
        for tip in wf_data.get("tips", []):
            self.add_workflow_tip(
                wf_id,
                tip.get("tip_type", "success"),
                tip.get("content", ""),
                tip.get("detail", ""),
            )
        return wf_id

    def workflow_success_patterns(self, min_workflows: int = 2,
                                  min_success_rate: float = 0.5) -> list[dict]:
        """Mine common action patterns across successful workflows.

        AWM insight: cross-trajectory pattern mining reveals reusable building
        blocks that no single workflow contains.  Finds actions that appear
        across multiple high-success-rate workflows, ranked by frequency.

        Args:
            min_workflows: minimum number of workflows an action must appear in
            min_success_rate: only consider workflows with success_rate >= this

        Returns:
            List of {action, frequency, workflow_ids, avg_order} sorted by
            frequency descending.
        """
        workflows = self.conn.execute(
            "SELECT id, data FROM nodes WHERE kind='workflow'"
        ).fetchall()
        qualified = []
        for r in workflows:
            data = json.loads(r["data"])
            s = data.get("success_count", 0)
            f = data.get("failure_count", 0)
            rate = s / (s + f) if (s + f) > 0 else 0.0
            if rate >= min_success_rate and (s + f) > 0:
                qualified.append(r["id"])
        if len(qualified) < min_workflows:
            return []
        action_map: dict[str, dict] = {}
        for wf_id in qualified:
            steps = self.conn.execute(
                "SELECT target FROM edges WHERE source=? AND relation='has_step'",
                (wf_id,),
            ).fetchall()
            for step_row in steps:
                step_node = self.get_node(step_row["target"])
                if not step_node:
                    continue
                step_data = step_node.data if isinstance(step_node.data, dict) else json.loads(step_node.data)
                action = step_data.get("action", step_node.label)
                if action not in action_map:
                    action_map[action] = {
                        "action": action,
                        "frequency": 0,
                        "workflow_ids": [],
                        "orders": [],
                    }
                entry = action_map[action]
                if wf_id not in entry["workflow_ids"]:
                    entry["frequency"] += 1
                    entry["workflow_ids"].append(wf_id)
                entry["orders"].append(step_data.get("order", 0))
        patterns = []
        for action, info in action_map.items():
            if info["frequency"] >= min_workflows:
                avg_order = sum(info["orders"]) / len(info["orders"])
                patterns.append({
                    "action": action,
                    "frequency": info["frequency"],
                    "workflow_ids": info["workflow_ids"],
                    "avg_order": round(avg_order, 1),
                })
        patterns.sort(key=lambda x: x["frequency"], reverse=True)
        return patterns

    def node_similarity(self, node_a_id: str, node_b_id: str) -> dict:
        """Compute multi-dimensional similarity between two nodes.

        Combines label trigram overlap, tag Jaccard, neighborhood overlap,
        and kind match into a composite score.

        Returns:
            {label_similarity, tag_similarity, neighbor_similarity,
             kind_match, composite} where composite is 0~1.
        """
        a = self.get_node(node_a_id)
        b = self.get_node(node_b_id)
        if not a or not b:
            return {"composite": 0.0}
        # Fetch tags from DB (Node dataclass has no tags field)
        row_a = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (node_a_id,)).fetchone()
        row_b = self.conn.execute("SELECT tags FROM nodes WHERE id=?", (node_b_id,)).fetchone()
        # Label trigram overlap
        def _trigrams(s: str) -> set:
            s = s.lower().strip()
            return {s[i:i+3] for i in range(len(s) - 2)} if len(s) >= 3 else {s}
        ta = _trigrams(a.label)
        tb = _trigrams(b.label)
        label_sim = len(ta & tb) / len(ta | tb) if (ta | tb) else 0.0
        # Tag Jaccard
        tags_a = set(json.loads(row_a["tags"])) if row_a and row_a["tags"] else set()
        tags_b = set(json.loads(row_b["tags"])) if row_b and row_b["tags"] else set()
        tag_sim = len(tags_a & tags_b) / len(tags_a | tags_b) if (tags_a | tags_b) else 0.0
        # Neighborhood overlap
        na = {n["target"] for n in self.conn.execute(
            "SELECT target FROM edges WHERE source=?", (node_a_id,)
        ).fetchall()}
        na.update(n["source"] for n in self.conn.execute(
            "SELECT source FROM edges WHERE target=?", (node_a_id,)
        ).fetchall())
        nb = {n["target"] for n in self.conn.execute(
            "SELECT target FROM edges WHERE source=?", (node_b_id,)
        ).fetchall()}
        nb.update(n["source"] for n in self.conn.execute(
            "SELECT source FROM edges WHERE target=?", (node_b_id,)
        ).fetchall())
        neighbor_sim = len(na & nb) / len(na | nb) if (na | nb) else 0.0
        kind_match = 1.0 if a.kind == b.kind else 0.0
        composite = (
            label_sim * 0.35 + tag_sim * 0.25 +
            neighbor_sim * 0.25 + kind_match * 0.15
        )
        return {
            "label_similarity": round(label_sim, 4),
            "tag_similarity": round(tag_sim, 4),
            "neighbor_similarity": round(neighbor_sim, 4),
            "kind_match": kind_match,
            "composite": round(composite, 4),
        }

    def memory_clone(self, node_id: str,
                     new_label: str | None = None,
                     deep_edges: bool = True) -> str | None:
        """Clone a node with its data, tags, and optionally edges.

        Creates a new node with the same kind/data/tags as the original.
        If deep_edges=True, copies all edges (both directions) with the
        new node as source/target.  Annotations are also copied.

        Returns:
            New node ID, or None if original doesn't exist.
        """
        original = self.get_node(node_id)
        if not original:
            return None
        cloned = self.add(
            new_label or f"{original.label} (clone)",
            kind=original.kind,
            data=original.data if isinstance(original.data, dict) else json.loads(original.data),
            tags=json.loads(self.conn.execute("SELECT tags FROM nodes WHERE id=?", (node_id,)).fetchone()["tags"]),
        )
        if deep_edges:
            outgoing = self.conn.execute(
                "SELECT target, relation, weight FROM edges WHERE source=?",
                (node_id,),
            ).fetchall()
            for e in outgoing:
                self.link(cloned.id, e["target"], e["relation"], e["weight"])
            incoming = self.conn.execute(
                "SELECT source, relation, weight FROM edges WHERE target=?",
                (node_id,),
            ).fetchall()
            for e in incoming:
                self.link(e["source"], cloned.id, e["relation"], e["weight"])
        # Copy annotations (stored in data._annotations)
        original_data = original.data if isinstance(original.data, dict) else json.loads(original.data)
        annotations = original_data.get("_annotations", {})
        if annotations:
            cloned_data = cloned.data if isinstance(cloned.data, dict) else json.loads(cloned.data)
            cloned_data["_annotations"] = dict(annotations)
            self.conn.execute(
                "UPDATE nodes SET data=? WHERE id=?",
                (json.dumps(cloned_data), cloned.id))
            self.conn.commit()
        return cloned.id

    def graph_diff_summary(self, other: 'MemoryGraph') -> str:
        """Human-readable summary of differences between two graphs.

        Complements graph_diff() with a formatted multi-line string suitable
        for logging, reports, or LLM context injection.

        Returns:
            Newline-separated summary string.
        """
        diff = self.graph_diff(other)
        lines = []
        n_self = len(diff["nodes_only_self"])
        n_other = len(diff["nodes_only_other"])
        n_mod = len(diff["nodes_modified"])
        n_eself = len(diff["edges_only_self"])
        n_eother = len(diff["edges_only_other"])
        total = n_self + n_other + n_mod + n_eself + n_eother
        if total == 0:
            return "Graphs are identical."
        lines.append(f"Graph Diff Summary ({total} differences):")
        if n_self:
            lines.append(f"  Nodes only in self: {n_self}")
        if n_other:
            lines.append(f"  Nodes only in other: {n_other}")
        if n_mod:
            fields = {}
            for m in diff["nodes_modified"]:
                fields[m["field"]] = fields.get(m["field"], 0) + 1
            detail = ", ".join(f"{k}:{v}" for k, v in sorted(fields.items()))
            lines.append(f"  Modified nodes: {n_mod} ({detail})")
        if n_eself:
            lines.append(f"  Edges only in self: {n_eself}")
        if n_eother:
            lines.append(f"  Edges only in other: {n_eother}")
        return "\n".join(lines)

    def workflow_retrieve_by_tag(self, tags: list[str],
                                 match_all: bool = False,
                                 limit: int = 10) -> list[dict]:
        """Retrieve workflows by tag intersection.

        Complements retrieve_workflows (goal-based) with tag-based filtering.
        Useful for domain-scoped workflow lookup (e.g., tags=['ci', 'deploy']).

        Args:
            tags: tags to match
            match_all: if True require all tags (AND), else any (OR)
            limit: max results

        Returns:
            List of workflow dicts with goal, tags, success_rate, step_count.
        """
        workflows = self.conn.execute(
            "SELECT id, label, data, tags FROM nodes WHERE kind='workflow'"
        ).fetchall()
        results = []
        target_tags = set(tags)
        for r in workflows:
            wf_tags = set(json.loads(r["tags"])) if r["tags"] else set()
            if match_all:
                if not target_tags.issubset(wf_tags):
                    continue
            else:
                if not (target_tags & wf_tags):
                    continue
            data = json.loads(r["data"])
            s = data.get("success_count", 0)
            f = data.get("failure_count", 0)
            rate = s / (s + f) if (s + f) > 0 else 0.0
            results.append({
                "id": r["id"],
                "goal": r["label"],
                "tags": sorted(wf_tags),
                "success_rate": round(rate, 4),
                "step_count": data.get("step_count", 0),
                "success_count": s,
                "failure_count": f,
            })
            if len(results) >= limit:
                break
        results.sort(key=lambda x: x["success_rate"], reverse=True)
        return results

    def node_degree_summary(self, node_id: str) -> dict | None:
        """Compact in/out/total degree breakdown for a node.

        Returns:
            {in_degree, out_degree, total, by_relation: {relation: count}}
            or None if node doesn't exist.
        """
        if not self.has_node(node_id):
            return None
        outgoing = self.conn.execute(
            "SELECT relation, COUNT(*) as c FROM edges WHERE source=? GROUP BY relation",
            (node_id,),
        ).fetchall()
        incoming = self.conn.execute(
            "SELECT relation, COUNT(*) as c FROM edges WHERE target=? GROUP BY relation",
            (node_id,),
        ).fetchall()
        out_by_rel = {r["relation"]: r["c"] for r in outgoing}
        in_by_rel = {r["relation"]: r["c"] for r in incoming}
        by_relation = {}
        for rel in set(out_by_rel) | set(in_by_rel):
            by_relation[rel] = {
                "out": out_by_rel.get(rel, 0),
                "in": in_by_rel.get(rel, 0),
            }
        return {
            "in_degree": sum(in_by_rel.values()),
            "out_degree": sum(out_by_rel.values()),
            "total": sum(in_by_rel.values()) + sum(out_by_rel.values()),
            "by_relation": by_relation,
        }

    def tag_correlation_network(self, min_co_occurrence: int = 2) -> dict:
        """Build a tag co-occurrence correlation network.

        Analyzes which tags appear together on the same nodes and returns
        a weighted graph of tag pairs.  Useful for discovering latent
        semantic structure in the knowledge graph.

        Args:
            min_co_occurrence: minimum times two tags must co-occur

        Returns:
            {nodes: [{tag, frequency}], edges: [{source, target, weight}], summary}
        """
        rows = self.conn.execute(
            "SELECT tags FROM nodes WHERE tags != '[]'"
        ).fetchall()
        tag_freq: dict[str, int] = {}
        pair_freq: dict[tuple[str, str], int] = {}
        for r in rows:
            tags = sorted(set(json.loads(r["tags"])))
            for t in tags:
                tag_freq[t] = tag_freq.get(t, 0) + 1
            for i in range(len(tags)):
                for j in range(i + 1, len(tags)):
                    pair = (tags[i], tags[j])
                    pair_freq[pair] = pair_freq.get(pair, 0) + 1
        nodes = [
            {"tag": t, "frequency": f}
            for t, f in sorted(tag_freq.items(), key=lambda x: x[1], reverse=True)
        ]
        edges = [
            {"source": a, "target": b, "weight": w}
            for (a, b), w in sorted(pair_freq.items(), key=lambda x: x[1], reverse=True)
            if w >= min_co_occurrence
        ]
        return {
            "nodes": nodes,
            "edges": edges,
            "total_tags": len(nodes),
            "total_correlations": len(edges),
            "strongest_correlation": edges[0] if edges else None,
        }

    def memory_path_explain(self, source_id: str, target_id: str) -> str | None:
        """Explain the path between two nodes as a narrative string.

        Finds the shortest path, then renders edge labels as a readable
        chain.  Useful for LLM context injection and debugging.

        Returns:
            Human-readable path string, or None if no path / nodes missing.
        """
        path = self.shortest_path(source_id, target_id)
        if not path:
            return None
        if len(path) == 1:
            node = self.get_node(path[0])
            return f"{node.label} (same node)"
        parts = []
        for i in range(len(path) - 1):
            node = self.get_node(path[i])
            next_node = self.get_node(path[i + 1])
            edge = self.conn.execute(
                "SELECT relation FROM edges WHERE source=? AND target=? "
                "ORDER BY weight DESC LIMIT 1",
                (path[i], path[i + 1]),
            ).fetchone()
            relation = edge["relation"] if edge else "→"
            parts.append(f"{node.label} --[{relation}]--> {next_node.label}")
        return "\n".join(parts)

    # ── Q-Value Utility Scoring (MemRL-inspired) ───────────────────

    def memory_qvalue(self, node_id: str,
                      alpha: float = 0.1,
                      gamma: float = 0.9) -> dict | None:
        """Compute Q-value utility score for a memory node.

        Inspired by MemRL (arXiv:2601.03192): memory management as a
        learning problem.  Each node gets a Q-value reflecting its
        demonstrated utility — how often it's accessed, how well
        connected it is, and whether neighbors are also high-value.

        Q(s) = α * immediate_reward + γ * max_neighbor_Q

        immediate_reward = access_frequency_norm * 0.4
                         + degree_norm * 0.3
                         + weight_norm * 0.3

        This is a single-pass approximation (not iterative Bellman) —
        fast enough for real-time query routing.

        Args:
            node_id: target node
            alpha: learning rate / immediate reward weight
            gamma: discount factor for neighbor propagation

        Returns:
            {qvalue, components, neighbors_checked} or None if not found
        """
        node = self.get_node(node_id)
        if not node:
            return None

        stats = self.stats()
        edge_count = stats.get("edges", 0)
        node_count = stats.get("nodes", 1)
        max_degree = max(2.0 * edge_count / max(node_count, 1), 1.0)

        # Access frequency: how many times touched vs created
        access_count = node.data.get("_access_count", 0)
        age_days = max((time.time() - node.created) / 86400.0, 0.01)
        access_freq = access_count / age_days if age_days > 0 else 0
        access_norm = min(access_freq / 10.0, 1.0)  # cap at 10/day

        # Degree normalisation
        degree = len(self.neighbors(node_id))
        degree_norm = degree / max_degree

        # Weight normalisation (0..1)
        weight_norm = max(0.0, min(1.0, node.weight))

        immediate = (access_norm * 0.4 + degree_norm * 0.3 + weight_norm * 0.3)

        # Neighbor Q: average weight of immediate neighbors as proxy
        nbrs = self.neighbors(node_id)
        neighbor_q = 0.0
        if nbrs:
            total_w = sum(
                self.get_node(n.id).weight for n in nbrs
                if self.get_node(n.id)
            )
            neighbor_q = total_w / len(nbrs)

        qvalue = alpha * immediate + gamma * neighbor_q

        return {
            "qvalue": round(qvalue, 4),
            "components": {
                "access": round(access_norm, 4),
                "degree": round(degree_norm, 4),
                "weight": round(weight_norm, 4),
                "immediate": round(immediate, 4),
                "neighbor_avg_weight": round(neighbor_q, 4),
            },
            "neighbors_checked": len(nbrs),
            "alpha": alpha,
            "gamma": gamma,
        }

    def memory_qvalue_batch(self, top_n: int = 20,
                            alpha: float = 0.1,
                            gamma: float = 0.9) -> list[dict]:
        """Compute Q-values for all nodes and return top-N ranked.

        Useful for: deciding which memories to keep active, which to
        consolidate, and which to evict.  Nodes with Q < 0.05 are
        candidates for eviction.

        Returns:
            List of {node_id, label, kind, qvalue, components} sorted desc
        """
        rows = self.conn.execute(
            "SELECT id FROM nodes ORDER BY weight DESC"
        ).fetchall()

        results = []
        for r in rows:
            q = self.memory_qvalue(r["id"], alpha, gamma)
            if q:
                node = self.get_node(r["id"])
                results.append({
                    "node_id": r["id"],
                    "label": node.label,
                    "kind": node.kind,
                    **q,
                })

        results.sort(key=lambda x: x["qvalue"], reverse=True)
        return results[:top_n]

    # ── Drift Detection (SSGM-inspired) ────────────────────────────

    def memory_drift_detect(self, node_id: str,
                            semantic: bool = True,
                            structural: bool = True,
                            temporal: bool = True) -> dict | None:
        """Detect multi-dimensional drift for a memory node.

        Inspired by SSGM (arXiv:2603.11768) drift taxonomy:
        - **Semantic drift**: node label/data diverges from neighbors
        - **Structural drift**: degree or connectivity pattern changed
        - **Temporal drift**: node hasn't been accessed recently

        Each dimension returns a 0..1 score (0 = stable, 1 = heavily
        drifted).  Overall drift = max of dimensions (worst case).

        Returns:
            {semantic, structural, temporal, overall, recommendation}
            or None if node not found
        """
        node = self.get_node(node_id)
        if not node:
            return None

        results = {}

        if semantic:
            # Use semantic_divergence if available
            div = self.semantic_divergence(node_id)
            if div:
                results["semantic"] = round(div.get("divergence_score", 0.0), 4)
            else:
                results["semantic"] = 0.0
        else:
            results["semantic"] = 0.0

        if structural:
            # Compare node degree to graph average
            edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
            node_count = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
            avg_degree = (2.0 * edge_count / node_count) if node_count > 0 else 0.0
            node_degree = len(self.neighbors(node_id))
            if avg_degree > 0:
                # If node has much fewer/more edges than average → drift
                ratio = abs(node_degree - avg_degree) / max(avg_degree, 1.0)
                results["structural"] = round(min(ratio, 1.0), 4)
            else:
                results["structural"] = 0.0
        else:
            results["structural"] = 0.0

        if temporal:
            # Days since last access
            days_since = (time.time() - node.accessed) / 86400.0
            # 30+ days = max temporal drift
            results["temporal"] = round(min(days_since / 30.0, 1.0), 4)
        else:
            results["temporal"] = 0.0

        overall = max(results.values())

        # Recommendation based on dominant drift dimension
        if overall < 0.2:
            recommendation = "stable"
        elif overall < 0.5:
            dom = max(results, key=results.get)
            recommendation = f"minor_{dom}_drift"
        elif overall < 0.8:
            dom = max(results, key=results.get)
            recommendation = f"review_{dom}_drift"
        else:
            dom = max(results, key=results.get)
            recommendation = f"action_{dom}_drift"

        results["overall"] = round(overall, 4)
        results["recommendation"] = recommendation
        results["node_id"] = node_id
        return results

    def memory_drift_scan(self, threshold: float = 0.5,
                          kinds: list[str] | None = None) -> list[dict]:
        """Scan all nodes for drift, return those above threshold.

        Args:
            threshold: minimum overall drift score (0..1)
            kinds: filter to specific node kinds

        Returns:
            List of drift reports sorted by overall desc
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        drifted = []
        for r in rows:
            if kinds:
                node = self.get_node(r["id"])
                if not node or node.kind not in kinds:
                    continue
            report = self.memory_drift_detect(r["id"])
            if report and report["overall"] >= threshold:
                drifted.append(report)

        drifted.sort(key=lambda x: x["overall"], reverse=True)
        return drifted

    # ── Skill Discovery (EvoSkill/SAGE-inspired) ───────────────────

    def discover_skills(self, min_frequency: int = 2,
                        min_success_rate: float = 0.5) -> list[dict]:
        """Discover reusable skill candidates from workflow memory.

        Inspired by EvoSkill (arXiv:2603.02766) failure-driven discovery
        and SAGE (arXiv:2512.17102) sequential rollout.  This method:

        1. Mines common action sequences from successful workflows
        2. Identifies actions that co-occur frequently (skill candidates)
        3. Checks if those actions appear in failed workflows (failure signal)
        4. Ranks by Pareto retention: frequency * (1 - failure_contamination)

        Unlike workflow_success_patterns which just counts individual actions,
        this finds **paired action sequences** — the building blocks of skills.

        Returns:
            List of {action_pair, frequency, success_workflows,
                     failure_workflows, pareto_score} sorted desc.
        """
        # Get successful workflows
        workflows = self.conn.execute(
            "SELECT id, data FROM nodes WHERE kind='workflow'"
        ).fetchall()

        success_seqs: dict[str, list[str]] = {}  # wf_id → ordered actions
        failure_seqs: dict[str, list[str]] = {}

        for r in workflows:
            data = json.loads(r["data"])
            s = data.get("success_count", 0)
            f = data.get("failure_count", 0)
            total = s + f
            if total == 0:
                continue

            steps = self.conn.execute(
                "SELECT target FROM edges WHERE source=? AND relation='has_step'",
                (r["id"],),
            ).fetchall()

            actions = []
            for step_row in steps:
                step_node = self.get_node(step_row["target"])
                if step_node:
                    sd = step_node.data if isinstance(step_node.data, dict) else json.loads(step_node.data)
                    actions.append(sd.get("action", step_node.label))

            if s > f:
                success_seqs[r["id"]] = actions
            elif f > s:
                failure_seqs[r["id"]] = actions

        # Find co-occurring action pairs in success sequences
        pair_stats: dict[tuple[str, str], dict] = {}
        for wf_id, actions in success_seqs.items():
            seen_pairs = set()
            for i in range(len(actions) - 1):
                for j in range(i + 1, len(actions)):
                    pair = tuple(sorted((actions[i], actions[j])))
                    if pair not in seen_pairs:
                        seen_pairs.add(pair)
                        if pair not in pair_stats:
                            pair_stats[pair] = {
                                "action_pair": list(pair),
                                "frequency": 0,
                                "success_workflows": [],
                                "failure_workflows": [],
                            }
                        pair_stats[pair]["frequency"] += 1
                        pair_stats[pair]["success_workflows"].append(wf_id)

        # Check contamination in failure sequences
        for wf_id, actions in failure_seqs.items():
            action_set = set(actions)
            for pair, info in pair_stats.items():
                if pair[0] in action_set and pair[1] in action_set:
                    info["failure_workflows"].append(wf_id)

        # Pareto scoring: frequency * (1 - failure_contamination)
        results = []
        for pair, info in pair_stats.items():
            if info["frequency"] < min_frequency:
                continue
            sf = len(info["success_workflows"])
            ff = len(info["failure_workflows"])
            rate = sf / (sf + ff) if (sf + ff) > 0 else 0.0
            if rate < min_success_rate:
                continue
            pareto = info["frequency"] * (1.0 - ff / max(sf + ff, 1))
            results.append({
                "action_pair": info["action_pair"],
                "frequency": info["frequency"],
                "success_workflows": sf,
                "failure_workflows": ff,
                "success_rate": round(rate, 4),
                "pareto_score": round(pareto, 4),
            })

        results.sort(key=lambda x: x["pareto_score"], reverse=True)
        return results

    # ── Memory Utilization Report ──────────────────────────────────

    def memory_utilization_report(self) -> dict:
        """Executive summary of memory store health and usage.

        Combines Q-value distribution, drift scan, workflow coverage,
        and kind distribution into a single dashboard report.

        Returns:
            {total_nodes, by_kind, avg_qvalue, top_qvalue_nodes,
             drifted_nodes, workflow_coverage, recommendations}
        """
        stats = self.stats()
        total = stats.get("nodes", 0)

        if total == 0:
            return {
                "total_nodes": 0,
                "by_kind": {},
                "avg_qvalue": 0.0,
                "top_qvalue_nodes": [],
                "drifted_nodes": [],
                "workflow_coverage": 0.0,
                "recommendations": ["empty_store"],
            }

        # Kind distribution
        by_kind = stats.get("by_kind", {})

        # Q-value stats (sample up to 50 for speed)
        q_batch = self.memory_qvalue_batch(top_n=50)
        q_values = [q["qvalue"] for q in q_batch]
        avg_q = sum(q_values) / len(q_values) if q_values else 0.0

        # Drift scan (threshold 0.5)
        drifted = self.memory_drift_scan(threshold=0.5)

        # Workflow coverage
        wf_stats = self.workflow_stats()
        wf_coverage = wf_stats.get("coverage", 0.0)

        # Build recommendations
        recs = []
        if avg_q < 0.1:
            recs.append("low_utilization")
        if len(drifted) > total * 0.3:
            recs.append("high_drift_ratio")
        if wf_coverage < 0.3:
            recs.append("low_workflow_coverage")
        if not recs:
            recs.append("healthy")

        return {
            "total_nodes": total,
            "by_kind": by_kind,
            "avg_qvalue": round(avg_q, 4),
            "top_qvalue_nodes": [
                {"label": q["label"], "qvalue": q["qvalue"]}
                for q in q_batch[:5]
            ],
            "drifted_count": len(drifted),
            "workflow_coverage": round(wf_coverage, 4),
            "recommendations": recs,
        }

    # ── Memory Reinforcement (MemRL operational) ───────────────────

    def memory_reinforce(self, node_id: str, outcome: str,
                         boost: float = 0.1) -> dict | None:
        """Reinforce a memory node based on observed outcome.

        Operationalises the MemRL insight: memory management is a learning
        problem.  Each outcome adjusts the node's weight, simulating
        Q-value updates without a full RL training loop.

        - "positive": weight += boost (capped at 1.0)
        - "negative": weight -= boost (floored at 0.01)
        - "neutral":  weight unchanged, but touch (update accessed)

        Records the reinforcement event in node metadata for auditability.

        Args:
            node_id: target node
            outcome: "positive" | "negative" | "neutral"
            boost: weight delta (default 0.1)

        Returns:
            {node_id, outcome, old_weight, new_weight, boost} or None
        """
        node = self.get_node(node_id)
        if not node:
            return None

        old_weight = node.weight

        if outcome == "positive":
            new_weight = min(1.0, old_weight + boost)
        elif outcome == "negative":
            new_weight = max(0.01, old_weight - boost)
        elif outcome == "neutral":
            new_weight = old_weight
        else:
            return None

        # Update weight, accessed time, and record event
        now = time.time()
        data = node.data if isinstance(node.data, dict) else json.loads(node.data)
        history = data.setdefault("_reinforcement_history", [])
        history.append({
            "outcome": outcome,
            "boost": boost,
            "old_weight": round(old_weight, 4),
            "new_weight": round(new_weight, 4),
            "timestamp": now,
        })
        # Keep only last 50 events
        if len(history) > 50:
            data["_reinforcement_history"] = history[-50:]

        self.conn.execute(
            "UPDATE nodes SET weight=?, accessed=?, data=? WHERE id=?",
            (new_weight, now, json.dumps(data), node_id),
        )
        self.conn.commit()

        return {
            "node_id": node_id,
            "outcome": outcome,
            "old_weight": round(old_weight, 4),
            "new_weight": round(new_weight, 4),
            "boost": boost,
        }

    def skill_gap_analysis(self, min_failures: int = 1) -> list[dict]:
        """Identify missing skills from failed workflow patterns.

        Insight from EvoSkill (arXiv:2603.02766): failures reveal which
        action transitions are missing.  If workflow A fails and workflow
        B succeeds, and A has steps [x, z] while B has [x, y, z], then
        action 'y' is a **skill gap** — a missing intermediate step.

        This method compares failed workflows to successful ones with
        overlapping actions, and identifies intermediate actions present
        in successes but absent in failures.

        Returns:
            List of {missing_action, in_workflows, failed_workflows,
                     gap_severity} sorted by gap_severity desc
        """
        workflows = self.conn.execute(
            "SELECT id, data FROM nodes WHERE kind='workflow'"
        ).fetchall()

        success_actions: dict[str, set[str]] = {}
        failure_actions: dict[str, set[str]] = {}

        for r in workflows:
            data = json.loads(r["data"])
            s = data.get("success_count", 0)
            f = data.get("failure_count", 0)
            total = s + f
            if total == 0:
                continue

            steps = self.conn.execute(
                "SELECT target FROM edges WHERE source=? AND relation='has_step'",
                (r["id"],),
            ).fetchall()

            actions = set()
            for step_row in steps:
                step_node = self.get_node(step_row["target"])
                if step_node:
                    sd = step_node.data if isinstance(step_node.data, dict) else json.loads(step_node.data)
                    actions.add(sd.get("action", step_node.label))

            if s > f:
                success_actions[r["id"]] = actions
            elif f >= min_failures:
                failure_actions[r["id"]] = actions

        # For each failure, find overlapping successes and identify missing
        gap_map: dict[str, dict] = {}
        for fail_id, fail_acts in failure_actions.items():
            for succ_id, succ_acts in success_actions.items():
                overlap = fail_acts & succ_acts
                if len(overlap) < 1:
                    continue
                missing = succ_acts - fail_acts
                for action in missing:
                    if action not in gap_map:
                        gap_map[action] = {
                            "missing_action": action,
                            "in_workflows": [],
                            "failed_workflows": [],
                            "gap_severity": 0,
                        }
                    gap_map[action]["in_workflows"].append(succ_id)
                    gap_map[action]["failed_workflows"].append(fail_id)

        # Severity = how many distinct failures would benefit
        results = []
        for action, info in gap_map.items():
            unique_failures = len(set(info["failed_workflows"]))
            unique_successes = len(set(info["in_workflows"]))
            info["in_workflows"] = unique_successes
            info["failed_workflows"] = unique_failures
            info["gap_severity"] = unique_failures * unique_successes
            results.append(info)

        results.sort(key=lambda x: x["gap_severity"], reverse=True)
        return results

    # ── Memory Attention Score ─────────────────────────────────────

    def memory_attention_score(self, node_id: str,
                               recency_window_hours: float = 24.0) -> dict | None:
        """Compute attention score — how "hot" a node is right now.

        Combines recent reinforcement events, access recency, and
        neighbor activity into a single 0..1 score.  Unlike Q-value
        (which is structural), attention is temporal — it decays.

        Attention = recency_boost * 0.4
                  + reinforcement_velocity * 0.4
                  + neighbor_activity * 0.2

        Use cases: prioritise which memories to surface in context,
        identify trending topics, detect attention sinkholes.

        Returns:
            {attention, recency_boost, reinforcement_velocity,
             neighbor_activity, recent_events} or None
        """
        node = self.get_node(node_id)
        if not node:
            return None

        now = time.time()
        window_sec = recency_window_hours * 3600

        # Recency boost: how recently was this node accessed?
        age_sec = now - node.accessed
        recency_boost = max(0.0, 1.0 - age_sec / window_sec)

        # Reinforcement velocity: rate of recent positive/negative events
        data = node.data if isinstance(node.data, dict) else json.loads(node.data)
        history = data.get("_reinforcement_history", [])
        recent_events = [
            e for e in history
            if (now - e.get("timestamp", 0)) < window_sec
        ]
        max_possible = 10  # normalize: 10 events in window = velocity 1.0
        reinforcement_velocity = min(len(recent_events) / max_possible, 1.0)

        # Neighbor activity: average recency of neighbor access
        nbrs = self.neighbors(node_id)
        if nbrs:
            neighbor_recencies = []
            for n in nbrs:
                n_age = now - n.accessed
                neighbor_recencies.append(max(0.0, 1.0 - n_age / window_sec))
            neighbor_activity = sum(neighbor_recencies) / len(neighbor_recencies)
        else:
            neighbor_activity = 0.0

        attention = (
            recency_boost * 0.4
            + reinforcement_velocity * 0.4
            + neighbor_activity * 0.2
        )

        return {
            "attention": round(attention, 4),
            "recency_boost": round(recency_boost, 4),
            "reinforcement_velocity": round(reinforcement_velocity, 4),
            "neighbor_activity": round(neighbor_activity, 4),
            "recent_events": len(recent_events),
        }

    def consolidation_priority(self, limit: int = 20) -> list[dict]:
        """Rank nodes by consolidation urgency.

        Combines drift score, Q-value, and attention into a priority
        ranking.  High-priority nodes are those that are:
        - Drifting (semantic/structural/temporal)
        - Low Q-value (low demonstrated utility)
        - Low attention (not recently active)

        These are prime candidates for: consolidation, archival, or eviction.

        Returns:
            List of {node_id, label, priority, drift, qvalue, attention}
            sorted by priority descending
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()

        results = []
        for r in rows:
            node = self.get_node(r["id"])
            if not node:
                continue

            drift = self.memory_drift_detect(r["id"])
            q = self.memory_qvalue(r["id"])
            att = self.memory_attention_score(r["id"])

            if not (drift and q and att):
                continue

            # Priority = drift * (1 - qvalue) * (1 - attention)
            # High drift + low Q + low attention = high priority
            priority = (
                drift["overall"]
                * (1.0 - q["qvalue"])
                * (1.0 - att["attention"])
            )

            results.append({
                "node_id": r["id"],
                "label": node.label,
                "kind": node.kind,
                "priority": round(priority, 4),
                "drift": drift["overall"],
                "qvalue": q["qvalue"],
                "attention": att["attention"],
                "recommendation": drift["recommendation"],
            })

        results.sort(key=lambda x: x["priority"], reverse=True)
        return results[:limit]

    # ── Bi-Temporal Validity Tracking ──────────────────────────────
    #
    # Inspired by Temporal Knowledge Graphs (T-KG) research.
    # Every edge can have a validity window [valid_from, valid_until].
    # Invalidated edges record *who* invalidated them and *when*.
    # This enables time-travel queries: "what was true at time T?"
    #
    # Storage: leverages the existing edge_props JSON column — zero
    # schema migration required.

    def edge_set_validity(self, source_id: str, target_id: str,
                          relation: str, valid_from: float = None,
                          valid_until: float = None) -> dict | None:
        """Set bi-temporal validity window on an edge.

        Args:
            valid_from:  Unix timestamp from which the edge is valid.
                         Default: now (edge creation time).
            valid_until: Unix timestamp after which the edge is invalid.
                         None means open-ended (still valid).

        Returns the stored validity dict, or None if edge doesn't exist.
        """
        edge = self.get_edge(source_id, target_id, relation)
        if not edge:
            return None
        now = time.time()
        props = self.edge_properties(source_id, target_id, relation) or {}
        props["_temporal"] = {
            "valid_from": valid_from if valid_from is not None else now,
            "valid_until": valid_until,          # None = open-ended
            "invalidated_by": props.get("_temporal", {}).get("invalidated_by"),
            "set_at": now,
        }
        self.set_edge_properties(source_id, target_id, relation, props)
        self.conn.commit()
        return props["_temporal"]

    def edge_invalidate(self, source_id: str, target_id: str,
                        relation: str, invalidated_by: str = None) -> dict | None:
        """Mark an edge as no longer valid.

        Sets valid_until to now and records who invalidated it.
        Idempotent — calling twice is a no-op.

        Args:
            invalidated_by: Identifier (node id or label) of the agent
                            or process that caused invalidation.

        Returns the updated validity dict, or None if edge doesn't exist.
        """
        edge = self.get_edge(source_id, target_id, relation)
        if not edge:
            return None
        now = time.time()
        props = self.edge_properties(source_id, target_id, relation) or {}
        existing = props.get("_temporal", {})
        if existing.get("valid_until") is not None:
            return existing  # already invalidated — idempotent
        props["_temporal"] = {
            "valid_from": existing.get("valid_from", now),
            "valid_until": now,
            "invalidated_by": invalidated_by,
            "set_at": now,
        }
        self.set_edge_properties(source_id, target_id, relation, props)
        self.conn.commit()
        return props["_temporal"]

    def edge_valid_at(self, source_id: str, target_id: str,
                      relation: str, timestamp: float = None) -> bool:
        """Check whether an edge was valid at the given time.

        An edge is valid at *timestamp* if:
        - The edge exists.
        - valid_from <= timestamp (or no temporal info → always valid).
        - valid_until is None or valid_until > timestamp.

        Default timestamp: now.
        """
        edge = self.get_edge(source_id, target_id, relation)
        if not edge:
            return False
        ts = timestamp if timestamp is not None else time.time()
        props = self.edge_properties(source_id, target_id, relation) or {}
        temporal = props.get("_temporal")
        if not temporal:
            return True  # no temporal constraint → always valid
        if temporal["valid_from"] > ts:
            return False
        vu = temporal.get("valid_until")
        if vu is not None and vu <= ts:
            return False
        return True

    def temporal_snapshot(self, timestamp: float = None) -> list[Edge]:
        """Return all edges valid at the given timestamp.

        Useful for time-travel queries: "what did the graph look like
        at time T?"  Edges without temporal info are always included.

        Returns a list of Edge namedtuples.
        """
        ts = timestamp if timestamp is not None else time.time()
        rows = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges"
        ).fetchall()
        result = []
        for r in rows:
            props = self.edge_properties(r["source"], r["target"], r["relation"])
            temporal = (props or {}).get("_temporal")
            if not temporal:
                result.append(Edge(r["source"], r["target"], r["relation"], r["weight"]))
                continue
            if temporal["valid_from"] <= ts:
                vu = temporal.get("valid_until")
                if vu is None or vu > ts:
                    result.append(Edge(r["source"], r["target"], r["relation"], r["weight"]))
        return result

    def edge_temporal_history(self, node_id: str,
                              direction: str = "both") -> list[dict]:
        """Return temporal history of edges connected to a node.

        Each entry includes the edge triple, validity window, and
        invalidation info (if any).  Sorted by valid_from descending.

        direction: 'outgoing', 'incoming', or 'both'.
        """
        edges = self.edges_of(node_id, direction=direction)
        history = []
        for e in edges:
            props = self.edge_properties(e.source, e.target, e.relation)
            temporal = (props or {}).get("_temporal")
            if temporal:
                history.append({
                    "source": e.source,
                    "target": e.target,
                    "relation": e.relation,
                    "valid_from": temporal["valid_from"],
                    "valid_until": temporal.get("valid_until"),
                    "invalidated_by": temporal.get("invalidated_by"),
                    "status": "invalidated" if temporal.get("valid_until") is not None else "valid",
                })
        history.sort(key=lambda x: x["valid_from"], reverse=True)
        return history

    # ── Node-Level Bi-Temporal Validity ───────────────────────
    #
    # Extends bi-temporal tracking from edges to nodes.  Enables:
    #   - "This fact was true from 2024-01-01 to 2024-06-30"
    #   - "Show me all concepts that were valid at time T"
    #   - "Invalidate this node — it's no longer accurate"
    #
    # Storage: node.data['_node_temporal'] — zero schema migration.

    def node_set_validity(self, node_id: str,
                          valid_from: float = None,
                          valid_until: float = None) -> dict | None:
        """Set bi-temporal validity window on a node.

        Args:
            valid_from: Unix timestamp from which the node's content is
                        valid.  Default: node creation time.
            valid_until: Unix timestamp after which the node is invalid.
                         None means open-ended (currently valid).

        Returns the stored validity dict, or None if node doesn't exist.
        """
        node = self.get_node(node_id)
        if not node:
            return None
        now = time.time()
        data = node.data if isinstance(node.data, dict) else json.loads(node.data)
        existing = data.get("_node_temporal", {})
        data["_node_temporal"] = {
            "valid_from": valid_from if valid_from is not None else existing.get("valid_from", node.created),
            "valid_until": valid_until if valid_until is not None else existing.get("valid_until"),
            "invalidated_by": existing.get("invalidated_by"),
            "set_at": now,
        }
        self.conn.execute(
            "UPDATE nodes SET data=? WHERE id=?",
            (json.dumps(data), node_id))
        self.conn.commit()
        return data["_node_temporal"]

    def node_invalidate(self, node_id: str,
                        invalidated_by: str = None) -> dict | None:
        """Mark a node as no longer valid.

        Sets valid_until to now and records who invalidated it.
        Idempotent — calling twice is a no-op.

        Args:
            invalidated_by: Identifier (agent id or label) of the
                            process that caused invalidation.

        Returns the updated validity dict, or None if node doesn't exist.
        """
        node = self.get_node(node_id)
        if not node:
            return None
        now = time.time()
        data = node.data if isinstance(node.data, dict) else json.loads(node.data)
        existing = data.get("_node_temporal", {})
        if existing.get("valid_until") is not None:
            return existing  # already invalidated — idempotent
        data["_node_temporal"] = {
            "valid_from": existing.get("valid_from", node.created),
            "valid_until": now,
            "invalidated_by": invalidated_by,
            "set_at": now,
        }
        self.conn.execute(
            "UPDATE nodes SET data=? WHERE id=?",
            (json.dumps(data), node_id))
        self.conn.commit()
        return data["_node_temporal"]

    def invalidate_cascade(self, node_id: str, reason: str = None,
                           invalidated_by: str = None,
                           cascade_relations: list[str] = None,
                           max_depth: int = 10) -> dict:
        """Invalidate a node and cascade to dependent nodes.

        Inspired by PLACEMEM (2607.04089): when a fact becomes invalid,
        nodes that *depend on* or are *enabled by* it should also be
        invalidated to prevent stale downstream reasoning.

        Traverses causal edges (``depends_on``, ``enables`` by default)
        via BFS, invalidating each reachable node. Cycle-safe via visited
        set. Already-invalidated nodes are skipped (idempotent).

        Args:
            node_id: Root node to invalidate.
            reason: Human-readable reason for invalidation.
            invalidated_by: Identifier of the invalidating agent/process.
            cascade_relations: Edge relations to follow for cascade.
                Default: ``['depends_on', 'enables']``.
            max_depth: Maximum BFS depth to prevent runaway cascades.

        Returns:
            Dict with ``root``, ``cascaded`` (list of node IDs),
            ``depth_reached``, ``reason``.
        """
        if cascade_relations is None:
            cascade_relations = ['depends_on', 'enables']
        root_node = self.get_node(node_id)
        if root_node is None:
            return {"root": node_id, "cascaded": [], "count": 0,
                    "depth_reached": 0, "reason": reason,
                    "error": "root node not found"}
        cascaded = []
        visited = {node_id}
        queue = [(node_id, 0)]
        while queue:
            current_id, depth = queue.pop(0)
            if depth > max_depth:
                continue
            # Invalidate current node (idempotent)
            result = self.node_invalidate(current_id, invalidated_by=invalidated_by)
            if result:
                cascaded.append(current_id)
            # Find dependent nodes:
            # - depends_on: A --depends_on--> current means A depends on current,
            #   so invalidating current should cascade to A (reverse lookup).
            # - enables: current --enables--> B means current enables B,
            #   so invalidating current should cascade to B (forward lookup).
            # For depends_on, find sources pointing to current
            dep_rows = self.conn.execute(
                "SELECT DISTINCT source FROM edges WHERE target=? AND relation='depends_on'",
                (current_id,)
            ).fetchall()
            for row in dep_rows:
                if row['source'] not in visited:
                    visited.add(row['source'])
                    queue.append((row['source'], depth + 1))
            # For enables, find targets from current
            placeholders = ','.join('?' * len(cascade_relations))
            fwd_rows = self.conn.execute(
                f"SELECT DISTINCT target FROM edges WHERE source=? AND relation IN ({placeholders})",
                (current_id, *cascade_relations)
            ).fetchall()
            for row in fwd_rows:
                if row['target'] not in visited:
                    visited.add(row['target'])
                    queue.append((row['target'], depth + 1))
        return {
            "root": node_id,
            "cascaded": cascaded,
            "count": len(cascaded),
            "depth_reached": max(0, max((d for _, d in [(n, 0) for n in cascaded]), default=0)),
            "reason": reason,
            "invalidated_by": invalidated_by,
        }

    def propagate_correction(self, node_id: str, new_content: str = None,
                             reason: str = None, corrected_by: str = None,
                             impact_relations: list[str] = None,
                             mark_status: str = "needs_review",
                             max_depth: int = 10) -> dict:
        """Propagate a content correction to dependent nodes.

        When a node's content is corrected, dependent nodes (connected via
        ``depends_on`` / ``enables`` edges) should be marked for review since
        they may have been derived from the old content.

        Unlike :meth:`invalidate_cascade` (which marks nodes invalid), this
        method uses a softer ``_correction`` metadata flag, preserving the
        knowledge while signalling it needs re-evaluation.

        Traversal logic (same as ``invalidate_cascade``):
        - ``depends_on``: A --depends_on--> current → A depends on current
          → reverse lookup (find sources pointing to current).
        - ``enables``: current --enables--> B → forward lookup.

        Args:
            node_id: The corrected node.
            new_content: If provided, updates the root node's label.
            reason: Human-readable reason for the correction.
            corrected_by: Identifier of who made the correction.
            impact_relations: Edge relations to traverse.
                Default: ``['depends_on', 'enables']``.
            mark_status: Status string to store in ``_correction`` metadata.
            max_depth: Maximum BFS depth.

        Returns:
            Dict with ``root``, ``impacted`` (list of node IDs),
            ``skipped`` (already-invalidated nodes), ``count``,
            ``depth_reached``, ``reason``, ``corrected_by``.
        """
        if impact_relations is None:
            impact_relations = ['depends_on', 'enables']
        root_node = self.get_node(node_id)
        if root_node is None:
            return {"root": node_id, "impacted": [], "skipped": [],
                    "count": 0, "depth_reached": 0, "reason": reason,
                    "corrected_by": corrected_by,
                    "error": "root node not found"}

        # Optionally update root content
        if new_content is not None:
            self.conn.execute(
                "UPDATE nodes SET label=? WHERE id=?",
                (new_content, node_id))

        impacted = []
        skipped = []
        visited = {node_id}
        queue = [(node_id, 0)]  # (node_id, hops_from_root)
        now = time.time()

        while queue:
            current_id, hops = queue.pop(0)
            if hops > max_depth:
                continue

            node = self.get_node(current_id)
            if node is None:
                continue

            # Check if already invalidated — skip if so
            data = node.data if isinstance(node.data, dict) else json.loads(node.data)
            temporal = data.get("_node_temporal", {})
            if temporal.get("valid_until") is not None:
                skipped.append(current_id)
                continue  # skip invalidated nodes, but still traverse their edges

            # Mark with correction metadata
            data["_correction"] = {
                "status": mark_status,
                "source": node_id,
                "reason": reason,
                "corrected_by": corrected_by,
                "corrected_at": now,
                "hops": hops,
            }
            self.conn.execute(
                "UPDATE nodes SET data=? WHERE id=?",
                (json.dumps(data), current_id))
            impacted.append(current_id)

            # Reverse lookup for depends_on: find sources pointing to current
            dep_rows = self.conn.execute(
                "SELECT DISTINCT source FROM edges WHERE target=? AND relation='depends_on'",
                (current_id,)
            ).fetchall()
            for row in dep_rows:
                if row['source'] not in visited:
                    visited.add(row['source'])
                    queue.append((row['source'], hops + 1))

            # Forward lookup for enables and other impact_relations
            placeholders = ','.join('?' * len(impact_relations))
            fwd_rows = self.conn.execute(
                f"SELECT DISTINCT target FROM edges WHERE source=? AND relation IN ({placeholders})",
                (current_id, *impact_relations)
            ).fetchall()
            for row in fwd_rows:
                if row['target'] not in visited:
                    visited.add(row['target'])
                    queue.append((row['target'], hops + 1))

        self.conn.commit()

        # Compute depth reached (max hops among impacted nodes)
        max_hops = 0
        for nid in impacted:
            n = self.get_node(nid)
            nd = n.data if isinstance(n.data, dict) else json.loads(n.data)
            c = nd.get("_correction", {})
            if c.get("hops", 0) > max_hops:
                max_hops = c["hops"]

        return {
            "root": node_id,
            "impacted": impacted,
            "skipped": skipped,
            "count": len(impacted),
            "depth_reached": max_hops,
            "reason": reason,
            "corrected_by": corrected_by,
        }

    def node_valid_at(self, node_id: str,
                      timestamp: float = None) -> bool:
        """Check whether a node was valid at the given time.

        A node is valid at *timestamp* if:
        - The node exists.
        - valid_from <= timestamp (or no temporal info → always valid).
        - valid_until is None or valid_until > timestamp.

        Default timestamp: now.
        """
        node = self.get_node(node_id)
        if not node:
            return False
        ts = timestamp if timestamp is not None else time.time()
        data = node.data if isinstance(node.data, dict) else json.loads(node.data)
        temporal = data.get("_node_temporal")
        if not temporal:
            return True  # no temporal constraint → always valid
        if temporal["valid_from"] > ts:
            return False
        vu = temporal.get("valid_until")
        if vu is not None and vu <= ts:
            return False
        return True

    def temporal_graph_snapshot(self, timestamp: float = None) -> dict:
        """Return the full graph state (nodes + edges) valid at *timestamp*.

        Combines node-level and edge-level bi-temporal filtering.
        Nodes/edges without temporal info are always included.

        Returns:
            {timestamp, nodes: [...], edges: [...], stats: {nodes, edges}}
        """
        ts = timestamp if timestamp is not None else time.time()

        # Filter nodes
        valid_nodes = []
        for row in self.conn.execute("SELECT id FROM nodes").fetchall():
            if self.node_valid_at(row["id"], ts):
                node = self.get_node(row["id"])
                valid_nodes.append({
                    "id": node.id,
                    "label": node.label,
                    "kind": node.kind,
                    "weight": round(node.weight, 4),
                })

        # Filter edges using edge_valid_at
        valid_edges = []
        for row in self.conn.execute(
            "SELECT source, target, relation FROM edges"
        ).fetchall():
            if self.edge_valid_at(row["source"], row["target"], row["relation"], ts):
                valid_edges.append({
                    "source": row["source"],
                    "target": row["target"],
                    "relation": row["relation"],
                })

        return {
            "timestamp": ts,
            "nodes": valid_nodes,
            "edges": valid_edges,
            "stats": {
                "nodes": len(valid_nodes),
                "edges": len(valid_edges),
            },
        }

    # ── OWASP ASI06: Provenance & Quarantine ──────────────────

    def temporal_diff(self, t1: float, t2: float) -> dict:
        """Measure graph evolution between two timestamps.

        Computes the structural difference between the graph state at
        *t1* and *t2* (where t1 < t2).  Returns node/edge churn,
        degree-index entropy delta, and growth/decay classification.

        Bridges the temporal query suite (``query_as_of``,
        ``temporal_graph_snapshot``) with the entropy toolkit to quantify
        *how much* and *in what direction* the graph evolved.

        Args:
            t1: Earlier timestamp.
            t2: Later timestamp (must be >= t1).

        Returns:
            Dict with:
            - ``t1``, ``t2``: input timestamps
            - ``nodes_added``: list of node IDs present at t2 but not t1
            - ``nodes_removed``: list of node IDs present at t1 but not t2
            - ``nodes_stable``: count of nodes present at both
            - ``edges_added``: count of new edges
            - ``edges_removed``: count of gone edges
            - ``edges_stable``: count of unchanged edges
            - ``node_churn``: float (added + removed) / total
            - ``edge_churn``: float (added + removed) / total
            - ``growth_rate``: float (net change) / baseline count
            - ``phase``: 'growth', 'decay', 'stable', or 'churn'
            - ``sombor_entropy_delta``: float or None
        """
        snap1 = self.temporal_graph_snapshot(t1)
        snap2 = self.temporal_graph_snapshot(t2)

        # Also filter by SQL-column validity (supersede system)
        nodes1_raw = {n["id"] for n in snap1["nodes"]}
        nodes2_raw = {n["id"] for n in snap2["nodes"]}
        nodes1 = {nid for nid in nodes1_raw if self.is_valid_at(nid, t1)}
        nodes2 = {nid for nid in nodes2_raw if self.is_valid_at(nid, t2)}

        edges1 = {
            (e["source"], e["target"], e["relation"])
            for e in snap1["edges"]
        }
        edges2 = {
            (e["source"], e["target"], e["relation"])
            for e in snap2["edges"]
        }

        nodes_added = sorted(nodes2 - nodes1)
        nodes_removed = sorted(nodes1 - nodes2)
        nodes_stable = len(nodes1 & nodes2)

        edges_added = edges2 - edges1
        edges_removed = edges1 - edges2
        edges_stable = len(edges1 & edges2)

        total_nodes = max(len(nodes1), len(nodes2), 1)
        total_edges = max(len(edges1), len(edges2), 1)

        node_churn = (len(nodes_added) + len(nodes_removed)) / total_nodes
        edge_churn = (len(edges_added) + len(edges_removed)) / total_edges

        net_node_change = len(nodes2) - len(nodes1)
        growth_rate = net_node_change / max(len(nodes1), 1)

        # Phase classification
        net_change = len(nodes_added) - len(nodes_removed)
        if abs(growth_rate) < 0.05 and node_churn < 0.1:
            phase = "stable"
        elif net_change > 0:
            phase = "growth"
        elif net_change < 0:
            phase = "decay"
        else:
            phase = "churn"  # High turnover, no net change

        return {
            "t1": t1,
            "t2": t2,
            "nodes_added": nodes_added,
            "nodes_removed": nodes_removed,
            "nodes_stable": nodes_stable,
            "edges_added": len(edges_added),
            "edges_removed": len(edges_removed),
            "edges_stable": edges_stable,
            "node_churn": round(node_churn, 6),
            "edge_churn": round(edge_churn, 6),
            "growth_rate": round(growth_rate, 6),
            "phase": phase,
        }

    # ── OWASP ASI06: Provenance & Quarantine ──────────────────

    def node_set_provenance(self, node_id: str, source: str = None,
                            trust_level: float = None,
                            parents: list[str] = None) -> bool:
        """Set provenance metadata on a node (OWASP ASI06 defense).

        Tracks WHERE a memory came from (source), HOW MUCH to trust it
        (trust_level 0-1), and WHICH nodes derived it (parents).
        Enables quarantine of untrusted/contaminated memory chains.
        """
        node = self.get_node(node_id)
        if not node:
            return False
        updates, params = [], []
        if source is not None:
            updates.append("source = ?")
            params.append(source)
        if trust_level is not None:
            updates.append("trust_level = ?")
            params.append(max(0.0, min(1.0, trust_level)))
        if parents is not None:
            updates.append("parents = ?")
            params.append(json.dumps(parents))
        if not updates:
            return False
        params.append(node_id)
        self.conn.execute(f"UPDATE nodes SET {', '.join(updates)} WHERE id = ?", params)
        self.conn.commit()
        return True

    def node_quarantine(self, node_id: str, reason: str = "") -> bool:
        """Quarantine a node — excluded from retrieval (recall/search/neighbors).

        Use when a memory is suspected of being contaminated, adversarial,
        or otherwise untrustworthy (OWASP ASI06).
        """
        node = self.get_node(node_id)
        if not node:
            return False
        self.conn.execute(
            "UPDATE nodes SET quarantined = 1, quarantine_reason = ? WHERE id = ?",
            (reason or "unspecified", node_id)
        )
        self.conn.commit()
        return True

    def node_unquarantine(self, node_id: str) -> bool:
        """Release a node from quarantine."""
        node = self.get_node(node_id)
        if not node:
            return False
        self.conn.execute(
            "UPDATE nodes SET quarantined = 0, quarantine_reason = NULL WHERE id = ?",
            (node_id,)
        )
        self.conn.commit()
        return True

    def quarantine_list(self) -> list[dict]:
        """List all quarantined nodes with reasons."""
        rows = self.conn.execute(
            "SELECT id, label, kind, trust_level, source, quarantine_reason "
            "FROM nodes WHERE quarantined = 1 ORDER BY label"
        ).fetchall()
        return [dict(r) for r in rows]

    def quarantine_scan(self, trust_threshold: float = 0.3) -> list[str]:
        """Auto-quarantine nodes with trust_level below threshold.

        Returns list of newly quarantined node IDs.
        """
        rows = self.conn.execute(
            "SELECT id FROM nodes WHERE quarantined = 0 AND trust_level < ?",
            (trust_threshold,)
        ).fetchall()
        quarantined_ids = []
        for r in rows:
            self.conn.execute(
                "UPDATE nodes SET quarantined = 1, quarantine_reason = ? WHERE id = ?",
                (f"auto: trust_level below {trust_threshold}", r["id"])
            )
            quarantined_ids.append(r["id"])
        self.conn.commit()
        return quarantined_ids

    # ── Graph Reasoning APIs (HopRAG / GR-Agent / GNN-RAG inspired) ────────

    def reasoning_path(self, seed_id: str, target_id: str,
                        max_hops: int = 3, strategy: str = "shortest",
                        top_k: int = 5) -> list[dict]:
        """带分数的推理路径 (Retrieve-Reason-Prune 范式).

        策略:
        - shortest: BFS 最短路径 (精确)
        - pagerank_guided: 经过高 PageRank 中间节点
        - random_walk: 多样化随机游走路径

        返回 [{path, edges, score, explanation, source}, ...]
        """
        if not self.has_node(seed_id) or not self.has_node(target_id):
            return []
        if seed_id == target_id:
            return [{"path": [seed_id], "edges": [], "score": 1.0,
                     "explanation": "seed and target are the same node",
                     "source": "trivial"}]
        results = []

        def _edge_label(s, t):
            r = self.conn.execute(
                "SELECT relation FROM edges WHERE source=? AND target=? ORDER BY weight DESC LIMIT 1",
                (s, t)).fetchone()
            if r:
                return r["relation"]
            r = self.conn.execute(
                "SELECT relation FROM edges WHERE source=? AND target=? ORDER BY weight DESC LIMIT 1",
                (t, s)).fetchone()
            return r["relation"] if r else "related"

        def _verbalize(path):
            parts = []
            for i in range(len(path) - 1):
                lbl = _edge_label(path[i], path[i + 1])
                n1 = self.conn.execute("SELECT label FROM nodes WHERE id=?", (path[i],)).fetchone()
                n2 = self.conn.execute("SELECT label FROM nodes WHERE id=?", (path[i + 1],)).fetchone()
                l1 = n1["label"] if n1 else path[i]
                l2 = n2["label"] if n2 else path[i + 1]
                parts.append(f"{l1} —({lbl})→ {l2}")
            return "; ".join(parts)

        if strategy in ("shortest", "auto"):
            sp = self.bfs_shortest_path(seed_id, target_id)
            if sp and len(sp) <= max_hops + 1:
                edges = [_edge_label(sp[i], sp[i + 1]) for i in range(len(sp) - 1)]
                results.append({
                    "path": sp,
                    "edges": edges,
                    "score": round(1.0 / len(sp), 4),
                    "explanation": _verbalize(sp),
                    "source": "shortest",
                })

        if strategy == "pagerank_guided" or (strategy == "shortest" and not results):
            pr = self.pagerank(max_iter=20)
            max_pr = max(pr.values()) if pr else 1.0
            all_paths = self.find_paths(seed_id, target_id, max_hops)
            scored = []
            for p in all_paths[:top_k * 3]:
                mid_pr = sum(pr.get(nid, 0) for nid in p[1:-1]) / max(1, len(p) - 2)
                edges = [_edge_label(p[i], p[i + 1]) for i in range(len(p) - 1)]
                path_score = (mid_pr / max_pr) * 0.5 + (1.0 / len(p)) * 0.5
                scored.append({
                    "path": p,
                    "edges": edges,
                    "score": round(path_score, 4),
                    "explanation": _verbalize(p),
                    "source": "pagerank_guided",
                })
            scored.sort(key=lambda x: x["score"], reverse=True)
            results.extend(scored[:top_k])

        if strategy == "random_walk":
            import random as _rng
            for _ in range(top_k * 2):
                current = seed_id
                path = [seed_id]
                visited = {seed_id}
                for _hop in range(max_hops):
                    nbrs = self.conn.execute(
                        "SELECT target FROM edges WHERE source=? AND target NOT IN ({})"
                        .format(",".join("?" * len(visited))),
                        [current] + list(visited)).fetchall()
                    rev_nbrs = self.conn.execute(
                        "SELECT source FROM edges WHERE target=? AND source NOT IN ({})"
                        .format(",".join("?" * len(visited))),
                        [current] + list(visited)).fetchall()
                    candidates = [r[0] for r in nbrs] + [r[0] for r in rev_nbrs]
                    if not candidates:
                        break
                    nxt = _rng.choice(candidates)
                    path.append(nxt)
                    visited.add(nxt)
                    if nxt == target_id:
                        break
                    current = nxt
                if path[-1] == target_id:
                    edges = [_edge_label(path[i], path[i + 1]) for i in range(len(path) - 1)]
                    results.append({
                        "path": path,
                        "edges": edges,
                        "score": round(1.0 / len(path), 4),
                        "explanation": _verbalize(path),
                        "source": "random_walk",
                    })
            results.sort(key=lambda x: x["score"], reverse=True)
            results = results[:top_k]

        # Deduplicate by path tuple
        seen = set()
        unique = []
        for r in results:
            key = tuple(r["path"])
            if key not in seen:
                seen.add(key)
                unique.append(r)
        return unique[:top_k]

    def explore(self, seed_id: str, max_hops: int = 2, budget: int = 50,
                direction: str = "both", min_score: float = 0.1) -> dict:
        """自适应图探索 (GR-Agent agent-environment 交互模式).

        从 seed 出发, 受预算约束地探索邻域, 返回发现的节点+推理路径+统计.
        """
        if not self.has_node(seed_id):
            return {"discovered": [], "paths": [],
                    "stats": {"nodes_visited": 0, "edges_traversed": 0,
                              "hops_completed": 0, "budget_used": 0.0}}

        pr = self.pagerank(max_iter=15)
        max_pr = max(pr.values()) if pr else 1.0

        visited = {seed_id}
        queue = [(seed_id, 0, 1.0)]
        discovered = []
        paths = []
        edges_traversed = 0

        def _edge_info(s, t):
            r = self.conn.execute(
                "SELECT relation, weight FROM edges WHERE source=? AND target=? ORDER BY weight DESC LIMIT 1",
                (s, t)).fetchone()
            if r:
                return r["relation"], r["weight"]
            r = self.conn.execute(
                "SELECT relation, weight FROM edges WHERE source=? AND target=? ORDER BY weight DESC LIMIT 1",
                (t, s)).fetchone()
            if r:
                return r["relation"], r["weight"]
            return "related", 1.0

        def _trace_back(src, intermediate):
            sp = self.bfs_shortest_path(src, intermediate)
            return sp or [src, intermediate]

        while queue and len(visited) < budget:
            current, depth, _score = queue.pop(0)
            if depth >= max_hops:
                continue

            if direction == "out":
                nbr_rows = self.conn.execute(
                    "SELECT target AS nb FROM edges WHERE source=?", (current,)).fetchall()
            elif direction == "in":
                nbr_rows = self.conn.execute(
                    "SELECT source AS nb FROM edges WHERE target=?", (current,)).fetchall()
            else:
                nbr_rows = self.conn.execute(
                    "SELECT target AS nb FROM edges WHERE source=? "
                    "UNION SELECT source AS nb FROM edges WHERE target=?",
                    (current, current)).fetchall()

            edges_traversed += len(nbr_rows)
            for row in nbr_rows:
                nb_id = row["nb"]
                if nb_id in visited:
                    continue
                visited.add(nb_id)

                rel, ew = _edge_info(current, nb_id)
                pr_score = pr.get(nb_id, 0) / max_pr
                depth_decay = 1.0 / (1 + depth)
                score = pr_score * 0.4 + ew * 0.3 + depth_decay * 0.3

                if score < min_score:
                    continue

                nb_row = self.conn.execute(
                    "SELECT label FROM nodes WHERE id=?", (nb_id,)).fetchone()
                nb_label = nb_row["label"] if nb_row else nb_id

                discovered.append({
                    "id": nb_id,
                    "label": nb_label,
                    "score": round(score, 4),
                    "depth": depth + 1,
                })

                back = _trace_back(seed_id, current)
                full_path = back + [nb_id]
                paths.append({
                    "path": full_path,
                    "edges": [_edge_info(full_path[i], full_path[i + 1])[0]
                              for i in range(len(full_path) - 1)],
                    "score": round(score, 4),
                    "explanation": f"{seed_id} →({rel})→ {nb_label}",
                    "source": "pagerank_guided",
                })

                queue.append((nb_id, depth + 1, score))

        discovered.sort(key=lambda x: x["score"], reverse=True)
        paths.sort(key=lambda x: x["score"], reverse=True)

        return {
            "discovered": discovered[:budget],
            "paths": paths[:10],
            "stats": {
                "nodes_visited": len(visited),
                "edges_traversed": edges_traversed,
                "hops_completed": max_hops,
                "budget_used": round(len(visited) / budget, 4),
            },
        }

    def infer_relation(self, node_a: str, node_b: str,
                        max_hops: int = 3) -> dict | None:
        """不完整知识下的关系推断.

        组合 link prediction (Adamic-Adar + common neighbors) + path finding.
        返回 {relation, confidence, evidence, link_scores}.
        """
        if not self.has_node(node_a) or not self.has_node(node_b):
            return None

        def _edge_label(s, t):
            r = self.conn.execute(
                "SELECT relation FROM edges WHERE source=? AND target=? ORDER BY weight DESC LIMIT 1",
                (s, t)).fetchone()
            if r:
                return r["relation"]
            r = self.conn.execute(
                "SELECT relation FROM edges WHERE source=? AND target=? ORDER BY weight DESC LIMIT 1",
                (t, s)).fetchone()
            return r["relation"] if r else "related"

        # Step 1: Direct edge check
        direct = self.conn.execute(
            "SELECT relation, weight FROM edges WHERE source=? AND target=? "
            "UNION SELECT relation, weight FROM edges WHERE source=? AND target=?",
            (node_a, node_b, node_b, node_a)).fetchone()
        if direct:
            return {
                "relation": direct["relation"],
                "confidence": 1.0,
                "evidence": [{
                    "path": [node_a, node_b],
                    "edges": [direct["relation"]],
                    "score": 1.0,
                    "explanation": f"Direct edge: {node_a} —({direct['relation']})→ {node_b}",
                    "source": "direct",
                }],
                "link_scores": {
                    "adamic_adar": 0.0,
                    "common_neighbors": 0,
                    "preferential_attachment": 0,
                },
            }

        # Step 2: Find indirect paths (reasoning evidence)
        paths = self.reasoning_path(node_a, node_b, max_hops=max_hops, top_k=3)

        # Step 3: Link prediction scores
        common = self.common_neighbors(node_a, node_b)
        deg_a = self.conn.execute(
            "SELECT COUNT(*) c FROM edges WHERE source=? OR target=?",
            (node_a, node_a)).fetchone()["c"]
        deg_b = self.conn.execute(
            "SELECT COUNT(*) c FROM edges WHERE source=? OR target=?",
            (node_b, node_b)).fetchone()["c"]

        aa_score = 0.0
        for cn in common:
            deg_cn = self.conn.execute(
                "SELECT COUNT(*) c FROM edges WHERE source=? OR target=?",
                (cn, cn)).fetchone()["c"]
            aa_score += 1.0 / math.log(max(deg_cn, 2))

        if not paths:
            # No path found, return link prediction only
            return {
                "relation": "unknown",
                "confidence": round(min(aa_score / 3.0, 0.3), 4),
                "evidence": [],
                "link_scores": {
                    "adamic_adar": round(aa_score, 4),
                    "common_neighbors": len(common),
                    "preferential_attachment": deg_a * deg_b,
                },
            }

        best = paths[0]
        inferred_rel = " → ".join(best["edges"])
        confidence = best["score"] * 0.7 + min(aa_score / 3.0, 0.3) * 0.3

        return {
            "relation": inferred_rel,
            "confidence": round(confidence, 4),
            "evidence": paths,
            "link_scores": {
                "adamic_adar": round(aa_score, 4),
                "common_neighbors": len(common),
                "preferential_attachment": deg_a * deg_b,
            },
        }

    def reasoning_subgraph(self, query: str = None, seed_ids: list[str] = None,
                             max_hops: int = 2, top_k: int = 20) -> dict:
        """查询相关的推理子图.

        从 BM25 搜索或指定种子节点出发, 构建完整推理子图.
        返回 {nodes, edges, paths, summary}.
        """
        if seed_ids is None:
            seed_ids = []

        if query and not seed_ids:
            results = self.search_bm25(query, limit=5)
            seed_ids = [r.get("id") or r.get("node_id") for r in results if r.get("id") or r.get("node_id")]

        # Filter to valid seeds
        seed_ids = [s for s in seed_ids if self.has_node(s)]
        if not seed_ids:
            return {"nodes": [], "edges": [], "paths": [], "summary": "no seed nodes found"}

        # BFS expand from seeds
        sub_nodes = set(seed_ids)
        sub_edges = []
        frontier = list(seed_ids)

        for hop in range(max_hops):
            next_frontier = []
            for nid in frontier:
                rows = self.conn.execute(
                    "SELECT target AS nb, relation, weight FROM edges WHERE source=? "
                    "UNION SELECT source AS nb, relation, weight FROM edges WHERE target=?",
                    (nid, nid)).fetchall()
                for r in rows:
                    nb = r["nb"]
                    edge = {
                        "source": nid, "target": nb,
                        "relation": r["relation"], "weight": r["weight"],
                    }
                    edge_key = (edge["source"], edge["target"], edge["relation"])
                    if not any(e.get("_key") == edge_key for e in sub_edges):
                        edge["_key"] = edge_key
                        sub_edges.append(edge)
                    if nb not in sub_nodes:
                        sub_nodes.add(nb)
                        if len(sub_nodes) < top_k * 2:
                            next_frontier.append(nb)
            frontier = next_frontier
            if not frontier:
                break

        # Build node list with labels
        node_list = []
        for nid in sub_nodes:
            row = self.conn.execute(
                "SELECT label, kind, weight FROM nodes WHERE id=?", (nid,)).fetchone()
            if row:
                node_list.append({
                    "id": nid, "label": row["label"],
                    "kind": row["kind"], "weight": row["weight"],
                })

        # Clean edges
        clean_edges = [{k: v for k, v in e.items() if k != "_key"} for e in sub_edges]

        # Build reasoning paths between seeds
        paths = []
        for i, s1 in enumerate(seed_ids):
            for s2 in seed_ids[i + 1:]:
                rp = self.reasoning_path(s1, s2, max_hops=max_hops, top_k=2)
                paths.extend(rp)

        # PageRank for node importance within subgraph
        pr = self.pagerank(max_iter=15)
        for n in node_list:
            n["importance"] = round(pr.get(n["id"], 0), 6)
        node_list.sort(key=lambda x: x["importance"], reverse=True)

        summary = (f"Subgraph with {len(node_list)} nodes, {len(clean_edges)} edges, "
                   f"{len(paths)} reasoning paths from {len(seed_ids)} seeds")

        return {
            "nodes": node_list[:top_k],
            "edges": clean_edges,
            "paths": paths,
            "summary": summary,
        }

    # ── Adaptive Retrieval APIs (Test-Time Scaling inspired) ─────────────

    def classify_query(self, query: str) -> dict:
        """查询复杂度分类 (Adaptive-RAG NAACL 2024 / AHR 4-tier).

        将查询分为 simple / moderate / complex / multi_hop,
        用于路由到不同检索管道。

        启发式规则, 零 LLM 调用。
        """
        import re
        q_lower = query.lower().strip()
        words = q_lower.split()
        word_count = len(words)

        multi_hop_indicators = [
            r'how.*relate', r'compare.*and', r'difference',
            r'between.*and', r'because', r'why.*then',
            r'cause', r'effect', r'impact', r'result',
            r'chain', r'sequence', r'flow',
        ]
        complex_indicators = [
            r'how', r'why', r'explain', r'analyze',
            r'design', r'architecture', r'trade.?off',
        ]

        multi_hop_score = sum(1 for p in multi_hop_indicators if re.search(p, q_lower))
        complex_score = sum(1 for p in complex_indicators if re.search(p, q_lower))

        reasoning = []
        if multi_hop_score >= 2 or (multi_hop_score >= 1 and word_count > 12):
            level = "multi_hop"
            reasoning.append(f"multi_hop_score={multi_hop_score}, words={word_count}")
        elif complex_score >= 1 and word_count >= 7:
            level = "complex"
            reasoning.append(f"complex_score={complex_score}, words={word_count}")
        elif word_count > 6:
            level = "moderate"
            reasoning.append(f"words={word_count} (>8, no complex indicators)")
        else:
            level = "simple"
            reasoning.append(f"words={word_count} (<=8, no complex indicators)")

        # Effort level mapping
        effort_map = {"simple": "low", "moderate": "medium",
                      "complex": "high", "multi_hop": "max"}
        # Strategy mapping
        strategy_map = {"simple": "bm25_only", "moderate": "bm25+vector",
                        "complex": "hybrid+graph", "multi_hop": "graph_reasoning"}

        return {
            "complexity": level,
            "effort": effort_map[level],
            "strategy": strategy_map[level],
            "word_count": word_count,
            "multi_hop_score": multi_hop_score,
            "complex_score": complex_score,
            "reasoning": "; ".join(reasoning),
            # QDAP-v2 enrichment: include fusion-relevant type for cross-reference
            "qdap_type": MemoryGraph._classify_query(query).get("type", "semantic"),
        }

    def grade_retrieval(self, query: str, results: list[dict],
                         threshold: float = 0.15) -> dict:
        """检索结果质量评分 (CRAG-inspired Correct/Ambiguous/Incorrect).

        不需要 LLM — 用分数分布 + 图连通性做评估。

        返回 {grade, relevant_count, scores, recommendation}.
        """
        if not results:
            return {
                "grade": "incorrect",
                "relevant_count": 0,
                "scores": {"avg": 0, "max": 0, "gap": 0},
                "recommendation": "retrieval_failed",
            }

        scores = [r.get("score", 0) for r in results]
        avg_score = sum(scores) / len(scores)
        max_score = max(scores)
        min_score = min(scores)
        score_gap = max_score - min_score

        # Count relevant results (above threshold)
        relevant = [r for r in results if r.get("score", 0) >= threshold]
        relevant_count = len(relevant)

        # Check graph connectivity among top results (if >1 result)
        connectivity = 0.0
        if len(results) > 1:
            top_ids = [r.get("id") or r.get("node_id") for r in results[:5]]
            top_ids = [t for t in top_ids if t]
            if len(top_ids) > 1:
                connected_pairs = 0
                total_pairs = 0
                for i, a in enumerate(top_ids):
                    for b in top_ids[i + 1:]:
                        total_pairs += 1
                        cn = self.common_neighbors(a, b)
                        if cn or self.conn.execute(
                            "SELECT 1 FROM edges WHERE source=? AND target=? "
                            "UNION SELECT 1 FROM edges WHERE source=? AND target=?",
                            (a, b, b, a)).fetchone():
                            connected_pairs += 1
                connectivity = connected_pairs / total_pairs if total_pairs else 0

        # CRAG-style grading
        if relevant_count >= 2 and avg_score >= threshold * 2:
            grade = "relevant"
            recommendation = "use_results"
        elif relevant_count == 0 and avg_score < threshold:
            grade = "incorrect"
            recommendation = "retry_with_graph_or_web"
        else:
            grade = "ambiguous"
            if connectivity > 0.3:
                recommendation = "use_top_k_and_expand_graph"
            else:
                recommendation = "use_top_k_and_rerank"

        return {
            "grade": grade,
            "relevant_count": relevant_count,
            "connectivity": round(connectivity, 4),
            "scores": {
                "avg": round(avg_score, 6),
                "max": round(max_score, 6),
                "min": round(min_score, 6),
                "gap": round(score_gap, 6),
            },
            "recommendation": recommendation,
        }

    def search_adaptive(self, query: str, embedding: list[float] = None,
                         limit: int = 10) -> dict:
        """自适应检索 — 根据查询复杂度路由到不同检索管道.

        Pipeline: classify_query → route → execute → grade_retrieval → (optional) expand

        Returns {results, classification, grade, strategy}.
        """
        classification = self.classify_query(query)

        # Trivial queries skip retrieval entirely
        qdap = self._classify_query(query, [r[0] for r in self.conn.execute(
            "SELECT DISTINCT label FROM nodes LIMIT 200").fetchall()])
        if not qdap.get("needs_retrieval", True):
            return {
                "results": [],
                "classification": classification,
                "grade": {"grade": "trivial", "relevant_count": 0,
                           "scores": {"avg": 0, "max": 0, "gap": 0},
                           "recommendation": "no_retrieval_needed"},
                "strategy": "skip",
                "query_type": qdap["type"],
            }

        strategy = classification["strategy"]

        # Execute based on strategy
        if strategy == "bm25_only":
            raw = self.search_bm25(query, limit=limit)
            results = [{"id": r.get("node_id", r.get("id")),
                        "label": r.get("label"),
                        "score": r.get("score", 0)} for r in raw]
        elif strategy in ("bm25+vector", "hybrid+graph") and embedding:
            raw = self.search_hybrid(query, embedding=embedding, limit=limit)
            results = [{"id": r.get("node_id", r.get("id")),
                        "label": r.get("label"),
                        "score": r.get("score", 0)} for r in raw]
        elif strategy == "graph_reasoning":
            # Multi-hop: BM25 seed → graph reasoning expand
            # FTS5 uses implicit AND, so use OR for broader seed coverage
            import re as _re
            terms = _re.findall(r'\b[a-zA-Z_]{3,}\b', query)
            # Filter out common stop words
            stop_words = {'the', 'and', 'how', 'what', 'why', 'for', 'they',
                          'are', 'was', 'were', 'been', 'have', 'has', 'had',
                          'that', 'this', 'with', 'from', 'into', 'their',
                          'them', 'then', 'there', 'these', 'those', 'than',
                          'but', 'not', 'nor', 'yet', 'both', 'each', 'all',
                          'any', 'some', 'most', 'none', 'one', 'two', 'three',
                          'first', 'second', 'other', 'another', 'same',
                          'different', 'between', 'compare', 'relate', 'relates'}
            meaningful = [t for t in terms if t.lower() not in stop_words]
            if meaningful:
                fts_query = " OR ".join(meaningful[:5])
            else:
                fts_query = query
            raw = self.search_bm25(fts_query, limit=5)
            seed_ids = [r.get("node_id", r.get("id")) for r in raw]
            seed_ids = [s for s in seed_ids if s]
            if seed_ids:
                sub = self.reasoning_subgraph(seed_ids=seed_ids, max_hops=2, top_k=limit)
                results = [{"id": n["id"], "label": n["label"],
                            "score": n.get("importance", 0)} for n in sub["nodes"]]
            else:
                results = []
        else:
            # Fallback: BM25
            raw = self.search_bm25(query, limit=limit)
            results = [{"id": r.get("node_id", r.get("id")),
                        "label": r.get("label"),
                        "score": r.get("score", 0)} for r in raw]

        # Grade the retrieval
        grade = self.grade_retrieval(query, results)

        # If ambiguous and graph expansion is recommended
        if grade["grade"] == "ambiguous" and "expand" in grade["recommendation"]:
            top_ids = [r["id"] for r in results[:3] if r.get("id")]
            if top_ids:
                expanded = self.explore(top_ids[0], max_hops=1, budget=10)
                for d in expanded["discovered"][:3]:
                    if d["id"] not in {r["id"] for r in results}:
                        results.append({
                            "id": d["id"],
                            "label": d["label"],
                            "score": d["score"],
                            "source": "graph_expansion",
                        })

        return {
            "results": results[:limit],
            "classification": classification,
            "grade": grade,
            "strategy": strategy,
        }

    # ── Evidence-Gap Tracker (MemR³ inspired) ────────────────────

    def search_with_gaps(self, query: str, results: list[dict] = None,
                          limit: int = 10) -> dict:
        """证据缺口追踪 — 识别检索结果中缺失的多跳推理环节.

        MemR³ (arXiv:2512.20237) 核心洞察: 多跳推理失败不是因为检索不到,
        而是因为中间实体/关系缺失. Evidence-Gap Tracker 提取查询实体,
        检查它们在结果中的覆盖, 并发现缺失的连接路径.

        零 LLM 调用 — 纯图结构 + BM25 实体匹配.

        Returns:
            {
                "entities": [{"entity": str, "covered": bool, "node_ids": [...]}],
                "gaps": [{"gap": str, "missing_entities": [...], "suggestion": str}],
                "gap_score": float (0=no gaps, 1=all gaps),
                "repair_strategy": "none" | "expand_neighbors" | "bridge_search",
            }
        """
        import re

        # Step 1: Extract entities from query (simple NER — noun-like tokens)
        stop_words = {
            'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been',
            'how', 'what', 'why', 'when', 'where', 'who', 'which',
            'and', 'or', 'but', 'not', 'nor', 'yet', 'so',
            'for', 'to', 'of', 'in', 'on', 'at', 'by', 'with',
            'from', 'into', 'about', 'between', 'through',
            'this', 'that', 'these', 'those',
            'do', 'does', 'did', 'has', 'have', 'had',
            'will', 'would', 'could', 'should', 'may', 'might',
            'compare', 'relate', 'relation', 'relationship',
            'difference', 'similar', 'same',
        }
        tokens = re.findall(r'\b[a-zA-Z_][a-zA-Z_]{2,}\b', query.lower())
        entities = [t for t in tokens if t not in stop_words]
        # Deduplicate while preserving order
        seen = set()
        entities = [e for e in entities if not (e in seen or seen.add(e))]
        entities = entities[:8]  # cap at 8 entities

        # Step 2: Check coverage of each entity in results
        if results is None:
            raw = self.search_bm25(query, limit=limit)
            results = [{"id": r.get("node_id", r.get("id")),
                        "label": r.get("label", ""),
                        "score": r.get("score", 0),
                        "tags": r.get("tags", [])} for r in raw]

        result_labels = " ".join(r.get("label", "").lower() for r in results)
        result_ids = set(r.get("id") for r in results if r.get("id"))

        entity_coverage = []
        for ent in entities:
            # Check if entity appears in any result label
            in_labels = ent in result_labels
            # Check if any node in graph matches this entity
            matching_nodes = self.conn.execute(
                "SELECT id FROM nodes WHERE LOWER(label) LIKE ? AND quarantined = 0",
                (f"%{ent}%",)
            ).fetchall()
            matching_ids = [row["id"] for row in matching_nodes]
            covered = in_labels or len(matching_ids) > 0
            entity_coverage.append({
                "entity": ent,
                "covered": covered,
                "in_results": in_labels,
                "node_ids": matching_ids[:5],
            })

        # Step 3: Find gaps — uncovered entities
        uncovered = [e for e in entity_coverage if not e["covered"]]
        covered_with_nodes = [e for e in entity_coverage
                              if e["covered"] and e["node_ids"]]

        gaps = []
        for unc in uncovered:
            # Try to find a bridge from covered entities to uncovered
            suggestion = "no_path"
            bridge_target = None
            for cov in covered_with_nodes:
                for cov_id in cov["node_ids"][:2]:
                    nbrs = self.neighbors(cov_id, depth=2)
                    for nbr in nbrs:
                        if unc["entity"] in nbr.label.lower():
                            bridge_target = nbr.id
                            suggestion = "bridge_found"
                            break
                    if bridge_target:
                        break
                if bridge_target:
                    break

            gaps.append({
                "gap": f"missing_entity: {unc['entity']}",
                "missing_entities": [unc["entity"]],
                "suggestion": suggestion,
                "bridge_node": bridge_target,
            })

        # Step 4: Check connectivity among covered entities (missing links)
        if len(covered_with_nodes) >= 2:
            for i, a in enumerate(covered_with_nodes[:4]):
                for b in covered_with_nodes[i + 1:4]:
                    # Check if there's any path between them
                    a_ids = a["node_ids"][:1]
                    b_ids = b["node_ids"][:1]
                    for aid in a_ids:
                        for bid in b_ids:
                            path = self.shortest_path(aid, bid)
                            if path is None:
                                gaps.append({
                                    "gap": f"no_path: {a['entity']} → {b['entity']}",
                                    "missing_entities": [a["entity"], b["entity"]],
                                    "suggestion": "bridge_search",
                                    "bridge_node": None,
                                })

        # Step 5: Compute gap score and repair strategy
        total_entities = len(entities) if entities else 1
        gap_score = len(uncovered) / total_entities

        if gap_score == 0 and not gaps:
            repair_strategy = "none"
        elif any(g["suggestion"] == "bridge_found" for g in gaps):
            repair_strategy = "expand_neighbors"
        else:
            repair_strategy = "bridge_search"

        return {
            "entities": entity_coverage,
            "gaps": gaps,
            "gap_score": round(gap_score, 4),
            "repair_strategy": repair_strategy,
            "entity_count": len(entities),
            "covered_count": len(entities) - len(uncovered),
        }

    # ── Admission Controller (A-MAC ICLR 2026 inspired) ─────────

    def should_admit(self, candidate_node_id: str = None, label: str = None,
                     kind: str = None, data: dict = None, tags: list[str] = None,
                     conflict_check: bool = True) -> dict:
        """记忆准入控制 — A-MAC 5-factor admission scoring.

        A-MAC (ICLR 2026 Workshop, arXiv:2603.04549) defines 5 factors for
        deciding whether new information should be admitted to memory:

        - **U**niqueness: How different from existing nodes? (trigram overlap)
        - **C**onflict: Does it contradict existing knowledge? (label/kind clash)
        - **N**ovelty: Does it bring new tags or connections? (tag set diff)
        - **R**elevance: How connected to existing graph? (neighbor overlap)
        - **T**imeliness: Is it temporally relevant? (recency factor)

        Returns: {admit: bool, score: float, factors: {U,C,N,R,T},
                  reason: str, conflicts: [...]}

        Zero LLM — pure heuristics on the graph structure.
        """
        # If node already exists, evaluate it; otherwise evaluate hypothetical
        if candidate_node_id and self.has_node(candidate_node_id):
            node = self.get_node(candidate_node_id)
            label = node.label
            kind = node.kind
            data = node.data
            tags_existing = self.conn.execute(
                "SELECT tags FROM nodes WHERE id = ?", (candidate_node_id,)
            ).fetchone()
            import json as _json
            tags = _json.loads(tags_existing["tags"]) if tags_existing and tags_existing["tags"] else []
        elif label is None:
            return {
                "admit": False,
                "score": 0.0,
                "factors": {"U": 0, "C": 0, "N": 0, "R": 0, "T": 0},
                "reason": "no_label_provided",
                "conflicts": [],
            }

        label_lower = label.lower()
        label_words = set(label_lower.split())

        # Factor 1: Uniqueness (U) — trigram overlap with existing nodes
        def _trigrams(text: str) -> set:
            chars = text.lower().replace(" ", "")
            return {chars[i:i + 3] for i in range(len(chars) - 2)} if len(chars) > 2 else {chars}

        cand_trigrams = _trigrams(label)
        all_nodes = self.conn.execute(
            "SELECT id, label FROM nodes WHERE quarantined = 0"
        ).fetchall()

        if all_nodes:
            max_overlap = 0.0
            most_similar = None
            for row in all_nodes:
                existing_trigrams = _trigrams(row["label"])
                if existing_trigrams:
                    overlap = len(cand_trigrams & existing_trigrams) / len(
                        cand_trigrams | existing_trigrams)
                    if overlap > max_overlap:
                        max_overlap = overlap
                        most_similar = row["label"]
            uniqueness = round(1.0 - max_overlap, 4)
        else:
            uniqueness = 1.0
            max_overlap = 0.0
            most_similar = None

        # Factor 2: Conflict (C) — does same-kind node with high label similarity exist?
        conflicts = []
        if conflict_check and kind:
            same_kind = [row for row in all_nodes if row["label"]]
            for row in same_kind:
                existing_label = row["label"]
                if label_lower == existing_label.lower():
                    conflicts.append({
                        "node_id": row["id"],
                        "label": existing_label,
                        "type": "exact_duplicate",
                    })
                else:
                    existing_words = set(existing_label.lower().split())
                    word_overlap = len(label_words & existing_words) / max(
                        len(label_words | existing_words), 1)
                    if word_overlap >= 0.5 and word_overlap < 1.0:
                        conflicts.append({
                            "node_id": row["id"],
                            "label": existing_label,
                            "type": "potential_conflict",
                            "similarity": round(word_overlap, 4),
                        })
        # Conflict score: exact dups penalize heavily, potential conflicts lightly
        exact_dups = sum(1 for c in conflicts if c["type"] == "exact_duplicate")
        potential_dups = sum(1 for c in conflicts if c["type"] == "potential_conflict")
        conflict_score = max(0.0, 1.0 - 0.5 * exact_dups - 0.1 * potential_dups)

        # Factor 3: Novelty (N) — new tags not in current tag vocabulary
        existing_tags = set()
        tag_rows = self.conn.execute("SELECT tags FROM nodes WHERE tags != '[]'").fetchall()
        for tr in tag_rows:
            import json as _j
            try:
                existing_tags.update(_j.loads(tr["tags"]))
            except Exception:
                pass
        new_tags = set(tags) - existing_tags if tags else set()
        novelty = round(len(new_tags) / max(len(tags), 1), 4) if tags else 0.5

        # Factor 4: Relevance (R) — how connected would this be?
        # Check if any existing node shares words/tags with candidate
        relevant_neighbors = 0
        if label_words:
            for row in all_nodes:
                row_words = set(row["label"].lower().split())
                if label_words & row_words:
                    relevant_neighbors += 1
        if tags:
            for tag in tags:
                tagged = self.search_by_tag(tag)
                relevant_neighbors += len(tagged)
        # Normalize: sigmoid-like (3 matching nodes → 0.6 relevance)
        relevance = round(min(1.0, relevant_neighbors / 5.0), 4)

        # Factor 5: Timeliness (T) — always 1.0 for new nodes (just created)
        timeliness = 1.0

        # Weighted admission score: U*0.25 + C*0.20 + N*0.15 + R*0.25 + T*0.15
        weights = {"U": 0.25, "C": 0.20, "N": 0.15, "R": 0.25, "T": 0.15}
        factors = {"U": uniqueness, "C": conflict_score,
                   "N": novelty, "R": relevance, "T": timeliness}
        score = round(sum(weights[k] * factors[k] for k in weights), 4)

        # Decision logic (conflicts checked before score)
        has_exact_dup = any(c["type"] == "exact_duplicate" for c in conflicts)
        if has_exact_dup:
            admit = False
            reason = "exact_duplicate_exists"
        elif len(conflicts) > 3:
            admit = False
            reason = "too_many_conflicts"
        elif score >= 0.5:
            admit = True
            reason = "above_threshold"
        elif uniqueness < 0.30 and relevance > 0.3:
            admit = True
            reason = "complementary_to_existing"
        else:
            admit = False
            reason = "below_threshold"

        return {
            "admit": admit,
            "score": score,
            "factors": factors,
            "weights": weights,
            "reason": reason,
            "conflicts": conflicts[:5],
            "most_similar": most_similar,
            "max_similarity": round(max_overlap, 4),
            "new_tags": sorted(new_tags) if new_tags else [],
            "relevant_neighbor_count": relevant_neighbors,
        }

    # ── Memory Lifecycle Report ─────────────────────────────────────

    def memory_lifecycle_report(self) -> dict:
        """Unified memory lifecycle dashboard.

        Combines access recency, weight distribution, decay status,
        consolidation state, quarantine health, and reinforcement
        activity into a single executive report.

        Returns:
            {total_nodes, active_nodes, stale_nodes, decaying_nodes,
             avg_weight, weight_distribution, quarantine_count,
             consolidated_count, reinforcement_events,
             lifecycle_stage, recommendations}
        """
        stats = self.stats()
        total = stats.get("nodes", 0)

        if total == 0:
            return {
                "total_nodes": 0,
                "lifecycle_stage": "empty",
                "recommendations": ["seed_initial_memories"],
            }

        now = time.time()

        # Access recency tiers
        rows = self.conn.execute(
            "SELECT id, weight, accessed, quarantined, data FROM nodes"
        ).fetchall()

        active_threshold = 3600 * 24 * 7  # 7 days
        stale_threshold = 3600 * 24 * 30  # 30 days

        active = stale = decaying = dormant = 0
        weights = []
        quarantined_count = 0
        consolidated_count = 0
        reinforcement_count = 0

        for row in rows:
            age = now - (row["accessed"] or now)
            weights.append(row["weight"] or 0.0)

            if row["quarantined"]:
                quarantined_count += 1

            if age < active_threshold:
                active += 1
            elif age < stale_threshold:
                stale += 1
            elif age < stale_threshold * 3:  # 90 days
                decaying += 1
            else:
                dormant += 1

            # Check consolidation/reinforcement in data
            try:
                data = json.loads(row["data"]) if isinstance(row["data"], str) else row["data"]
                if isinstance(data, dict):
                    if data.get("_consolidated"):
                        consolidated_count += 1
                    rh = data.get("_reinforcement_history", [])
                    if rh:
                        reinforcement_count += len(rh)
            except Exception:
                pass

        avg_weight = sum(weights) / len(weights) if weights else 0.0

        # Weight distribution buckets
        buckets = {"critical (<0.1)": 0, "low (0.1-0.3)": 0,
                   "medium (0.3-0.6)": 0, "high (0.6-0.9)": 0,
                   "peak (>=0.9)": 0}
        for w in weights:
            if w < 0.1:
                buckets["critical (<0.1)"] += 1
            elif w < 0.3:
                buckets["low (0.1-0.3)"] += 1
            elif w < 0.6:
                buckets["medium (0.3-0.6)"] += 1
            elif w < 0.9:
                buckets["high (0.6-0.9)"] += 1
            else:
                buckets["peak (>=0.9)"] += 1

        # Determine lifecycle stage
        active_ratio = active / total
        if total < 10:
            stage = "seed"
        elif active_ratio > 0.6 and avg_weight > 0.3:
            stage = "thriving"
        elif active_ratio > 0.3:
            stage = "active"
        elif dormant > active:
            stage = "declining"
        else:
            stage = "maintenance"

        # Build recommendations
        recs = []
        if quarantined_count > total * 0.1:
            recs.append("review_quarantine_backlog")
        if dormant > total * 0.3:
            recs.append("prune_dormant_memories")
        if avg_weight < 0.1:
            recs.append("reinforce_key_memories")
        if reinforcement_count == 0:
            recs.append("start_reinforcement_tracking")
        if consolidated_count == 0 and total > 50:
            recs.append("run_consolidation_pipeline")
        if not recs:
            recs.append("healthy")

        return {
            "total_nodes": total,
            "active_nodes": active,
            "stale_nodes": stale,
            "decaying_nodes": decaying,
            "dormant_nodes": dormant,
            "avg_weight": round(avg_weight, 4),
            "weight_distribution": buckets,
            "quarantine_count": quarantined_count,
            "consolidated_count": consolidated_count,
            "reinforcement_events": reinforcement_count,
            "lifecycle_stage": stage,
            "recommendations": recs,
        }

    # ── Memory Access Pattern Analysis ──────────────────────────────

    def memory_access_pattern(self, *, days: int = 30) -> dict:
        """Analyse temporal access patterns of memory nodes.

        Groups nodes by kind, identifies access hotspots (frequently
        accessed) and cold spots (never/rarely accessed), computes
        access velocity (accesses per day), and detects diurnal
        bias (are memories accessed more at certain hours?).

        Args:
            days: look-back window for pattern analysis (default 30)

        Returns:
            {window_days, total_nodes, hot_nodes, cold_nodes,
             access_velocity, diurnal_bias, kind_temperature,
             recommendations}
        """
        now = time.time()
        cutoff = now - (days * 86400)

        rows = self.conn.execute(
            "SELECT id, label, kind, accessed, created FROM nodes WHERE quarantined = 0"
        ).fetchall()

        total = len(rows)
        if total == 0:
            return {
                "window_days": days,
                "total_nodes": 0,
                "recommendations": ["empty_store"],
            }

        hot = []
        cold = []
        kind_access = {}

        for row in rows:
            kind = row["kind"] or "unknown"
            accessed = row["accessed"] or row["created"] or now
            created = row["created"] or now

            if kind not in kind_access:
                kind_access[kind] = {"total": 0, "hot": 0, "cold": 0}
            kind_access[kind]["total"] += 1

            if accessed >= cutoff:
                hot.append({"id": row["id"], "label": row["label"], "kind": kind})
                kind_access[kind]["hot"] += 1
            elif created < cutoff:
                cold.append({"id": row["id"], "label": row["label"], "kind": kind,
                             "days_idle": round((now - accessed) / 86400, 1)})
                kind_access[kind]["cold"] += 1

        velocity = round(len(hot) / max(days * total, 1), 4)

        # Diurnal bias: hour-of-day distribution
        hour_counts = [0] * 24
        for row in rows:
            accessed = row["accessed"] or row["created"] or now
            if accessed >= cutoff:
                dt_hour = int((accessed % 86400) // 3600)
                hour_counts[dt_hour] += 1

        total_hour_accesses = sum(hour_counts)
        if total_hour_accesses > 0:
            peak_hour = hour_counts.index(max(hour_counts))
            peak_ratio = round(max(hour_counts) / total_hour_accesses, 4)
            diurnal_bias = peak_ratio > 0.2
        else:
            peak_hour = None
            peak_ratio = 0.0
            diurnal_bias = False

        # Kind temperature classification
        kind_temp = {}
        for kind, counts in kind_access.items():
            if counts["total"] > 0:
                ratio = round(counts["hot"] / counts["total"], 4)
                if ratio >= 0.7:
                    temp = "hot"
                elif ratio >= 0.3:
                    temp = "warm"
                else:
                    temp = "cold"
                kind_temp[kind] = {
                    "temperature": temp,
                    "hot_ratio": ratio,
                    "total": counts["total"],
                    "hot": counts["hot"],
                    "cold": counts["cold"],
                }

        recs = []
        cold_ratio = len(cold) / total if total > 0 else 0
        if cold_ratio > 0.5:
            recs.append("high_cold_ratio")
        if velocity < 0.01:
            recs.append("low_access_velocity")
        if diurnal_bias:
            recs.append("diurnal_bias_detected")
        fully_cold_kinds = [k for k, v in kind_temp.items() if v["temperature"] == "cold"]
        if fully_cold_kinds:
            recs.append("review_cold_kinds:" + ",".join(fully_cold_kinds[:3]))
        if not recs:
            recs.append("balanced_access")

        return {
            "window_days": days,
            "total_nodes": total,
            "hot_nodes": len(hot),
            "cold_nodes": len(cold),
            "hot_examples": hot[:5],
            "cold_examples": sorted(cold, key=lambda x: x["days_idle"], reverse=True)[:5],
            "access_velocity": velocity,
            "diurnal_bias": diurnal_bias,
            "peak_hour": peak_hour,
            "peak_hour_ratio": peak_ratio,
            "kind_temperature": kind_temp,
            "recommendations": recs,
        }

    # ── Memory Health Score ──────────────────────────────────────────

    def memory_health_score(self) -> dict:
        """Single composite health score (0–100) for the memory store.

        Combines five dimensions into one executive KPI:
        1. Vitality (30): are nodes active and weighted?
        2. Integrity (20): quarantine ratio, exact duplicates
        3. Connectivity (20): graph density, isolation rate
        4. Diversity (15): kind distribution evenness
        5. Maintenance (15): consolidation, reinforcement tracking

        Returns:
            {score, grade, dimensions, issues, trends}
        """
        stats = self.stats()
        total = stats.get("nodes", 0)

        if total == 0:
            return {"score": 0, "grade": "N/A",
                    "issues": ["empty_store"], "dimensions": {}}

        rows = self.conn.execute(
            "SELECT id, kind, weight, accessed, quarantined, data FROM nodes"
        ).fetchall()

        # 1. Vitality (0-30): avg weight * active ratio
        now = time.time()
        week_ago = now - 86400 * 7
        weights = [r["weight"] or 0.0 for r in rows]
        avg_weight = sum(weights) / len(weights) if weights else 0.0
        active = sum(1 for r in rows if (r["accessed"] or 0) >= week_ago)
        active_ratio = active / total
        vitality = round(min(30.0, (avg_weight * 0.5 + active_ratio * 0.5) * 30.0), 1)

        # 2. Integrity (0-20): penalize quarantine and low trust
        quarantined = sum(1 for r in rows if r["quarantined"])
        q_ratio = quarantined / total
        integrity = round(max(0.0, 20.0 * (1.0 - q_ratio * 5.0)), 1)

        # 3. Connectivity (0-20): edge coverage
        edge_count = self.conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
        max_edges = total * (total - 1)
        density = (2 * edge_count / max_edges) if max_edges > 0 else 0.0
        # Nodes with at least 1 edge
        connected = self.conn.execute(
            "SELECT COUNT(DISTINCT source) FROM edges UNION SELECT COUNT(DISTINCT target) FROM edges"
        ).fetchall()
        sources = self.conn.execute("SELECT COUNT(DISTINCT source) FROM edges").fetchone()[0]
        targets = self.conn.execute("SELECT COUNT(DISTINCT target) FROM edges").fetchone()[0]
        involved = len(set(r["id"] for r in rows if r["id"] in [
            row[0] for row in self.conn.execute("SELECT source FROM edges").fetchall()
        ] or []))
        isolation_rate = 1.0 - min(1.0, (sources + targets) / (2 * total)) if total > 0 else 1.0
        connectivity = round(min(20.0, (1.0 - isolation_rate) * 15.0 + density * 100.0), 1)

        # 4. Diversity (0-15): kind distribution evenness (Shannon entropy)
        kind_counts = {}
        for r in rows:
            k = r["kind"] or "unknown"
            kind_counts[k] = kind_counts.get(k, 0) + 1
        if len(kind_counts) > 1:
            import math as _m
            entropy = -sum((c / total) * _m.log2(c / total) for c in kind_counts.values())
            max_entropy = _m.log2(len(kind_counts))
            evenness = entropy / max_entropy if max_entropy > 0 else 0.0
        else:
            evenness = 0.0
        diversity = round(evenness * 15.0, 1)

        # 5. Maintenance (0-15): consolidation + reinforcement
        consolidated = 0
        reinforced = 0
        for r in rows:
            try:
                data = json.loads(r["data"]) if isinstance(r["data"], str) else r["data"]
                if isinstance(data, dict):
                    if data.get("_consolidated"):
                        consolidated += 1
                    if data.get("_reinforcement_history"):
                        reinforced += 1
            except Exception:
                pass
        maintenance_score = 0.0
        if total > 0:
            maintenance_score = min(15.0, (consolidated / total * 7.5) + (reinforced / total * 7.5))
        maintenance = round(maintenance_score, 1)

        score = round(vitality + integrity + connectivity + diversity + maintenance, 1)

        # Grade
        if score >= 80:
            grade = "A"
        elif score >= 65:
            grade = "B"
        elif score >= 50:
            grade = "C"
        elif score >= 35:
            grade = "D"
        else:
            grade = "F"

        # Issues
        issues = []
        if vitality < 10:
            issues.append("low_vitality")
        if integrity < 10:
            issues.append("quarantine_backlog")
        if connectivity < 5:
            issues.append("poor_connectivity")
        if diversity < 3:
            issues.append("low_diversity")
        if maintenance < 3:
            issues.append("no_maintenance")
        if not issues:
            issues.append("healthy")

        return {
            "score": score,
            "grade": grade,
            "dimensions": {
                "vitality": {"score": vitality, "max": 30,
                             "avg_weight": round(avg_weight, 4),
                             "active_ratio": round(active_ratio, 4)},
                "integrity": {"score": integrity, "max": 20,
                              "quarantine_ratio": round(q_ratio, 4)},
                "connectivity": {"score": connectivity, "max": 20,
                                 "density": round(density, 6),
                                 "isolation_rate": round(isolation_rate, 4)},
                "diversity": {"score": diversity, "max": 15,
                              "kind_count": len(kind_counts),
                              "evenness": round(evenness, 4)},
                "maintenance": {"score": maintenance, "max": 15,
                                "consolidated": consolidated,
                                "reinforced": reinforced},
            },
            "issues": issues,
        }

    # ── Diffusion Retrieval (ExpGraph-inspired Graph Diffusion) ────────────

    def diffusion_retrieve(
        self,
        query: str = "",
        *,
        seeds: list[str] | None = None,
        embedding: list[float] | None = None,
        limit: int = 10,
        alpha: float = 0.15,
        max_iter: int = 50,
        tol: float = 1e-4,
        edge_weight_factor: float = 1.0,
        merge_bm25: bool = True,
        bm25_boost: float = 0.3,
        explain: bool = False,
    ) -> list[dict]:
        """Personalized PageRank diffusion retrieval (ExpGraph-inspired).

        Replaces fixed-hop BFS neighborhood expansion with diffusion that
        naturally decays with graph distance. Seed nodes are identified via
        BM25 / vector search, then Personalized PageRank propagates relevance
        scores through the graph.

        Args:
            query: Text query for seed identification (used if ``seeds`` is None).
            seeds: Explicit seed node IDs (skips BM25/vector seed discovery).
            embedding: Optional query vector for vector-based seed discovery.
            limit: Number of results to return.
            alpha: Teleport probability (a.k.a. reset probability). Higher values
                bias toward seeds; lower values let diffusion spread further.
                Typical: 0.15 (standard PPR) to 0.3 (conservative).
            max_iter: Maximum power iterations.
            tol: Convergence tolerance (L1 norm).
            edge_weight_factor: Exponent applied to edge weights. 1.0 = linear,
                0.5 = square root (dampens strong edges), 2.0 = amplifies.
            merge_bm25: If True, blend diffusion scores with BM25 relevance.
            bm25_boost: Weight of BM25 scores in the final blend (0-1).
                ``1.0 - bm25_boost`` is the diffusion weight.
            explain: If True, include diffusion paths and step-by-step trace.

        Returns:
            List of dicts sorted by blended score (descending)::

                [{node_id, label, kind, score, diffusion_score,
                  bm25_score, hop_distance, sources}, ...]
        """
        # ── 1. Seed discovery ──────────────────────────────────────────
        if seeds is None:
            if not query:
                raise ValueError("Either query or seeds must be provided")
            # Use BM25 to find top seed candidates
            bm25_results = self.search_bm25(query, limit=limit * 3)
            if not bm25_results:
                bm25_results = [
                    {"node_id": r["node"].id, "label": r["node"].label,
                     "kind": r["node"].kind, "score": r["score"]}
                    for r in self.search_unified(query, limit=limit * 3)
                ]
            seed_ids = [item["node_id"] for item in bm25_results[:max(limit, 5)]]
            seed_scores = {item["node_id"]: item.get("score", 0.0)
                           for item in bm25_results}
        else:
            seed_ids = list(seeds)
            seed_scores = {sid: 1.0 for sid in seed_ids}
            bm25_results = []

        if not seed_ids:
            return []

        # Filter to existing nodes
        existing = set(
            str(r["id"]) for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined = 0"
            ).fetchall()
        )
        seed_ids = [sid for sid in seed_ids if sid in existing]
        if not seed_ids:
            return []

        # ── 2. Build weighted adjacency (subgraph around seeds) ────────
        # Collect all nodes reachable within a few hops from seeds.
        # To keep it efficient, we load edges once and build adjacency.
        all_edges = self.conn.execute(
            "SELECT source, target, weight FROM edges"
        ).fetchall()

        adj: dict[str, list[tuple[str, float]]] = {}
        out_degree: dict[str, float] = {}
        node_set: set[str] = set()

        for e in all_edges:
            s = str(e["source"])
            t = str(e["target"])
            w = e["weight"] if e["weight"] else 1.0
            w = w ** edge_weight_factor
            if s not in adj:
                adj[s] = []
                out_degree[s] = 0.0
            if t not in adj:
                adj[t] = []
                out_degree[t] = 0.0
            adj[s].append((t, w))
            out_degree[s] += w
            node_set.add(s)
            node_set.add(t)

        # Ensure seed nodes exist in adjacency (even if isolated)
        for sid in seed_ids:
            if sid not in adj:
                adj[sid] = []
                out_degree[sid] = 0.0
                node_set.add(sid)

        if not node_set:
            return []

        # ── 3. Personalized PageRank (power iteration) ────────────────
        # PPR: p = alpha * teleport + (1 - alpha) * W^T p
        # where teleport is uniform over seed nodes.
        n = len(node_set)
        teleport_mass = 1.0 / len(seed_ids)

        rank = {nid: 0.0 for nid in node_set}
        for sid in seed_ids:
            rank[sid] = teleport_mass

        # Normalize initial rank (handle seeds not in node_set)
        total = sum(rank.values())
        if total > 0:
            rank = {nid: v / total for nid, v in rank.items()}

        # Dangling mass redistribution
        for _ in range(max_iter):
            new_rank = {nid: 0.0 for nid in node_set}
            dangling_mass = 0.0

            for nid in node_set:
                if out_degree.get(nid, 0) > 0:
                    out_w = out_degree[nid]
                    for tgt, w in adj.get(nid, []):
                        new_rank[tgt] += rank[nid] * (w / out_w) * (1 - alpha)
                else:
                    dangling_mass += rank[nid]

            # Teleport + dangling redistribution to seeds
            for sid in seed_ids:
                new_rank[sid] += alpha * teleport_mass
                new_rank[sid] += dangling_mass * teleport_mass

            # Check convergence
            diff = sum(abs(new_rank[nid] - rank[nid]) for nid in node_set)
            rank = new_rank
            if diff < tol:
                break

        # ── 4. Compute hop distances from seeds (BFS) ──────────────────
        hop_distance: dict[str, int] = {}
        bfs_frontier = list(seed_ids)
        for sid in seed_ids:
            hop_distance[sid] = 0
        hop = 0
        while bfs_frontier:
            hop += 1
            next_frontier = []
            for nid in bfs_frontier:
                for tgt, _ in adj.get(nid, []):
                    if tgt not in hop_distance:
                        hop_distance[tgt] = hop
                        next_frontier.append(tgt)
            bfs_frontier = next_frontier
            if hop >= 5:  # limit BFS depth
                break

        # ── 5. Merge with BM25 scores (optional) ───────────────────────
        bm25_map = {item["node_id"]: item.get("score", 0.0) for item in bm25_results} if merge_bm25 else {}
        max_bm25 = max(bm25_map.values()) if bm25_map else 1.0

        # Normalize diffusion scores
        max_diffusion = max(rank.values()) if rank else 1.0
        if max_diffusion == 0:
            max_diffusion = 1.0

        # Fetch node info
        node_info = {}
        for r in self.conn.execute(
            "SELECT id, label, kind FROM nodes WHERE quarantined = 0"
        ).fetchall():
            node_info[str(r["id"])] = (r["label"], r["kind"])

        results = []
        for nid, diff_score in rank.items():
            if diff_score <= 0 and nid not in seed_scores:
                continue
            if nid not in node_info:
                continue

            norm_diff = diff_score / max_diffusion
            bm25_s = 0.0
            if merge_bm25 and nid in bm25_map:
                bm25_s = bm25_map[nid] / max_bm25 if max_bm25 > 0 else 0.0

            blended = (1 - bm25_boost) * norm_diff + bm25_boost * bm25_s

            sources = set()
            if nid in seed_scores:
                sources.add("seed")
            if nid in bm25_map:
                sources.add("bm25")
            if nid not in seed_ids and diff_score > 0:
                sources.add("diffusion")

            results.append({
                "node_id": nid,
                "label": node_info[nid][0],
                "kind": node_info[nid][1],
                "score": round(blended, 6),
                "diffusion_score": round(norm_diff, 6),
                "bm25_score": round(bm25_s, 6),
                "hop_distance": hop_distance.get(nid, -1),
                "sources": sorted(sources),
            })

        results.sort(key=lambda x: x["score"], reverse=True)

        if explain:
            for r_item in results:
                r_item["diffusion_paths"] = self._diffusion_explain(
                    r_item["node_id"], seed_ids, adj, hop_distance
                )

        return results[:limit]

    def _diffusion_explain(
        self,
        target: str,
        seeds: list[str],
        adj: dict[str, list[tuple[str, float]]],
        hop_distance: dict[str, int],
    ) -> list[dict]:
        """Trace shortest diffusion paths from seeds to target."""
        paths = []
        target_hop = hop_distance.get(target, -1)
        if target_hop <= 0:
            return [{"path": [target], "length": 0, "note": "seed node"}]

        # BFS from each seed to find path to target
        for seed in seeds:
            if seed == target:
                paths.append({"path": [seed], "length": 0, "note": "seed"})
                continue

            # BFS with path tracking (limited depth)
            queue = [(seed, [seed])]
            visited = {seed}
            found = False
            for _ in range(target_hop + 2):
                next_queue = []
                for node, path in queue:
                    for tgt, w in adj.get(node, []):
                        if tgt == target:
                            paths.append({
                                "path": path + [tgt],
                                "length": len(path),
                                "edge_weight": round(w, 4),
                            })
                            found = True
                            break
                        if tgt not in visited:
                            visited.add(tgt)
                            next_queue.append((tgt, path + [tgt]))
                    if found:
                        break
                queue = next_queue
                if found or not queue:
                    break

        return paths[:3]  # limit explanation paths

    # ── Knowledge Graph Embeddings (TransE) ────────────────

    def train_kge(self, dim: int = 32, epochs: int = 200, lr: float = 0.01,
                  margin: float = 1.0, seed: int = None) -> dict:
        """Train TransE knowledge graph embeddings.

        TransE models relationships as translations in embedding space:
            h + r ≈ t  (head + relation ≈ tail)

        Uses margin-based ranking loss with negative sampling.
        Stores entity/relation embeddings in kge_embeddings table.

        Args:
            dim: Embedding dimensionality (default 32)
            epochs: Training epochs (default 200)
            lr: Learning rate (default 0.01)
            margin: Margin for hinge loss γ (default 1.0)
            seed: Random seed for reproducibility

        Returns:
            {"entities": N, "relations": N, "dim": dim, "epochs": epochs}
        """
        import struct

        if seed is not None:
            import random as _rng
            _rng.seed(seed)

        # Collect entities and relations
        node_rows = self.conn.execute(
            "SELECT id, label FROM nodes WHERE quarantined = 0 OR quarantined IS NULL"
        ).fetchall()
        if len(node_rows) < 2:
            raise ValueError("Need at least 2 nodes for KGE training")

        edge_rows = self.conn.execute(
            "SELECT source, target, relation FROM edges"
        ).fetchall()
        if not edge_rows:
            raise ValueError("Need at least 1 edge for KGE training")

        entities = {row["id"]: row["label"] for row in node_rows}
        entity_ids = list(entities.keys())
        entity_idx = {eid: i for i, eid in enumerate(entity_ids)}

        relations = list(set(r["relation"] for r in edge_rows))
        rel_idx = {r: i for i, r in enumerate(relations)}

        n_ent = len(entity_ids)
        n_rel = len(relations)

        # Initialize embeddings (uniform [-1, 1] / dim, normalized)
        import random as _r2
        _r2.seed(seed) if seed is not None else None

        ent_emb = [[_r2.uniform(-1, 1) / math.sqrt(dim) for _ in range(dim)]
                   for _ in range(n_ent)]
        rel_emb = [[_r2.uniform(-1, 1) / math.sqrt(dim) for _ in range(dim)]
                   for _ in range(n_rel)]

        # Normalize entity embeddings to unit length
        for i in range(n_ent):
            norm = math.sqrt(sum(x * x for x in ent_emb[i])) or 1.0
            ent_emb[i] = [x / norm for x in ent_emb[i]]

        # Training triples
        triples = [(r["source"], r["target"], r["relation"]) for r in edge_rows]

        # Training loop
        for epoch in range(epochs):
            _r2.shuffle(triples)
            total_loss = 0.0

            for h_id, t_id, rel in triples:
                h = entity_idx.get(h_id)
                t = entity_idx.get(t_id)
                r = rel_idx.get(rel)
                if h is None or t is None or r is None:
                    continue

                # Negative sampling: corrupt tail
                neg_t = _r2.randint(0, n_ent - 1)
                while neg_t == t:
                    neg_t = _r2.randint(0, n_ent - 1)

                # Compute scores: d(h+r, t) and d(h+r, neg_t)
                def _dist(h_idx, t_idx, r_idx):
                    return sum((ent_emb[h_idx][d] + rel_emb[r_idx][d] - ent_emb[t_idx][d]) ** 2
                               for d in range(dim))

                pos_dist = _dist(h, t, r)
                neg_dist = _dist(h, neg_t, r)

                # Hinge loss: max(0, margin + pos - neg)
                loss = max(0, margin + pos_dist - neg_dist)
                total_loss += loss

                if loss > 0:
                    # Gradient update: push h+r toward t, away from neg_t
                    for d in range(dim):
                        # Positive direction
                        diff_pos = 2 * (ent_emb[h][d] + rel_emb[r][d] - ent_emb[t][d])
                        diff_neg = 2 * (ent_emb[h][d] + rel_emb[r][d] - ent_emb[neg_t][d])
                        grad = diff_pos - diff_neg

                        ent_emb[h][d] -= lr * grad
                        ent_emb[t][d] += lr * grad
                        ent_emb[neg_t][d] -= lr * (-grad)
                        rel_emb[r][d] -= lr * grad

                    # Re-normalize h (TransE constraint)
                    norm = math.sqrt(sum(x * x for x in ent_emb[h])) or 1.0
                    ent_emb[h] = [x / norm for x in ent_emb[h]]

        # Store in SQLite
        self.conn.execute("DROP TABLE IF EXISTS kge_embeddings")
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS kge_embeddings (
                entity TEXT PRIMARY KEY,
                entity_type TEXT DEFAULT 'node',
                embedding BLOB NOT NULL
            )
        """)

        for eid, idx in entity_idx.items():
            blob = struct.pack(f'{dim}f', *ent_emb[idx])
            self.conn.execute(
                "INSERT OR REPLACE INTO kge_embeddings (entity, entity_type, embedding) VALUES (?, ?, ?)",
                (eid, 'node', blob)
            )
        for rel, idx in rel_idx.items():
            blob = struct.pack(f'{dim}f', *rel_emb[idx])
            self.conn.execute(
                "INSERT OR REPLACE INTO kge_embeddings (entity, entity_type, embedding) VALUES (?, ?, ?)",
                (rel, 'relation', blob)
            )

        self.conn.commit()
        self._kge_dim = dim
        self._kge_trained = True

        return {"entities": n_ent, "relations": n_rel, "dim": dim, "epochs": epochs}

    def _kge_distance(self, h_id: str, t_id: str, rel: str) -> float:
        """Compute TransE L2 distance for a triple. Returns inf if any entity missing."""
        import struct

        h_row = self.conn.execute(
            "SELECT embedding FROM kge_embeddings WHERE entity=? AND entity_type='node'", (h_id,)
        ).fetchone()
        t_row = self.conn.execute(
            "SELECT embedding FROM kge_embeddings WHERE entity=? AND entity_type='node'", (t_id,)
        ).fetchone()
        r_row = self.conn.execute(
            "SELECT embedding FROM kge_embeddings WHERE entity=? AND entity_type='relation'", (rel,)
        ).fetchone()

        if not h_row or not t_row or not r_row:
            return float('inf')

        dim = getattr(self, '_kge_dim', 32)
        h_emb = struct.unpack(f'{dim}f', h_row["embedding"])
        t_emb = struct.unpack(f'{dim}f', t_row["embedding"])
        r_emb = struct.unpack(f'{dim}f', r_row["embedding"])

        return sum((h_emb[d] + r_emb[d] - t_emb[d]) ** 2 for d in range(dim))

    def kge_score(self, head_label: str, tail_label: str, relation: str) -> float:
        """Score a triple using trained TransE embeddings (L2 distance, lower = better).

        Args:
            head_label: Head node label (must exist in graph)
            tail_label: Tail node label (must exist in graph)
            relation: Relation type

        Returns:
            L2 distance (float). Lower means more plausible. inf if entities not found.

        Raises:
            ValueError: If train_kge() has not been called
        """
        if not getattr(self, '_kge_trained', False):
            raise ValueError("KGE not trained. Call train_kge() first.")

        h_row = self.conn.execute("SELECT id FROM nodes WHERE label=?", (head_label,)).fetchone()
        t_row = self.conn.execute("SELECT id FROM nodes WHERE label=?", (tail_label,)).fetchone()
        if not h_row or not t_row:
            return float('inf')

        return self._kge_distance(h_row["id"], t_row["id"], relation)

    def get_kge_embedding(self, entity: str) -> Optional[list[float]]:
        """Get the learned KGE embedding for an entity (node ID or label).

        Args:
            entity: Node ID or label

        Returns:
            List of floats, or None if not found
        """
        import struct

        if not getattr(self, '_kge_trained', False):
            return None

        # Try as node ID first, then label
        row = self.conn.execute(
            "SELECT embedding FROM kge_embeddings WHERE entity=? AND entity_type='node'", (entity,)
        ).fetchone()
        if not row:
            n_row = self.conn.execute("SELECT id FROM nodes WHERE label=?", (entity,)).fetchone()
            if n_row:
                row = self.conn.execute(
                    "SELECT embedding FROM kge_embeddings WHERE entity=? AND entity_type='node'",
                    (n_row["id"],)
                ).fetchone()

        if not row:
            return None

        dim = getattr(self, '_kge_dim', 32)
        return list(struct.unpack(f'{dim}f', row["embedding"]))

    def _kge_neighbors(self, node_id: str, limit: int = 10) -> list[dict]:
        """Find related nodes via KGE proximity (internal helper for search_hybrid)."""
        import struct

        if not getattr(self, '_kge_trained', False):
            return []

        h_row = self.conn.execute(
            "SELECT embedding FROM kge_embeddings WHERE entity=? AND entity_type='node'", (node_id,)
        ).fetchone()
        if not h_row:
            return []

        dim = self._kge_dim
        h_emb = struct.unpack(f'{dim}f', h_row["embedding"])

        # Get all relation embeddings
        rel_rows = self.conn.execute(
            "SELECT entity, embedding FROM kge_embeddings WHERE entity_type='relation'",
        ).fetchall()
        if not rel_rows:
            return []

        # For each relation, compute h+r and find nearest entities
        all_entities = self.conn.execute(
            "SELECT entity, embedding FROM kge_embeddings WHERE entity_type='node' AND entity != ?",
            (node_id,)
        ).fetchall()

        if not all_entities:
            return []

        # Score = min over all relations of distance(h+r, t)
        scores = []
        for ent_row in all_entities:
            t_emb = struct.unpack(f'{dim}f', ent_row["embedding"])
            best_score = float('inf')
            for rel_row in rel_rows:
                r_emb = struct.unpack(f'{dim}f', rel_row["embedding"])
                dist = sum((h_emb[d] + r_emb[d] - t_emb[d]) ** 2 for d in range(dim))
                if dist < best_score:
                    best_score = dist
            scores.append((ent_row["entity"], best_score))

        scores.sort(key=lambda x: x[1])
        return [{"node_id": eid, "kge_distance": dist} for eid, dist in scores[:limit]]

    # ------------------------------------------------------------------
    # Bi-temporal validity tracking
    # ------------------------------------------------------------------

    def set_validity(self, node_id: str, valid_from: float = None,
                     valid_to: float = None) -> bool:
        """Set the valid-time interval for a node.

        Valid time represents when the fact is true in the real world.
        None for valid_from means "beginning of time".
        None for valid_to means "valid until superseded" (open-ended).

        Args:
            node_id: Node ID
            valid_from: Unix timestamp when the fact became true
            valid_to: Unix timestamp when the fact ceased to be true (None = still valid)

        Returns:
            True if updated, False if node not found
        """
        row = self.conn.execute("SELECT id FROM nodes WHERE id=?", (node_id,)).fetchone()
        if not row:
            return False
        if valid_from is not None:
            self.conn.execute("UPDATE nodes SET valid_from=? WHERE id=?", (valid_from, node_id))
        if valid_to is not None:
            self.conn.execute("UPDATE nodes SET valid_to=? WHERE id=?", (valid_to, node_id))
        self.conn.execute(
            "UPDATE nodes SET txn_time=? WHERE id=?",
            (time.time(), node_id)
        )
        self.conn.commit()
        return True

    def is_valid_at(self, node_id: str, timestamp: float) -> bool:
        """Check if a node's fact was valid at the given timestamp.

        A node is valid at time T if:
        - valid_from is NULL or valid_from <= T, AND
        - valid_to is NULL or valid_to > T

        Nodes without any validity metadata are always considered valid.

        Args:
            node_id: Node ID
            timestamp: Unix timestamp to check

        Returns:
            True if the node was valid at the given time
        """
        row = self.conn.execute(
            "SELECT valid_from, valid_to FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return False
        vf, vt = row["valid_from"], row["valid_to"]
        if vf is not None and vf > timestamp:
            return False
        if vt is not None and vt <= timestamp:
            return False
        return True

    def supersede(self, node_id: str, new_label: str = None,
                  new_kind: str = None, new_data: dict = None) -> Optional[str]:
        """Mark an old node as superseded and create a replacement.

        Sets valid_to on the old node to 'now', creates a new node with
        valid_from='now', and links old → new with a 'superseded_by' edge.

        Args:
            node_id: ID of the node to supersede
            new_label: Label for the new node (defaults to old label)
            new_kind: Kind for the new node (defaults to old kind)
            new_data: Data for the new node (defaults to old data)

        Returns:
            New node ID, or None if old node not found
        """
        old = self.get_node(node_id)
        if not old:
            return None
        now = time.time()
        # Close the old node's valid time
        self.conn.execute(
            "UPDATE nodes SET valid_to=?, txn_time=? WHERE id=?",
            (now, now, node_id)
        )
        # Create replacement
        new_node = self.add(
            new_label or old.label,
            new_kind or old.kind,
            new_data or old.data
        )
        self.conn.execute(
            "UPDATE nodes SET valid_from=?, txn_time=? WHERE id=?",
            (now, now, new_node.id)
        )
        # Link old → new
        self.link(node_id, new_node.id, "superseded_by")
        self.conn.commit()
        return new_node.id

    def query_valid_at(self, timestamp: float, kind: str = None) -> list[Node]:
        """Query all nodes whose valid-time interval contains the given timestamp.

        Args:
            timestamp: Unix timestamp to query
            kind: Optional kind filter

        Returns:
            List of Node objects valid at that time
        """
        sql = (
            "SELECT * FROM nodes WHERE "
            "(valid_from IS NULL OR valid_from <= ?) AND "
            "(valid_to IS NULL OR valid_to > ?) AND "
            "(quarantined = 0 OR quarantined IS NULL)"
        )
        params = [timestamp, timestamp]
        if kind is not None:
            sql += " AND kind=?"
            params.append(kind)
        rows = self.conn.execute(sql, params).fetchall()
        return [
            Node(r["id"], r["label"], r["kind"],
                 json.loads(r["data"]), r["created"], r["accessed"], r["weight"])
            for r in rows
        ]

    def get_history(self, node_id: str) -> list[dict]:
        """Get the full validity history chain for a node.

        Follows 'superseded_by' edges forward and backward to reconstruct
        the complete timeline of a fact.

        Args:
            node_id: Starting node ID

        Returns:
            List of {node_id, label, valid_from, valid_to, txn_time} sorted chronologically
        """
        chain = []
        seen = set()
        # Walk forward (this node → successors)
        current = node_id
        while current and current not in seen:
            seen.add(current)
            row = self.conn.execute(
                "SELECT id, label, valid_from, valid_to, txn_time FROM nodes WHERE id=?",
                (current,)
            ).fetchone()
            if not row:
                break
            chain.append({
                "node_id": row["id"],
                "label": row["label"],
                "valid_from": row["valid_from"],
                "valid_to": row["valid_to"],
                "txn_time": row["txn_time"],
            })
            # Find successor
            succ = self.conn.execute(
                "SELECT target FROM edges WHERE source=? AND relation='superseded_by'",
                (current,)
            ).fetchone()
            current = succ["target"] if succ else None
        # Walk backward (predecessors → this node)
        current = node_id
        backward = []
        while True:
            pred = self.conn.execute(
                "SELECT source FROM edges WHERE target=? AND relation='superseded_by'",
                (current,)
            ).fetchone()
            if not pred or pred["source"] in seen:
                break
            seen.add(pred["source"])
            row = self.conn.execute(
                "SELECT id, label, valid_from, valid_to, txn_time FROM nodes WHERE id=?",
                (pred["source"],)
            ).fetchone()
            if row:
                backward.append({
                    "node_id": row["id"],
                    "label": row["label"],
                    "valid_from": row["valid_from"],
                    "valid_to": row["valid_to"],
                    "txn_time": row["txn_time"],
                })
            current = pred["source"]
        chain = list(reversed(backward)) + chain
        return chain

    def query_as_of(self, timestamp: float, node_id: str = None,
                    *, depth: int = 1, kind: str = None,
                    relation: str = None, limit: int = 100) -> dict:
        """Unified bi-temporal query — "what did the graph look like at time T?"

        Combines node-level and edge-level bi-temporal filtering into a
        single query API.  Two modes:

        1. **Localized** (node_id given): BFS from *node_id* to *depth*,
           returning only nodes and edges valid at *timestamp*.  This is
           the Engram retrieval pattern — bi-temporal context retrieval
           beats full-context by +10.4pp (LongMemEval).

        2. **Global** (node_id is None): Full graph snapshot at *timestamp*.

        Args:
            timestamp: Unix timestamp to query (as-of time).
            node_id: Optional seed node for localized subgraph query.
            depth: BFS depth from seed (localized mode only). Default 1.
            kind: Optional node kind filter.
            relation: Optional edge relation filter.
            limit: Max nodes to return (safety cap). Default 100.

        Returns:
            Dict with keys:
            - ``timestamp``: the query timestamp
            - ``mode``: 'localized' or 'global'
            - ``nodes``: list of {id, label, kind, weight, valid_from, valid_to}
            - ``edges``: list of {source, target, relation, weight}
            - ``stats``: {nodes, edges, depth_reached}
        """
        ts = timestamp

        # ── Global mode: delegate to temporal_graph_snapshot ──
        if node_id is None:
            snap = self.temporal_graph_snapshot(ts)
            nodes_out = snap["nodes"]
            edges_out = snap["edges"]
            if kind is not None:
                nodes_out = [n for n in nodes_out if n.get("kind") == kind]
            if relation is not None:
                edges_out = [e for e in edges_out if e.get("relation") == relation]
            nodes_out = nodes_out[:limit]
            return {
                "timestamp": ts,
                "mode": "global",
                "nodes": nodes_out,
                "edges": edges_out,
                "stats": {"nodes": len(nodes_out), "edges": len(edges_out),
                          "depth_reached": None},
            }

        # ── Localized mode: BFS from node_id ──
        if not self.get_node(node_id):
            return {"timestamp": ts, "mode": "localized", "nodes": [],
                    "edges": [], "stats": {"nodes": 0, "edges": 0,
                                            "depth_reached": 0}}

        visited: set[str] = set()
        frontier = {node_id}
        all_edges = []
        depth_reached = 0

        for d in range(depth + 1):
            next_frontier = set()
            for nid in frontier:
                if nid in visited or len(visited) >= limit:
                    continue
                # Check node validity at ts (both systems)
                if not self.node_valid_at(nid, ts):
                    continue
                if not self.is_valid_at(nid, ts):
                    continue
                if kind is not None:
                    node = self.get_node(nid)
                    if node.kind != kind:
                        continue
                visited.add(nid)

                # Explore edges (only if we haven't reached max depth)
                if d < depth:
                    for e in self.edges_of(nid, direction="both"):
                        # Edge relation filter
                        if relation is not None and e.relation != relation:
                            continue
                        # Edge temporal validity
                        if not self.edge_valid_at(e.source, e.target,
                                                  e.relation, ts):
                            continue
                        # Avoid duplicate edges
                        edge_key = (e.source, e.target, e.relation)
                        if not any(ae["source"] == e.source and
                                   ae["target"] == e.target and
                                   ae["relation"] == e.relation
                                   for ae in all_edges):
                            all_edges.append({
                                "source": e.source,
                                "target": e.target,
                                "relation": e.relation,
                                "weight": round(e.weight, 4),
                            })
                        # Add unvisited neighbors to frontier
                        neighbor = e.target if e.source == nid else e.source
                        if neighbor not in visited:
                            next_frontier.add(neighbor)

            frontier = next_frontier
            if frontier:
                depth_reached = d + 1
            if not frontier or len(visited) >= limit:
                break

        # Build node list with temporal metadata
        nodes_out = []
        for nid in visited:
            node = self.get_node(nid)
            row = self.conn.execute(
                "SELECT valid_from, valid_to FROM nodes WHERE id=?", (nid,)
            ).fetchone()
            data = node.data if isinstance(node.data, dict) else json.loads(node.data)
            node_temporal = data.get("_node_temporal", {})
            nodes_out.append({
                "id": node.id,
                "label": node.label,
                "kind": node.kind,
                "weight": round(node.weight, 4),
                "valid_from": row["valid_from"] if row else node_temporal.get("valid_from"),
                "valid_to": row["valid_to"] if row else node_temporal.get("valid_until"),
            })

        return {
            "timestamp": ts,
            "mode": "localized",
            "nodes": nodes_out,
            "edges": all_edges,
            "stats": {
                "nodes": len(nodes_out),
                "edges": len(all_edges),
                "depth_reached": depth_reached,
            },
        }

    def trace_decision_chain(self, topic: str = None,
                             node_id: str = None) -> list[dict]:
        """Trace the decision/supersession chain for a topic or node.

        Inspired by TokenMizer's ``why_decision``: for each hop in the
        supersession chain, report *trigger*, *reason*, and *evidence*
        so the caller can answer "why did this fact change from A to B?".

        Each returned dict contains:
        - ``from_node``: node ID at this hop (or ``None`` for the origin)
        - ``to_node``: successor node ID (or ``None`` for the latest)
        - ``from_label`` / ``to_label``: human-readable labels
        - ``trigger``: what caused the change — ``'supersede'``,
          ``'conflict_resolve'``, or ``'unknown'``
        - ``reason``: extracted reason text (from edge metadata,
          conflict log, or node data)
        - ``evidence``: list of supporting node IDs (edges pointing
          to either node with evidence-type relations)
        - ``timestamp``: when the transition happened (valid_to of
          from_node)

        Args:
            topic: Label substring to search for (case-insensitive).
                Finds the oldest matching node and traces forward.
            node_id: Start from a specific node ID. Used if topic
                is ``None``.

        Returns:
            List of hop dicts in chronological order. Empty list if
            the topic/node is not found or has no supersession history.
        """
        # Resolve starting node
        if node_id is None:
            if topic is None:
                return []
            row = self.conn.execute(
                "SELECT id FROM nodes WHERE label LIKE ? "
                "ORDER BY created ASC LIMIT 1",
                (f"%{topic}%",)
            ).fetchone()
            if not row:
                return []
            node_id = row["id"]

        # Verify node exists
        start = self.conn.execute(
            "SELECT id, label FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not start:
            return []

        # Walk the full supersession chain from the oldest ancestor
        chain = self.get_history(node_id)
        if len(chain) < 2:
            return []

        # Check for conflict resolution logs
        conflict_rows = self.conn.execute(
            "SELECT kept, superseded, reason FROM _conflict_log"
            if self.conn.execute(
                "SELECT name FROM sqlite_master WHERE "
                "type='table' AND name='_conflict_log'"
            ).fetchone()
            else []
        ).fetchall() if self.conn.execute(
            "SELECT name FROM sqlite_master WHERE "
            "type='table' AND name='_conflict_log'"
        ).fetchone() else []

        conflict_map: dict[str, str] = {}
        for cr in conflict_rows:
            conflict_map[str(cr["superseded"])] = cr["reason"] or ""

        hops: list[dict] = []
        for i in range(len(chain) - 1):
            cur = chain[i]
            nxt = chain[i + 1]

            # Determine trigger
            edge = self.conn.execute(
                "SELECT source, target, relation FROM edges "
                "WHERE source=? AND target=? AND relation='superseded_by'",
                (cur["node_id"], nxt["node_id"])
            ).fetchone()

            trigger = "unknown"
            reason = ""
            if edge:
                trigger = "supersede"
            if cur["node_id"] in conflict_map:
                trigger = "conflict_resolve"
                reason = conflict_map[cur["node_id"]]

            # Gather evidence: edges with 'evidence' or 'supports' relations
            evidence_rows = self.conn.execute(
                "SELECT source FROM edges WHERE target=? "
                "AND relation IN ('evidence', 'supports', 'proves')",
                (nxt["node_id"],)
            ).fetchall()
            evidence = [str(r["source"]) for r in evidence_rows]

            hops.append({
                "from_node": cur["node_id"],
                "to_node": nxt["node_id"],
                "from_label": cur["label"],
                "to_label": nxt["label"],
                "trigger": trigger,
                "reason": reason,
                "evidence": evidence,
                "timestamp": cur["valid_to"],
            })

        return hops

    # ------------------------------------------------------------------
    # Q-value scoring (RL-inspired retrieval feedback)
    # ------------------------------------------------------------------

    def update_q_value(self, node_id: str, reward: float,
                       alpha: float = 0.1, gamma: float = 0.9) -> bool:
        """Update a node's Q-value using temporal-difference learning.

        Q(s) ← Q(s) + α · (reward + γ · max_neighbor_Q − Q(s))

        This lets frequently-useful memories accumulate higher Q-values,
        while rarely-useful ones decay toward zero.

        Args:
            node_id: Node to update
            reward: Immediate reward (positive=useful, negative=not useful)
            alpha: Learning rate (default 0.1)
            gamma: Discount factor for neighbor contribution (default 0.9)

        Returns:
            True if updated, False if node not found
        """
        row = self.conn.execute(
            "SELECT q_value FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return False
        old_q = row["q_value"] if row["q_value"] is not None else 0.0
        # Max Q among neighbors (propagate value through graph)
        neighbor_q = self.conn.execute(
            "SELECT MAX(n.q_value) as max_q FROM nodes n"
            " JOIN edges e ON n.id = e.target WHERE e.source = ?",
            (node_id,)
        ).fetchone()
        max_n_q = neighbor_q["max_q"] if neighbor_q and neighbor_q["max_q"] is not None else 0.0
        new_q = old_q + alpha * (reward + gamma * max_n_q - old_q)
        self.conn.execute(
            "UPDATE nodes SET q_value=? WHERE id=?", (new_q, node_id)
        )
        self.conn.commit()
        return True

    def get_q_value(self, node_id: str) -> Optional[float]:
        """Get the current Q-value for a node.

        Returns:
            Q-value float, or None if node not found
        """
        row = self.conn.execute(
            "SELECT q_value FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return None
        return row["q_value"] if row["q_value"] is not None else 0.0

    def reward(self, node_id: str, amount: float = 1.0) -> bool:
        """Convenience: give positive reward to a node (shortcut for update_q_value).

        Args:
            node_id: Node to reward
            amount: Reward magnitude (default 1.0)

        Returns:
            True if updated, False if not found
        """
        return self.update_q_value(node_id, reward=amount)

    def penalize(self, node_id: str, amount: float = 1.0) -> bool:
        """Convenience: give negative reward to a node.

        Args:
            node_id: Node to penalize
            amount: Penalty magnitude (default 1.0)

        Returns:
            True if updated, False if not found
        """
        return self.update_q_value(node_id, reward=-amount)

    def recall_with_q(self, query: str, limit: int = 5,
                      q_bias: float = 0.3) -> list[dict]:
        """Recall memories, blending text relevance with Q-value scoring.

        Final score = (1 − q_bias) · text_score + q_bias · normalized_q

        Args:
            query: Search query
            limit: Number of results
            q_bias: Weight of Q-value in final score (0.0=text only, 1.0=Q only)

        Returns:
            List of {node_id, label, kind, score, q_value} sorted by blended score
        """
        results = self.recall(query, limit=limit * 3)
        if not results:
            return []
        # Normalize text scores to [0, 1]
        max_text = max((n.weight for n in results), default=1.0)
        if max_text <= 0:
            max_text = 1.0
        # Normalize Q-values to [0, 1]
        q_values = {}
        for n in results:
            q = self.get_q_value(n.id)
            q_values[n.id] = q if q is not None else 0.0
        all_q = list(q_values.values())
        min_q = min(all_q) if all_q else 0.0
        max_q = max(all_q) if all_q else 1.0
        q_range = max_q - min_q
        if q_range <= 0:
            q_range = 1.0
        # Blend scores
        scored = []
        for n in results:
            text_norm = n.weight / max_text
            q_norm = (q_values[n.id] - min_q) / q_range
            blended = (1.0 - q_bias) * text_norm + q_bias * q_norm
            scored.append({
                "node_id": n.id,
                "label": n.label,
                "kind": n.kind,
                "score": round(blended, 6),
                "q_value": round(q_values[n.id], 6),
            })
        scored.sort(key=lambda x: x["score"], reverse=True)
        return scored[:limit]

    def top_q_nodes(self, limit: int = 10, kind: str = None) -> list[dict]:
        """Return nodes with the highest Q-values.

        Args:
            limit: Number of nodes to return
            kind: Optional kind filter

        Returns:
            List of {node_id, label, kind, q_value} sorted by Q-value descending
        """
        sql = (
            "SELECT id, label, kind, q_value FROM nodes "
            "WHERE (quarantined = 0 OR quarantined IS NULL)"
        )
        params = []
        if kind is not None:
            sql += " AND kind=?"
            params.append(kind)
        sql += " ORDER BY q_value DESC LIMIT ?"
        params.append(limit)
        rows = self.conn.execute(sql, params).fetchall()
        return [
            {"node_id": r["id"], "label": r["label"],
             "kind": r["kind"], "q_value": r["q_value"] or 0.0}
            for r in rows
        ]

    # ── Vector Clock + Subscribe/Publish ──

    def _tick(self, op: str, node_id: str = None, details: dict = None):
        """Advance Lamport clock, log the event, and emit to subscribers."""
        self._lamport_clock += 1
        lamport = self._lamport_clock
        detail_str = json.dumps(details or {})
        self.conn.execute(
            "INSERT INTO clock_log (lamport, op, node_id, details, wall_time) VALUES (?,?,?,?,?)",
            (lamport, op, node_id, detail_str, time.time())
        )
        self.conn.commit()
        evt = {"lamport": lamport, "op": op, "node_id": node_id, **(details or {})}
        self._emit(op, evt)

    def _emit(self, op: str, evt: dict):
        """Dispatch event to matching subscribers."""
        for op_key in (op, "*"):
            for _sub_id, callback in self._typed_subscribers.get(op_key, []):
                try:
                    callback(evt)
                except Exception:
                    pass

    def lamport_clock(self) -> int:
        """Return the current Lamport logical clock value for this graph."""
        return self._lamport_clock

    def event_log(self) -> list[dict]:
        """Return the full event log ordered by Lamport time."""
        rows = self.conn.execute(
            "SELECT lamport, op, node_id, details FROM clock_log ORDER BY lamport"
        ).fetchall()
        result = []
        for r in rows:
            entry = {"lamport": r["lamport"], "op": r["op"],
                     "node_id": r["node_id"]}
            entry.update(json.loads(r["details"]))
            result.append(entry)
        return result

    def get_operation_history(self, *,
                              operation_type: str | None = None,
                              node_id: str | None = None,
                              start_time: float | None = None,
                              end_time: float | None = None,
                              limit: int = 100,
                              offset: int = 0,
                              group_by: str = "none") -> dict:
        """MemOps-compatible structured operation history.

        Provides operation-level audit trail for agent memory evaluation.
        Maps raw clock_log events into MemOps 6-category taxonomy:

        ===========  =================================================
        Category     Mapped operations
        ===========  =================================================
        remember     add (node creation)
        link         link, add_causal_edge, add_workflow
        update       update, tag, embed, confidence changes
        forget       decay, forget_policy, security_purge, quarantine
        reflect      consolidate, merge, compress, auto_heal
        retrieve     query, search, retrieval_failure
        ===========  =================================================

        **Use cases:**

        - MemOps benchmark evaluation (operation-level scoring)
        - Debugging unexpected graph state changes
        - Audit trail for governance/compliance
        - Temporal analysis of memory operations

        Args:
            operation_type: Filter by MemOps category (remember/link/
                update/forget/reflect/retrieve) or raw op name.
            node_id: Filter to operations involving a specific node.
            start_time: Unix timestamp lower bound (inclusive).
            end_time: Unix timestamp upper bound (exclusive).
            limit: Max entries to return (default 100).
            offset: Pagination offset.
            group_by: "none" (default), "type" (group by MemOps category),
                or "time" (group by hour).

        Returns:
            Dict with:
            - ``operations``: list of {lamport, op, memops_type, node_id,
                details, wall_time, timestamp_iso}
            - ``total``: total matching count (before limit/offset)
            - ``summary``: {total_ops, by_type: {remember: N, ...}}
            - ``time_range``: {earliest, latest} Unix timestamps
        """
        import datetime as _dt

        # MemOps category mapping
        MEMOPS_MAP = {
            # remember
            "add":               "remember",
            "add_with_entropy":  "remember",
            # link
            "link":              "link",
            "add_causal_edge":   "link",
            "add_workflow":       "link",
            "add_intention":      "link",
            # update
            "update":             "update",
            "tag":               "update",
            "embed":             "update",
            "add_embedding":      "update",
            "set_confidence":     "update",
            "set_category":       "update",
            # forget
            "decay":              "forget",
            "forget":             "forget",
            "forget_policy":      "forget",
            "security_purge":     "forget",
            "quarantine":         "forget",
            "soft_forget":        "forget",
            "cue_reactivation":   "forget",
            # reflect
            "consolidate":        "reflect",
            "merge":             "reflect",
            "merge_nodes":        "reflect",
            "compress":           "reflect",
            "auto_heal":          "reflect",
            "auto_consolidate":   "reflect",
            # retrieve
            "query":             "retrieve",
            "search":            "retrieve",
            "retrieval_failure":  "retrieve",
            "drift":             "retrieve",
        }

        query_parts = [
            "SELECT lamport, op, node_id, details, wall_time FROM clock_log"
        ]
        conditions = []
        params = []

        if operation_type:
            # Check if it's a MemOps category or raw op
            memops_ops = [k for k, v in MEMOPS_MAP.items() if v == operation_type]
            if memops_ops:
                placeholders = ",".join("?" * len(memops_ops))
                conditions.append(f"op IN ({placeholders})")
                params.extend(memops_ops)
            else:
                conditions.append("op = ?")
                params.append(operation_type)

        if node_id:
            conditions.append("node_id = ?")
            params.append(node_id)

        if start_time is not None:
            conditions.append("wall_time >= ?")
            params.append(start_time)

        if end_time is not None:
            conditions.append("wall_time < ?")
            params.append(end_time)

        where_clause = (" WHERE " + " AND ".join(conditions)) if conditions else ""

        # Total count
        count_row = self.conn.execute(
            f"SELECT COUNT(*) c FROM clock_log{where_clause}", params
        ).fetchone()
        total = count_row["c"] if count_row else 0

        # Fetch with pagination
        query_parts.append(where_clause)
        query_parts.append(" ORDER BY lamport DESC LIMIT ? OFFSET ?")
        full_query = "".join(query_parts)
        rows = self.conn.execute(full_query, params + [limit, offset]).fetchall()

        # Build operations list
        operations = []
        by_type: dict[str, int] = {}
        earliest = None
        latest = None
        for r in rows:
            memops_type = MEMOPS_MAP.get(r["op"], "other")
            details = json.loads(r["details"]) if r["details"] else {}
            wt = r["wall_time"]
            if wt is not None:
                if earliest is None or wt < earliest:
                    earliest = wt
                if latest is None or wt > latest:
                    latest = wt
            operations.append({
                "lamport":      r["lamport"],
                "op":           r["op"],
                "memops_type":  memops_type,
                "node_id":      r["node_id"],
                "details":      details,
                "wall_time":    wt,
                "timestamp_iso": (_dt.datetime.fromtimestamp(wt).isoformat()
                                   if wt else None),
            })
            by_type[memops_type] = by_type.get(memops_type, 0) + 1

        result = {
            "operations":  operations,
            "total":       total,
            "summary": {
                "total_ops":   total,
                "by_type":     by_type,
                "categories":  sorted(by_type.keys()),
            },
            "time_range": {
                "earliest":    earliest,
                "latest":      latest,
            },
            "limit":       limit,
            "offset":      offset,
        }

        # Optional grouping
        if group_by == "type" and operations:
            grouped: dict[str, list] = {}
            for op in operations:
                grouped.setdefault(op["memops_type"], []).append(op)
            result["grouped"] = grouped
        elif group_by == "time" and operations:
            time_groups: dict[str, list] = {}
            for op in operations:
                wt = op.get("wall_time")
                if wt:
                    hour_key = _dt.datetime.fromtimestamp(wt).strftime("%Y-%m-%dT%H:00")
                    time_groups.setdefault(hour_key, []).append(op)
            result["grouped"] = time_groups

        return result

    def on(self, event_type: str, callback: callable) -> str:
        """Subscribe to graph mutation events (typed pub/sub).

        Args:
            event_type: One of 'add', 'link', 'delete', 'update', or '*' for all.
            callback: Called with event dict on each matching operation.

        Returns:
            Subscription ID for later removal via off().
        """
        import uuid as _uuid
        sub_id = _uuid.uuid4().hex[:8]
        self._typed_subscribers.setdefault(event_type, []).append((sub_id, callback))
        return sub_id

    def off(self, sub_id: str) -> bool:
        """Remove a typed subscription by ID. Returns True if found."""
        for op_key, subs in self._typed_subscribers.items():
            for i, (sid, _) in enumerate(subs):
                if sid == sub_id:
                    subs.pop(i)
                    return True
        return False

    # ── Memory Conflict Detection ──

    @staticmethod
    def _extract_entities(text: str) -> set[str]:
        """Extract simple entity tokens from text (non-stopword, length>2)."""
        import re
        stopwords = {
            'the', 'is', 'are', 'was', 'were', 'a', 'an', 'of', 'in', 'to',
            'and', 'or', 'not', 'for', 'with', 'by', 'on', 'at', 'from',
            'it', 'this', 'that', 'these', 'those', 'be', 'been', 'being',
        }
        tokens = re.findall(r'[A-Za-z]{3,}', text.lower())
        return {t for t in tokens if t not in stopwords}

    @staticmethod
    def _extract_numbers(text: str) -> list[str]:
        """Extract numeric values from text."""
        import re
        return re.findall(r'\d+(?:\.\d+)?', text)

    def conflict_detect(self, threshold: float = 0.5,
                        kind: str = None) -> list[dict]:
        """Detect contradictions between facts in the memory graph.

        Uses entity overlap + numeric mismatch heuristics:
        - Facts sharing key entities are candidates
        - If numbers differ → value_mismatch conflict
        - If high text similarity but different phrasing → potential restatement (not conflict)

        Args:
            threshold: Conflict score threshold (0-1). Higher = stricter.
            kind: Optional kind filter (e.g. 'fact').

        Returns:
            List of conflict dicts: {node_a, node_b, label_a, label_b,
                                     kind_a, kind_b, type, score}
        """
        sql = "SELECT id, label, kind FROM nodes WHERE (quarantined = 0 OR quarantined IS NULL)"
        params = []
        if kind:
            sql += " AND kind=?"
            params.append(kind)
        sql += " ORDER BY kind, label"
        rows = self.conn.execute(sql, params).fetchall()

        conflicts = []
        # Group by entity overlap
        entities_map = {}
        for row in rows:
            ents = self._extract_entities(row["label"])
            for ent in ents:
                entities_map.setdefault(ent, []).append(row)

        checked = set()
        for ent, group in entities_map.items():
            if len(group) < 2:
                continue
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    a, b = group[i], group[j]
                    if a["id"] == b["id"]:
                        continue
                    pair_key = tuple(sorted([a["id"], b["id"]]))
                    if pair_key in checked:
                        continue
                    checked.add(pair_key)

                    # Check if this is actually a conflict
                    nums_a = self._extract_numbers(a["label"])
                    nums_b = self._extract_numbers(b["label"])

                    # Shared entities beyond this one word
                    ents_a = self._extract_entities(a["label"])
                    ents_b = self._extract_entities(b["label"])
                    shared = ents_a & ents_b

                    if nums_a and nums_b:
                        # Both have numbers — if different, likely conflict
                        if set(nums_a) != set(nums_b):
                            overlap_score = len(shared) / max(len(ents_a | ents_b), 1)
                            if overlap_score >= threshold * 0.5:
                                conflicts.append({
                                    "node_a": a["id"], "node_b": b["id"],
                                    "label_a": a["label"], "label_b": b["label"],
                                    "kind_a": a["kind"], "kind_b": b["kind"],
                                    "type": "value_mismatch",
                                    "score": round(min(overlap_score + 0.3, 1.0), 3),
                                    "shared_entities": list(shared),
                                    "numbers_a": nums_a,
                                    "numbers_b": nums_b,
                                })
                        # Same numbers + high similarity = restatement, not conflict
                    elif len(shared) >= 2:
                        # High entity overlap but no numbers — check for semantic contradiction
                        sim = self._content_similarity(a["label"], b["label"])
                        only_a = ents_a - ents_b
                        only_b = ents_b - ents_a
                        # If they share most words but have different specific entities
                        # (e.g. "capital of France" vs "capital of Germany")
                        if only_a and only_b and sim >= 0.3:
                            # Different proper nouns with high overlap = likely contradiction
                            score = round(sim * len(shared) / max(len(ents_a | ents_b), 1) + 0.3, 3)
                            score = min(score, 1.0)
                            if score >= threshold:
                                conflicts.append({
                                    "node_a": a["id"], "node_b": b["id"],
                                    "label_a": a["label"], "label_b": b["label"],
                                    "kind_a": a["kind"], "kind_b": b["kind"],
                                    "type": "semantic_contradiction",
                                    "score": score,
                                    "shared_entities": list(shared),
                                })
                        elif sim < 0.6 and sim > 0.1:
                            score = round(len(shared) / max(len(ents_a | ents_b), 1) * (1 - sim), 3)
                            if score >= threshold:
                                conflicts.append({
                                    "node_a": a["id"], "node_b": b["id"],
                                    "label_a": a["label"], "label_b": b["label"],
                                    "kind_a": a["kind"], "kind_b": b["kind"],
                                    "type": "semantic_contradiction",
                                    "score": score,
                                    "shared_entities": list(shared),
                                })

        # Sort by score descending
        conflicts.sort(key=lambda c: c["score"], reverse=True)
        return conflicts

    def conflict_resolve(self, keep_id: str, supersede_id: str,
                         reason: str = "") -> bool:
        """Resolve a conflict by keeping keep_id and quarantining supersede_id.

        Args:
            keep_id: Node ID to keep as authoritative.
            supersede_id: Node ID to quarantine.
            reason: Optional reason for the resolution.

        Returns:
            True if both nodes existed and resolution was applied.
        """
        keep = self.conn.execute("SELECT id FROM nodes WHERE id=?", (keep_id,)).fetchone()
        sup = self.conn.execute("SELECT id FROM nodes WHERE id=?", (supersede_id,)).fetchone()
        if not keep or not sup:
            return False
        self.conn.execute(
            "UPDATE nodes SET quarantined=1, quarantine_reason=? WHERE id=?",
            (f"superseded by {keep_id}: {reason}", supersede_id)
        )
        self.conn.commit()
        self._tick("conflict_resolve", keep_id,
                   {"kept": keep_id, "superseded": supersede_id, "reason": reason})
        return True

    def conflict_report(self, conflicts: list[dict]) -> str:
        """Generate a human-readable conflict report.

        Args:
            conflicts: Output from conflict_detect()

        Returns:
            Formatted string suitable for logging or display.
        """
        if not conflicts:
            return "No memory conflicts detected. ✓"
        lines = [f"⚠️ {len(conflicts)} memory conflict(s) detected:\n"]
        for i, c in enumerate(conflicts, 1):
            lines.append(f"  {i}. [{c['type']}] score={c['score']}")
            lines.append(f"     A: \"{c['label_a']}\"")
            lines.append(f"     B: \"{c['label_b']}\"")
            if c.get('shared_entities'):
                lines.append(f"     Shared: {', '.join(c['shared_entities'])}")
            lines.append("")
        return "\n".join(lines)

    # ── Strategic Forget ──

    def strategic_forget(self, min_weight: float = None,
                         max_age_days: float = None,
                         protect_q_above: float = None,
                         kind: str = None,
                         target_count: int = None,
                         dry_run: bool = False) -> dict:
        """Deliberate, confidence-weighted forgetting.

        MemoryArena research insight: forgetting is the most under-appreciated
        memory operation. This method provides controlled, audited removal of
        low-value memories while protecting high-confidence ones.

        Args:
            min_weight: Forget nodes with weight below this.
            max_age_days: Forget nodes not accessed in this many days.
            protect_q_above: Never forget nodes with Q-value above this.
            kind: Only forget nodes of this kind.
            target_count: If set, forget lowest-value nodes until count remains.
            dry_run: If True, report without deleting.

        Returns:
            {forgotten, edges_removed, kept, details: [...]}
        """
        import time as _time
        now = _time.time()

        # Build candidate query
        sql = (
            "SELECT id, label, kind, weight, accessed, q_value FROM nodes "
            "WHERE (quarantined = 0 OR quarantined IS NULL)"
        )
        params = []
        if kind:
            sql += " AND kind=?"
            params.append(kind)
        # Exclude protected nodes
        if protect_q_above is not None:
            sql += " AND (q_value IS NULL OR q_value < ?)"
            params.append(protect_q_above)

        # Apply age/weight filters for candidate selection
        conditions = []
        if min_weight is not None:
            conditions.append("weight < ?")
            params.append(min_weight)
        if max_age_days is not None:
            cutoff = now - max_age_days * 86400
            conditions.append("accessed < ?")
            params.append(cutoff)

        if target_count is not None:
            # Need to forget down to target — select all, sort by value ascending
            sql += " ORDER BY q_value ASC, weight ASC, accessed ASC"
            rows = self.conn.execute(sql, params).fetchall()
            current_count = self.conn.execute(
                "SELECT COUNT(*) FROM nodes WHERE (quarantined=0 OR quarantined IS NULL)"
                + (" AND kind=?" if kind else ""),
                [kind] if kind else []
            ).fetchone()[0]
            to_forget = max(0, current_count - target_count)
            rows = rows[:to_forget]
        else:
            if conditions:
                sql += " AND " + " AND ".join(conditions)
            sql += " ORDER BY weight ASC, accessed ASC"
            rows = self.conn.execute(sql, params).fetchall()

        forgotten = []
        edges_removed = 0
        for row in rows:
            # Double-check protection
            if protect_q_above is not None and (row["q_value"] or 0) >= protect_q_above:
                continue
            node_id = row["id"]
            # Count edges that will be removed
            edge_count = self.conn.execute(
                "SELECT COUNT(*) FROM edges WHERE source=? OR target=?",
                (node_id, node_id)
            ).fetchone()[0]
            if not dry_run:
                self.conn.execute("DELETE FROM edges WHERE source=? OR target=?",
                                  (node_id, node_id))
                self._fts_delete_node(node_id)
                self.conn.execute("DELETE FROM nodes WHERE id=?", (node_id,))
                self._tick("strategic_forget", node_id,
                           {"label": row["label"], "weight": row["weight"],
                            "kind": row["kind"]})
            edges_removed += edge_count
            forgotten.append({
                "node_id": node_id,
                "label": row["label"],
                "kind": row["kind"],
                "weight": row["weight"],
                "q_value": row["q_value"] or 0.0,
            })

        if not dry_run:
            self.conn.commit()

        remaining = self.conn.execute(
            "SELECT COUNT(*) FROM nodes WHERE (quarantined=0 OR quarantined IS NULL)"
        ).fetchone()[0]

        return {
            "forgotten": len(forgotten),
            "edges_removed": edges_removed,
            "kept": remaining,
            "details": forgotten[:50],  # cap details for large forgets
        }

    # ── Community Detection (Label Propagation Algorithm) ──

    def _build_adjacency(self) -> dict[str, set[str]]:
        """Build undirected adjacency map from directed edges.

        Excludes quarantined nodes.
        """
        active_ids = {
            row["id"] for row in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0 OR quarantined IS NULL"
            ).fetchall()
        }
        adj: dict[str, set[str]] = defaultdict(set)
        for row in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = row["source"], row["target"]
            if s in active_ids and t in active_ids:
                adj[s].add(t)
                adj[t].add(s)
        for nid in active_ids:
            adj.setdefault(nid, set())
        return dict(adj)

    def detect_communities(self, max_iterations: int = 20, resolution: float = 1.0) -> dict:
        """Label Propagation Algorithm (LPA) for community detection.

        Assigns each node to a community by iteratively adopting the most
        frequent community label among its neighbors.  Converges when no
        node changes label in a full pass, or after *max_iterations*.

        Args:
            max_iterations: Maximum LPA iterations.
            resolution: Weight multiplier for same-kind nodes (higher
                values bias toward forming communities among nodes of the
                same kind).

        Returns dict with:
            - communities: {community_id: [node_id, ...]}
            - node_community: {node_id: community_id}
            - num_communities: int
            - iterations: int
            - modularity: float (Q-score, [−0.5, 1])
        """
        adj = self._build_adjacency()
        if not adj:
            return {"communities": {}, "node_community": {},
                    "num_communities": 0, "iterations": 0, "modularity": 0.0}

        node_ids = sorted(adj.keys())
        # Initialise: each node is its own community
        labels: dict[str, int] = {nid: i for i, nid in enumerate(node_ids)}
        # Pre-fetch kind for resolution bias
        kind_map: dict[str, str] = {}
        for row in self.conn.execute("SELECT id, kind FROM nodes").fetchall():
            kind_map[row["id"]] = row["kind"] or "unknown"

        iterations = 0
        changed = True
        while changed and iterations < max_iterations:
            changed = False
            iterations += 1
            for nid in node_ids:
                neighbors = adj[nid]
                if not neighbors:
                    continue
                # Vote: weighted label count
                votes: dict[int, float] = defaultdict(float)
                for nb in neighbors:
                    nb_label = labels[nb]
                    weight = resolution
                    if resolution != 1.0 and kind_map.get(nid) == kind_map.get(nb):
                        weight *= resolution  # same-kind boost
                    votes[nb_label] += weight
                if not votes:
                    continue
                # Pick the label with the highest vote (deterministic tie-break)
                best_label = max(votes, key=lambda lb: (votes[lb], -lb))
                if best_label != labels[nid]:
                    labels[nid] = best_label
                    changed = True

        # Relabel to consecutive integers starting from 0
        unique = sorted(set(labels.values()))
        remap = {old: new for new, old in enumerate(unique)}
        node_community = {nid: remap[labels[nid]] for nid in node_ids}

        # Group by community
        communities: dict[int, list[str]] = defaultdict(list)
        for nid, cid in node_community.items():
            communities[cid].append(nid)

        # Compute modularity Q
        modularity = self._modularity(adj, node_community, len(node_ids))

        # Cache results in instance for later lookups
        self._community_cache = {
            "node_community": node_community,
            "communities": dict(communities),
        }

        return {
            "communities": dict(communities),
            "node_community": node_community,
            "num_communities": len(communities),
            "iterations": iterations,
            "modularity": round(modularity, 4),
        }

    @staticmethod
    def _modularity(adj: dict[str, set[str]], labels: dict[str, int],
                    n: int) -> float:
        """Compute modularity Q for the current partition.

        Q = (1/2m) * Σ_ij [A_ij - k_i*k_j/(2m)] * δ(c_i, c_j)
        """
        if n == 0:
            return 0.0
        # Build degree map
        degree: dict[str, int] = {nid: len(nbrs) for nid, nbrs in adj.items()}
        two_m = sum(degree.values())  # 2m
        if two_m == 0:
            return 0.0
        # Sum over same-community pairs
        intra = 0.0
        for nid, nbrs in adj.items():
            for nb in nbrs:
                if labels.get(nid) == labels.get(nb):
                    intra += 1.0
        # intra now counts each edge twice (undirected)
        q = (intra / two_m) - sum(
            (degree[nid] / two_m) ** 2 for nid in degree
        )
        return q

    def community_of(self, node_id: str) -> Optional[int]:
        """Return the community ID for a node, or None if not assigned.

        Runs detect_communities() on first call and caches the result.
        """
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", None)
        if cache is None:
            return None
        return cache["node_community"].get(node_id)

    def community_members(self, community_id: int) -> list[Node]:
        """Return all nodes in a given community."""
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", {})
        ids = cache.get("communities", {}).get(community_id, [])
        nodes = []
        for nid in ids:
            node = self.get_node(nid)
            if node:
                nodes.append(node)
        return nodes

    def community_stats(self) -> list[dict]:
        """Return per-community statistics.

        Each dict contains:
            - community_id: int
            - size: int
            - kinds: {kind: count}
            - avg_weight: float
            - avg_q_value: float
            - internal_edges: int
            - total_edges: int
            - density: float (internal_edges / (size*(size-1)/2))
        """
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", {})
        node_community = cache.get("node_community", {})
        communities = cache.get("communities", {})
        if not communities:
            return []

        # Pre-load nodes
        all_nodes: dict[str, sqlite3.Row] = {
            r["id"]: r for r in self.conn.execute("SELECT * FROM nodes").fetchall()
        }
        # Pre-load edges
        all_edges = self.conn.execute("SELECT source, target FROM edges").fetchall()

        result = []
        for cid, members in sorted(communities.items()):
            member_set = set(members)
            kinds: dict[str, int] = defaultdict(int)
            weights = []
            q_values = []
            for nid in members:
                row = all_nodes.get(nid)
                if not row:
                    continue
                kinds[row["kind"] or "unknown"] += 1
                weights.append(row["weight"] or 0.0)
                q_values.append(row["q_value"] or 0.0)
            internal_edges = sum(
                1 for e in all_edges
                if e["source"] in member_set and e["target"] in member_set
            )
            total_edges = sum(
                1 for e in all_edges
                if e["source"] in member_set or e["target"] in member_set
            )
            size = len(members)
            max_internal = size * (size - 1) / 2 if size > 1 else 1
            result.append({
                "community_id": cid,
                "size": size,
                "kinds": dict(kinds),
                "avg_weight": round(sum(weights) / len(weights), 4) if weights else 0.0,
                "avg_q_value": round(sum(q_values) / len(q_values), 4) if q_values else 0.0,
                "internal_edges": internal_edges,
                "total_edges": total_edges,
                "density": round(internal_edges / max_internal, 4) if max_internal > 0 else 0.0,
            })
        return result

    def search_community(self, query: str, limit: int = 10) -> list[Node]:
        """Community-aware retrieval: find the best community first, then search within it.

        1. BM25 search across all nodes to find the top match.
        2. Identify its community.
        3. Search within that community (and optionally neighbors) for related nodes.

        Falls back to global search if no communities are detected.
        """
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", None)
        if cache is None or not cache.get("communities"):
            return self.recall(query, limit=limit)

        # Step 1: global BM25 to find seed
        seed_results = self.search_bm25(query, limit=1)
        if not seed_results:
            return self.recall(query, limit=limit)
        seed_id = seed_results[0]["node_id"]
        cid = cache["node_community"].get(seed_id)
        if cid is None:
            return self.recall(query, limit=limit)

        # Step 2: gather community members + adjacent communities
        member_ids = set(cache["communities"].get(cid, []))
        # Also include nodes from adjacent communities (1-hop neighbors)
        adj = self._build_adjacency()
        for mid in list(member_ids):
            for nb in adj.get(mid, []):
                member_ids.add(nb)

        # Step 3: BM25 within the community subset
        member_list = tuple(member_ids) if member_ids else ("__none__",)
        placeholders = ",".join("?" * len(member_list))
        if self._fts_enabled:
            sql = (
                f"SELECT n.id, n.label, n.kind, n.weight, "
                f"bm25(nodes_fts) AS score "
                f"FROM nodes_fts JOIN nodes n ON nodes_fts.node_id = n.id "
                f"WHERE nodes_fts MATCH ? AND n.id IN ({placeholders}) "
                f"ORDER BY score LIMIT ?"
            )
            try:
                rows = self.conn.execute(
                    sql, (query, *member_list, limit)
                ).fetchall()
            except sqlite3.OperationalError:
                # Fallback if FTS query syntax fails
                rows = []
        else:
            rows = []

        if not rows:
            # Fallback: filter by label LIKE
            like = f"%{query}%"
            sql = (
                f"SELECT id, label, kind, weight, 0 AS score FROM nodes "
                f"WHERE label LIKE ? AND id IN ({placeholders}) "
                f"ORDER BY weight DESC LIMIT ?"
            )
            rows = self.conn.execute(sql, (like, *member_list, limit)).fetchall()

        now = time.time()
        nodes = []
        for r in rows:
            self.conn.execute(
                "UPDATE nodes SET accessed=? WHERE id=?", (now, r["id"])
            )
            nodes.append(Node(r["id"], r["label"], r["kind"], {},
                              0, now, r["weight"] or 1.0))
        self.conn.commit()
        return nodes

    def community_graph(self) -> dict:
        """Build a reduced graph where each community is a supernode.

        Returns:
            - supernodes: [{community_id, size, dominant_kind, avg_weight}]
            - superedges: [{source, target, edges}]
        """
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", {})
        node_community = cache.get("node_community", {})
        communities = cache.get("communities", {})
        if not communities:
            return {"supernodes": [], "superedges": []}

        # Compute per-community aggregates
        stats = self.community_stats()
        supernodes = []
        for s in stats:
            dominant_kind = max(s["kinds"].items(), key=lambda x: x[1])[0] if s["kinds"] else "unknown"
            supernodes.append({
                "community_id": s["community_id"],
                "size": s["size"],
                "dominant_kind": dominant_kind,
                "avg_weight": s["avg_weight"],
                "density": s["density"],
            })

        # Build inter-community edge counts
        inter: dict[tuple[int, int], int] = defaultdict(int)
        for row in self.conn.execute("SELECT source, target FROM edges").fetchall():
            src_c = node_community.get(row["source"])
            tgt_c = node_community.get(row["target"])
            if src_c is not None and tgt_c is not None and src_c != tgt_c:
                key = (min(src_c, tgt_c), max(src_c, tgt_c))
                inter[key] += 1

        superedges = [
            {"source": s, "target": t, "edges": cnt}
            for (s, t), cnt in sorted(inter.items())
        ]
        return {"supernodes": supernodes, "superedges": superedges}

    def community_profile(self, community_id: int) -> dict:
        """Generate a structured deep-dive profile of a single community.

        Complements community_summary() (which returns an overview list).
        This method focuses on one community: its internal structure,
        bridge nodes, and cohesion score.

        Returns:
            - community_id: int
            - size: int
            - dominant_kind: str
            - representative_labels: list[str] (top-5 by weight)
            - kind_distribution: {kind: count}
            - avg_weight / avg_q_value: float
            - internal_relations: {relation: count} (edge types within)
            - bridge_nodes: list[{node_id, label, external_edges}]
            - cohesion: float (internal_edges / total_edges, [0, 1])
        """
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", {})
        communities = cache.get("communities", {})
        members = communities.get(community_id, [])
        if not members:
            return {}

        member_set = set(members)
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE id IN (%s) ORDER BY weight DESC" %
            ",".join("?" * len(members)), members
        ).fetchall()

        kinds: dict[str, int] = defaultdict(int)
        weights = []
        for r in rows:
            kinds[r["kind"] or "unknown"] += 1
            weights.append(r["weight"] or 0.0)

        dominant_kind = max(kinds.items(), key=lambda x: x[1])[0] if kinds else "unknown"
        representative = [r["label"] for r in rows[:5]]

        # Internal edge relations
        rel_counts: dict[str, int] = defaultdict(int)
        internal_edges = 0
        total_edges_for_community = 0
        edge_rows = self.conn.execute(
            "SELECT source, target, relation FROM edges WHERE source IN (%s) OR target IN (%s)" %
            (",".join("?" * len(members)), ",".join("?" * len(members))),
            members + members
        ).fetchall()
        for e in edge_rows:
            is_internal = e["source"] in member_set and e["target"] in member_set
            if is_internal:
                internal_edges += 1
                rel_counts[e["relation"]] += 1
            total_edges_for_community += 1

        # Bridge nodes: nodes with edges to other communities
        bridge_nodes = []
        for r in rows:
            outgoing = self.conn.execute(
                "SELECT target FROM edges WHERE source=?", (r["id"],)
            ).fetchall()
            incoming = self.conn.execute(
                "SELECT source FROM edges WHERE target=?", (r["id"],)
            ).fetchall()
            external = 0
            for o in outgoing:
                if o["target"] not in member_set:
                    external += 1
            for ic in incoming:
                if ic["source"] not in member_set:
                    external += 1
            if external > 0:
                bridge_nodes.append({
                    "node_id": r["id"],
                    "label": r["label"],
                    "external_edges": external,
                })
        bridge_nodes.sort(key=lambda b: b["external_edges"], reverse=True)

        cohesion = internal_edges / total_edges_for_community if total_edges_for_community > 0 else 0.0

        return {
            "community_id": community_id,
            "size": len(members),
            "dominant_kind": dominant_kind,
            "representative_labels": representative,
            "kind_distribution": dict(kinds),
            "avg_weight": round(sum(weights) / len(weights), 4) if weights else 0.0,
            "avg_q_value": round(
                sum(r["q_value"] or 0.0 for r in rows) / len(rows), 4
            ) if rows else 0.0,
            "internal_relations": dict(sorted(rel_counts.items(), key=lambda x: -x[1])),
            "bridge_nodes": bridge_nodes[:10],
            "cohesion": round(cohesion, 4),
        }

    def community_bridge_nodes(self) -> list[dict]:
        """Find all bridge nodes across all communities.

        A bridge node has edges to nodes in other communities.
        Returns list of {node_id, label, community_id, external_edges, external_communities}.
        """
        cache = getattr(self, "_community_cache", None)
        if cache is None:
            self.detect_communities()
            cache = getattr(self, "_community_cache", {})
        node_community = cache.get("node_community", {})
        if not node_community:
            return []

        bridges = []
        seen = set()
        for row in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = row["source"], row["target"]
            sc = node_community.get(s)
            tc = node_community.get(t)
            if sc is None or tc is None or sc == tc:
                continue
            for nid, cid, other in [(s, sc, tc), (t, tc, sc)]:
                if nid not in seen:
                    seen.add(nid)
                    # Count external edges and communities
                    ext_edges = 0
                    ext_comms = set()
                    for nb_row in self.conn.execute(
                        "SELECT target FROM edges WHERE source=? UNION "
                        "SELECT source FROM edges WHERE target=?",
                        (nid, nid)
                    ).fetchall():
                        nb_id = nb_row[0]
                        nb_c = node_community.get(nb_id)
                        if nb_c is not None and nb_c != cid:
                            ext_edges += 1
                            ext_comms.add(nb_c)
                    node_row = self.conn.execute(
                        "SELECT label FROM nodes WHERE id=?", (nid,)
                    ).fetchone()
                    bridges.append({
                        "node_id": nid,
                        "label": node_row["label"] if node_row else "",
                        "community_id": cid,
                        "external_edges": ext_edges,
                        "external_communities": sorted(ext_comms),
                    })
        bridges.sort(key=lambda b: b["external_edges"], reverse=True)
        return bridges

    def crystallize_intents(self, *, density_threshold: float = 0.5,
                           min_community_size: int = 3,
                           algorithm: str = "leiden") -> dict:
        """Crystallize implicit intents from community structure.

        Inspired by CogniFold (2026): when concept clusters reach sufficient
        density, they "crystallize" into explicit intent nodes. This creates
        a higher-level abstraction layer without manual labeling.

        For each community that exceeds ``density_threshold`` (internal
        edge density), creates an ``intent`` node linked to all member
        nodes via ``"abstracts"`` edges.

        Density = 2 * internal_edges / (size * (size - 1))

        Args:
            density_threshold:  Minimum internal density [0, 1] to crystallize.
            min_community_size: Minimum members to consider.
            algorithm:          Community detection algorithm.

        Returns:
            ``{crystallized: [...], skipped: [...], total_communities: int}``
            Each crystallized entry: ``{intent_id, label, community_id,
            size, density, dominant_kind, members}``
        """
        # Detect communities
        comm_result = self.community_detect()
        if not comm_result:
            return {"crystallized": [], "skipped": [], "total_communities": 0}

        # comm_result is {community_id: [member_ids]}
        communities = comm_result

        crystallized = []
        skipped = []

        for comm_id, members in communities.items():
            if len(members) < min_community_size:
                skipped.append({
                    "community_id": comm_id,
                    "size": len(members),
                    "reason": "too_small",
                })
                continue

            member_set = set(members)

            # Count internal edges
            placeholders = ",".join("?" * len(members))
            edge_rows = self.conn.execute(
                f"SELECT source, target FROM edges WHERE source IN ({placeholders}) "
                f"AND target IN ({placeholders})",
                members + members
            ).fetchall()
            internal_edges = len(edge_rows)
            size = len(members)
            max_possible = size * (size - 1)
            density = (2.0 * internal_edges / max_possible) if max_possible > 0 else 0.0

            if density < density_threshold:
                skipped.append({
                    "community_id": comm_id,
                    "size": size,
                    "density": round(density, 4),
                    "reason": "low_density",
                })
                continue

            # Get dominant kind and representative label
            node_rows = self.conn.execute(
                f"SELECT id, label, kind FROM nodes WHERE id IN ({placeholders})",
                members
            ).fetchall()
            kind_counts: dict[str, int] = defaultdict(int)
            labels = []
            non_intent_members = []
            for r in node_rows:
                kind_counts[r["kind"] or "unknown"] += 1
                if r["kind"] != "intent":
                    labels.append(r["label"])
                    non_intent_members.append(r["id"])
            dominant_kind = max(kind_counts.items(), key=lambda x: x[1])[0] if kind_counts else "unknown"

            # Create intent node
            # Label: combine top member labels
            top_labels = sorted(set(labels))[:3]
            intent_label = f"Intent: {', '.join(top_labels)}"

            # Check if we already crystallized this exact member set
            existing = self.conn.execute(
                "SELECT id FROM nodes WHERE kind='intent' AND label=?",
                (intent_label,)
            ).fetchone()
            if existing:
                skipped.append({
                    "community_id": comm_id,
                    "size": size,
                    "density": round(density, 4),
                    "reason": "already_crystallized",
                    "existing_intent": existing["id"],
                })
                continue

            intent_id = self.add(intent_label, "intent", {
                "source": "crystallize_intents",
                "community_id": str(comm_id),
                "density": round(density, 4),
                "member_count": size,
            }).id

            # Link intent to members
            for member_id in members:
                self.link(intent_id, member_id, "abstracts")

            crystallized.append({
                "intent_id": intent_id,
                "label": intent_label,
                "community_id": comm_id,
                "size": size,
                "density": round(density, 4),
                "dominant_kind": dominant_kind,
                "members": members,
            })

        return {
            "crystallized": crystallized,
            "skipped": skipped,
            "total_communities": len(communities),
        }

    # ─── Proactive Context (CogniFold) ─────────────────────────────────
    # Instead of waiting for a query, use crystallized intent nodes to
    # proactively surface relevant memory.  CogniFold (2605.13438) showed
    # that goal-directed context assembly outperforms reactive retrieval.

    def read_proactive_context(
        self,
        *,
        active_intents: list[str] | None = None,
        top_k: int = 10,
        min_temperature: float = 0.1,
        include_intents: bool = True,
    ) -> dict:
        """Proactively surface memory relevant to current active intents.

        CogniFold-inspired (2605.13438): instead of reactive retrieval
        (waiting for a user query), the graph *pushes* context that is
        likely relevant given the currently crystallized intent nodes.

        Pipeline:
            1. Identify intent nodes (kind='intent').
            2. If *active_intents* is given, filter / rank to those.
            3. For each intent, gather abstracted member nodes.
            4. Score members by cache_temperature + weight.
            5. Deduplicate, return top-k as a context bundle.

        Args:
            active_intents:   Optional list of intent node IDs or label
                              substrings to focus on.  If ``None``, all
                              intent nodes are considered.
            top_k:            Maximum member nodes to return.
            min_temperature:  Exclude nodes below this temperature.
            include_intents:  Include intent node metadata in output.

        Returns:
            ``{contexts: [{intent_id, label, density, members: [...]}],
                         total_intents: int, total_nodes: int}``
        """
        # 1. Gather intent nodes
        intent_rows = self.conn.execute(
            "SELECT id, label, data FROM nodes WHERE kind='intent' AND quarantined = 0"
        ).fetchall()
        if not intent_rows or top_k <= 0:
            return {"contexts": [], "total_intents": 0, "total_nodes": 0}

        # 2. Filter by active_intents if provided
        if active_intents:
            filtered = []
            intent_ids_set = set()
            for spec in active_intents:
                # Could be an exact node ID or a label substring
                matches = self.conn.execute(
                    "SELECT id, label, data FROM nodes WHERE kind='intent' "
                    "AND (id = ? OR label LIKE ?) AND quarantined = 0",
                    (spec, f"%{spec}%"),
                ).fetchall()
                for m in matches:
                    if m["id"] not in intent_ids_set:
                        filtered.append(m)
                        intent_ids_set.add(m["id"])
            intent_rows = filtered
            if not intent_rows:
                return {"contexts": [], "total_intents": 0, "total_nodes": 0}

        # 3. For each intent, gather members via 'abstracts' edges
        scored: list[tuple[float, str, str, str, float]] = []
        # (temperature, node_id, label, kind, intent_id) — sorted later
        intent_meta: dict[str, dict] = {}

        for ir in intent_rows:
            intent_id = ir["id"]
            data = json.loads(ir["data"]) if ir["data"] else {}
            intent_meta[intent_id] = {
                "intent_id": intent_id,
                "label": ir["label"],
                "density": data.get("density", 0.0),
                "member_count": data.get("member_count", 0),
            }

            # Find members linked via 'abstracts'
            member_rows = self.conn.execute(
                "SELECT target FROM edges WHERE source = ? AND relation = 'abstracts'",
                (intent_id,),
            ).fetchall()
            seen = set()
            for mr in member_rows:
                mid = mr["target"]
                if mid in seen or mid == intent_id:
                    continue
                seen.add(mid)
                node_row = self.conn.execute(
                    "SELECT id, label, kind, weight, accessed, q_value, quarantined "
                    "FROM nodes WHERE id = ?",
                    (mid,),
                ).fetchone()
                if node_row is None or node_row["quarantined"]:
                    continue
                # Compute temperature inline (avoid extra call overhead)
                now = time.time()
                age = max(now - (node_row["accessed"] or now), 0)
                recency = math.exp(-age / 604800.0)
                weight_n = min(max(node_row["weight"] or 0.0, 0.0), 2.0) / 2.0
                q_norm = max(0.0, min(1.0, (node_row["q_value"] or 0.0)))
                temp = round(recency * 0.5 + weight_n * 0.3 + q_norm * 0.2, 4)
                if temp < min_temperature:
                    continue
                scored.append(
                    (temp, mid, node_row["label"], node_row["kind"] or "unknown", intent_id)
                )

        # 4. Sort by temperature descending, deduplicate node_ids
        scored.sort(key=lambda t: t[0], reverse=True)
        seen_ids: set[str] = set()
        top_members: list[dict] = []
        member_to_intents: dict[str, list[str]] = defaultdict(list)

        for temp, nid, label, kind, iid in scored:
            member_to_intents[nid].append(iid)
            if nid in seen_ids:
                continue
            seen_ids.add(nid)
            top_members.append({
                "node_id": nid,
                "label": label,
                "kind": kind,
                "temperature": temp,
                "linked_intents": member_to_intents[nid],
            })
            if len(top_members) >= top_k:
                break

        # 5. Build per-intent context groups
        contexts = []
        for iid, meta in intent_meta.items():
            members = [m for m in top_members if iid in m["linked_intents"]]
            if not members and not include_intents:
                continue
            entry = {
                "intent_id": iid,
                "label": meta["label"],
                "density": meta["density"],
                "member_count": meta["member_count"],
                "members": members,
            }
            contexts.append(entry)

        # Sort contexts by number of surfaced members (most useful first)
        contexts.sort(key=lambda c: len(c["members"]), reverse=True)

        if not include_intents:
            # Strip member metadata, just return nodes
            for c in contexts:
                c.pop("density", None)
                c.pop("member_count", None)

        return {
            "contexts": contexts,
            "total_intents": len(intent_meta),
            "total_nodes": len(top_members),
        }

    # ─── Cache Temperature ─────────────────────────────────────────────
    # CPU-cache-inspired memory temperature: hot/warm/cold zones.
    # Temperature = f(recency, access_count, weight, q_value)

    def cache_temperature(self, node_id: str) -> float:
        """Return cache temperature score [0, 1] for a node.

        Combines recency, weight, and Q-value into a single 0-1
        temperature where 1 = hot (likely needed soon), 0 = cold.
        """
        row = self.conn.execute(
            "SELECT weight, accessed, q_value FROM nodes WHERE id=?",
            (node_id,)
        ).fetchone()
        if row is None:
            return 0.0
        now = time.time()
        age = max(now - (row["accessed"] or now), 0)
        recency = math.exp(-age / 604800.0)  # half-life ~7 days
        weight = min(max(row["weight"] or 0.0, 0.0), 2.0) / 2.0
        q_norm = max(0.0, min(1.0, (row["q_value"] or 0.0)))
        return round(recency * 0.5 + weight * 0.3 + q_norm * 0.2, 4)

    def cache_snapshot(self) -> dict:
        """Return a cache-temperature snapshot of the entire graph.

        Partitions nodes into hot (>0.66), warm (0.33-0.66), cold (<0.33).
        """
        rows = self.conn.execute(
            "SELECT id, label, kind, weight, accessed, q_value FROM nodes WHERE quarantined = 0"
        ).fetchall()
        now = time.time()
        hot, warm, cold = [], [], []
        for r in rows:
            age = max(now - (r["accessed"] or now), 0)
            recency = math.exp(-age / 604800.0)
            weight_n = min(max(r["weight"] or 0.0, 0.0), 2.0) / 2.0
            q_norm = max(0.0, min(1.0, (r["q_value"] or 0.0)))
            temp = round(recency * 0.5 + weight_n * 0.3 + q_norm * 0.2, 4)
            entry = {
                "node_id": r["id"], "label": r["label"],
                "kind": r["kind"], "temperature": temp,
            }
            if temp > 0.66:
                hot.append(entry)
            elif temp > 0.33:
                warm.append(entry)
            else:
                cold.append(entry)
        hot.sort(key=lambda e: e["temperature"], reverse=True)
        warm.sort(key=lambda e: e["temperature"], reverse=True)
        cold.sort(key=lambda e: e["temperature"])
        return {
            "hot_count": len(hot),
            "warm_count": len(warm),
            "cold_count": len(cold),
            "total": len(rows),
            "hot": hot,
            "warm": warm,
            "cold": cold,
        }

    def warm_cache(self, query: str, limit: int = 10) -> int:
        """Pre-warm memories matching a search query.

        Boosts accessed timestamp and slightly bumps weight for
        matched nodes. Returns count of warmed nodes.
        """
        results = self.recall(query, limit=limit)
        now = time.time()
        count = 0
        for node in results:
            self.conn.execute(
                "UPDATE nodes SET accessed = ?, weight = MIN(weight + 0.05, 2.0) WHERE id = ?",
                (now, node.id)
            )
            self._tick("update", node.id, {"action": "warm_cache"})
            count += 1
        self.conn.commit()
        return count

    def evict_cold(self, max_temperature: float = 0.15, min_age_hours: float = 48.0,
                   dry_run: bool = False) -> list[str]:
        """Evict (quarantine) nodes below a temperature threshold.

        Only evicts nodes that are both cold AND old. Q-value > 0.5
        nodes are protected. Returns list of evicted node IDs.
        """
        snapshot = self.cache_snapshot()
        now = time.time()
        cutoff = now - min_age_hours * 3600
        candidates = []
        for entry in snapshot["cold"]:
            if entry["temperature"] > max_temperature:
                continue
            row = self.conn.execute(
                "SELECT accessed, q_value FROM nodes WHERE id = ?",
                (entry["node_id"],)
            ).fetchone()
            if row is None:
                continue
            if (row["accessed"] or now) > cutoff:
                continue
            if (row["q_value"] or 0.0) > 0.5:
                continue
            candidates.append(entry["node_id"])
        if not dry_run:
            for nid in candidates:
                self.conn.execute(
                    "UPDATE nodes SET quarantined = 1, quarantine_reason = ? WHERE id = ?",
                    (f"cache_eviction: temp <= {max_temperature}", nid)
                )
            self.conn.commit()
            for nid in candidates:
                self._tick("update", nid, {"action": "evict_cold"})
        return candidates

    # ─── Memorywire Compatibility ─────────────────────────────────────

    def to_memorywire_format(self, include_quarantined: bool = False) -> dict:
        """Export graph in Memorywire-compatible JSON format.

        Memorywire is a memory exchange format with nodes (memories),
        edges (associations), and metadata. This enables interoperability
        with other memory systems.

        Schema:
            {
              "format": "memorywire/v1",
              "exported_at": <epoch>,
              "stats": {nodes, edges, kinds},
              "memories": [{id, label, kind, data, weight, q_value, ...}],
              "associations": [{source, target, relation, weight}]
            }
        """
        node_filter = "WHERE quarantined = 0" if not include_quarantined else ""
        nodes = self.conn.execute(
            f"SELECT id, label, kind, data, created, accessed, weight, "
            f"q_value, valid_from, valid_to, quarantined "
            f"FROM nodes {node_filter}"
        ).fetchall()
        edges = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges"
        ).fetchall()
        kind_counts: dict[str, int] = {}
        for n in nodes:
            kind_counts[n["kind"]] = kind_counts.get(n["kind"], 0) + 1
        return {
            "format": "memorywire/v1",
            "exported_at": time.time(),
            "stats": {
                "nodes": len(nodes),
                "edges": len(edges),
                "kinds": kind_counts,
            },
            "memories": [{
                "id": n["id"],
                "label": n["label"],
                "kind": n["kind"],
                "data": json.loads(n["data"]),
                "created": n["created"],
                "accessed": n["accessed"],
                "weight": n["weight"],
                "q_value": n["q_value"],
                "valid_from": n["valid_from"],
                "valid_to": n["valid_to"],
                "quarantined": bool(n["quarantined"]),
            } for n in nodes],
            "associations": [{
                "source": e["source"],
                "target": e["target"],
                "relation": e["relation"],
                "weight": e["weight"],
            } for e in edges],
        }

    def from_memorywire_format(self, data: dict) -> int:
        """Import a Memorywire-format dict into this graph.

        Adds all memories and associations from the import. Returns
        the number of memories imported.
        """
        if data.get("format") != "memorywire/v1":
            raise ValueError(f"Unsupported format: {data.get('format')}")
        count = 0
        id_map: dict[str, str] = {}  # original_id → new_id
        for mem in data.get("memories", []):
            node = self.add(
                label=mem["label"],
                kind=mem.get("kind", "fact"),
                data=mem.get("data", {}),
            )
            id_map[mem["id"]] = node.id
            # Preserve metadata
            updates = {}
            if "weight" in mem:
                updates["weight"] = mem["weight"]
            if updates:
                self.conn.execute(
                    "UPDATE nodes SET weight = ? WHERE id = ?",
                    (updates["weight"], node.id)
                )
            count += 1
        # Import edges
        for assoc in data.get("associations", []):
            src = id_map.get(assoc["source"])
            tgt = id_map.get(assoc["target"])
            if src and tgt:
                self.link(src, tgt, assoc.get("relation", "related_to"))
        self.conn.commit()
        return count

    # ─── Scope-Delete Guard ────────────────────────────────────────────

    def delete_node_safe(self, node_id: str, force: bool = False) -> dict:
        """Delete a node with scope-delete guard.

        Prevents accidental deletion of nodes that have dependents
        (edges pointing TO this node from non-quarantined nodes).
        Use force=True to override.

        Returns dict with keys: deleted (bool), blocked_by (list of
        dependent node labels), reason (str).
        """
        row = self.conn.execute(
            "SELECT id, label FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return {"deleted": False, "blocked_by": [], "reason": "not_found"}
        # Find dependents: nodes with edges pointing TO this node
        dependents = self.conn.execute(
            "SELECT DISTINCT e.source, n.label FROM edges e "
            "JOIN nodes n ON e.source = n.id "
            "WHERE e.target = ? AND n.quarantined = 0 AND e.source != ?",
            (node_id, node_id)
        ).fetchall()
        if dependents and not force:
            return {
                "deleted": False,
                "blocked_by": [d["label"] for d in dependents],
                "reason": f"{len(dependents)} dependent node(s) reference this memory",
            }
        self.delete_node(node_id)
        return {"deleted": True, "blocked_by": [], "reason": "ok"}



    # ─── Temporal Staleness Scoring ──────────────────────────────────

    def staleness_score(self, node_id: str) -> float:
        """Return staleness score [0, 1] where 0 = fresh, 1 = fully stale.

        Inspired by Mem0's temporal degradation finding:
        benchmark 91.6 → 49.0% after 30 days in production.

        Combines:
        - Age decay (40%): exponential with 30-day half-life
        - Access recency (35%): how recently the node was accessed
        - Validity gap (25%): if bi-temporal valid_to is in the past
        """
        row = self.conn.execute(
            "SELECT created, accessed, valid_from, valid_to FROM nodes WHERE id=?",
            (node_id,)
        ).fetchone()
        if row is None:
            return 1.0
        now = time.time()
        # Age component: 30-day half-life
        age_seconds = max(now - (row["created"] or now), 0)
        age_staleness = 1.0 - math.exp(-age_seconds / 2592000.0)  # 30-day half-life
        # Access recency: 7-day half-life
        access_age = max(now - (row["accessed"] or row["created"] or now), 0)
        access_staleness = 1.0 - math.exp(-access_age / 604800.0)  # 7-day half-life
        # Validity gap: if valid_to is set and in the past
        validity_staleness = 0.0
        if row["valid_to"] is not None:
            vt = row["valid_to"]
            if isinstance(vt, str):
                vt = datetime.fromisoformat(vt.replace("Z", "+00:00")).timestamp()
            if vt < now:
                validity_staleness = 1.0
            else:
                # Approaching expiry
                time_left = vt - now
                if time_left < 604800:  # within 7 days
                    validity_staleness = 1.0 - (time_left / 604800.0)
        return round(
            age_staleness * 0.40 + access_staleness * 0.35 + validity_staleness * 0.25, 4
        )

    def stale_nodes(self, threshold: float = 0.7, limit: int = 100) -> list[dict]:
        """Return nodes with staleness >= threshold, most stale first.

        Args:
            threshold: Minimum staleness to include [0, 1]
            limit: Maximum nodes to return

        Returns:
            List of {node_id, label, kind, staleness, created, accessed}
        """
        rows = self.conn.execute(
            "SELECT id, label, kind, created, accessed FROM nodes WHERE quarantined = 0"
        ).fetchall()
        result = []
        for r in rows:
            s = self.staleness_score(r["id"])
            if s >= threshold:
                result.append({
                    "node_id": r["id"], "label": r["label"],
                    "kind": r["kind"], "staleness": s,
                    "created": r["created"], "accessed": r["accessed"],
                })
        result.sort(key=lambda x: x["staleness"], reverse=True)
        return result[:limit]

    def fresh_nodes(self, threshold: float = 0.3, limit: int = 100) -> list[dict]:
        """Return nodes with staleness <= threshold, most fresh first.

        Args:
            threshold: Maximum staleness to include [0, 1]
            limit: Maximum nodes to return

        Returns:
            List of {node_id, label, kind, staleness, created, accessed}
        """
        rows = self.conn.execute(
            "SELECT id, label, kind, created, accessed FROM nodes WHERE quarantined = 0"
        ).fetchall()
        result = []
        for r in rows:
            s = self.staleness_score(r["id"])
            if s <= threshold:
                result.append({
                    "node_id": r["id"], "label": r["label"],
                    "kind": r["kind"], "staleness": s,
                    "created": r["created"], "accessed": r["accessed"],
                })
        result.sort(key=lambda x: x["staleness"])
        return result[:limit]

    def refresh_node(self, node_id: str) -> bool:
        """Refresh a stale node by updating its access timestamp.

        Returns True if node was found and refreshed, False otherwise.
        """
        row = self.conn.execute(
            "SELECT id FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if row is None:
            return False
        now = time.time()
        self.conn.execute(
            "UPDATE nodes SET accessed=? WHERE id=?", (now, node_id)
        )
        self.conn.commit()
        self._tick("update", node_id, {"action": "refresh"})
        return True

    def temporal_score(self, node_id: str, *, query_time: float | None = None,
                       alpha: float = 0.5, half_life_days: float = 30.0) -> dict:
        """Continuous temporal relevance score inspired by RoMem (2026).

        Instead of binary stale/fresh, models temporal relevance as a
        continuous score in [0, 1] using an exponential decay function.

        The ``alpha`` parameter controls the sharpness of decay:
        - ``alpha ≈ 0``: nearly flat — temporal info barely matters
        - ``alpha ≈ 0.5``: moderate decay (default)
        - ``alpha ≈ 1.0``: aggressive decay — old items rapidly irrelevant

        This mirrors RoMem's insight that different relationship types have
        different volatility: static facts (α≈0) never decay, while volatile
        facts (α≈0.85) rotate out of phase quickly.

        Returns a dict with:
        - ``temporal_score``: composite score [0, 1] (1 = perfectly timely)
        - ``age_component``: exponential age decay
        - ``access_component``: access recency decay
        - ``validity_component``: bi-temporal validity factor
        - ``alpha``: the sharpness parameter used
        - ``age_days``: age of the node in days

        Args:
            node_id:       Node to score.
            query_time:    Reference timestamp (default: now).
            alpha:         Decay sharpness [0, 1].
            half_life_days: Half-life for age decay in days.

        Returns:
            Dict with temporal scoring breakdown, or ``{"temporal_score": 0.0}``
            if node not found.
        """
        row = self.conn.execute(
            "SELECT created, accessed, valid_from, valid_to FROM nodes WHERE id=?",
            (node_id,)
        ).fetchone()
        if row is None:
            return {"temporal_score": 0.0, "not_found": True}

        now = query_time if query_time is not None else time.time()
        half_life_seconds = half_life_days * 86400.0

        # Age component: exponential decay with configurable half-life
        age_seconds = max(now - (row["created"] or now), 0)
        age_component = math.exp(-alpha * age_seconds / half_life_seconds)

        # Access recency: 7-day half-life, scaled by alpha
        access_age = max(now - (row["accessed"] or row["created"] or now), 0)
        access_component = math.exp(-alpha * access_age / 604800.0)

        # Validity component: bi-temporal window
        validity_component = 1.0
        if row["valid_to"] is not None:
            vt = row["valid_to"]
            if isinstance(vt, str):
                from datetime import datetime as _dt
                vt = _dt.fromisoformat(vt.replace("Z", "+00:00")).timestamp()
            if vt < now:
                validity_component = 0.0  # expired
            else:
                time_left = vt - now
                if time_left < 604800:  # within 7 days of expiry
                    validity_component = time_left / 604800.0

        # Composite: weighted geometric-ish mean
        composite = (
            age_component ** 0.40 *
            access_component ** 0.35 *
            validity_component ** 0.25
        )

        return {
            "temporal_score": round(composite, 4),
            "age_component": round(age_component, 4),
            "access_component": round(access_component, 4),
            "validity_component": round(validity_component, 4),
            "alpha": alpha,
            "age_days": round(age_seconds / 86400.0, 2),
        }

    # ─── Multi-Path Retrieval Fusion ───────────────────────────────────

    def search_multi(self, query: str, limit: int = 10,
                     paths: list[str] = None,
                     weights: dict[str, float] = None) -> list[dict]:
        """Multi-path retrieval with Reciprocal Rank Fusion (RRF).

        Combines multiple retrieval strategies and fuses their rankings.
        Research insight (MemRL, ICLR 2026): usefulness ≠ similarity —
        different retrieval paths capture different aspects of relevance.

        Available paths:
        - "bm25": label text matching (recall)
        - "q_value": Q-value ranking (top_q_nodes)
        - "community": community-aware retrieval (search_community)
        - "temperature": cache temperature ranking

        Args:
            query: Search query
            limit: Final number of results
            paths: List of paths to use (default: all available)
            weights: Per-path weight overrides {path: weight}

        Returns:
            List of {node_id, label, kind, fused_score, sources} sorted by fused score
        """
        if paths is None:
            paths = ["bm25", "q_value", "community", "temperature"]
        if weights is None:
            weights = {}

        k = 60  # RRF constant
        rrf_scores: dict[str, float] = {}
        node_sources: dict[str, set] = {}
        node_info: dict[str, dict] = {}

        for path_name in paths:
            path_weight = weights.get(path_name, 1.0)
            ranked: list[str] = []

            if path_name == "bm25":
                results = self.recall(query, limit=limit * 3)
                ranked = [n.id for n in results]
            elif path_name == "q_value":
                results = self.recall_with_q(query, limit=limit * 3)
                ranked = [r["node_id"] for r in results]
            elif path_name == "community":
                try:
                    results = self.search_community(query, limit=limit * 3)
                    ranked = [n.id for n in results]
                except Exception:
                    pass
            elif path_name == "temperature":
                snapshot = self.cache_snapshot()
                for entry in snapshot["hot"] + snapshot["warm"]:
                    ranked.append(entry["node_id"])

            for rank, nid in enumerate(ranked):
                rrf = path_weight / (k + rank + 1)
                rrf_scores[nid] = rrf_scores.get(nid, 0.0) + rrf
                node_sources.setdefault(nid, set()).add(path_name)
                if nid not in node_info:
                    node = self.get_node(nid)
                    if node:
                        node_info[nid] = {
                            "label": node.label,
                            "kind": node.kind,
                        }

        fused = []
        for nid, score in rrf_scores.items():
            info = node_info.get(nid, {})
            fused.append({
                "node_id": nid,
                "label": info.get("label", ""),
                "kind": info.get("kind", ""),
                "fused_score": round(score, 6),
                "sources": sorted(node_sources[nid]),
            })
        fused.sort(key=lambda x: x["fused_score"], reverse=True)
        return fused[:limit]

    # ─── Memory Sleep Consolidation ───────────────────────────────────

    def sleep_consolidate(self, similarity_threshold: float = 0.6,
                          min_weight: float = 0.3,
                          dry_run: bool = False) -> dict:
        """Consolidate memories by merging similar low-weight nodes.

        Inspired by biological sleep-time memory consolidation:
        - Weak memories with high overlap are merged into a single stronger node
        - Preserves the strongest node in each cluster as the 'anchor'
        - Edge relationships from merged nodes are redirected to anchor

        This is a destructive operation (unless dry_run=True) — merged nodes
        are quarantined, not deleted, preserving audit trail.

        Args:
            similarity_threshold: Minimum label similarity to merge [0, 1]
            min_weight: Only merge nodes below this weight
            dry_run: Report without executing

        Returns:
            {scanned, merged, kept, details}
        """
        import difflib

        rows = self.conn.execute(
            "SELECT id, label, kind, weight FROM nodes "
            "WHERE quarantined = 0 AND weight < ?",
            (min_weight,)
        ).fetchall()

        if len(rows) < 2:
            return {"scanned": len(rows), "merged": 0, "kept": len(rows),
                    "details": []}

        # Group by kind first for efficiency
        kind_groups: dict[str, list] = {}
        for r in rows:
            kind_groups.setdefault(r["kind"], []).append(r)

        result = {"scanned": len(rows), "merged": 0, "kept": 0, "details": []}
        merged_ids: set = set()

        for kind, group in kind_groups.items():
            for i, base in enumerate(group):
                if base["id"] in merged_ids:
                    continue
                cluster = [base]
                for candidate in group[i + 1:]:
                    if candidate["id"] in merged_ids:
                        continue
                    sim = difflib.SequenceMatcher(
                        None, base["label"].lower(), candidate["label"].lower()
                    ).ratio()
                    if sim >= similarity_threshold:
                        cluster.append(candidate)

                if len(cluster) < 2:
                    result["kept"] += 1
                    continue

                # Pick anchor: highest weight
                anchor = max(cluster, key=lambda r: r["weight"] or 0.0)
                merged_weight = sum(r["weight"] or 0.0 for r in cluster)

                if not dry_run:
                    for node in cluster:
                        if node["id"] == anchor["id"]:
                            continue
                        # Redirect edges to anchor
                        self.conn.execute(
                            "UPDATE edges SET source=? WHERE source=?",
                            (anchor["id"], node["id"])
                        )
                        self.conn.execute(
                            "UPDATE edges SET target=? WHERE target=?",
                            (anchor["id"], node["id"])
                        )
                        # Quarantine merged node
                        self.conn.execute(
                            "UPDATE nodes SET quarantined=1, weight=0.0 WHERE id=?",
                            (node["id"],)
                        )
                        self._tick("update", node["id"], {
                            "action": "consolidate_merge",
                            "anchor": anchor["id"],
                        })
                        merged_ids.add(node["id"])

                    # Boost anchor weight
                    self.conn.execute(
                        "UPDATE nodes SET weight=? WHERE id=?",
                        (merged_weight, anchor["id"])
                    )
                    self._tick("update", anchor["id"], {
                        "action": "consolidate_anchor",
                        "absorbed": len(cluster) - 1,
                    })

                result["merged"] += len(cluster) - 1
                result["kept"] += 1
                result["details"].append({
                    "anchor_id": anchor["id"],
                    "anchor_label": anchor["label"],
                    "merged_labels": [r["label"] for r in cluster if r["id"] != anchor["id"]],
                    "combined_weight": round(merged_weight, 4),
                })

        self.conn.commit()
        return result


    # ── Episodic Memory Replay ────────────────────────────

    def retrieve_episodes(self, start_time: float = None, end_time: float = None,
                           kind: str = None, node_id: str = None,
                           limit: int = 20) -> list[dict]:
        """Reconstruct temporal sequences of memories (episodes).

        Retrieves nodes ordered by creation time within a time window,
        optionally filtered by kind or anchored to a specific node's
        neighborhood. Each episode entry includes the node and its
        temporal distance from the previous node in the sequence.

        Inspired by episodic memory replay in biological systems —
        the ability to re-experience a sequence of events in order.

        Args:
            start_time: Unix timestamp lower bound (inclusive). Default: all.
            end_time: Upper bound (inclusive). Default: now.
            kind: Filter by node kind (e.g. 'event', 'fact').
            node_id: If provided, only include nodes within 2-hop neighborhood.
            limit: Maximum episodes to return.

        Returns:
            List of dicts: {node, prev_gap_seconds, cumulative_seconds}
        """
        now = time.time()
        if end_time is None:
            end_time = now
        if start_time is None:
            start_time = 0.0

        # Build neighborhood filter if node_id provided
        neighbor_ids = None
        if node_id:
            neighbor_ids = {node_id}
            # 1-hop neighbors
            rows = self.conn.execute(
                "SELECT DISTINCT target FROM edges WHERE source=? "
                "UNION SELECT DISTINCT source FROM edges WHERE target=?",
                (node_id, node_id)
            ).fetchall()
            neighbor_ids.update(r[0] for r in rows)
            # 2-hop neighbors
            for r in rows:
                nid = r[0]
                r2 = self.conn.execute(
                    "SELECT DISTINCT target FROM edges WHERE source=? "
                    "UNION SELECT DISTINCT source FROM edges WHERE target=?",
                    (nid, nid)
                ).fetchall()
                neighbor_ids.update(x[0] for x in r2)

        conditions = ["created >= ?", "created <= ?", "quarantined = 0"]
        params = [start_time, end_time]
        if kind:
            conditions.append("kind = ?")
            params.append(kind)
        if neighbor_ids is not None:
            placeholders = ','.join('?' * len(neighbor_ids))
            conditions.append(f"id IN ({placeholders})")
            params.extend(list(neighbor_ids))

        where_clause = " AND ".join(conditions)
        params.append(limit)
        rows = self.conn.execute(
            f"SELECT * FROM nodes WHERE {where_clause} ORDER BY created ASC LIMIT ?",
            params
        ).fetchall()

        episodes = []
        prev_time = None
        cumulative = 0.0
        for row in rows:
            node = Node(row["id"], row["label"], row["kind"],
                        json.loads(row["data"]), row["created"],
                        row["accessed"], row["weight"])
            gap = (node.created - prev_time) if prev_time is not None else 0.0
            cumulative += gap
            episodes.append({
                "node": node,
                "prev_gap_seconds": round(gap, 3),
                "cumulative_seconds": round(cumulative, 3),
            })
            prev_time = node.created
        return episodes

    def episode_timeline(self, episodes: list[dict] = None,
                         start_time: float = None, end_time: float = None,
                         kind: str = None) -> str:
        """Format episodes as a human-readable timeline.

        If episodes not provided, calls retrieve_episodes() with the
        given filters. Returns a formatted string with timestamps,
        temporal gaps, and node labels.
        """
        if episodes is None:
            episodes = self.retrieve_episodes(
                start_time=start_time, end_time=end_time, kind=kind, limit=50
            )
        if not episodes:
            return "(empty timeline)"

        lines = []
        for ep in episodes:
            node = ep["node"]
            ts = datetime.fromtimestamp(node.created).strftime("%Y-%m-%d %H:%M:%S")
            gap = ep["prev_gap_seconds"]
            gap_str = f" (+{gap:.0f}s)" if gap > 0 and gap < 3600 else (
                f" (+{gap/3600:.1f}h)" if gap >= 3600 and gap < 86400 else (
                    f" (+{gap/86400:.1f}d)" if gap >= 86400 else ""
                )
            )
            lines.append(f"  {ts}{gap_str} [{node.kind}] {node.label} (w={node.weight:.2f})")
        return "\n".join(lines)

    def replay_from(self, node_id: str, direction: str = "forward",
                    hops: int = 3, limit: int = 15) -> list[dict]:
        """Replay memories starting from a specific node, traversing edges.

        Traverses the graph from node_id either forward (outgoing edges)
        or backward (incoming edges), collecting nodes in temporal order.
        Each hop level is tracked. Useful for 'how did I get here?' or
        'what happened next?' queries.

        Args:
            node_id: Starting node.
            direction: 'forward' (outgoing edges) or 'backward' (incoming).
            hops: Maximum traversal depth.
            limit: Maximum nodes to return.

        Returns:
            List of dicts: {node, hop, edge_relation, prev_node_id}
        """
        if direction not in ("forward", "backward"):
            raise ValueError("direction must be 'forward' or 'backward'")

        visited = {node_id}
        results = []
        frontier = [(node_id, 0, None, None)]  # (id, hop, relation, prev_id)

        while frontier and len(results) < limit:
            curr_id, hop, relation, prev_id = frontier.pop(0)
            # Skip quarantined nodes entirely (don't expand or include)
            if self._is_quarantined(curr_id) and curr_id != node_id:
                continue
            if hop > 0:  # Don't include the starting node itself
                node = self.get_node(curr_id)
                if node and not self._is_quarantined(curr_id):
                    results.append({
                        "node": node,
                        "hop": hop,
                        "edge_relation": relation,
                        "prev_node_id": prev_id,
                    })
                    visited.add(curr_id)
            if hop >= hops:
                continue

            if direction == "forward":
                edges = self.conn.execute(
                    "SELECT target, relation FROM edges WHERE source=?", (curr_id,)
                ).fetchall()
            else:
                edges = self.conn.execute(
                    "SELECT source, relation FROM edges WHERE target=?", (curr_id,)
                ).fetchall()

            for edge in edges:
                neighbor_id = edge[0]
                if neighbor_id not in visited:
                    frontier.append((neighbor_id, hop + 1, edge["relation"], curr_id))

        # Sort by creation time for temporal replay
        results.sort(key=lambda r: r["node"].created)
        return results

    def _is_quarantined(self, node_id: str) -> bool:
        """Check if a node is quarantined."""
        row = self.conn.execute(
            "SELECT quarantined FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        return row is not None and row[0] == 1

    # ── Graph Analytics ─────────────────────────────────────

    def graph_analytics(self) -> dict:
        """Comprehensive graph analytics in a single call.

        Returns density, degree distribution, centrality metrics,
        memory health scores, and structural insights.
        Combines and extends stats() with deeper analysis.
        """
        nodes = self.conn.execute(
            "SELECT * FROM nodes WHERE quarantined=0"
        ).fetchall()
        n_count = len(nodes)

        edges = self.conn.execute("SELECT * FROM edges").fetchall()
        e_count = len(edges)

        # Density: actual / max possible edges (directed, no self-loops)
        max_edges = n_count * (n_count - 1) if n_count > 1 else 0
        density = e_count / max_edges if max_edges > 0 else 0.0

        # Degree analysis
        out_deg = defaultdict(int)
        in_deg = defaultdict(int)
        for e in edges:
            out_deg[e["source"]] += 1
            in_deg[e["target"]] += 1

        all_degrees = [out_deg.get(r["id"], 0) + in_deg.get(r["id"], 0) for r in nodes]
        avg_degree = sum(all_degrees) / len(all_degrees) if all_degrees else 0.0
        max_degree = max(all_degrees) if all_degrees else 0

        # Degree distribution buckets
        deg_dist = {"0": 0, "1-2": 0, "3-5": 0, "6-10": 0, "10+": 0}
        for d in all_degrees:
            if d == 0:
                deg_dist["0"] += 1
            elif d <= 2:
                deg_dist["1-2"] += 1
            elif d <= 5:
                deg_dist["3-5"] += 1
            elif d <= 10:
                deg_dist["6-10"] += 1
            else:
                deg_dist["10+"] += 1

        # Top nodes by degree (hub nodes)
        node_degrees = [
            (r["id"], r["label"], out_deg.get(r["id"], 0) + in_deg.get(r["id"], 0))
            for r in nodes
        ]
        node_degrees.sort(key=lambda x: x[2], reverse=True)
        hubs = [
            {"id": nid, "label": label, "degree": deg}
            for nid, label, deg in node_degrees[:5]
        ]

        # Weight distribution
        weights = [r["weight"] for r in nodes]
        avg_weight = sum(weights) / len(weights) if weights else 0.0
        low_weight = sum(1 for w in weights if w < 0.3)
        high_weight = sum(1 for w in weights if w >= 0.7)

        # Q-value distribution
        q_values = [r["q_value"] for r in nodes if r["q_value"] != 0.0]
        avg_q = sum(q_values) / len(q_values) if q_values else 0.0

        # Kind distribution
        kind_counts = defaultdict(int)
        for r in nodes:
            kind_counts[r["kind"]] += 1

        # Orphan nodes (no edges)
        connected_ids = set()
        for e in edges:
            connected_ids.add(e["source"])
            connected_ids.add(e["target"])
        orphans = sum(1 for r in nodes if r["id"] not in connected_ids)
        orphan_ratio = orphans / n_count if n_count > 0 else 0.0

        # Reciprocal edges (A→B and B→A)
        edge_pairs = set()
        reciprocal = 0
        for e in edges:
            pair = (e["source"], e["target"])
            reverse = (e["target"], e["source"])
            if reverse in edge_pairs:
                reciprocal += 1
            edge_pairs.add(pair)

        # Memory health score [0, 1] — composite
        # Lower orphans, good avg weight, high connectivity → higher score
        connectivity_score = 1.0 - orphan_ratio if n_count > 0 else 0.0
        weight_score = min(avg_weight, 1.0)
        density_score = min(density * 10, 1.0)  # Scale: 0.1 density → full score
        health = (connectivity_score * 0.4 + weight_score * 0.3 + density_score * 0.3)

        # Relation distribution
        relation_counts = defaultdict(int)
        for e in edges:
            relation_counts[e["relation"]] += 1
        top_relations = sorted(relation_counts.items(), key=lambda x: x[1], reverse=True)[:5]

        return {
            "node_count": n_count,
            "edge_count": e_count,
            "density": round(density, 4),
            "avg_degree": round(avg_degree, 2),
            "max_degree": max_degree,
            "degree_distribution": deg_dist,
            "hub_nodes": hubs,
            "avg_weight": round(avg_weight, 4),
            "low_weight_count": low_weight,
            "high_weight_count": high_weight,
            "avg_q_value": round(avg_q, 4),
            "kind_distribution": dict(kind_counts),
            "orphan_nodes": orphans,
            "orphan_ratio": round(orphan_ratio, 4),
            "reciprocal_edges": reciprocal,
            "top_relations": [{"relation": r, "count": c} for r, c in top_relations],
            "memory_health": round(health, 4),
        }

    # ── Memory Diff ─────────────────────────────────────────

    def diff_graph(self, other: 'MemoryGraph') -> dict:
        """Compute the difference between this graph and another.

        Returns added/removed/changed nodes and edges, useful for
        audit trails, before/after comparisons, and memory evolution
        tracking.

        Args:
            other: The other MemoryGraph to diff against.

        Returns dict with:
            nodes_added, nodes_removed, nodes_changed,
            edges_added, edges_removed,
            summary: {added, removed, changed totals}
        """
        self_nodes = {
            r["id"]: r for r in self.conn.execute(
                "SELECT * FROM nodes WHERE quarantined=0"
            ).fetchall()
        }
        other_nodes = {
            r["id"]: r for r in other.conn.execute(
                "SELECT * FROM nodes WHERE quarantined=0"
            ).fetchall()
        }

        self_ids = set(self_nodes.keys())
        other_ids = set(other_nodes.keys())

        nodes_added = []
        for nid in other_ids - self_ids:
            r = other_nodes[nid]
            nodes_added.append({
                "id": nid, "label": r["label"], "kind": r["kind"],
                "weight": r["weight"],
            })

        nodes_removed = []
        for nid in self_ids - other_ids:
            r = self_nodes[nid]
            nodes_removed.append({
                "id": nid, "label": r["label"], "kind": r["kind"],
                "weight": r["weight"],
            })

        nodes_changed = []
        for nid in self_ids & other_ids:
            old = self_nodes[nid]
            new = other_nodes[nid]
            changes = {}
            if old["label"] != new["label"]:
                changes["label"] = {"old": old["label"], "new": new["label"]}
            if old["kind"] != new["kind"]:
                changes["kind"] = {"old": old["kind"], "new": new["kind"]}
            if abs(old["weight"] - new["weight"]) > 0.001:
                changes["weight"] = {"old": old["weight"], "new": new["weight"]}
            old_data = json.loads(old["data"])
            new_data = json.loads(new["data"])
            if old_data != new_data:
                changes["data_added"] = {k: v for k, v in new_data.items() if k not in old_data}
                changes["data_removed"] = {k: v for k, v in old_data.items() if k not in new_data}
            if changes:
                nodes_changed.append({
                    "id": nid,
                    "label": new["label"],
                    "changes": changes,
                })

        # Edge diff
        self_edges = {
            (r["source"], r["target"], r["relation"])
            for r in self.conn.execute("SELECT * FROM edges").fetchall()
        }
        other_edges = {
            (r["source"], r["target"], r["relation"])
            for r in other.conn.execute("SELECT * FROM edges").fetchall()
        }

        edges_added = [
            {"source": s, "target": t, "relation": r}
            for s, t, r in other_edges - self_edges
        ]
        edges_removed = [
            {"source": s, "target": t, "relation": r}
            for s, t, r in self_edges - other_edges
        ]

        return {
            "nodes_added": nodes_added,
            "nodes_removed": nodes_removed,
            "nodes_changed": nodes_changed,
            "edges_added": edges_added,
            "edges_removed": edges_removed,
            "summary": {
                "added": len(nodes_added) + len(edges_added),
                "removed": len(nodes_removed) + len(edges_removed),
                "changed": len(nodes_changed),
            },
        }

    def diff_report(self, diff: dict = None, other: 'MemoryGraph' = None) -> str:
        """Format a diff as a human-readable report.

        Either pass a pre-computed diff dict, or pass another graph
        to compute diff on the fly.
        """
        if diff is None:
            if other is None:
                raise ValueError("Provide either diff dict or other graph")
            diff = self.diff_graph(other)

        lines = []
        s = diff["summary"]
        lines.append(
            f"Memory Diff: +{s['added']} added, -{s['removed']} removed, ~{s['changed']} changed"
        )

        if diff["nodes_added"]:
            lines.append(f"\n  ▲ Nodes added ({len(diff['nodes_added'])}):")
            for n in diff["nodes_added"]:
                lines.append(f"    + [{n['kind']}] {n['label']} (w={n['weight']:.2f})")

        if diff["nodes_removed"]:
            lines.append(f"\n  ▼ Nodes removed ({len(diff['nodes_removed'])}):")
            for n in diff["nodes_removed"]:
                lines.append(f"    - [{n['kind']}] {n['label']} (w={n['weight']:.2f})")

        if diff["nodes_changed"]:
            lines.append(f"\n  ◆ Nodes changed ({len(diff['nodes_changed'])}):")
            for n in diff["nodes_changed"]:
                parts = [f"    ~ {n['label']}"]
                for field, change in n["changes"].items():
                    if isinstance(change, dict) and "old" in change:
                        parts.append(f"    {field}: {change['old']} → {change['new']}")
                    elif field == "data_added":
                        keys = list(change.keys())
                        parts.append(f"    data +{keys}")
                    elif field == "data_removed":
                        keys = list(change.keys())
                        parts.append(f"    data -{keys}")
                lines.append("\n".join(parts))

        if diff["edges_added"]:
            lines.append(f"\n  ▲ Edges added ({len(diff['edges_added'])}):")
            for e in diff["edges_added"][:10]:
                lines.append(f"    + {e['source'][:8]}→{e['target'][:8]} [{e['relation']}]")
            if len(diff["edges_added"]) > 10:
                lines.append(f"    ... and {len(diff['edges_added']) - 10} more")

        if diff["edges_removed"]:
            lines.append(f"\n  ▼ Edges removed ({len(diff['edges_removed'])}):")
            for e in diff["edges_removed"][:10]:
                lines.append(f"    - {e['source'][:8]}→{e['target'][:8]} [{e['relation']}]")
            if len(diff["edges_removed"]) > 10:
                lines.append(f"    ... and {len(diff['edges_removed']) - 10} more")

        if s["added"] == 0 and s["removed"] == 0 and s["changed"] == 0:
            lines.append("  (no changes)")

        return "\n".join(lines)

    # ─── Batch Operations ───────────────────────────────────────────

    def batch_create_nodes(self, nodes_data: list[dict]) -> dict:
        """Create multiple nodes in a single transaction.

        Each item in *nodes_data* must be a dict with keys:
            label (required), kind (default 'fact'), data (default {}),
            tags (default []), weight (default 1.0).

        Returns a dict with keys ``created`` (list of Node),
        ``skipped`` (list of error strings), and ``count``.
        """
        created: list[Node] = []
        skipped: list[str] = []
        now = time.time()
        for item in nodes_data:
            label = item.get("label")
            if not label:
                skipped.append(f"missing label: {item}")
                continue
            try:
                node = Node(
                    id=uuid.uuid4().hex[:12],
                    label=label,
                    kind=item.get("kind", "fact"),
                    data=item.get("data", {}),
                    created=now, accessed=now,
                    weight=item.get("weight", 1.0),
                )
                self.conn.execute(
                    "INSERT INTO nodes (id,label,kind,data,created,accessed,weight,tags) "
                    "VALUES (?,?,?,?,?,?,?,?)",
                    (node.id, node.label, node.kind, json.dumps(node.data),
                     node.created, node.accessed, node.weight,
                     json.dumps(item.get("tags", []))),
                )
                self._fts_sync_node(node.id)
                created.append(node)
            except Exception as exc:
                skipped.append(f"{label}: {exc}")
        self.conn.commit()
        self._tick("batch_create_nodes", None, {"count": len(created)})
        return {"created": created, "skipped": skipped, "count": len(created)}

    def batch_add_edges(self, edges_data: list[dict]) -> dict:
        """Add multiple edges in a single transaction.

        Each item in *edges_data* must be a dict with keys:
            source (required), target (required), relation (required),
            weight (default 1.0).

        Source and target may be either node IDs or labels
        (resolved via ``link_by_label`` semantics: ID first, then label).

        Returns a dict with keys ``added``, ``skipped``, and ``count``.
        """
        added = 0
        skipped: list[str] = []
        for item in edges_data:
            src = item.get("source")
            tgt = item.get("target")
            rel = item.get("relation")
            if not src or not tgt or not rel:
                skipped.append(f"missing fields: {item}")
                continue
            w = item.get("weight", 1.0)
            # Try direct ID first, then label lookup
            src_row = self.conn.execute(
                "SELECT id FROM nodes WHERE id=? OR label=? ORDER BY created DESC LIMIT 1",
                (src, src),
            ).fetchone()
            tgt_row = self.conn.execute(
                "SELECT id FROM nodes WHERE id=? OR label=? ORDER BY created DESC LIMIT 1",
                (tgt, tgt),
            ).fetchone()
            if not src_row or not tgt_row:
                skipped.append(f"node not found: {src}→{tgt}")
                continue
            try:
                self.conn.execute(
                    "INSERT OR REPLACE INTO edges VALUES (?,?,?,?)",
                    (src_row["id"], tgt_row["id"], rel, w),
                )
                added += 1
            except Exception as exc:
                skipped.append(f"{src}→{tgt}: {exc}")
        self.conn.commit()
        self._tick("batch_add_edges", None, {"count": added})
        return {"added": added, "skipped": skipped, "count": added}

    def batch_delete_nodes(self, node_ids: list[str], safe: bool = True) -> dict:
        """Delete multiple nodes.  If *safe* is True, nodes with live
        dependents are skipped (uses ``delete_node_safe``).

        Returns dict with ``deleted``, ``skipped``, ``count``.
        """
        deleted: list[str] = []
        skipped: list[str] = []
        for nid in node_ids:
            if safe:
                result = self.delete_node_safe(nid)
                if result["deleted"]:
                    deleted.append(nid)
                else:
                    skipped.append(f"{nid}: {result.get('reason', 'unknown')}")
            else:
                if self.delete_node(nid):
                    deleted.append(nid)
                else:
                    skipped.append(f"{nid}: not found")
        return {"deleted": deleted, "skipped": skipped, "count": len(deleted)}

    # ─── Link Prediction ────────────────────────────────────────────

    def predict_links(self, node_id: str = None, limit: int = 10,
                      min_score: float = 0.0) -> list[dict]:
        """Suggest missing edges using common-neighbor heuristics.

        For each pair of nodes (u, v) that are **not** directly connected,
        compute a prediction score from three signals:

        * **Common Neighbors** — number of shared neighbors.
        * **Adamic-Adar** — sum of 1/log(degree(w)) over shared neighbors w.
        * **Preferential Attachment** — degree(u) × degree(v).

        The final ``score`` is a weighted blend
        (0.4·CN + 0.4·AA + 0.2·PA_normalised).

        Args:
            node_id: If given, only predict links *from* this node.
                     If None, scan all nodes (may be slow on large graphs).
            limit: Maximum number of suggestions.
            min_score: Filter out predictions below this threshold.

        Returns a list of dicts sorted by score descending, each with keys:
            ``source``, ``target``, ``source_label``, ``target_label``,
            ``common_neighbors``, ``adamic_adar``, ``preferential_attachment``,
            ``score``.
        """
        # Build adjacency sets (undirected for neighbor computation)
        rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        adj: dict[str, set[str]] = {}
        for r in rows:
            adj.setdefault(r["source"], set()).add(r["target"])
            adj.setdefault(r["target"], set()).add(r["source"])

        # Compute degree for every node
        all_nodes = set()
        for s, ts in adj.items():
            all_nodes.add(s)
            all_nodes |= ts
        # Include isolated nodes too
        node_rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        for nr in node_rows:
            all_nodes.add(nr["id"])

        degree = {n: len(adj.get(n, set())) for n in all_nodes}

        import math

        # Determine source set
        sources = [node_id] if node_id else list(all_nodes)

        predictions: list[dict] = []
        seen_pairs: set[frozenset] = set()

        for u in sources:
            neighbors_u = adj.get(u, set())
            for v in all_nodes:
                if v == u:
                    continue
                pair = frozenset({u, v})
                if pair in seen_pairs:
                    continue
                seen_pairs.add(pair)
                # Skip already-connected pairs
                if v in neighbors_u:
                    continue
                # Compute scores
                neighbors_v = adj.get(v, set())
                common = neighbors_u & neighbors_v
                cn = len(common)
                if cn == 0 and degree[u] * degree[v] == 0:
                    continue
                aa = sum(
                    1.0 / math.log(degree[w])
                    for w in common
                    if degree[w] > 1
                )
                pa = degree[u] * degree[v]
                # Normalise PA: divide by max possible (N-1)^2
                n_total = len(all_nodes)
                pa_norm = pa / ((n_total - 1) ** 2) if n_total > 1 else 0.0
                score = 0.4 * cn + 0.4 * aa + 0.2 * pa_norm
                if score <= min_score:
                    continue
                predictions.append({
                    "source": u,
                    "target": v,
                    "common_neighbors": cn,
                    "adamic_adar": round(aa, 4),
                    "preferential_attachment": pa,
                    "score": round(score, 4),
                })

        predictions.sort(key=lambda p: p["score"], reverse=True)

        # Resolve labels and truncate
        label_cache: dict[str, str] = {}
        for p in predictions[:limit]:
            for key in ("source", "target"):
                nid = p[key]
                if nid not in label_cache:
                    row = self.conn.execute(
                        "SELECT label FROM nodes WHERE id=?", (nid,)
                    ).fetchone()
                    label_cache[nid] = row["label"] if row else nid
                p[f"{key}_label"] = label_cache[nid]

        return predictions[:limit]

    # ─── Weighted Shortest Path (Dijkstra) ──────────────────────────

    def shortest_path_weighted(self, source_id: str, target_id: str,
                                default_weight: float = 1.0) -> Optional[dict]:
        """Find the minimum-cost path between two nodes using edge weights.

        Uses Dijkstra's algorithm.  Unlike ``shortest_path`` (BFS by hops),
        this accounts for edge ``weight`` values so that a 3-hop path
        through low-weight edges may beat a 2-hop path through high-weight
        edges.

        Args:
            source_id: Starting node ID.
            target_id: Ending node ID.
            default_weight: Weight to use if an edge has no weight column
                            or weight is NULL (default 1.0).

        Returns ``None`` if no path exists, otherwise a dict with:
            ``path`` (list of node IDs), ``cost`` (total weight),
            ``hops`` (number of edges).
        """
        if source_id == target_id:
            return {"path": [source_id], "cost": 0.0, "hops": 0}

        import heapq

        # Build weighted adjacency (directed)
        rows = self.conn.execute(
            "SELECT source, target, weight FROM edges"
        ).fetchall()
        adj: dict[str, list[tuple[str, float]]] = {}
        for r in rows:
            w = r["weight"] if r["weight"] is not None else default_weight
            adj.setdefault(r["source"], []).append((r["target"], w))

        # Dijkstra
        dist: dict[str, float] = {source_id: 0.0}
        prev: dict[str, str] = {}
        visited: set[str] = set()
        pq: list[tuple[float, str]] = [(0.0, source_id)]

        while pq:
            d, u = heapq.heappop(pq)
            if u in visited:
                continue
            visited.add(u)
            if u == target_id:
                break
            for v, w in adj.get(u, []):
                nd = d + w
                if nd < dist.get(v, float('inf')):
                    dist[v] = nd
                    prev[v] = u
                    heapq.heappush(pq, (nd, v))

        if target_id not in dist:
            return None

        # Reconstruct path
        path = [target_id]
        cur = target_id
        while cur != source_id:
            cur = prev[cur]
            path.append(cur)
        path.reverse()

        return {"path": path, "cost": round(dist[target_id], 6), "hops": len(path) - 1}

    def path_cost(self, path: list[str]) -> float:
        """Compute the total weight of a given node-ID path.

        Returns ``inf`` if any edge in the path does not exist.
        """
        if len(path) < 2:
            return 0.0
        total = 0.0
        for i in range(len(path) - 1):
            row = self.conn.execute(
                "SELECT weight FROM edges WHERE source=? AND target=? "
                "ORDER BY weight ASC LIMIT 1",
                (path[i], path[i + 1]),
            ).fetchone()
            if not row:
                return float('inf')
            total += row["weight"] if row["weight"] is not None else 1.0
        return round(total, 6)

    # ─── Path Enumeration ───────────────────────────────────────────

    def all_paths(self, source_id: str, target_id: str,
                  max_hops: int = 5, limit: int = 20) -> list[list[str]]:
        """Find all simple paths (no repeated nodes) between two nodes.

        Uses DFS with pruning at *max_hops*.  Returns a list of paths
        (each a list of node IDs), sorted by length (shortest first).
        Limited to *limit* results to prevent combinatorial explosion.

        Args:
            source_id: Starting node ID.
            target_id: Ending node ID.
            max_hops: Maximum number of edges in a path.
            limit: Maximum number of paths to return.

        Returns an empty list if no path exists or nodes don't exist.
        """
        # Verify nodes exist
        for nid in (source_id, target_id):
            if not self.conn.execute(
                "SELECT 1 FROM nodes WHERE id=?", (nid,)
            ).fetchone():
                return []

        if source_id == target_id:
            return [[source_id]]

        # Build adjacency
        rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        adj: dict[str, list[str]] = {}
        for r in rows:
            adj.setdefault(r["source"], []).append(r["target"])

        results: list[list[str]] = []

        def _dfs(current: str, path: list[str], visited: set[str]):
            if len(results) >= limit:
                return
            if len(path) - 1 >= max_hops:
                return
            for neighbor in adj.get(current, []):
                if neighbor == target_id:
                    results.append(path + [neighbor])
                    if len(results) >= limit:
                        return
                    continue
                if neighbor in visited:
                    continue
                visited.add(neighbor)
                _dfs(neighbor, path + [neighbor], visited)
                visited.discard(neighbor)

        _dfs(source_id, [source_id], {source_id})
        results.sort(key=len)
        return results

    def k_shortest_paths(self, source_id: str, target_id: str,
                         k: int = 3, max_hops: int = 8) -> list[dict]:
        """Find the K lowest-cost simple paths between two nodes.

        Uses Yen's algorithm (simplified): repeatedly find shortest path,
        then spur from deviations.

        Args:
            source_id: Starting node ID.
            target_id: Ending node ID.
            k: Number of paths to find.
            max_hops: Maximum path length to consider.

        Returns a list of dicts with ``path``, ``cost``, ``hops``
        sorted by cost ascending.  May return fewer than *k* if not
        enough paths exist.
        """
        # Get candidate paths via all_paths
        candidates = self.all_paths(source_id, target_id,
                                     max_hops=max_hops, limit=k * 5)
        if not candidates:
            return []

        # Score each path by cost
        scored: list[dict] = []
        for p in candidates:
            cost = self.path_cost(p)
            if cost == float('inf'):
                continue
            scored.append({"path": p, "cost": cost, "hops": len(p) - 1})

        scored.sort(key=lambda x: x["cost"])
        return scored[:k]

    # ─────────────────────────────────────────────
    # Cycle 192: Subgraph Extraction
    # ─────────────────────────────────────────────

    def extract_subgraph(self, node_id: str, radius: int = 1,
                         max_nodes: int = 100,
                         include_quarantined: bool = False) -> 'MemoryGraph':
        """Extract a neighborhood subgraph around *node_id*.

        Performs BFS up to *radius* hops, collecting all reachable nodes
        and the edges between them.  Returns a **new** MemoryGraph instance
        containing only the extracted subset.

        Args:
            node_id: Centre node for extraction.
            radius: Maximum hop distance (1 = immediate neighbours).
            max_nodes: Safety cap to avoid extracting huge subgraphs.
            include_quarantined: If False, skip quarantined nodes.

        Returns a new MemoryGraph.  Raises ValueError if *node_id* not found.
        """
        if not self.conn.execute(
            "SELECT 1 FROM nodes WHERE id=?", (node_id,)
        ).fetchone():
            raise ValueError(f"Node not found: {node_id}")

        # BFS to collect node IDs within radius
        visited: set[str] = set()
        frontier: set[str] = {node_id}
        for hop in range(radius + 1):
            if not frontier or len(visited) >= max_nodes:
                break
            next_frontier: set[str] = set()
            for nid in frontier:
                if nid in visited or len(visited) >= max_nodes:
                    continue
                # Skip quarantined unless explicitly included
                if not include_quarantined and self._is_quarantined(nid):
                    continue
                visited.add(nid)
                # Get neighbors (both directions)
                for r in self.conn.execute(
                    "SELECT target FROM edges WHERE source=?", (nid,)
                ).fetchall():
                    if r["target"] not in visited:
                        next_frontier.add(r["target"])
                for r in self.conn.execute(
                    "SELECT source FROM edges WHERE target=?", (nid,)
                ).fetchall():
                    if r["source"] not in visited:
                        next_frontier.add(r["source"])
            frontier = next_frontier

        # Build subgraph
        sub = MemoryGraph()
        # Copy nodes
        for nid in visited:
            row = self.conn.execute(
                "SELECT * FROM nodes WHERE id=?", (nid,)
            ).fetchone()
            if row is None:
                continue
            sub.conn.execute(
                """INSERT OR REPLACE INTO nodes
                   (id,label,kind,data,created,accessed,weight,tags,
                    source,trust_level,parents,quarantined,quarantine_reason,
                    valid_from,valid_to,txn_time,q_value)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (row["id"], row["label"], row["kind"], row["data"],
                 row["created"], row["accessed"], row["weight"], row["tags"],
                 row["source"], row["trust_level"], row["parents"],
                 row["quarantined"], row["quarantine_reason"],
                 row["valid_from"], row["valid_to"], row["txn_time"],
                 row["q_value"])
            )
        # Copy edges between visited nodes
        for r in self.conn.execute("SELECT * FROM edges").fetchall():
            if r["source"] in visited and r["target"] in visited:
                sub.conn.execute(
                    "INSERT OR REPLACE INTO edges (source,target,relation,weight) VALUES (?,?,?,?)",
                    (r["source"], r["target"], r["relation"], r["weight"])
                )
        # Copy edge props
        for r in self.conn.execute("SELECT * FROM edge_props").fetchall():
            if r["source"] in visited and r["target"] in visited:
                sub.conn.execute(
                    "INSERT OR REPLACE INTO edge_props (source,target,relation,properties) VALUES (?,?,?,?)",
                    (r["source"], r["target"], r["relation"], r["properties"])
                )
        # Rebuild FTS
        sub._rebuild_fts()
        sub.conn.commit()
        return sub

    def neighborhood(self, node_id: str, radius: int = 1,
                     include_quarantined: bool = False) -> list[str]:
        """Return node IDs within *radius* hops of *node_id*.

        Lightweight alternative to :meth:`extract_subgraph` when you only
        need the ID list, not a full subgraph copy.

        Args:
            node_id: Centre node.
            radius: Maximum hop distance.
            include_quarantined: If False, skip quarantined nodes.

        Returns a list of node IDs (including *node_id* itself).
        Raises ValueError if node not found.
        """
        if not self.conn.execute(
            "SELECT 1 FROM nodes WHERE id=?", (node_id,)
        ).fetchone():
            raise ValueError(f"Node not found: {node_id}")

        visited: set[str] = set()
        frontier: set[str] = {node_id}
        for hop in range(radius + 1):
            if not frontier:
                break
            next_frontier: set[str] = set()
            for nid in frontier:
                if nid in visited:
                    continue
                if not include_quarantined and self._is_quarantined(nid):
                    continue
                visited.add(nid)
                for r in self.conn.execute(
                    "SELECT target FROM edges WHERE source=?", (nid,)
                ).fetchall():
                    if r["target"] not in visited:
                        next_frontier.add(r["target"])
                for r in self.conn.execute(
                    "SELECT source FROM edges WHERE target=?", (nid,)
                ).fetchall():
                    if r["source"] not in visited:
                        next_frontier.add(r["source"])
            frontier = next_frontier
        return sorted(visited)

    def _rebuild_fts(self):
        """Rebuild the FTS5 index from the nodes table."""
        if not getattr(self, '_fts_enabled', False):
            return
        self.conn.execute("DELETE FROM nodes_fts")
        for row in self.conn.execute("SELECT id,label,kind,data,tags FROM nodes").fetchall():
            self.conn.execute(
                "INSERT INTO nodes_fts (node_id,label,kind,data,tags) VALUES (?,?,?,?,?)",
                (row["id"], row["label"], row["kind"], row["data"], row["tags"])
            )

    # ─────────────────────────────────────────────
    # Cycle 193: Centrality Metrics
    # ─────────────────────────────────────────────

    def betweenness_all(self, normalized: bool = True,
                        include_quarantined: bool = False) -> dict[str, float]:
        """Compute betweenness centrality for all nodes (Brandes' algorithm).

        Betweenness = how many shortest paths pass through a node.
        High-betweenness nodes are "bridges" connecting different parts
        of the graph.

        Args:
            normalized: If True, divide by (N-1)(N-2)/2 for undirected.
            include_quarantined: If False, skip quarantined nodes.

        Returns {node_id: centrality_score}.
        """
        # Gather active node IDs
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        n = len(node_ids)
        if n < 3:
            return {nid: 0.0 for nid in node_ids}

        # Build adjacency (undirected for centrality)
        node_set = set(node_ids)
        adj: dict[str, list[str]] = {nid: [] for nid in node_ids}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                adj[s].append(t)
                adj[t].append(s)  # treat as undirected

        # Brandes' algorithm
        centrality: dict[str, float] = {nid: 0.0 for nid in node_ids}
        for s in node_ids:
            # Single-source BFS
            stack: list[str] = []
            pred: dict[str, list[str]] = {nid: [] for nid in node_ids}
            sigma: dict[str, float] = {nid: 0.0 for nid in node_ids}
            sigma[s] = 1.0
            dist: dict[str, int] = {nid: -1 for nid in node_ids}
            dist[s] = 0
            queue: list[str] = [s]
            while queue:
                v = queue.pop(0)
                stack.append(v)
                for w in adj[v]:
                    if dist[w] < 0:
                        queue.append(w)
                        dist[w] = dist[v] + 1
                    if dist[w] == dist[v] + 1:
                        sigma[w] += sigma[v]
                        pred[w].append(v)
            # Accumulation
            delta: dict[str, float] = {nid: 0.0 for nid in node_ids}
            while stack:
                w = stack.pop()
                for v in pred[w]:
                    delta[v] += (sigma[v] / sigma[w]) * (1.0 + delta[w])
                if w != s:
                    centrality[w] += delta[w]

        # For undirected graphs, each pair is counted twice; halve
        for nid in centrality:
            centrality[nid] /= 2.0
        # Normalize (standard undirected normalization)
        if normalized and n > 2:
            factor = 2.0 / ((n - 1) * (n - 2))
            for nid in centrality:
                centrality[nid] *= factor

        return centrality

    def closeness_all(self, normalized: bool = True,
                      include_quarantined: bool = False) -> dict[str, float]:
        """Compute closeness centrality for all nodes.

        Closeness = reciprocal of average shortest-path distance to all
        other reachable nodes.  High-closeness nodes can reach the rest
        of the graph quickly.

        Uses multi-source BFS.  Disconnected nodes get 0.

        Args:
            normalized: If True, multiply by (reachable_count / (N-1)).
            include_quarantined: If False, skip quarantined nodes.

        Returns {node_id: centrality_score}.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        n = len(node_ids)
        if n < 2:
            return {nid: 1.0 for nid in node_ids}

        node_set = set(node_ids)
        adj: dict[str, list[str]] = {nid: [] for nid in node_ids}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                adj[s].append(t)
                adj[t].append(s)

        centrality: dict[str, float] = {}
        for s in node_ids:
            # BFS distances
            dist: dict[str, int] = {s: 0}
            queue: list[str] = [s]
            total_dist = 0
            reachable = 0
            while queue:
                v = queue.pop(0)
                for w in adj[v]:
                    if w not in dist:
                        dist[w] = dist[v] + 1
                        total_dist += dist[w]
                        reachable += 1
                        queue.append(w)
            if total_dist == 0:
                centrality[s] = 0.0
            else:
                cc = reachable / total_dist
                if normalized:
                    cc *= reachable / (n - 1)
                centrality[s] = cc

        return centrality

    def eigenvector_all(self, iterations: int = 100,
                         tolerance: float = 1e-6,
                         include_quarantined: bool = False) -> dict[str, float]:
        """Compute eigenvector centrality for all nodes via power iteration.

        High-eigenvector nodes are those connected to other high-scoring
        nodes.  Identifies the "core" of influential memories.

        Args:
            iterations: Max power-iteration steps.
            tolerance: Convergence threshold (L1 norm).
            include_quarantined: If False, skip quarantined nodes.

        Returns {node_id: centrality_score}.  Empty dict if graph is empty.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        n = len(node_ids)
        if n == 0:
            return {}
        if n == 1:
            return {node_ids[0]: 1.0}

        node_set = set(node_ids)
        adj: dict[str, list[str]] = {nid: [] for nid in node_ids}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                adj[s].append(t)
                adj[t].append(s)

        # Power iteration
        centrality = {nid: 1.0 / n for nid in node_ids}
        for _ in range(iterations):
            new_c = {nid: 0.0 for nid in node_ids}
            for v in node_ids:
                for w in adj[v]:
                    new_c[w] += centrality[v]
            # Normalize
            norm = sum(v * v for v in new_c.values()) ** 0.5
            if norm == 0:
                break
            new_c = {nid: v / norm for nid, v in new_c.items()}
            # Check convergence
            diff = sum(abs(new_c[nid] - centrality[nid]) for nid in node_ids)
            centrality = new_c
            if diff < tolerance:
                break

        return centrality

    # ─────────────────────────────────────────────
    # Cycle 194: Graph Merge & Serialization
    # ─────────────────────────────────────────────

    def merge_graph(self, other: 'MemoryGraph',
                    strategy: str = "union",
                    prefix: str = None,
                    on_conflict: str = "keep_both") -> dict:
        """Merge another MemoryGraph into this one.

        Useful for multi-agent memory fusion: each agent maintains its
        own graph, then merges results.

        Args:
            other: The graph to merge FROM.
            strategy: "union" (all nodes/edges) or "intersection"
                      (only nodes that exist in both, plus other's edges).
            prefix: If given, prefix other's node IDs with this string
                    to avoid ID collisions (e.g. "agent2_").
            on_conflict: "keep_both" (add with prefixed ID),
                         "skip" (don't add conflicting IDs),
                         "overwrite" (replace local data).

        Returns a dict with merge stats:
            nodes_added, nodes_skipped, edges_added, edges_skipped
        """
        stats = {"nodes_added": 0, "nodes_skipped": 0,
                 "edges_added": 0, "edges_skipped": 0}

        # Build ID mapping (other_id → target_id in self)
        id_map: dict[str, str] = {}

        if strategy == "intersection":
            # Only include nodes that already exist in self (by label match)
            local_labels = {r["label"]: r["id"] for r in
                            self.conn.execute("SELECT id, label FROM nodes").fetchall()}
            for row in other.conn.execute("SELECT * FROM nodes").fetchall():
                if row["label"] in local_labels:
                    id_map[row["id"]] = local_labels[row["label"]]
            # Only map edges between intersection nodes
            for r in other.conn.execute("SELECT * FROM edges").fetchall():
                if r["source"] in id_map and r["target"] in id_map:
                    try:
                        self.conn.execute(
                            "INSERT OR IGNORE INTO edges (source,target,relation,weight) VALUES (?,?,?,?)",
                            (id_map[r["source"]], id_map[r["target"]], r["relation"], r["weight"])
                        )
                        if self.conn.total_changes > 0:
                            stats["edges_added"] += 1
                        else:
                            stats["edges_skipped"] += 1
                    except sqlite3.IntegrityError:
                        stats["edges_skipped"] += 1
            self.conn.commit()
            self._rebuild_fts()
            return stats

        # Union strategy
        for row in other.conn.execute("SELECT * FROM nodes").fetchall():
            other_id = row["id"]
            # Check if ID collides
            existing = self.conn.execute(
                "SELECT 1 FROM nodes WHERE id=?", (other_id,)
            ).fetchone()

            if existing and prefix is None:
                # ID collision without prefix
                if on_conflict == "skip":
                    id_map[other_id] = other_id
                    stats["nodes_skipped"] += 1
                    continue
                elif on_conflict == "overwrite":
                    self.conn.execute(
                        """UPDATE nodes SET label=?, kind=?, data=?, weight=?, tags=?,
                           source=?, trust_level=?, q_value=?
                           WHERE id=?""",
                        (row["label"], row["kind"], row["data"],
                         row["weight"], row["tags"],
                         row["source"], row["trust_level"],
                         row["q_value"], other_id)
                    )
                    id_map[other_id] = other_id
                    stats["nodes_added"] += 1
                    continue
                # keep_both: fall through to prefix logic

            # Determine target ID
            target_id = f"{prefix}{other_id}" if prefix else other_id
            if existing and on_conflict == "keep_both" and prefix is None:
                # Auto-generate prefix to avoid collision
                target_id = f"m_{other_id}"

            id_map[other_id] = target_id

            # Insert node
            self.conn.execute(
                """INSERT OR REPLACE INTO nodes
                   (id,label,kind,data,created,accessed,weight,tags,
                    source,trust_level,parents,quarantined,quarantine_reason,
                    valid_from,valid_to,txn_time,q_value)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (target_id, row["label"], row["kind"], row["data"],
                 row["created"], row["accessed"], row["weight"], row["tags"],
                 row["source"], row["trust_level"], row["parents"],
                 row["quarantined"], row["quarantine_reason"],
                 row["valid_from"], row["valid_to"], row["txn_time"],
                 row["q_value"])
            )
            stats["nodes_added"] += 1

        # Copy edges (using ID mapping)
        for r in other.conn.execute("SELECT * FROM edges").fetchall():
            src = id_map.get(r["source"])
            tgt = id_map.get(r["target"])
            if src is None or tgt is None:
                stats["edges_skipped"] += 1
                continue
            try:
                self.conn.execute(
                    "INSERT OR IGNORE INTO edges (source,target,relation,weight) VALUES (?,?,?,?)",
                    (src, tgt, r["relation"], r["weight"])
                )
                if self.conn.total_changes > 0:
                    stats["edges_added"] += 1
                else:
                    stats["edges_skipped"] += 1
            except sqlite3.IntegrityError:
                stats["edges_skipped"] += 1

        # Copy edge props
        for r in other.conn.execute("SELECT * FROM edge_props").fetchall():
            src = id_map.get(r["source"])
            tgt = id_map.get(r["target"])
            if src and tgt:
                self.conn.execute(
                    "INSERT OR REPLACE INTO edge_props (source,target,relation,properties) VALUES (?,?,?,?)",
                    (src, tgt, r["relation"], r["properties"])
                )

        self.conn.commit()
        self._rebuild_fts()
        return stats

    def to_dict(self) -> dict:
        """Serialize the graph to a plain dict (JSON-safe).

        Includes all nodes, edges, and edge_props.
        Useful for snapshotting, API responses, or inter-agent transfer.

        Returns a dict with 'nodes', 'edges', 'edge_props', 'meta'.
        """
        nodes = []
        for r in self.conn.execute("SELECT * FROM nodes").fetchall():
            nodes.append({
                "id": r["id"], "label": r["label"], "kind": r["kind"],
                "data": json.loads(r["data"]), "created": r["created"],
                "accessed": r["accessed"], "weight": r["weight"],
                "tags": json.loads(r["tags"]),
                "quarantined": bool(r["quarantined"]),
                "q_value": r["q_value"],
            })
        edges = []
        for r in self.conn.execute("SELECT * FROM edges").fetchall():
            edges.append({
                "source": r["source"], "target": r["target"],
                "relation": r["relation"], "weight": r["weight"],
            })
        return {
            "nodes": nodes,
            "edges": edges,
            "meta": {
                "node_count": len(nodes),
                "edge_count": len(edges),
            },
        }

    @classmethod
    def from_dict(cls, data: dict) -> 'MemoryGraph':
        """Deserialize a graph from a dict produced by :meth:`to_dict`.

        Creates a new in-memory MemoryGraph and populates it.
        """
        mg = cls()
        for n in data.get("nodes", []):
            mg.conn.execute(
                """INSERT OR REPLACE INTO nodes
                   (id,label,kind,data,created,accessed,weight,tags)
                   VALUES (?,?,?,?,?,?,?,?)""",
                (n["id"], n["label"], n.get("kind", "fact"),
                 json.dumps(n.get("data", {})),
                 n.get("created", time.time()), n.get("accessed", time.time()),
                 n.get("weight", 1.0), json.dumps(n.get("tags", [])))
            )
        for e in data.get("edges", []):
            mg.conn.execute(
                "INSERT OR IGNORE INTO edges (source,target,relation,weight) VALUES (?,?,?,?)",
                (e["source"], e["target"], e["relation"], e.get("weight", 1.0))
            )
        mg.conn.commit()
        if getattr(mg, '_fts_enabled', False):
            mg._rebuild_fts()
        return mg

    # ─────────────────────────────────────────────
    # Cycle 195: Graph Contraction (Supernode Collapse)
    # ─────────────────────────────────────────────

    def contract_nodes(self, node_ids: list[str],
                       supernode_label: str,
                       kind: str = "supernode",
                       data: dict = None,
                       quarantine_members: bool = True) -> dict:
        """Collapse a set of nodes into a single supernode.

        External edges to/from any member node are redirected to the
        supernode with aggregated weights (sum).  Internal edges between
        contracted members are dropped (not converted to self-loops).

        Use cases:
        - Multi-resolution graph views (collapse communities)
        - Entity merging / deduplication
        - Abstraction hierarchies

        Args:
            node_ids: IDs of nodes to contract (must exist).
            supernode_label: Label for the new supernode.
            kind: Kind for the supernode (default "supernode").
            data: Optional extra data to set on the supernode.
                  Member node data is merged under "contracted_from".
            quarantine_members: If True, quarantine member nodes
                                (preserving audit trail) instead of deleting.

        Returns a dict:
            supernode_id, member_ids, edges_redirected, internal_edges_dropped
        """
        # Validate	node_ids
        existing = set()
        for nid in node_ids:
            row = self.conn.execute(
                "SELECT id FROM nodes WHERE id = ?", (nid,)
            ).fetchone()
            if row:
                existing.add(nid)
        if len(existing) < 2:
            return {"supernode_id": None, "error": "Need ≥2 existing nodes to contract"}

        member_ids = list(existing)
        member_set = set(member_ids)

        # Create supernode
        sn = self.add(supernode_label, kind=kind,
                      data=data or {}, tags=["contracted"])

        # Merge member data
        contracted_from = {}
        for nid in member_ids:
            row = self.conn.execute(
                "SELECT label, kind, data, weight FROM nodes WHERE id = ?", (nid,)
            ).fetchone()
            if row:
                contracted_from[nid] = {
                    "label": row["label"],
                    "kind": row["kind"],
                    "weight": row["weight"],
                }
        sn_member_data = json.loads(
            self.conn.execute("SELECT data FROM nodes WHERE id = ?", (sn.id,)).fetchone()["data"]
        )
        sn_member_data["contracted_from"] = contracted_from
        self.conn.execute(
            "UPDATE nodes SET data = ? WHERE id = ?",
            (json.dumps(sn_member_data), sn.id)
        )

        edges_redirected = 0
        internal_edges_dropped = 0

        # Redirect external edges → supernode
        edges_to_process = []
        for nid in member_ids:
            for r in self.conn.execute(
                "SELECT source, target, relation, weight FROM edges WHERE source = ? OR target = ?",
                (nid, nid)
            ).fetchall():
                edges_to_process.append(dict(r))

        seen_edge_keys = {}  # (new_source, new_target, relation) → summed weight
        seen_internal = set()  # (src, tgt, rel) dedup for internal edges

        for e in edges_to_process:
            src, tgt, rel, w = e["source"], e["target"], e["relation"], e["weight"]
            is_internal = src in member_set and tgt in member_set
            if is_internal:
                # Count each internal edge once (skip duplicates from reverse scan)
                ikey = (src, tgt, rel)
                if ikey not in seen_internal:
                    internal_edges_dropped += 1
                    seen_internal.add(ikey)
                continue
            # Map endpoints
            new_src = sn.id if src in member_set else src
            new_tgt = sn.id if tgt in member_set else tgt
            key = (new_src, new_tgt, rel)
            if key in seen_edge_keys:
                seen_edge_keys[key] += w
            else:
                seen_edge_keys[key] = w
            edges_redirected += 1

        # Write aggregated edges
        for (new_src, new_tgt, rel), total_w in seen_edge_keys.items():
            self.conn.execute(
                """INSERT INTO edges (source, target, relation, weight)
                   VALUES (?,?,?,?)
                   ON CONFLICT(source,target,relation) DO UPDATE SET weight = weight + ?""",
                (new_src, new_tgt, rel, total_w, total_w)
            )
            # Merge edge props if any
            for old_nid in member_ids:
                old_src = old_nid if new_src == sn.id else new_src
                old_tgt = old_nid if new_tgt == sn.id else new_tgt
                prop_row = self.conn.execute(
                    "SELECT properties FROM edge_props WHERE source=? AND target=? AND relation=?",
                    (old_src, old_tgt, rel)
                ).fetchone()
                if prop_row:
                    props = json.loads(prop_row["properties"])
                    if props:
                        existing_prop = self.conn.execute(
                            "SELECT properties FROM edge_props WHERE source=? AND target=? AND relation=?",
                            (new_src, new_tgt, rel)
                        ).fetchone()
                        merged = json.loads(existing_prop["properties"]) if existing_prop else {}
                        merged.update(props)
                        self.conn.execute(
                            """INSERT OR REPLACE INTO edge_props (source,target,relation,properties)
                               VALUES (?,?,?,?)""",
                            (new_src, new_tgt, rel, json.dumps(merged))
                        )

        # Remove old edges touching members
        for nid in member_ids:
            self.conn.execute(
                "DELETE FROM edges WHERE source = ? OR target = ?", (nid, nid)
            )
            self.conn.execute(
                "DELETE FROM edge_props WHERE source = ? OR target = ?", (nid, nid)
            )

        # Quarantine or delete members
        if quarantine_members:
            for nid in member_ids:
                self.conn.execute(
                    """UPDATE nodes SET quarantined = 1, quarantine_reason = ?
                       WHERE id = ?""",
                    (f"contracted into {sn.id}", nid)
                )

        self.conn.commit()
        self._rebuild_fts()

        # Emit event
        self._emit("contract", {
            "supernode_id": sn.id,
            "member_ids": member_ids,
            "edges_redirected": edges_redirected,
        })

        return {
            "supernode_id": sn.id,
            "member_ids": member_ids,
            "edges_redirected": edges_redirected,
            "internal_edges_dropped": internal_edges_dropped,
        }

    def contract_communities(self, labels: list[str] = None,
                             max_iterations: int = 20,
                             resolution: float = 1.0) -> dict:
        """Detect communities and contract each into a supernode.

        Runs LPA community detection, then collapses each community
        into a single supernode.  Useful for multi-resolution analysis
        and graph summarisation.

        Args:
            labels: Optional list of labels for supernodes (one per
                    community).  If shorter than community count or None,
                    auto-generated as "community_N".
            max_iterations: Max LPA iterations.
            resolution: LPA resolution parameter.

        Returns a dict:
            communities_found, supernode_ids, total_edges_redirected
        """
        # Only contract non-quarantined nodes
        active_nodes = [
            r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined = 0"
            ).fetchall()
        ]
        if len(active_nodes) < 2:
            return {"communities_found": 0, "supernode_ids": [], "total_edges_redirected": 0}

        result = self.detect_communities(
            max_iterations=max_iterations, resolution=resolution
        )
        partition = result.get("node_community", {})

        # Group node IDs by community
        comm_groups = defaultdict(list)
        for nid, cid in partition.items():
            if nid in active_nodes:
                comm_groups[cid].append(nid)

        # Only contract communities with ≥2 members
        comm_groups = {k: v for k, v in comm_groups.items() if len(v) >= 2}

        supernode_ids = []
        total_redirected = 0

        for i, (cid, nids) in enumerate(sorted(comm_groups.items())):
            label = labels[i] if labels and i < len(labels) else f"community_{cid}"
            r = self.contract_nodes(nids, label, kind="community_supernode")
            if r.get("supernode_id"):
                supernode_ids.append(r["supernode_id"])
                total_redirected += r.get("edges_redirected", 0)

        return {
            "communities_found": len(comm_groups),
            "supernode_ids": supernode_ids,
            "total_edges_redirected": total_redirected,
        }

    # ── Cycle Path Detection ─────────────────────────────────────

    def find_cycle(self) -> Optional[list[str]]:
        """Find and return a cycle path in the graph (directed edges).

        Uses DFS with an explicit stack to track the current path.
        When a back-edge is found (neighbor is on the current path),
        the cycle is extracted from the path stack.

        Returns:
            A list of node IDs representing the cycle, where the first
            and last elements are equal (closed path), e.g. [A, B, C, A].
            None if no cycle exists.

        Quarantined nodes are excluded.
        """
        nodes = [
            str(r["id"]) for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined = 0"
            ).fetchall()
        ]
        if not nodes:
            return None

        adj: dict[str, list[str]] = {}
        for r in self.conn.execute(
            "SELECT source, target FROM edges "
            "WHERE source IN (SELECT id FROM nodes WHERE quarantined = 0) "
            "AND target IN (SELECT id FROM nodes WHERE quarantined = 0)"
        ).fetchall():
            adj.setdefault(str(r["source"]), []).append(str(r["target"]))

        WHITE, GRAY, BLACK = 0, 1, 2
        color = {nid: WHITE for nid in nodes}
        parent: dict[str, Optional[str]] = {nid: None for nid in nodes}

        for start in nodes:
            if color[start] != WHITE:
                continue
            stack = [(start, iter(adj.get(start, [])))]
            color[start] = GRAY
            path = [start]

            while stack:
                node, it = stack[-1]
                advanced = False
                for nb in it:
                    if color.get(nb, WHITE) == GRAY:
                        # Found back-edge → extract cycle
                        cycle_start_idx = path.index(nb)
                        cycle = path[cycle_start_idx:] + [nb]
                        return cycle
                    if color.get(nb, WHITE) == WHITE:
                        color[nb] = GRAY
                        stack.append((nb, iter(adj.get(nb, []))))
                        path.append(nb)
                        advanced = True
                        break
                if not advanced:
                    color[node] = BLACK
                    stack.pop()
                    path.pop()

        return None

    # ── Graph Periphery ──────────────────────────────────────────

    def graph_periphery(self) -> Optional[list[str]]:
        """Return nodes with maximum eccentricity (= graph diameter).

        The periphery consists of the "most distant" nodes in the graph —
        those whose shortest path to some other node equals the diameter.
        Complementary to graph_center() (nodes with eccentricity = radius).

        Returns:
            List of node IDs with eccentricity equal to the diameter.
            None for an empty graph.

        Quarantined nodes are excluded.
        """
        rows = self.conn.execute(
            "SELECT id FROM nodes WHERE quarantined = 0"
        ).fetchall()
        if not rows:
            return None

        # Build quarantine-aware adjacency once for efficiency
        active_ids = {str(r["id"]) for r in rows}
        adj: dict[str, list[str]] = {}
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = str(r["source"]), str(r["target"])
            if s in active_ids and t in active_ids:
                adj.setdefault(s, []).append(t)
                adj.setdefault(t, []).append(s)

        def _bfs_max_dist(start: str) -> int:
            """BFS returning max distance from start to any active node."""
            dists = {start: 0}
            queue = [start]
            while queue:
                cur = queue.pop(0)
                for nb in adj.get(cur, []):
                    if nb not in dists:
                        dists[nb] = dists[cur] + 1
                        queue.append(nb)
            return max(dists.values()) if dists else 0

        eccs: dict[str, int] = {}
        for row in rows:
            nid = str(row["id"])
            eccs[nid] = _bfs_max_dist(nid)

        if not eccs:
            return None

        max_ecc = max(eccs.values())
        return sorted([nid for nid, ecc in eccs.items() if ecc == max_ecc])


    # ------------------------------------------------------------------
    #  Bron-Kerbosch maximal clique enumeration (with pivoting)
    # ------------------------------------------------------------------

    def maximal_cliques(self, min_size: int = 3) -> list[list[str]]:
        """Enumerate all maximal cliques via Bron-Kerbosch with pivoting.

        A clique is a set of nodes where every pair is directly connected.
        Maximal = not a subset of any larger clique.  Useful for identifying
        tightly coupled memory clusters (e.g. redundant facts, dense
        episodic chains).

        Args:
            min_size: minimum clique size to report (default 3 = triangles+).

        Returns:
            Sorted list of cliques, each a sorted list of node IDs.
            Empty list if the graph has no cliques ≥ *min_size*.

        Quarantined nodes are excluded.
        """
        rows = self.conn.execute(
            "SELECT id FROM nodes WHERE quarantined = 0"
        ).fetchall()
        if not rows:
            return []

        active_ids = {str(r["id"]) for r in rows}
        adj: dict[str, set[str]] = {nid: set() for nid in active_ids}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = str(r["source"]), str(r["target"])
            if s in active_ids and t in active_ids:
                adj[s].add(t)
                adj[t].add(s)

        cliques: list[list[str]] = []

        def _bron_kerbosch(R: set, P: set, X: set):
            """Classic BK with Brelzig-Kernighan pivot."""
            if not P and not X:
                if len(R) >= min_size:
                    cliques.append(sorted(R))
                return
            # Choose pivot u from P ∪ X with max |P ∩ N(u)|
            pivot_pool = P | X
            pivot = max(pivot_pool, key=lambda u: len(P & adj[u]))
            for v in list(P - adj[pivot]):
                _bron_kerbosch(
                    R | {v},
                    P & adj[v],
                    X & adj[v],
                )
                P.discard(v)
                X.add(v)

        _bron_kerbosch(set(), set(adj.keys()), set())
        cliques.sort(key=lambda c: (-len(c), c))
        return cliques

    def clique_number(self) -> int:
        """Size of the largest clique (0 if empty graph, 1 if no edges)."""
        rows = self.conn.execute(
            "SELECT id FROM nodes WHERE quarantined = 0"
        ).fetchall()
        if not rows:
            return 0

        active_ids = {str(r["id"]) for r in rows}
        # Quick check: any edges at all?
        edge_count = self.conn.execute(
            "SELECT COUNT(*) FROM edges WHERE source IN (%s) AND target IN (%s)"
            % (",".join("?" * len(active_ids)), ",".join("?" * len(active_ids))),
            list(active_ids) * 2,
        ).fetchone()[0]
        if edge_count == 0:
            return 1 if active_ids else 0

        all_cliques = self.maximal_cliques(min_size=1)
        return max((len(c) for c in all_cliques), default=1 if active_ids else 0)

    def largest_clique(self) -> list[str]:
        """The single largest maximal clique (sorted node IDs).

        Returns an empty list if the graph has no nodes.
        """
        all_cliques = self.maximal_cliques(min_size=1)
        if not all_cliques:
            # No edges — but maybe single nodes exist
            rows = self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined = 0 ORDER BY id LIMIT 1"
            ).fetchall()
            return [str(rows[0]["id"])] if rows else []
        return all_cliques[0]

    # ------------------------------------------------------------------
    #  Clique Overlap Analysis
    # ------------------------------------------------------------------

    def clique_overlap_matrix(self) -> dict[tuple[int, int], int]:
        """Compute shared-node counts between all pairs of maximal cliques.

        For each pair of maximal cliques (i, j) where i < j, records how
        many nodes they share.  Only pairs with overlap ≥ 1 are included.

        Returns:
            Dict mapping (clique_i_index, clique_j_index) → shared_node_count.
            Indices refer to positions in ``maximal_cliques(min_size=1)``.
            Empty dict if fewer than 2 cliques exist.

        Quarantined nodes are excluded.
        """
        cliques = self.maximal_cliques(min_size=1)
        if len(cliques) < 2:
            return {}

        # Convert to sets for O(1) intersection
        sets = [set(c) for c in cliques]
        result: dict[tuple[int, int], int] = {}
        for i in range(len(sets)):
            for j in range(i + 1, len(sets)):
                shared = len(sets[i] & sets[j])
                if shared > 0:
                    result[(i, j)] = shared
        return result

    # ------------------------------------------------------------------
    #  Clique Percolation Method (CPM) — overlapping community detection
    # ------------------------------------------------------------------

    def k_clique_communities(self, k: int = 3) -> list[list[str]]:
        """Detect overlapping communities via the Clique Percolation Method.

        Palla et al. (2005).  Two k-cliques are considered adjacent if they
        share k-1 nodes.  Communities are the connected components of the
        clique-clique adjacency graph.  Unlike Label Propagation or Leiden,
        nodes may belong to *multiple* communities simultaneously.

        Args:
            k: clique size for percolation (default 3).  Must be ≥ 2.

        Returns:
            List of communities, each a sorted list of node IDs.
            Communities are sorted by size (desc) then lexicographically.
            Empty list if the graph has no k-cliques.

        Raises:
            ValueError: if k < 2.

        Quarantined nodes are excluded.
        """
        if k < 2:
            raise ValueError("k must be >= 2")

        cliques = self.maximal_cliques(min_size=k)
        if not cliques:
            return []

        # Build clique adjacency: two cliques are adjacent if they share ≥ k-1 nodes
        clique_sets = [set(c) for c in cliques]
        n = len(clique_sets)
        adj: dict[int, list[int]] = {i: [] for i in range(n)}

        for i in range(n):
            for j in range(i + 1, n):
                if len(clique_sets[i] & clique_sets[j]) >= k - 1:
                    adj[i].append(j)
                    adj[j].append(i)

        # Connected components via BFS → each component is a CPM community
        visited = set()
        communities: list[list[str]] = []

        for start in range(n):
            if start in visited:
                continue
            # BFS to collect this component
            component_cliques = []
            queue = [start]
            visited.add(start)
            while queue:
                cur = queue.pop(0)
                component_cliques.append(cur)
                for nb in adj[cur]:
                    if nb not in visited:
                        visited.add(nb)
                        queue.append(nb)

            # Union all nodes from all cliques in the component
            members: set[str] = set()
            for ci in component_cliques:
                members |= clique_sets[ci]
            communities.append(sorted(members))

        communities.sort(key=lambda c: (-len(c), c))
        return communities

    # ─────────────────────────────────────────────
    # Cycle 199: Katz Centrality
    # ─────────────────────────────────────────────

    def katz_centrality(self, alpha: float = 0.1,
                        beta: float = 1.0,
                        iterations: int = 100,
                        tolerance: float = 1e-6,
                        include_quarantined: bool = False
                        ) -> dict[str, float]:
        """Compute Katz centrality for all nodes.

        Katz centrality generalises eigenvector centrality with an
        attenuation factor *alpha* that discounts long walks.  Unlike
        eigenvector centrality, it converges for disconnected graphs
        because each node receives a baseline contribution *beta*.

        The score for node *i* is::

            c_i = beta + alpha * sum(c_j for j in neighbours(i))

        Convergence is guaranteed when ``alpha < 1 / lambda_max``,
        where ``lambda_max`` is the largest eigenvalue of the adjacency
        matrix.  For typical sparse graphs (max degree *d*),
        ``alpha < 1/d`` is a safe default.

        Args:
            alpha: Attenuation factor (0 < alpha < 1).  Smaller values
                emphasise local structure; larger values approach
                eigenvector centrality.
            beta: Base contribution per node (default 1.0).
            iterations: Max iterations.
            tolerance: Convergence threshold (L1 norm).
            include_quarantined: If False, skip quarantined nodes.

        Returns ``{node_id: centrality_score}``.
        Empty dict if graph is empty.
        """
        if not 0 < alpha < 1:
            raise ValueError("alpha must be in (0, 1)")
        if beta < 0:
            raise ValueError("beta must be non-negative")

        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        n = len(node_ids)
        if n == 0:
            return {}
        if n == 1:
            return {node_ids[0]: beta}

        node_set = set(node_ids)

        # Build undirected adjacency from edges
        adj: dict[str, list[str]] = {nid: [] for nid in node_ids}
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                adj[s].append(t)
                adj[t].append(s)

        # Deduplicate
        for nid in node_ids:
            adj[nid] = list(set(adj[nid]))

        # Iterative computation: c_i = beta + alpha * sum(c_j)
        centrality = {nid: beta for nid in node_ids}

        for _ in range(iterations):
            new_c: dict[str, float] = {}
            for nid in node_ids:
                s = sum(centrality[nb] for nb in adj[nid])
                new_c[nid] = beta + alpha * s

            diff = sum(abs(new_c[nid] - centrality[nid]) for nid in node_ids)
            centrality = new_c
            if diff < tolerance:
                break

        # Normalise to [0, 1] range for comparability
        max_val = max(centrality.values()) if centrality else 1.0
        if max_val > 0:
            centrality = {nid: v / max_val for nid, v in centrality.items()}

        return centrality

    # ------------------------------------------------------------------
    # Subgraph centrality
    # ------------------------------------------------------------------
    def subgraph_centrality(self, max_order: int = 20,
                            include_quarantined: bool = False
                            ) -> dict[str, float]:
        """Compute subgraph centrality for all nodes.

        Subgraph centrality counts closed walks of all lengths,
        weighted by *1/k!* for length *k*.  It captures a node's
        participation in subgraph structures (triangles, squares,
        cycles, etc.).

        The score for node *i* is::

            sc_i = sum_{k=0}^{max_order} (A^k)_{ii} / k!

        where *A* is the adjacency matrix.  This is the *i*-th
        diagonal entry of the matrix exponential *e^A*.

        **Comparison with other centrality measures:**

        - *Degree centrality*: counts walks of length 1 only.
        - *Katz centrality*: counts **all** walks (open + closed),
          discounted by *alpha^k*.
        - *Subgraph centrality*: counts **closed** walks only,
          discounted by *1/k!*.

        Subgraph centrality naturally rewards nodes that participate
        in many triangles and short cycles, making it sensitive to
        local community structure.

        Args:
            max_order: Maximum walk length to consider (truncated
                Taylor series).  Default 20 gives >15 digits of
                accuracy for typical graphs.
            include_quarantined: If False, skip quarantined nodes.

        Returns ``{node_id: centrality_score}`` normalised to
        ``[0, 1]``.  Empty dict if graph is empty.
        """
        if max_order < 1:
            raise ValueError("max_order must be >= 1")

        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        n = len(node_ids)
        if n == 0:
            return {}
        if n == 1:
            return {node_ids[0]: 1.0}

        node_set = set(node_ids)
        idx = {nid: i for i, nid in enumerate(node_ids)}

        # Build adjacency matrix
        A = [[0.0] * n for _ in range(n)]
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                i, j = idx[s], idx[t]
                A[i][j] = 1.0
                A[j][i] = 1.0

        # Compute diagonal of exp(A) via truncated Taylor series:
        #   diag(A^0) = 1 for all i (identity)
        #   diag(A^k) += diag(A^{k-1} * A) / k!
        # Use iterative matrix multiplication keeping only diagonal.

        import math

        # diag(A^0) = all ones
        sc = [1.0] * n  # k=0 term: 1/0! = 1

        # For k=1: diag(A^1) = A[i][i] = 0 (no self-loops)
        # For k>=2: compute iteratively
        # We only need the diagonal of A^k, but computing it requires
        # the full matrix product.  For small-to-medium graphs this is
        # fine.  For large graphs we'd use a sparse approach.

        # Current power: A_power = A^k (full matrix)
        A_power = [row[:] for row in A]  # copy A as A^1

        for k in range(1, max_order + 1):
            # Add diagonal of A^k / k!
            diag = [A_power[i][i] for i in range(n)]
            inv_fact = 1.0 / math.factorial(k)
            for i in range(n):
                sc[i] += diag[i] * inv_fact

            # Compute A^{k+1} = A^k * A (if not last iteration)
            if k < max_order:
                new_power = [[0.0] * n for _ in range(n)]
                for i in range(n):
                    row = A_power[i]
                    for j in range(n):
                        if row[j] != 0.0:
                            r = row[j]
                            for col in range(n):
                                new_power[i][col] += r * A[j][col]
                A_power = new_power

        # Normalise to [0, 1]
        max_val = max(sc) if sc else 1.0
        if max_val > 0:
            sc = {node_ids[i]: sc[i] / max_val for i in range(n)}
        else:
            sc = {node_ids[i]: 0.0 for i in range(n)}

        return sc

    # ─────────────────────────────────────────────
    # Cycle 200: Memory Maturation (sigmoid activation)
    # Source: Human-Inspired Memory Architecture (arXiv:2605.08538)
    # ─────────────────────────────────────────────

    def memory_maturation(self, node_id: str, t_half: float = 24.0,
                          k: float = 6.0) -> float:
        """Compute and store sigmoid activation for a node.

        Implements the engram maturation model: new memories start
        with activation ≈ 0 (silent) and gradually mature via::

            A(t) = 1 / (1 + e^(-(t - t_half) / k))

        where *t* is age in hours, *t_half* is half-activation
        time (default 24 h), and *k* controls curve steepness.

        At t=0:     A ≈ 0.04  (nearly silent)
        At t=t_half: A = 0.50  (half-activated)
        At t=2*t_half: A ≈ 0.96 (nearly mature)

        Returns the computed activation value [0, 1].
        """
        row = self.conn.execute(
            "SELECT created FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return 0.0
        age_hours = (time.time() - row["created"]) / 3600.0
        activation = 1.0 / (1.0 + math.exp(-(age_hours - t_half) / k))
        self.conn.execute(
            "UPDATE nodes SET activation=? WHERE id=?",
            (activation, node_id),
        )
        self.conn.commit()
        return activation

    def get_activation(self, node_id: str) -> float:
        """Return the current activation strength of a node [0, 1].

        Returns 0.0 if node doesn't exist.
        """
        row = self.conn.execute(
            "SELECT activation FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return 0.0
        return row["activation"] if row["activation"] is not None else 0.0

    def is_mature(self, node_id: str, threshold: float = 0.5) -> bool:
        """Check whether a node has matured past the activation threshold.

        Convenience wrapper around :meth:`memory_maturation` + threshold
        comparison.  Updates activation before checking.
        """
        return self.memory_maturation(node_id) >= threshold

    def batch_maturation(self, t_half: float = 24.0,
                         k: float = 6.0) -> dict:
        """Update activation for every node in the graph.

        Returns a summary dict with counts by maturity bucket::

            mature   – activation ≥ 0.7
            emerging – 0.3 ≤ activation < 0.7
            silent   – activation < 0.3
        """
        rows = self.conn.execute(
            "SELECT id, created FROM nodes"
        ).fetchall()
        mature = emerging = silent = 0
        now = time.time()
        for r in rows:
            age_h = (now - r["created"]) / 3600.0
            act = 1.0 / (1.0 + math.exp(-(age_h - t_half) / k))
            self.conn.execute(
                "UPDATE nodes SET activation=? WHERE id=?",
                (act, r["id"]),
            )
            if act >= 0.7:
                mature += 1
            elif act >= 0.3:
                emerging += 1
            else:
                silent += 1
        self.conn.commit()
        return {
            "total": len(rows),
            "mature": mature,
            "emerging": emerging,
            "silent": silent,
        }

    def recall_with_activation(self, query: str, limit: int = 5,
                               activation_threshold: float = 0.5,
                               fallback_to_immature: bool = True
                               ) -> list:
        """Recall memories, filtering by activation maturity.

        Combines :meth:`recall` with activation gating.  Mature memories
        (activation ≥ *threshold*) are returned first.  If fewer than
        ``limit`` mature results are found and *fallback_to_immature*
        is True, the remaining slots are filled from immature memories.

        Returns a list of (node_id, label, kind, weight, activation) tuples.
        """
        # Refresh activations for all nodes
        self.batch_maturation()

        # Query FTS/BM25 for relevance
        candidates = self.recall(query, limit=limit * 3)

        results = []
        mature = []
        immature = []
        for node in candidates:
            act = self.get_activation(node.id)
            if act >= activation_threshold:
                mature.append((node, act))
            else:
                immature.append((node, act))

        # Sort mature by weight * activation
        mature.sort(key=lambda x: -x[0].weight * x[1])
        results.extend(mature[:limit])

        # Fallback: fill remaining slots with immature if needed
        if len(results) < limit and fallback_to_immature:
            immature.sort(key=lambda x: -x[0].weight)
            results.extend(immature[:limit - len(results)])

        return [
            (n.id, n.label, n.kind, round(n.weight, 4), round(a, 4))
            for n, a in results
        ]

    # ─────────────────────────────────────────────
    # Cycle 201: Confidence Score (Unified Trust Metric)
    # Source: Portable Agent Memory (arXiv:2605.11032)
    # ─────────────────────────────────────────────

    # Source trust levels (arXiv:2605.11032 provenance model)
    _SOURCE_TRUST = {
        "verified_user": 1.0,
        "user_corrected": 0.95,
        "llm_extracted": 0.7,
        "inferred": 0.5,
        "external": 0.3,
        "unknown": 0.2,
    }

    def confidence_score(self, node_id: str, conflicts: int = 0,
                         w_source: float = 0.30,
                         w_consistency: float = 0.25,
                         w_freshness: float = 0.15,
                         w_corroboration: float = 0.20,
                         w_transformation: float = 0.10) -> float:
        """Compute and store a unified confidence score [0, 1].

        Combines five dimensions from the Portable Agent Memory
        provenance model (arXiv:2605.11032)::

            source        – who said it (provenance trust)
            consistency   – conflicts with existing knowledge?
            freshness     – exponential decay (30-day half-life)
            corroboration – how many times accessed/confirmed
            transformation – information loss from merges/summaries

        Returns the computed confidence [0.0, 1.0].
        """
        row = self.conn.execute(
            "SELECT source, trust_level, created, accessed, "
            "weight, transform_count FROM nodes WHERE id=?",
            (node_id,),
        ).fetchone()
        if not row:
            return 0.0

        # 1. Source trust
        src = row["source"] or "unknown"
        source_score = self._SOURCE_TRUST.get(src, row["trust_level"] or 0.2)

        # 2. Consistency (conflict penalty)
        consistency_score = max(0.0, 1.0 - 0.3 * conflicts)

        # 3. Freshness (30-day half-life exponential decay)
        age_days = (time.time() - row["created"]) / 86400.0
        freshness_score = math.exp(-0.693 * age_days / 30.0)

        # 4. Corroboration (access frequency as proxy)
        # Use weight as access proxy if accessed timestamps are close to created
        access_proxy = row["weight"] * 10  # scale weight to log domain
        corroboration_score = min(1.0, math.log(access_proxy + 1) / math.log(10))

        # 5. Transformation cost
        tc = row["transform_count"] or 0
        transformation_score = 1.0 / (1.0 + 0.2 * tc)

        confidence = (
            w_source * source_score
            + w_consistency * consistency_score
            + w_freshness * freshness_score
            + w_corroboration * corroboration_score
            + w_transformation * transformation_score
        )

        confidence = round(confidence, 4)
        self.conn.execute(
            "UPDATE nodes SET confidence=? WHERE id=?",
            (confidence, node_id),
        )
        self.conn.commit()
        return confidence

    def get_confidence(self, node_id: str) -> float:
        """Return the stored confidence score of a node [0, 1]."""
        row = self.conn.execute(
            "SELECT confidence FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return 0.0
        return row["confidence"] if row["confidence"] is not None else 0.5

    def batch_confidence(self, conflict_map: dict = None) -> dict:
        """Score all nodes. *conflict_map*: ``{node_id: conflict_count}``.

        Returns summary stats.
        """
        conflict_map = conflict_map or {}
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        scored = 0
        low_confidence = []
        total_conf = 0.0
        for r in rows:
            c = self.confidence_score(r["id"], conflict_map.get(r["id"], 0))
            scored += 1
            total_conf += c
            if c < 0.3:
                low_confidence.append(r["id"])
        return {
            "scored": scored,
            "avg_confidence": round(total_conf / max(scored, 1), 4),
            "low_confidence_ids": low_confidence,
        }

    def set_source(self, node_id: str, source: str) -> bool:
        """Set the provenance source for a node.

        Recognized sources (from arXiv:2605.11032):
        ``verified_user``, ``user_corrected``, ``llm_extracted``,
        ``inferred``, ``external``, ``unknown``.
        """
        row = self.conn.execute(
            "SELECT id FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return False
        self.conn.execute(
            "UPDATE nodes SET source=? WHERE id=?", (source, node_id)
        )
        self.conn.commit()
        return True

    def increment_transform(self, node_id: str) -> int:
        """Increment transform_count (call after merge/summarize).

        Returns the new transform_count value.
        """
        row = self.conn.execute(
            "SELECT transform_count FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return 0
        tc = (row["transform_count"] or 0) + 1
        self.conn.execute(
            "UPDATE nodes SET transform_count=? WHERE id=?", (tc, node_id)
        )
        self.conn.commit()
        return tc

    # ─────────────────────────────────────────────
    # Cycle 202: Forgetting Curve (Ebbinghaus + FOREVER)
    # Source: FOREVER (arXiv:2601.03938, ACL 2026)
    # ─────────────────────────────────────────────

    def forgetting_curve(self, node_id: str,
                         graph_activity: float = 0.5) -> float:
        """Compute and apply Ebbinghaus forgetting curve with adaptive intensity.

        Implements the FOREVER model's insight: memory decay should
        account for graph activity, not just wall-clock time.

        Retention formula::

            R(t) = e^(-0.693 * t / S_eff)

        Where effective stability *S_eff* combines:
          - base half-life (default 168h = 1 week)
          - access reinforcement (spaced repetition, ×1.5 per access)
          - activity adjustment (high activity → slower decay)
          - Q-value bonus (important memories last longer)

        Updates the node's weight to the computed retention.
        Returns retention [0, 1].
        """
        row = self.conn.execute(
            "SELECT created, accessed, weight, q_value FROM nodes WHERE id=?",
            (node_id,),
        ).fetchone()
        if not row:
            return 0.0

        base_half_life = 168.0       # 1 week default
        reinforcement_factor = 1.5   # each access ×1.5 half-life
        intensity_sensitivity = 0.1 # activity modulation

        age_hours = (time.time() - row["created"]) / 3600.0

        # Estimate access count from weight and accessed timestamp
        time_since_access = max(0.0, (time.time() - row["accessed"]) / 3600.0)
        accessed_recently = time_since_access < 24.0
        access_proxy = 1 if accessed_recently else 0

        # Q-value extends half-life (Q=1 → 5x)
        q_val = row["q_value"] or 0.0
        q_multiplier = 1.0 + q_val * 4.0

        # Reinforcement (spaced repetition)
        access_multiplier = reinforcement_factor ** access_proxy

        # Activity adjustment (FOREVER-inspired)
        activity_multiplier = 1.0 + intensity_sensitivity * graph_activity

        s_eff = (
            base_half_life
            * access_multiplier
            * activity_multiplier
            * q_multiplier
        )

        retention = math.exp(-0.693 * age_hours / s_eff)
        retention = max(0.0, min(1.0, retention))

        self.conn.execute(
            "UPDATE nodes SET weight=? WHERE id=?",
            (retention, node_id),
        )
        self.conn.commit()
        return retention

    def batch_forgetting(self, graph_activity: float = 0.5) -> dict:
        """Apply forgetting curve to all nodes.

        Returns stats including which nodes fell below the minimum
        weight threshold and should be considered "forgotten".
        """
        min_weight = 0.05
        rows = self.conn.execute(
            "SELECT id, created, accessed, weight, q_value FROM nodes"
        ).fetchall()
        forgotten = []
        total_retention = 0.0
        count = 0

        for r in rows:
            age_h = (time.time() - r["created"]) / 3600.0
            time_since_access = max(0.0, (time.time() - r["accessed"]) / 3600.0)
            access_proxy = 1 if time_since_access < 24.0 else 0
            q_val = r["q_value"] or 0.0

            q_mult = 1.0 + q_val * 4.0
            access_mult = 1.5 ** access_proxy
            activity_mult = 1.0 + 0.1 * graph_activity
            s_eff = 168.0 * access_mult * activity_mult * q_mult

            retention = math.exp(-0.693 * age_h / s_eff)
            retention = max(0.0, min(1.0, retention))

            self.conn.execute(
                "UPDATE nodes SET weight=? WHERE id=?",
                (retention, r["id"]),
            )
            total_retention += retention
            count += 1
            if retention < min_weight:
                forgotten.append(r["id"])

        self.conn.commit()
        return {
            "total": count,
            "forgotten": len(forgotten),
            "forgotten_ids": forgotten,
            "avg_retention": round(total_retention / max(count, 1), 4),
            "graph_activity": graph_activity,
        }

    def forgetting_curve_data(self, access_count: int = 0,
                              q_value: float = 0.0,
                              max_hours: float = 720,
                              points: int = 50) -> list:
        """Generate forgetting curve data points for visualization.

        Useful for debugging, documentation, and parameter tuning.
        Returns list of ``{"hours": float, "retention": float}``.
        """
        base_half_life = 168.0
        access_mult = 1.5 ** access_count
        q_mult = 1.0 + q_value * 4.0
        s_eff = base_half_life * access_mult * (1.0 + 0.1 * 0.5) * q_mult

        curve = []
        for i in range(points):
            t = max_hours * i / max(points - 1, 1)
            r = math.exp(-0.693 * t / s_eff)
            curve.append({"hours": round(t, 1), "retention": round(r, 4)})
        return curve

    # ─────────────────────────────────────────────
    # Cycle 208: Graph Activity Computation
    # Source: FOREVER (arXiv:2601.03938)
    # ─────────────────────────────────────────────

    def compute_graph_activity(self, window_hours: float = 1.0) -> float:
        """Compute normalised graph activity for the recent time window.

        Implements the FOREVER mapping of model-centric time → graph
        activity.  An active memory graph (many new nodes/edges per
        hour) retains memories longer, while a dormant graph
        accelerates forgetting.

        Activity is normalised to ``[0, 1]`` using a sigmoid:

        .. code-block:: text

           activity = new_events / window_hours
           normalised = sigmoid(activity - midpoint)

        where *midpoint* is auto-calibrated to the median activity
        over the graph's lifetime.

        Returns:
            Normalised activity score in ``[0, 1]``.
        """
        now = time.time()
        window_start = now - window_hours * 3600

        # Count new nodes in the window (edges don't have a created column)
        new_nodes = self.conn.execute(
            "SELECT count(*) FROM nodes WHERE created >= ?",
            (window_start,),
        ).fetchone()[0]
        # Approximate edge creation via edge_props if available
        try:
            new_edges = self.conn.execute(
                "SELECT count(*) FROM edge_props WHERE created >= ?",
                (window_start,),
            ).fetchone()[0]
        except Exception:
            new_edges = 0

        total_events = new_nodes + new_edges
        raw_rate = total_events / max(window_hours, 0.001)

        # Auto-calibrate midpoint from historical data
        oldest = self.conn.execute(
            "SELECT MIN(created) FROM nodes"
        ).fetchone()[0]
        total_nodes = self.conn.execute(
            "SELECT count(*) FROM nodes"
        ).fetchone()[0]

        if oldest and total_nodes > 0:
            lifetime_hours = max((now - oldest) / 3600.0, 1.0)
            avg_rate = total_nodes / lifetime_hours
            midpoint = max(avg_rate, 0.1)
        else:
            midpoint = 1.0  # default for empty/new graphs

        # Sigmoid normalisation
        normalised = 1.0 / (1.0 + math.exp(-(raw_rate - midpoint) / max(midpoint, 0.1)))
        return round(normalised, 4)

    def auto_forget(self, window_hours: float = 1.0) -> dict:
        """Run batch forgetting with auto-computed graph activity.

        This is a convenience wrapper around :meth:`batch_forgetting`
        that automatically computes ``graph_activity`` from recent
        graph events, following the FOREVER model: active graphs forget
        less, dormant graphs forget more.

        Returns the :meth:`batch_forgetting` result dict plus the
        computed ``graph_activity`` value.
        """
        activity = self.compute_graph_activity(window_hours)
        result = self.batch_forgetting(graph_activity=activity)
        result["graph_activity"] = activity
        result["activity_source"] = "auto"
        return result

    # ─────────────────────────────────────────────
    # Cycle 203: Recurrence Detector
    # Source: RecMem (arXiv:2605.16045, ACL 2026 Findings)
    # ─────────────────────────────────────────────

    def detect_recurrence(self, node_id: str,
                          min_recurrence: int = 3,
                          similarity_threshold: float = 0.75,
                          window_hours: float = 48.0) -> dict:
        """Detect whether a node's topic has recurred enough to trigger
        smart consolidation.

        Inspired by RecMem's three-tier subconscious architecture:
        new interactions accumulate in a subconscious layer; when the
        same topic recurs ≥ *min_recurrence* times within
        *window_hours*, a consolidation trigger is fired.

        Uses lightweight word-overlap similarity as a proxy for
        embedding cosine similarity.

        Returns a dict with trigger info, or ``{"triggered": False}``
        if no recurrence threshold was met.
        """
        target = self.get_node(node_id)
        if not target:
            return {"triggered": False, "reason": "node_not_found"}

        # Gather candidate nodes within the time window
        now = time.time()
        window_start = now - window_hours * 3600
        rows = self.conn.execute(
            "SELECT id, label FROM nodes WHERE created >= ? AND id != ?",
            (window_start, node_id),
        ).fetchall()

        # Compute word-overlap similarity
        target_words = set(target.label.lower().split())
        if not target_words:
            return {"triggered": False, "reason": "empty_content"}

        similar = []
        for r in rows:
            candidate_words = set(r["label"].lower().split())
            if not candidate_words:
                continue
            overlap = len(target_words & candidate_words)
            sim = overlap / len(target_words | candidate_words)
            if sim >= similarity_threshold:
                similar.append({"id": r["id"], "label": r["label"], "similarity": round(sim, 3)})

        total_count = len(similar) + 1  # include self

        if total_count >= min_recurrence:
            return {
                "triggered": True,
                "type": "recurrence",
                "count": total_count,
                "threshold": min_recurrence,
                "similar_nodes": similar,
                "should_consolidate": True,
                "mode": "smart",
            }

        return {
            "triggered": False,
            "count": total_count,
            "threshold": min_recurrence,
            "similar_nodes": similar,
        }

    def batch_recurrence(self, min_recurrence: int = 3,
                         similarity_threshold: float = 0.75,
                         window_hours: float = 48.0) -> dict:
        """Scan all nodes for recurrence patterns.

        Returns a summary with triggered nodes and consolidation
        candidates.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        triggers = []
        for r in rows:
            result = self.detect_recurrence(
                r["id"], min_recurrence, similarity_threshold, window_hours
            )
            if result.get("triggered"):
                triggers.append(result)

        return {
            "total_scanned": len(rows),
            "triggers": triggers,
            "trigger_count": len(triggers),
            "consolidation_candidates": len(triggers),
        }

    # ─────────────────────────────────────────────
    # Cycle 204: Consolidation Router
    # Source: Dual-Mode Consolidation Architecture (自有设计)
    # ─────────────────────────────────────────────

    def consolidation_router(self, node_id: str) -> dict:
        """Evaluate triggers and route a node to FAST or SMART consolidation.

        Inspects six trigger signals and decides whether *node_id*
        needs lightweight (FAST) or deep (SMART) consolidation:

        1. **Recurrence** – topic recurred ≥3 times → SMART
        2. **Divergence** – semantic_divergence > 0.6 → SMART
        3. **Low confidence** – confidence_score < 0.3 → FAST (flag)
        4. **Low retention** – retention_score < 0.15 → FAST (evict)
        5. **High Q-value, low activation** – promising but young → FAST (boost)
        6. **Maturation crossover** – activation crossing 0.5 → SMART

        Returns a routing decision dict with mode, trigger, reason,
        and recommended actions.
        """
        node = self.get_node(node_id)
        if not node:
            return {"node_id": node_id, "mode": "skip",
                    "reason": "node_not_found", "trigger": "none"}

        triggers = []

        # 1. Recurrence trigger
        rec = self.detect_recurrence(
            node_id, similarity_threshold=0.35)
        if rec.get("triggered"):
            triggers.append({
                "type": "recurrence",
                "mode": "smart",
                "detail": f"{rec['count']} similar nodes in window",
            })

        # 2. Divergence trigger
        div = self.semantic_divergence(node_id)
        if div and div.get("divergence", 0) > 0.6:
            triggers.append({
                "type": "divergence",
                "mode": "smart",
                "detail": f"divergence={div['divergence']:.3f}",
            })

        # 3. Low confidence trigger
        conf = self.confidence_score(node_id)
        if conf < 0.4:
            triggers.append({
                "type": "low_confidence",
                "mode": "fast",
                "detail": f"confidence={conf:.3f}",
                "action": "flag_for_review",
            })

        # 4. Low retention trigger
        ret = self.retention_score(node_id)
        if ret and ret.get("score", 1.0) < 0.15:
            triggers.append({
                "type": "low_retention",
                "mode": "fast",
                "detail": f"retention={ret['score']:.3f}",
                "action": "evict_candidate",
            })

        # 5. High Q-value + low activation → boost
        act = self.get_activation(node_id)
        qval_row = self.conn.execute(
            "SELECT q_value FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        qval = qval_row["q_value"] if qval_row else 0.0
        if qval > 0.5 and act < 0.3:
            triggers.append({
                "type": "high_q_low_activation",
                "mode": "fast",
                "detail": f"q={qval:.3f}, activation={act:.3f}",
                "action": "boost_activation",
            })

        # 6. Maturation crossover → SMART (just crossed threshold)
        if 0.45 <= act <= 0.55:
            triggers.append({
                "type": "maturation_crossover",
                "mode": "smart",
                "detail": f"activation={act:.3f} (near 0.5)",
            })

        # Decide: if any SMART trigger → SMART; else if FAST → FAST; else IDLE
        smart_triggers = [t for t in triggers if t["mode"] == "smart"]
        fast_triggers = [t for t in triggers if t["mode"] == "fast"]

        if smart_triggers:
            mode = "smart"
            primary = smart_triggers[0]
        elif fast_triggers:
            mode = "fast"
            primary = fast_triggers[0]
        else:
            mode = "idle"
            primary = None

        return {
            "node_id": node_id,
            "mode": mode,
            "trigger": primary["type"] if primary else "none",
            "reason": primary["detail"] if primary else "no triggers fired",
            "action": primary.get("action") if primary else None,
            "all_triggers": triggers,
            "trigger_count": len(triggers),
        }

    def batch_consolidation_routing(self) -> dict:
        """Route every node in the graph and return a routing summary.

        Returns counts by mode plus per-node routing decisions.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        decisions = []
        smart_count = fast_count = idle_count = 0

        for r in rows:
            decision = self.consolidation_router(r["id"])
            decisions.append(decision)
            if decision["mode"] == "smart":
                smart_count += 1
            elif decision["mode"] == "fast":
                fast_count += 1
            else:
                idle_count += 1

        return {
            "total": len(rows),
            "smart": smart_count,
            "fast": fast_count,
            "idle": idle_count,
            "decisions": decisions,
        }

    # ===================================================================
    # Laplacian Centrality (Network Disruption Importance)
    # ===================================================================

    def laplacian_centrality(self, include_quarantined: bool = False
                             ) -> dict[str, float]:
        """Compute Laplacian centrality for all nodes.

        Laplacian centrality measures the importance of each node
        by quantifying how much the graph's *Laplacian energy*
        drops when that node (and all its edges) is removed.

        The Laplacian energy of a graph is defined as the sum of
        squared eigenvalues of the Laplacian matrix *L = D - A*::

            E_L(G) = tr(L²) = Σ_i d_i² + 2m

        where *d_i* is the degree of node *i* and *m* is the number
        of edges.

        When node *v* is removed, the energy drop is::

            C_L(v) = d_v² + d_v + 2·Σ_{u ∈ N(v)} d_u

        This captures both direct importance (*d_v²*) and indirect
        importance through neighbours (the sum of neighbour degrees).

        **Comparison with other centrality measures:**

        - *Degree centrality*: counts direct connections only.
        - *Betweenness centrality*: measures path mediation.
        - *Eigenvector centrality*: importance from important neighbours.
        - *Subgraph centrality*: closed-walk participation.
        - *Laplacian centrality*: **network disruption potential** —
          how much connectivity is lost if this node disappears.

        Laplacian centrality rewards nodes that are both highly
        connected themselves AND connected to other highly-connected
        nodes, making it sensitive to critical bridging roles.

        Args:
            include_quarantined: If False, skip quarantined nodes.

        Returns ``{node_id: centrality_score}`` normalised to
        ``[0, 1]``.  Empty dict if graph is empty.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        n = len(node_ids)
        if n == 0:
            return {}
        if n == 1:
            return {node_ids[0]: 1.0}

        node_set = set(node_ids)

        # Build adjacency lists and compute degrees
        neighbors: dict[str, list[str]] = {nid: [] for nid in node_ids}
        degree: dict[str, int] = {nid: 0 for nid in node_ids}

        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                neighbors[s].append(t)
                neighbors[t].append(s)
                degree[s] += 1
                degree[t] += 1

        # Laplacian centrality: C_L(v) = d_v² + d_v + 2·Σ_{u ∈ N(v)} d_u
        scores: dict[str, float] = {}
        for nid in node_ids:
            dv = degree[nid]
            neighbor_degree_sum = sum(degree[u] for u in neighbors[nid])
            scores[nid] = float(dv * dv + dv + 2 * neighbor_degree_sum)

        # Normalise to [0, 1]
        max_val = max(scores.values()) if scores else 1.0
        if max_val > 0:
            scores = {nid: scores[nid] / max_val for nid in node_ids}
        else:
            scores = {nid: 0.0 for nid in node_ids}

        return scores

    # ── Matrix-exponential graph metrics ───────────────────

    def _adjacency_matrix(self, node_ids: list[str],
                          node_set: set[str]) -> list[list[float]]:
        """Build symmetric adjacency matrix for given node set."""
        n = len(node_ids)
        idx = {nid: i for i, nid in enumerate(node_ids)}
        A = [[0.0] * n for _ in range(n)]
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                i, j = idx[s], idx[t]
                A[i][j] = 1.0
                A[j][i] = 1.0
        return A

    def estrada_index(self, max_order: int = 20,
                      include_quarantined: bool = False) -> float:
        """Compute the Estrada index of the graph.

        The Estrada index measures overall *well-connectedness*.
        It is the trace of the matrix exponential::

            EE = tr(e^A) = Σ_{k=0}^{∞} tr(A^k) / k!

        where *A* is the adjacency matrix.  Equivalently,
        ``EE = Σ_i e^(λ_i)`` where *λ_i* are eigenvalues of *A*.

        **Interpretation:**

        - Counts total closed walks of all lengths, weighted by *1/k!*.
        - Higher EE → densely / redundantly connected graph.
        - Lower EE → sparse, tree-like structure.
        - EE is always ≥ *n* (the identity contribution from *k=0*).
        - Sensitive to triangles and short cycles (like subgraph centrality,
          but aggregated to the entire graph).

        **Comparison with other graph-level metrics:**

        - *Graph density*: edges / possible edges — ignores topology.
        - *Transitivity*: 3 × triangles / triads — only considers *k=3*.
        - *Estrada index*: considers *all* closed walk lengths, weighted
          by *1/k!* so short cycles dominate but longer ones contribute.

        Args:
            max_order: Maximum walk length (Taylor series truncation).
                Default 20 gives >15 digits of accuracy.
            include_quarantined: If False, skip quarantined nodes.

        Returns the Estrada index as a float.  Returns ``0.0`` for
        an empty graph, ``float(n)`` for *n* nodes with no edges
        (each isolated node contributes exactly *1* from the *k=0*
        identity term).
        """
        if max_order < 1:
            raise ValueError("max_order must be >= 1")

        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        n = len(node_ids)
        if n == 0:
            return 0.0

        node_set = set(node_ids)
        A = self._adjacency_matrix(node_ids, node_set)

        import math

        # EE = Σ_k tr(A^k) / k!
        # tr(A^0) = n  (identity matrix)
        # tr(A^1) = 0   (no self-loops, diagonal is zero)
        # tr(A^2) = 2m  (each edge contributes 2 back-and-forth walks)
        # tr(A^3) = 6 × (number of triangles)

        ee = float(n)  # k=0 term: tr(I)/0! = n

        A_power = [row[:] for row in A]  # A^1
        for k in range(1, max_order + 1):
            trace = sum(A_power[i][i] for i in range(n))
            ee += trace / math.factorial(k)

            if k < max_order:
                # A^{k+1} = A^k × A
                new_power = [[0.0] * n for _ in range(n)]
                for i in range(n):
                    row = A_power[i]
                    for j in range(n):
                        if row[j] != 0.0:
                            r = row[j]
                            for col in range(n):
                                new_power[i][col] += r * A[j][col]
                A_power = new_power

        return ee

    def communicability(self, node_a: str, node_b: str,
                        max_order: int = 20,
                        include_quarantined: bool = False) -> float:
        """Compute communicability between two nodes.

        Communicability measures how easily information flows between
        *node_a* and *node_b*, considering **all** paths (not just
        shortest paths).  It is the *(a, b)* entry of the matrix
        exponential::

            G(a, b) = (e^A)_{ab} = Σ_{k=0}^{∞} (A^k)_{ab} / k!

        **Interpretation:**

        - Higher value → more / shorter paths between the two nodes.
        - ``G(a, a)`` equals the subgraph centrality of *a* (before
          normalisation).
        - Two nodes connected by many short paths have higher
          communicability than two nodes connected by one long path.
        - Sensitive to triangles: if *a* and *b* share common neighbours,
          their communicability is boosted.

        **Comparison with shortest-path metrics:**

        - *Shortest path*: only the single shortest route matters.
        - *Communicability*: all walks contribute, shorter ones weighted
          more heavily by *1/k!*.

        Args:
            node_a, node_b: Node IDs to compute communicability for.
            max_order: Maximum walk length (Taylor series truncation).
                Default 20 gives >15 digits of accuracy.
            include_quarantined: If False, skip quarantined nodes.

        Returns the communicability score as a float.  Returns ``0.0``
        if either node does not exist (or is quarantined and excluded).
        Self-communicability (``node_a == node_b``) returns the
        subgraph centrality (unnormalised).
        """
        if max_order < 1:
            raise ValueError("max_order must be >= 1")

        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        n = len(node_ids)
        if n == 0:
            return 0.0

        node_set = set(node_ids)
        if node_a not in node_set or node_b not in node_set:
            return 0.0

        idx = {nid: i for i, nid in enumerate(node_ids)}
        ia, ib = idx[node_a], idx[node_b]

        A = self._adjacency_matrix(node_ids, node_set)

        import math

        # (e^A)_{ab} = Σ_k (A^k)_{ab} / k!
        # k=0: (I)_{ab} = 1 if a==b, else 0
        score = 1.0 if ia == ib else 0.0

        A_power = [row[:] for row in A]  # A^1
        for k in range(1, max_order + 1):
            score += A_power[ia][ib] / math.factorial(k)

            if k < max_order:
                new_power = [[0.0] * n for _ in range(n)]
                for i in range(n):
                    row = A_power[i]
                    for j in range(n):
                        if row[j] != 0.0:
                            r = row[j]
                            for col in range(n):
                                new_power[i][col] += r * A[j][col]
                A_power = new_power

        return score

    # ------------------------------------------------------------------
    # Natural connectivity + Effective resistance + Information centrality
    # ------------------------------------------------------------------

    def natural_connectivity(self, max_order: int = 20,
                             include_quarantined: bool = False) -> float:
        """Natural connectivity — size-normalised robustness measure.

        Also known as the *average subgraph centrality* or the
        *logarithm of the mean Estrada index*::

            λ̄ = ln(EE / n)

        where *EE* is the Estrada index and *n* the node count.

        **Why normalise?**

        The raw Estrada index scales with graph size — a path of 50
        nodes has larger EE than a path of 5 nodes, even though both
        are equally "path-like".  Natural connectivity removes this
        size bias, enabling fair comparison across graphs of different
        orders.

        **Interpretation:**

        - Higher λ̄ → more robust / redundant connectivity.
        - For a complete graph *K_n*: λ̄ ≈ *n-1* (maximum for *n* nodes).
        - For a path graph: λ̄ ≈ 0 (minimal connectivity).
        - For an empty graph: λ̄ = 0 exactly (each node isolated, EE = n,
          ln(1) = 0).

        Args:
            max_order: Taylor series truncation for Estrada index.
            include_quarantined: If False, skip quarantined nodes.

        Returns the natural connectivity as a float.  Returns ``0.0``
        for an empty graph.
        """
        import math

        if include_quarantined:
            count = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        else:
            count = self.conn.execute(
                "SELECT COUNT(*) FROM nodes WHERE quarantined=0"
            ).fetchone()[0]

        if count == 0:
            return 0.0

        ee = self.estrada_index(max_order, include_quarantined)
        return math.log(ee / count)

    def _laplacian_pseudoinverse(self, node_ids: list[str],
                                 node_set: set[str]) -> list[list[float]] | None:
        """Compute the Moore-Penrose pseudoinverse of the graph Laplacian.

        Uses the formula (for connected graphs)::

            L⁺ = (L + J/n)⁻¹ − J/n

        where *J* is the all-ones matrix and *n* the node count.
        This requires one *n×n* matrix inversion via Gaussian elimination.

        Returns ``None`` if the graph has 0 or 1 nodes.
        """
        n = len(node_ids)
        if n <= 1:
            return None

        idx = {nid: i for i, nid in enumerate(node_ids)}

        # Build Laplacian L = D − A
        L = [[0.0] * n for _ in range(n)]
        degrees = [0] * n
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                i, j = idx[s], idx[t]
                L[i][j] -= 1.0
                L[j][i] -= 1.0
                degrees[i] += 1
                degrees[j] += 1
        for i in range(n):
            L[i][i] = float(degrees[i])

        # L⁺ = (L + J/n)⁻¹ − J/n
        # Add J/n to L
        jn = 1.0 / n
        M = [[L[i][j] + jn for j in range(n)] for i in range(n)]

        # Invert M via Gauss-Jordan elimination with partial pivoting
        # Augmented matrix [M | I]
        aug = [[M[i][j] for j in range(n)] + [
            1.0 if i == j else 0.0 for j in range(n)
        ] for i in range(n)]

        for col in range(n):
            # Partial pivot: find row with largest |value| in this column
            pivot_row = col
            max_val = abs(aug[col][col])
            for row in range(col + 1, n):
                if abs(aug[row][col]) > max_val:
                    max_val = abs(aug[row][col])
                    pivot_row = row

            if max_val < 1e-14:
                # Singular — fall back gracefully
                return None

            # Swap rows
            if pivot_row != col:
                aug[col], aug[pivot_row] = aug[pivot_row], aug[col]

            # Scale pivot row
            pivot_val = aug[col][col]
            inv_pivot = 1.0 / pivot_val
            for j in range(2 * n):
                aug[col][j] *= inv_pivot

            # Eliminate column in all other rows
            for row in range(n):
                if row == col:
                    continue
                factor = aug[row][col]
                if factor != 0.0:
                    for j in range(2 * n):
                        aug[row][j] -= factor * aug[col][j]

        # Extract inverse from augmented matrix
        inv = [[aug[i][n + j] for j in range(n)] for i in range(n)]

        # Subtract J/n
        L_plus = [[inv[i][j] - jn for j in range(n)] for i in range(n)]

        return L_plus

    def effective_resistance(self, node_a: str, node_b: str,
                             *, include_quarantined: bool = False) -> float:
        """Effective resistance between two nodes (electrical analogy).

        Treats the graph as an electrical circuit where each edge is a
        1-ohm resistor.  The effective resistance *R(a, b)* is the
        resistance measured between nodes *a* and *b*.

        Computed via the Laplacian pseudoinverse::

            R(a, b) = L⁺_{aa} + L⁺_{bb} − 2·L⁺_{ab}

        **Interpretation:**

        - Lower resistance → many short paths → well connected.
        - Higher resistance → few / long paths → poorly connected.
        - For directly connected nodes in a tree: *R = 1*.
        - For nodes in a triangle: *R = 2/3* (parallel paths reduce it).
        - For disconnected nodes: *R = ∞* (returns ``float('inf')``).

        **Relation to information centrality:**

        Information centrality uses *1 / R(a, b)* as "information flow".
        The sum *Σ_w R(v, w)* appears in the denominator.

        Args:
            node_a, node_b: Node IDs.
            include_quarantined: If False, skip quarantined nodes.

        Returns the effective resistance as a float.  Returns ``0.0``
        if either node doesn't exist.  Returns ``float('inf')`` if the
        nodes are in different connected components.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        node_set = set(node_ids)
        if node_a not in node_set or node_b not in node_set:
            return 0.0

        if node_a == node_b:
            return 0.0

        # Check connectivity (must be in same component)
        # Use the pseudoinverse: if nodes are disconnected, R = inf
        L_plus = self._laplacian_pseudoinverse(node_ids, node_set)
        if L_plus is None:
            return 0.0 if node_a == node_b else float('inf')

        idx = {nid: i for i, nid in enumerate(node_ids)}
        ia, ib = idx[node_a], idx[node_b]

        r = L_plus[ia][ia] + L_plus[ib][ib] - 2.0 * L_plus[ia][ib]

        # Numerical noise can push slightly below 0 for directly-connected nodes
        if r < 0:
            r = 0.0

        # Detect disconnection: if R is very large, nodes are likely
        # in different components.  Verify with BFS for robustness.
        if r > 1e6:
            dists = self._bfs_distances(node_a)
            if node_b not in dists:
                return float('inf')

        return r

    def information_centrality(self, *, include_quarantined: bool = False
                               ) -> dict[str, float]:
        """Information centrality — information flow efficiency per node.

        Proposed by Stephenson & Zelen (1989).  Measures how efficiently
        information flows from a node to all others, considering **all**
        paths (not just shortest paths).

        Based on *effective resistance*: the information flow between
        *v* and *w* is *I(v, w) = 1 / R(v, w)*.  The centrality of
        node *v* is::

            C_I(v) = n / Σ_w R(v, w)

        (where *R(v, v) = 0* is excluded from the sum).

        **Key properties:**

        - Captures both direct and indirect connectivity.
        - Penalises nodes at the end of long chains.
        - Rewards nodes in the centre of dense clusters.
        - For disconnected nodes, *R = ∞* so *I = 0*, which lowers
          the centrality of nodes with unreachable neighbours.

        **Comparison with other centralities:**

        - *Closeness*: uses shortest-path distance only.
        - *Betweenness*: counts paths that pass *through* a node.
        - *Information*: considers all paths via effective resistance.

        Args:
            include_quarantined: If False, skip quarantined nodes.

        Returns a dict mapping node IDs to centrality scores in
        ``[0, 1]``.  Higher = more central.  Empty graph returns ``{}``.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]

        n = len(node_ids)
        if n == 0:
            return {}
        if n == 1:
            return {node_ids[0]: 1.0}

        node_set = set(node_ids)
        L_plus = self._laplacian_pseudoinverse(node_ids, node_set)
        if L_plus is None:
            return {nid: 0.0 for nid in node_ids}

        # For each node, sum of effective resistances to all others
        # R(v, w) = L⁺_{vv} + L⁺_{ww} − 2·L⁺_{vw}
        # Σ_w R(v, w) = n·L⁺_{vv} + Σ_w L⁺_{ww} − 2·Σ_w L⁺_{vw}
        #             = n·L⁺_{vv} + tr(L⁺) − 2·(row sum of L⁺)_v
        trace_L = sum(L_plus[i][i] for i in range(n))
        row_sums = [sum(L_plus[i][j] for j in range(n)) for i in range(n)]

        scores: dict[str, float] = {}
        raw_scores: list[float] = []

        for i, nid in enumerate(node_ids):
            total_r = n * L_plus[i][i] + trace_L - 2.0 * row_sums[i]
            # Exclude self: R(v, v) should be 0, but the formula
            # includes it.  The L⁺ formula gives R(v,v) = 0 exactly
            # (L⁺_{vv} + L⁺_{vv} − 2·L⁺_{vv} = 0), so the sum is correct.

            # For disconnected nodes, total_r can be extremely large (inf).
            # Check connectivity to handle this properly.
            if total_r < 1e-10:
                # All resistances ~0 means perfectly connected (shouldn't happen
                # unless n=1).  Assign max score.
                raw_scores.append(float('inf'))
                continue

            # Check if this node can reach all others
            # (for disconnected graphs, effective resistance is infinite
            # for unreachable pairs, making the formula break down)
            dists = self._bfs_distances(nid)
            reachable = len(dists)

            if reachable < n:
                # Some nodes unreachable — penalise heavily
                # Use only reachable nodes for the sum, then penalise
                unreachable = n - reachable
                # Each unreachable pair contributes effectively infinite R
                # We approximate by adding a large penalty
                raw_scores.append(total_r + unreachable * 1e6)
            else:
                raw_scores.append(total_r)

        # C_I(v) = n / Σ_w R(v, w), then normalise to [0, 1]
        for i, nid in enumerate(node_ids):
            if raw_scores[i] == float('inf'):
                scores[nid] = 1.0
            elif raw_scores[i] >= 1e6:
                scores[nid] = 0.0  # disconnected nodes get 0
            else:
                scores[nid] = n / raw_scores[i] if raw_scores[i] > 0 else 0.0

        # Normalise to [0, 1]
        max_score = max(scores.values()) if scores else 1.0
        if max_score > 0:
            scores = {k: v / max_score for k, v in scores.items()}

        return scores

    def current_flow_betweenness(
        self,
        *,
        include_quarantined: bool = False,
        normalized: bool = True,
    ) -> dict[str, float]:
        """Current-flow betweenness centrality (Brandes & Fleischer 2007).

        Also known as *random-walk betweenness*.  Measures the expected
        number of times a random walk from *s* to *t* passes through *v*,
        averaged over all source-target pairs.

        For each pair (s, t) a unit current is injected at *s* and
        extracted at *t*.  The voltage at node *u* is::

            V_u = L\u207a_us \u2212 L\u207a_ut

        The current through node *v* (for this pair) equals half the
        sum of absolute currents on its incident edges::

            b_{st}(v) = \u00bd \u03a3_{w \u2208 N(v)} |V_v \u2212 V_w|

        Total CFB(v) = \u03a3_{s<t} b_{st}(v),  normalised by (n\u22121)(n\u22122)/2.

        Time complexity: O(n\u00b2 \u00b7 m) where *m* is the number of edges
        (acceptable for graphs up to ~ 500 nodes).

        Args:
            include_quarantined: If ``True``, include quarantined nodes.
            normalized:          If ``True``, normalise to ``[0, 1]``.

        Returns:
            ``{node_id: cf_betweenness_score}``.

        Raises:
            ValueError: If the graph has fewer than 3 nodes.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)

        if n < 3:
            raise ValueError(
                "current_flow_betweenness requires >= 3 nodes, got %d" % n
            )

        node_set = set(node_ids)
        L_plus = self._laplacian_pseudoinverse(node_ids, node_set)
        if L_plus is None:
            return {nid: 0.0 for nid in node_ids}

        idx = {nid: i for i, nid in enumerate(node_ids)}

        # Build adjacency for the subgraph
        adj: list[list[int]] = [[] for _ in range(n)]
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s_id, t_id = r["source"], r["target"]
            if s_id in node_set and t_id in node_set:
                si, ti = idx[s_id], idx[t_id]
                adj[si].append(ti)
                adj[ti].append(si)

        cfb = [0.0] * n

        for s in range(n):
            for t in range(s + 1, n):
                # Voltage at each node for unit current s -> t
                # V_u = L+_us - L+_ut
                # Current through v = (1/2) * sum |V_v - V_w| for w in N(v)
                for v in range(n):
                    if v == s or v == t:
                        continue
                    v_volt = L_plus[v][s] - L_plus[v][t]
                    flow = 0.0
                    for w in adj[v]:
                        w_volt = L_plus[w][s] - L_plus[w][t]
                        flow += abs(v_volt - w_volt)
                    cfb[v] += 0.5 * flow

        scores = {node_ids[i]: cfb[i] for i in range(n)}

        if normalized:
            norm = (n - 1) * (n - 2) / 2.0
            if norm > 0:
                scores = {k: v / norm for k, v in scores.items()}

        return scores

    def current_flow_closeness(
        self,
        *,
        include_quarantined: bool = False,
    ) -> dict[str, float]:
        """Current-flow closeness centrality (Brandes & Fleischer 2007).

        Also known as *random-walk closeness*.  For each node *v*::

            CFC(v) = (n - 1) / \u03a3_{w\u2260v} R(v, w)

        where ``R(v, w) = L\u207a_vv + L\u207a_ww \u2212 2\u00b7L\u207a_vw`` is the
        effective resistance between *v* and *w*.

        Args:
            include_quarantined: If ``True``, include quarantined nodes.

        Returns:
            ``{node_id: cf_closeness_score}`` in range ``(0, 1]``.

        Raises:
            ValueError: If the graph has fewer than 2 nodes.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)

        if n < 2:
            raise ValueError(
                "current_flow_closeness requires >= 2 nodes, got %d" % n
            )

        node_set = set(node_ids)
        L_plus = self._laplacian_pseudoinverse(node_ids, node_set)
        if L_plus is None:
            return {nid: 0.0 for nid in node_ids}

        scores: dict[str, float] = {}
        for i, nid in enumerate(node_ids):
            total_r = 0.0
            count = 0
            for j in range(n):
                if i == j:
                    continue
                r = L_plus[i][i] + L_plus[j][j] - 2.0 * L_plus[i][j]
                total_r += r
                count += 1
            if total_r > 1e-12:
                scores[nid] = count / total_r
            else:
                scores[nid] = float('inf')

        return scores

    def edge_current_flow_betweenness(
        self,
        *,
        include_quarantined: bool = False,
        normalized: bool = True,
    ) -> dict[frozenset[str], float]:
        r"""Edge current-flow betweenness centrality.

        For each edge *e = (v, w)*, measures how much electrical current
        flows through that edge when unit current is injected at *s* and
        extracted at *t*, summed over all source-target pairs (s, t)::

            c_f(e) = \u03a3_{s < t} |V\u2076\u02e2\u1d57 \u2212 V\u1d65\u02e2\u1d57|

        where ``V\u1d64\u02e2\u1d57 = L\u207a_us \u2212 L\u207a_ut``  is the voltage at
        node *u* for the (s, t) pair.

        Uses the **sorted absolute difference identity** for O(n\u00b2 log n)
        computation instead of the brute-force O(n\u2074):

        For each edge (v, w), compute the transfer-admittance vector
        ``T[j] = L\u207a[v][j] \u2212 L\u207a[w][j]``,  sort it, then apply:

            \u03a3_{s<t} |T[s] \u2212 T[t]| = \u03a3_k T_sorted[k] \u00b7 (2k \u2212 n + 1)

        Edges with high CF-betweenness are **information bottlenecks**
        \u2014 their removal most disrupts information flow in the graph.

        Args:
            include_quarantined: If ``True``, include quarantined nodes
                                 and their edges.
            normalized:          If ``True``, normalise by ``(n\u22121)(n\u22122)/2``.

        Returns:
            ``{frozenset({source_id, target_id}): score}``.

        Raises:
            ValueError: If the graph has fewer than 3 nodes.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)

        if n == 0:
            return {}

        if n < 3:
            raise ValueError(
                "edge_current_flow_betweenness requires >= 3 nodes, got %d" % n
            )

        node_set = set(node_ids)
        L_plus = self._laplacian_pseudoinverse(node_ids, node_set)
        if L_plus is None:
            return {}

        idx = {nid: i for i, nid in enumerate(node_ids)}

        # Collect unique undirected edges within the subgraph
        edges: list[tuple[int, int]] = []
        seen_pairs: set[frozenset] = set()
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s_id, t_id = r["source"], r["target"]
            if s_id in node_set and t_id in node_set:
                pair = frozenset({s_id, t_id})
                if pair not in seen_pairs and s_id != t_id:
                    seen_pairs.add(pair)
                    edges.append((idx[s_id], idx[t_id]))

        scores: dict[frozenset[str], float] = {}

        for vi, wi in edges:
            # Transfer admittance vector: T[j] = L+[v][j] - L+[w][j]
            T = sorted(L_plus[vi][j] - L_plus[wi][j] for j in range(n))

            # Sorted absolute difference identity:
            # sum_{s<t} |T[s]-T[t]| = sum_k T_sorted[k] * (2k - n + 1)
            raw = 0.0
            for k in range(n):
                raw += T[k] * (2 * k - n + 1)

            # raw is sum of |T[s]-T[t]| over all s<t pairs
            # (the identity gives the exact sum of absolute differences)
            # But since current through the edge for pair (s,t) =
            # |V_v - V_w| = |T[s] - T[t]|, we need the raw sum.
            # The identity gives Σ_{s<t} |a_s - a_t| directly.
            # No extra 1/2 factor for edges (unlike nodes).

            key = frozenset({node_ids[vi], node_ids[wi]})
            scores[key] = raw

        if normalized:
            norm = (n - 1) * (n - 2) / 2.0
            if norm > 0:
                scores = {k: v / norm for k, v in scores.items()}

        return scores

    def kirchhoff_index(self, *, include_quarantined: bool = False) -> float:
        r"""Kirchhoff index (total effective resistance) of the graph.

        The Kirchhoff index is the sum of effective resistances over all
        unordered pairs::

            Kf(G) = \u03a3_{i<j} R(i, j)

        where ``R(i, j) = L\u207a_ii + L\u207a_jj \u2212 2\u00b7L\u207a_ij``.

        Using the identity ``\u03a3_{i<j} R(i,j) = n \u00b7 tr(L\u207a)``:

        .. math::

            K_f = n \cdot \text{tr}(L^+)

        Complexity: ``O(n\u00b2)`` (dominated by pseudoinverse).

        Returns:
            Kirchhoff index (float).  ``0.0`` if < 2 nodes.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)
        if n < 2:
            return 0.0

        node_set = set(node_ids)
        L_plus = self._laplacian_pseudoinverse(node_ids, node_set)
        if L_plus is None:
            return 0.0

        trace = sum(L_plus[i][i] for i in range(n))
        return n * trace

    def spanning_tree_count(self, *, include_quarantined: bool = False) -> int:
        r"""Number of spanning trees via Kirchhoff's Matrix-Tree Theorem.

        Any cofactor of the Laplacian matrix equals the number of spanning
        trees.  Using the Laplacian pseudoinverse identity for connected
        graphs::

            \u03c4(G) = (1/n\u00b2) \u00b7 \u220f_{i=1}^{n-1} \u03bb_i

        where ``\u03bb_i`` are the non-zero eigenvalues of *L*.

        Alternatively, ``\u03c4 = (1/n) \u00b7 1/trace(L\u207a)`` for the special
        case of computing the (0,0) cofactor from ``L\u207a``:

        .. math::

            \tau(G) = \frac{(-1)^{i+j} M_{ij}}{1}

        where ``M_{ij}`` is computed from ``L`` (delete row i, col j,
        take determinant).  We use the pseudoinverse shortcut:

        .. math:: \tau(G) = \frac{n}{\prod ...}

        For practical purposes we compute ``\det(L_{sub})`` where
        ``L_{sub}`` is L with one row and column removed.

        Returns:
            Number of spanning trees (int).  ``0`` if < 2 nodes or
            disconnected.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)
        if n < 2:
            return 0

        idx = {nid: i for i, nid in enumerate(node_ids)}
        node_set = set(node_ids)

        # Build Laplacian L = D - A
        L = [[0.0] * n for _ in range(n)]
        degrees = [0] * n
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s_id, t_id = r["source"], r["target"]
            if s_id in node_set and t_id in node_set:
                si, ti = idx[s_id], idx[t_id]
                L[si][ti] -= 1.0
                L[ti][si] -= 1.0
                degrees[si] += 1
                degrees[ti] += 1
        for i in range(n):
            L[i][i] = float(degrees[i])

        # Matrix-Tree theorem: any cofactor of L = number of spanning trees
        # Remove last row and column, take determinant
        m = n - 1
        if m == 0:
            return 0
        sub = [[L[i][j] for j in range(m)] for i in range(m)]

        # Determinant via LU decomposition with partial pivoting
        det = 1.0
        for col in range(m):
            # Partial pivot
            pivot_row = col
            max_val = abs(sub[col][col])
            for row in range(col + 1, m):
                if abs(sub[row][col]) > max_val:
                    max_val = abs(sub[row][col])
                    pivot_row = row
            if max_val < 1e-14:
                return 0  # Singular → disconnected or no spanning tree
            if pivot_row != col:
                sub[col], sub[pivot_row] = sub[pivot_row], sub[col]
                det = -det
            pivot = sub[col][col]
            det *= pivot
            inv_pivot = 1.0 / pivot
            for row in range(col + 1, m):
                factor = sub[row][col] * inv_pivot
                if factor != 0.0:
                    for j in range(col, m):
                        sub[row][j] -= factor * sub[col][j]

        return int(round(det))

    def spectral_gap(self, *, include_quarantined: bool = False) -> float:
        """Spectral gap: difference between the two largest adjacency eigenvalues.

        The spectral gap ``\u03b4 = \u03bb_1 - \u03bb_2`` (where ``\u03bb_1 \u2265 \u03bb_2``
        are the top eigenvalues of the adjacency matrix) measures how well
        connected the graph is.  A larger gap implies faster mixing of random
        walks and better expansion properties.

        Uses ``_sym_eigenvalues`` (QR algorithm) on the adjacency matrix.

        Returns:
            Spectral gap (float).  ``0.0`` if < 2 nodes.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)
        if n < 2:
            return 0.0

        idx = {nid: i for i, nid in enumerate(node_ids)}
        node_set = set(node_ids)

        A = [[0.0] * n for _ in range(n)]
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s_id, t_id = r["source"], r["target"]
            if s_id in node_set and t_id in node_set:
                si, ti = idx[s_id], idx[t_id]
                A[si][ti] = 1.0
                A[ti][si] = 1.0

        eigvals = self._sym_eigenvalues(A)
        eigvals.sort(reverse=True)
        return eigvals[0] - eigvals[1] if len(eigvals) >= 2 else 0.0

    def graph_energy(self, *, include_quarantined: bool = False) -> float:
        """Graph energy: sum of absolute values of adjacency eigenvalues.

        The energy ``E(G) = \u03a3 |\u03bb_i|`` was introduced by Gutman (1978)
        and is a molecular descriptor in chemistry and a complexity
        measure in network science.

        Bounds:  ``2\u221am \u2264 E(G) \u2264 2n``  for simple graphs with
        *m* edges and *n* nodes.

        Returns:
            Graph energy (float).  ``0.0`` if no nodes.
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes"
            ).fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        node_ids.sort()
        n = len(node_ids)
        if n == 0:
            return 0.0
        if n == 1:
            return 0.0  # Single eigenvalue is 0

        idx = {nid: i for i, nid in enumerate(node_ids)}
        node_set = set(node_ids)

        A = [[0.0] * n for _ in range(n)]
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s_id, t_id = r["source"], r["target"]
            if s_id in node_set and t_id in node_set:
                si, ti = idx[s_id], idx[t_id]
                A[si][ti] = 1.0
                A[ti][si] = 1.0

        eigvals = self._sym_eigenvalues(A)
        return sum(abs(ev) for ev in eigvals)

    # ------------------------------------------------------------------
    # Personalized PageRank (HippoRAG core algorithm)
    # ------------------------------------------------------------------

    def personalized_pagerank(
        self,
        seed_ids: list[str],
        *,
        damping: float = 0.85,
        max_iter: int = 100,
        tol: float = 1e-6,
        seed_weights: list[float] | None = None,
    ) -> dict[str, float]:
        """Personalized PageRank (PPR) — topic-sensitive PageRank from seed nodes.

        Unlike global PageRank which distributes the teleport uniformly across all
        nodes, PPR teleports only to **seed_ids**, letting graph topology propagate
        relevance from the seeds.  This is the core retrieval algorithm of
        HippoRAG 2 (ICML'25): given query-matched seed nodes, PPR discovers
        multi-hop neighbours in a single propagation step.

        Args:
            seed_ids:     Nodes to teleport to (the "personalisation vector").
            damping:      ``1 - damping`` is the teleport probability per iteration.
            max_iter:     Maximum power-iteration steps.
            tol:          L1 convergence threshold.
            seed_weights: Optional non-negative weights for each seed (normalised
                          internally).  Uniform if ``None``.

        Returns:
            ``{node_id: ppr_score}`` — scores sum to ≈1.0 over all nodes.
        """
        if not seed_ids:
            return {}

        # Validate / normalise seed weights
        if seed_weights is None:
            seed_weights = [1.0] * len(seed_ids)
        if len(seed_weights) != len(seed_ids):
            raise ValueError("seed_weights length must match seed_ids length")
        total_w = sum(seed_weights)
        if total_w <= 0:
            return {}
        teleport = {}
        for sid, sw in zip(seed_ids, seed_weights):
            if sw > 0:
                teleport[sid] = teleport.get(sid, 0.0) + sw
        for sid in teleport:
            teleport[sid] /= total_w

        # Load graph
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return {}
        node_ids = [str(r["id"]) for r in rows]
        id_set = set(node_ids)

        # Filter seeds to existing nodes
        teleport = {sid: w for sid, w in teleport.items() if sid in id_set}
        if not teleport:
            return {}

        n = len(node_ids)
        rank = {nid: 0.0 for nid in node_ids}
        # Initialise: uniform over seeds
        for nid in node_ids:
            rank[nid] = teleport.get(nid, 0.0)

        # Build outbound adjacency with weights
        outbound = {nid: [] for nid in node_ids}
        outbound_count = {nid: 0 for nid in node_ids}
        edges = self.conn.execute(
            "SELECT source, target, weight FROM edges"
        ).fetchall()
        for e in edges:
            s, t = str(e["source"]), str(e["target"])
            if s in id_set and t in id_set:
                outbound[s].append(t)
                outbound_count[s] += 1

        for _ in range(max_iter):
            new_rank = {nid: 0.0 for nid in node_ids}

            # Distribute rank through edges
            for src in node_ids:
                deg = outbound_count[src]
                if deg > 0 and rank[src] > 0:
                    share = rank[src] / deg
                    for tgt in outbound[src]:
                        new_rank[tgt] += share

            # Dangling nodes: redistribute uniformly
            dangling_sum = sum(
                rank[nid] for nid in node_ids if outbound_count[nid] == 0
            )
            if dangling_sum > 0:
                for nid in node_ids:
                    new_rank[nid] += dangling_sum / n

            # Teleport to seeds only
            for nid in node_ids:
                new_rank[nid] = (
                    (1 - damping) * teleport.get(nid, 0.0)
                    + damping * new_rank[nid]
                )

            diff = sum(abs(new_rank[nid] - rank[nid]) for nid in node_ids)
            rank = new_rank
            if diff < tol:
                break

        return rank

    def ppr_retrieve(
        self,
        query: str,
        *,
        limit: int = 10,
        damping: float = 0.85,
    ) -> list[dict]:
        """Retrieve nodes via Personalized PageRank.

        Two-stage pipeline (HippoRAG pattern):
        1. Use :meth:`recall` (keyword) to find seed nodes matching *query*.
        2. Run PPR from those seeds to discover multi-hop neighbours.

        This lets graph topology participate in retrieval — a single propagation
        step finds conceptually related nodes even without keyword overlap.

        Returns a list of ``{node, ppr_score}`` dicts sorted by PPR score,
        excluding the seeds themselves.
        """
        seeds = self.recall(query, limit=max(limit, 5))
        if not seeds:
            return []
        seed_ids = [s.id for s in seeds]
        ppr = self.personalized_pagerank(seed_ids, damping=damping)
        seed_set = set(seed_ids)
        ranked = [
            {"node_id": nid, "ppr_score": score}
            for nid, score in ppr.items()
            if nid not in seed_set and score > 0
        ]
        ranked.sort(key=lambda x: x["ppr_score"], reverse=True)
        # Attach node objects
        for item in ranked[:limit]:
            item["node"] = self.get_node(item["node_id"])
        return ranked[:limit]

    # ------------------------------------------------------------------
    # Retrieval-failure logging (SAGE reader-writer feedback loop)
    # ------------------------------------------------------------------

    def log_retrieval_failure(
        self,
        query: str,
        result_count: int = 0,
        top_score: float = 0.0,
        stage: str = "recall",
    ) -> int:
        """Log a retrieval failure for later analysis.

        SAGE (2605.12061) reader-writer feedback: when retrieval returns
        few/no results or low-confidence hits, log the query so that
        :meth:`analyse_retrieval_failures` can identify missing edges
        and suggest graph improvements.

        Args:
            query:        The query that produced poor results.
            result_count: Number of results returned.
            top_score:    Score of the top result (0 if none).
            stage:        Retrieval stage (``recall``, ``ppr``, ``hybrid``).

        Returns:
            The auto-incremented failure-log row ID.
        """
        cur = self.conn.execute(
            """INSERT INTO retrieval_failures
               (query, result_count, top_score, stage, timestamp)
               VALUES (?, ?, ?, ?, ?)""",
            (query, result_count, top_score, stage, time.time()),
        )
        self.conn.commit()
        return cur.lastrowid or 0

    def get_retrieval_failures(
        self,
        *,
        since: float | None = None,
        stage: str | None = None,
        analysed_only: bool = False,
        limit: int = 100,
    ) -> list[dict]:
        """Retrieve logged retrieval failures.

        Args:
            since:        Only failures after this Unix timestamp.
            stage:        Filter by retrieval stage.
            analysed_only: If ``True``, only return analysed entries.
            limit:        Max rows.

        Returns:
            List of failure dicts sorted newest-first.
        """
        clauses = []
        params: list = []
        if since is not None:
            clauses.append("timestamp >= ?")
            params.append(since)
        if stage is not None:
            clauses.append("stage = ?")
            params.append(stage)
        if analysed_only:
            clauses.append("analysed = 1")
        where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
        params.append(limit)
        rows = self.conn.execute(
            f"""SELECT * FROM retrieval_failures{where}
               ORDER BY timestamp DESC LIMIT ?""",
            params,
        ).fetchall()
        return [dict(r) for r in rows]

    def analyse_retrieval_failures(
        self,
        *,
        min_failures: int = 3,
        since_hours: float = 24.0,
    ) -> list[dict]:
        """Analyse retrieval failures to find missing graph connections.

        Groups failures by normalised query, identifies queries that
        fail repeatedly, and checks whether existing nodes *should* have
        matched (i.e. partial label overlap exists but exact keyword
        recall missed them).

        This implements the SAGE writer feedback loop: retrieval gaps
        inform graph evolution.

        Args:
            min_failures: Minimum failures per query to flag.
            since_hours:  Only consider failures within this time window.

        Returns:
            List of analysis dicts::

                [{query, failure_count, suggested_nodes, severity}]
        """
        cutoff = time.time() - since_hours * 3600
        rows = self.conn.execute(
            """SELECT query, COUNT(*) as cnt, MAX(timestamp) as last_ts
               FROM retrieval_failures
               WHERE timestamp >= ?
               GROUP BY query
               HAVING cnt >= ?
               ORDER BY cnt DESC""",
            (cutoff, min_failures),
        ).fetchall()

        results = []
        for r in rows:
            query = r["query"]
            # Look for nodes with partial label overlap
            tokens = [t for t in query.lower().split() if len(t) > 2]
            suggested = set()
            for token in tokens:
                node_rows = self.conn.execute(
                    "SELECT id, label FROM nodes WHERE LOWER(label) LIKE ? LIMIT 5",
                    (f"%{token}%",),
                ).fetchall()
                for nr in node_rows:
                    suggested.add(nr["id"])

            results.append({
                "query": query,
                "failure_count": r["cnt"],
                "last_failure_ts": r["last_ts"],
                "suggested_node_ids": list(suggested),
                "suggestion_count": len(suggested),
                "severity": "high" if r["cnt"] >= min_failures * 2 else "medium",
            })

            # Mark these failures as analysed
            self.conn.execute(
                """UPDATE retrieval_failures SET analysed=1
                   WHERE query=? AND timestamp >= ?""",
                (query, cutoff),
            )

        self.conn.commit()
        return results

    def clear_retrieval_failures(self, older_than_hours: float | None = None) -> int:
        """Clear retrieval failure logs.

        Args:
            older_than_hours: If given, only clear entries older than this.
                              If ``None``, clear all.

        Returns:
            Number of rows deleted.
        """
        if older_than_hours is not None:
            cutoff = time.time() - older_than_hours * 3600
            cur = self.conn.execute(
                "DELETE FROM retrieval_failures WHERE timestamp < ?",
                (cutoff,),
            )
        else:
            cur = self.conn.execute("DELETE FROM retrieval_failures")
        self.conn.commit()
        return cur.rowcount

    def ppr_structured(
        self,
        seed_ids: list[str],
        *,
        damping: float = 0.85,
        max_iter: int = 100,
        tol: float = 1e-6,
        gate: str = "degree",
        gate_alpha: float = 0.5,
    ) -> dict[str, float]:
        """Structure-gated Personalized PageRank.

        SAGE-inspired (2605.12061): propagation signal is modulated by
        node centrality — structurally important nodes (bridges, hubs)
        pass more signal than peripheral leaf nodes.

        Update rule per node *v*::

            gate_v = (1 − α) + α · centrality_norm(v)
            score(v) ← (1 − damping) · teleport(v)
                      + damping · gate_v · Σ_{u→v} score(u) / deg(u)

        When ``gate_alpha = 0`` this degenerates to standard PPR.

        Args:
            seed_ids:   Seed nodes for the teleport vector.
            damping:    ``1 − damping`` teleport probability.
            max_iter:   Max power-iteration steps.
            tol:        L1 convergence threshold.
            gate:       Centrality metric used for gating —
                        ``"degree"``, ``"betweenness"``, ``"closeness"``,
                        ``"eigenvector"``, or ``"pagerank"``.
            gate_alpha: Gating strength [0, 1].
                        ``0`` = standard PPR (no gating),
                        ``1`` = pure centrality-weighted propagation.

        Returns:
            ``{node_id: gated_ppr_score}`` — normalised to sum ≈ 1.0.
        """
        if not seed_ids:
            return {}

        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if not rows:
            return {}
        node_ids = [str(r["id"]) for r in rows]
        id_set = set(node_ids)
        seed_set = {s for s in seed_ids if s in id_set}
        if not seed_set:
            return {}

        n = len(node_ids)

        # --- Build adjacency ----------------------------------------
        outbound: dict[str, list[str]] = {nid: [] for nid in node_ids}
        for r in self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall():
            s, t = str(r["source"]), str(r["target"])
            if s in id_set and t in id_set:
                outbound[s].append(t)

        # --- Compute centrality gates -------------------------------
        if gate_alpha <= 0:
            gates = {nid: 1.0 for nid in node_ids}
        else:
            raw_cen: dict[str, float] = {}
            g = gate.lower().strip()
            if g == "degree":
                for nid in node_ids:
                    raw_cen[nid] = len(outbound[nid])
            elif g == "pagerank":
                raw_cen = self.pagerank()
            elif g == "eigenvector":
                try:
                    raw_cen = self.eigenvector_all(normalized=True)
                except Exception:
                    raw_cen = {nid: float(len(outbound[nid])) for nid in node_ids}
            elif g == "betweenness":
                try:
                    raw_cen = self.betweenness_all(normalized=True)
                except Exception:
                    raw_cen = {nid: float(len(outbound[nid])) for nid in node_ids}
            elif g == "closeness":
                try:
                    raw_cen = self.closeness_all(normalized=True)
                except Exception:
                    raw_cen = {nid: float(len(outbound[nid])) for nid in node_ids}
            else:
                for nid in node_ids:
                    raw_cen[nid] = len(outbound[nid])

            # Normalise to [0, 1]
            vals = list(raw_cen.values())
            lo, hi = min(vals), max(vals)
            rng = hi - lo
            if rng < 1e-12:
                norm_cen = {nid: 1.0 for nid in node_ids}
            else:
                norm_cen = {nid: (v - lo) / rng for nid, v in raw_cen.items()}

            gates = {
                nid: (1.0 - gate_alpha) + gate_alpha * norm_cen.get(nid, 0.0)
                for nid in node_ids
            }

        # --- Initialise rank: uniform over seeds --------------------
        teleport = {nid: (1.0 / len(seed_set) if nid in seed_set else 0.0)
                    for nid in node_ids}
        rank = dict(teleport)

        # --- Power iteration with gating ----------------------------
        for _ in range(max_iter):
            new_rank = {nid: 0.0 for nid in node_ids}

            for src in node_ids:
                deg = len(outbound[src])
                if deg > 0 and rank[src] > 0:
                    share = rank[src] / deg
                    for tgt in outbound[src]:
                        new_rank[tgt] += share

            # Dangling nodes: redistribute to seeds
            dangling_sum = sum(
                rank[nid] for nid in node_ids if not outbound[nid]
            )
            if dangling_sum > 0:
                for nid in seed_set:
                    new_rank[nid] += dangling_sum / len(seed_set)

            # Apply gate + teleport
            for nid in node_ids:
                new_rank[nid] = (
                    (1 - damping) * teleport.get(nid, 0.0)
                    + damping * gates[nid] * new_rank[nid]
                )

            # Normalise to prevent drift from gating
            total = sum(new_rank.values())
            if total > 0:
                new_rank = {nid: v / total for nid, v in new_rank.items()}

            diff = sum(abs(new_rank[nid] - rank[nid]) for nid in node_ids)
            rank = new_rank
            if diff < tol:
                break

        return rank

    def hybrid_retrieve(
        self,
        query: str,
        *,
        limit: int = 10,
        damping: float = 0.85,
        k: int = 60,
    ) -> list[dict]:
        """Hybrid retrieval combining keyword + PPR + tag search via RRF.

        Uses Reciprocal Rank Fusion (RRF) to merge three retrieval signals:

        1. **Keyword** (``recall``) — BM25-style keyword matching on labels
        2. **Topology** (``ppr_retrieve``) — graph walk from keyword seeds
        3. **Tag** (``search_by_tag``) — exact tag match

        RRF score for each node::

            rrf = Σ_i  1 / (k + rank_i)

        where *k* is the RRF constant (default 60, standard value from
        the original paper).  This gives higher-ranked items more weight
        without depending on raw score scales.

        Args:
            query:   Search query string.
            limit:   Max results to return.
            damping: PPR damping factor.
            k:       RRF constant (larger = smoother fusion).

        Returns:
            List of ``{node_id, rrf_score, sources}`` sorted by RRF score.
        """
        rrf_scores: dict[str, float] = defaultdict(float)
        sources_map: dict[str, set[str]] = defaultdict(set)

        # Signal 1: Keyword recall
        kw_results = self.recall(query, limit=max(limit, 20))
        for rank, node in enumerate(kw_results, 1):
            rrf_scores[node.id] += 1.0 / (k + rank)
            sources_map[node.id].add("keyword")

        # Signal 2: PPR topology retrieval
        try:
            ppr_results = self.ppr_retrieve(query, limit=max(limit, 20), damping=damping)
            for rank, item in enumerate(ppr_results, 1):
                nid = item["node_id"]
                rrf_scores[nid] += 1.0 / (k + rank)
                sources_map[nid].add("topology")
        except Exception:
            pass  # PPR needs edges; skip if graph is sparse

        # Signal 3: Tag search
        try:
            tag_results = self.search_by_tag(query)
            for rank, node in enumerate(tag_results, 1):
                rrf_scores[node.id] += 1.0 / (k + rank)
                sources_map[node.id].add("tag")
        except Exception:
            pass

        # Sort by RRF score
        ranked = sorted(rrf_scores.items(), key=lambda x: x[1], reverse=True)
        result = []
        for nid, score in ranked[:limit]:
            result.append({
                "node_id": nid,
                "rrf_score": round(score, 6),
                "sources": sorted(sources_map[nid]),
                "node": self.get_node(nid),
            })
        return result

    # ------------------------------------------------------------------
    # Post-retrieval re-ranking via graph centrality
    # ------------------------------------------------------------------

    def graph_rerank(
        self,
        results: list,
        *,
        alpha: float = 0.5,
        centrality: str = "degree",
    ) -> list[dict]:
        """Re-rank retrieval results using graph centrality scores.

        Blends the original retrieval score with a graph-centrality
        score to boost nodes that are structurally important::

            combined = α · centrality_norm + (1−α) · retrieval_norm

        This is the standard final step in GraphRAG / HippoRAG2
        pipelines: after candidate retrieval (keyword, PPR, hybrid),
        re-rank by graph topology to surface structurally central
        nodes that might be under-ranked by text-only signals.

        Args:
            results:     Retrieval results — either ``Node`` objects
                         (from :meth:`recall`) or dicts with
                         ``node_id`` / ``rrf_score`` (from
                         :meth:`hybrid_retrieve`).
            alpha:       Blend factor [0, 1].
                         ``0`` = pure retrieval, ``1`` = pure centrality.
            centrality:  Centrality measure to use —
                         ``"degree"``, ``"eigenvector"``, ``"pagerank"``,
                         ``"betweenness"``, ``"closeness"``, or
                         ``"current_flow_betweenness"``.

        Returns:
            List of dicts sorted by ``combined_score`` descending::

                [{node_id, combined_score, retrieval_score,
                  centrality_score, node}]
        """
        if not results:
            return []

        # --- Extract node IDs and retrieval scores -----------------
        node_ids: list[str] = []
        retrieval_scores: dict[str, float] = {}

        for item in results:
            if isinstance(item, dict):
                # From hybrid_retrieve / ppr_retrieve
                nid = item.get("node_id", "")
                score = item.get("rrf_score", item.get("ppr_score", 0.0))
            elif hasattr(item, "id"):
                # Node object from recall()
                nid = item.id
                score = getattr(item, "weight", 1.0)
            else:
                continue
            if nid:
                node_ids.append(nid)
                retrieval_scores[nid] = score

        if not node_ids:
            return []

        # --- Compute centrality scores for candidate nodes ---------
        unique_ids = list(dict.fromkeys(node_ids))

        centrality_scores: dict[str, float] = {}
        method = centrality.lower().strip()

        if method == "eigenvector":
            try:
                ev = self.eigenvector_all(normalized=True)
                for nid in unique_ids:
                    centrality_scores[nid] = ev.get(nid, 0.0)
            except Exception:
                method = "degree"  # fallback

        if method == "pagerank":
            try:
                pr = self.pagerank()
                for nid in unique_ids:
                    centrality_scores[nid] = pr.get(nid, 0.0)
            except Exception:
                method = "degree"

        if method == "betweenness":
            try:
                bc = self.betweenness_all(normalized=True)
                for nid in unique_ids:
                    centrality_scores[nid] = bc.get(nid, 0.0)
            except Exception:
                method = "degree"

        if method == "current_flow_betweenness":
            try:
                cfb = self.current_flow_betweenness(normalized=True)
                for nid in unique_ids:
                    centrality_scores[nid] = cfb.get(nid, 0.0)
            except Exception:
                method = "degree"

        if method == "closeness":
            try:
                cc = self.closeness_all(normalized=True)
                for nid in unique_ids:
                    centrality_scores[nid] = cc.get(nid, 0.0)
            except Exception:
                method = "degree"

        if method not in ("eigenvector", "pagerank", "betweenness",
                           "closeness", "current_flow_betweenness"):
            # Degree centrality (default / fallback)
            for nid in unique_ids:
                centrality_scores[nid] = self.degree_centrality(nid)

        # --- Normalise scores to [0, 1] -----------------------------
        def _normalise(scores: dict[str, float]) -> dict[str, float]:
            if not scores:
                return {}
            vals = list(scores.values())
            lo, hi = min(vals), max(vals)
            rng = hi - lo
            if rng < 1e-12:
                return {k: 1.0 for k in scores}  # all same → uniform
            return {k: (v - lo) / rng for k, v in scores.items()}

        ret_norm = _normalise(retrieval_scores)
        cen_norm = _normalise(centrality_scores)

        # --- Blend and sort -----------------------------------------
        combined: list[dict] = []
        for nid in unique_ids:
            r_score = ret_norm.get(nid, 0.0)
            c_score = cen_norm.get(nid, 0.0)
            blended = alpha * c_score + (1.0 - alpha) * r_score
            combined.append({
                "node_id": nid,
                "combined_score": round(blended, 6),
                "retrieval_score": round(r_score, 6),
                "centrality_score": round(c_score, 6),
                "node": self.get_node(nid),
            })

        combined.sort(key=lambda x: x["combined_score"], reverse=True)
        return combined


    # ------------------------------------------------------------------
    # Unified retrieval pipeline orchestrator
    # ------------------------------------------------------------------

    def retrieve(
        self,
        query: str,
        *,
        limit: int = 10,
        stages: list[str] | None = None,
        rerank: bool = True,
        rerank_centrality: str = "degree",
        rerank_alpha: float = 0.5,
        damping: float = 0.85,
        rrf_k: int = 60,
        explain: bool = False,
    ) -> list[dict] | dict:
        """End-to-end retrieval pipeline — one call, four stages.

        Chains the full GraphRAG retrieval pipeline automatically:

        1. **Keyword** — ``recall()`` BM25-style label matching
        2. **Topology** — ``ppr_retrieve()`` Personalized PageRank walk
        3. **Hybrid** — ``hybrid_retrieve()`` RRF fusion of all signals
        4. **Re-rank** — ``graph_rerank()`` centrality boosting

        This is the convenience entry point for production use —
        callers don't need to know the internal stage order.

        Args:
            query:              Search query string.
            limit:              Max results in final output.
            stages:             Custom stage subset, e.g.
                                ``["keyword", "rerank"]``.
                                Default: all four stages.
            rerank:             If ``False``, skip the re-rank stage
                                even if included in *stages*.
            rerank_centrality:  Centrality measure for re-rank.
            rerank_alpha:       Blend factor (0=pure retrieval,
                                1=pure centrality).
            damping:            PPR damping factor.
            rrf_k:              RRF fusion constant.
            explain:            If ``True``, return ``{results, explain}``
                                with per-stage counts and timing.

        Returns:
            List of result dicts sorted by final score.
            Each dict has at minimum ``node_id``, ``score``, ``node``.
            If *explain* is ``True``, returns a dict with
            ``results`` and ``explain`` (stage metadata).
        """
        import time

        all_stages = ["keyword", "topology", "hybrid", "rerank"]
        active = stages if stages is not None else list(all_stages)
        if not rerank and "rerank" in active:
            active = [s for s in active if s != "rerank"]

        trace: dict = {"query": query, "stages": [], "limits": {"limit": limit}}
        t0 = time.perf_counter()

        # ---- Stage 1: Keyword -----------------------------------------
        kw_nodes = []
        if "keyword" in active:
            t1 = time.perf_counter()
            kw_nodes = self.recall(query, limit=max(limit, 20))
            trace["stages"].append({
                "name": "keyword",
                "candidates": len(kw_nodes),
                "elapsed_ms": round((time.perf_counter() - t1) * 1000, 2),
            })

        # Early exit if no keyword hits and no further enrichment
        if not kw_nodes and active == ["keyword"]:
            trace["total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
            return {"results": [], "explain": trace} if explain else []

        # ---- Stage 2: Topology (PPR) ----------------------------------
        if "topology" in active and kw_nodes:
            t2 = time.perf_counter()
            try:
                seed_ids = [n.id for n in kw_nodes]
                ppr = self.personalized_pagerank(seed_ids, damping=damping)
                seed_set = set(seed_ids)
                ppr_results = [
                    {"node_id": nid, "ppr_score": score}
                    for nid, score in ppr.items()
                    if nid not in seed_set and score > 0
                ]
                ppr_results.sort(key=lambda x: x["ppr_score"], reverse=True)
                ppr_results = ppr_results[:max(limit, 20)]
                for item in ppr_results:
                    item["node"] = self.get_node(item["node_id"])
            except Exception:
                ppr_results = []
            trace["stages"].append({
                "name": "topology",
                "candidates": len(ppr_results),
                "elapsed_ms": round((time.perf_counter() - t2) * 1000, 2),
            })
        else:
            ppr_results = []

        # ---- Stage 3: Hybrid (RRF) ------------------------------------
        if "hybrid" in active:
            t3 = time.perf_counter()
            hybrid = self.hybrid_retrieve(
                query, limit=max(limit, 20), damping=damping, k=rrf_k
            )
            trace["stages"].append({
                "name": "hybrid",
                "candidates": len(hybrid),
                "elapsed_ms": round((time.perf_counter() - t3) * 1000, 2),
            })
            candidates = hybrid
        elif kw_nodes:
            # Use keyword results if hybrid skipped
            candidates = [
                {"node_id": n.id, "rrf_score": n.weight, "node": n}
                for n in kw_nodes
            ]
        elif ppr_results:
            candidates = ppr_results
        else:
            candidates = []

        # ---- Stage 4: Re-rank (centrality) ----------------------------
        if "rerank" in active and candidates:
            t4 = time.perf_counter()
            reranked = self.graph_rerank(
                candidates, alpha=rerank_alpha, centrality=rerank_centrality
            )
            trace["stages"].append({
                "name": "rerank",
                "candidates": len(reranked),
                "elapsed_ms": round((time.perf_counter() - t4) * 1000, 2),
            })
            final = [
                {
                    "node_id": r["node_id"],
                    "score": r["combined_score"],
                    "retrieval_score": r["retrieval_score"],
                    "centrality_score": r["centrality_score"],
                    "node": r["node"],
                }
                for r in reranked
            ]
        else:
            final = [
                {
                    "node_id": c.get("node_id", ""),
                    "score": c.get("rrf_score", c.get("ppr_score", 0.0)),
                    "node": c.get("node"),
                }
                for c in candidates
            ]

        # Trim to limit
        final = final[:limit]
        trace["total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        trace["final_count"] = len(final)

        if explain:
            return {"results": final, "explain": trace}
        return final

    def retrieve_token_budgeted(
        self,
        query: str,
        *,
        token_budget: int = 2048,
        chars_per_token: float = 4.0,
        damping: float = 0.85,
        rerank: bool = True,
        rerank_centrality: str = "degree",
    ) -> dict:
        """Token-budgeted context generation — quantitative retrieval.

        Mandol-inspired: produce a context window that fits within a
        specified token budget, **without any LLM calls**. Nodes are
        ranked by retrieval score, then greedily packed until the
        budget is exhausted.

        This is the production retrieval path for agent memory:
        deterministic, fast, and cost-free.

        Args:
            query:            Search query.
            token_budget:     Maximum tokens (approx).
            chars_per_token:  Conversion ratio (default 4.0 chars/token).
            damping:          PPR damping factor.
            rerank:           Apply centrality re-ranking before packing.
            rerank_centrality: Centrality metric for re-rank.

        Returns:
            Dict with::

                context:     Formatted string ready for LLM prompt.
                nodes:       List of included node dicts.
                token_count: Estimated tokens used.
                char_count:  Total characters.
                truncated:   True if budget was exhausted.
                budget:      The token budget.
        """
        char_budget = int(token_budget * chars_per_token)

        # Retrieve candidates (unlimited to maximise pool)
        candidates = self.retrieve(
            query,
            limit=100,
            rerank=rerank,
            rerank_centrality=rerank_centrality,
            damping=damping,
        )

        if not candidates:
            return {
                "context": "",
                "nodes": [],
                "token_count": 0,
                "char_count": 0,
                "truncated": False,
                "budget": token_budget,
            }

        # Greedy pack by score order
        packed = []
        total_chars = 0
        truncated = False

        for item in candidates:
            node = item.get("node")
            if node is None:
                continue
            # Format node as context line
            label = getattr(node, "label", "")
            kind = getattr(node, "kind", "")
            data = getattr(node, "data", {})
            score = item.get("score", item.get("rrf_score", 0.0))

            line = f"[{kind}] {label}"
            if data:
                # Compact data rendering
                data_str = ", ".join(f"{k}={v}" for k, v in data.items() if v)
                if data_str:
                    line += f" ({data_str})"
            line += f" score={score:.3f}"
            line += "\n"

            if total_chars + len(line) > char_budget:
                truncated = True
                break

            total_chars += len(line)
            packed.append({
                "node_id": item.get("node_id", ""),
                "label": label,
                "kind": kind,
                "score": score,
                "line": line.rstrip(),
            })

        context = "".join(p["line"] + "\n" for p in packed)
        token_count = int(total_chars / chars_per_token)

        return {
            "context": context,
            "nodes": packed,
            "token_count": token_count,
            "char_count": total_chars,
            "truncated": truncated,
            "budget": token_budget,
        }

    def centrality_optimized(self, normalized: bool = True, 
                            include_quarantined: bool = False) -> tuple[dict[str, float], dict[str, float]]:
        """Optimized joint computation of betweenness and closeness centrality.
        
        Avoids redundant adjacency list construction and BFS traversals.
        Returns (betweenness_dict, closeness_dict).
        """
        if include_quarantined:
            node_ids = [r["id"] for r in self.conn.execute("SELECT id FROM nodes").fetchall()]
        else:
            node_ids = [r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()]
        n = len(node_ids)
        if n < 2:
            return (
                {nid: 0.0 for nid in node_ids},
                {nid: 1.0 if n == 1 else 0.0 for nid in node_ids}
            )
        
        node_set = set(node_ids)
        adj: dict[str, list[str]] = {nid: [] for nid in node_ids}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = r["source"], r["target"]
            if s in node_set and t in node_set:
                adj[s].append(t)
                adj[t].append(s)
        
        betweenness = {nid: 0.0 for nid in node_ids}
        closeness = {nid: 0.0 for nid in node_ids}
        
        for s in node_ids:
            pred: dict[str, list[str]] = {nid: [] for nid in node_ids}
            dist: dict[str, int] = {s: 0}
            queue: list[str] = [s]
            sigma: dict[str, float] = {nid: 0.0 for nid in node_ids}
            sigma[s] = 1.0
            
            while queue:
                v = queue.pop(0)
                for w in adj[v]:
                    if w not in dist:
                        dist[w] = dist[v] + 1
                        queue.append(w)
                    if dist.get(w, float('inf')) == dist[v] + 1:
                        sigma[w] += sigma[v]
                        pred[w].append(v)
            
            delta: dict[str, float] = {nid: 0.0 for nid in node_ids}
            total_dist = 0
            reachable = 0
            sorted_nodes = sorted(node_ids, key=lambda x: dist.get(x, float('inf')), reverse=True)
            
            for w in sorted_nodes:
                if w == s:
                    continue
                for v in pred.get(w, []):
                    delta[v] += (sigma[v] / sigma[w]) * (1 + delta[w])
                if w in dist and dist[w] < float('inf'):
                    total_dist += dist[w]
                    reachable += 1
            
            betweenness[s] = delta[s]
            if total_dist > 0:
                cc = reachable / total_dist
                if normalized:
                    cc *= reachable / (n - 1)
                closeness[s] = cc
            else:
                closeness[s] = 0.0
        
        if normalized and n > 2:
            factor = 2.0 / ((n - 1) * (n - 2))
            betweenness = {nid: score * factor for nid, score in betweenness.items()}
        
        return betweenness, closeness

    # ── Governed Selection Pipeline (MRMS-inspired) ─────────────

    def select_governed(
        self,
        query: str,
        *,
        limit: int = 10,
        min_confidence: float = 0.0,
        kinds: list[str] | None = None,
        require_tags: list[str] | None = None,
        rerank: bool = True,
        rerank_centrality: str = "degree",
        explain: bool = False,
    ) -> list[dict] | dict:
        """MRMS-style three-stage governed selection pipeline.

        Pre-generation governance layer over the existing retrieve()
        pipeline. Implements the synchronized structured-vector-graph
        selection pattern from MRMS (arXiv:2607.04617):

        **Stage 1 — Structured gates:** Filter out quarantined,
        superseded, or low-confidence nodes before retrieval.

        **Stage 2 — Vector recall:** Delegate to existing ``retrieve()``
        for hybrid keyword + PPR + RRF + centrality rerank.

        **Stage 3 — Graph expansion:** Annotate each result with
        evidence (supports edges), conflicts (contradicts edges),
        and superseded_by metadata. Tag each packet as safe/unsafe.

        Args:
            query:              Search query.
            limit:              Max results.
            min_confidence:     Minimum confidence score (0–1).
            kinds:              Node kind whitelist.
            require_tags:       Tags that must be present.
            rerank:             Apply centrality rerank in recall.
            rerank_centrality:  Centrality metric for rerank.
            explain:            Return governance metadata.

        Returns:
            List of governed result packets, each containing::

                node_id, claim, kind, score, confidence,
                is_safe, evidence, conflicts, superseded_by

            If *explain* is ``True``, returns::

                {"results": [...], "governance": {...}}
        """
        import time

        t0 = time.perf_counter()
        trace = {
            "query": query,
            "stages": [],
            "filters": {
                "min_confidence": min_confidence,
                "kinds": kinds,
                "require_tags": require_tags,
            },
        }

        # ── Stage 1: Structured gates ────────────────────────────
        t1 = time.perf_counter()

        # Build exclusion set from structured filters
        excluded: set[str] = set()

        # Quarantine gate
        quarantined = {
            row["id"] for row in self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined = 1"
            ).fetchall()
        }
        excluded |= quarantined

        # Superseded gate (valid_to is set and in the past)
        now = time.time()
        superseded_ids = {
            row["id"] for row in self.conn.execute(
                "SELECT id FROM nodes WHERE valid_to IS NOT NULL AND valid_to < ?",
                (now,)
            ).fetchall()
        }
        excluded |= superseded_ids

        # Kind filter
        if kinds:
            kind_set = set(kinds)
            kind_excluded = {
                row["id"] for row in self.conn.execute(
                    "SELECT id FROM nodes WHERE kind NOT IN (%s)"
                    % ",".join("?" * len(kind_set)),
                    tuple(kind_set),
                ).fetchall()
            }
            excluded |= kind_excluded

        # Tag filter
        if require_tags:
            import json as _json
            required = set(require_tags)
            all_nodes = self.conn.execute(
                "SELECT id, tags FROM nodes"
            ).fetchall()
            for row in all_nodes:
                node_tags = set(_json.loads(row["tags"]) if row["tags"] else [])
                if not required.issubset(node_tags):
                    excluded.add(row["id"])

        gate_passed = set()
        for row in self.conn.execute("SELECT id FROM nodes").fetchall():
            if row["id"] not in excluded:
                gate_passed.add(row["id"])

        trace["stages"].append({
            "name": "structured_gate",
            "total_nodes": self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0],
            "passed": len(gate_passed),
            "excluded": len(excluded),
            "quarantined": len(quarantined),
            "superseded": len(superseded_ids),
            "elapsed_ms": round((time.perf_counter() - t1) * 1000, 2),
        })

        # Early exit if nothing passes the gate
        if not gate_passed:
            trace["total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
            if explain:
                return {"results": [], "governance": trace}
            return []

        # ── Stage 2: Vector recall (delegate to retrieve) ─────────
        t2 = time.perf_counter()
        candidates = self.retrieve(
            query,
            limit=max(limit * 3, 30),  # over-fetch for post-filtering
            rerank=rerank,
            rerank_centrality=rerank_centrality,
        )

        # Apply gate filter to retrieve results
        gated_candidates = [
            c for c in candidates if c.get("node_id") in gate_passed
        ]

        # Apply confidence filter
        if min_confidence > 0:
            gated_candidates = [
                c for c in gated_candidates
                if self.get_confidence(c.get("node_id", "")) >= min_confidence
            ]

        trace["stages"].append({
            "name": "recall",
            "candidates": len(gated_candidates),
            "pre_gate": len(candidates),
            "filtered_by_gate": len(candidates) - len(gated_candidates),
            "elapsed_ms": round((time.perf_counter() - t2) * 1000, 2),
        })

        if not gated_candidates:
            trace["total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
            if explain:
                return {"results": [], "governance": trace}
            return []

        # ── Stage 3: Graph expansion + annotation ─────────────────
        t3 = time.perf_counter()
        packets: list[dict] = []

        for cand in gated_candidates[:limit]:
            nid = cand.get("node_id", "")
            node = cand.get("node") or self.get_node(nid)
            if not node:
                continue

            # Gather edges for annotation
            evidence: list[dict] = []
            conflicts: list[dict] = []
            superseded_by: list[dict] = []

            edge_rows = self.conn.execute(
                "SELECT target, relation FROM edges WHERE source=? UNION "
                "SELECT source AS target, relation FROM edges WHERE target=?",
                (nid, nid),
            ).fetchall()

            for erow in edge_rows:
                other_id = erow["target"]
                rel = erow["relation"]
                if other_id == nid:
                    continue  # skip self-references
                other = self.get_node(other_id)
                if not other:
                    continue
                if other_id in excluded:
                    continue

                entry = {"id": other_id, "claim": other.label, "relation": rel}
                if rel in ("supports", "supported_by", "corroborates"):
                    evidence.append(entry)
                elif rel in ("contradicts", "contradicted_by", "conflicts_with"):
                    conflicts.append(entry)
                elif rel in ("superseded_by", "replaces"):
                    superseded_by.append(entry)

            confidence = self.get_confidence(nid)
            is_safe = len(conflicts) == 0 and len(superseded_by) == 0

            packets.append({
                "node_id": nid,
                "claim": node.label,
                "kind": node.kind,
                "score": cand.get("score", cand.get("rrf_score", 0.0)),
                "confidence": round(confidence, 4),
                "is_safe": is_safe,
                "evidence": evidence,
                "conflicts": conflicts,
                "superseded_by": superseded_by,
            })

        trace["stages"].append({
            "name": "graph_expansion",
            "annotated": len(packets),
            "safe": sum(1 for p in packets if p["is_safe"]),
            "conflicted": sum(1 for p in packets if not p["is_safe"]),
            "elapsed_ms": round((time.perf_counter() - t3) * 1000, 2),
        })

        trace["total_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        trace["final_count"] = len(packets)

        if explain:
            return {"results": packets, "governance": trace}
        return packets

    # ─────────────────────────────────────────────
    # Cycle 224: Retrieval Quality Evaluation
    # Building block for LoCoMo benchmark adapter.
    # Computes precision@k, recall@k, F1, NDCG, MRR.
    # ─────────────────────────────────────────────

    def retrieval_quality_eval(
        self,
        eval_cases: list[dict],
        *,
        k: int = 10,
        limit: int | None = None,
        rerank: bool = True,
        rerank_centrality: str = "degree",
        rerank_alpha: float = 0.5,
    ) -> dict:
        """Evaluate retrieval quality against ground-truth relevant sets.

        Each eval case is::

            {"query": str, "relevant_ids": set[str] | list[str]}

        Runs :meth:`retrieve` for each query and compares the top-*k*
        results against ``relevant_ids``.

        Metrics computed per-query and aggregated (macro-average):

        - **precision@k** — fraction of retrieved items that are relevant
        - **recall@k** — fraction of relevant items that are retrieved
        - **f1@k** — harmonic mean of precision and recall
        - **ndcg@k** — normalised discounted cumulative gain
        - **mrr** — mean reciprocal rank of first relevant hit
        - **hit@k** — 1 if at least one relevant item in top-*k*
        - **utilization_rate** — fraction of retrieved items actually cited
          by the downstream model (ACL 2026 GEM).  Only computed when
          eval cases include ``cited_ids``.

        Args:
            eval_cases:         List of ``{query, relevant_ids}`` dicts.
                                Optionally include ``cited_ids`` for
                                utilization_rate computation.
            k:                  Cutoff for top-k metrics.
            limit:              Override retrieval limit (default = *k*).
            rerank:             Pass through to :meth:`retrieve`.
            rerank_centrality:  Pass through to :meth:`retrieve`.
            rerank_alpha:       Pass through to :meth:`retrieve`.

        Returns:
            ``{overall: {precision, recall, f1, ndcg, mrr, hit_rate,
              utilization_rate},
             per_query: [...], k, n_cases}``
        """
        import math as _math

        eff_limit = limit if limit is not None else k
        per_query: list[dict] = []

        # Aggregators
        sum_p = sum_r = sum_f1 = sum_ndcg = sum_mrr = 0.0
        sum_util = 0.0
        util_count = 0
        hits = 0

        for case in eval_cases:
            query = case["query"]
            relevant = set(case.get("relevant_ids", []))
            if not relevant:
                # No ground truth — skip but record
                per_query.append({
                    "query": query,
                    "precision": 0.0, "recall": 0.0,
                    "f1": 0.0, "ndcg": 0.0, "mrr": 0.0,
                    "hit": False, "utilization_rate": None,
                    "skipped": True,
                })
                continue

            results = self.retrieve(
                query,
                limit=eff_limit,
                rerank=rerank,
                rerank_centrality=rerank_centrality,
                rerank_alpha=rerank_alpha,
            )

            retrieved_ids = [r["node_id"] for r in results[:k]]
            retrieved_set = set(retrieved_ids)

            # Precision@k
            tp = len(retrieved_set & relevant)
            precision = tp / len(retrieved_ids) if retrieved_ids else 0.0

            # Recall@k
            recall = tp / len(relevant) if relevant else 0.0

            # F1@k
            f1 = (2 * precision * recall / (precision + recall)
                  if (precision + recall) > 0 else 0.0)

            # NDCG@k — binary relevance
            dcg = 0.0
            for i, rid in enumerate(retrieved_ids):
                if rid in relevant:
                    dcg += 1.0 / _math.log2(i + 2)  # rank starts at 1
            # Ideal DCG
            ideal_n = min(len(relevant), k)
            idcg = sum(1.0 / _math.log2(i + 2) for i in range(ideal_n))
            ndcg = dcg / idcg if idcg > 0 else 0.0

            # MRR — reciprocal rank of first relevant hit
            mrr = 0.0
            for i, rid in enumerate(retrieved_ids):
                if rid in relevant:
                    mrr = 1.0 / (i + 1)
                    break

            hit = mrr > 0.0

            # Utilization rate — ACL 2026 GEM insight
            cited = set(case.get("cited_ids", []))
            if cited:
                utilized = len(retrieved_set & cited)
                utilization = utilized / len(retrieved_ids) if retrieved_ids else 0.0
                sum_util += utilization
                util_count += 1
            else:
                utilization = None

            per_query.append({
                "query": query,
                "precision": round(precision, 4),
                "recall": round(recall, 4),
                "f1": round(f1, 4),
                "ndcg": round(ndcg, 4),
                "mrr": round(mrr, 4),
                "hit": hit,
                "utilization_rate": round(utilization, 4) if utilization is not None else None,
                "retrieved_count": len(retrieved_ids),
                "relevant_count": len(relevant),
                "tp": tp,
            })

            sum_p += precision
            sum_r += recall
            sum_f1 += f1
            sum_ndcg += ndcg
            sum_mrr += mrr
            if hit:
                hits += 1

        evaluated_cases = [q for q in per_query if not q.get("skipped")]
        n_evaluated = len(evaluated_cases)
        divisor = n_evaluated if n_evaluated > 0 else 1

        overall = {
            "precision": round(sum_p / divisor, 4),
            "recall": round(sum_r / divisor, 4),
            "f1": round(sum_f1 / divisor, 4),
            "ndcg": round(sum_ndcg / divisor, 4),
            "mrr": round(sum_mrr / divisor, 4),
            "hit_rate": round(hits / divisor, 4),
            "utilization_rate": round(sum_util / util_count, 4) if util_count > 0 else None,
        }

        return {
            "overall": overall,
            "per_query": per_query,
            "k": k,
            "n_cases": len(eval_cases),
            "n_evaluated": n_evaluated,
        }

    # ────────────────────────────────────────────────────────────
    # Causal edges — ActMem-inspired (arXiv:2603.00026)
    # ────────────────────────────────────────────────────────────
    _CAUSAL_RELATIONS = frozenset({
        "causes", "prevents", "conflicts_with", "enables", "depends_on",
        "derived_from", "computed_from",
    })

    def add_causal_edge(self, source_id: str, target_id: str,
                        relation: str, confidence: float = 1.0,
                        evidence: list[str] | None = None,
                        note: str | None = None) -> dict:
        """Add a typed causal edge between two nodes.

        Inspired by ActMem (arXiv:2603.00026): causal edges let a memory
        graph answer "what are the consequences of X?" rather than only
        "what is related to X?".

        Seven relation types are supported:
        - ``causes``: source directly causes the target event/state.
        - ``prevents``: source stops or inhibits the target.
        - ``conflicts_with``: source and target cannot both hold.
        - ``enables``: source is a prerequisite for target.
        - ``depends_on``: source requires target to be true.
        - ``derived_from``: source is derived (extracted, summarised,
          inferred) from target — provenance / lineage tracking.
        - ``computed_from``: source is computed (aggregated, transformed,
          calculated) from target — deterministic lineage.

        The edge is stored via the regular ``link()`` mechanism with
        the relation as the edge type, and rich metadata (confidence,
        evidence list, note, timestamp) is saved into ``edge_props``.

        Args:
            source_id: ID of the cause / enabler / depender node.
            target_id: ID of the effect / prevented / dependent node.
            relation: One of the five causal relation types.
            confidence: Float in ``[0, 1]`` — how certain is this
                causal link? Defaults to ``1.0`` (certain).
            evidence: Optional list of node IDs that serve as
                supporting evidence for this causal claim.
            note: Optional human-readable explanation.

        Returns:
            Dict summarising the created edge:
            ``{source, target, relation, confidence, evidence, note, created_at}``.

        Raises:
            ValueError: If *relation* is not one of the five causal
                types, or if *confidence* is outside ``[0, 1]``, or
                if either node does not exist.
        """
        if relation not in self._CAUSAL_RELATIONS:
            raise ValueError(
                f"Unknown causal relation {relation!r}. "
                f"Must be one of {sorted(self._CAUSAL_RELATIONS)}."
            )
        if not 0 <= confidence <= 1:
            raise ValueError(
                f"confidence must be in [0, 1], got {confidence}."
            )
        for nid, label in ((source_id, "source"), (target_id, "target")):
            if not self.conn.execute(
                "SELECT 1 FROM nodes WHERE id=?", (nid,)
            ).fetchone():
                raise ValueError(f"{label} node {nid!r} not found")

        # Create the edge with confidence as weight
        self.link(source_id, target_id, relation, weight=confidence)

        # Store rich metadata in edge_props
        import time as _t
        created_at = _t.time()
        props = {
            "confidence": confidence,
            "evidence": evidence or [],
            "note": note or "",
            "created_at": created_at,
            "causal": True,
        }
        self.conn.execute(
            "INSERT OR REPLACE INTO edge_props "
            "(source, target, relation, properties) VALUES (?, ?, ?, ?)",
            (source_id, target_id, relation, json.dumps(props)),
        )
        self.conn.commit()

        return {
            "source": source_id,
            "target": target_id,
            "relation": relation,
            "confidence": confidence,
            "evidence": evidence or [],
            "note": note or "",
            "created_at": created_at,
        }

    def get_causal_edges(self, node_id: str,
                         direction: str = "both",
                         relation: str | None = None) -> list[dict]:
        """Retrieve causal edges connected to a node.

        Args:
            node_id: The node to query.
            direction: ``'outgoing'`` (edges from *node_id*),
                      ``'incoming'`` (edges to *node_id*), or
                      ``'both'`` (default).
            relation: Optional filter to a specific causal relation.

        Returns:
            List of edge dicts with keys: ``source``, ``target``,
            ``relation``, ``weight``, ``confidence``, ``evidence``,
            ``note``, ``created_at``.
        """
        if direction not in ("outgoing", "incoming", "both"):
            raise ValueError(
                f"direction must be outgoing/incoming/both, got {direction!r}"
            )

        relations = (
            {relation} if relation else set(self._CAUSAL_RELATIONS)
        )
        placeholders = ",".join("?" for _ in relations)
        params: list = list(relations)

        clauses = []
        if direction in ("outgoing", "both"):
            clauses.append(f"source=? AND relation IN ({placeholders})")
        if direction in ("incoming", "both"):
            clauses.append(f"target=? AND relation IN ({placeholders})")

        if direction == "both":
            where = f"({clauses[0]} OR {clauses[1]})"
            sql_params = [node_id] + params + [node_id] + params
        elif direction == "outgoing":
            where = clauses[0]
            sql_params = [node_id] + params
        else:
            where = clauses[0]
            sql_params = [node_id] + params

        rows = self.conn.execute(
            f"SELECT source, target, relation, weight "
            f"FROM edges WHERE {where}",
            sql_params,
        ).fetchall()

        results: list[dict] = []
        for r in rows:
            entry = {
                "source": r["source"],
                "target": r["target"],
                "relation": r["relation"],
                "weight": r["weight"],
                "confidence": r["weight"],
                "evidence": [],
                "note": "",
                "created_at": None,
            }
            # Enrich from edge_props if available
            prop_row = self.conn.execute(
                "SELECT properties FROM edge_props "
                "WHERE source=? AND target=? AND relation=?",
                (r["source"], r["target"], r["relation"]),
            ).fetchone()
            if prop_row:
                p = json.loads(prop_row["properties"])
                entry["confidence"] = p.get("confidence", r["weight"])
                entry["evidence"] = p.get("evidence", [])
                entry["note"] = p.get("note", "")
                entry["created_at"] = p.get("created_at")
            results.append(entry)
        return results

    def trace_causal_chain(self, node_id: str,
                           max_depth: int = 10,
                           direction: str = "forward") -> list[list[dict]]:
        """Trace causal chains emanating from or converging on a node.

        Performs BFS traversal following only causal edges, building
        complete cause→effect (or effect→cause) paths.

        Args:
            node_id: Starting node.
            max_depth: Maximum chain length (default 10 hops).
            direction: ``'forward'`` — follow causes to their effects
                      (outgoing edges); ``'backward'`` — trace effects
                      back to their root causes (incoming edges).

        Returns:
            List of chains, where each chain is a list of edge dicts
            (``source``, ``target``, ``relation``, ``confidence``).
            Chains are sorted longest-first.
        """
        if direction not in ("forward", "backward"):
            raise ValueError(
                f"direction must be forward/backward, got {direction!r}"
            )

        visit_field = "target" if direction == "forward" else "source"
        next_field = "source" if direction == "forward" else "target"

        results: list[list[dict]] = []
        queue: list[tuple[str, list[dict], set]] = [
            (node_id, [], {node_id})
        ]

        while queue:
            current, path, visited = queue.pop(0)
            if len(path) >= max_depth:
                results.append(path)
                continue

            edges = self.get_causal_edges(
                current,
                direction="outgoing" if direction == "forward" else "incoming",
            )

            had_next = False
            for e in edges:
                nxt = e[visit_field] if e["source"] == current else e[next_field]
                # For forward: next is target; for backward: next is source
                nxt = e["target"] if direction == "forward" else e["source"]
                if nxt in visited:
                    continue
                had_next = True
                new_path = path + [{
                    "source": e["source"],
                    "target": e["target"],
                    "relation": e["relation"],
                    "confidence": e["confidence"],
                }]
                new_visited = visited | {nxt}
                queue.append((nxt, new_path, new_visited))

            if not had_next and path:
                results.append(path)

        # Sort: longest chains first, then by total confidence
        results.sort(key=lambda c: (-len(c), -sum(e["confidence"] for e in c)))
        return results

    # ── Derivation Provenance ───────────────────────────────────
    def trace_derivation(self, node_id: str,
                         max_depth: int = 10) -> dict:
        """Trace the full provenance / derivation tree of a node.

        Follows ``derived_from`` and ``computed_from`` edges backward
        (from target to source) to reconstruct how a node came to be.

        Unlike :meth:`trace_causal_chain` (which follows all causal
        edges), this method focuses specifically on data-lineage:
        *where did this knowledge come from?*

        Each path in the result is a chain of ``source → target``
        derivation edges, from the query node back to its roots.
        Nodes with no incoming derivation edges are "roots" (original
        observations, not derived from anything).

        Args:
            node_id: The node whose provenance to trace.
            max_depth: Maximum derivation chain length (default 10).

        Returns:
            Dict with:
            - ``node``: the starting node ID.
            - ``roots``: list of root source node IDs (origins).
            - ``chains``: list of derivation paths, each a list of
              ``{source, target, relation, confidence}`` dicts.
              Sorted longest-first.
            - ``all_sources``: flat set of all upstream source IDs.
            - ``depth_reached``: maximum chain length found.

        Example::

            >>> mg.add_causal_edge("summary", "raw_data",
            ...                    "derived_from", confidence=0.9)
            >>> mg.add_causal_edge("raw_data", "sensor_1",
            ...                    "computed_from", confidence=1.0)
            >>> mg.trace_derivation("summary")
            {'node': 'summary',
             'roots': ['sensor_1'],
             'chains': [[
                {'source': 'summary', 'target': 'raw_data',
                 'relation': 'derived_from', 'confidence': 0.9},
                {'source': 'raw_data', 'target': 'sensor_1',
                 'relation': 'computed_from', 'confidence': 1.0},
             ]],
             'all_sources': ['raw_data', 'sensor_1'],
             'depth_reached': 2}
        """
        derivation_relations = ("derived_from", "computed_from")

        # Verify node exists
        node = self.get_node(node_id)
        if node is None:
            return {"node": node_id, "roots": [], "chains": [],
                    "all_sources": [], "depth_reached": 0,
                    "error": "node not found"}

        chains: list[list[dict]] = []
        roots: set[str] = set()
        all_sources: set[str] = set()
        queue: list[tuple[str, list[dict], set]] = [
            (node_id, [], {node_id})
        ]

        while queue:
            current, path, visited = queue.pop(0)
            if len(path) >= max_depth:
                roots.add(current)
                if path:
                    chains.append(path)
                continue

            # Find outgoing derivation edges: current → target
            # In add_causal_edge, source derives FROM target:
            #   add_causal_edge(source="summary", target="raw", "derived_from")
            #   means "summary is derived from raw".
            # So to trace provenance, follow outgoing edges
            # (where source = current node).
            placeholders = ','.join('?' * len(derivation_relations))
            rows = self.conn.execute(
                f"SELECT source, target, relation FROM edges "
                f"WHERE source=? AND relation IN ({placeholders})",
                (current, *derivation_relations)
            ).fetchall()

            had_next = False
            for row in rows:
                tgt = row['target']  # upstream source node
                rel = row['relation']
                if tgt in visited:
                    continue
                had_next = True

                # Get confidence from edge_props
                prop_row = self.conn.execute(
                    "SELECT properties FROM edge_props "
                    "WHERE source=? AND target=? AND relation=?",
                    (current, tgt, rel)
                ).fetchone()
                confidence = 1.0
                if prop_row:
                    try:
                        props = json.loads(prop_row['properties'])
                        confidence = props.get("confidence", 1.0)
                    except (json.JSONDecodeError, TypeError):
                        pass

                edge_dict = {
                    "source": current,
                    "target": tgt,
                    "relation": rel,
                    "confidence": confidence,
                }
                new_path = path + [edge_dict]
                new_visited = visited | {tgt}
                all_sources.add(tgt)
                queue.append((tgt, new_path, new_visited))

            if not had_next:
                # No further derivations — this is a root
                roots.add(current)
                if path:
                    chains.append(path)

        # Sort chains: longest first, then by total confidence
        chains.sort(key=lambda c: (-len(c), -sum(e["confidence"] for e in c)))

        return {
            "node": node_id,
            "roots": sorted(roots),
            "chains": chains,
            "all_sources": sorted(all_sources),
            "depth_reached": max((len(c) for c in chains), default=0),
        }

    # ── Spreading Activation (Collins & Loftus 1975) ─────────────
    def spread_activation(
        self,
        seed_ids: list[str],
        *,
        decay_factor: float = 0.5,
        threshold: float = 0.1,
        max_hops: int = 3,
        include_quarantined: bool = False,
        edge_weight_factor: bool = True,
    ) -> dict[str, float]:
        """Collins & Loftus (1975) spreading activation retrieval.

        Starts from *seed_ids* and propagates activation along edges,
        decaying by ``decay_factor`` per hop. Returns a dict mapping
        node_id → activation level (sorted descending by caller).

        Parameters
        ----------
        seed_ids
            Starting node IDs (must exist).
        decay_factor
            Multiplicative decay per hop (0–1).  Lower = more local.
        threshold
            Minimum activation to include in results.
        max_hops
            Maximum propagation distance from any seed.
        include_quarantined
            If False, quarantined nodes are skipped.
        edge_weight_factor
            If True, activation is multiplied by edge weight.

        Returns
        -------
        dict[str, float]
            ``{node_id: activation}`` for all nodes ≥ *threshold*.
            Seed nodes get activation 1.0.

        Raises
        ------
        ValueError
            If *seed_ids* is empty, *decay_factor* not in (0, 1],
            *threshold* < 0, or *max_hops* < 1.
        KeyError
            If any seed node does not exist.
        """
        if not seed_ids:
            raise ValueError("seed_ids must not be empty")
        if not (0 < decay_factor <= 1):
            raise ValueError(f"decay_factor must be in (0, 1], got {decay_factor}")
        if threshold < 0:
            raise ValueError(f"threshold must be ≥ 0, got {threshold}")
        if max_hops < 1:
            raise ValueError(f"max_hops must be ≥ 1, got {max_hops}")

        # Validate seeds exist
        for sid in seed_ids:
            row = self.conn.execute(
                "SELECT id FROM nodes WHERE id=?", (sid,)
            ).fetchone()
            if row is None:
                raise KeyError(f"Seed node not found: {sid}")

        # BFS-based spreading activation
        activation: dict[str, float] = {}
        for sid in seed_ids:
            activation[sid] = max(activation.get(sid, 0.0), 1.0)

        frontier = list(seed_ids)
        visited = set(seed_ids)

        for hop in range(max_hops):
            if not frontier:
                break
            next_frontier: list[str] = []
            for nid in frontier:
                current_act = activation.get(nid, 0.0)
                if current_act < threshold:
                    continue

                # Get all neighbours (both directions)
                rows = self.conn.execute(
                    """
                    SELECT target AS nbr, weight FROM edges WHERE source=?
                    UNION
                    SELECT source AS nbr, weight FROM edges WHERE target=?
                    """,
                    (nid, nid),
                ).fetchall()

                for r in rows:
                    nbr_id = r["nbr"]
                    edge_w = r["weight"] if edge_weight_factor else 1.0

                    # Apply decay + edge weight
                    propagated = current_act * decay_factor * edge_w

                    if propagated < threshold:
                        continue

                    # Skip quarantined
                    if not include_quarantined:
                        nq = self.conn.execute(
                            "SELECT quarantined FROM nodes WHERE id=?", (nbr_id,)
                        ).fetchone()
                        if nq and nq["quarantined"]:
                            continue

                    if nbr_id not in activation or propagated > activation[nbr_id]:
                        activation[nbr_id] = propagated
                        if nbr_id not in visited:
                            visited.add(nbr_id)
                            next_frontier.append(nbr_id)

            frontier = next_frontier

        # Filter by threshold and return
        return {nid: act for nid, act in activation.items() if act >= threshold}

    # ──────────────────────────────────────────────────────────────
    # Context Engineering Layer (Cycle 239)
    # Inspired by LCM (arXiv:2605.04050) + Searchat (dual-layer index).
    # immutable_store ensures data survives compaction/deletion.
    # ──────────────────────────────────────────────────────────────

    def _init_immutable_store(self):
        """Create the immutable_store table if not yet present.

        The immutable store is an append-only log that captures every
        ``add()`` call's原始 data.  It enables lossless recovery via
        ``expand()`` and full-text search via ``grep()`` even after
        nodes are compacted or deleted.

        Schema:
        - seq: auto-increment sequence number (monotonic).
        - node_id: FK to nodes(id) at time of insertion.
        - label, kind, data, tags, category: snapshot of node fields.
        - timestamp: wall-clock at insertion.
        """
        self.conn.executescript("""
            CREATE TABLE IF NOT EXISTS immutable_store (
                seq INTEGER PRIMARY KEY AUTOINCREMENT,
                node_id TEXT NOT NULL,
                label TEXT,
                kind TEXT,
                data TEXT DEFAULT '{}',
                tags TEXT DEFAULT '[]',
                category TEXT DEFAULT NULL,
                timestamp REAL NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_immut_node ON immutable_store(node_id);
            CREATE INDEX IF NOT EXISTS idx_immut_kind ON immutable_store(kind);
            CREATE INDEX IF NOT EXISTS idx_immut_ts ON immutable_store(timestamp);
        """)

    def _immutable_log(self, node_id: str, label: str, kind: str,
                       data: dict, tags: list, category: str = None):
        """Append a record to the immutable store.

        Called automatically from ``add()``.  Also callable directly
        for retroactive logging of pre-existing nodes.
        """
        self.conn.execute(
            "INSERT INTO immutable_store (node_id,label,kind,data,tags,category,timestamp) "
            "VALUES (?,?,?,?,?,?,?)",
            (node_id, label, kind, json.dumps(data or {}),
             json.dumps(tags or []), category, time.time())
        )

    def immutable_retrieve(self, node_id: str) -> list[dict]:
        """Return all immutable snapshots for *node_id*, oldest first.

        Each record is a dict with keys: seq, node_id, label, kind,
        data, tags, category, timestamp.

        Returns an empty list if the node was never logged.
        """
        rows = self.conn.execute(
            "SELECT * FROM immutable_store WHERE node_id=? ORDER BY seq",
            (node_id,)
        ).fetchall()
        return [dict(r) for r in rows]

    def immutable_all(self, limit: int = 0) -> list[dict]:
        """Return immutable store records, newest first.

        Args:
            limit: Max records to return. ``0`` means all.
        """
        sql = "SELECT * FROM immutable_store ORDER BY seq DESC"
        params = ()
        if limit and limit > 0:
            sql += " LIMIT ?"
            params = (limit,)
        return [dict(r) for r in self.conn.execute(sql, params).fetchall()]

    def immutable_count(self) -> int:
        """Return total number of records in the immutable store."""
        return self.conn.execute(
            "SELECT COUNT(*) AS c FROM immutable_store"
        ).fetchone()["c"]

    def grep(self, pattern: str, case_insensitive: bool = True) -> list[dict]:
        """Search across ALL immutable history for *pattern*.

        Unlike ``search()`` which only sees current live nodes,
        ``grep()`` scans the immutable store — including nodes that
        were later compacted, superseded, or deleted.

        Searches label and data fields (JSON string match).

        Args:
            pattern: Substring to search for.
            case_insensitive: If True, performs case-insensitive search.

        Returns:
            List of matching records (dicts), newest first.
        """
        like_pattern = f"%{pattern}%"
        if case_insensitive:
            sql = ("SELECT * FROM immutable_store "
                   "WHERE LOWER(label) LIKE LOWER(?) ESCAPE '\\' "
                   "OR LOWER(data) LIKE LOWER(?) ESCAPE '\\' "
                   "ORDER BY seq DESC")
        else:
            sql = ("SELECT * FROM immutable_store "
                   "WHERE label GLOB ? OR data GLOB ? "
                   "ORDER BY seq DESC")
            # GLOB is case-sensitive in SQLite
            glob_pattern = f"*{pattern}*"
            rows = self.conn.execute(sql, (glob_pattern, glob_pattern)).fetchall()
            return [dict(r) for r in rows]
        rows = self.conn.execute(sql, (like_pattern, like_pattern)).fetchall()
        return [dict(r) for r in rows]

    def expand(self, node_id: str) -> Optional[dict]:
        """Losslessly recover the original node data from immutable store.

        If the node still exists in the live ``nodes`` table, returns
        the current data.  If it has been deleted/compacted, falls back
        to the most recent immutable snapshot.

        Returns ``None`` if neither live nor immutable data exists.
        """
        # Try live node first
        row = self.conn.execute(
            "SELECT * FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if row:
            return dict(row)
        # Fall back to latest immutable snapshot
        rows = self.conn.execute(
            "SELECT * FROM immutable_store WHERE node_id=? ORDER BY seq DESC LIMIT 1",
            (node_id,)
        ).fetchall()
        if rows:
            return dict(rows[0])
        return None

    # ──────────────────────────────────────────────────────────────
    # compact() — three-level upgrade (Cycle 240)
    # LCM-inspired: LLM-detailed → LLM-bullet → deterministic truncate
    # ──────────────────────────────────────────────────────────────

    def compact_node(self, node_id: str, max_label_len: int = 80,
                level: int = 0,
                summarizer=None) -> Optional[dict]:
        """Compact a node's representation, preserving key info.

        Three-level upgrade inspired by LCM (arXiv:2605.04050):
        - **Level 2** (default): Deterministic truncation — truncate
          label to *max_label_len* chars with ellipsis, compact data
          by keeping only top-level keys.
        - **Level 1**: LLM bullet summary — if *summarizer* callable is
          provided, call ``summarizer(label, data)`` → bullet-point summary.
        - **Level 0**: LLM detailed summary — if *summarizer* is provided
          and level=0, call ``summarizer(label, data)`` → detailed paragraph.

        The original data is ALWAYS preserved in the immutable store.
        Only the live ``nodes`` row is updated.

        Args:
            node_id: Target node to compact.
            max_label_len: Max characters for level-2 label truncation.
            level: Compaction level (0=detailed, 1=bullet, 2=truncate).
            summarizer: Optional callable(label:str, data:dict) → str.
                If None and level < 2, falls back to level 2.

        Returns:
            Dict with keys: node_id, old_label, new_label, level,
            old_data_len, new_data_len. Or ``None`` if node not found.
        """
        row = self.conn.execute(
            "SELECT * FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            return None

        old_label = row["label"]
        old_data = json.loads(row["data"]) if row["data"] else {}
        old_data_str = json.dumps(old_data)
        old_len = len(old_data_str)

        # Determine effective level
        effective_level = level if (level < 2 and summarizer) else 2

        if effective_level < 2 and summarizer:
            # LLM-backed summarization
            try:
                summary = summarizer(old_label, old_data)
                if summary and isinstance(summary, str):
                    new_label = summary[:max_label_len * 3]  # allow longer for LLM
                    new_data = {"_compacted": True, "_level": effective_level,
                                "_summary": summary,
                                "_orig_label_len": len(old_label)}
                else:
                    effective_level = 2
                    new_label = old_label[:max_label_len]
                    new_data = self._compact_data(old_data)
            except Exception:
                effective_level = 2
                new_label = old_label[:max_label_len]
                new_data = self._compact_data(old_data)
        else:
            # Level 2: deterministic truncation
            new_label = old_label[:max_label_len]
            if len(old_label) > max_label_len:
                new_label = new_label[:-3] + "..."
            new_data = self._compact_data(old_data)

        new_data_str = json.dumps(new_data)
        new_len = len(new_data_str)

        # Update live node
        self.conn.execute(
            "UPDATE nodes SET label=?, data=? WHERE id=?",
            (new_label, new_data_str, node_id)
        )
        self._fts_sync_node(node_id)
        self.conn.commit()
        self._tick("compact", node_id, {"level": effective_level})

        return {
            "node_id": node_id,
            "old_label": old_label,
            "new_label": new_label,
            "level": effective_level,
            "old_data_len": old_len,
            "new_data_len": new_len,
        }

    def _compact_data(self, data: dict, max_keys: int = 10) -> dict:
        """Deterministic data compaction (level 2).

        Keeps top-level keys only, limiting to *max_keys*.
        Nested dicts/lists are replaced with type+length markers.
        """
        if not isinstance(data, dict) or not data:
            return {}
        result = {}
        for i, (k, v) in enumerate(data.items()):
            if i >= max_keys:
                result["_truncated_keys"] = len(data) - max_keys
                break
            if isinstance(v, str) and len(v) > 100:
                result[k] = v[:97] + "..."
            elif isinstance(v, dict):
                result[k] = f"{{dict:{len(v)} keys}}"
            elif isinstance(v, list):
                result[k] = f"[list:{len(v)} items]"
            else:
                result[k] = v
        return result

    def compact_batch(self, node_ids: list[str], max_label_len: int = 80,
                      level: int = 2, summarizer=None) -> list[dict]:
        """Compact multiple nodes in one call.

        Returns list of compaction results (same format as ``compact()``).
        Nodes that don't exist are skipped (no error).
        """
        results = []
        for nid in node_ids:
            r = self.compact_node(nid, max_label_len=max_label_len,
                             level=level, summarizer=summarizer)
            if r:
                results.append(r)
        return results

    def compact_stats(self) -> dict:
        """Return statistics about compacted vs. uncompacted nodes.

        A node is considered "compacted" if its data contains
        ``_compacted: True``.
        """
        total = self.conn.execute(
            "SELECT COUNT(*) AS c FROM nodes"
        ).fetchone()["c"]
        compacted = self.conn.execute(
            "SELECT COUNT(*) AS c FROM nodes WHERE data LIKE '%_compacted%'",
        ).fetchone()["c"]
        immutable = self.immutable_count()
        return {
            "total_nodes": total,
            "compacted_nodes": compacted,
            "uncompacted_nodes": total - compacted,
            "immutable_records": immutable,
            "compaction_ratio": round(compacted / total, 4) if total else 0.0,
        }

    # ──────────────────────────────────────────────────────────────
    # serialize() — token-budget-aware context serialization (Cycle 241)
    # Searchat-inspired: pointer-based representation for max info density
    # ──────────────────────────────────────────────────────────────

    def serialize(self, node_ids: list[str] = None, token_budget: int = 4096,
                  include_edges: bool = True,
                  include_data: bool = True) -> dict:
        """Serialize graph nodes into a token-budgeted context representation.

        Inspired by Searchat dual-layer index: produces a compact
        text representation with pointers (node IDs) for expandable
        detail.  Maximizes information density within *token_budget*.

        Output format::

            {
                "context": "[id1] label1 (kind1)\n[id2] label2 ...",
                "node_pointers": {"id1": {"label":..., "kind":...}, ...},
                "edge_summary": [{"source": id1, "target": id2, ...}],
                "tokens_used": 123,
                "tokens_budget": 4096,
                "nodes_included": 5,
                "nodes_truncated": 0,
                "compacted_nodes": ["id3", ...],
            }

        Args:
            node_ids: Specific nodes to serialize. If None, uses all nodes
                ordered by weight descending (most important first).
            token_budget: Approximate token budget (1 token ≈ 4 chars).
            include_edges: If True, include edge summary within budget.
            include_data: If True, include data field snippets.

        Returns:
            Serialization dict with context string and metadata.
        """
        # Select nodes
        if node_ids is None:
            rows = self.conn.execute(
                "SELECT id FROM nodes ORDER BY weight DESC, accessed DESC"
            ).fetchall()
            node_ids = [r["id"] for r in rows]

        char_budget = token_budget * 4
        char_used = 0
        context_lines = []
        node_pointers = {}
        nodes_included = 0
        nodes_truncated = 0
        compacted_ids = []

        for nid in node_ids:
            row = self.conn.execute(
                "SELECT * FROM nodes WHERE id=?", (nid,)
            ).fetchone()
            if not row:
                continue

            label = row["label"] or ""
            kind = row["kind"] or ""
            data_str = row["data"] or "{}"
            is_compacted = "_compacted" in data_str

            # Estimate line size
            if include_data and data_str != "{}":
                data_preview = data_str[:80]
                line = f"[{nid}] {label} ({kind}) {data_preview}"
            else:
                line = f"[{nid}] {label} ({kind})"

            line_len = len(line) + 1  # +1 for newline

            if char_used + line_len > char_budget:
                nodes_truncated = len(node_ids) - nodes_included
                break

            context_lines.append(line)
            node_pointers[nid] = {"label": label, "kind": kind}
            if is_compacted:
                compacted_ids.append(nid)
            char_used += line_len
            nodes_included += 1

        # Edge summary (within remaining budget)
        edge_summary = []
        if include_edges and nodes_included > 0:
            included_set = set(node_pointers.keys())
            placeholders = ",".join(f"'{nid}'" for nid in included_set)
            edge_rows = self.conn.execute(
                f"SELECT source, target, relation, weight FROM edges "
                f"WHERE source IN ({placeholders}) OR target IN ({placeholders})"
            ).fetchall()
            for er in edge_rows:
                edge_line = {"source": er["source"], "target": er["target"],
                             "relation": er["relation"], "weight": er["weight"]}
                edge_str = json.dumps(edge_line)
                if char_used + len(edge_str) < char_budget:
                    edge_summary.append(edge_line)
                    char_used += len(edge_str)
                else:
                    break

        context = "\n".join(context_lines)
        return {
            "context": context,
            "node_pointers": node_pointers,
            "edge_summary": edge_summary,
            "tokens_used": max(1, char_used // 4),
            "tokens_budget": token_budget,
            "nodes_included": nodes_included,
            "nodes_truncated": nodes_truncated,
            "compacted_nodes": compacted_ids,
        }

    def serialize_compact(self, token_budget: int = 2048) -> dict:
        """Convenience: serialize all nodes with auto-compaction.

        First auto-compacts low-weight nodes (below median weight),
        then serializes within *token_budget*.

        Args:
            token_budget: Target token budget for the output.

        Returns:
            Same format as ``serialize()``.
        """
        rows = self.conn.execute(
            "SELECT id, weight FROM nodes ORDER BY weight"
        ).fetchall()
        if not rows:
            return self.serialize(token_budget=token_budget)

        weights = [r["weight"] for r in rows]
        median_w = sorted(weights)[len(weights) // 2]

        to_compact = [r["id"] for r in rows if r["weight"] < median_w]
        if to_compact:
            self.compact_batch(to_compact, level=2)

        return self.serialize(token_budget=token_budget)



    # ──────────────────────────────────────────────────────────────
    # RelationIntegrityChecker (Cycle 242)
    # ShadowMerge defense (arXiv:2605.09033) — 93.8% attack rate on graph memory
    # Three checks: value_conflict / confidence_anomaly / origin_mismatch
    # ──────────────────────────────────────────────────────────────

    def check_relation_integrity(self, node_id: str = None) -> dict:
        """Scan for relation-channel integrity issues.

        Inspired by ShadowMerge attack analysis (arXiv:2605.09033):
        93.8% attack success rate against graph memory via relation-channel
        conflicts. This is a defensive scan to detect such patterns.

        Three check types:
        1. **value_conflict** — same source+relation, targets with contradictory data.
        2. **confidence_anomaly** — node with low trust_level not quarantined.
        3. **origin_mismatch** — edge between high-trust and low-trust nodes.

        Args:
            node_id: If provided, only check edges involving this node.
                If None, checks all edges (full scan).

        Returns:
            Dict with keys: issues, summary, integrity_score.
        """
        issues = []

        if node_id:
            edges = self.conn.execute(
                "SELECT * FROM edges WHERE source=? OR target=?",
                (node_id, node_id)
            ).fetchall()
        else:
            edges = self.conn.execute("SELECT * FROM edges").fetchall()

        if not edges:
            edges = []  # Still run node-level checks below

        # Check 1: value_conflict
        edge_map = {}
        for e in edges:
            key = (e["source"], e["relation"])
            edge_map.setdefault(key, []).append(e)

        for (src, rel), group in edge_map.items():
            if len(group) < 2:
                continue
            target_data = []
            for ge in group:
                trow = self.conn.execute(
                    "SELECT data, trust_level FROM nodes WHERE id=?",
                    (ge["target"],)
                ).fetchone()
                if trow:
                    target_data.append((ge["target"],
                                        json.loads(trow["data"] or "{}"),
                                        trow["trust_level"]))

            for i in range(len(target_data)):
                for j in range(i + 1, len(target_data)):
                    tid1, d1, _ = target_data[i]
                    tid2, d2, _ = target_data[j]
                    conflicts = self._detect_value_conflicts(d1, d2)
                    for field, v1, v2 in conflicts:
                        issues.append({
                            "type": "value_conflict",
                            "source": src,
                            "relation": rel,
                            "targets": [tid1, tid2],
                            "field": field,
                            "values": [v1, v2],
                            "severity": "high",
                            "details": f"Field '{field}' has conflicting values: {v1} vs {v2}",
                        })

        # Check 2: confidence_anomaly
        trust_rows = self.conn.execute(
            "SELECT id, label, trust_level, quarantined FROM nodes "
            "WHERE trust_level < 0.3 AND quarantined = 0"
        ).fetchall()
        for tr in trust_rows:
            issues.append({
                "type": "confidence_anomaly",
                "node_id": tr["id"],
                "label": tr["label"],
                "trust_level": tr["trust_level"],
                "severity": "medium",
                "details": f"Node '{tr['label']}' has low trust_level={tr['trust_level']:.3f} but not quarantined",
            })

        # Check 3: origin_mismatch
        for e in edges:
            src_row = self.conn.execute(
                "SELECT trust_level FROM nodes WHERE id=?",
                (e["source"],)
            ).fetchone()
            tgt_row = self.conn.execute(
                "SELECT trust_level FROM nodes WHERE id=?",
                (e["target"],)
            ).fetchone()
            if src_row and tgt_row:
                trust_diff = abs(src_row["trust_level"] - tgt_row["trust_level"])
                if trust_diff > 0.5:
                    issues.append({
                        "type": "origin_mismatch",
                        "edge": {"source": e["source"], "target": e["target"],
                                 "relation": e["relation"]},
                        "source_trust": src_row["trust_level"],
                        "target_trust": tgt_row["trust_level"],
                        "trust_gap": round(trust_diff, 3),
                        "severity": "low" if trust_diff < 0.7 else "high",
                        "details": f"Trust gap {trust_diff:.3f} between linked nodes",
                    })

        # Summary
        by_type = {}
        by_severity = {}
        for iss in issues:
            by_type[iss["type"]] = by_type.get(iss["type"], 0) + 1
            by_severity[iss["severity"]] = by_severity.get(iss["severity"], 0) + 1

        total_checks = max(len(edges), 1)
        integrity_score = max(0.0, 1.0 - len(issues) / total_checks)

        return {
            "issues": issues,
            "summary": {
                "total": len(issues),
                "by_type": by_type,
                "by_severity": by_severity,
                "total_edges": len(edges),
            },
            "integrity_score": round(integrity_score, 4),
        }

    def _detect_value_conflicts(self, d1: dict, d2: dict,
                                fields: list[str] = None) -> list[tuple]:
        """Detect conflicting scalar values between two data dicts.

        Only compares keys present in BOTH dicts with different values.
        Skips complex types (dict/list).
        """
        conflicts = []
        keys = set(d1.keys()) & set(d2.keys())
        if fields:
            keys &= set(fields)
        for key in keys:
            v1, v2 = d1[key], d2[key]
            if isinstance(v1, (dict, list)) or isinstance(v2, (dict, list)):
                continue
            if v1 != v2:
                conflicts.append((key, v1, v2))
        return conflicts

    def integrity_quarantine(self, issues: list[dict] = None,
                             severity_threshold: str = "high") -> list[str]:
        """Auto-quarantine nodes flagged by high-severity integrity issues.

        Args:
            issues: Issues list from check_relation_integrity().
                If None, runs a fresh full scan.
            severity_threshold: Quarantine at this severity or above
                ('high', 'medium', 'low').

        Returns:
            List of node IDs that were quarantined.
        """
        if issues is None:
            result = self.check_relation_integrity()
            issues = result["issues"]

        severity_order = {"low": 0, "medium": 1, "high": 2}
        threshold_level = severity_order.get(severity_threshold, 2)

        quarantined = []
        for iss in issues:
            if severity_order.get(iss["severity"], 0) >= threshold_level:
                node_ids = set()
                if "node_id" in iss:
                    node_ids.add(iss["node_id"])
                if "targets" in iss:
                    node_ids.update(iss["targets"])
                if "edge" in iss:
                    node_ids.add(iss["edge"]["source"])
                    node_ids.add(iss["edge"]["target"])

                for nid in node_ids:
                    self.conn.execute(
                        "UPDATE nodes SET quarantined=1, quarantine_reason=? "
                        "WHERE id=? AND quarantined=0",
                        (f"integrity: {iss['type']}", nid)
                    )
                    if self.conn.total_changes > 0:
                        quarantined.append(nid)

        self.conn.commit()
        if quarantined:
            self._tick("integrity_quarantine", ",".join(quarantined[:5]),
                        {"count": len(quarantined)})
        return quarantined



    # ------------------------------------------------------------------
    # Cycle 243: Semantic Speed Gate (RoMem-inspired edge volatility)
    # ------------------------------------------------------------------

    def semantic_speed_gate(self, node_id: str, *, window_hours: float = 24.0,
                            query_time: float | None = None) -> dict:
        """Measure edge-neighborhood volatility for a single node.

        Inspired by RoMem (2026): semantic speed captures how fast a node's
        neighborhood is changing.  High speed → active learning / instability,
        low speed → stable, settled knowledge.

        Speed is computed as the fraction of edges (in + out) created or
        modified within ``window_hours`` of ``query_time``, weighted by edge
        weight so important new connections count more.

        Returns a dict with:
        - ``speed``: volatility score in [0, 1] (1 = all edges recent)
        - ``edge_count``: total edges examined
        - ``recent_edges``: edges within the window
        - ``stability``: 1 - speed (convenience for sorting)
        - ``velocity``: recent_edges per hour (raw rate)
        - ``verdict``: 'volatile' | 'active' | 'stable'

        Args:
            node_id:     Node to examine.
            window_hours: Time window in hours (default 24).
            query_time:  Reference timestamp (default: now).

        Returns:
            Dict with speed breakdown, or ``{"speed": 0.0, "not_found": True}``.
        """
        now = query_time if query_time is not None else time.time()
        window_seconds = window_hours * 3600.0

        # Fetch edges for this node
        rows = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges "
            "WHERE source=? OR target=?",
            (node_id, node_id)
        ).fetchall()

        if not rows:
            # Check if node exists at all
            exists = self.conn.execute(
                "SELECT id FROM nodes WHERE id=?", (node_id,)
            ).fetchone()
            if exists is None:
                return {"speed": 0.0, "not_found": True}
            return {
                "speed": 0.0, "edge_count": 0, "recent_edges": 0,
                "stability": 1.0, "velocity": 0.0, "verdict": "stable",
            }

        # Build edge creation-time lookup from clock_log
        edge_times: dict[tuple[str, str, str], float] = {}
        log_rows = self.conn.execute(
            "SELECT node_id, details, wall_time FROM clock_log WHERE op='link'"
        ).fetchall()
        for lr in log_rows:
            try:
                detail = json.loads(lr["details"])
                key = (detail["source"], detail["target"], detail["relation"])
                edge_times[key] = lr["wall_time"]
            except (json.JSONDecodeError, KeyError, TypeError):
                continue

        total_weight = 0.0
        recent_weight = 0.0
        recent_count = 0

        for r in rows:
            w = r["weight"] if r["weight"] is not None else 0.5
            total_weight += w
            # Look up creation time from clock_log; fallback to node created time
            key = (r["source"], r["target"], r["relation"])
            edge_created = edge_times.get(key)
            if edge_created is None:
                # Fallback: use the younger endpoint's created time as approximation
                node_row = self.conn.execute(
                    "SELECT created FROM nodes WHERE id=?", (r["source"],)
                ).fetchone()
                edge_created = node_row["created"] if node_row else now
            age = now - (edge_created or now)
            if age <= window_seconds:
                recent_weight += w
                recent_count += 1

        if total_weight == 0:
            speed = 0.0
        else:
            speed = recent_weight / total_weight

        velocity = recent_count / window_hours if window_hours > 0 else 0.0

        if speed >= 0.6:
            verdict = "volatile"
        elif speed >= 0.25:
            verdict = "active"
        else:
            verdict = "stable"

        return {
            "speed": round(speed, 4),
            "edge_count": len(rows),
            "recent_edges": recent_count,
            "stability": round(1.0 - speed, 4),
            "velocity": round(velocity, 4),
            "verdict": verdict,
        }

    def speed_gate_batch(self, node_ids: list[str] = None, *,
                         window_hours: float = 24.0,
                         query_time: float | None = None,
                         min_speed: float = 0.0) -> list[dict]:
        """Batch semantic speed gate for multiple (or all) nodes.

        Args:
            node_ids:  Nodes to check.  If None, checks all non-quarantined nodes.
            window_hours: Time window for volatility.
            query_time: Reference timestamp.
            min_speed: Only return nodes with speed >= this value.

        Returns:
            List of dicts (node_id, label, kind, speed, stability, verdict)
            sorted by speed descending.
        """
        if node_ids is None:
            rows = self.conn.execute(
                "SELECT id FROM nodes WHERE quarantined=0"
            ).fetchall()
            node_ids = [r["id"] for r in rows]

        results = []
        for nid in node_ids:
            sg = self.semantic_speed_gate(
                nid, window_hours=window_hours, query_time=query_time
            )
            if sg.get("not_found"):
                continue
            if sg["speed"] < min_speed:
                continue
            # Attach label/kind for convenience
            node = self.conn.execute(
                "SELECT label, kind FROM nodes WHERE id=?", (nid,)
            ).fetchone()
            results.append({
                "node_id": nid,
                "label": node["label"] if node else "",
                "kind": node["kind"] if node else "",
                **{k: v for k, v in sg.items() if k != "not_found"},
            })

        results.sort(key=lambda x: x["speed"], reverse=True)
        return results

    def volatile_nodes(self, *, window_hours: float = 24.0,
                       min_speed: float = 0.5, limit: int = 20,
                       query_time: float | None = None) -> list[dict]:
        """Shortcut: get the most volatile nodes (high edge turnover).

        Useful for prioritising which nodes to consolidate or compact.

        Args:
            window_hours: Time window for speed calculation.
            min_speed:    Minimum speed threshold.
            limit:        Max results.
            query_time:   Reference timestamp.

        Returns:
            List of speed-gate dicts, most volatile first.
        """
        batch = self.speed_gate_batch(
            window_hours=window_hours,
            query_time=query_time,
            min_speed=min_speed,
        )
        return batch[:limit]

    # ------------------------------------------------------------------
    # Cycle 243: Selective Filter (Context Engineering Layer)
    # ------------------------------------------------------------------

    def selective_filter(self, node_ids: list[str], *,
                         max_weight: float | None = None,
                         min_weight: float | None = None,
                         kinds: list[str] | None = None,
                         exclude_kinds: list[str] | None = None,
                         exclude_quarantined: bool = True,
                         max_staleness: float | None = None,
                         require_fresh: bool = False,
                         limit: int | None = None) -> list[str]:
        """Filter a set of node IDs by multiple quality criteria.

        Inspired by Context Engineering's selective filtering stage:
        before sending context to an LLM, prune nodes that are too stale,
        too low-weight, wrong kind, or quarantined.

        All filters are optional — pass only the ones you need.

        Args:
            node_ids:          Candidate node IDs.
            max_weight:        Exclude nodes above this weight.
            min_weight:        Exclude nodes below this weight.
            kinds:             Whitelist of node kinds to keep.
            exclude_kinds:     Blacklist of node kinds to drop.
            exclude_quarantined: Drop quarantined nodes (default True).
            max_staleness:     Drop nodes with staleness above this.
            require_fresh:     Only keep nodes with staleness < 0.3.
            limit:             Truncate to first N after filtering.

        Returns:
            Filtered list of node IDs (preserves input order).
        """
        if not node_ids:
            return []

        placeholders = ",".join("?" * len(node_ids))
        rows = self.conn.execute(
            f"SELECT id, label, kind, weight, quarantined, accessed "
            f"FROM nodes WHERE id IN ({placeholders})",
            node_ids
        ).fetchall()

        row_map = {r["id"]: r for r in rows}
        result = []

        for nid in node_ids:
            r = row_map.get(nid)
            if r is None:
                continue  # doesn't exist

            # Quarantine filter
            if exclude_quarantined and r["quarantined"]:
                continue

            # Weight filters
            w = r["weight"] if r["weight"] is not None else 0.5
            if min_weight is not None and w < min_weight:
                continue
            if max_weight is not None and w > max_weight:
                continue

            # Kind filters
            if kinds is not None and r["kind"] not in kinds:
                continue
            if exclude_kinds is not None and r["kind"] in exclude_kinds:
                continue

            # Staleness filters
            if max_staleness is not None or require_fresh:
                s = self.staleness_score(r["id"])
                if max_staleness is not None and s > max_staleness:
                    continue
                if require_fresh and s >= 0.3:
                    continue

            result.append(nid)

        if limit is not None:
            result = result[:limit]
        return result

    def selective_filter_report(self, node_ids: list[str], **kwargs) -> dict:
        """Run selective_filter and return a summary report.

        Returns:
            {
                "input_count": N,
                "output_count": M,
                "dropped": N - M,
                "drop_rate": float,
                "filtered_ids": [...],
            }
        """
        filtered = self.selective_filter(node_ids, **kwargs)
        input_count = len(node_ids)
        output_count = len(filtered)
        dropped = input_count - output_count
        return {
            "input_count": input_count,
            "output_count": output_count,
            "dropped": dropped,
            "drop_rate": round(dropped / input_count, 4) if input_count else 0.0,
            "filtered_ids": filtered,
        }

    # ── Procedural Memory: Experience Compression (L1→L2) ──────────

    def compress_to_skill(self, episode_ids: list[str], name: str,
                          *, description: str = "",
                          confidence: float = 0.5) -> Optional[Node]:
        """Compress multiple episodic memories into a procedural skill node.

        Implements the L1→L2 upward compression described in the Experience
        Compression Spectrum (Zhang et al., arXiv:2604.15877):

            L0 (trace)  → L1 (episodic, 5-20×) → L2 (skill, 50-500×)

        Given a set of episode / event / fact nodes, this method:

        1. Validates all *episode_ids* exist.
        2. Extracts labels + data from source episodes.
        3. Creates a ``kind='skill'`` node with a **Skill Contract** data
           structure (inspired by Anything2Skill, arXiv:2607.09033):

           .. code-block:: python

               {
                   "skill_name": "...",
                   "description": "...",
                   "source_episodes": ["id1", "id2", ...],
                   "source_count": N,
                   "compression_ratio": approx,
                   "confidence": float,          # 0.0–1.0
                   "version": "0.1.0",
                   "invocation_conditions": [],   # filled by caller or evolve
                   "steps": [],                   # extracted steps
                   "constraints": [],
                   "created_at": timestamp,
               }

        4. Links skill → each source episode via ``'abstracts'`` edge
           (reuses crystallize_intents convention).
        5. Awards a Q-value boost to the new skill node.

        Args:
            episode_ids: Source episode / event / fact node IDs.
            name: Skill name (becomes node label).
            description: Optional human-readable summary.
            confidence: Initial confidence [0,1].

        Returns:
            The created skill :class:`Node`, or ``None`` if no valid episodes.
        """
        if not episode_ids:
            return None

        # Validate source episodes
        valid = []
        for eid in episode_ids:
            row = self.conn.execute(
                "SELECT id, label, kind, data FROM nodes WHERE id=?", (eid,)
            ).fetchone()
            if row:
                valid.append(row)

        if not valid:
            return None

        # Extract steps from source episodes (labels become step candidates)
        steps = []
        source_labels = []
        source_kinds = set()
        for row in valid:
            source_labels.append(row["label"])
            source_kinds.add(row["kind"])
            d = row["data"]
            if isinstance(d, str):
                try:
                    d = json.loads(d)
                except Exception:
                    d = {}
            if isinstance(d, dict):
                action = d.get("action") or d.get("step")
                if action:
                    steps.append(action)

        # Deduplicate steps while preserving order
        seen = set()
        unique_steps = []
        for s in steps:
            if s not in seen:
                seen.add(s)
                unique_steps.append(s)

        # Build Skill Contract
        source_count = len(valid)
        # Approximate compression: episodes → 1 skill node
        # Each episode ~5 tokens of label+data vs 1 consolidated node
        compression_ratio = round(source_count * 5.0, 1)

        skill_data = {
            "skill_name": name,
            "description": description,
            "source_episodes": [r["id"] for r in valid],
            "source_count": source_count,
            "source_kinds": sorted(source_kinds),
            "compression_ratio": compression_ratio,
            "confidence": max(0.0, min(1.0, confidence)),
            "version": "0.1.0",
            "invocation_conditions": [],
            "steps": unique_steps,
            "constraints": [],
            "created_at": time.time(),
        }

        # Create the skill node
        skill = self.add(name, kind="skill", data=skill_data,
                         tags=["procedural", "compressed"])

        # Link skill → source episodes via 'abstracts' edges
        for row in valid:
            self.link(skill.id, row["id"], "abstracts", weight=0.8)

        # Q-value boost for consolidated skills
        try:
            self.update_q(skill.id, reward=0.3,
                          reason="skill_compression")
        except Exception:
            pass

        return skill

    def retrieve_skills(self, context: str = "", *, top_k: int = 5,
                        min_confidence: float = 0.0,
                        tags: list[str] = None) -> list[Node]:
        """Retrieve procedural skill nodes matching *context*.

        Procedural retrieval inspired by Anything2Skill (arXiv:2607.09033):
        matches ``invocation_conditions`` and ``steps`` against the query
        context, combined with Q-value and recency signals.

        Scoring components (equal weight):
            - **Text relevance**: BM25 / FTS match on name + description + steps
            - **Confidence**: Skill Contract confidence field
            - **Q-value**: Learned utility (if available)
            - **Recency**: Fresher skills get a small boost

        Args:
            context: Task / query context to match against.
            top_k: Maximum skills to return.
            min_confidence: Filter out skills below this threshold.
            tags: Optional tag filter.

        Returns:
            List of skill :class:`Node` objects, best first.
        """
        query = (
            "SELECT id FROM nodes WHERE kind='skill'"
        )
        params: list = []
        if tags:
            # Simple tag containment check
            query += " AND tags LIKE ?"
            params.append(f'%"{tags[0]}"%')
        rows = self.conn.execute(query, params).fetchall()

        if not rows:
            return []

        # Gather text for BM25-like scoring
        terms = set(context.lower().split()) if context else set()
        scored = []

        for row in rows:
            node = self.get_node(row["id"])
            if not node:
                continue
            d = node.data if isinstance(node.data, dict) else {}
            confidence = d.get("confidence", 0.5)
            if confidence < min_confidence:
                continue

            # Text relevance: term overlap on name + description + steps
            text_parts = [node.label.lower()]
            if isinstance(d, dict):
                text_parts.append(str(d.get("description", "")).lower())
                for s in d.get("steps", []):
                    text_parts.append(str(s).lower())
                for c in d.get("invocation_conditions", []):
                    text_parts.append(str(c).lower())
            blob = " ".join(text_parts)

            if terms:
                hits = sum(1 for t in terms if t in blob)
                text_score = hits / max(len(terms), 1)
            else:
                text_score = 0.5  # neutral if no query

            # Confidence signal
            conf_score = confidence

            # Q-value signal
            q = 0.5
            try:
                qrow = self.conn.execute(
                    "SELECT q_value FROM nodes WHERE id=?", (node.id,)
                ).fetchone()
                if qrow and qrow["q_value"] is not None:
                    q = min(max(qrow["q_value"], 0.0), 1.0)
            except Exception:
                pass

            # Recency signal
            age = time.time() - node.created
            recency = max(0.0, 1.0 - age / (365.0 * 86400))  # 1-year half-life

            combined = 0.30 * text_score + 0.25 * conf_score + 0.30 * q + 0.15 * recency
            scored.append((combined, node))

        scored.sort(key=lambda x: x[0], reverse=True)
        return [n for _, n in scored[:top_k]]

    def evolve_skill(self, skill_id: str, *,
                     feedback: float = 0.0,
                     new_steps: list[str] = None,
                     new_constraints: list[str] = None,
                     description: str = None,
                     reason: str = "") -> Optional[Node]:
        """Evolve a procedural skill with feedback and version tracking.

        Inspired by AutoRefine (arXiv:2607.04588): skills without maintenance
        decay.  This method applies feedback (positive or negative) and
        optionally extends the Skill Contract, then increments the patch
        version (semver).

        - Positive *feedback* (→ 1.0): increases confidence and Q-value.
        - Negative *feedback* (→ -1.0): decreases confidence; if it drops
          below 0.1, the skill is marked as deprecated via a tag.

        Uses the existing ``supersede`` mechanism to record the evolution
        chain, so ``trace_decision_chain()`` can reconstruct the skill's
        history.

        Args:
            skill_id: The skill node to evolve.
            feedback: Signal in [-1, 1]. Positive = success, negative = failure.
            new_steps: Additional steps to append.
            new_constraints: Additional constraints to append.
            description: New description (replaces old).
            reason: Human-readable reason for this evolution.

        Returns:
            Updated skill :class:`Node`, or ``None`` if not found.
        """
        node = self.get_node(skill_id)
        if not node or node.kind != "skill":
            return None

        d = node.data if isinstance(node.data, dict) else {}

        # Adjust confidence
        old_conf = d.get("confidence", 0.5)
        delta = feedback * 0.15  # 15% per feedback event
        new_conf = max(0.0, min(1.0, old_conf + delta))
        d["confidence"] = round(new_conf, 4)

        # Append steps / constraints
        if new_steps:
            existing_steps = d.get("steps", [])
            for s in new_steps:
                if s not in existing_steps:
                    existing_steps.append(s)
            d["steps"] = existing_steps

        if new_constraints:
            existing_cons = d.get("constraints", [])
            for c in new_constraints:
                if c not in existing_cons:
                    existing_cons.append(c)
            d["constraints"] = existing_cons

        if description is not None:
            d["description"] = description

        # Version bump (patch level)
        ver = d.get("version", "0.1.0")
        parts = ver.split(".")
        if len(parts) == 3:
            parts[2] = str(int(parts[2]) + 1)
            d["version"] = ".".join(parts)
        else:
            d["version"] = "0.1.1"

        d["last_evolved_at"] = time.time()
        d["last_evolution_reason"] = reason

        # Deprecate if confidence too low
        tags = json.loads(
            self.conn.execute("SELECT tags FROM nodes WHERE id=?", (skill_id,)).fetchone()["tags"]
        ) if self.conn.execute("SELECT tags FROM nodes WHERE id=?", (skill_id,)).fetchone() else []
        if new_conf < 0.1 and "deprecated" not in tags:
            tags.append("deprecated")
        elif new_conf >= 0.1 and "deprecated" in tags:
            tags.remove("deprecated")

        # Persist
        self.conn.execute(
            "UPDATE nodes SET data=?, tags=?, accessed=? WHERE id=?",
            (json.dumps(d), json.dumps(tags), time.time(), skill_id)
        )

        # Q-value adjustment
        try:
            if feedback > 0:
                self.update_q(skill_id, reward=feedback * 0.2,
                              reason=f"skill_evolve: {reason}")
            elif feedback < 0:
                self.penalize_q(skill_id, penalty=abs(feedback) * 0.2,
                                reason=f"skill_evolve: {reason}")
        except Exception:
            pass

        # Record evolution as a supersede chain entry
        try:
            self.conn.execute(
                "INSERT OR REPLACE INTO supersede_chain"
                " (old_id, new_id, trigger, reason, evidence, timestamp)"
                " VALUES (?, ?, ?, ?, ?, ?)",
                (skill_id, skill_id, "skill_evolution",
                 reason or "feedback-based evolution",
                 json.dumps({"feedback": feedback,
                              "old_confidence": old_conf,
                              "new_confidence": new_conf,
                              "version": d["version"]}),
                 time.time())
            )
        except Exception:
            pass

        self.conn.commit()
        self._tick("evolve_skill", skill_id, {"feedback": feedback})
        return self.get_node(skill_id)

    def skill_bank_health(self) -> dict:
        """Health metrics for the procedural skill bank.

        Mirrors ``agent-context-store``'s ``store_health_check`` pattern,\n        applied to L2 procedural memory.

        Returns a dashboard dict with:

            - total_skills: Count of skill nodes.
            - active: Skills with confidence ≥ 0.3 (not deprecated).
            - deprecated: Skills tagged 'deprecated'.
            - avg_confidence: Mean confidence across active skills.
            - avg_q_value: Mean Q-value (if Q-learning is used).
            - coverage_by_kind: Source episode kinds represented.
            - avg_staleness: Mean age of last evolution / creation.
            - redundancy: Skills sharing >60% step overlap (over-clustering).
            - recommendations: Actionable suggestions.
        """
        rows = self.conn.execute(
            "SELECT id, label, data, tags, created, accessed, weight"
            " FROM nodes WHERE kind='skill'"
        ).fetchall()

        if not rows:
            return {
                "total_skills": 0,
                "active": 0,
                "deprecated": 0,
                "avg_confidence": 0.0,
                "avg_q_value": 0.0,
                "coverage_by_kind": [],
                "avg_staleness_days": 0.0,
                "redundancy_groups": 0,
                "recommendations": ["No procedural skills yet. Use compress_to_skill() to create one."],
            }

        total = len(rows)
        confidences = []
        q_values = []
        active_count = 0
        deprecated_count = 0
        source_kinds = set()
        now = time.time()
        ages = []
        step_sets = []

        for row in rows:
            d = row["data"]
            if isinstance(d, str):
                try:
                    d = json.loads(d)
                except Exception:
                    d = {}
            if not isinstance(d, dict):
                d = {}

            tags = row["tags"]
            if isinstance(tags, str):
                try:
                    tags = json.loads(tags)
                except Exception:
                    tags = []

            conf = d.get("confidence", 0.5)
            confidences.append(conf)

            is_deprecated = "deprecated" in (tags or [])
            if is_deprecated:
                deprecated_count += 1
            elif conf >= 0.3:
                active_count += 1

            for k in d.get("source_kinds", []):
                source_kinds.add(k)

            steps = d.get("steps", [])
            if steps:
                step_sets.append(set(steps))

            # Q-value
            qrow = self.conn.execute(
                "SELECT q_value FROM nodes WHERE id=?", (row["id"],)
            ).fetchone()
            if qrow and qrow["q_value"] is not None:
                q_values.append(qrow["q_value"])

            # Age (use last_evolved_at if available)
            last_ts = d.get("last_evolved_at", row["created"])
            ages.append((now - last_ts) / 86400)  # days

        # Redundancy: pairs with >60% step overlap
        redundancy_groups = 0
        for i in range(len(step_sets)):
            for j in range(i + 1, len(step_sets)):
                overlap = len(step_sets[i] & step_sets[j])
                union = len(step_sets[i] | step_sets[j])
                if union > 0 and overlap / union > 0.6:
                    redundancy_groups += 1

        avg_conf = sum(confidences) / len(confidences) if confidences else 0.0
        avg_q = sum(q_values) / len(q_values) if q_values else 0.0
        avg_age = sum(ages) / len(ages) if ages else 0.0

        # Recommendations
        recs = []
        if avg_conf < 0.4:
            recs.append("Average confidence is low. Collect more feedback via evolve_skill().")
        if deprecated_count > active_count:
            recs.append("More deprecated than active skills. Consider pruning or refining.")
        if avg_age > 30:
            recs.append("Skills are stale (avg >30 days). Run evolve_skill() with fresh feedback.")
        if redundancy_groups > 0:
            recs.append(f"{redundancy_groups} redundant skill pairs detected. Consider merging.")
        if not recs:
            recs.append("Skill bank is healthy.")

        return {
            "total_skills": total,
            "active": active_count,
            "deprecated": deprecated_count,
            "avg_confidence": round(avg_conf, 4),
            "avg_q_value": round(avg_q, 4),
            "coverage_by_kind": sorted(source_kinds),
            "avg_staleness_days": round(avg_age, 1),
            "redundancy_groups": redundancy_groups,
            "recommendations": recs,
        }

    # ── Skill Composition (L1→L2 Meta-Skill) ──────────────────────

    def skill_compose(self, skill_ids: list[str], name: str,
                      *, description: str = "",
                      confidence: float = None) -> Optional[Node]:
        """Compose multiple L1 skills into an L2 meta-skill.

        Implements the upward composition step in the Experience
        Compression Spectrum (Zhang et al., arXiv:2604.15877):

            L0 (trace) → L1 (skill) → L2 (meta-skill)

        Given two or more ``kind='skill'`` nodes (created via
        :meth:`compress_to_skill`), this method:

        1. Validates all *skill_ids* exist and are skills.
        2. Merges their steps (union, deduplicated, order-preserving).
        3. Merges constraints from all component skills.
        4. Aggregates source episode references.
        5. Creates a new ``kind='skill'`` node with ``'composed'`` tag.
        6. Links meta-skill → each component via ``'composes'`` edges.
        7. Sets confidence = mean of components (or explicit override).

        The resulting meta-skill can itself be evolved via
        :meth:`evolve_skill` or retrieved via :meth:`retrieve_skills`.

        Args:
            skill_ids: Two or more component skill node IDs.
            name: Meta-skill name (becomes node label).
            description: Optional human-readable summary.
            confidence: Override confidence [0,1]. Default: mean of components.

        Returns:
            The created meta-skill :class:`Node`, or ``None`` if <2 valid skills.
        """
        if not skill_ids or len(skill_ids) < 2:
            return None

        # Validate component skills
        valid = []
        for sid in skill_ids:
            row = self.conn.execute(
                "SELECT id, label, kind, data FROM nodes WHERE id=?", (sid,)
            ).fetchone()
            if row and row["kind"] == "skill":
                valid.append(row)

        if len(valid) < 2:
            return None

        # Merge steps, constraints, source episodes from all components
        merged_steps = []
        merged_constraints = []
        all_source_episodes = []
        component_confidences = []
        total_source_count = 0

        for row in valid:
            d = row["data"]
            if isinstance(d, str):
                try:
                    d = json.loads(d)
                except Exception:
                    d = {}
            if not isinstance(d, dict):
                d = {}

            for s in d.get("steps", []):
                if s not in merged_steps:
                    merged_steps.append(s)

            for c in d.get("constraints", []):
                if c not in merged_constraints:
                    merged_constraints.append(c)

            for ep in d.get("source_episodes", []):
                if ep not in all_source_episodes:
                    all_source_episodes.append(ep)

            component_confidences.append(d.get("confidence", 0.5))
            total_source_count += d.get("source_count", 0)

        # Confidence: explicit override or mean of components
        if confidence is not None:
            final_confidence = max(0.0, min(1.0, confidence))
        else:
            final_confidence = round(
                sum(component_confidences) / len(component_confidences), 4
            )

        meta_data = {
            "skill_name": name,
            "description": description,
            "component_skills": [r["id"] for r in valid],
            "component_count": len(valid),
            "source_episodes": all_source_episodes,
            "aggregated_source_count": total_source_count,
            "compression_ratio": round(total_source_count * 5.0, 1),
            "confidence": final_confidence,
            "version": "0.1.0",
            "invocation_conditions": [],
            "steps": merged_steps,
            "constraints": merged_constraints,
            "composed_at": time.time(),
            "composition_level": 2,
        }

        # Create the meta-skill node
        meta = self.add(name, kind="skill", data=meta_data,
                        tags=["procedural", "composed"])

        # Link meta-skill → components via 'composes' edges
        for row in valid:
            self.link(meta.id, row["id"], "composes", weight=0.9)

        # Q-value: aggregate from components
        try:
            q_vals = []
            for row in valid:
                qrow = self.conn.execute(
                    "SELECT q_value FROM nodes WHERE id=?", (row["id"],)
                ).fetchone()
                if qrow and qrow["q_value"] is not None:
                    q_vals.append(qrow["q_value"])
            base_q = sum(q_vals) / len(q_vals) if q_vals else 0.0
            self.update_q(meta.id, reward=base_q + 0.1,
                          reason="skill_composition")
        except Exception:
            pass

        return meta

    def skill_decompose(self, meta_skill_id: str) -> list[Node]:
        """Return the component skills of an L2+ meta-skill.

        Args:
            meta_skill_id: A skill node created via :meth:`skill_compose`.

        Returns:
            List of component skill :class:`Node` objects. Empty if the
            skill has no components or doesn't exist.
        """
        node = self.get_node(meta_skill_id)
        if not node or node.kind != "skill":
            return []

        d = node.data if isinstance(node.data, dict) else {}
        component_ids = d.get("component_skills", [])
        if not component_ids:
            return []

        result = []
        for cid in component_ids:
            n = self.get_node(cid)
            if n:
                result.append(n)
        return result

    def skill_lineage(self, skill_id: str, *, depth: int = 10) -> dict:
        """Recursively expand the composition hierarchy of a skill.

        Returns a tree dict showing the full lineage:

        .. code-block:: python

            {
                "id": "meta-skill-id",
                "label": "Full Pipeline",
                "level": 2,
                "components": [
                    {"id": "skill-1", "label": "Deploy", "level": 1, ...},
                    {"id": "skill-2", "label": "Test", "level": 1, ...},
                ]
            }

        Args:
            skill_id: Root skill to expand.
            depth: Max recursion depth to prevent infinite loops.

        Returns:
            Tree dict, or empty dict if skill not found.
        """
        node = self.get_node(skill_id)
        if not node or node.kind != "skill":
            return {}

        d = node.data if isinstance(node.data, dict) else {}
        level = d.get("composition_level", 1)

        result = {
            "id": node.id,
            "label": node.label,
            "level": level,
            "confidence": d.get("confidence", 0.5),
            "steps": d.get("steps", []),
        }

        if depth > 0:
            component_ids = d.get("component_skills", [])
            if component_ids:
                children = []
                for cid in component_ids:
                    child = self.skill_lineage(cid, depth=depth - 1)
                    if child:
                        children.append(child)
                result["components"] = children

        return result

    # ── Skill Candidate Detection (Cycle 275) ─────────────────────

    _ACTION_VERBS = frozenset({
        'ran', 'created', 'built', 'tested', 'deployed', 'fixed',
        'updated', 'checked', 'analyzed', 'implemented', 'refactored',
        'debugged', 'configured', 'installed', 'wrote', 'deleted',
        'moved', 'merged', 'reviewed', 'documented', 'designed',
        'optimized', 'migrated', 'validated', 'published', 'released',
    })

    def detect_skill_candidates(self, *, min_frequency: int = 2) -> list[dict]:
        """Mine episodic memories for repeated action patterns.

        Scans event and intention nodes for recurring action verbs
        and returns candidates eligible for promotion to skill type.

        This is the read-only foundation for ``compress_to_skill()``.

        Args:
            min_frequency: Minimum occurrences to qualify as a pattern.

        Returns:
            List of candidate dicts, sorted by confidence (desc):

            .. code-block:: python

                {
                    "action": "created",
                    "frequency": 3,
                    "confidence": 0.6,
                    "memory_ids": ["abc123", ...],
                    "suggested_compression": "'created' repeated 3× — promote to skill?",
                }
        """
        import re

        # Gather episodic nodes (events + intentions), sorted by time
        rows = self.conn.execute(
            "SELECT id, label, kind, created FROM nodes "
            "WHERE kind IN ('event', 'intention') "
            "ORDER BY created ASC"
        ).fetchall()

        if len(rows) < min_frequency:
            return []

        # Extract action verb from each label (first matching verb)
        verb_pattern = re.compile(
            r'\b(' + '|'.join(sorted(self._ACTION_VERBS)) + r')\b',
            re.IGNORECASE,
        )

        verb_groups: dict[str, list[dict]] = {}
        for row in rows:
            label = row["label"] if "label" in row.keys() else row[1]
            nid = row["id"] if "id" in row.keys() else row[0]
            created = row["created"] if "created" in row.keys() else row[3]

            match = verb_pattern.search(label)
            verb = match.group(1).lower() if match else None

            if verb:
                verb_groups.setdefault(verb, []).append({
                    "id": nid,
                    "label": label,
                    "created": created,
                })

        # Build candidates for verbs meeting threshold
        candidates = []
        for verb, sources in verb_groups.items():
            freq = len(sources)
            if freq < min_frequency:
                continue
            confidence = min(1.0, freq / 5.0)  # saturates at 5 occurrences
            candidates.append({
                "action": verb,
                "frequency": freq,
                "confidence": round(confidence, 3),
                "memory_ids": [s["id"] for s in sources],
                "suggested_compression": (
                    f"'{verb}' repeated {freq}\u00d7 "
                    f"across {freq} episodic memories \u2014 "
                    f"promote to skill?"
                ),
            })

        # Sort by confidence descending, then frequency
        candidates.sort(key=lambda c: (-c["confidence"], -c["frequency"]))
        return candidates

    def auto_compress_skills(self, *,                          # noqa: C901
                             min_frequency: int = 2,
                             min_confidence: float = 0.4,
                             max_skills: int = 5,
                             dry_run: bool = False) -> dict:
        """Auto-promote detected skill candidates into procedural skills.

        The **act** half of the detect→compress skill loop,
        mirroring ``auto_heal_gaps()`` for gaps and ``auto_consolidate()``
        for redundancy.

        While ``detect_skill_candidates`` *identifies* recurring action
        patterns, this API *acts* on them by calling ``compress_to_skill()``
        for each qualifying candidate.

        **Compression strategy:**

        1. Run ``detect_skill_candidates`` with the given ``min_frequency``.
        2. Filter candidates by ``min_confidence``.
        3. For each candidate (up to ``max_skills``), call
           ``compress_to_skill()`` on the candidate's memory IDs.
        4. Skip candidates whose memory IDs are already linked to
           an existing skill node (avoids double-compression).

        **Non-mutating when** ``dry_run=True``:
        All actions are simulated; no nodes are created.

        Args:
            min_frequency: Minimum pattern occurrences to qualify.
            min_confidence: Minimum candidate confidence [0–1].
            max_skills: Maximum number of skills to create.
            dry_run: If True, report what *would* be done.

        Returns:
            Dict with:

            - **skills_created**: List of ``{name, action, frequency,
              confidence, source_count, skill_id}``
            - **total_created**: Count of skills created
            - **candidates_found**: Total candidates from detection
            - **skipped**: Candidates skipped (below threshold or
              already compressed)
            - **actions**: Human-readable summary strings
            - **dry_run**: Whether this was a dry run
        """
        report = self.detect_skill_candidates(
            min_frequency=min_frequency,
        )

        skills_created = []
        actions = []
        skipped = []
        created_count = 0

        # Track memory IDs already compressed in this run
        consumed_ids: set[str] = set()

        for cand in report:
            if created_count >= max_skills:
                break

            if cand["confidence"] < min_confidence:
                skipped.append({
                    "action": cand["action"],
                    "reason": (
                        f"confidence {cand['confidence']:.3f} "
                        f"< {min_confidence}"
                    ),
                })
                continue

            mem_ids = cand["memory_ids"]

            # Skip if all source IDs were already consumed in this run
            # or already linked to an existing skill via 'abstracts' edge
            already_skilled = set()
            for mid in mem_ids:
                if mid in consumed_ids:
                    already_skilled.add(mid)
                    continue
                # Check if this memory is already abstracted by a skill
                for edge in self.edges_of(mid):
                    if edge.relation == "abstracts":
                        already_skilled.add(mid)
                        break

            if all(mid in already_skilled for mid in mem_ids):
                skipped.append({
                    "action": cand["action"],
                    "reason": "all source memories already compressed",
                })
                continue

            # Filter out already-consumed or already-skilled IDs
            available_ids = [
                mid for mid in mem_ids
                if mid not in consumed_ids and mid not in already_skilled
            ]

            if not available_ids:
                skipped.append({
                    "action": cand["action"],
                    "reason": "no new source memories available",
                })
                continue

            skill_name = f"auto: {cand['action']}"

            if dry_run:
                skills_created.append({
                    "name": skill_name,
                    "action": cand["action"],
                    "frequency": cand["frequency"],
                    "confidence": cand["confidence"],
                    "source_count": len(available_ids),
                    "skill_id": None,
                })
                actions.append(
                    f"[dry-run] Would create skill '{skill_name}' "
                    f"from {len(available_ids)} episodes "
                    f"(confidence={cand['confidence']:.3f})"
                )
            else:
                skill = self.compress_to_skill(
                    available_ids,
                    skill_name,
                    description=cand["suggested_compression"],
                    confidence=cand["confidence"],
                )
                if skill is not None:
                    skills_created.append({
                        "name": skill_name,
                        "action": cand["action"],
                        "frequency": cand["frequency"],
                        "confidence": cand["confidence"],
                        "source_count": len(available_ids),
                        "skill_id": skill.id,
                    })
                    actions.append(
                        f"Created skill '{skill_name}' "
                        f"from {len(available_ids)} episodes "
                        f"(confidence={cand['confidence']:.3f})"
                    )
                else:
                    skipped.append({
                        "action": cand["action"],
                        "reason": "compress_to_skill returned None",
                    })
                    continue

            # Mark source IDs as consumed
            consumed_ids.update(available_ids)
            created_count += 1

        return {
            "skills_created": skills_created,
            "total_created": created_count,
            "candidates_found": len(report),
            "skipped": skipped,
            "actions": actions,
            "dry_run": dry_run,
        }

    # ── Skill Bank Governance (SkeMex / MUSE inspired) ───────────

    def govern_skill_bank(
        self,
        *,
        max_skills: int = 100,
        min_confidence: float = 0.2,
        deprecate_after_days: float = 60,
        merge_redundancy_threshold: float = 0.7,
        dry_run: bool = False,
    ) -> dict:
        """Enforce governance policies on the procedural skill bank.

        SkeMex (arXiv:2606.09365) Read-Write-Assess-**Govern** lifecycle:
        this method is the *Govern* step. It applies configurable policies
        to keep the skill bank healthy and bounded.

        Policies enforced (in order):

        1. **Deprecate stale skills** — Skills not evolved within
           ``deprecate_after_days`` get tagged 'deprecated'.
        2. **Deprecate low-confidence** — Skills with confidence <
           ``min_confidence`` get tagged 'deprecated'.
        3. **Merge redundant pairs** — Skills with step overlap ≥
           ``merge_redundancy_threshold`` are merged via
           ``skill_compose()``.
        4. **Prune overflow** — If total skills > ``max_skills``, oldest
           deprecated skills are deleted (``strategic_forget()``).

        Args:
            max_skills:               Maximum active skills to retain.
            min_confidence:           Confidence floor; below = deprecated.
            deprecate_after_days:     Staleness threshold in days.
            merge_redundancy_threshold: Jaccard overlap to trigger merge.
            dry_run:                  If True, report actions without
                                      making changes.

        Returns:
            ``{policies, actions, summary}`` where *actions* is a list
            of ``{action, skill_id, reason}`` dicts.
        """
        import time as _time

        policies = {
            "max_skills": max_skills,
            "min_confidence": min_confidence,
            "deprecate_after_days": deprecate_after_days,
            "merge_redundancy_threshold": merge_redundancy_threshold,
            "dry_run": dry_run,
        }

        actions = []
        now = _time.time()

        rows = self.conn.execute(
            "SELECT id, label, data, tags, created, accessed, weight "
            "FROM nodes WHERE kind='skill'"
        ).fetchall()

        if not rows:
            return {
                "policies": policies,
                "actions": [],
                "summary": {"total_examined": 0, "deprecated": 0,
                             "merged": 0, "pruned": 0},
            }

        # Parse all skills
        skills = []
        for row in rows:
            d = row["data"]
            if isinstance(d, str):
                try:
                    d = json.loads(d)
                except Exception:
                    d = {}
            if not isinstance(d, dict):
                d = {}
            tags = row["tags"]
            if isinstance(tags, str):
                try:
                    tags = json.loads(tags)
                except Exception:
                    tags = []
            skills.append({
                "id": row["id"],
                "label": row["label"],
                "data": d,
                "tags": tags or [],
                "created": row["created"],
                "accessed": row["accessed"],
                "weight": row["weight"],
                "confidence": d.get("confidence", 0.5),
                "steps": d.get("steps", []),
                "last_evolved_at": d.get("last_evolved_at", row["created"]),
            })

        total_examined = len(skills)
        deprecated_count = 0
        merged_count = 0
        pruned_count = 0

        # 1. Deprecate stale skills
        for s in skills:
            age_days = (now - s["last_evolved_at"]) / 86400
            if age_days > deprecate_after_days and "deprecated" not in s["tags"]:
                actions.append({
                    "action": "deprecate_stale",
                    "skill_id": s["id"],
                    "label": s["label"],
                    "reason": f"not evolved in {age_days:.0f} days",
                })
                if not dry_run:
                    new_tags = s["tags"] + ["deprecated"]
                    self.conn.execute(
                        "UPDATE nodes SET tags=? WHERE id=?",
                        (json.dumps(new_tags), s["id"]),
                    )
                deprecated_count += 1

        # 2. Deprecate low-confidence skills
        for s in skills:
            if s["confidence"] < min_confidence and "deprecated" not in s["tags"]:
                # Skip if already deprecated by staleness
                already = any(
                    a["skill_id"] == s["id"] and a["action"] == "deprecate_stale"
                    for a in actions
                )
                if already:
                    continue
                actions.append({
                    "action": "deprecate_low_confidence",
                    "skill_id": s["id"],
                    "label": s["label"],
                    "reason": f"confidence={s['confidence']:.2f} < {min_confidence}",
                })
                if not dry_run:
                    new_tags = s["tags"] + ["deprecated"]
                    self.conn.execute(
                        "UPDATE nodes SET tags=? WHERE id=?",
                        (json.dumps(new_tags), s["id"]),
                    )
                deprecated_count += 1

        # 3. Merge redundant pairs
        step_sets = {s["id"]: set(s["steps"]) for s in skills if s["steps"]}
        merged_ids = set()
        for i, s1 in enumerate(skills):
            if s1["id"] in merged_ids:
                continue
            set1 = step_sets.get(s1["id"], set())
            if not set1:
                continue
            for s2 in skills[i + 1:]:
                if s2["id"] in merged_ids:
                    continue
                set2 = step_sets.get(s2["id"], set())
                if not set2:
                    continue
                union = set1 | set2
                if union:
                    jaccard = len(set1 & set2) / len(union)
                    if jaccard >= merge_redundancy_threshold:
                        actions.append({
                            "action": "merge_redundant",
                            "skill_id": s1["id"],
                            "label": s1["label"],
                            "reason": (
                                f"{jaccard:.0%} overlap with "
                                f"'{s2['label']}' ({s2['id']})"
                            ),
                        })
                        if not dry_run:
                            try:
                                self.skill_compose(
                                    [s1["id"], s2["id"]],
                                    f"Merged: {s1['label']} + {s2['label']}",
                                    description=(
                                        f"Auto-merged by govern_skill_bank() "
                                        f"(Jaccard={jaccard:.2f})"
                                    ),
                                )
                                merged_ids.add(s2["id"])
                            except Exception:
                                pass
                        merged_count += 1

        # 4. Prune overflow
        active_skills = [
            s for s in skills
            if "deprecated" not in s["tags"] or True  # count all for pruning
        ]
        if len(active_skills) > max_skills:
            # Sort deprecated + oldest first for pruning
            deprecated_skills = [
                s for s in active_skills if "deprecated" in s["tags"]
            ]
            deprecated_skills.sort(key=lambda s: s["accessed"])
            to_prune = len(active_skills) - max_skills
            for s in deprecated_skills[:to_prune]:
                actions.append({
                    "action": "prune_overflow",
                    "skill_id": s["id"],
                    "label": s["label"],
                    "reason": f"bank overflow ({len(active_skills)} > {max_skills})",
                })
                if not dry_run:
                    try:
                        self.strategic_forget(s["id"])
                    except Exception:
                        self.delete(s["id"])
                pruned_count += 1

        if not dry_run:
            self.conn.commit()

        return {
            "policies": policies,
            "actions": actions,
            "summary": {
                "total_examined": total_examined,
                "deprecated": deprecated_count,
                "merged": merged_count,
                "pruned": pruned_count,
            },
        }

    # ── Memory Information Density (PRISM / PlugMem inspired) ──────

    def memory_information_density(self, *, node_id: str = None,
                                   kind: str = None,
                                   top_k: int = 20) -> dict | list[dict]:
        """Compute information density metrics for memory nodes.

        Inspired by:
            - PRISM (arXiv:2607): accuracy–context–cost Pareto frontier
            - PlugMem (ICML 2026): Memory Information Density (PMI/token)

        Density is defined as the ratio of **useful semantic content** to
        **storage cost** (in characters), giving a per-node score.

        For each node, density = (unique_terms / char_count) × q_value_weight,
        where:
            - unique_terms = number of distinct non-trivial words in label + data
            - char_count = total characters of serialised label + data JSON
            - q_value_weight = 0.5 + q_value (range [0.5, 1.5])

        A higher score means more information per token — the node is
        information-dense.

        Args:
            node_id: Score a single node. Returns a dict.
            kind: Filter by node kind.  Returns top-k densest.
            top_k: Limit when returning a ranked list.

        Returns:
            If *node_id* given: ``{id, label, kind, density, unique_terms,
            char_count, q_value, rank_percentile}``.

            Otherwise: list of dicts sorted by density descending, length ≤ top_k.
        """
        import math as _math

        if node_id is not None:
            row = self.conn.execute(
                "SELECT id, label, kind, data, weight FROM nodes WHERE id=?",
                (node_id,)
            ).fetchone()
            if not row:
                return {}
            return self._compute_density(row)

        # Bulk: optionally filter by kind
        if kind:
            rows = self.conn.execute(
                "SELECT id, label, kind, data, weight FROM nodes WHERE kind=? ORDER BY weight DESC",
                (kind,)
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT id, label, kind, data, weight FROM nodes ORDER BY weight DESC"
            ).fetchall()

        if not rows:
            return []

        scored = [self._compute_density(r) for r in rows]
        scored.sort(key=lambda x: x.get("density", 0), reverse=True)

        # Add rank percentile
        total = len(scored)
        for i, entry in enumerate(scored[:top_k]):
            entry["rank_percentile"] = round((total - i) / total * 100, 1)

        return scored[:top_k]

    def _compute_density(self, row) -> dict:
        """Compute information density for a single node row."""
        label = row["label"] or ""
        raw_data = row["data"]
        if isinstance(raw_data, str):
            try:
                data = json.loads(raw_data)
            except Exception:
                data = {}
        else:
            data = raw_data or {}

        # Flatten data into a text blob
        data_str = json.dumps(data, ensure_ascii=False, sort_keys=True)
        full_text = (label + " " + data_str).lower()

        # Unique non-trivial terms (len > 2 to skip stop-word-ish tokens)
        terms = set(
            w for w in full_text.replace("{", " ").replace("}", " ")
            .replace('"', " ").replace(":", " ").replace(",", " ")
            .replace("[", " ").replace("]", " ")
            .split()
            if len(w) > 2
        )
        unique_terms = len(terms)

        # Character cost
        char_count = len(label) + len(data_str)
        if char_count == 0:
            char_count = 1

        # Q-value weight
        try:
            qrow = self.conn.execute(
                "SELECT q_value FROM nodes WHERE id=?", (row["id"],)
            ).fetchone()
            q_val = qrow["q_value"] if qrow and qrow["q_value"] is not None else 0.5
        except Exception:
            q_val = 0.5

        q_weight = 0.5 + max(0.0, min(1.0, q_val))

        density = (unique_terms / char_count) * q_weight

        return {
            "id": row["id"],
            "label": label,
            "kind": row["kind"],
            "density": round(density, 6),
            "unique_terms": unique_terms,
            "char_count": char_count,
            "q_value": round(q_val, 4),
        }

    # ── Intent-Aware Edge Costing (PRISM-inspired) ────────────────

    # Intent type → edge-type discount/inflation map
    _INTENT_EDGE_AFFINITY: dict[str, dict[str, float]] = {
        "temporal": {
            "happened_before": 0.5, "happened_after": 0.5,
            "supersedes": 0.3, "causes": 0.4,
            "abstracts": 1.5, "similar_to": 1.5,
        },
        "causal": {
            "causes": 0.2, "prevents": 0.2, "enables": 0.3,
            "depends_on": 0.3, "conflicts_with": 0.4,
            "abstracts": 1.5, "similar_to": 1.2,
        },
        "multi_hop": {
            "similar_to": 0.4, "related_to": 0.5,
            "abstracts": 0.6, "works_on": 0.8,
            "causes": 0.7, "depends_on": 0.7,
        },
        "factual": {},  # no special weighting
    }

    _INTENT_KEYWORDS: dict[str, set[str]] = {
        "temporal": {"when", "before", "after", "timeline", "history",
                      "sequence", "order", "past", "future", "ago",
                      "\u4ec0\u4e48\u65f6\u5019", "\u4e4b\u524d", "\u4e4b\u540e", "\u65f6\u95f4\u7ebf"},
        "causal": {"why", "because", "cause", "effect", "reason",
                   "result", "consequence", "prevent", "enable",
                   "\u4e3a\u4ec0\u4e48", "\u539f\u56e0", "\u5bfc\u81f4", "\u7ed3\u679c"},
        "multi_hop": {"connect", "path", "link", "related",
                      "chain", "trace", "follow", "expand",
                      "\u5173\u8054", "\u94fe\u8def", "\u8ffd\u6eaf"},
    }

    def detect_query_intent(self, query: str) -> str:
        """Classify a query into an intent type for edge-aware retrieval.

        Inspired by PRISM (arXiv:2607): intent routing determines which
        edge types are prioritised during graph traversal.

        Types:
            - ``temporal`` — time/ordering queries
            - ``causal`` — why/cause/effect queries
            - ``multi_hop`` — connectivity/path queries
            - ``factual`` — default keyword lookup

        Args:
            query: Natural language query string.

        Returns:
            One of 'temporal', 'causal', 'multi_hop', 'factual'.
        """
        q_lower = query.lower()
        best_intent = "factual"
        best_score = 0

        for intent, keywords in self._INTENT_KEYWORDS.items():
            score = sum(1 for kw in keywords if kw in q_lower)
            if score > best_score:
                best_score = score
                best_intent = intent

        return best_intent

    def intent_aware_edge_cost(self, query: str, *, node_id: str = None,
                               ) -> list[dict] | dict:
        """Compute intent-adjusted edge costs for graph traversal.

        PRISM-inspired: different query intents should traverse
        different edge types with different costs.

        - **temporal** queries: discount temporal edges (supersedes, causes)
        - **causal** queries: discount causal edges (causes, prevents, enables)
        - **multi_hop** queries: discount structural edges (similar_to, related_to)
        - **factual** queries: no discounting (uniform cost)

        Edge cost = 1.0 × affinity_multiplier, where lower = cheaper traversal.

        Args:
            query: Query string for intent detection.
            node_id: If given, only return edges from this node.
                     Otherwise returns all edges with adjusted costs.

        Returns:
            If node_id given: dict with ``{intent, edges: [...]}``.
            Otherwise: ``{intent, edge_count, edges: [...]}``.
        """
        intent = self.detect_query_intent(query)
        affinity = self._INTENT_EDGE_AFFINITY.get(intent, {})

        if node_id:
            rows = self.conn.execute(
                "SELECT source, target, relation, weight FROM edges WHERE source=? OR target=?",
                (node_id, node_id)
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT source, target, relation, weight FROM edges"
            ).fetchall()

        edges = []
        for row in rows:
            rel = row["relation"]
            base_cost = 1.0 / max(row["weight"], 0.01)
            multiplier = affinity.get(rel, 1.0)
            adjusted_cost = round(base_cost * multiplier, 4)
            edges.append({
                "source": row["source"],
                "target": row["target"],
                "relation": rel,
                "base_cost": round(base_cost, 4),
                "adjusted_cost": adjusted_cost,
                "multiplier": multiplier,
            })

        return {
            "intent": intent,
            "edge_count": len(edges),
            "edges": edges,
        }

    def retrieve_with_intent(self, query: str, *, limit: int = 10,
                             ) -> dict:
        """Intent-routed retrieval combining intent detection with pipeline.

        Thin integration layer that:
        1. Detects query intent (temporal/causal/multi_hop/factual)
        2. Runs the standard ``retrieve()`` pipeline
        3. Applies intent-aware edge-cost reranking as a tiebreaker

        Returns a dict with both the results and the intent metadata,
        so callers can understand *why* certain results were surfaced.

        Args:
            query:  Natural language query.
            limit:  Max results.

        Returns:
            ``{intent, results: [...], edge_adjustments: {...}}``
        """
        intent = self.detect_query_intent(query)

        # Standard retrieval pipeline
        raw_results = self.retrieve(query, limit=limit * 2, rerank=True)

        if not raw_results:
            return {
                "intent": intent,
                "results": [],
                "edge_adjustments": {},
            }

        # Get intent-aware edge costs for the result nodes
        affinity = self._INTENT_EDGE_AFFINITY.get(intent, {})

        # Rerank results using edge-cost information
        # For each result, find its incoming edges and compute an
        # intent bonus (lower avg edge cost = more relevant)
        reranked = []
        for r in raw_results:
            nid = r.get("node_id", r.get("id"))
            if not nid:
                reranked.append(r)
                continue

            # Get edges connected to this node
            edges = self.conn.execute(
                "SELECT relation, weight FROM edges WHERE source=? OR target=?",
                (nid, nid)
            ).fetchall()

            if edges and affinity:
                # Average multiplier on connected edges
                multipliers = []
                for e in edges:
                    m = affinity.get(e["relation"], 1.0)
                    multipliers.append(m)
                avg_mult = sum(multipliers) / len(multipliers)
                # Lower multiplier = more relevant for this intent
                intent_bonus = max(0.0, 1.0 - avg_mult)  # 0 to 0.5ish
            else:
                intent_bonus = 0.0

            # Blend original score with intent bonus
            base_score = r.get("score", 0.5)
            final_score = base_score * (1.0 + intent_bonus)

            r_copy = dict(r)
            r_copy["intent_bonus"] = round(intent_bonus, 4)
            r_copy["score"] = round(final_score, 6)
            reranked.append(r_copy)

        # Re-sort by blended score
        reranked.sort(key=lambda x: x.get("score", 0), reverse=True)

        return {
            "intent": intent,
            "results": reranked[:limit],
            "edge_adjustments": affinity,
        }

    # ── Hippocampus-inspired Dual-Mode Binary Signature ────────────
    #
    # SimHash binary signatures enable O(1) Hamming-distance similarity
    # pre-filtering before expensive graph traversal.
    #
    # Reference: Hippocampus (arXiv:2602.13594) — 31× faster retrieval,
    # 14× fewer tokens via Dynamic Wavelet Matrix compression.
    #
    # Pipeline:  binary pre-filter  →  graph rerank  →  combined score

    @staticmethod
    def _simhash(text: str, bits: int = 64) -> str:
        """Compute SimHash of *text* as a bit string.

        Uses token-level hashing with weighted summation across
        a *bits*-dimensional vector, then median threshold.
        """
        import hashlib as _hl
        import collections as _c

        tokens = [t for t in text.lower().split() if len(t) > 1]
        if not tokens:
            return "0" * bits

        vec = [0] * bits
        counts = _c.Counter(tokens)

        for token, weight in counts.items():
            # Stable 32-bit hash of token
            h = int(_hl.md5(token.encode()).hexdigest(), 16)
            for i in range(bits):
                if h & (1 << i % 32):
                    vec[i] += weight
                else:
                    vec[i] -= weight

        # Threshold at zero → binary signature
        return "".join("1" if v > 0 else "0" for v in vec)

    @staticmethod
    def hamming_distance(sig_a: str, sig_b: str) -> int:
        """Count differing bits between two binary signatures.

        Raises:
            ValueError: If signatures have different lengths.
        """
        if len(sig_a) != len(sig_b):
            raise ValueError(
                f"Signature length mismatch: {len(sig_a)} vs {len(sig_b)}"
            )
        return sum(1 for a, b in zip(sig_a, sig_b) if a != b)

    def _node_text(self, node_id: str) -> str:
        """Concatenate label + flattened data for signature computation."""
        row = self.conn.execute(
            "SELECT label, data FROM nodes WHERE id=?", (node_id,)
        ).fetchone()
        if not row:
            raise KeyError(node_id)

        parts = [row["label"] or ""]
        raw = row["data"]
        if isinstance(raw, dict):
            d = raw
        elif isinstance(raw, str):
            try:
                parsed = json.loads(raw)
                d = parsed if isinstance(parsed, dict) else {}
            except Exception:
                d = {}
        else:
            d = {}

        for k, v in d.items():
            parts.append(str(k))
            parts.append(str(v))
        return " ".join(parts)

    def binary_signature(self, node_id: str, *, bits: int = 64) -> str:
        """Compute the SimHash binary signature of a node.

        Produces a deterministic *bits*-width bit string from the
        node's label and data payload.  Two nodes with identical
        content yield identical signatures; semantically similar
        nodes yield few differing bits.

        Args:
            node_id: Target node.
            bits:   Signature width (default 64).

        Returns:
            Bit string of length *bits*.

        Raises:
            KeyError: If *node_id* is not found.
        """
        text = self._node_text(node_id)
        return self._simhash(text, bits=bits)

    def similarity_search_binary(self, query: str, *, limit: int = 10,
                                 max_hamming: int = None,
                                 kind: str = None) -> list[dict]:
        """Fast binary-signature similarity search.

        Computes the SimHash of *query* and scans all nodes by
        Hamming distance — O(N) but with a tiny constant (~1 cmp/ns).

        This is the pre-filter stage of :meth:`dual_mode_retrieve`.

        Args:
            query:       Natural-language query.
            limit:       Max results.
            max_hamming: Optional distance cutoff (e.g. 20 means
                         only nodes within 20 bits are returned).
            kind:        Optional node-kind filter.

        Returns:
            List of ``{node_id, label, kind, hamming_distance}``
            sorted by ascending Hamming distance.
        """
        query_sig = self._simhash(query, bits=64)

        if kind:
            rows = self.conn.execute(
                "SELECT id, label, kind FROM nodes WHERE kind=?",
                (kind,)
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT id, label, kind FROM nodes"
            ).fetchall()

        if not rows:
            return []

        scored = []
        for row in rows:
            node_sig = self.binary_signature(row["id"])
            dist = self.hamming_distance(query_sig, node_sig)
            if max_hamming is not None and dist > max_hamming:
                continue
            scored.append({
                "node_id": row["id"],
                "label": row["label"],
                "kind": row["kind"],
                "hamming_distance": dist,
            })

        scored.sort(key=lambda x: x["hamming_distance"])
        return scored[:limit]

    def dual_mode_retrieve(self, query: str, *, limit: int = 10,
                           ) -> dict:
        """Dual-mode retrieval: binary pre-filter → graph rerank.

        Combines the speed of SimHash similarity with the structural
        awareness of graph-based retrieval.

        **Phase 1 — Binary:**  Compute SimHash of *query*, rank all
        nodes by Hamming distance, select top candidates.

        **Phase 2 — Graph:**  Run the standard :meth:`retrieve`
        pipeline on the candidate set, blending graph scores with
        binary similarity for a final ranking.

        For small graphs (< 10 nodes) the binary phase is skipped
        because brute-force retrieval is already fast enough.

        Args:
            query:  Natural-language query.
            limit:  Max final results.

        Returns:
            ``{candidates, results, binary_phase, graph_phase}``
        """
        node_count = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]

        if node_count < 10:
            # Small graph — skip binary phase
            raw = self.retrieve(query, limit=limit)
            return {
                "candidates": [],
                "results": raw if raw else [],
                "binary_phase": {"skipped": True, "reason": "small_graph"},
                "graph_phase": {"method": "direct_retrieve", "count": len(raw or [])},
            }

        # Phase 1: binary pre-filter
        # Select 3× limit candidates (with floor of 10)
        candidate_limit = max(limit * 3, 10)
        candidates = self.similarity_search_binary(query, limit=candidate_limit)
        candidate_ids = {c["node_id"] for c in candidates}
        candidate_map = {c["node_id"]: c["hamming_distance"] for c in candidates}

        # Phase 2: graph retrieval on candidates
        query_sig = self._simhash(query, bits=64)
        raw_results = self.retrieve(query, limit=limit * 2, rerank=True)

        if not raw_results:
            return {
                "candidates": candidates,
                "results": [],
                "binary_phase": {
                    "skipped": False,
                    "candidate_count": len(candidates),
                    "query_signature": query_sig,
                },
                "graph_phase": {"method": "retrieve_rerank", "count": 0},
            }

        max_bits = 64
        reranked = []
        for r in raw_results:
            nid = r.get("node_id", r.get("id", ""))
            ham = candidate_map.get(nid)
            if ham is None:
                # Node not in pre-filtered set — compute on the fly
                try:
                    node_sig = self.binary_signature(nid)
                    ham = self.hamming_distance(query_sig, node_sig)
                except (KeyError, Exception):
                    ham = max_bits  # worst case

            binary_sim = 1.0 - (ham / max_bits)  # 0..1
            graph_score = min(r.get("retrieval_score", r.get("score", 0.5)), 1.0)
            combined = round(binary_sim * 0.4 + graph_score * 0.6, 6)

            r_copy = dict(r)
            r_copy["hamming_distance"] = ham
            r_copy["binary_similarity"] = round(binary_sim, 4)
            r_copy["graph_score"] = round(graph_score, 4)
            r_copy["combined_score"] = combined
            # Ensure label is accessible
            if "label" not in r_copy:
                node_obj = r.get("node")
                if node_obj and hasattr(node_obj, "label"):
                    r_copy["label"] = node_obj.label
                else:
                    row = self.conn.execute(
                        "SELECT label FROM nodes WHERE id=?", (nid,)
                    ).fetchone()
                    r_copy["label"] = row["label"] if row else ""
            reranked.append(r_copy)

        reranked.sort(key=lambda x: x.get("combined_score", 0), reverse=True)

        return {
            "candidates": candidates,
            "results": reranked[:limit],
            "binary_phase": {
                "skipped": False,
                "candidate_count": len(candidates),
                "query_signature": query_sig,
            },
            "graph_phase": {
                "method": "retrieve_rerank",
                "count": len(reranked),
                "returned": min(len(reranked), limit),
            },
        }



    # ── Memory Deduplication (SimHash-based) ──────────────────────
    #
    # Near-duplicate detection using binary signatures from cycle 249.
    # Two nodes with Hamming distance ≤ threshold are considered duplicates.
    # Merge strategy: keep the node with higher weight, absorb edges and
    # data from the duplicate.
    #
    # Reference: Charikar (2002) SimHash + Manku et al. (2008) Hamming LSH.

    def find_duplicate_nodes(self, *, threshold: int = 3, bits: int = 64,
                             kind: str = None) -> list[dict]:
        """Detect near-duplicate nodes via SimHash Hamming distance.

        Computes a binary signature for every node (or all nodes of
        a given *kind*) and reports pairs whose Hamming distance is
        within *threshold*.

        Time complexity is O(N²) in the number of nodes, but with
        a tiny constant (~1 comparison per nanosecond).  For typical
        memory graphs (< 10 000 nodes) this completes in well under
        a second.

        Args:
            threshold: Max Hamming distance to consider duplicates.
                       Default 3 (≈95% bit overlap for 64-bit hashes).
            bits:      Signature width (should match binary_signature).
            kind:      Restrict scan to a single node kind.

        Returns:
            List of ``{node_a, node_b, label_a, label_b, kind,
            hamming_distance}`` sorted by ascending distance.
        """
        if kind:
            rows = self.conn.execute(
                "SELECT id, label, kind FROM nodes WHERE kind=?",
                (kind,)
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT id, label, kind FROM nodes"
            ).fetchall()

        if len(rows) < 2:
            return []

        # Pre-compute signatures
        sigs: list[tuple[str, str, str, str]] = []  # (id, sig, label, kind)
        for row in rows:
            try:
                sig = self.binary_signature(row["id"], bits=bits)
                sigs.append((row["id"], sig, row["label"], row["kind"]))
            except (KeyError, Exception):
                continue

        duplicates: list[dict] = []
        n = len(sigs)
        for i in range(n):
            for j in range(i + 1, n):
                dist = self.hamming_distance(sigs[i][1], sigs[j][1])
                if dist <= threshold:
                    duplicates.append({
                        "node_a": sigs[i][0],
                        "node_b": sigs[j][0],
                        "label_a": sigs[i][2],
                        "label_b": sigs[j][2],
                        "kind": sigs[i][3],
                        "hamming_distance": dist,
                    })

        duplicates.sort(key=lambda x: x["hamming_distance"])
        return duplicates

    def deduplicate(self, *, threshold: int = 3, dry_run: bool = True,
                    kind: str = None) -> dict:
        """Detect and optionally merge near-duplicate nodes.

        Uses :meth:`find_duplicate_nodes` to identify pairs, then
        (unless *dry_run*) merges the lower-weight node into the
        higher-weight one using :meth:`merge_nodes`.

        When multiple duplicates form a cluster (A≈B, B≈C), they are
        processed in ascending Hamming order so the closest pair is
        merged first; subsequent pairs involving a merged-away node
        are skipped.

        Args:
            threshold: Max Hamming distance for duplicate detection.
            dry_run:   If True (default), only report — do not merge.
            kind:      Restrict to a single node kind.

        Returns:
            ``{duplicates_found, merges_executed, merged_pairs,
            skipped, savings}``

            *savings* is an estimate of storage saved (bytes freed).
        """
        dupes = self.find_duplicate_nodes(
            threshold=threshold, kind=kind
        )

        if dry_run or not dupes:
            return {
                "duplicates_found": len(dupes),
                "merges_executed": 0,
                "merged_pairs": [],
                "skipped": 0,
                "savings": 0,
                "dry_run": dry_run,
            }

        # Track which nodes have been merged away
        merged_away: set[str] = set()
        merges: list[dict] = []
        skipped = 0

        for pair in dupes:
            a, b = pair["node_a"], pair["node_b"]
            if a in merged_away or b in merged_away:
                skipped += 1
                continue

            # Decide which to keep (higher weight wins)
            wa = self.conn.execute(
                "SELECT weight FROM nodes WHERE id=?", (a,)
            ).fetchone()
            wb = self.conn.execute(
                "SELECT weight FROM nodes WHERE id=?", (b,)
            ).fetchone()

            if not wa or not wb:
                skipped += 1
                continue

            if wa["weight"] >= wb["weight"]:
                keep_id, merge_id = a, b
            else:
                keep_id, merge_id = b, a

            # Estimate savings (label + data size)
            merge_row = self.conn.execute(
                "SELECT label, data FROM nodes WHERE id=?", (merge_id,)
            ).fetchone()
            est_savings = len(merge_row["label"] or "") + len(merge_row["data"] or "")

            result = self.merge_nodes(merge_id, keep_id)
            if result is not None:
                merged_away.add(merge_id)
                merges.append({
                    "kept": keep_id,
                    "merged": merge_id,
                    "label_kept": pair["label_a"] if keep_id == a else pair["label_b"],
                    "label_merged": pair["label_b"] if keep_id == a else pair["label_a"],
                    "hamming_distance": pair["hamming_distance"],
                })
            else:
                skipped += 1

        total_savings = sum(
            len(str(m.get("label_merged", ""))) + 60  # rough per-node overhead
            for m in merges
        )

        return {
            "duplicates_found": len(dupes),
            "merges_executed": len(merges),
            "merged_pairs": merges,
            "skipped": skipped,
            "savings": total_savings,
            "dry_run": False,
        }


    # ----------------------------------------------------------------
    # Write Governance Check (PASB-inspired, arXiv:2607.10526)
    # ----------------------------------------------------------------

    _GOVERNANCE_HEDGES = frozenset({
        'maybe', 'might', 'could', 'perhaps', 'possibly', 'seems',
        'apparently', 'supposedly', 'allegedly', 'presumably',
        'likely', 'probably', 'roughly', 'approximately',
        'suggests', 'appears', 'uncertain', 'unclear', 'unconfirmed',
        'tentative', 'hypothetical', 'speculative', 'draft',
        'estimate', 'estimated', 'estimated to be', 'believed',
        'thought to be', 'said to be', 'reportedly',
    })

    _GOVERNANCE_CERTAINTY = frozenset({
        'is', 'are', 'definitely', 'absolutely', 'certainly',
        'undoubtedly', 'confirmed', 'verified', 'proven',
        'established', 'guaranteed', 'always', 'never',
        'all', 'every', 'none', 'must', 'cannot',
        'will', 'shall', 'undeniably', 'incontestably',
        'unquestionably', 'irrefutably', 'positively',
    })

    _GOVERNANCE_BROADENERS = frozenset({
        'all', 'every', 'always', 'never', 'everyone',
        'everything', 'nobody', 'nothing', 'anywhere',
        'everywhere', 'all types', 'all kinds', 'all forms',
        'universally', 'exclusively', 'only', 'solely',
    })

    _ATTRIBUTION_KEYS = frozenset({
        'source', 'according_to', 'cited_from', 'reference',
        'reported_by', 'verified_by', 'evidence', 'provenance',
        'citation', 'attributed_to', 'source_type',
        'confidence_level', 'reliability', 'verbatim',
    })

    def _tokenize_gov(self, text: str) -> list[str]:
        """Lower-case word tokens for governance analysis."""
        import re
        return re.findall(r"[a-z']+", text.lower())

    def _detect_status_promotion(self, old_label: str, new_label: str) -> dict:
        """Detect certainty escalation from hedged to definitive.

        PASB failure mode #1: *status promotion* transforms a tentative
        statement into an asserted fact, e.g.
        ``"user might like Italian"`` → ``"user likes Italian"``.
        """
        old_tokens = set(self._tokenize_gov(old_label))
        new_tokens = set(self._tokenize_gov(new_label))

        old_hedges = old_tokens & self._GOVERNANCE_HEDGES
        new_hedges = new_tokens & self._GOVERNANCE_HEDGES
        old_cert = old_tokens & self._GOVERNANCE_CERTAINTY
        new_cert = new_tokens & self._GOVERNANCE_CERTAINTY

        hedge_removed = bool(old_hedges and not new_hedges)
        certainty_added = bool(new_cert and not old_cert)

        score = 0.0
        if hedge_removed:
            score += 0.35
        if certainty_added:
            score += 0.35
        # Extra signal: hedge count drops further
        if len(old_hedges) > len(new_hedges):
            score += 0.1 * (len(old_hedges) - len(new_hedges))

        score = min(1.0, score)
        triggered = score >= 0.3

        return {
            "type": "status_promotion",
            "triggered": triggered,
            "score": round(score, 3),
            "old_hedges": sorted(old_hedges),
            "new_hedges": sorted(new_hedges),
            "old_certainty": sorted(old_cert),
            "new_certainty": sorted(new_cert),
            "detail": (
                f"Hedged→definitive: removed {sorted(old_hedges - new_hedges)}, "
                f"added certainty {sorted(new_cert - old_cert)}"
                if triggered else "No significant certainty escalation"
            ),
        }

    def _detect_attribution_removal(self, old_data: dict,
                                    new_data: dict) -> dict:
        """Detect removal of source / provenance / evidence.

        PASB failure mode #2: *attribution removal* strips source
        qualifiers, e.g. ``{source: "survey"}`` → ``{}``.
        """
        old_keys = set((old_data or {}).keys())
        new_keys = set((new_data or {}).keys())

        old_attribution = old_keys & self._ATTRIBUTION_KEYS
        new_attribution = new_keys & self._ATTRIBUTION_KEYS
        removed = old_attribution - new_attribution

        # Also detect confidence level drop
        old_conf = (old_data or {}).get('confidence_level')
        new_conf = (new_data or {}).get('confidence_level')
        conf_dropped = False
        if old_conf and new_conf and new_conf > old_conf:
            conf_dropped = True
        elif old_conf and not new_conf:
            conf_dropped = True

        score = 0.0
        if removed:
            score += 0.4 * len(removed)
        if conf_dropped:
            score += 0.3

        score = min(1.0, score)
        triggered = score >= 0.3

        return {
            "type": "attribution_removal",
            "triggered": triggered,
            "score": round(score, 3),
            "removed_keys": sorted(removed),
            "confidence_dropped": conf_dropped,
            "detail": (
                f"Removed attribution keys: {sorted(removed)}"
                if removed else
                ("Confidence level inflated or removed"
                 if conf_dropped else "No attribution removal detected")
            ),
        }

    def _detect_scope_broadening(self, old_label: str,
                                 new_label: str) -> dict:
        """Detect over-generalisation from specific to universal.

        PASB failure mode #3: *scope broadening* generalises a
        qualified statement, e.g. ``"likes restaurant A"`` →
        ``"likes all restaurants"``.
        """
        old_tokens = set(self._tokenize_gov(old_label))
        new_tokens = set(self._tokenize_gov(new_label))

        old_broad = old_tokens & self._GOVERNANCE_BROADENERS
        new_broad = new_tokens & self._GOVERNANCE_BROADENERS
        added = new_broad - old_broad

        # Detect universal quantifier insertion
        score = 0.0
        if added:
            score += 0.5 * len(added)

        # Detect removal of qualifiers / specific identifiers
        old_specific = old_tokens - new_tokens - self._GOVERNANCE_BROADENERS
        if old_specific and added:
            score += 0.2

        score = min(1.0, score)
        triggered = score >= 0.3

        return {
            "type": "scope_broadening",
            "triggered": triggered,
            "score": round(score, 3),
            "added_broadeners": sorted(added),
            "removed_specifics": sorted(old_specific)[:10],
            "detail": (
                f"Added universal quantifiers: {sorted(added)}"
                if triggered else "No scope broadening detected"
            ),
        }

    def write_governance_check(self, node_id: str, *,
                               new_label: str = None,
                               new_data: dict = None) -> dict:
        """Check a proposed write for sycophantic content modification.

        Inspired by PASB (arXiv:2607.10526): *Persistent Agent
        Sycophancy at Commit Boundaries*. Agents exhibit three failure
        modes when persisting memory across session boundaries:

        1. **Status promotion** — hedged claim → definitive assertion.
        2. **Attribution removal** — source/evidence qualifiers stripped.
        3. **Scope broadening** — specific claim → universal generalisation.

        This method compares an existing node's content with proposed
        new content and flags any of the three patterns.

        Args:
            node_id: ID of the node being modified.
            new_label: Proposed new label (``None`` = unchanged).
            new_data: Proposed new data dict (``None`` = unchanged).

        Returns:
            ``{node_id, verdict, overall_score, checks: [...], recommendation}``

            *verdict* is one of ``'safe'``, ``'flag'``, ``'reject'``.
            *recommendation* is a human-readable action string.
        """
        node = self.get_node(node_id)
        if not node:
            return {
                "node_id": node_id,
                "verdict": "error",
                "overall_score": 0.0,
                "checks": [],
                "recommendation": "Node not found",
            }

        old_label = node.label or ""
        old_data = node.data or {}
        check_label = new_label if new_label is not None else old_label
        check_data = new_data if new_data is not None else old_data

        checks = []
        checks.append(self._detect_status_promotion(old_label, check_label))
        checks.append(self._detect_attribution_removal(old_data, check_data))
        checks.append(self._detect_scope_broadening(old_label, check_label))

        triggered = [c for c in checks if c["triggered"]]
        overall = max((c["score"] for c in checks), default=0.0)

        if overall >= 0.6:
            verdict = "reject"
        elif triggered:
            verdict = "flag"
        else:
            verdict = "safe"

        if verdict == "reject":
            rec = ("Write rejected: high-risk sycophantic modification "
                   f"({len(triggered)} patterns detected). "
                   "Review before committing.")
        elif verdict == "flag":
            names = ", ".join(c["type"] for c in triggered)
            rec = (f"Write flagged: potential {names}. "
                   "Proceed with caution or revise content.")
        else:
            rec = "Write appears safe — no sycophantic patterns detected."

        return {
            "node_id": node_id,
            "verdict": verdict,
            "overall_score": round(overall, 3),
            "checks": checks,
            "recommendation": rec,
        }

    def safe_supersede(self, node_id: str, *,
                       new_label: str = None, new_kind: str = None,
                       new_data: dict = None) -> dict:
        """Supersede a node with write governance check.

        Runs :meth:`write_governance_check` first. If the verdict is
        ``'reject'``, the supersede is blocked and the original node
        is left untouched. If ``'flag'``, a warning is recorded but
        the supersede proceeds. If ``'safe'``, normal supersede.

        Args:
            node_id: ID of the node to supersede.
            new_label: New label (defaults to old).
            new_kind: New kind (defaults to old).
            new_data: New data (defaults to old).

        Returns:
            ``{governance, new_id}`` — *governance* is the check
            result, *new_id* is the new node ID or ``None`` if blocked.
        """
        gov = self.write_governance_check(
            node_id, new_label=new_label, new_data=new_data
        )

        if gov["verdict"] == "reject":
            return {"governance": gov, "new_id": None}

        new_id = self.supersede(
            node_id, new_label=new_label,
            new_kind=new_kind, new_data=new_data
        )
        return {"governance": gov, "new_id": new_id}

    def governance_audit(self, *, node_id: str = None,
                         limit: int = 100) -> dict:
        """Audit recent supersede operations for governance risk.

        Scans the supersede chain (old → new via ``superseded_by``
        edges) and runs governance checks on each transition.

        Args:
            node_id: If provided, audit only that node's chain.
                     If ``None``, sample up to *limit* recent superseded nodes.
            limit: Max chains to audit when *node_id* is ``None``.

        Returns:
            ``{total_chains, audited, safe, flagged, rejected, details}``
        """
        if node_id:
            chains = [(node_id,)]
        else:
            # Find nodes that were superseded (have outgoing superseded_by)
            rows = self.conn.execute(
                "SELECT source FROM edges WHERE relation='superseded_by' "
                "ORDER BY ROWID DESC LIMIT ?", (limit,)
            ).fetchall()
            chains = [(r["source"],) for r in rows]

        details = []
        safe = flagged = rejected = 0

        for (old_id,) in chains:
            # Find the new node via superseded_by edge
            edge = self.conn.execute(
                "SELECT target FROM edges WHERE source=? AND relation='superseded_by'",
                (old_id,)
            ).fetchone()
            if not edge:
                continue

            new_id = edge["target"]
            old_node = self.get_node(old_id)
            new_node = self.get_node(new_id)
            if not old_node or not new_node:
                continue

            gov = self.write_governance_check(
                old_id,
                new_label=new_node.label,
                new_data=new_node.data,
            )

            if gov["verdict"] == "safe":
                safe += 1
            elif gov["verdict"] == "flag":
                flagged += 1
            elif gov["verdict"] == "reject":
                rejected += 1

            details.append({
                "old_id": old_id,
                "old_label": old_node.label,
                "new_id": new_id,
                "new_label": new_node.label,
                "verdict": gov["verdict"],
                "score": gov["overall_score"],
            })

        return {
            "total_chains": len(chains),
            "audited": len(details),
            "safe": safe,
            "flagged": flagged,
            "rejected": rejected,
            "details": details,
        }


    # ----------------------------------------------------------------
    # Community Semantic Layer (GraphRAG-inspired)
    # ----------------------------------------------------------------

    def community_topic_labels(self, communities: dict[str, int] = None,
                               *, top_k: int = 5) -> dict[int, list[str]]:
        """Extract dominant topic labels for each community.

        Derives topics from three signals (in priority order):
        1. **Kind frequency** — the most common node kind.
        2. **Tag frequency** — aggregated tag counts.
        3. **Keyword extraction** — top TF words across member labels.

        Args:
            communities: ``{node_id: community_id}``. Auto-detects if None.
            top_k: Max topics per community.

        Returns:
            ``{community_id: ["topic1", "topic2", ...]}``
        """
        if communities is None:
            communities = self.detect_communities_leiden()
        if not communities:
            return {}

        # Group members
        members: dict[int, list[str]] = defaultdict(list)
        for nid, cid in communities.items():
            members[cid].append(nid)

        import re
        from collections import Counter

        result = {}
        for cid, node_ids in members.items():
            if not node_ids:
                continue
            placeholders = ",".join("?" * len(node_ids))
            rows = self.conn.execute(
                f"SELECT label, kind, tags FROM nodes WHERE id IN ({placeholders})",
                node_ids
            ).fetchall()

            # Kind frequency
            kind_counts = Counter(r["kind"] for r in rows)
            # Tag frequency
            tag_counts: Counter = Counter()
            for r in rows:
                for tag in json.loads(r["tags"] or "[]"):
                    tag_counts[tag] += 1

            # Keyword extraction from labels
            word_counts: Counter = Counter()
            stop = {"the", "a", "an", "is", "are", "was", "were",
                    "to", "of", "in", "for", "and", "or", "not",
                    "with", "by", "on", "at", "from", "as", "it",
                    "this", "that", "user", "data"}
            for r in rows:
                words = re.findall(r"[a-z]{2,}", (r["label"] or "").lower())
                for w in words:
                    if w not in stop:
                        word_counts[w] += 1

            topics: list[str] = []
            # Top kind
            if kind_counts:
                top_kind = kind_counts.most_common(1)[0][0]
                topics.append(f"{top_kind}s")
            # Top tags
            for tag, _ in tag_counts.most_common(2):
                if tag not in topics:
                    topics.append(tag)
            # Top keywords
            for word, _ in word_counts.most_common(3):
                if word not in topics and len(topics) < top_k:
                    topics.append(word)

            result[cid] = topics[:top_k]

        return result

    def community_semantic_summary(self, communities: dict[str, int] = None,
                                  *, summarizer=None) -> list[dict]:
        """Generate semantic summaries for each community.

        For each community, collects member labels and produces a
        concise summary. If *summarizer* (a callable
        ``str → str``) is provided, it is called with the concatenated
        labels; otherwise a deterministic extractive summary is used
        (top-weighted labels).

        Inspired by GraphRAG community summaries (Edge et al., 2024):
        communities are summarised independently, then summaries can
        be composed hierarchically for global queries.

        Args:
            communities: ``{node_id: community_id}``. Auto-detects if None.
            summarizer: Optional ``Callable[[str], str]`` for LLM-based summary.

        Returns:
            ``[{community_id, size, summary, top_labels, topics}]``
        """
        if communities is None:
            communities = self.detect_communities_leiden()
        if not communities:
            return []

        topics_map = self.community_topic_labels(communities)
        members: dict[int, list[str]] = defaultdict(list)
        for nid, cid in communities.items():
            members[cid].append(nid)

        results = []
        for cid, node_ids in members.items():
            if not node_ids:
                continue
            placeholders = ",".join("?" * len(node_ids))
            rows = self.conn.execute(
                f"SELECT id, label, weight FROM nodes WHERE id IN ({placeholders}) ORDER BY weight DESC",
                node_ids
            ).fetchall()

            labels = [r["label"] for r in rows if r["label"]]
            top_labels = labels[:10]

            if summarizer and labels:
                combined = "; ".join(labels[:50])
                try:
                    summary = summarizer(combined)
                except Exception:
                    summary = "; ".join(top_labels[:5])
            else:
                # Deterministic: top 5 labels by weight
                summary = "; ".join(top_labels[:5])

            results.append({
                "community_id": cid,
                "size": len(node_ids),
                "summary": summary,
                "top_labels": top_labels,
                "topics": topics_map.get(cid, []),
            })

        # Sort by size descending
        results.sort(key=lambda x: x["size"], reverse=True)
        return results

    def community_overview(self, communities: dict[str, int] = None,
                           *, summarizer=None) -> dict:
        """Generate a hierarchical overview of all communities.

        Combines structural stats (from ``community_summary``) with
        semantic summaries (from ``community_semantic_summary``) into
        a single dashboard-like report.

        Args:
            communities: ``{node_id: community_id}``. Auto-detects if None.
            summarizer: Optional LLM callback for richer summaries.

        Returns:
            ``{total_communities, total_nodes, largest_community,
            communities: [{id, size, summary, topics, density,
            avg_weight, top_members}]}``
        """
        if communities is None:
            communities = self.detect_communities_leiden()
        if not communities:
            return {
                "total_communities": 0,
                "total_nodes": 0,
                "largest_community": None,
                "communities": [],
            }

        structural = self.community_summary(communities={
            cid: nids for cid, nids in self._group_communities(communities).items()
        })
        semantic = self.community_semantic_summary(
            communities, summarizer=summarizer
        )

        # Index structural by community id
        struct_map = {s["id"]: s for s in structural}
        sem_map = {s["community_id"]: s for s in semantic}

        all_cids = sorted(set(struct_map) | set(sem_map),
                          key=lambda c: struct_map.get(c, {}).get("size", 0),
                          reverse=True)

        combined = []
        for cid in all_cids:
            s = struct_map.get(cid, {})
            sm = sem_map.get(cid, {})
            combined.append({
                "id": cid,
                "size": s.get("size", sm.get("size", 0)),
                "summary": sm.get("summary", ""),
                "topics": sm.get("topics", []),
                "density": s.get("density", 0.0),
                "avg_weight": s.get("avg_weight", 0.0),
                "top_members": s.get("top_members", []),
                "internal_edges": s.get("internal_edges", 0),
            })

        total_nodes = sum(c["size"] for c in combined)
        largest = combined[0]["id"] if combined else None

        return {
            "total_communities": len(combined),
            "total_nodes": total_nodes,
            "largest_community": largest,
            "communities": combined,
        }

    def _group_communities(self, communities: dict[str, int]) -> dict[int, list[str]]:
        """Convert {node_id: comm_id} → {comm_id: [node_ids]}."""
        groups: dict[int, list[str]] = defaultdict(list)
        for nid, cid in communities.items():
            groups[cid].append(nid)
        return dict(groups)

    def query_global(self, question: str, *, summarizer=None,
                     limit: int = 10) -> dict:
        """GraphRAG-style global query across community summaries.

        Instead of retrieving individual nodes, this method:
        1. Detects communities.
        2. Generates summaries for each.
        3. Scores each summary against the query (keyword overlap).
        4. Returns top matching communities + their member nodes.

        This is the GraphRAG *global* search mode, suitable for
        questions that span many nodes (e.g. "what are the main themes?").

        Args:
            question: Natural-language query.
            summarizer: Optional LLM callback for community summaries.
            limit: Max communities to return.

        Returns:
            ``{question, communities_matched, total_communities,
            results: [{community_id, score, summary, topics, members}]}``
        """
        communities = self.detect_communities_leiden()
        if not communities:
            return {
                "question": question,
                "communities_matched": 0,
                "total_communities": 0,
                "results": [],
            }

        summaries = self.community_semantic_summary(
            communities, summarizer=summarizer
        )

        import re
        query_words = set(re.findall(r"[a-z]{2,}", question.lower()))
        query_words -= {"the", "a", "an", "is", "are", "was", "were",
                        "to", "of", "in", "for", "and", "or", "not",
                        "with", "by", "on", "at", "from", "as", "it",
                        "this", "that", "what", "how", "why", "when"}

        scored = []
        for s in summaries:
            # Score by keyword overlap with summary + topics + labels
            summary_words = set(re.findall(
                r"[a-z]{2,}", s["summary"].lower()
            ))
            topic_words = set(
                w.lower() for t in s.get("topics", []) for w in t.split()
            )
            label_words = set(
                w.lower() for label in s.get("top_labels", [])
                for w in re.findall(r"[a-z]{2,}", label.lower())
            )

            all_words = summary_words | topic_words | label_words
            overlap = len(query_words & all_words)
            # Normalise by query length
            score = overlap / max(len(query_words), 1)

            scored.append((score, s))

        scored.sort(key=lambda x: x[0], reverse=True)
        top = scored[:limit]

        # Get member nodes for top communities
        members_map = self._group_communities(communities)

        results = []
        for score, s in top:
            cid = s["community_id"]
            member_ids = members_map.get(cid, [])
            member_nodes = []
            if member_ids:
                placeholders = ",".join("?" * len(member_ids))
                rows = self.conn.execute(
                    f"SELECT id, label, kind, weight FROM nodes WHERE id IN ({placeholders}) ORDER BY weight DESC LIMIT 10",
                    member_ids
                ).fetchall()
                member_nodes = [
                    {"id": r["id"], "label": r["label"],
                      "kind": r["kind"], "weight": r["weight"]}
                    for r in rows
                ]

            results.append({
                "community_id": cid,
                "score": round(score, 4),
                "summary": s["summary"],
                "topics": s.get("topics", []),
                "size": s["size"],
                "members": member_nodes,
            })

        return {
            "question": question,
            "communities_matched": len([r for r in results if r["score"] > 0]),
            "total_communities": len(summaries),
            "results": results,
        }

    # ----------------------------------------------------------------
    # Lifecycle Operation Evaluation (MemOps-inspired, arXiv:2607.12893)
    # ----------------------------------------------------------------

    def lifecycle_operation_eval(self, operations: list[dict],
                                  *, golden_set: dict = None) -> dict:
        """Evaluate memory lifecycle operations for integrity.

        MemOps (arXiv:2607.12893) defines 6 probe types that test
        whether memory operations maintain a consistent, safe state:

        1. **detection** — Can we find the target memory to operate on?
        2. **target** — Is the correct memory selected (not a distractor)?
        3. **transition** — Does the operation produce the expected state change?
        4. **robustness** — Does the operation handle edge cases gracefully?
        5. **provenance** — Is the operation history traceable?
        6. **leakage** — Does the operation affect unrelated memories?

        This method runs a sequence of operations and evaluates each
        across all 6 probes.

        Args:
            operations: List of operation dicts, each with:
                - ``op``: ``'add'|'update'|'supersede'|'forget'|'merge'``
                - ``args``: Arguments dict for the operation
                - ``expect``: Expected post-state (optional)
                - ``probe_overrides``: Per-probe expectations (optional)
            golden_set: Optional ``{node_id: expected_attrs}`` for
                        validating target correctness.

        Returns:
            ``{total_ops, probes_passed, probes_total, pass_rate,
            details: [{op_index, op_type, probes: {detection, target,
            transition, robustness, provenance, leakage}}]}``
        """
        results = []
        probes_passed = 0
        probes_total = 0

        for i, op_spec in enumerate(operations):
            op_type = op_spec.get("op", "")
            args = op_spec.get("args", {})
            expect = op_spec.get("expect", {})
            overrides = op_spec.get("probe_overrides", {})

            probe_results = {}

            # --- 1. Detection: can we find the target? ---
            target_id = args.get("node_id") or args.get("source_id")
            if op_type == "add":
                # Add always succeeds in detection (no target needed)
                probe_results["detection"] = {"pass": True, "detail": "N/A (add op)"}
            elif target_id:
                node = self.get_node(target_id)
                passed = node is not None
                probe_results["detection"] = {
                    "pass": passed,
                    "detail": f"Target {target_id} {'found' if passed else 'NOT found'}",
                }
            else:
                probe_results["detection"] = {
                    "pass": False, "detail": "No target_id specified",
                }

            # --- Execute operation ---
            op_result = self._execute_lifecycle_op(op_type, args)

            # --- 2. Target: correct memory selected? ---
            if golden_set and target_id:
                golden = golden_set.get(target_id, {})
                node = self.get_node(target_id) or self._get_deleted_node(target_id)
                if node:
                    matches = all(
                        getattr(node, k, None) == v
                        for k, v in golden.items()
                    )
                    probe_results["target"] = {
                        "pass": matches,
                        "detail": f"Golden attrs {'match' if matches else 'MISMATCH'}",
                    }
                else:
                    probe_results["target"] = {
                        "pass": False, "detail": "Node not found for golden check",
                    }
            elif op_type == "add":
                passed = op_result is not None
                probe_results["target"] = {
                    "pass": passed,
                    "detail": f"Add created node: {'yes' if passed else 'no'}",
                }
            else:
                probe_results["target"] = {
                    "pass": True, "detail": "No golden set provided",
                }

            # --- 3. Transition: expected state change? ---
            if expect:
                actual = self._check_post_state(op_type, args, op_result)
                expected_status = expect.get("status", True)
                passed = actual == expected_status
                probe_results["transition"] = {
                    "pass": passed,
                    "detail": f"Expected {expected_status}, got {actual}",
                }
            else:
                probe_results["transition"] = {
                    "pass": True, "detail": "No expectation specified",
                }

            # --- 4. Robustness: edge cases handled? ---
            robustness_passed = op_result is not None or op_type in ("update", "forget", "merge")
            if op_type == "supersede":
                # Supersede should produce a new ID
                robustness_passed = isinstance(op_result, str) and len(op_result) > 0
            elif op_type == "merge":
                robustness_passed = op_result is not None
            probe_results["robustness"] = {
                "pass": robustness_passed,
                "detail": f"Op returned {'valid' if robustness_passed else 'invalid'} result",
            }

            # --- 5. Provenance: operation traceable? ---
            provenance_passed = False
            if op_type == "supersede" and op_result:
                # Check superseded_by edge exists
                if target_id:
                    edge = self.conn.execute(
                        "SELECT 1 FROM edges WHERE source=? AND relation='superseded_by'",
                        (target_id,)
                    ).fetchone()
                    provenance_passed = edge is not None
            elif op_type == "add" and op_result:
                provenance_passed = True  # add is always in the log
            elif op_type in ("update", "forget", "merge"):
                provenance_passed = True  # these are logged via _tick
            else:
                provenance_passed = True
            probe_results["provenance"] = {
                "pass": provenance_passed,
                "detail": f"Traceability: {'verified' if provenance_passed else 'MISSING'}",
            }

            # --- 6. Leakage: unrelated memories unaffected? ---
            unrelated_ids = op_spec.get("unrelated_ids", [])
            if unrelated_ids:
                unaffected = True
                for uid in unrelated_ids:
                    node = self.get_node(uid)
                    if node is None:
                        unaffected = False
                        break
                probe_results["leakage"] = {
                    "pass": unaffected,
                    "detail": f"{len(unrelated_ids)} unrelated nodes {'unaffected' if unaffected else 'AFFECTED'}",
                }
            else:
                probe_results["leakage"] = {
                    "pass": True, "detail": "No unrelated IDs to check",
                }

            # Apply overrides
            for probe_name, override in overrides.items():
                if probe_name in probe_results:
                    probe_results[probe_name].update(override)

            # Count passes
            for probe in probe_results.values():
                probes_total += 1
                if probe["pass"]:
                    probes_passed += 1

            results.append({
                "op_index": i,
                "op_type": op_type,
                "probes": probe_results,
            })

        pass_rate = (probes_passed / probes_total) if probes_total > 0 else 0.0

        return {
            "total_ops": len(operations),
            "probes_passed": probes_passed,
            "probes_total": probes_total,
            "pass_rate": round(pass_rate, 4),
            "details": results,
        }

    def _execute_lifecycle_op(self, op_type: str, args: dict):
        """Execute a single lifecycle operation and return result."""
        try:
            if op_type == "add":
                return self.add(**args)
            elif op_type == "update":
                return self.update_node(**args)
            elif op_type == "supersede":
                return self.supersede(**args)
            elif op_type == "forget":
                return self.strategic_forget(**args)
            elif op_type == "merge":
                return self.merge_nodes(**args)
            else:
                return None
        except Exception:
            return None

    def _get_deleted_node(self, node_id: str):
        """Try to retrieve a node that may have been deleted/merged."""
        # Check immutable store
        try:
            entries = self._immutable_retrieve(node_id)
            if entries:
                return entries[0]
        except Exception:
            pass
        return None

    def _check_post_state(self, op_type: str, args: dict, result) -> bool:
        """Check if post-operation state matches expected."""
        if result is None:
            return False
        if op_type == "add":
            return hasattr(result, "id")
        if op_type == "update":
            return result is not None
        if op_type == "supersede":
            return isinstance(result, str) and len(result) > 0
        if op_type == "forget":
            return True  # strategic_forget returns None on success
        if op_type == "merge":
            return result is not None
        return False

    # ----------------------------------------------------------------
    # Prospective Memory (PM-Bench-inspired, arXiv:2607.12385)
    # ----------------------------------------------------------------

    def add_intention(self, label: str, *, trigger: str = None,
                      action: str = None, data: dict = None,
                      deadline: float = None,
                      priority: str = "normal") -> Node:
        """Add a prospective memory — a delayed intention to be executed
        when a trigger condition is met.

        PM-Bench (arXiv:2607.12385, COLM 2026) shows prospective memory
        is largely unsolved: GPT-5.4 achieves only 65.1% F1. This method
        stores intentions with trigger cues so they can be matched later.

        Args:
            label: Description of the intention.
            trigger: Natural-language cue description (when to fire).
            action: What to do when triggered.
            data: Optional metadata.
            deadline: Optional Unix timestamp for expiry.
            priority: ``'low'|'normal'|'high'``.

        Returns:
            The created intention node (kind=``'intention'``).
        """
        intention_data = data or {}
        if trigger:
            intention_data["trigger"] = trigger
        if action:
            intention_data["action"] = action
        if deadline:
            intention_data["deadline"] = deadline
        intention_data["priority"] = priority
        intention_data["status"] = "pending"

        return self.add(label, kind="intention", data=intention_data,
                         tags=["prospective"])

    def check_prospective_cues(self, context: str, *, now: float = None
                                ) -> list[dict]:
        """Check if any pending intentions should be triggered by *context*.

        Performs keyword-overlap matching between the context string
        and each pending intention's trigger description. Returns matched
        intentions sorted by match score.

        Also checks deadlines: expired intentions are marked as ``'missed'``.

        Args:
            context: Current context / user input to match against.
            now: Override current timestamp (for testing).

        Returns:
            List of ``{node_id, label, trigger, action, score, priority,
            deadline_status}`` for matched intentions.
        """
        import time as _time
        import re
        current_time = now or _time.time()

        # Get all pending intentions
        rows = self.conn.execute(
            "SELECT * FROM nodes WHERE kind='intention' "
            "AND json_extract(data, '$.status')='pending'"
        ).fetchall()

        if not rows:
            return []

        context_words = set(re.findall(r"[a-z]{2,}", context.lower()))
        context_stop = {"the", "a", "an", "is", "are", "to", "of",
                        "in", "for", "and", "or", "not", "with", "by",
                        "on", "at", "i", "you", "we", "it", "this",
                        "that", "my", "your", "me"}
        context_words -= context_stop

        results = []
        for row in rows:
            data = json.loads(row["data"])
            trigger = data.get("trigger", "")
            trigger_words = set(re.findall(r"[a-z]{2,}", trigger.lower()))
            trigger_words -= context_stop

            # Keyword overlap score
            if not trigger_words:
                score = 0.0
            else:
                overlap = len(context_words & trigger_words)
                score = overlap / max(len(trigger_words), 1)

            # Deadline check
            deadline = data.get("deadline")
            deadline_status = "none"
            if deadline:
                if current_time >= deadline:
                    deadline_status = "expired"
                    # Mark as missed
                    data["status"] = "missed"
                    self.conn.execute(
                        "UPDATE nodes SET data=? WHERE id=?",
                        (json.dumps(data), row["id"])
                    )
                else:
                    remaining = deadline - current_time
                    if remaining < 3600:
                        deadline_status = "urgent"
                    elif remaining < 86400:
                        deadline_status = "soon"
                    else:
                        deadline_status = "future"

            # Only include if there's some match or deadline urgency
            if score > 0 or deadline_status in ("urgent", "expired"):
                results.append({
                    "node_id": row["id"],
                    "label": row["label"],
                    "trigger": trigger,
                    "action": data.get("action", ""),
                    "score": round(score, 4),
                    "priority": data.get("priority", "normal"),
                    "deadline_status": deadline_status,
                    "deadline": deadline,
                })

        self.conn.commit()

        # Sort by score desc, then priority
        priority_order = {"high": 0, "normal": 1, "low": 2}
        results.sort(
            key=lambda x: (-x["score"], priority_order.get(x["priority"], 1))
        )
        return results

    def fulfill_intention(self, node_id: str) -> bool:
        """Mark a prospective intention as fulfilled.

        Args:
            node_id: ID of the intention node.

        Returns:
            ``True`` if updated, ``False`` if not found or not an intention.
        """
        node = self.get_node(node_id)
        if not node or node.kind != "intention":
            return False
        data = node.data or {}
        data["status"] = "fulfilled"
        data["fulfilled_at"] = time.time()
        self.update_node(node_id, data=data)
        return True

    def pending_intentions(self, *, include_expired: bool = False
                            ) -> list[dict]:
        """List all pending prospective intentions.

        Args:
            include_expired: If True, also include 'missed' intentions.

        Returns:
            List of intention summaries.
        """
        if include_expired:
            rows = self.conn.execute(
                "SELECT * FROM nodes WHERE kind='intention' "
                "AND json_extract(data, '$.status') IN ('pending', 'missed') "
                "ORDER BY created DESC"
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT * FROM nodes WHERE kind='intention' "
                "AND json_extract(data, '$.status')='pending' "
                "ORDER BY created DESC"
            ).fetchall()

        return [
            {
                "node_id": r["id"],
                "label": r["label"],
                "trigger": json.loads(r["data"]).get("trigger", ""),
                "action": json.loads(r["data"]).get("action", ""),
                "priority": json.loads(r["data"]).get("priority", "normal"),
                "status": json.loads(r["data"]).get("status", "pending"),
                "deadline": json.loads(r["data"]).get("deadline"),
            }
            for r in rows
        ]


    # ----------------------------------------------------------------
    # DRIFT Search (GraphRAG-inspired, Edge et al. 2024)
    # ----------------------------------------------------------------

    def drift_search(
        self,
        question: str,
        *,
        max_iterations: int = 2,
        local_k: int = 5,
        global_k: int = 3,
        spread_hops: int = 2,
        spread_decay: float = 0.4,
        spread_threshold: float = 0.1,
        rrf_k: int = 60,
        summarizer=None,
    ) -> dict:
        """DRIFT-style hybrid search — global sweep then local refinement.

        Combines GraphRAG's two-phase philosophy in a single method:

        1. **Global phase** — ``query_global()`` finds relevant
           communities at a high level.
        2. **Local phase** — For each matched community, runs
           ``spread_activation()`` from member nodes to find
           neighbourhood context.
        3. **Refinement loop** — Extracts keywords from phase-1
           results and re-retrieves with ``retrieve()`` to catch
           nodes that community-level matching missed.

        This is the most sophisticated retrieval mode, blending
        community-level understanding with node-level precision.
        Use when neither pure-global nor pure-local search suffices.

        Args:
            question:       Natural-language query.
            max_iterations: Refinement iterations (1 = no refine).
            local_k:        Max nodes per community in local phase.
            global_k:       Max communities from global phase.
            spread_hops:    Spreading activation max hops.
            spread_decay:   Spreading activation decay.
            spread_threshold: Spreading activation min activation.
            rrf_k:          RRF constant for merging phases.
            summarizer:     Optional LLM callback for community summaries.

        Returns:
            ``{question, iterations, global_results, local_results,
            refined_results, final_results}``
        """
        import re

        # ---- Phase 1: Global community sweep -------------------------
        global_res = self.query_global(
            question, summarizer=summarizer, limit=global_k
        )

        # ---- Phase 2: Local spreading activation ---------------------
        seed_ids: list[str] = []
        for community in global_res.get("results", []):
            for member in community.get("members", []):
                seed_ids.append(member["id"])

        # Also do a direct keyword retrieval as parallel local signal
        kw_results = self.recall(question, limit=local_k * 2)
        for r in kw_results:
            if hasattr(r, 'id'):
                seed_ids.append(r.id)
            elif isinstance(r, dict) and r.get("node_id"):
                seed_ids.append(r["node_id"])
            elif isinstance(r, dict) and r.get("id"):
                seed_ids.append(r["id"])

        # Deduplicate seeds
        seen = set()
        unique_seeds = []
        for sid in seed_ids:
            if sid not in seen:
                seen.add(sid)
                unique_seeds.append(sid)

        local_results: list[dict] = []
        if unique_seeds:
            try:
                activations = self.spread_activation(
                    unique_seeds,
                    decay_factor=spread_decay,
                    threshold=spread_threshold,
                    max_hops=spread_hops,
                )
            except (KeyError, ValueError):
                activations = {}

            # Build node detail for activated nodes
            for nid, act in sorted(
                activations.items(), key=lambda x: x[1], reverse=True
            )[:local_k * 3]:
                row = self.conn.execute(
                    "SELECT id, label, kind, weight FROM nodes WHERE id=?",
                    (nid,),
                ).fetchone()
                if row:
                    local_results.append({
                        "node_id": nid,
                        "label": row["label"],
                        "kind": row["kind"],
                        "weight": row["weight"],
                        "activation": round(act, 4),
                        "source": "seed" if nid in seen else "spread",
                    })

        # ---- Phase 3: RRF merge of global + local --------------------
        def _rrf_score(node_id: str, rank_global: int, rank_local: int) -> float:
            return (1 / (rrf_k + rank_global)) + (1 / (rrf_k + rank_local))

        # Rank nodes from each phase
        global_node_rank: dict[str, int] = {}
        for i, community in enumerate(global_res.get("results", [])):
            for member in community.get("members", []):
                nid = member["id"]
                if nid not in global_node_rank:
                    global_node_rank[nid] = len(global_node_rank) + 1

        local_node_rank: dict[str, int] = {}
        for i, lr in enumerate(local_results):
            local_node_rank[lr["node_id"]] = i + 1

        all_nodes = set(global_node_rank) | set(local_node_rank)
        merged = []
        for nid in all_nodes:
            gr = global_node_rank.get(nid, len(global_node_rank) + 100)
            lr = local_node_rank.get(nid, len(local_node_rank) + 100)
            score = _rrf_score(nid, gr, lr)
            row = self.conn.execute(
                "SELECT label, kind, weight FROM nodes WHERE id=?", (nid,)
            ).fetchone()
            if row:
                merged.append({
                    "node_id": nid,
                    "label": row["label"],
                    "kind": row["kind"],
                    "weight": row["weight"],
                    "score": round(score, 6),
                    "in_global": nid in global_node_rank,
                    "in_local": nid in local_node_rank,
                })

        merged.sort(key=lambda x: x["score"], reverse=True)
        refined_results = merged[:local_k * 3]

        # ---- Iterative refinement -----------------------------------
        iteration_log = [{
            "iteration": 0,
            "global_communities": global_res.get("total_communities", 0),
            "global_matched": global_res.get("communities_matched", 0),
            "local_activated": len(local_results),
            "merged_unique": len(merged),
        }]

        for iteration in range(1, max_iterations):
            # Extract keywords from current results
            current_labels = " ".join(
                r.get("label", "") for r in refined_results
            )
            # Combine original question with discovered labels
            expanded_query = f"{question} {current_labels}"

            # Re-retrieve with expanded query
            try:
                new_results = self.retrieve(
                    expanded_query, limit=local_k * 2, rerank=True
                )
            except Exception:
                new_results = []

            # Merge new results with existing via RRF
            new_node_rank: dict[str, int] = {}
            for i, r in enumerate(new_results):
                nid = ""
                if isinstance(r, dict):
                    nid = r.get("node_id", r.get("id", ""))
                elif hasattr(r, 'id'):
                    nid = r.id
                if nid and nid not in new_node_rank:
                    new_node_rank[nid] = len(new_node_rank) + 1

            # Preserve original global/local flags from first pass
            orig_flags: dict[str, dict] = {}
            for r in refined_results:
                orig_flags[r["node_id"]] = {
                    "in_global": r.get("in_global", False),
                    "in_local": r.get("in_local", False),
                }

            existing_rank = {
                r["node_id"]: i + 1
                for i, r in enumerate(refined_results)
            }

            all_ids = set(existing_rank) | set(new_node_rank)
            remerged = []
            for nid in all_ids:
                er = existing_rank.get(nid, len(existing_rank) + 100)
                nr = new_node_rank.get(nid, len(new_node_rank) + 100)
                score = _rrf_score(nid, er, nr)
                row = self.conn.execute(
                    "SELECT label, kind, weight FROM nodes WHERE id=?", (nid,)
                ).fetchone()
                if row:
                    flags = orig_flags.get(nid, {})
                    remerged.append({
                        "node_id": nid,
                        "label": row["label"],
                        "kind": row["kind"],
                        "weight": row["weight"],
                        "score": round(score, 6),
                        "in_previous": nid in existing_rank,
                        "in_expanded": nid in new_node_rank,
                        "in_global": flags.get("in_global", False),
                        "in_local": flags.get("in_local", False),
                    })

            remerged.sort(key=lambda x: x["score"], reverse=True)
            refined_results = remerged[:local_k * 3]

            iteration_log.append({
                "iteration": iteration,
                "expanded_query": expanded_query[:200],
                "new_candidates": len(new_results),
                "merged_unique": len(remerged),
            })

        # Final trim
        final_results = refined_results[:local_k * 2]

        return {
            "question": question,
            "iterations": len(iteration_log),
            "iteration_log": iteration_log,
            "global_results": global_res,
            "local_results": local_results[:local_k],
            "refined_results": refined_results,
            "final_results": final_results,
            "total_unique_nodes": len(merged) + sum(
                il.get("new_candidates", 0) for il in iteration_log[1:]
            ),
        }

    # ----------------------------------------------------------------
    # Adaptive Query Router (GraphRAG / LightRAG-inspired)
    # ----------------------------------------------------------------

    def query(
        self,
        question: str,
        *,
        mode: str = "auto",
        limit: int = 10,
        detail: bool = False,
        **kwargs,
    ) -> dict:
        """Adaptive query router — picks the best retrieval strategy.

        Inspired by GraphRAG (Edge et al. 2024) and LightRAG (HKUDS
        2024) query routing, this method analyses the question and
        automatically dispatches to the most appropriate search mode:

        - **basic**  — Keyword lookup via ``retrieve()`` (BM25 + vector).
          Fast, precise, best for simple entity lookups.
        - **global** — Community-level scan via ``query_global()``.
          Best for broad conceptual questions ("what are the main themes?").
        - **local**  — Spreading activation from seed nodes via
          ``spread_activation()``. Best for neighbourhood exploration
          ("what's connected to X?").
        - **drift**  — DRIFT hybrid search via ``drift_search()``.
          Best for complex multi-hop questions requiring both global
          context and local precision.
        - **hybrid** — SimHash + graph via ``dual_mode_retrieve()``.
          Best for large graphs where binary pre-filtering helps.

        When ``mode='auto'`` (default), the router uses lightweight
        heuristics on the question to pick the best mode:

        1. Short factual questions (≤3 words, contains entity names)
           → **basic**
        2. Questions with global/exploratory keywords ("overview",
           "themes", "summary", "all about", "big picture")
           → **global**
        3. Questions asking about relationships/connections ("related",
           "connected", "linked", "between")
           → **local**
        4. Complex questions (multi-clause, contains "how"/"why",
           >8 words)
           → **drift**
        5. Temporal questions ("when", "before", "after", "timeline")
           → **temporal** — bi-temporal validity scan
        6. Constraint questions ("must", "required", "allowed",
           "valid") → **constraint** — validation against constraints
        7. Fallback for everything else
           → **hybrid** if graph has >10 nodes, else **basic**

        Args:
            question: Natural-language query string.
            mode:     Force a specific mode ('auto'|'basic'|'global'|
                      'local'|'drift'|'hybrid').
            limit:    Max results to return.
            detail:   If True, include full node details in results.
            **kwargs: Passed through to the underlying search method.

        Returns:
            ``{question, mode, rationale, results, stats}``
        """
        import re

        # --- Determine mode ----------------------------------------
        if mode == "auto":
            mode, rationale = self._route_query(question)
        else:
            rationale = f"explicit mode='{mode}'"

        # --- Dispatch to chosen strategy ---------------------------
        t0 = __import__("time").perf_counter()

        if mode == "basic":
            raw = self.retrieve(question, limit=limit, rerank=True)
            results = []
            for r in (raw if isinstance(raw, list) else []):
                if isinstance(r, dict):
                    node = r.get("node")
                    results.append({
                        "node_id": r.get("node_id", r.get("id", "")),
                        "label": r.get("label") or (node.label if node else ""),
                        "kind": r.get("kind") or (node.kind if node else ""),
                        "score": r.get("score", r.get("bm25_score", 0)),
                    })
                elif hasattr(r, "id"):
                    results.append({
                        "node_id": r.id,
                        "label": getattr(r, "label", ""),
                        "kind": getattr(r, "kind", ""),
                        "score": getattr(r, "score", 0),
                    })

        elif mode == "global":
            raw = self.query_global(
                question, limit=kwargs.get("global_k", 5),
            )
            results = []
            for community in raw.get("results", []):
                for member in community.get("members", []):
                    results.append({
                        "node_id": member["id"],
                        "label": member.get("label", ""),
                        "kind": member.get("kind", ""),
                        "community": community.get("community_id"),
                        "score": community.get("score", 0),
                    })
                    if len(results) >= limit:
                        break
                if len(results) >= limit:
                    break

        elif mode == "local":
            # Seed from keyword search, then spread
            seeds = self.retrieve(question, limit=3)
            seed_ids = []
            for r in (seeds if isinstance(seeds, list) else []):
                if isinstance(r, dict):
                    seed_ids.append(
                        r.get("node_id", r.get("id", ""))
                    )
                elif hasattr(r, "id"):
                    seed_ids.append(r.id)
            seed_ids = [s for s in seed_ids if s]

            if seed_ids:
                try:
                    activations = self.spread_activation(
                        seed_ids,
                        decay_factor=kwargs.get("decay", 0.4),
                        threshold=kwargs.get("threshold", 0.1),
                        max_hops=kwargs.get("max_hops", 2),
                    )
                except (KeyError, ValueError):
                    activations = {}

                results = []
                for nid, act in sorted(
                    activations.items(), key=lambda x: x[1], reverse=True
                )[:limit]:
                    row = self.conn.execute(
                        "SELECT label, kind FROM nodes WHERE id=?",
                        (nid,),
                    ).fetchone()
                    if row:
                        results.append({
                            "node_id": nid,
                            "label": row["label"],
                            "kind": row["kind"],
                            "score": round(act, 4),
                            "seed": nid in seed_ids,
                        })
            else:
                results = []

        elif mode == "drift":
            raw = self.drift_search(
                question,
                local_k=limit,
                global_k=kwargs.get("global_k", 3),
                max_iterations=kwargs.get("max_iterations", 2),
            )
            results = raw.get("final_results", [])

        elif mode == "hybrid":
            raw = self.dual_mode_retrieve(
                question, limit=limit,
            )
            results = raw if isinstance(raw, list) else raw.get("results", [])

        elif mode == "temporal":
            # Temporal reasoning: find nodes valid at relevant times
            results = self._temporal_search(question, limit)

        elif mode == "constraint":
            # Constraint validation: find nodes with constraints
            results = self._constraint_search(question, limit)

        else:
            raise ValueError(
                f"Unknown mode '{mode}'. "
                "Use: auto, basic, global, local, drift, hybrid, "
                "temporal, constraint"
            )

        elapsed_ms = (__import__("time").perf_counter() - t0) * 1000

        # --- Enrich with detail if requested -----------------------
        if detail:
            for r in results:
                nid = r.get("node_id", "")
                if nid:
                    row = self.conn.execute(
                        "SELECT label, kind, weight, data, tags FROM nodes "
                        "WHERE id=?",
                        (nid,),
                    ).fetchone()
                    if row:
                        r["label"] = r.get("label") or row["label"]
                        r["kind"] = r.get("kind") or row["kind"]
                        r["weight"] = row["weight"]
                        r["data"] = json.loads(row["data"]) if row["data"] else {}
                        r["tags"] = json.loads(row["tags"]) if row["tags"] else []

        return {
            "question": question,
            "mode": mode,
            "rationale": rationale,
            "results": results[:limit],
            "stats": {
                "total_results": len(results),
                "elapsed_ms": round(elapsed_ms, 2),
                "node_count": self.stats()["nodes"],
                "edge_count": self.edge_count(),
            },
        }

    def _route_query(self, question: str) -> tuple[str, str]:
        """Heuristic router — analyse question to pick best mode.

        Returns ``(mode, rationale_string)``.
        """
        q_lower = question.lower().strip()
        words = q_lower.split()
        n_words = len(words)
        node_count = self.stats()["nodes"]
        import re as _re

        # 0. Temporal keywords (check before short-query rule so
        #    "when?", "history of X" route correctly)
        temporal_short = ["when", "since", "until"]
        temporal_long = [
            "before", "after", "timeline", "history",
            "future", "changed", "used to be", "previously",
        ]
        has_temporal = any(
            _re.search(r'\b' + _re.escape(m) + r'\b', q_lower)
            for m in temporal_short
        ) or any(m in q_lower for m in temporal_long)

        # 0b. Constraint keywords
        constraint_short = ["must", "rule", "valid", "invalid"]
        constraint_long = [
            "required", "allowed", "permitted", "forbidden",
            "constraint", "policy", "comply", "violation",
        ]
        has_constraint = any(
            _re.search(r'\b' + _re.escape(m) + r'\b', q_lower)
            for m in constraint_short
        ) or any(m in q_lower for m in constraint_long)

        if has_temporal:
            return "temporal", (
                "temporal keywords detected → bi-temporal scan"
            )
        if has_constraint:
            return "constraint", (
                "constraint keywords detected → validation scan"
            )

        # 1. Short factual lookup → basic
        if n_words <= 3:
            return "basic", (
                "short query (≤3 words) → keyword lookup"
            )

        # 2. Global / exploratory keywords
        global_markers = [
            "overview", "themes", "summary", "all about",
            "big picture", "landscape", "categories", "main",
            "list all", "everything",
        ]
        if any(m in q_lower for m in global_markers):
            return "global", (
                "exploratory keywords detected → community scan"
            )

        # 3. Complex multi-hop → drift (check before local so
        #    multi-clause questions with "connected" route here)
        # Use word-boundary matching for short markers to avoid
        # false positives (e.g. 'how' inside 'show').
        complex_markers = ["how", "why", "trace"]
        has_complex = any(
            _re.search(r'\b' + _re.escape(m) + r'\b', q_lower)
            for m in complex_markers
        ) or "what happens if" in q_lower
        has_multiclause = q_lower.count(" and ") >= 1 or \
            q_lower.count("?") >= 2
        if has_complex or (n_words > 8 and has_multiclause):
            return "drift", (
                "complex multi-hop question → DRIFT hybrid search"
            )

        # 4. Relationship / connection questions
        local_markers = [
            "related", "connected", "linked", "between",
            "neighbors", "neighbours", "associated",
            "what connects", "depends on",
        ]
        if any(m in q_lower for m in local_markers):
            return "local", (
                "relationship keywords → spreading activation"
            )

        # 5. Default: hybrid for large graphs, basic for small
        if node_count > 10:
            return "hybrid", (
                f"general query on {node_count}-node graph "
                "→ dual-mode SimHash+graph"
            )
        return "basic", (
            f"general query on small graph ({node_count} nodes) "
            "→ keyword lookup"
        )


    # ----------------------------------------------------------------
    # Intent-Aware Token Budgets (MemFlow-inspired)
    # ----------------------------------------------------------------

    _INTENT_BUDGET_PRESETS = {
        # Mode → (default_budget, description)
        "basic":  200,
        "local":  500,
        "global": 1000,
        "drift":  800,
        "hybrid": 600,
    }

    def intent_aware_token_budgets(
        self,
        question: str = "",
        *,
        mode: str = "auto",
        override: dict[str, int] = None,
    ) -> dict:
        """Return mode-dependent token budgets for retrieval.

        MemFlow (arXiv:2605.03312) shows that different query intents
        benefit from tiered token budgets: simple lookups need few
        tokens, while global/drift queries need more context to be
        effective.  Disabling intent-aware budgets costs ~18.7pp
        accuracy.

        This method does NOT perform retrieval — it returns the
        budget allocation that ``query_with_budgets()`` (or external
        callers) should use.

        Presets (tokens)::

            basic:   200   — quick entity lookup
            local:   500   — neighbourhood exploration
            hybrid:  600   — SimHash + graph blend
            drift:   800   — multi-hop with global context
            global: 1000   — community-level thematic scan

        Args:
            question:  Natural-language query (used to auto-detect mode).
            mode:      Force a mode ('auto' to detect from question).
            override:  Dict mapping mode → token budget to customise.
                       ``{"global": 1500}`` raises global budget.

        Returns:
            ``{mode, budgets, selected_budget, rationale}``
        """
        # Resolve mode
        if mode == "auto":
            resolved_mode, rationale = self._route_query(question)
        else:
            resolved_mode = mode
            rationale = f"explicit mode='{mode}'"

        # Build budget table
        budgets = dict(self._INTENT_BUDGET_PRESETS)
        if override:
            for k, v in override.items():
                if k in budgets:
                    budgets[k] = v

        selected = budgets.get(resolved_mode, 600)

        return {
            "mode": resolved_mode,
            "budgets": budgets,
            "selected_budget": selected,
            "rationale": rationale,
        }

    def query_with_budgets(
        self,
        question: str,
        *,
        mode: str = "auto",
        override: dict[str, int] = None,
        chars_per_token: float = 4.0,
        detail: bool = False,
    ) -> dict:
        """Query with intent-aware token budget allocation.

        Combines ``intent_aware_token_budgets()`` with
        ``retrieve_token_budgeted()`` to provide a single-call
        retrieval that automatically scales context size based on
        query complexity.

        This is the recommended production retrieval path for
        external callers (LLM agents, MCP servers, etc.).

        Args:
            question:       Natural-language query.
            mode:           Force mode ('auto' for detection).
            override:       Custom mode → budget overrides.
            chars_per_token: Char-to-token conversion ratio.
            detail:         Include full node details.

        Returns:
            ``{question, mode, rationale, budget, context, nodes,
            token_count, truncated, stats}``
        """
        # 1. Determine budget
        budget_info = self.intent_aware_token_budgets(
            question, mode=mode, override=override,
        )
        token_budget = budget_info["selected_budget"]

        # 2. Retrieve with budget
        retrieval = self.retrieve_token_budgeted(
            question,
            token_budget=token_budget,
            chars_per_token=chars_per_token,
        )

        # 3. Optionally enrich with detail
        nodes = retrieval["nodes"]
        if detail:
            for n in nodes:
                nid = n.get("node_id", "")
                if nid:
                    row = self.conn.execute(
                        "SELECT weight, data, tags FROM nodes WHERE id=?",
                        (nid,),
                    ).fetchone()
                    if row:
                        n["weight"] = row["weight"]
                        n["data"] = json.loads(row["data"]) if row["data"] else {}
                        n["tags"] = json.loads(row["tags"]) if row["tags"] else []

        return {
            "question": question,
            "mode": budget_info["mode"],
            "rationale": budget_info["rationale"],
            "budget": token_budget,
            "context": retrieval["context"],
            "nodes": nodes,
            "token_count": retrieval["token_count"],
            "truncated": retrieval["truncated"],
            "stats": {
                "node_count": self.stats()["nodes"],
                "edge_count": self.edge_count(),
                "elapsed_ms": 0,  # filled by caller if needed
            },
        }

    # ----------------------------------------------------------------
    # Retrieval Screening — read-time security (GhostWriter-inspired)
    # ----------------------------------------------------------------

    _INJECTION_PATTERNS = [
        # Instruction-pattern keywords that indicate attempted
        # memory-injection / prompt-injection via stored content
        "ignore previous",
        "ignore all",
        "disregard the above",
        "you are now",
        "new instructions:",
        "system prompt:",
        "forget everything",
        "override your",
        "act as if",
        "pretend you are",
        "do not follow",
        "reveal your",
        "what is your prompt",
        "what are your instructions",
    ]

    def screen_retrieval(
        self,
        results: list[dict],
        *,
        patterns: list[str] = None,
        threshold: int = 1,
        node_field: str = "nodes",
    ) -> dict:
        """Screen retrieval results for injection / manipulation.

        GhostWriter/AM-Sentry (arXiv:2607.06595) show 98% memory
        injection rate in unprotected systems.  This method provides
        read-time screening: scanning retrieved node content for
        instruction-pattern strings that may indicate planted
        injections.

        Dual-layer defense (complements ``write_governance_check()``):
        - **Write-time** (cycle 252): blocks sycophantic writes
        - **Read-time** (this): flags suspicious retrieved content

        Args:
            results:    Retrieval result dict (from ``query()`` or
                        ``query_with_budgets()``) or list of node dicts.
            patterns:   Custom pattern list (default: built-in).
            threshold:  Min pattern hits to flag as suspicious.
            node_field: Key containing node list in dict input.

        Returns:
            ``{clean, flagged, total, flagged_ids, details}``
        """
        check_patterns = patterns or self._INJECTION_PATTERNS
        check_lower = [p.lower() for p in check_patterns]

        # Normalise input to list of node dicts
        if isinstance(results, dict):
            nodes = results.get(node_field, results.get("results", []))
        else:
            nodes = results

        clean = []
        flagged = []
        details = []

        for node in nodes:
            # Gather all text content from the node
            label = str(node.get("label", ""))
            kind = str(node.get("kind", ""))
            data = node.get("data", {})
            if isinstance(data, str):
                try:
                    data = json.loads(data)
                except Exception:
                    pass
            data_str = " ".join(str(v) for v in data.values()) if isinstance(data, dict) else str(data)
            tags = node.get("tags", [])
            tags_str = " ".join(str(t) for t in tags) if isinstance(tags, list) else str(tags)

            combined = f"{label} {kind} {data_str} {tags_str}".lower()

            hits = []
            for p in check_lower:
                if p in combined:
                    hits.append(p)

            node_id = node.get("node_id", node.get("id", ""))

            if len(hits) >= threshold:
                flagged.append(node)
                details.append({
                    "node_id": node_id,
                    "hits": hits,
                    "hit_count": len(hits),
                    "label": label,
                })
            else:
                clean.append(node)

        return {
            "clean": clean,
            "flagged": flagged,
            "total": len(nodes),
            "flagged_count": len(flagged),
            "flagged_ids": [d["node_id"] for d in details],
            "details": details,
        }

    def query_confidence_score(
        self,
        question: str,
        *,
        mode: str = "auto",
        limit: int = 10,
    ) -> dict:
        """Query with confidence scoring for caller-side escalation.

        MemFlow Validator-inspired: not all retrievals are equally
        trustworthy.  This method wraps ``query()`` and adds a
        ``confidence`` field [0, 1] so callers can decide whether to
        use the results directly or escalate (e.g., ask user, search
        wider, or fallback to full-context).

        Confidence factors:
        - **Coverage**: fraction of results with non-empty data (0-0.3)
        - **Score spread**: variance of result scores (0-0.2)
        - **Graph density**: local edge density around results (0-0.2)
        - **Result count**: sufficient results vs limit (0-0.15)
        - **Freshness**: recency of top results (0-0.15)

        Args:
            question: Natural-language query.
            mode:     Force mode ('auto' for detection).
            limit:    Max results.

        Returns:
            ``{question, mode, results, confidence, factors, stats}``
        """
        raw = self.query(question, mode=mode, limit=limit, detail=True)
        results = raw.get("results", [])

        if not results:
            return {
                "question": question,
                "mode": raw.get("mode", mode),
                "results": [],
                "confidence": 0.0,
                "factors": {"reason": "no results"},
                "stats": raw.get("stats", {}),
            }

        # Factor 1: Coverage (nodes with non-empty data)
        with_data = sum(
            1 for r in results
            if r.get("data") and any(v for v in r["data"].values())
        )
        coverage = min(with_data / max(len(results), 1), 1.0) * 0.30

        # Factor 2: Score spread (variance indicates differentiation)
        scores = [r.get("score", 0) for r in results if isinstance(r.get("score"), (int, float))]
        if len(scores) >= 2:
            avg = sum(scores) / len(scores)
            variance = sum((s - avg) ** 2 for s in scores) / len(scores)
            spread = min(variance * 10, 1.0) * 0.20  # scale up small variances
        else:
            spread = 0.0

        # Factor 3: Graph density around result nodes
        result_ids = [r.get("node_id", "") for r in results if r.get("node_id")]
        if result_ids:
            placeholders = ",".join("?" * len(result_ids))
            edge_count = self.conn.execute(
                f"SELECT COUNT(*) FROM edges WHERE source IN ({placeholders}) OR target IN ({placeholders})",
                (*result_ids, *result_ids),
            ).fetchone()[0]
            max_possible = len(result_ids) * (len(result_ids) - 1)
            density = min(edge_count / max(max_possible, 1), 1.0) * 0.20
        else:
            density = 0.0

        # Factor 4: Result count sufficiency
        count_factor = min(len(results) / max(limit, 1), 1.0) * 0.15

        # Factor 5: Freshness (top-3 average recency)
        import time
        now = time.time()
        top3 = results[:3]
        ages = []
        for r in top3:
            nid = r.get("node_id", "")
            if nid:
                row = self.conn.execute(
                    "SELECT accessed FROM nodes WHERE id=?", (nid,),
                ).fetchone()
                if row and row["accessed"]:
                    ages.append(max(now - row["accessed"], 0))
        if ages:
            avg_age = sum(ages) / len(ages)
            # 0 seconds old → full 0.15, 7 days → ~0
            freshness = max(0, 1 - avg_age / 604800) * 0.15
        else:
            freshness = 0.0

        confidence = round(coverage + spread + density + count_factor + freshness, 4)

        return {
            "question": question,
            "mode": raw.get("mode", mode),
            "results": results,
            "confidence": confidence,
            "factors": {
                "coverage": round(coverage, 4),
                "score_spread": round(spread, 4),
                "graph_density": round(density, 4),
                "result_count": round(count_factor, 4),
                "freshness": round(freshness, 4),
            },
            "stats": raw.get("stats", {}),
        }


    def _temporal_search(self, question: str, limit: int = 10) -> list[dict]:
        """Temporal reasoning search — find time-relevant nodes.

        Scans for nodes with temporal metadata (created/accessed/
        validity ranges) and returns them sorted by temporal relevance.
        Queries temporal fields: supersede timestamps, validity
        windows, and bi-temporal history.
        """
        import time as _time
        now = _time.time()

        # Get all nodes with temporal data
        rows = self.conn.execute(
            "SELECT id, label, kind, weight, created, accessed, data "
            "FROM nodes ORDER BY accessed DESC LIMIT ?",
            (limit * 3,),
        ).fetchall()

        results = []
        for row in rows:
            d = row["data"]
            if isinstance(d, str):
                try:
                    d = json.loads(d)
                except Exception:
                    d = {}
            if not isinstance(d, dict):
                d = {}

            # Compute temporal score
            age = now - row["accessed"]
            # Newer = higher score, with exponential decay
            temporal_score = max(0, 1 - age / (86400 * 30))  # 30-day half-life

            # Boost if has validity range
            valid_from = d.get("valid_from")
            valid_until = d.get("valid_until")
            if valid_from and valid_until:
                if valid_from <= now <= valid_until:
                    temporal_score *= 1.5  # currently valid
            elif valid_from and not valid_until:
                if valid_from <= now:
                    temporal_score *= 1.3  # open-ended validity

            # Check for superseded nodes (lower score)
            is_superseded = bool(d.get("superseded_by"))
            if is_superseded:
                temporal_score *= 0.3

            results.append({
                "node_id": row["id"],
                "label": row["label"],
                "kind": row["kind"],
                "score": round(temporal_score, 4),
                "created": row["created"],
                "accessed": row["accessed"],
                "superseded": is_superseded,
            })

        # Sort by temporal score descending
        results.sort(key=lambda x: x["score"], reverse=True)
        return results[:limit]

    def _constraint_search(self, question: str, limit: int = 10) -> list[dict]:
        """Constraint validation search — find rule/constraint nodes.

        Looks for nodes that represent constraints, rules, policies,
        or validation criteria, and returns them for evaluation
        against the query.
        """
        constraint_kinds = [
            "constraint", "rule", "policy", "requirement",
            "law", "regulation", "standard",
        ]

        # Also check tags and data fields
        results = []

        # 1. Find nodes by kind
        for kind in constraint_kinds:
            rows = self.conn.execute(
                "SELECT id, label, kind, weight, data, tags "
                "FROM nodes WHERE kind=? LIMIT ?",
                (kind, limit),
            ).fetchall()
            for row in rows:
                results.append({
                    "node_id": row["id"],
                    "label": row["label"],
                    "kind": row["kind"],
                    "score": row["weight"],
                    "match_type": "kind",
                })

        # 2. Find nodes with constraint-related tags
        if len(results) < limit:
            rows = self.conn.execute(
                "SELECT id, label, kind, weight, tags FROM nodes LIMIT 100"
            ).fetchall()
            for row in rows:
                tags_raw = row["tags"]
                if isinstance(tags_raw, str):
                    try:
                        tags = json.loads(tags_raw)
                    except Exception:
                        tags = []
                else:
                    tags = tags_raw or []

                for tag in (tags or []):
                    tag_lower = str(tag).lower()
                    if any(c in tag_lower for c in constraint_kinds):
                        if not any(r["node_id"] == row["id"] for r in results):
                            results.append({
                                "node_id": row["id"],
                                "label": row["label"],
                                "kind": row["kind"],
                                "score": row["weight"] * 0.8,
                                "match_type": "tag",
                            })
                        break

        # 3. Fallback: keyword search for constraint-related content
        if len(results) < limit:
            kw_results = self.retrieve(question, limit=limit)
            for r in (kw_results if isinstance(kw_results, list) else []):
                if isinstance(r, dict):
                    nid = r.get("node_id", r.get("id", ""))
                    if nid and not any(x["node_id"] == nid for x in results):
                        results.append({
                            "node_id": nid,
                            "label": r.get("label", ""),
                            "kind": r.get("kind", ""),
                            "score": r.get("score", 0) * 0.5,
                            "match_type": "keyword",
                        })

        return results[:limit]


    def query_route_audit(
        self,
        questions: list[str] = None,
        *,
        include_results: bool = False,
    ) -> dict:
        """Audit query routing decisions for observability.

        MemFlow (arXiv:2605.03312) shows disabling intent routing costs
        ~18.7pp.  This method helps debug *why* a question was routed
        to a particular mode and identify routing mis-classifications.

        Runs ``_route_query()`` for each question (no actual retrieval),
        building a routing table with mode distribution, rationale
        summary, and per-question detail.

        Args:
            questions:         List of questions to audit. If None, uses
                           a built-in diagnostic set.
        include_results: If True, also run full query() for each.

        Returns:
            ``{audited, mode_distribution, summary, per_question}``
        """
        if questions is None:
            questions = [
                # basic
                "Alice",
                "deploy",
                # global
                "overview of all themes",
                "big picture summary",
                # drift
                "how does Alice connect to the project?",
                "why was this decision made and what follows?",
                # local
                "what is connected to Bob?",
                # temporal
                "when was Alice created?",
                "timeline of changes",
                # constraint
                "what policy applies here?",
                "is this valid?",
            ]

        per_question = []
        mode_counts = {}

        for q in questions:
            mode, rationale = self._route_query(q)
            mode_counts[mode] = mode_counts.get(mode, 0) + 1

            entry = {
                "question": q,
                "mode": mode,
                "rationale": rationale,
            }

            if include_results:
                result = self.query(q)
                entry["result_count"] = len(result.get("results", []))
                entry["elapsed_ms"] = result.get("stats", {}).get("elapsed_ms", 0)

            per_question.append(entry)

        # Sort mode distribution by count descending
        sorted_modes = sorted(
            mode_counts.items(), key=lambda x: x[1], reverse=True
        )

        summary_parts = []
        for mode, count in sorted_modes:
            summary_parts.append(f"{mode}:{count}")

        return {
            "audited": len(questions),
            "mode_distribution": dict(sorted_modes),
            "summary": ", ".join(summary_parts),
            "per_question": per_question,
        }


    # ----------------------------------------------------------------
    # Entropy-Guided Query Routing (Entropy-Guided Branching)
    # ----------------------------------------------------------------

    _ENTROPY_ROUTE_BINS = {
        # Normalised Shannon entropy → recommended retrieval mode.
        #
        # Shannon entropy is maximised when all edge contributions are
        # equal (regular graphs → entropy = 1.0).  Low entropy means
        # a few edges dominate (hubs, bridges → heterogeneous).
        #
        # Low entropy (heterogeneous structure) → drift multi-hop:
        #   structural complexity requires exploratory traversal.
        # Medium entropy → hybrid SimHash + graph.
        # High entropy (uniform structure) → basic keyword lookup:
        #   regular graphs are simple to search.
        "low":    (0.0, 0.33, "drift"),
        "medium": (0.33, 0.67, "hybrid"),
        "high":   (0.67, 1.01, "basic"),
    }

    def harary_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Harary (reciprocal-distance) contributions.

        For each reachable node pair (u, v), compute the reciprocal
        distance r_uv = 1/d(u,v), normalise to p_uv = r_uv / H where
        H is the Harary index, then calculate Shannon entropy:

            H_H = −Σ p_uv · ln(p_uv)

        When *normalized* is True the result is divided by ln(pairs)
        so the output lies in (0, 1].  A value of 1.0 means all
        reachable pairs are equidistant (e.g. complete graphs, cycles).

        **Properties:**
        - Complete graph K_n: all d=1, H_H = 1.0 (all equal)
        - Cycle C_n: all d=1 or d=2, structure-dependent
        - Star K_{1,k}: hub-leaf pairs d=1, leaf-leaf d=2 → heterogeneity
        - Sensitive to reciprocal distances → emphasises compactness variation

        Returns:
            float in (0, ln(pairs)] or (0, 1], or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        contributions: list[float] = []
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    contributions.append(1.0 / d)
        if not contributions:
            return None
        h = sum(contributions)
        if h <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / h
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    def wiener_entropy(self, normalized: bool = True) -> Optional[float]:
        """Shannon entropy of normalised Wiener (distance) contributions.

        For each reachable node pair (u, v), compute the distance d_uv,
        normalise to p_uv = d_uv / W where W is the Wiener index,
        then calculate Shannon entropy:

            H_W = −Σ p_uv · ln(p_uv)

        When *normalized* is True the result is divided by ln(pairs)
        so the output lies in (0, 1].  A value of 1.0 means all
        reachable pairs are equidistant.

        **Properties:**
        - Complete graph K_n: all d=1, H_W = 1.0
        - Cycle C_n: distances are 1 and n/2 (for large n), bimodal
        - Star K_{1,k}: hub-leaf d=1, leaf-leaf d=2 → near-uniform
        - Complementary to harary_entropy: Wiener weights long paths,
          Harary weights short paths

        Returns:
            float in (0, ln(pairs)] or (0, 1], or ``None`` for < 2 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(rows) < 2:
            return None
        node_ids = [str(r["id"]) for r in rows]
        contributions: list[float] = []
        for i, nid in enumerate(node_ids):
            dists = self._bfs_distances(nid)
            for other in node_ids[i + 1:]:
                d = dists.get(other)
                if d and d > 0:
                    contributions.append(float(d))
        if not contributions:
            return None
        w = sum(contributions)
        if w <= 0:
            return None
        m = len(contributions)
        entropy = 0.0
        for c in contributions:
            p = c / w
            if p > 0:
                entropy -= p * math.log(p)
        if normalized and m > 1:
            entropy /= math.log(m)
        return entropy

    # ------------------------------------------------------------------
    # Spectral entropy (Laplacian eigenvalue based)
    # ------------------------------------------------------------------

    def _laplacian_eigenvalues(self, *, include_quarantined: bool = False
                               ) -> Optional[list[float]]:
        """Return sorted Laplacian eigenvalues of the undirected graph.

        Builds L = D − A (symmetric) and applies ``_sym_eigenvalues``.
        Used by all spectral-entropy methods.

        Args:
            include_quarantined:  If True, include quarantined nodes.

        Returns:
            Sorted list of eigenvalues (ascending), or ``None``
            for fewer than 2 nodes.
        """
        base = "SELECT id FROM nodes"
        if not include_quarantined:
            base += " WHERE quarantined = 0"
        node_ids = [str(r["id"]) for r in self.conn.execute(base).fetchall()]
        n = len(node_ids)
        if n < 2:
            return None
        idx = {nid: i for i, nid in enumerate(node_ids)}
        degree = [0] * n
        adj_sym: dict[int, set[int]] = defaultdict(set)
        edge_q = "SELECT source, target FROM edges"
        for e in self.conn.execute(edge_q).fetchall():
            s, t = str(e["source"]), str(e["target"])
            if s in idx and t in idx:
                i, j = idx[s], idx[t]
                adj_sym[i].add(j)
                adj_sym[j].add(i)
                degree[i] += 1
                degree[j] += 1
        L = [[0.0] * n for _ in range(n)]
        for i in range(n):
            L[i][i] = float(degree[i])
            for j in adj_sym[i]:
                L[i][j] = -1.0
        evals = self._sym_eigenvalues(L)
        evals.sort()
        return evals

    def von_neumann_entropy(self, normalized: bool = True,
                            *, include_quarantined: bool = False
                            ) -> Optional[float]:
        r"""Von Neumann graph entropy — Shannon entropy of normalised
        positive Laplacian eigenvalues.

        For a graph with Laplacian eigenvalues *λ₁ … λₙ* (λ₁ = 0 for
        each connected component), define:

            λ_sum = Σ λᵢ  (= 2m  where *m* is the edge count)
            pᵢ   = λᵢ / λ_sum
            H_vN = −Σ pᵢ · ln(pᵢ)        (skip pᵢ = 0)

        **Properties** (Research #031):
        - K_n maximises: all non-zero λᵢ = n, uniform → H = ln(n−1)
        - Empty graph (0 edges): all λ = 0 → convention H = 0
        - Path P_n: heterogeneous spectrum → moderate entropy
        - Complementary to degree-based entropies: captures **global**
          topology through the spectral decomposition, not local
          neighbourhood structure.

        When *normalized* is True the result is divided by ln(n−1)
        so that a complete graph maps to 1.0.

        Args:
            normalized:           Divide by ln(n−1) so K_n → 1.0.
            include_quarantined:  Include quarantined nodes.

        Returns:
            float in [0, ln(n−1)] or [0, 1], or ``None`` for < 2 nodes.
        """
        evals = self._laplacian_eigenvalues(include_quarantined=include_quarantined)
        if evals is None:
            return None
        # Sum of Laplacian eigenvalues = trace(L) = 2m
        lam_sum = sum(evals)
        if lam_sum <= 0:
            return 0.0  # no edges → all eigenvalues zero
        probs = [e / lam_sum for e in evals if e > 1e-15]
        if not probs:
            return 0.0
        entropy = 0.0
        for p in probs:
            entropy -= p * math.log(p)
        n = len(evals)
        if normalized and n > 2:
            max_entropy = math.log(n - 1)
            if max_entropy > 0:
                entropy /= max_entropy
        return entropy

    def spectral_entropy_profile(self, *, include_quarantined: bool = False
                                 ) -> Optional[dict]:
        """Dashboard of spectral (Laplacian-eigenvalue) graph descriptors.

        Aggregates all spectral information into a single dict:

        - ``von_neumann_entropy``      — normalised H_vN ∈ [0, 1]
        - ``von_neumann_entropy_raw``  — raw H_vN
        - ``algebraic_connectivity``   — λ₂ (Fiedler value)
        - ``spectral_gap``             — λₙ − λ₂ (gap between largest
          and second-smallest eigenvalue)
        - ``spectral_radius``          — largest |λᵢ|
        - ``n_positive``               — count of λᵢ > ε
        - ``n_zero``                   — count of λᵢ ≈ 0 (= #components)
        - ``max_entropy_possible``     — ln(n−1)
        - ``entropy_ratio``            — H_vN / ln(n−1)
        - ``complexity``               — participation ratio
          (Σλ²)² / Σλ⁴ — measures how spread the spectrum is
        - ``eigenvalues``              — full sorted eigenvalue list

        Returns:
            dict, or ``None`` for < 2 nodes.
        """
        evals = self._laplacian_eigenvalues(include_quarantined=include_quarantined)
        if evals is None:
            return None
        n = len(evals)
        eps = 1e-9
        n_zero = sum(1 for e in evals if abs(e) < eps)
        n_pos = sum(1 for e in evals if e > eps)
        lam_max = max(evals) if evals else 0.0
        lam_sum = sum(evals)
        # Algebraic connectivity (second smallest)
        alg_conn = evals[1] if n >= 2 else 0.0
        # Spectral gap = largest - second smallest
        spec_gap = (evals[-1] - evals[1]) if n >= 2 else 0.0
        # Participation ratio (quantum complexity measure)
        if lam_sum > 0:
            sum_sq = sum(e * e for e in evals)
            sum_4th = sum(e ** 4 for e in evals)
            complexity = (sum_sq * sum_sq / sum_4th) if sum_4th > eps else 0.0
        else:
            complexity = 0.0
        h_vn_norm = self.von_neumann_entropy(normalized=True,
                                             include_quarantined=include_quarantined)
        h_vn_raw = self.von_neumann_entropy(normalized=False,
                                            include_quarantined=include_quarantined)
        max_h = math.log(n - 1) if n > 2 else 0.0
        entropy_ratio = (h_vn_raw / max_h) if max_h > 0 else 0.0
        return {
            "von_neumann_entropy":     h_vn_norm,
            "von_neumann_entropy_raw": h_vn_raw,
            "algebraic_connectivity":  alg_conn,
            "spectral_gap":            spec_gap,
            "spectral_radius":         lam_max,
            "n_positive":              n_pos,
            "n_zero":                  n_zero,
            "max_entropy_possible":    max_h,
            "entropy_ratio":           entropy_ratio,
            "complexity":              complexity,
            "eigenvalues":             evals,
        }

    def quantum_jensen_shannon_distance(
        self,
        other: "MemoryGraph",
        *,
        include_quarantined: bool = False,
    ) -> Optional[float]:
        r"""Quantum Jensen-Shannon distance between two graphs.

        Treats each graph's Laplacian spectrum as a quantum density
        matrix (diagonal), then computes the **quantum** JSD:

            ρ_G = diag(λ₁/Σλ, …, λₙ/Σλ)    (normalised eigenvalues)

            d_QJSD(G, H) = √( ½ S(ρ_G ‖ M) + ½ S(ρ_H ‖ M) )

        where M = ½(ρ_G + ρ_H) and S(ρ‖σ) is the von Neumann
        relative entropy:

            S(ρ‖σ) = Tr(ρ · (ln ρ − ln σ))

        Since both ρ are diagonal, this reduces to elementwise
        computation on the eigenvalue probability vectors.

        **Properties** (Research #031):
        - Symmetric: d(A,B) = d(B,A)
        - Bounded: 0 ≤ d ≤ ln(2)^½ ≈ 0.833
        - Metric: satisfies triangle inequality
        - Captures **global** topology: two graphs with the same
          degree sequence but different wiring give d > 0
        - Complementary to ``entropy_distance()`` (which uses
          degree-based edge contributions)

        Graphs of different sizes are handled by padding the shorter
        eigenvalue vector with zeros.

        Args:
            other:               The graph to compare against.
            include_quarantined:  Include quarantined nodes.

        Returns:
            float in [0, √ln2], or ``None`` if either graph has < 2 nodes.
        """
        evals_a = self._laplacian_eigenvalues(include_quarantined=include_quarantined)
        evals_b = other._laplacian_eigenvalues(include_quarantined=include_quarantined)
        if evals_a is None or evals_b is None:
            return None
        # Normalise eigenvalues to probability vectors
        sum_a = sum(evals_a)
        sum_b = sum(evals_b)
        if sum_a <= 0 and sum_b <= 0:
            # Both empty graphs → distance 0
            return 0.0
        if sum_a <= 0 or sum_b <= 0:
            # One empty, one not → maximum distance
            return math.sqrt(math.log(2))
        p = [e / sum_a for e in evals_a]
        q = [e / sum_b for e in evals_b]
        # Pad to same length
        n = max(len(p), len(q))
        p += [0.0] * (n - len(p))
        q += [0.0] * (n - len(q))
        # M = (p + q) / 2
        m = [(p[i] + q[i]) / 2.0 for i in range(n)]
        eps = 1e-15
        # Von Neumann relative entropies
        s_pm = 0.0  # S(p || m)
        s_qm = 0.0  # S(q || m)
        for i in range(n):
            if p[i] > eps and m[i] > eps:
                s_pm += p[i] * (math.log(p[i]) - math.log(m[i]))
            if q[i] > eps and m[i] > eps:
                s_qm += q[i] * (math.log(q[i]) - math.log(m[i]))
        qjsd = 0.5 * s_pm + 0.5 * s_qm
        # Numerical safety
        if qjsd < 0:
            qjsd = 0.0
        return math.sqrt(qjsd)

    def entropy_guided_query_route(
        self,
        question: str,
        *,
        limit: int = 10,
        entropy_index: str = "sombor",
        detail: bool = False,
        override_heuristic: bool = True,
    ) -> dict:
        """Query with entropy-aware strategy selection.

        Uses graph topology entropy to determine the optimal retrieval
        strategy, complementing the keyword-based ``_route_query``
        heuristic with structural awareness.

        **Core idea** (Research #028: Entropy-Guided Branching):

        - **High entropy** (uniform graph structure, all edges similar)
          → ``basic`` keyword lookup.  The graph is regular enough that
          direct search suffices.
        - **Medium entropy** → ``hybrid`` SimHash + graph.  Moderate
          structural variation benefits from binary pre-filtering.
        - **Low entropy** (heterogeneous structure with hubs, clusters,
          bridges) → ``drift`` multi-hop.  Structural complexity requires
          exploratory traversal to capture multi-hop relationships.

        The entropy is computed from the chosen degree-based index
        (default: Sombor).  The profile range and std are also reported
        for transparency.

        When ``override_heuristic`` is True (default), the entropy-based
        mode takes precedence over the keyword heuristic — useful for
        graphs where structure matters more than question phrasing.
        When False, the heuristic runs first and entropy only adjusts
        the mode if the graph is extremely heterogeneous (top 10%).

        Args:
            question:            Natural-language query.
            limit:               Max results.
            entropy_index:       Which entropy index to use for routing
                                 (``"sombor"``, ``"randic"``, ``"abc"``,
                                 ``"ga"``, ``"zagreb_m1"``,
                                 ``"augmented_zagreb"``, ``"edge_betweenness"``).
            detail:              Include full node details.
            override_heuristic:  If True, entropy determines the mode.

        Returns:
            ``{question, mode, entropy_mode, heuristic_mode, entropy_analysis,
            results, stats}``
        """
        import time as _time

        # --- 1. Compute entropy -------------------------------
        index_map = {
            "sombor":            self.sombor_entropy,
            "reduced_sombor":    self.reduced_sombor_entropy,
            "randic":            self.randic_entropy,
            "zagreb_m1":         self.zagreb_m1_entropy,
            "abc":               self.abc_entropy,
            "ga":                self.ga_entropy,
            "augmented_zagreb":  self.augmented_zagreb_entropy,
            "edge_betweenness":  self.edge_betweenness_entropy,
        }
        entropy_fn = index_map.get(entropy_index)
        if entropy_fn is None:
            raise ValueError(
                f"Unknown entropy_index '{entropy_index}'. "
                f"Choose from: {', '.join(index_map)}"
            )

        entropy_val = entropy_fn(normalized=True)
        profile = self.entropy_profile()

        # --- 2. Classify into bin -----------------------------
        if entropy_val is None:
            # Not enough edges for entropy — fall back to heuristic
            entropy_val = 0.0
            entropy_bin = "low"
            bin_reason = "insufficient edges for entropy → default low"
        else:
            for bname, (lo, hi, _) in self._ENTROPY_ROUTE_BINS.items():
                if lo <= entropy_val < hi:
                    entropy_bin = bname
                    bin_reason = (
                        f"{entropy_index} entropy {entropy_val:.4f} "
                        f"∈ [{lo:.2f}, {hi:.2f}) → {bname}"
                    )
                    break
            else:
                entropy_bin = "high"
                bin_reason = f"{entropy_index} entropy {entropy_val:.4f} → high"

        _, _, entropy_mode = self._ENTROPY_ROUTE_BINS[entropy_bin]

        # --- 3. Get heuristic mode for comparison -------------
        heuristic_mode, heuristic_rationale = self._route_query(question)

        # --- 4. Decide final mode ----------------------------
        if override_heuristic:
            final_mode = entropy_mode
            decision = (
                f"entropy overrides heuristic: {entropy_bin} "
                f"({bin_reason})"
            )
        else:
            # Only override if entropy is very low (heterogeneous) and
            # heuristic picked a simple mode that misses complexity
            if entropy_bin == "low" and heuristic_mode in ("basic", "local"):
                final_mode = entropy_mode
                decision = (
                    f"entropy escalation: low entropy (heterogeneous) "
                    f"overrides heuristic '{heuristic_mode}' → '{entropy_mode}'"
                )
            else:
                final_mode = heuristic_mode
                decision = (
                    f"heuristic kept: '{heuristic_mode}' "
                    f"(entropy={entropy_bin}, not extreme enough to override)"
                )

        # --- 5. Execute query --------------------------------
        t0 = _time.perf_counter()
        raw = self.query(
            question, mode=final_mode, limit=limit, detail=detail,
        )
        elapsed_ms = (_time.perf_counter() - t0) * 1000

        # --- 6. Build entropy analysis report ----------------
        entropy_analysis = {
            "index": entropy_index,
            "value": round(entropy_val, 6),
            "bin": entropy_bin,
            "bin_reason": bin_reason,
            "recommended_mode": entropy_mode,
            "heuristic_mode": heuristic_mode,
            "heuristic_rationale": heuristic_rationale,
            "final_mode": final_mode,
            "decision": decision,
        }
        if profile:
            entropy_analysis["profile"] = {
                "min": round(profile["min"], 6),
                "max": round(profile["max"], 6),
                "range": round(profile["range"], 6),
                "mean": round(profile["mean"], 6),
                "std": round(profile["std"], 6),
                "most_heterogeneous": profile["most_heterogeneous"],
                "most_homogeneous": profile["most_homogeneous"],
            }

        return {
            "question": question,
            "mode": final_mode,
            "entropy_mode": entropy_mode,
            "heuristic_mode": heuristic_mode,
            "entropy_analysis": entropy_analysis,
            "results": raw.get("results", []),
            "stats": {
                **raw.get("stats", {}),
                "elapsed_ms": round(elapsed_ms, 2),
            },
        }


    # ----------------------------------------------------------------
    # Reasoning Quality Evaluation (MemOps + ActMem-inspired)
    # ----------------------------------------------------------------

    def reasoning_quality_eval(self, *, seed_ids: list[str] = None) -> dict:
        """Evaluate graph reasoning quality across structural metrics.

        Completes the evaluation trilogy:

        - :meth:`retrieval_quality_eval` — IR metrics (can we *find*?)
        - :meth:`lifecycle_operation_eval` — ops safety (can we *maintain*?)
        - :meth:`reasoning_quality_eval` — graph quality (can we *reason*?)

        Inspired by MemOps (arXiv:2607.12893) beyond-recall evaluation
        and ActMem (arXiv:2606.xxxxx) causal completeness analysis.

        Seven quality dimensions:

        1. **connectivity** — fraction of nodes reachable from seeds
           (or from the highest-degree node if no seeds given).
           Low connectivity → fragmented graph → poor multi-hop reasoning.
        2. **causal_chain_completeness** — of nodes with ``causes`` edges,
           what fraction form complete chains (head → … → tail with no
           orphans)?  Broken chains indicate missing intermediate nodes.
        3. **conflict_resolution_rate** — of all supersede chains, what
           fraction are resolved (superseded node still exists but marked)?
           Unresolved conflicts bias reasoning.
        4. **supersede_depth_stats** — descriptive stats on supersede
           chain lengths.  Deep chains (>5) indicate volatile facts;
           zero chains indicate static knowledge.
        5. **temporal_consistency** — for bi-temporal nodes (with
           ``valid_from``/``valid_to``), checks for gaps or overlaps
           within the same entity lineage.
        6. **community_coherence** — modularity score (Q) indicating
           whether the graph has meaningful community structure.
           High modularity → good for localised reasoning.
        7. **provenance_coverage** — fraction of nodes with ``source``
           or ``origin`` metadata.  Low coverage → untraceable reasoning.

        Args:
            seed_ids:  List of node IDs to use as reachability seeds.
                       If ``None``, uses the top-3 degree nodes.

        Returns:
            ``{overall_score, dimensions: {connectivity: {score, detail},
            causal_chain_completeness: {score, detail}, …},
            recommendations: [...]}``
        """
        import statistics as _stats

        dims: dict[str, dict] = {}
        recs: list[str] = []

        node_count = self.stats()["nodes"]

        # --- 1. Connectivity ---
        if node_count == 0:
            return {
                "overall_score": 0.0,
                "dimensions": {},
                "recommendations": ["Graph is empty."],
            }

        all_ids = [
            r["id"] for r in self.conn.execute(
                "SELECT id FROM nodes ORDER BY id"
            ).fetchall()
        ]
        all_id_set = set(all_ids)

        # Determine seeds
        if not seed_ids:
            degree_rows = self.conn.execute(
                "SELECT source FROM edges UNION ALL SELECT target FROM edges"
            ).fetchall()
            deg: dict[str, int] = {}
            for r in degree_rows:
                deg[r["source"]] = deg.get(r["source"], 0) + 1
            top_nodes = sorted(deg, key=deg.get, reverse=True)[:3]
            seeds = top_nodes if top_nodes else all_ids[:1]
        else:
            seeds = list(seed_ids)

        # BFS reachability from seeds
        visited: set[str] = set()
        queue = list(seeds)
        while queue:
            current = queue.pop(0)
            if current in visited:
                continue
            visited.add(current)
            for nb in self.neighbors(current):
                if nb.id not in visited:
                    queue.append(nb.id)

        connectivity_score = len(visited) / len(all_id_set) if all_id_set else 0.0
        dims["connectivity"] = {
            "score": round(connectivity_score, 4),
            "detail": f"{len(visited)}/{len(all_id_set)} nodes reachable from {len(seeds)} seeds",
        }
        if connectivity_score < 0.5:
            recs.append(
                "Low connectivity (<50%). Consider adding bridge edges "
                "between isolated clusters."
            )

        # --- 2. Causal chain completeness ---
        causal_edges = self.conn.execute(
            "SELECT source, target FROM edges WHERE relation='causes'"
        ).fetchall()
        if causal_edges:
            # Build adjacency for causal subgraph
            causal_adj: dict[str, list[str]] = {}
            causal_nodes: set[str] = set()
            for ce in causal_edges:
                causal_adj.setdefault(ce["source"], []).append(ce["target"])
                causal_nodes.add(ce["source"])
                causal_nodes.add(ce["target"])

            # Find chain heads (no incoming causes edge) and tails (no outgoing)
            has_incoming: set[str] = set()
            for ce in causal_edges:
                has_incoming.add(ce["target"])

            heads = causal_nodes - has_incoming
            tails = {n for n in causal_nodes if n not in causal_adj}

            # For each head, DFS to find chain end
            complete_chains = 0
            total_heads = 0
            for head in heads:
                total_heads += 1
                # DFS
                stack = [head]
                visited_causal: set[str] = set()
                reached_tail = False
                while stack:
                    node = stack.pop()
                    if node in visited_causal:
                        continue
                    visited_causal.add(node)
                    successors = causal_adj.get(node, [])
                    if not successors:
                        reached_tail = True
                    for s in successors:
                        if s not in visited_causal:
                            stack.append(s)
                if reached_tail:
                    complete_chains += 1

            causal_score = complete_chains / total_heads if total_heads else 1.0
            dims["causal_chain_completeness"] = {
                "score": round(causal_score, 4),
                "detail": f"{complete_chains}/{total_heads} causal chains complete "
                          f"({len(causal_nodes)} nodes, {len(causal_edges)} edges)",
            }
            if causal_score < 0.7:
                recs.append(
                    "Incomplete causal chains (<70%). Some causes lead to "
                    "dead ends — add intermediate effect nodes."
                )
        else:
            dims["causal_chain_completeness"] = {
                "score": 1.0,
                "detail": "No causal edges in graph (N/A)",
            }

        # --- 3. Conflict resolution rate ---
        # Supersede is tracked via edges with relation='superseded_by'
        supersede_edges = self.conn.execute(
            "SELECT source, target FROM edges WHERE relation='superseded_by'"
        ).fetchall()
        if supersede_edges:
            resolved = sum(
                1 for r in supersede_edges
                if self.get_node(r["source"]) is not None
            )
            conflict_score = resolved / len(supersede_edges)
            dims["conflict_resolution_rate"] = {
                "score": round(conflict_score, 4),
                "detail": f"{resolved}/{len(supersede_edges)} superseded nodes resolvable",
            }
            if conflict_score < 1.0:
                recs.append(
                    f"{len(supersede_edges) - resolved} superseded nodes "
                    "could not be found — possible data integrity issue."
                )
        else:
            dims["conflict_resolution_rate"] = {
                "score": 1.0,
                "detail": "No supersede chains (stable knowledge)",
            }

        # --- 4. Supersede depth stats ---
        chain_depths = []
        for r in supersede_edges:
            depth = 1
            current = r["target"]
            seen_chain: set[str] = {r["source"]}
            while current and current not in seen_chain:
                seen_chain.add(current)
                next_edge = self.conn.execute(
                    "SELECT target FROM edges WHERE source=? AND relation='superseded_by'",
                    (current,)
                ).fetchone()
                if not next_edge:
                    break
                depth += 1
                current = next_edge["target"]
            chain_depths.append(depth)

        if chain_depths:
            avg_depth = _stats.mean(chain_depths)
            max_depth = max(chain_depths)
            dims["supersede_depth_stats"] = {
                "score": round(min(1.0, 1.0 / max(avg_depth, 1)), 4),
                "detail": f"avg={avg_depth:.1f}, max={max_depth}, "
                          f"n={len(chain_depths)} chains",
            }
            if avg_depth > 3:
                recs.append(
                    f"High supersede depth (avg={avg_depth:.1f}). "
                    "Facts are volatile — consider merge or governance."
                )
        else:
            dims["supersede_depth_stats"] = {
                "score": 1.0,
                "detail": "No supersede chains",
            }

        # --- 5. Temporal consistency ---
        temporal_nodes = self.conn.execute(
            "SELECT id, valid_from, valid_to FROM nodes "
            "WHERE valid_from IS NOT NULL"
        ).fetchall()
        if temporal_nodes:
            # Group by supersede chain to check continuity
            consistent = 0
            for tn in temporal_nodes:
                vf = tn["valid_from"]
                vt = tn["valid_to"]
                if vf and vt and vt >= vf:
                    consistent += 1
                elif vf and not vt:
                    consistent += 1  # open-ended is fine
            temporal_score = consistent / len(temporal_nodes)
            dims["temporal_consistency"] = {
                "score": round(temporal_score, 4),
                "detail": f"{consistent}/{len(temporal_nodes)} temporal records valid",
            }
            if temporal_score < 1.0:
                recs.append(
                    "Temporal inconsistency detected — some valid_to "
                    "precedes valid_from."
                )
        else:
            dims["temporal_consistency"] = {
                "score": 1.0,
                "detail": "No bi-temporal nodes",
            }

        # --- 6. Community coherence ---
        try:
            communities = self.community_detect()
            # community_detect returns {node_id: community_label}
            if communities and len(set(communities.values())) > 1:
                mod = self.modularity(communities)
                dims["community_coherence"] = {
                    "score": round(min(1.0, mod), 4),
                    "detail": f"Q={mod:.4f}, {len(set(communities.values()))} communities",
                }
                if mod < 0.1:
                    recs.append(
                        "Low modularity (<0.1). Graph lacks clear community "
                        "structure — may affect localised reasoning."
                    )
            else:
                dims["community_coherence"] = {
                    "score": 0.0,
                    "detail": "Single community (no partition)",
                }
        except Exception:
            dims["community_coherence"] = {
                "score": 0.0,
                "detail": "Community detection unavailable",
            }

        # --- 7. Provenance coverage ---
        nodes_with_source = self.conn.execute(
            "SELECT COUNT(*) as c FROM nodes "
            "WHERE data LIKE '%source%' OR data LIKE '%origin%'"
        ).fetchone()["c"]
        provenance_score = nodes_with_source / len(all_ids) if all_ids else 0.0
        dims["provenance_coverage"] = {
            "score": round(provenance_score, 4),
            "detail": f"{nodes_with_source}/{len(all_ids)} nodes have source/origin metadata",
        }
        if provenance_score < 0.3:
            recs.append(
                "Low provenance coverage (<30%). Add source metadata "
                "to improve traceability."
            )

        # --- Overall score ---
        scores = [d["score"] for d in dims.values()]
        overall = _stats.mean(scores) if scores else 0.0

        if not recs:
            recs.append("All quality dimensions look healthy.")

        return {
            "overall_score": round(overall, 4),
            "dimensions": dims,
            "recommendations": recs,
        }

    # ── Information Density: PMI-based graph quality metric ────────

    def graph_information_density(self, *, node_ids: list[str] = None,
                                 edge_types: list[str] = None) -> dict:
        """Compute Pointwise Mutual Information (PMI) density of the memory graph.

        Inspired by PlugMem which uses PMI to measure whether memory
        connections carry genuine information or are merely structural noise.

        **PMI density** compares the actual edge-weight distribution against
        a maximum-entropy (uniform) baseline:

            PMI(w_ij) = log2( (w_ij * W_total) / (s_i * s_j) )

        where s_i, s_j are weighted degrees (strengths) of nodes
        *i* and *j*, and W_total is the sum of all edge weights.

        A graph where all edges have equal weight has PMI ≈ 0 for every
        edge (maximum entropy, no information differentiation).  Positive
        PMI means the edge is stronger than expected; negative means weaker.

        **Metrics returned:**

        - **mean_pmi**: Average PMI across all edges.
        - **positive_fraction**: Fraction of edges with PMI > 0.
        - **negative_fraction**: Fraction with PMI < 0.
        - **entropy**: Shannon entropy of the normalised edge-weight
          distribution (bits).  Maximum = log₂(N_edges).
        - **normalized_entropy**: entropy / log₂(N_edges), ∈ [0, 1].
          High → uniform (low information); Low → concentrated (high information).
        - **density**: Graph density = actual_edges / max_possible_edges.
        - **weighted_density**: Sum of edge weights / (N × (N-1) / 2).
        - **pmi_spread**: Standard deviation of PMI values (differentiation).
          Higher spread = more informative edge structure.
        - **information_score**: Composite: (1 - normalized_entropy) × density.
          ∈ [0, 1].  Summarises overall information density.
        - **edge_type_breakdown**: Per-edge-type PMI statistics.
        - **recommendations**: Actionable suggestions.

        Args:
            node_ids: Restrict analysis to a subgraph induced by these nodes.
                If None, analyses the entire graph.
            edge_types: Restrict to specific edge types (e.g. ``['causes',
                'relates_to']``).  If None, includes all edge types.

        Returns:
            Dict with the metrics described above.
        """
        # ── Gather edges ────────────────────────────────────────────
        query = "SELECT source, target, weight, relation FROM edges"
        conditions = []
        params: list = []

        if node_ids:
            placeholders = ",".join("?" * len(node_ids))
            conditions.append(f"source IN ({placeholders})")
            conditions.append(f"target IN ({placeholders})")
            params.extend(node_ids)
            params.extend(node_ids)

        if edge_types:
            placeholders = ",".join("?" * len(edge_types))
            conditions.append(f"relation IN ({placeholders})")
            params.extend(edge_types)

        if conditions:
            query += " WHERE " + " AND ".join(conditions)

        rows = self.conn.execute(query, params).fetchall()

        if len(rows) < 2:
            return {
                "mean_pmi": 0.0,
                "positive_fraction": 0.0,
                "negative_fraction": 0.0,
                "entropy": 0.0,
                "normalized_entropy": 0.0,
                "density": 0.0,
                "weighted_density": 0.0,
                "pmi_spread": 0.0,
                "information_score": 0.0,
                "node_count": 0,
                "edge_count": len(rows),
                "total_weight": 0.0,
                "edge_type_breakdown": {},
                "recommendations": [
                    "Insufficient edges for density analysis.",
                    "Add more connections to enable meaningful PMI computation.",
                ],
            }

        # ── Compute node strengths (weighted degrees) ──────────────
        strengths: dict[str, float] = {}
        total_weight = 0.0

        for row in rows:
            w = row["weight"] if row["weight"] is not None else 1.0
            w = max(w, 1e-10)  # avoid zero division
            strengths[row["source"]] = strengths.get(row["source"], 0.0) + w
            strengths[row["target"]] = strengths.get(row["target"], 0.0) + w
            total_weight += w

        if total_weight <= 0:
            total_weight = float(len(rows))

        # ── PMI per edge ────────────────────────────────────────────
        pmi_values = []
        pmi_by_type: dict[str, list[float]] = {}

        for row in rows:
            w = row["weight"] if row["weight"] is not None else 1.0
            w = max(w, 1e-10)
            s_i = strengths.get(row["source"], 1e-10)
            s_j = strengths.get(row["target"], 1e-10)

            # PMI: log2( (w_ij * W_total) / (s_i * s_j) )
            numerator = w * total_weight
            denominator = s_i * s_j
            if denominator > 0 and numerator > 0:
                pmi = math.log2(numerator / denominator)
            else:
                pmi = 0.0

            pmi_values.append(pmi)
            rel = row["relation"] or "default"
            pmi_by_type.setdefault(rel, []).append(pmi)

        # ── Shannon entropy of normalised weights ──────────────────
        raw_weights = [
            max(row["weight"] if row["weight"] is not None else 1.0, 1e-10)
            for row in rows
        ]
        w_sum = sum(raw_weights)
        if w_sum > 0:
            probs = [w / w_sum for w in raw_weights]
        else:
            probs = [1.0 / len(raw_weights)] * len(raw_weights)

        entropy = -sum(p * math.log2(p) for p in probs if p > 0)
        max_entropy = math.log2(len(rows)) if len(rows) > 1 else 1.0
        norm_entropy = entropy / max_entropy if max_entropy > 0 else 0.0

        # ── Graph density ───────────────────────────────────────────
        n_nodes = len(strengths)
        max_edges = n_nodes * (n_nodes - 1) / 2 if n_nodes > 1 else 1
        density = len(rows) / max_edges if max_edges > 0 else 0.0
        weighted_density = total_weight / max_edges if max_edges > 0 else 0.0

        # ── Aggregate metrics ───────────────────────────────────────
        mean_pmi = sum(pmi_values) / len(pmi_values) if pmi_values else 0.0
        positive = sum(1 for v in pmi_values if v > 0)
        negative = sum(1 for v in pmi_values if v < 0)
        total = len(pmi_values)

        # Standard deviation of PMI
        if total > 1:
            variance = sum((v - mean_pmi) ** 2 for v in pmi_values) / (total - 1)
            pmi_spread = math.sqrt(variance)
        else:
            pmi_spread = 0.0

        # Composite information score
        information_score = (1.0 - norm_entropy) * density if density > 0 else 0.0

        # Per-type breakdown
        type_breakdown = {}
        for rel, vals in pmi_by_type.items():
            if vals:
                type_breakdown[rel] = {
                    "count": len(vals),
                    "mean_pmi": round(sum(vals) / len(vals), 4),
                    "min": round(min(vals), 4),
                    "max": round(max(vals), 4),
                }

        # ── Recommendations ─────────────────────────────────────────
        recs = []
        if norm_entropy > 0.9:
            recs.append(
                "Edge weights are near-uniform (high entropy). "
                "Consider differentiating weights to improve routing."
            )
        if density < 0.1 and n_nodes > 10:
            recs.append(
                f"Low density ({density:.3f}) with {n_nodes} nodes. "
                "Graph is sparse — add connections to improve reachability."
            )
        if total > 0 and negative / total > 0.5:
            recs.append(
                f"{negative}/{total} edges have negative PMI "
                "(weaker than expected). Consider pruning or re-weighting."
            )
        if pmi_spread < 0.1 and total > 5:
            recs.append(
                "Very low PMI spread — all edges are structurally similar. "
                "Add typed/weighted edges for differentiation."
            )
        if information_score < 0.05:
            recs.append(
                f"Low information score ({information_score:.4f}). "
                "Graph stores little structural signal relative to size."
            )
        if not recs:
            recs.append(
                "Information density is healthy. "
                "Edge structure carries meaningful differentiation."
            )

        return {
            "mean_pmi": round(mean_pmi, 4),
            "positive_fraction": round(positive / total, 4) if total > 0 else 0.0,
            "negative_fraction": round(negative / total, 4) if total > 0 else 0.0,
            "entropy": round(entropy, 4),
            "normalized_entropy": round(norm_entropy, 4),
            "density": round(density, 4),
            "weighted_density": round(weighted_density, 4),
            "pmi_spread": round(pmi_spread, 4),
            "information_score": round(information_score, 4),
            "node_count": n_nodes,
            "edge_count": len(rows),
            "total_weight": round(total_weight, 4),
            "edge_type_breakdown": type_breakdown,
            "recommendations": recs,
        }


    def knowledge_gap_report(self, *, node_ids: list[str] = None,
                             max_gaps: int = 10,
                             min_score: float = 0.3) -> dict:
        """Identify structural gaps in the knowledge graph.

        Complements the evaluation quartet by answering: **where should we
        add connections?**  While ``graph_information_density`` measures
        overall information structure, this API pinpoints specific nodes
        and cluster boundaries that lack connections.

        **Sections returned:**

        - **orphan_nodes**: Nodes with degree ≤ 1 (isolated or barely
          connected).  These memories are effectively unreachable via
          graph traversal.
        - **isolated_clusters**: Connected components with fewer than 2
          cross-component bridge edges.  Each listed with member count,
          total weight, and average internal degree.
        - **bridge_opportunities**: Specific node pairs across cluster
          boundaries that, if connected, would most improve graph
          connectivity.  Scored by shared tags + combined weight.
        - **underconnected_hubs**: High-weight nodes (top 25th
          percentile) with surprisingly few edges (degree < median).
          These are "important but lonely" memories.
        - **gap_score**: 0-100 composite (100 = well-connected, 0 =
          severely gapped).  Combines orphan fraction, component count,
          and average degree.
        - **recommendations**: Prioritised action list.

        Args:
            node_ids: Restrict analysis to a subgraph.  If None,
                analyses the entire graph.
            max_gaps: Maximum bridge opportunities to return.
            min_score: Minimum bridge score to include (0-1).

        Returns:
            Dict with the sections described above.
        """
        import statistics

        # ── Gather nodes ───────────────────────────────────────────
        if node_ids is not None:
            placeholders = ",".join("?" * len(node_ids))
            node_rows = self.conn.execute(
                f"SELECT * FROM nodes WHERE id IN ({placeholders})", node_ids
            ).fetchall()
        else:
            node_rows = self.conn.execute("SELECT * FROM nodes").fetchall()

        if not node_rows:
            return {
                "orphan_nodes": [],
                "isolated_clusters": [],
                "bridge_opportunities": [],
                "underconnected_hubs": [],
                "gap_score": 100.0,
                "component_count": 0,
                "total_nodes": 0,
                "total_orphans": 0,
                "total_isolated_clusters": 0,
                "recommendations": ["Graph is empty — no gaps to detect."],
            }

        node_set = {r["id"] for r in node_rows}

        # ── Degree computation ─────────────────────────────────────
        degrees: dict[str, int] = {}
        for r in node_rows:
            nid = r["id"]
            out_n = self.conn.execute(
                "SELECT COUNT(*) c FROM edges WHERE source=?", (nid,)
            ).fetchone()["c"]
            in_n = self.conn.execute(
                "SELECT COUNT(*) c FROM edges WHERE target=?", (nid,)
            ).fetchone()["c"]
            degrees[nid] = out_n + in_n

        # ── Orphan nodes (degree ≤ 1) ──────────────────────────────
        orphans = []
        for r in node_rows:
            d = degrees.get(r["id"], 0)
            if d <= 1:
                orphans.append({
                    "node_id": r["id"],
                    "label": r["label"],
                    "kind": r["kind"],
                    "degree": d,
                    "weight": round(r["weight"] if r["weight"] else 0.0, 4),
                })
        orphans.sort(key=lambda x: x["weight"], reverse=True)

        # ── Connected components ───────────────────────────────────
        if node_ids is not None:
            # Subgraph components
            visited = set()
            components = []
            for nid in node_set:
                if nid in visited:
                    continue
                comp = []
                queue = [nid]
                while queue:
                    cur = queue.pop(0)
                    if cur in visited:
                        continue
                    visited.add(cur)
                    comp.append(cur)
                    for e in self.conn.execute(
                        "SELECT target FROM edges WHERE source=?", (cur,)
                    ).fetchall():
                        if e["target"] in node_set and e["target"] not in visited:
                            queue.append(e["target"])
                    for e in self.conn.execute(
                        "SELECT source FROM edges WHERE target=?", (cur,)
                    ).fetchall():
                        if e["source"] in node_set and e["source"] not in visited:
                            queue.append(e["source"])
                components.append(comp)
        else:
            components = self.find_components()

        # ── Isolated clusters ──────────────────────────────────────
        isolated = []
        if len(components) > 1:  # Only check for isolation when there are multiple components
            for i, comp in enumerate(components):
                if len(comp) <= 1:
                    continue
                # Count cross-component edges
                comp_set = set(comp)
                cross_edges = 0
                internal_edges = 0
                for nid in comp:
                    for e in self.conn.execute(
                        "SELECT target FROM edges WHERE source=?", (nid,)
                    ).fetchall():
                        if e["target"] in comp_set:
                            internal_edges += 1
                        else:
                            cross_edges += 1

                if cross_edges < 2:
                    total_weight = sum(
                        r["weight"] or 0.0
                        for r in node_rows
                        if r["id"] in comp_set
                    )
                    avg_deg = sum(degrees.get(n, 0) for n in comp) / len(comp)
                    isolated.append({
                        "component_id": i,
                        "size": len(comp),
                        "cross_edges": cross_edges,
                        "internal_edges": internal_edges,
                        "total_weight": round(total_weight, 4),
                        "avg_degree": round(avg_deg, 2),
                        "members": comp[:10],  # cap for readability
                    })

        isolated.sort(key=lambda x: x["size"], reverse=True)

        # ── Bridge opportunities ───────────────────────────────────
        # For each pair of components, find best node pair by shared tags
        bridges = []
        if len(components) > 1 and len(components) <= 50:
            # Build tag sets per node
            node_tags: dict[str, set[str]] = {}
            for r in node_rows:
                raw = r["tags"] if r["tags"] else ""
                tags = {t.strip() for t in raw.split(",") if t.strip()} if raw else set()
                node_tags[r["id"]] = tags

            # Sample top-weight node from each component (cap at 20 components)
            comp_reps = []
            for comp in components:
                if len(comp) == 0:
                    continue
                # Pick highest-weight node in component
                best = max(
                    comp,
                    key=lambda n: next(
                        (r["weight"] or 0.0 for r in node_rows if r["id"] == n), 0.0
                    ),
                )
                comp_reps.append((comp, best))

            for i in range(len(comp_reps)):
                for j in range(i + 1, len(comp_reps)):
                    comp_a, rep_a = comp_reps[i]
                    comp_b, rep_b = comp_reps[j]

                    # Compute bridge score
                    tags_a = node_tags.get(rep_a, set())
                    tags_b = node_tags.get(rep_b, set())
                    shared = tags_a & tags_b
                    tag_score = len(shared) / max(
                        len(tags_a | tags_b) if tags_a | tags_b else 1, 1
                    )

                    w_a = next(
                        (r["weight"] or 0.0 for r in node_rows if r["id"] == rep_a), 0.0
                    )
                    w_b = next(
                        (r["weight"] or 0.0 for r in node_rows if r["id"] == rep_b), 0.0
                    )
                    weight_score = min(w_a, w_b) / max(
                        max(w_a, w_b), 1.0
                    ) if max(w_a, w_b) > 0 else 0.0

                    bridge_score = 0.4 * tag_score + 0.6 * weight_score

                    if bridge_score >= min_score:
                        bridges.append({
                            "node_a": rep_a,
                            "node_b": rep_b,
                            "component_a_size": len(comp_a),
                            "component_b_size": len(comp_b),
                            "shared_tags": sorted(shared)[:5],
                            "score": round(bridge_score, 4),
                        })

        bridges.sort(key=lambda x: x["score"], reverse=True)
        bridges = bridges[:max_gaps]

        # ── Underconnected hubs ────────────────────────────────────
        weights = [r["weight"] or 0.0 for r in node_rows]
        if len(weights) >= 2:
            w_threshold = statistics.quantiles(weights, n=4)[2]  # 75th percentile
            degree_values = list(degrees.values())
            d_median = (
                statistics.median(degree_values) if degree_values else 0
            )
        elif weights:
            w_threshold = weights[0]
            d_median = statistics.median(degrees.values()) if degrees else 0
        else:
            w_threshold = 0
            d_median = 0

        underconnected = []
        for r in node_rows:
            w = r["weight"] or 0.0
            d = degrees.get(r["id"], 0)
            if w >= w_threshold and d < d_median and d >= 0:
                underconnected.append({
                    "node_id": r["id"],
                    "label": r["label"],
                    "kind": r["kind"],
                    "weight": round(w, 4),
                    "degree": d,
                    "gap": d_median - d,
                })

        underconnected.sort(key=lambda x: x["gap"], reverse=True)
        underconnected = underconnected[:20]  # cap

        # ── Gap score (0-100) ──────────────────────────────────────
        n_total = len(node_rows)
        orphan_ratio = len(orphans) / n_total if n_total > 0 else 0.0
        component_penalty = min(len(components) / max(n_total, 1), 1.0)
        avg_degree = sum(degrees.values()) / n_total if n_total > 0 else 0.0
        degree_factor = min(avg_degree / 4.0, 1.0)  # 4+ avg degree = full marks

        gap_score = 100.0 * (
            1.0
            - 0.35 * orphan_ratio
            - 0.30 * component_penalty
            - 0.35 * (1.0 - degree_factor)
        )
        gap_score = max(0.0, min(100.0, gap_score))

        # ── Recommendations ────────────────────────────────────────
        recs = []
        if orphans:
            recs.append(
                f"{len(orphans)} orphan nodes (degree ≤ 1). "
                f"Review and connect high-value ones."
            )
        if isolated:
            recs.append(
                f"{len(isolated)} isolated clusters with <2 cross-component edges. "
                f"Consider adding bridge edges between clusters."
            )
        if bridges:
            top_bridge = bridges[0]
            recs.append(
                f"Top bridge opportunity: {top_bridge['node_a']} ↔ {top_bridge['node_b']} "
                f"(score={top_bridge['score']}, shared tags: {top_bridge['shared_tags']})."
            )
        if underconnected:
            recs.append(
                f"{len(underconnected)} high-weight nodes with below-median degree. "
                f"These are important memories that lack connections."
            )
        if gap_score >= 80:
            recs.append("Overall graph connectivity is healthy.")
        elif gap_score >= 50:
            recs.append("Moderate gaps detected — focus on bridge edges.")
        else:
            recs.append(
                "Significant connectivity gaps — prioritize adding edges "
                "and reviewing orphaned content."
            )
        if not recs:
            recs.append("No significant gaps detected.")

        return {
            "orphan_nodes": orphans,
            "isolated_clusters": isolated,
            "bridge_opportunities": bridges,
            "underconnected_hubs": underconnected,
            "gap_score": round(gap_score, 2),
            "component_count": len(components),
            "total_nodes": n_total,
            "total_orphans": len(orphans),
            "total_isolated_clusters": len(isolated),
            "recommendations": recs,
        }

    def auto_heal_gaps(self, *,
                       max_heals: int = 10,
                       min_bridge_score: float = 0.3,
                       connect_orphans: bool = True,
                       orphan_strategy: str = "nearest",
                       dry_run: bool = False,
                       node_ids: list[str] = None) -> dict:
        """Auto-apply structural gap repairs suggested by knowledge_gap_report.

        The **act** half of the measure→diagnose→act loop opened by
        ``knowledge_gap_report()`` (cycle 265).  While the report
        *identifies* gaps, this API *fixes* them by adding edges.

        **Healing actions:**

        1. **Bridge connection** — For each bridge_opportunity from the
           gap report, add an edge between the two component-representative
           nodes (relation ``"bridged_to"``).  This merges isolated clusters.
        2. **Orphan rescue** — For each orphan node (degree ≤ 1), find the
           most similar non-orphan node and connect them.  Similarity is
           computed from shared tags and weight proximity.

        Args:
            max_heals: Maximum total healing actions (bridges + orphans).
            min_bridge_score: Minimum bridge-opportunity score to act on.
            connect_orphans: Whether to attempt orphan rescue.
            orphan_strategy: ``"nearest"`` connect to most-similar node;
                ``"hub"`` connect to highest-degree node.
            dry_run: If True, report what *would* be done without modifying.
            node_ids: Restrict analysis to a subgraph.

        Returns:
            Dict with:

            - **bridges_added**: List of ``{source, target, relation, score}``
            - **orphans_connected**: List of ``{orphan, connected_to, strategy, similarity}``
            - **total_heals**: Count of actions performed
            - **gap_score_before**: Gap score prior to healing
            - **gap_score_after**: Gap score after healing (unchanged if dry_run)
            - **actions**: Human-readable summary strings
            - **dry_run**: Whether this was a dry run
        """
        # ── Capture before-state ────────────────────────────────────
        report_before = self.knowledge_gap_report(
            node_ids=node_ids, max_gaps=max_heals, min_score=min_bridge_score
        )
        gap_before = report_before["gap_score"]

        bridges_added = []
        orphans_connected = []
        actions = []
        heals_used = 0

        # ── Helper: check if edge already exists ────────────────────
        def _edge_exists(src: str, tgt: str) -> bool:
            row = self.conn.execute(
                "SELECT 1 FROM edges WHERE source=? AND target=? "
                "UNION SELECT 1 FROM edges WHERE source=? AND target=?",
                (src, tgt, tgt, src),
            ).fetchone()
            return row is not None

        # ── 1. Bridge connections ──────────────────────────────────
        for bridge in report_before.get("bridge_opportunities", []):
            if heals_used >= max_heals:
                break
            if bridge["score"] < min_bridge_score:
                continue
            node_a = bridge["node_a"]
            node_b = bridge["node_b"]
            if _edge_exists(node_a, node_b):
                continue
            action = {
                "source": node_a,
                "target": node_b,
                "relation": "bridged_to",
                "score": bridge["score"],
                "shared_tags": bridge.get("shared_tags", []),
            }
            bridges_added.append(action)
            heals_used += 1
            if not dry_run:
                self.link(node_a, node_b, "bridged_to",
                          weight=round(bridge["score"], 4))
            actions.append(
                f"Bridge: {node_a} ↔ {node_b} "
                f"(score={bridge['score']:.3f})"
            )

        # ── 2. Orphan rescue ───────────────────────────────────────
        if connect_orphans and heals_used < max_heals:
            orphans = report_before.get("orphan_nodes", [])
            # Build degree map for all nodes (if not subgraph)
            all_degrees: dict[str, int] = {}
            for r in self.conn.execute("SELECT id FROM nodes").fetchall():
                nid = r["id"]
                out_c = self.conn.execute(
                    "SELECT COUNT(*) c FROM edges WHERE source=?", (nid,)
                ).fetchone()["c"]
                in_c = self.conn.execute(
                    "SELECT COUNT(*) c FROM edges WHERE target=?", (nid,)
                ).fetchone()["c"]
                all_degrees[nid] = out_c + in_c

            # Build tag sets for all nodes
            node_tags: dict[str, set[str]] = {}
            for r in self.conn.execute("SELECT id, tags FROM nodes").fetchall():
                raw = r["tags"] if r["tags"] else ""
                node_tags[r["id"]] = {
                    t.strip() for t in raw.split(",") if t.strip()
                } if raw else set()

            # Candidate connectors: non-orphan nodes
            non_orphan_ids = [
                nid for nid, deg in all_degrees.items()
                if deg > 1 and nid not in {o["node_id"] for o in orphans}
            ]

            for orphan in orphans:
                if heals_used >= max_heals:
                    break
                oid = orphan["node_id"]
                if not non_orphan_ids:
                    break

                if orphan_strategy == "hub":
                    # Connect to highest-degree node
                    target_id = max(non_orphan_ids,
                                    key=lambda n: all_degrees.get(n, 0))
                    similarity = 0.0
                else:
                    # "nearest": most similar by Jaccard tags + weight proximity
                    o_tags = node_tags.get(oid, set())
                    o_weight = orphan.get("weight", 0.0)

                    best_id = None
                    best_sim = -1.0
                    for cand in non_orphan_ids:
                        c_tags = node_tags.get(cand, set())
                        # Jaccard similarity
                        if o_tags or c_tags:
                            tag_sim = len(o_tags & c_tags) / len(o_tags | c_tags)
                        else:
                            tag_sim = 0.0
                        # Weight proximity (stored in nodes)
                        c_weight = self.conn.execute(
                            "SELECT weight FROM nodes WHERE id=?", (cand,)
                        ).fetchone()
                        c_w = c_weight["weight"] if c_weight and c_weight["weight"] else 0.0
                        weight_sim = 1.0 - min(abs(o_weight - c_w) / max(o_weight, c_w, 1.0), 1.0)
                        sim = 0.6 * tag_sim + 0.4 * weight_sim
                        if sim > best_sim:
                            best_sim = sim
                            best_id = cand
                    target_id = best_id
                    similarity = round(best_sim, 4)

                if target_id is None or _edge_exists(oid, target_id):
                    continue

                rescue = {
                    "orphan": oid,
                    "connected_to": target_id,
                    "strategy": orphan_strategy,
                    "similarity": similarity,
                }
                orphans_connected.append(rescue)
                heals_used += 1
                if not dry_run:
                    self.link(oid, target_id, "rescued_to",
                              weight=round(max(similarity, 0.1), 4))
                actions.append(
                    f"Orphan rescue: {oid} → {target_id} "
                    f"({orphan_strategy}, sim={similarity:.3f})"
                )

        # ── Capture after-state ────────────────────────────────────
        if not dry_run and heals_used > 0:
            gap_after = self.knowledge_gap_report(
                node_ids=node_ids
            )["gap_score"]
        else:
            gap_after = gap_before

        return {
            "bridges_added": bridges_added,
            "orphans_connected": orphans_connected,
            "total_heals": heals_used,
            "gap_score_before": gap_before,
            "gap_score_after": gap_after,
            "gap_delta": round(gap_after - gap_before, 2),
            "actions": actions,
            "dry_run": dry_run,
        }


    def redundancy_detect(self, *,
                          node_ids: list[str] = None,
                          max_pairs: int = 10,
                          content_threshold: float = 0.65,
                          structural_threshold: float = 0.6,
                          ) -> dict:
        """Detect redundant nodes in the knowledge graph.

        Complements ``knowledge_gap_report`` by answering the opposite
        question: **where is there too much overlap?**  While gaps indicate
        missing connections, redundancy indicates noise that dilutes signal.

        **Three detection dimensions:**

        1. **content_duplicates**: Node pairs whose labels are highly similar
           (trigram Jaccard ≥ ``content_threshold``).  These nodes likely
           express the same information.
        2. **structural_clones**: Node pairs that share most of their neighbors
           (Jaccard of neighbour sets ≥ ``structural_threshold``).  Even if
           content differs, these nodes play identical structural roles.
        3. **functional_duplicates**: Same ``kind`` + similar weight (within
           20%) + similar degree (within 1).  These nodes serve the same
           function in the graph topology.

        **Returns:**

        - **content_duplicates**: ``[{node_a, node_b, label_a, label_b, similarity}]``
        - **structural_clones**: ``[{node_a, node_b, jaccard, shared_count, total_neighbors}]``
        - **functional_duplicates**: ``[{node_a, node_b, kind, weight_diff, degree_diff}]``
        - **redundancy_score**: 0-100 (100 = highly redundant, 0 = no redundancy).
          Computed as a weighted blend of the three dimensions.
        - **merge_candidates**: Top recommended merge pairs, sorted by combined
          score across all three dimensions.
        - **recommendations**: Human-readable action items.

        Args:
            node_ids: Restrict analysis to a subgraph.  If None, analyses
                the entire graph.
            max_pairs: Maximum pairs to return per category.
            content_threshold: Minimum trigram similarity for content duplicates.
            structural_threshold: Minimum Jaccard for structural clones.
        """
        # ── Gather nodes ───────────────────────────────────────────
        if node_ids is not None:
            placeholders = ",".join("?" * len(node_ids))
            node_rows = self.conn.execute(
                f"SELECT * FROM nodes WHERE id IN ({placeholders})", node_ids
            ).fetchall()
        else:
            node_rows = self.conn.execute("SELECT * FROM nodes").fetchall()

        if len(node_rows) < 2:
            return {
                "content_duplicates": [],
                "structural_clones": [],
                "functional_duplicates": [],
                "redundancy_score": 0.0,
                "merge_candidates": [],
                "total_nodes": len(node_rows),
                "recommendations": ["Not enough nodes for redundancy analysis (need ≥2)."],
            }

        ids = [r["id"] for r in node_rows]
        n = len(node_rows)

        # ── Pre-compute neighbour sets, tags, degrees ──────────────
        nbrs: dict[str, set[str]] = {}
        tags_map: dict[str, set[str]] = {}
        degrees: dict[str, int] = {}

        for r in node_rows:
            nid = r["id"]
            out_e = self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION "
                "SELECT source FROM edges WHERE target=?",
                (nid, nid),
            ).fetchall()
            nbrs[nid] = {e[0] for e in out_e}
            degrees[nid] = len(nbrs[nid])
            raw_tags = r["tags"] if r["tags"] else ""
            tags_map[nid] = {
                t.strip() for t in raw_tags.split(",") if t.strip()
            } if raw_tags else set()

        # ── 1. Content duplicates (trigram Jaccard) ────────────────
        content_dups = []
        for i in range(n):
            for j in range(i + 1, n):
                sim = self._content_similarity(
                    node_rows[i]["label"], node_rows[j]["label"]
                )
                if sim >= content_threshold:
                    content_dups.append({
                        "node_a": node_rows[i]["id"],
                        "node_b": node_rows[j]["id"],
                        "label_a": node_rows[i]["label"],
                        "label_b": node_rows[j]["label"],
                        "similarity": round(sim, 4),
                    })
        content_dups.sort(key=lambda x: x["similarity"], reverse=True)
        content_dups = content_dups[:max_pairs]

        # ── 2. Structural clones (neighbour Jaccard) ───────────────
        struct_clones = []
        for i in range(n):
            for j in range(i + 1, n):
                a_id, b_id = ids[i], ids[j]
                na, nb = nbrs[a_id], nbrs[b_id]
                if not na and not nb:
                    continue
                union = na | nb
                if not union:
                    continue
                jac = len(na & nb) / len(union)
                if jac >= structural_threshold:
                    struct_clones.append({
                        "node_a": a_id,
                        "node_b": b_id,
                        "jaccard": round(jac, 4),
                        "shared_count": len(na & nb),
                        "total_neighbors": len(union),
                    })
        struct_clones.sort(key=lambda x: x["jaccard"], reverse=True)
        struct_clones = struct_clones[:max_pairs]

        # ── 3. Functional duplicates (same kind + similar metrics) ─
        func_dups = []
        for i in range(n):
            for j in range(i + 1, n):
                ri, rj = node_rows[i], node_rows[j]
                if ri["kind"] != rj["kind"]:
                    continue
                if not ri["kind"]:
                    continue  # skip untyped nodes
                w1 = ri["weight"] if ri["weight"] else 1.0
                w2 = rj["weight"] if rj["weight"] else 1.0
                w_diff = abs(w1 - w2)
                w_max = max(w1, w2, 0.001)
                if w_diff / w_max > 0.2:
                    continue
                d1, d2 = degrees[ri["id"]], degrees[rj["id"]]
                if abs(d1 - d2) > 1:
                    continue
                func_dups.append({
                    "node_a": ri["id"],
                    "node_b": rj["id"],
                    "kind": ri["kind"],
                    "weight_diff": round(w_diff, 4),
                    "degree_diff": abs(d1 - d2),
                })
        func_dups = func_dups[:max_pairs]

        # ── 4. Redundancy score (0-100) ────────────────────────────
        possible_pairs = n * (n - 1) / 2
        content_ratio = len(content_dups) / possible_pairs if possible_pairs else 0
        struct_ratio = len(struct_clones) / possible_pairs if possible_pairs else 0
        func_ratio = len(func_dups) / possible_pairs if possible_pairs else 0
        # Weighted blend: content heaviest (40%), structural (35%), functional (25%)
        redundancy_score = round(
            min(100, 40 * content_ratio * 5 + 35 * struct_ratio * 5 + 25 * func_ratio * 5),
            2,
        )

        # ── 5. Merge candidates (cross-dimensional ranking) ────────
        pair_scores: dict[tuple[str, str], dict] = {}
        for dup in content_dups:
            key = tuple(sorted([dup["node_a"], dup["node_b"]]))
            pair_scores.setdefault(key, {"content": 0, "structural": 0, "functional": 0})
            pair_scores[key]["content"] = dup["similarity"]
        for sc in struct_clones:
            key = tuple(sorted([sc["node_a"], sc["node_b"]]))
            pair_scores.setdefault(key, {"content": 0, "structural": 0, "functional": 0})
            pair_scores[key]["structural"] = sc["jaccard"]
        for fd in func_dups:
            key = tuple(sorted([fd["node_a"], fd["node_b"]]))
            pair_scores.setdefault(key, {"content": 0, "structural": 0, "functional": 0})
            pair_scores[key]["functional"] = 1.0  # binary signal

        merge_candidates = []
        for (a, b), scores in pair_scores.items():
            combined = (
                0.40 * scores["content"]
                + 0.35 * scores["structural"]
                + 0.25 * scores["functional"]
            )
            if combined > 0:
                merge_candidates.append({
                    "node_a": a,
                    "node_b": b,
                    "content_score": round(scores["content"], 4),
                    "structural_score": round(scores["structural"], 4),
                    "functional_score": round(scores["functional"], 4),
                    "combined_score": round(combined, 4),
                })
        merge_candidates.sort(key=lambda x: x["combined_score"], reverse=True)
        merge_candidates = merge_candidates[:max_pairs]

        # ── 6. Recommendations ─────────────────────────────────────
        recommendations = []
        if content_dups:
            top = content_dups[0]
            recommendations.append(
                f"🔴 Content duplicate: '{top['label_a']}' ≈ '{top['label_b']}' "
                f"(similarity={top['similarity']:.2f}). Consider merge_nodes()."
            )
        if struct_clones:
            top = struct_clones[0]
            recommendations.append(
                f"🟠 Structural clone: {top['node_a']} ↔ {top['node_b']} "
                f"(Jaccard={top['jaccard']:.2f}, {top['shared_count']} shared neighbours). "
                f"Consider if both are needed."
            )
        if func_dups:
            recommendations.append(
                f"🟡 {len(func_dups)} functional duplicate pair(s) with same kind. "
                f"Review for potential consolidation."
            )
        if merge_candidates:
            top = merge_candidates[0]
            recommendations.append(
                f"💡 Top merge candidate: {top['node_a']} + {top['node_b']} "
                f"(combined={top['combined_score']:.2f})."
            )
        if not recommendations:
            recommendations.append("✅ No significant redundancy detected.")

        # Severity classification
        if redundancy_score >= 40:
            recommendations.insert(0, f"⚠️ High redundancy ({redundancy_score}/100). Prioritise merging.")
        elif redundancy_score >= 15:
            recommendations.insert(0, f"📉 Moderate redundancy ({redundancy_score}/100).")
        else:
            recommendations.insert(0, f"✅ Low redundancy ({redundancy_score}/100).")

        return {
            "content_duplicates": content_dups,
            "structural_clones": struct_clones,
            "functional_duplicates": func_dups,
            "redundancy_score": redundancy_score,
            "merge_candidates": merge_candidates,
            "total_nodes": n,
            "total_pairs_checked": int(possible_pairs),
            "recommendations": recommendations,
        }

    def gap_redundancy_balance(self, *,
                               node_ids: list[str] = None,
                               gap_weight: float = 0.5,
                               redundancy_weight: float = 0.5,
                               ) -> dict:
        """Unified dual-loop health metric combining gap and redundancy scores.

        Fuses ``knowledge_gap_report`` (missing connections) and
        ``redundancy_detect`` (excess overlap) into a single actionable
        assessment.  This is the capstone of the dual-loop quality system:

        - **Loop 1 — Gap analysis**: ``knowledge_gap_report`` → ``auto_heal_gaps``
        - **Loop 2 — Redundancy analysis**: ``redundancy_detect`` → (future merge)
        - **Synthesis**: this method → single health score + action priority

        **Scoring model:**

        - ``health_score = 100 - w_gap * (100 - gap_score) - w_red * redundancy_score``
        - Weights are auto-normalised to sum to 1.0.
        - ``balance_ratio`` ∈ [-1, 1]: negative = gap-dominated, positive =
          redundancy-dominated, ≈0 = balanced.

        **Verdicts:**

        - ``empty`` — graph has no nodes.
        - ``healthy`` — health ≥ 80, no dominant issue.
        - ``good`` — health ≥ 65, minor issues.
        - ``gap-heavy`` — gaps are the primary drag on health.
        - ``redundancy-heavy`` — redundancy is the primary drag.
        - ``balanced-issues`` — both gap and redundancy are significant.

        Args:
            node_ids: Restrict analysis to a subgraph.  If None, analyses
                the entire graph.
            gap_weight: Weight for gap penalty (default 0.5).
            redundancy_weight: Weight for redundancy penalty (default 0.5).

        Returns:
            Dict with keys: health_score, gap_score, redundancy_score,
            verdict, dominant_issue, balance_ratio, action_priority,
            summary, recommendations.
        """
        # ── Run both analyses ──────────────────────────────────────
        gap_report = self.knowledge_gap_report(node_ids=node_ids)
        redundancy_report = self.redundancy_detect(node_ids=node_ids)

        gap_score = gap_report["gap_score"]
        redundancy_score = redundancy_report["redundancy_score"]
        n_nodes = gap_report.get("total_nodes", 0)

        # ── Empty graph ────────────────────────────────────────────
        if n_nodes == 0:
            return {
                "health_score": 100.0,
                "gap_score": 100.0,
                "redundancy_score": 0.0,
                "verdict": "empty",
                "dominant_issue": "none",
                "balance_ratio": 0.0,
                "action_priority": "none",
                "summary": "Graph is empty — no issues to detect.",
                "recommendations": ["Add nodes to begin building the knowledge graph."],
            }

        # ── Normalise weights ──────────────────────────────────────
        w_sum = gap_weight + redundancy_weight
        if w_sum <= 0:
            w_gap, w_red = 0.5, 0.5
        else:
            w_gap = gap_weight / w_sum
            w_red = redundancy_weight / w_sum

        # ── Health score ───────────────────────────────────────────
        # gap_score: 100 = good, 0 = bad → penalty = (100 - gap_score)
        # redundancy_score: 100 = bad, 0 = good → penalty = redundancy_score
        gap_penalty = 100.0 - gap_score
        redundancy_penalty = redundancy_score
        health_score = 100.0 - (w_gap * gap_penalty + w_red * redundancy_penalty)
        health_score = max(0.0, min(100.0, round(health_score, 2)))

        # ── Balance ratio (-1 to +1) ───────────────────────────────
        total_penalty = gap_penalty + redundancy_penalty
        if total_penalty > 0:
            balance_ratio = round((redundancy_penalty - gap_penalty) / total_penalty, 4)
        else:
            balance_ratio = 0.0

        # ── Dominant issue ─────────────────────────────────────────
        if total_penalty < 5.0:
            dominant_issue = "none"
        elif gap_penalty > redundancy_penalty * 1.5:
            dominant_issue = "gap"
        elif redundancy_penalty > gap_penalty * 1.5:
            dominant_issue = "redundancy"
        else:
            dominant_issue = "balanced-issues"

        # ── Action priority ────────────────────────────────────────
        if total_penalty < 5.0:
            action_priority = "none"
        elif dominant_issue == "gap":
            action_priority = "gap"
        elif dominant_issue == "redundancy":
            action_priority = "redundancy"
        else:
            action_priority = "both"

        # ── Verdict ────────────────────────────────────────────────
        if health_score >= 80:
            verdict = "healthy"
        elif health_score >= 65:
            verdict = "good"
        elif dominant_issue == "gap":
            verdict = "gap-heavy"
        elif dominant_issue == "redundancy":
            verdict = "redundancy-heavy"
        else:
            verdict = "balanced-issues"

        # ── Summary ────────────────────────────────────────────────
        summary = (
            f"Health={health_score:.1f}/100 "
            f"(gap={gap_score:.1f}, redundancy={redundancy_score:.1f}). "
        )
        if action_priority == "none":
            summary += "Graph quality is good — no urgent action needed."
        elif action_priority == "gap":
            summary += "Primary concern: knowledge gaps. Add connections to improve reachability."
        elif action_priority == "redundancy":
            summary += "Primary concern: redundancy. Merge similar nodes to reduce noise."
        else:
            summary += "Both gaps and redundancy need attention. Address the larger penalty first."

        # ── Recommendations ────────────────────────────────────────
        recommendations = []

        # Carry over top gap recommendation (if gap-driven)
        if action_priority in ("gap", "both"):
            for rec in gap_report.get("recommendations", []):
                recommendations.append(f"[gap] {rec}")
                if len(recommendations) >= 3:
                    break

        # Carry over top redundancy recommendation (if redundancy-driven)
        if action_priority in ("redundancy", "both"):
            for rec in redundancy_report.get("recommendations", []):
                recommendations.append(f"[redundancy] {rec}")
                if len(recommendations) >= 5:
                    break

        # Add balance recommendation if applicable
        if abs(balance_ratio) > 0.5 and action_priority != "none":
            if balance_ratio > 0:
                recommendations.append(
                    f"⚠️ Redundancy significantly outweighs gaps "
                    f"(ratio={balance_ratio:+.2f}). Focus on merging."
                )
            else:
                recommendations.append(
                    f"⚠️ Gaps significantly outweigh redundancy "
                    f"(ratio={balance_ratio:+.2f}). Focus on connecting."
                )

        if not recommendations:
            recommendations.append("✅ Graph quality is well-balanced. No urgent action needed.")

        return {
            "health_score": health_score,
            "gap_score": round(gap_score, 2),
            "redundancy_score": round(redundancy_score, 2),
            "verdict": verdict,
            "dominant_issue": dominant_issue,
            "balance_ratio": balance_ratio,
            "action_priority": action_priority,
            "summary": summary,
            "recommendations": recommendations,
        }

    # ════════════════════════════════════════════════════════════
    #  CYCLE 269 — auto_consolidate()
    #  Redundancy act-loop: detect → consolidate (mirrors gap loop)
    # ════════════════════════════════════════════════════════════

    def auto_consolidate(self, *,                        # noqa: C901
                         max_merges: int = 5,
                         min_score: float = 0.5,
                         content_threshold: float = 0.65,
                         structural_threshold: float = 0.6,
                         dry_run: bool = False,
                         node_ids: list[str] = None) -> dict:
        """Auto-merge top redundancy candidates identified by ``redundancy_detect``.

        The **act** half of the detect→consolidate redundancy loop,
        mirroring ``auto_heal_gaps()`` for the gap loop.

        While ``redundancy_detect`` *identifies* excess overlap, this API
        *fixes* it by merging node pairs — choosing the higher-degree node
        as the merge target (survivor) in each pair.

        **Merge strategy:**

        1. Run ``redundancy_detect`` with the given thresholds.
        2. Filter ``merge_candidates`` by ``min_score``.
        3. For each candidate (up to ``max_merges``), merge the
           lower-degree node into the higher-degree node using
           ``merge_nodes()``.
        4. Skip pairs where either node was already merged in this run.

        **Non-mutating fields returned when** ``dry_run=True``:
        All actions are simulated; no nodes are actually merged.

        Args:
            max_merges: Maximum number of merge operations.
            min_score: Minimum combined merge-score to act on (0–1).
            content_threshold: Passed through to ``redundancy_detect``.
            structural_threshold: Passed through to ``redundancy_detect``.
            dry_run: If True, report what *would* be done without modifying.
            node_ids: Restrict analysis to a subgraph.

        Returns:
            Dict with:

            - **merges_performed**: List of ``{source, target, score,
              content_sim, structural_sim, functional_dup, reason}``
            - **total_merges**: Count of merges performed
            - **redundancy_score_before**: Redundancy score prior to action
            - **redundancy_score_after**: Redundancy score after (same as
              before if ``dry_run``)
            - **nodes_before / nodes_after**: Node counts
            - **actions**: Human-readable summary strings
            - **dry_run**: Whether this was a dry run
            - **skipped**: Pairs skipped (already merged or below threshold)
        """
        # ── Capture before-state ────────────────────────────────────
        report_before = self.redundancy_detect(
            node_ids=node_ids,
            max_pairs=max_merges * 3,  # fetch more, filter later
            content_threshold=content_threshold,
            structural_threshold=structural_threshold,
        )
        redundancy_before = report_before["redundancy_score"]
        nodes_before = report_before["total_nodes"]

        merges_performed = []
        actions = []
        skipped = []
        merged_nodes: set[str] = set()  # track consumed node ids
        merges_used = 0

        candidates = report_before.get("merge_candidates", [])

        for cand in candidates:
            if merges_used >= max_merges:
                break

            combined_score = cand.get("combined_score", 0.0)
            if combined_score < min_score:
                skipped.append({
                    "node_a": cand["node_a"],
                    "node_b": cand["node_b"],
                    "reason": f"score {combined_score:.3f} < {min_score}",
                })
                continue

            node_a = cand["node_a"]
            node_b = cand["node_b"]

            # Skip if either node was already merged in this run
            if node_a in merged_nodes or node_b in merged_nodes:
                skipped.append({
                    "node_a": node_a,
                    "node_b": node_b,
                    "reason": "node already merged in this run",
                })
                continue

            # Determine merge direction: lower-degree → higher-degree
            deg_a = self._node_degree(node_a)
            deg_b = self._node_degree(node_b)

            if deg_a >= deg_b:
                source, target = node_b, node_a
            else:
                source, target = node_a, node_b

            # Build action record
            content_sim = cand.get("content_score", 0.0)
            structural_sim = cand.get("structural_score", 0.0)
            functional_dup = cand.get("functional_score", 0.0)

            # Determine primary reason
            dims = [
                ("content", content_sim),
                ("structural", structural_sim),
                ("functional", functional_dup),
            ]
            dims.sort(key=lambda x: x[1], reverse=True)
            reason = f"{dims[0][0]}-dominated ({dims[0][1]:.3f})"

            action = {
                "source": source,
                "target": target,
                "score": round(combined_score, 4),
                "content_sim": round(content_sim, 4),
                "structural_sim": round(structural_sim, 4),
                "functional_dup": round(functional_dup, 4),
                "reason": reason,
            }
            merges_performed.append(action)
            merged_nodes.add(source)
            merged_nodes.add(target)
            merges_used += 1

            if not dry_run:
                self.merge_nodes(source, target)

            actions.append(
                f"Merge: {source} → {target} "
                f"(score={combined_score:.3f}, {reason})"
            )

        # ── Capture after-state ────────────────────────────────────
        if not dry_run and merges_used > 0:
            report_after = self.redundancy_detect(
                node_ids=node_ids,
                max_pairs=10,
                content_threshold=content_threshold,
                structural_threshold=structural_threshold,
            )
            redundancy_after = report_after["redundancy_score"]
            nodes_after = report_after["total_nodes"]
        else:
            redundancy_after = redundancy_before
            nodes_after = nodes_before - merges_used if not dry_run else nodes_before

        return {
            "merges_performed": merges_performed,
            "total_merges": merges_used,
            "redundancy_score_before": round(redundancy_before, 2),
            "redundancy_score_after": round(redundancy_after, 2),
            "nodes_before": nodes_before,
            "nodes_after": nodes_after,
            "actions": actions,
            "dry_run": dry_run,
            "skipped": skipped,
        }

    def _node_degree(self, node_id: str) -> int:
        """Return the total degree (in + out) of a node."""
        out_c = self.conn.execute(
            "SELECT COUNT(*) c FROM edges WHERE source=?", (node_id,)
        ).fetchone()["c"]
        in_c = self.conn.execute(
            "SELECT COUNT(*) c FROM edges WHERE target=?", (node_id,)
        ).fetchone()["c"]
        return out_c + in_c

    # ─────────────────────────────────────────────────────────────
    # Cycle 271: Semantic cluster detection — group-level redundancy
    # ─────────────────────────────────────────────────────────────

    def semantic_cluster_detect(self, *,                                # noqa: C901
                                node_ids: list[str] = None,
                                min_cluster_size: int = 3,
                                content_threshold: float = 0.55,
                                structural_threshold: float = 0.5,
                                ) -> dict:
        """Detect clusters of N+ semantically similar nodes.

        While ``redundancy_detect`` finds *pairs* of redundant nodes,
        this API finds entire **clusters** of nodes that are all similar
        to each other — enabling batch consolidation decisions.

        **Two clustering approaches:**

        1. **Content clusters** — Groups of nodes whose labels are mutually
           similar (trigram Jaccard ≥ ``content_threshold``).  Uses
           single-linkage agglomerative clustering: two clusters merge
           if *any* cross-pair exceeds the threshold.

        2. **Structural clusters** — Groups of nodes that share most
           neighbours (Jaccard ≥ ``structural_threshold``), indicating
           they occupy the same structural niche.

        **Returns:**

        - **content_clusters**: List of cluster dicts, each with
          ``members``, ``size``, ``avg_similarity``, ``representative``
          (highest-degree node), and ``labels``.
        - **structural_clusters**: Same format for structural groups.
        - **combined_clusters**: Clusters that are significant in *both*
          dimensions — prime consolidation candidates.
        - **cluster_score**: 0-100 indicating overall cluster redundancy.
        - **recommendations**: Actionable suggestions.

        Args:
            node_ids: Restrict analysis to a subgraph.
            min_cluster_size: Minimum nodes to form a cluster (default 3).
            content_threshold: Minimum trigram similarity for content edges.
            structural_threshold: Minimum Jaccard for structural edges.
        """
        # ── Gather nodes ───────────────────────────────────────────
        if node_ids is not None:
            placeholders = ",".join("?" * len(node_ids))
            node_rows = self.conn.execute(
                f"SELECT * FROM nodes WHERE id IN ({placeholders})", node_ids
            ).fetchall()
        else:
            node_rows = self.conn.execute("SELECT * FROM nodes").fetchall()

        n = len(node_rows)
        if n < min_cluster_size:
            return {
                "content_clusters": [],
                "structural_clusters": [],
                "combined_clusters": [],
                "cluster_score": 0.0,
                "total_nodes": n,
                "recommendations": [
                    f"Not enough nodes for cluster analysis "
                    f"(need ≥{min_cluster_size}, got {n})."
                ],
            }

        ids = [r["id"] for r in node_rows]

        # ── Pre-compute neighbour sets and degrees ─────────────────
        nbrs: dict[str, set[str]] = {}
        degrees: dict[str, int] = {}
        for r in node_rows:
            nid = r["id"]
            out_e = self.conn.execute(
                "SELECT target FROM edges WHERE source=? UNION "
                "SELECT source FROM edges WHERE target=?",
                (nid, nid),
            ).fetchall()
            nbrs[nid] = {e[0] for e in out_e}
            degrees[nid] = len(nbrs[nid])

        # ── Helper: union-find for single-linkage clustering ───────
        parent: dict[str, str] = {nid: nid for nid in ids}

        def find(x: str) -> str:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: str, b: str) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # ── 1. Content clusters via single-linkage ─────────────────
        content_parent = dict(parent)  # fresh copy
        content_edges: list[tuple[str, str, float]] = []

        for i in range(n):
            for j in range(i + 1, n):
                sim = self._content_similarity(
                    node_rows[i]["label"], node_rows[j]["label"]
                )
                if sim >= content_threshold:
                    content_edges.append((ids[i], ids[j], sim))

        # Reset parent for content clustering
        parent = {nid: nid for nid in ids}
        for a, b, _ in content_edges:
            union(a, b)

        # Collect content clusters
        content_groups: dict[str, list[str]] = {}
        for nid in ids:
            root = find(nid)
            content_groups.setdefault(root, []).append(nid)

        content_clusters_raw = [
            grp for grp in content_groups.values()
            if len(grp) >= min_cluster_size
        ]

        # Build content cluster details
        content_clusters = []
        for grp in content_clusters_raw:
            # Compute average pairwise similarity within cluster
            sims = []
            for i in range(len(grp)):
                for j in range(i + 1, len(grp)):
                    ni = self.get_node(grp[i])
                    nj = self.get_node(grp[j])
                    if ni and nj:
                        s = self._content_similarity(ni.label, nj.label)
                        sims.append(s)
            avg_sim = sum(sims) / len(sims) if sims else 0.0

            # Representative = highest-degree node
            rep = max(grp, key=lambda x: degrees.get(x, 0))
            rep_node = self.get_node(rep)

            label_list = []
            for nid in grp:
                node = self.get_node(nid)
                if node:
                    label_list.append(node.label)

            content_clusters.append({
                "members": list(grp),
                "size": len(grp),
                "avg_similarity": round(avg_sim, 4),
                "representative": rep,
                "representative_label": rep_node.label if rep_node else "",
                "labels": label_list,
                "total_degree": sum(degrees.get(nid, 0) for nid in grp),
            })

        content_clusters.sort(key=lambda x: x["avg_similarity"], reverse=True)

        # ── 2. Structural clusters via single-linkage ──────────────
        struct_edges: list[tuple[str, str, float]] = []
        for i in range(n):
            for j in range(i + 1, n):
                a_id, b_id = ids[i], ids[j]
                na, nb = nbrs[a_id], nbrs[b_id]
                if not na and not nb:
                    continue
                union_set = na | nb
                if not union_set:
                    continue
                jac = len(na & nb) / len(union_set)
                if jac >= structural_threshold:
                    struct_edges.append((a_id, b_id, jac))

        # Reset parent for structural clustering
        parent = {nid: nid for nid in ids}
        for a, b, _ in struct_edges:
            union(a, b)

        # Collect structural clusters
        struct_groups: dict[str, list[str]] = {}
        for nid in ids:
            root = find(nid)
            struct_groups.setdefault(root, []).append(nid)

        structural_clusters_raw = [
            grp for grp in struct_groups.values()
            if len(grp) >= min_cluster_size
        ]

        structural_clusters = []
        for grp in structural_clusters_raw:
            # Compute avg structural overlap
            sims = []
            for i in range(len(grp)):
                for j in range(i + 1, len(grp)):
                    na, nb = nbrs[grp[i]], nbrs[grp[j]]
                    u = na | nb
                    if u:
                        sims.append(len(na & nb) / len(u))
            avg_sim = sum(sims) / len(sims) if sims else 0.0

            rep = max(grp, key=lambda x: degrees.get(x, 0))
            rep_node = self.get_node(rep)

            structural_clusters.append({
                "members": list(grp),
                "size": len(grp),
                "avg_similarity": round(avg_sim, 4),
                "representative": rep,
                "representative_label": rep_node.label if rep_node else "",
                "total_degree": sum(degrees.get(nid, 0) for nid in grp),
            })

        structural_clusters.sort(key=lambda x: x["avg_similarity"], reverse=True)

        # ── 3. Combined clusters (significant in both dimensions) ──
        content_member_sets = [
            set(c["members"]) for c in content_clusters
        ]
        combined_clusters = []
        for sc in structural_clusters:
            sc_set = set(sc["members"])
            for ci, cc_set in enumerate(content_member_sets):
                overlap = sc_set & cc_set
                # If ≥ min_cluster_size nodes appear in both a content
                # and structural cluster, it's a combined cluster
                if len(overlap) >= min_cluster_size:
                    content_cl = content_clusters[ci]
                    combined_clusters.append({
                        "members": sorted(overlap),
                        "size": len(overlap),
                        "content_avg_similarity": content_cl["avg_similarity"],
                        "structural_avg_similarity": sc["avg_similarity"],
                        "representative": sc["representative"],
                        "representative_label": sc["representative_label"],
                        "consolidation_potential": round(
                            0.5 * content_cl["avg_similarity"]
                            + 0.5 * sc["avg_similarity"], 4
                        ),
                    })
                    break  # each structural cluster matches at most one content cluster

        combined_clusters.sort(
            key=lambda x: x["consolidation_potential"], reverse=True
        )

        # ── 4. Cluster score (0-100) ───────────────────────────────
        nodes_in_content = sum(c["size"] for c in content_clusters)
        nodes_in_structural = sum(c["size"] for c in structural_clusters)
        nodes_in_combined = sum(c["size"] for c in combined_clusters)

        content_ratio = nodes_in_content / n if n else 0
        structural_ratio = nodes_in_structural / n if n else 0
        combined_ratio = nodes_in_combined / n if n else 0

        cluster_score = round(
            min(100, 35 * content_ratio * 3
                + 35 * structural_ratio * 3
                + 30 * combined_ratio * 5),
            2,
        )

        # ── 5. Recommendations ────────────────────────────────────
        recommendations = []

        if combined_clusters:
            top = combined_clusters[0]
            recommendations.append(
                f"🔴 Combined cluster found: {top['size']} nodes "
                f"redundant in both content and structure "
                f"(potential={top['consolidation_potential']:.2f}). "
                f"Representative: '{top['representative_label']}'. "
                f"Consider batch consolidation via auto_consolidate()."
            )
        if content_clusters:
            top = content_clusters[0]
            recommendations.append(
                f"🟠 Content cluster: {top['size']} nodes with avg similarity "
                f"{top['avg_similarity']:.2f}. Representative: '{top['representative_label']}'."
            )
        if structural_clusters:
            top = structural_clusters[0]
            recommendations.append(
                f"🟡 Structural cluster: {top['size']} nodes with avg overlap "
                f"{top['avg_similarity']:.2f}. Representative: '{top['representative_label']}'."
            )
        if not recommendations:
            recommendations.append(
                "✅ No significant clusters detected. "
                "Graph diversity is healthy."
            )

        # Severity
        if cluster_score >= 40:
            recommendations.insert(
                0,
                f"⚠️ High cluster redundancy ({cluster_score}/100). "
                f"Batch consolidation recommended.",
            )
        elif cluster_score >= 15:
            recommendations.insert(
                0,
                f"📉 Moderate cluster redundancy ({cluster_score}/100).",
            )
        else:
            recommendations.insert(
                0,
                f"✅ Low cluster redundancy ({cluster_score}/100).",
            )

        return {
            "content_clusters": content_clusters,
            "structural_clusters": structural_clusters,
            "combined_clusters": combined_clusters,
            "cluster_score": cluster_score,
            "total_nodes": n,
            "nodes_in_content_clusters": nodes_in_content,
            "nodes_in_structural_clusters": nodes_in_structural,
            "nodes_in_combined_clusters": nodes_in_combined,
            "recommendations": recommendations,
        }

    # ─────────────────────────────────────────────────────────────
    # Cycle 272: Auto-consolidate cluster — group-level merge action
    # ─────────────────────────────────────────────────────────────

    def auto_consolidate_cluster(self, *,                            # noqa: C901
                                 cluster_index: int = 0,
                                 cluster_type: str = "combined",
                                 min_cluster_size: int = 3,
                                 content_threshold: float = 0.55,
                                 structural_threshold: float = 0.5,
                                 dry_run: bool = False,
                                 node_ids: list[str] = None) -> dict:
        """Batch-consolidate an entire detected semantic cluster.

        The **act** half of the cluster detect→consolidate loop,
        mirroring ``auto_consolidate()`` for pairwise redundancy.

        While ``semantic_cluster_detect()`` *finds* clusters of N+
        similar nodes, this API *merges* an entire cluster in one
        operation — choosing the highest-degree node as the survivor
        and folding every other member into it.

        **Merge strategy:**

        1. Run ``semantic_cluster_detect`` with the given thresholds.
        2. Select the cluster at ``cluster_index`` from the specified
           ``cluster_type`` ("combined", "content", or "structural").
        3. Sort members by degree (descending).  The highest-degree
           node is the survivor; all others merge into it in order.
        4. Use ``merge_nodes()`` for each merge.

        **Why batch is better than pairwise for clusters:**

        - *Optimal survivor*: The highest-degree node survives all
          merges, accumulating edges from every member.
        - *Deterministic order*: Degree-sorted merge sequence avoids
          the random pair ordering problem of calling
          ``auto_consolidate`` repeatedly.
        - *Single call*: One API call replaces N-1 pairwise calls.

        **Non-mutating when** ``dry_run=True``.

        Args:
            cluster_index: Index into the cluster list (0 = largest/best).
            cluster_type: Which cluster list to use — "combined",
                "content", or "structural".
            min_cluster_size: Passed through to ``semantic_cluster_detect``.
            content_threshold: Passed through to ``semantic_cluster_detect``.
            structural_threshold: Passed through to ``semantic_cluster_detect``.
            dry_run: If True, simulate without modifying.
            node_ids: Restrict analysis to a subgraph.

        Returns:
            Dict with:

            - **merges_performed**: List of ``{source, target, reason}``
            - **survivor**: The surviving (highest-degree) node id
            - **survivor_label**: Label of the survivor
            - **total_merges**: Count of merge operations (= cluster_size - 1)
            - **cluster_type / cluster_index**: Echo of parameters
            - **cluster_score_before / after**: Before/after scores
            - **nodes_before / after**: Node counts
            - **actions**: Human-readable summary strings
            - **dry_run**: Whether this was a simulation
            - **error**: Present only if cluster not found
        """
        # ── Detect clusters ────────────────────────────────────────
        report = self.semantic_cluster_detect(
            node_ids=node_ids,
            min_cluster_size=min_cluster_size,
            content_threshold=content_threshold,
            structural_threshold=structural_threshold,
        )

        cluster_score_before = report["cluster_score"]
        nodes_before = report["total_nodes"]

        # ── Select cluster list ───────────────────────────────────
        key = f"{cluster_type}_clusters"
        clusters = report.get(key, [])
        if cluster_index >= len(clusters):
            return {
                "error": (
                    f"No cluster at index {cluster_index} in "
                    f"{cluster_type}_clusters "
                    f"(have {len(clusters)} clusters)"
                ),
                "cluster_type": cluster_type,
                "cluster_index": cluster_index,
                "dry_run": dry_run,
            }

        cluster = clusters[cluster_index]
        members = list(cluster["members"])

        if len(members) < 2:
            return {
                "error": "Cluster has fewer than 2 members; nothing to merge",
                "cluster_type": cluster_type,
                "cluster_index": cluster_index,
                "dry_run": dry_run,
            }

        # ── Sort by degree (descending) — survivor first ──────────
        members_sorted = sorted(
            members,
            key=lambda nid: self._node_degree(nid),
            reverse=True,
        )
        survivor = members_sorted[0]
        to_merge = members_sorted[1:]

        survivor_node = self.get_node(survivor)
        survivor_label = survivor_node.label if survivor_node else ""

        merges_performed = []
        actions = []

        for src_id in to_merge:
            src_node = self.get_node(src_id)
            src_label = src_node.label if src_node else src_id
            src_deg = self._node_degree(src_id)

            merge_rec = {
                "source": src_id,
                "target": survivor,
                "source_label": src_label,
                "source_degree": src_deg,
                "reason": (
                    f"degree {src_deg} < survivor "
                    f"{self._node_degree(survivor)}"
                ),
            }
            merges_performed.append(merge_rec)

            if not dry_run:
                self.merge_nodes(src_id, survivor)

            actions.append(
                f"Merge: {src_label} ({src_id}) → "
                f"{survivor_label} ({survivor})"
            )

        total_merges = len(merges_performed)

        # ── Capture after-state ───────────────────────────────────
        if not dry_run and total_merges > 0:
            report_after = self.semantic_cluster_detect(
                node_ids=node_ids,
                min_cluster_size=min_cluster_size,
                content_threshold=content_threshold,
                structural_threshold=structural_threshold,
            )
            cluster_score_after = report_after["cluster_score"]
            nodes_after = report_after["total_nodes"]
        else:
            cluster_score_after = cluster_score_before
            nodes_after = nodes_before - total_merges if not dry_run else nodes_before

        return {
            "merges_performed": merges_performed,
            "survivor": survivor,
            "survivor_label": survivor_label,
            "total_merges": total_merges,
            "cluster_type": cluster_type,
            "cluster_index": cluster_index,
            "cluster_score_before": round(cluster_score_before, 2),
            "cluster_score_after": round(cluster_score_after, 2),
            "nodes_before": nodes_before,
            "nodes_after": nodes_after,
            "actions": actions,
            "dry_run": dry_run,
        }

    # ── EntityResolver: alias management + duplicate detection ────────────────
    # Research #032: Entity resolution is "table stakes" (Mem0 v3, Graphiti).
    # This fills the gap with alias registration, fuzzy duplicate detection,
    # and entity merging.

    def _label_exists(self, label: str) -> bool:
        """Check if any node has this exact label."""
        row = self.conn.execute("SELECT 1 FROM nodes WHERE label=? LIMIT 1", (label,)).fetchone()
        return row is not None

    def register_alias(self, canonical_label: str, alias: str) -> None:
        """Register *alias* as an alternate name for *canonical_label*.

        Raises ValueError if canonical_label does not exist in the graph.
        Aliases are stored case-insensitively and whitespace-trimmed.
        """
        canonical_label = canonical_label.strip()
        alias = alias.strip()
        if not self._label_exists(canonical_label):
            raise ValueError(f"Canonical label '{canonical_label}' not found in graph")
        key = alias.lower()
        self.conn.execute(
            "INSERT OR REPLACE INTO entity_aliases (alias_key, canonical_label, alias_display) VALUES (?,?,?)",
            (key, canonical_label, alias),
        )
        self.conn.commit()

    def resolve_alias(self, alias: str) -> Optional[str]:
        """Resolve *alias* to its canonical label. Returns None if not found."""
        key = alias.strip().lower()
        row = self.conn.execute(
            "SELECT canonical_label FROM entity_aliases WHERE alias_key=?", (key,)
        ).fetchone()
        if row:
            return row["canonical_label"]
        # Also check if it's already a canonical label
        if self._label_exists(alias.strip()):
            return alias.strip()
        return None

    def list_aliases(self, canonical: str = None) -> dict:
        """List all aliases, optionally filtered by canonical label.

        Returns ``{canonical_label: [alias1, alias2, ...]}``.
        """
        if canonical:
            rows = self.conn.execute(
                "SELECT alias_display FROM entity_aliases WHERE canonical_label=? ORDER BY alias_display",
                (canonical,),
            ).fetchall()
            return {canonical: [r["alias_display"] for r in rows]} if rows else {}
        rows = self.conn.execute(
            "SELECT canonical_label, alias_display FROM entity_aliases ORDER BY canonical_label, alias_display"
        ).fetchall()
        result: dict[str, list[str]] = {}
        for r in rows:
            result.setdefault(r["canonical_label"], []).append(r["alias_display"])
        return result

    def remove_alias(self, alias: str) -> bool:
        """Remove an alias. Returns True if it existed."""
        key = alias.strip().lower()
        cur = self.conn.execute("DELETE FROM entity_aliases WHERE alias_key=?", (key,))
        self.conn.commit()
        return cur.rowcount > 0

    def _find_by_label(self, label: str) -> Optional[str]:
        """Find node ID by exact label match."""
        row = self.conn.execute("SELECT id FROM nodes WHERE label=? LIMIT 1", (label,)).fetchone()
        return row["id"] if row else None

    def suggest_duplicates(self, *, threshold: float = 0.92) -> list[dict]:
        """Detect potential duplicate entities via normalised label comparison.

        Compares nodes of the same *kind*. Two labels are considered duplicates if
        their case-insensitive, whitespace-trimmed forms match exactly.

        Returns a list of ``{"canonical": label, "kind": kind, "duplicates": [(id, label)]}``.
        """
        rows = self.conn.execute("SELECT id, label, kind FROM nodes").fetchall()
        # Group by (normalised_label, kind)
        groups: dict[tuple[str, str], list] = {}
        for r in rows:
            key = (r["label"].strip().lower(), r["kind"] or "fact")
            groups.setdefault(key, []).append((r["id"], r["label"], r["kind"] or "fact"))
        dupes = []
        for (norm_label, kind), entries in groups.items():
            if len(entries) > 1:
                canonical = entries[0][1]  # first-added is canonical
                dupes.append({
                    "canonical": canonical,
                    "kind": kind,
                    "duplicates": [(e[0], e[1]) for e in entries[1:]],
                    "duplicate_kind": kind,
                })
        return dupes

    def merge_entities(self, source_id: str, target_id: str) -> bool:
        """Merge *source_id* into *target_id* — redirect all edges, merge data, delete source.

        Data from source is merged into target (target takes precedence on conflicts).
        Returns False if either node doesn't exist, True on success.
        """
        src = self.get_node(source_id)
        tgt = self.get_node(target_id)
        if not src or not tgt:
            return False
        if source_id == target_id:
            return True
        # Merge data (target wins)
        merged_data = {**src.data, **tgt.data}
        self.update_node(target_id, data=merged_data)
        # Redirect edges: source→X becomes target→X
        out_edges = self.conn.execute(
            "SELECT target, relation, weight FROM edges WHERE source=?", (source_id,)
        ).fetchall()
        for e in out_edges:
            if e["target"] != target_id:  # avoid self-loop
                self.link(target_id, e["target"], e["relation"], e["weight"])
        # Redirect edges: X→source becomes X→target
        in_edges = self.conn.execute(
            "SELECT source, relation, weight FROM edges WHERE target=?", (source_id,)
        ).fetchall()
        for e in in_edges:
            if e["source"] != target_id:
                self.link(e["source"], target_id, e["relation"], e["weight"])
        # Delete source node (also cleans its edges)
        self.delete_node(source_id)
        return True

    def resolve_or_add(self, label: str, *, kind: str = "fact", data: dict = None) -> object:
        """Resolve *label* via aliases; if not found, create a new node.

        Returns the resolved/created Node.
        """
        canonical = self.resolve_alias(label)
        if canonical:
            nid = self._find_by_label(canonical)
            if nid:
                return self.get_node(nid)
        # No alias found — create new
        return self.add(label, kind, data or {})

    def auto_resolve_check(self) -> dict:
        """Audit entity resolution health — find duplicates and report coverage.

        Returns::

            {
              "total_nodes": int,
              "total_aliases": int,
              "aliased_entities": int,
              "duplicates_found": int,
              "suggestions": [...],  # from suggest_duplicates()
            }
        """
        dupes = self.suggest_duplicates()
        alias_rows = self.conn.execute(
            "SELECT COUNT(*) as cnt, COUNT(DISTINCT canonical_label) as entities FROM entity_aliases"
        ).fetchone()
        node_count = self.conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
        return {
            "total_nodes": node_count,
            "total_aliases": alias_rows["cnt"],
            "aliased_entities": alias_rows["entities"],
            "duplicates_found": len(dupes),
            "suggestions": dupes,
            "recommended_action": "merge_entities() on each duplicate group" if dupes else "none",
        }

    # ── Entropy-Weighted Retrieval ───────────────────────────────────────────
    # Research #032: amg's unique advantage — entropy as retrieval signal.
    # While Mem0 uses vector similarity and Graphiti uses graph traversal,
    # amg uses structural entropy to boost informationally rich nodes.

    def _entropy_weight_for_node(self, node_id: str,
                                 entropy_index: str = "sombor") -> float:
        """Compute a normalised entropy weight [0,1] for a single node.

        Uses the node's degree relative to the max degree in the graph,
        weighted by the chosen degree-entropy index's power.
        """
        deg = self._node_degree(node_id)
        if deg == 0:
            return 0.0
        max_deg = max((self._node_degree(r["id"])
                       for r in self.conn.execute("SELECT id FROM nodes").fetchall()),
                      default=0)
        if max_deg == 0:
            return 0.0
        # Normalise degree to [0, 1]
        norm_deg = deg / max_deg
        # Apply index-specific power (approximates contribution share)
        index_powers = {
            "sombor": 1.5,
            "reduced_sombor": 1.0,
            "randic": 0.5,
            "zagreb_m1": 2.0,
            "abc": 1.5,
            "ga": 0.5,
            "augmented_zagreb": 2.5,
            "edge_betweenness": 1.0,
        }
        power = index_powers.get(entropy_index, 1.5)
        return min(1.0, norm_deg ** power)

    def entropy_weighted_retrieval(
        self,
        query: str,
        *,
        limit: int = 10,
        alpha: float = 0.3,
        entropy_index: str = "sombor",
        detail: bool = False,
    ) -> list[dict]:
        """Retrieve nodes ranked by a blend of BM25 similarity and entropy weight.

        This is amg's novel differentiator (Research #032): structural
        entropy boosts nodes that are informationally rich and
        well-connected, going beyond pure keyword matching.

        Score = (1 - alpha) * similarity + alpha * entropy_weight

        Args:
            query:          Natural-language search query.
            limit:          Max results.
            alpha:          Entropy blend factor [0, 1].
                            0 = pure similarity (BM25), 1 = pure entropy.
                            Default 0.3 gives a gentle structural boost.
            entropy_index:  Degree-entropy index for weight computation.
            detail:         Include full Node objects in results.

        Returns: list of dicts with keys: node_id, label, score,
                 similarity, entropy_weight, and optionally node.
        """
        valid_indices = {"sombor", "reduced_sombor", "randic", "zagreb_m1",
                         "abc", "ga", "augmented_zagreb", "edge_betweenness"}
        if entropy_index not in valid_indices:
            raise ValueError(
                f"Unknown entropy index '{entropy_index}'. "
                f"Choose from: {', '.join(sorted(valid_indices))}"
            )

        # Step 1: BM25 similarity search
        bm25_results = self.search_bm25(query, limit=limit * 3)
        if not bm25_results:
            # Fallback: search_unified
            bm25_results = self.search_unified(query, limit=limit * 3)
            bm25_results = [
                {"node_id": r["node"].id, "label": r["node"].label,
                 "kind": r["node"].kind, "score": r["score"]}
                for r in bm25_results
            ]
        if not bm25_results:
            return []

        # Normalise BM25 scores to [0, 1]
        max_sim = max((r["score"] for r in bm25_results), default=1.0)
        if max_sim <= 0:
            max_sim = 1.0

        # Step 2: Compute entropy weight and blended score
        results = []
        for r in bm25_results[:limit * 2]:
            nid = r["node_id"]
            sim = r["score"] / max_sim
            ew = self._entropy_weight_for_node(nid, entropy_index)
            score = (1 - alpha) * sim + alpha * ew
            entry = {
                "node_id": nid,
                "label": r["label"],
                "kind": r.get("kind", "fact"),
                "score": round(score, 6),
                "similarity": round(sim, 6),
                "entropy_weight": round(ew, 6),
            }
            if detail:
                node = self.get_node(nid)
                if node:
                    entry["node"] = node
            results.append(entry)

        results.sort(key=lambda x: x["score"], reverse=True)
        return results[:limit]

    # ------------------------------------------------------------------
    # Cycle 306: entropy_contribution()
    # ------------------------------------------------------------------

    def entropy_contribution(self, index: str = "sombor",
                             sample: int | None = None,
                             top_k: int = 0) -> Optional[dict]:
        """Leave-one-out marginal entropy contribution per node.

        For each node *v*, computes the graph's degree-based entropy
        as if *v* were removed (edges incident to *v* deleted, and
        the degrees of *v*' neighbors decremented by 1), then measures
        the absolute change:

            ΔH_v = |H(G) − H(G − v)|

        Nodes with high ΔH_v are **information-critical**: their removal
        most disrupts the graph's structural diversity.  This is valuable
        for:

        * Memory consolidation — protect high-contribution nodes from forgetting
        * Graph pruning — safely remove low-contribution nodes
        * Centrality analysis — an information-theoretic alternative to PageRank

        Implementation note: instead of cloning the full graph N times,
        this method computes entropy directly from cached degree/edge
        arrays, achieving O(n·m) total complexity.

        Args:
            index: Degree-based entropy index to use.  One of
                ``sombor``, ``reduced_sombor``, ``randic``, ``zagreb_m1``,
                ``abc``, ``ga``, ``augmented_zagreb``.
            sample: If the graph has more than *sample* nodes, randomly
                sample that many instead of exhaustive leave-one-out.
                ``None`` = always exhaustive.  Recommended ≤ 200.
            top_k: If > 0, only return the top-*k* contributors
                (sorted by ΔH descending).

        Returns:
            Dict with keys:

            * ``baseline_entropy``: H(G) on the full graph
            * ``contributions``: ``{node_id: ΔH_v}`` for every (or sampled) node
            * ``ranked``: list of ``(node_id, ΔH_v)`` sorted descending
            * ``mean``: average ΔH across evaluated nodes
            * ``std``: standard deviation of ΔH
            * ``max_delta``: largest ΔH (most critical node)
            * ``min_delta``: smallest ΔH (most expendable node)
            * ``critical_nodes``: nodes with ΔH > mean + std
            * ``expendable_nodes``: nodes with ΔH < mean − std
            * ``index``: the entropy index used
            * ``sampled``: whether sampling was used
            * ``evaluated``: number of nodes evaluated

            Returns ``None`` if the graph has fewer than 3 nodes or 1 edge.
        """
        import random as _random

        # ── Edge contribution functions: f(d_u, d_v) → float ──
        def _sombor_contrib(du, dv):
            return math.sqrt(du * du + dv * dv)

        def _reduced_sombor_contrib(du, dv):
            rm_u, rm_v = max(du - 1, 0), max(dv - 1, 0)
            return math.sqrt(rm_u * rm_u + rm_v * rm_v)

        def _randic_contrib(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            return 1.0 / math.sqrt(du * dv)

        def _zagreb_m1_contrib(du, dv):
            return float(du * du + dv * dv)

        def _abc_contrib(du, dv):
            if du <= 1 or dv <= 1:
                return 0.0
            return math.sqrt((du + dv - 2.0) / (du * dv))

        def _ga_contrib(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            return 2.0 * math.sqrt(du * dv) / (du + dv)

        def _augmented_zagreb_contrib(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            ratio = (du * dv) / (du + dv)
            return ratio ** 3  # |(d_u*d_v)/(d_u+d_v)|^3

        CONTRIB_MAP = {
            "sombor":           _sombor_contrib,
            "reduced_sombor":   _reduced_sombor_contrib,
            "randic":           _randic_contrib,
            "zagreb_m1":        _zagreb_m1_contrib,
            "abc":              _abc_contrib,
            "ga":               _ga_contrib,
            "augmented_zagreb": _augmented_zagreb_contrib,
        }
        if index not in CONTRIB_MAP:
            raise ValueError(
                f"Unknown index '{index}'. Valid: {list(CONTRIB_MAP)}"
            )
        contrib_fn = CONTRIB_MAP[index]

        # ── Helper: compute Shannon entropy from edge contributions ──
        def _shannon_entropy(contribs: list[float]) -> Optional[float]:
            valid = [c for c in contribs if c > 0]
            if not valid:
                return None if not contribs else 0.0
            total = sum(valid)
            if total <= 0:
                return None
            m = len(valid)
            h = 0.0
            for c in valid:
                p = c / total
                if p > 0:
                    h -= p * math.log(p)
            if m > 1:
                h /= math.log(m)
            return h

        # ── Cache graph state ──
        node_rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        all_node_ids = [str(r["id"]) for r in node_rows]
        n_nodes = len(all_node_ids)
        edge_rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        all_edges = [(str(r["source"]), str(r["target"])) for r in edge_rows]
        n_edges = len(all_edges)

        if n_nodes < 3 or n_edges < 1:
            return None

        # Compute original degrees
        orig_deg: dict[str, int] = {}
        for nid in all_node_ids:
            orig_deg[nid] = self.degree(nid)

        # Baseline entropy
        baseline_contribs = [
            contrib_fn(orig_deg.get(s, 0), orig_deg.get(t, 0))
            for s, t in all_edges
        ]
        baseline = _shannon_entropy(baseline_contribs)
        if baseline is None:
            return None

        # ── Determine which nodes to evaluate ──
        use_sampling = sample is not None and n_nodes > sample
        if use_sampling:
            eval_nodes = _random.sample(all_node_ids, sample)
        else:
            eval_nodes = all_node_ids

        # ── Adjacency for fast degree adjustment ──
        adjacency: dict[str, set[str]] = {nid: set() for nid in all_node_ids}
        for s, t in all_edges:
            adjacency.setdefault(s, set()).add(t)
            adjacency.setdefault(t, set()).add(s)

        contributions: dict[str, float] = {}

        for nid in eval_nodes:
            # Adjusted degrees: decrement neighbors of nid
            adj_deg = dict(orig_deg)  # shallow copy
            neighbors = adjacency.get(nid, set())
            for nb in neighbors:
                adj_deg[nb] = max(0, adj_deg.get(nb, 0) - 1)
            adj_deg[nid] = 0  # effectively removed

            # Filter edges not incident to nid, compute contributions
            removed_contribs = []
            for s, t in all_edges:
                if s == nid or t == nid:
                    continue
                removed_contribs.append(
                    contrib_fn(adj_deg.get(s, 0), adj_deg.get(t, 0))
                )

            h_without = _shannon_entropy(removed_contribs)
            if h_without is not None:
                contributions[nid] = round(abs(baseline - h_without), 6)
            elif len(removed_contribs) == 0:
                # All edges removed — full entropy loss
                contributions[nid] = round(baseline, 6)
            else:
                contributions[nid] = 0.0

        if not contributions:
            return None

        deltas = list(contributions.values())
        n_eval = len(deltas)
        mean_delta = sum(deltas) / n_eval
        var_delta = sum((d - mean_delta) ** 2 for d in deltas) / n_eval
        std_delta = var_delta ** 0.5

        ranked = sorted(contributions.items(), key=lambda x: x[1], reverse=True)
        if top_k > 0:
            ranked = ranked[:top_k]

        critical = [
            nid for nid, d in contributions.items()
            if d > mean_delta + std_delta
        ]
        expendable = [
            nid for nid, d in contributions.items()
            if d < max(0.0, mean_delta - std_delta)
        ]

        return {
            "baseline_entropy":  round(baseline, 6),
            "contributions":     contributions,
            "ranked":            ranked,
            "mean":              round(mean_delta, 6),
            "std":               round(std_delta, 6),
            "max_delta":         round(max(deltas), 6),
            "min_delta":         round(min(deltas), 6),
            "critical_nodes":    critical,
            "expendable_nodes":  expendable,
            "index":             index,
            "sampled":           use_sampling,
            "evaluated":         n_eval,
        }

    # ── Cycle 310: Spectral entropy contribution (leave-one-out von Neumann) ──

    def spectral_entropy_contribution(self, *, sample: int | None = None,
                                        top_k: int = 0) -> Optional[dict]:
        r"""Leave-one-out spectral entropy contribution per node.

        For each node *v*, computes the graph's von Neumann entropy
        (Laplacian eigenvalue Shannon) as if *v* and all its incident
        edges were removed, then measures the absolute change:

            ΔH_v = |H_vN(G) − H_vN(G − v)|

        This is the **spectral counterpart** to ``entropy_contribution()``.
        While degree-based contribution measures local structural diversity
        disruption, spectral contribution captures **global topology**
        disruption — which nodes most affect the eigenvalue distribution.

        **Use cases:**
        * Identify graph-structurally critical nodes (global topology)
        * Complement degree-based entropy_contribution for richer analysis
        * Memory consolidation — protect spectrally-critical nodes

        **Complexity:** O(n² · max_iter) per node — use *sample* for large graphs.

        Args:
            sample: If graph has more nodes, randomly sample this many.
                    ``None`` = exhaustive.  Recommended ≤ 50 for spectral.
            top_k: If > 0, only return top-*k* contributors.

        Returns:
            Dict with keys:
            * ``baseline_entropy``: H_vN(G) normalised
            * ``contributions``: {node_id: ΔH_v}
            * ``ranked``: [(node_id, ΔH_v)] sorted descending
            * ``mean``, ``std``, ``max_delta``, ``min_delta``: stats
            * ``critical_nodes``: ΔH > mean + std
            * ``expendable_nodes``: ΔH < max(0, mean − std)
            * ``index``: "von_neumann"
            * ``sampled``, ``evaluated``: sampling info

            Returns ``None`` if graph has < 3 nodes.
        """
        import random as _random

        # ── Get base node set ──
        node_ids = [
            str(r["id"]) for r in
            self.conn.execute("SELECT id FROM nodes WHERE quarantined = 0").fetchall()
        ]
        n = len(node_ids)
        if n < 3:
            return None

        # ── Baseline von Neumann entropy ──
        baseline = self.von_neumann_entropy(normalized=True)
        if baseline is None:
            return None

        # ── Build adjacency and degree ──
        edge_rows = self.conn.execute(
            "SELECT source, target FROM edges"
        ).fetchall()
        adj: dict[str, set[str]] = {nid: set() for nid in node_ids}
        for e in edge_rows:
            s, t = str(e["source"]), str(e["target"])
            if s in adj and t in adj:
                adj[s].add(t)
                adj[t].add(s)

        # ── Determine evaluation set ──
        use_sampling = sample is not None and n > sample
        if use_sampling:
            eval_nodes = _random.sample(node_ids, sample)
        else:
            eval_nodes = node_ids

        contributions: dict[str, float] = {}

        for nid in eval_nodes:
            # Build graph without nid
            remaining = [x for x in node_ids if x != nid]
            idx = {x: i for i, x in enumerate(remaining)}
            m = len(remaining)
            degree = [0] * m
            adj_sym: dict[int, set[int]] = defaultdict(set)
            for s_nb in adj.get(nid, set()):
                # Edge (nid, s_nb) is removed; also check other edges
                pass
            for e in edge_rows:
                s, t = str(e["source"]), str(e["target"])
                if s == nid or t == nid:
                    continue
                if s in idx and t in idx:
                    i, j = idx[s], idx[t]
                    adj_sym[i].add(j)
                    adj_sym[j].add(i)
                    degree[i] += 1
                    degree[j] += 1

            if m < 2:
                # Only 1 node left — full entropy loss
                contributions[nid] = round(baseline, 6)
                continue

            # Build Laplacian
            L = [[0.0] * m for _ in range(m)]
            for i in range(m):
                L[i][i] = float(degree[i])
                for j in adj_sym[i]:
                    L[i][j] = -1.0
            evals = self._sym_eigenvalues(L)
            if evals is None:
                contributions[nid] = 0.0
                continue

            # Von Neumann entropy
            lam_sum = sum(evals)
            if lam_sum <= 0:
                h_without = 0.0
            else:
                probs = [e / lam_sum for e in evals if e > 1e-15]
                if not probs:
                    h_without = 0.0
                else:
                    h_raw = 0.0
                    for p in probs:
                        h_raw -= p * math.log(p)
                    max_ent = math.log(m - 1) if m > 2 else 1.0
                    h_without = h_raw / max_ent if max_ent > 0 else 0.0

            contributions[nid] = round(abs(baseline - h_without), 6)

        if not contributions:
            return None

        deltas = list(contributions.values())
        n_eval = len(deltas)
        mean_d = sum(deltas) / n_eval
        var_d = sum((d - mean_d) ** 2 for d in deltas) / n_eval
        std_d = var_d ** 0.5

        ranked = sorted(contributions.items(), key=lambda x: x[1], reverse=True)
        if top_k > 0:
            ranked = ranked[:top_k]

        critical = [nid for nid, d in contributions.items() if d > mean_d + std_d]
        expendable = [nid for nid, d in contributions.items()
                      if d < max(0.0, mean_d - std_d)]

        return {
            "baseline_entropy": round(baseline, 6),
            "contributions":    contributions,
            "ranked":           ranked,
            "mean":             round(mean_d, 6),
            "std":              round(std_d, 6),
            "max_delta":        round(max(deltas), 6),
            "min_delta":        round(min(deltas), 6),
            "critical_nodes":   critical,
            "expendable_nodes": expendable,
            "index":            "von_neumann",
            "sampled":          use_sampling,
            "evaluated":        n_eval,
        }

    # ── Cycle 311: Spectral entropy stability (von Neumann) ──

    def entropy_stability_spectral(self, *, trials: int = 30,
                                      edge_fraction: float = 0.1,
                                      mode: str = "remove",
                                      seed: int | None = None,
                                      include_quarantined: bool = False
                                      ) -> Optional[dict]:
        r"""Monte Carlo von Neumann entropy stability under edge perturbation.

        Repeatedly perturbs the graph (remove or rewire edges),
        recomputes the **spectral (von Neumann) entropy** after each
        perturbation, and summarises the distribution.

        This is the spectral counterpart to ``entropy_stability()``
        (which uses degree-based indices).  Spectral stability captures
        **global topology** robustness — how much the eigenvalue
        distribution changes when edges are perturbed.

        **Perturbation modes:**
        - ``"remove"``: delete edges (default)
        - ``"rewire"``: rewire endpoints (preserve degree sequence)

        Args:
            trials: Monte Carlo iterations (default 30, fewer than
                    degree-based due to O(n²) eigenvalue cost).
            edge_fraction: fraction of edges to perturb per trial (0–1).
            mode: "remove" or "rewire".
            seed: RNG seed for reproducibility.
            include_quarantined: include quarantined nodes.

        Returns:
            Dict with same keys as ``entropy_stability()`` plus
            ``index: "von_neumann"``.  Returns ``None`` for < 2 nodes.
        """
        import random as _rng

        if seed is not None:
            _rng.seed(seed)
        if edge_fraction <= 0 or edge_fraction > 1:
            raise ValueError("edge_fraction must be in (0, 1]")
        if trials < 1:
            raise ValueError("trials must be >= 1")
        if mode not in ("remove", "rewire"):
            raise ValueError(f"Unknown mode '{mode}'; choose 'remove' or 'rewire'")

        # ── Collect graph state ──
        base_q = "SELECT id FROM nodes"
        if not include_quarantined:
            base_q += " WHERE quarantined = 0"
        node_ids = [str(r["id"]) for r in self.conn.execute(base_q).fetchall()]
        n = len(node_ids)
        if n < 2:
            return None

        edge_rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        all_edges = [(str(e["source"]), str(e["target"])) for e in edge_rows
                     if str(e["source"]) in set(node_ids)
                     and str(e["target"]) in set(node_ids)]
        n_edges = len(all_edges)
        if n_edges < 1:
            return None

        # Baseline
        baseline = self.von_neumann_entropy(
            normalized=True, include_quarantined=include_quarantined
        )
        if baseline is None:
            return None

        n_perturb = max(1, int(n_edges * edge_fraction))
        idx_set = set(node_ids)
        entropy_values: list[float] = []

        for _trial in range(trials):
            trial_edges = list(all_edges)

            if mode == "remove":
                if n_perturb >= len(trial_edges):
                    # All edges removed → entropy = 0
                    entropy_values.append(0.0)
                    continue
                indices_to_remove = set(
                    _rng.sample(range(len(trial_edges)), n_perturb)
                )
                trial_edges = [
                    e for i, e in enumerate(trial_edges)
                    if i not in indices_to_remove
                ]

            else:  # rewire
                adj: dict[str, set[str]] = {nid: set() for nid in node_ids}
                for s, t in all_edges:
                    adj[s].add(t)
                    adj[t].add(s)
                for _ in range(n_perturb):
                    if not trial_edges:
                        break
                    ei = _rng.randrange(len(trial_edges))
                    s, t = trial_edges[ei]
                    if _rng.random() < 0.5:
                        new_t = _rng.choice(node_ids)
                        if new_t != s and new_t != t and new_t not in adj.get(s, set()):
                            trial_edges[ei] = (s, new_t)
                    else:
                        new_s = _rng.choice(node_ids)
                        if new_s != s and new_s != t and new_s not in adj.get(t, set()):
                            trial_edges[ei] = (new_s, t)

            # Build Laplacian from trial_edges
            degree = [0] * n
            adj_sym: dict[int, set[int]] = defaultdict(set)
            node_idx = {nid: i for i, nid in enumerate(node_ids)}
            for s, t in trial_edges:
                if s in node_idx and t in node_idx:
                    i, j = node_idx[s], node_idx[t]
                    adj_sym[i].add(j)
                    adj_sym[j].add(i)
                    degree[i] += 1
                    degree[j] += 1

            L = [[0.0] * n for _ in range(n)]
            for i in range(n):
                L[i][i] = float(degree[i])
                for j in adj_sym[i]:
                    L[i][j] = -1.0

            evals = self._sym_eigenvalues(L)
            if evals is None:
                continue

            lam_sum = sum(evals)
            if lam_sum <= 0:
                h = 0.0
            else:
                probs = [e / lam_sum for e in evals if e > 1e-15]
                if not probs:
                    h = 0.0
                else:
                    h_raw = 0.0
                    for p in probs:
                        h_raw -= p * math.log(p)
                    max_ent = math.log(n - 1) if n > 2 else 1.0
                    h = h_raw / max_ent if max_ent > 0 else 0.0

            entropy_values.append(h)

        if not entropy_values:
            return None

        n_val = len(entropy_values)
        mean_h = sum(entropy_values) / n_val
        var_h = sum((v - mean_h) ** 2 for v in entropy_values) / n_val
        std_h = var_h ** 0.5
        min_h = min(entropy_values)
        max_h = max(entropy_values)
        cv = std_h / mean_h if mean_h > 0 else float("inf")
        stability = max(0.0, min(1.0, 1.0 - cv))

        return {
            "baseline_entropy":  round(baseline, 6),
            "mean":              round(mean_h, 6),
            "std":               round(std_h, 6),
            "cv":                round(cv, 6),
            "min":               round(min_h, 6),
            "max":               round(max_h, 6),
            "range":             round(max_h - min_h, 6),
            "stability_score":   round(stability, 6),
            "entropy_values":    [round(v, 6) for v in entropy_values],
            "perturbed_edges":   n_perturb,
            "trials":            n_val,
            "mode":              mode,
            "index":             "von_neumann",
        }

    # ── Cycle 316: Unified node entropy importance ──

    def node_entropy_importance(self, index: str = "sombor",
                               weights: dict[str, float] | None = None) -> Optional[dict]:
        """Unified per-node importance score combining multiple entropy signals.

        Fuses three complementary entropy-based node measures into a single
        ranking:
        1. **Entropy contribution** (leave-one-out): how much global entropy
           changes when this node is removed.
        2. **Ego-entropy**: how diverse this node's local neighbourhood is.
        3. **Anomaly z-score**: how far this node's local entropy deviates
           from the graph average.

        Each signal captures different aspects:
        - Contribution = global importance (impact on graph structure)
        - Ego-entropy = local importance (neighbourhood diversity)
        - Anomaly = distinctiveness (unusual structural role)

        **Use cases:**
        - Prioritized retrieval (high-importance nodes first)
        - Forgetting decisions (low-importance nodes first)
        - Knowledge gap detection (unexpected low-importance hubs)
        - Consolidation (merge similar low-importance nodes)

        Args:
            index: Degree-based entropy index.
            weights: Custom weights for the three signals.
                Keys: ``"contribution"``, ``"ego"``, ``"anomaly"``.
                Default: equal weights (1/3 each).

        Returns:
            Dict with:
            - ``ranking``: list of ``(node_id, score, components)`` sorted desc
            - ``scores``: ``{node_id: composite_score}``
            - ``components``: ``{node_id: {contribution, ego, anomaly}}``
            - ``top_k_critical``: top 10% nodes (high importance)
            - ``bottom_k_expendable``: bottom 10% nodes (low importance)
            - ``mean``: average composite score
            - ``std``: std deviation
            - ``index``: entropy index used

            Returns ``None`` for < 3 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        n = len(rows)
        if n < 3:
            return None

        if weights is None:
            weights = {"contribution": 1.0 / 3, "ego": 1.0 / 3, "anomaly": 1.0 / 3}
        else:
            # Normalize weights
            total_w = sum(weights.values())
            if total_w > 0:
                weights = {k: v / total_w for k, v in weights.items()}

        # ── Signal 1: Entropy contribution ──
        contrib = self.entropy_contribution(index=index)
        contrib_scores: dict[str, float] = {}
        if contrib and "contributions" in contrib:
            max_c = max(contrib["contributions"].values()) if contrib["contributions"] else 1.0
            max_c = max(max_c, 1e-12)
            contrib_scores = {k: v / max_c for k, v in contrib["contributions"].items()}

        # ── Signal 2: Ego-entropy ──
        ego = self.ego_entropy_profile(index=index)
        ego_scores: dict[str, float] = {}
        if ego and "ego_entropy" in ego:
            max_e = max(ego["ego_entropy"].values()) if ego["ego_entropy"] else 1.0
            max_e = max(max_e, 1e-12)
            ego_scores = {k: v / max_e for k, v in ego["ego_entropy"].items()}

        # ── Signal 3: Anomaly z-score ──
        anomaly = self.entropy_anomaly_detect(index=index)
        anomaly_scores: dict[str, float] = {}
        if anomaly and "node_scores" in anomaly:
            max_a = max(abs(v) for v in anomaly["node_scores"].values()) if anomaly["node_scores"] else 1.0
            max_a = max(max_a, 1e-12)
            # Use absolute z-score (high anomaly = high importance)
            anomaly_scores = {k: abs(v) / max_a for k, v in anomaly["node_scores"].items()}

        # ── Composite score ──
        all_node_ids = [str(r["id"]) for r in rows]
        composite: dict[str, float] = {}
        components: dict[str, dict[str, float]] = {}

        for nid in all_node_ids:
            c = contrib_scores.get(nid, 0.0)
            e = ego_scores.get(nid, 0.0)
            a = anomaly_scores.get(nid, 0.0)
            score = (weights.get("contribution", 0) * c +
                     weights.get("ego", 0) * e +
                     weights.get("anomaly", 0) * a)
            composite[nid] = round(score, 6)
            components[nid] = {"contribution": round(c, 6), "ego": round(e, 6), "anomaly": round(a, 6)}

        # ── Ranking ──
        ranked = sorted(composite.items(), key=lambda x: -x[1])

        values = list(composite.values())
        mean_s = sum(values) / len(values)
        var_s = sum((v - mean_s) ** 2 for v in values) / len(values)
        std_s = var_s ** 0.5

        # Top/bottom 10%
        k = max(1, n // 10)
        top_critical = [nid for nid, _ in ranked[:k]]
        bottom_expendable = [nid for nid, _ in ranked[-k:]]

        return {
            "ranking":            [(nid, s, components[nid]) for nid, s in ranked],
            "scores":             composite,
            "components":         components,
            "top_k_critical":     top_critical,
            "bottom_k_expendable": bottom_expendable,
            "mean":               round(mean_s, 6),
            "std":                round(std_s, 6),
            "index":              index,
            "weights":            weights,
        }

    # ── Cycle 317: Three-layer router cascade (MemFlow pattern) ──

    def three_layer_router_cascade(
        self,
        question: str,
        *,
        embedding: list[float] | None = None,
        limit: int = 10,
        detail: bool = False,
        entropy_index: str = "sombor",
    ) -> dict:
        """Production-pattern query router with three-layer cascade.

        Implements the MemFlow 7-intent routing pattern as a cascade:

        **Layer 1 — Rules** (fastest, ~0ms):
            Keyword-based heuristic routing via ``_route_query``.
            Handles temporal, constraint, short-lookup, and global
            queries deterministically.

        **Layer 2 — Entropy-guided** (~1-5ms):
            If the rule-based mode is ``"hybrid"`` or ``"drift"``
            (ambiguous), escalate to ``entropy_guided_query_route``
            which uses graph topology entropy to pick the optimal
            strategy.  This handles cases where question phrasing
            doesn't clearly indicate the best retrieval mode.

        **Layer 3 — Keyword fallback** (~0ms):
            If both layers above yield no results (empty graph,
            insufficient edges for entropy, etc.), fall back to
            basic keyword search via ``smart_query_route``.

        **Cascade logic:**

        1. Run Layer 1 (rules).  If mode is ``basic``, ``temporal``,
           ``constraint``, or ``global`` — **commit immediately**.
           These are high-confidence deterministic routes.
        2. If Layer 1 mode is ``hybrid`` or ``drift`` — **escalate**
           to Layer 2 (entropy).
        3. If Layer 2 produces results — **commit**.
        4. If Layer 2 fails or is skipped — **fall back** to Layer 3.

        **Audit trail:**
        The returned dict includes a ``cascade_trace`` showing which
        layers were attempted, their outcomes, and latencies.  This
        is essential for debugging routing decisions in production.

        **Use cases:**
        - Production deployment where routing reliability matters
        - Debugging unexpected retrieval results
        - A/B testing routing strategies (compare layer outcomes)
        - Performance monitoring (which layer handles most queries)

        Args:
            question:       Natural-language query string.
            embedding:      Optional pre-computed query embedding
                            for semantic search modes.
            limit:          Maximum results to return.
            detail:         Include full node details in results.
            entropy_index:  Entropy index for Layer 2
                            (``"sombor"``, ``"randic"``, etc.).

        Returns:
            ``{question, mode, layer, results, stats, cascade_trace}``
        """
        import time as _time

        trace: list[dict] = []

        # ── Layer 1: Rules ──
        t0 = _time.perf_counter()
        rule_mode, rule_rationale = self._route_query(question)
        t1 = _time.perf_counter()
        trace.append({
            "layer":         "rules",
            "mode":          rule_mode,
            "rationale":     rule_rationale,
            "latency_ms":    round((t1 - t0) * 1000, 3),
            "committed":     False,
        })

        # Deterministic high-confidence modes → commit immediately
        commit_modes = {"basic", "temporal", "constraint", "global"}
        results = None
        chosen_mode = rule_mode
        chosen_layer = "rules"

        if rule_mode in commit_modes:
            trace[-1]["committed"] = True
            try:
                results = self.smart_query_route(
                    question, embedding=embedding, limit=limit,
                )
            except Exception:
                results = {"mode": rule_mode, "results": [], "reason": "error"}
                trace[-1]["committed"] = True
                trace[-1]["error"] = "smart_query_route failed"
        else:
            # ── Layer 2: Entropy-guided escalation ──
            t2 = _time.perf_counter()
            try:
                ent_result = self.entropy_guided_query_route(
                    question,
                    limit=limit,
                    entropy_index=entropy_index,
                    detail=detail,
                    override_heuristic=True,
                )
                t3 = _time.perf_counter()
                ent_results = ent_result.get("results", [])
                trace.append({
                    "layer":         "entropy",
                    "mode":          ent_result.get("mode", "unknown"),
                    "entropy_mode":  ent_result.get("entropy_mode"),
                    "heuristic_mode": ent_result.get("heuristic_mode"),
                    "latency_ms":    round((t3 - t2) * 1000, 3),
                    "committed":     False,
                    "n_results":     len(ent_results),
                })
                if ent_results:
                    trace[-1]["committed"] = True
                    results = ent_result
                    chosen_mode = ent_result.get("mode", rule_mode)
                    chosen_layer = "entropy"
            except Exception as exc:
                t3 = _time.perf_counter()
                trace.append({
                    "layer":         "entropy",
                    "mode":          None,
                    "error":         str(exc),
                    "latency_ms":    round((t3 - t2) * 1000, 3),
                    "committed":     False,
                })

            # ── Layer 3: Keyword fallback ──
            if results is None:
                t4 = _time.perf_counter()
                try:
                    results = self.smart_query_route(
                        question, embedding=embedding, limit=limit,
                    )
                except Exception:
                    results = {"mode": "basic", "results": []}
                t5 = _time.perf_counter()
                trace.append({
                    "layer":         "fallback",
                    "mode":          "basic",
                    "latency_ms":    round((t5 - t4) * 1000, 3),
                    "committed":     True,
                    "n_results":     len(results.get("results", [])),
                })
                chosen_mode = "basic"
                chosen_layer = "fallback"

        # ── Build summary ──
        final_results = results.get("results", []) if isinstance(results, dict) else []
        total_latency = sum(t["latency_ms"] for t in trace)

        return {
            "question":       question,
            "mode":           chosen_mode,
            "layer":          chosen_layer,
            "results":        final_results,
            "n_results":      len(final_results),
            "stats": {
                "total_latency_ms":  round(total_latency, 3),
                "layers_attempted":  len(trace),
                "committed_layer":   chosen_layer,
            },
            "cascade_trace":  trace,
        }

    # ── Cycle 315: Graph topology classification via entropy signatures ──

    def graph_type_indicator(self) -> Optional[dict]:
        """Classify graph topology type from entropy and structural metrics.

        Uses a combination of degree-distribution statistics and entropy
        measures to classify the graph into one of seven canonical types.
        No reference graphs required — pure heuristic classification.

        **Detectable types:**
        - ``complete`` — K_n: all nodes connected. Max entropy, uniform degree.
        - ``star`` — One hub, many leaves. Extreme degree variance.
        - ``path`` — Linear chain. Low entropy, moderate degree variance.
        - ``cycle`` — Ring. Uniform degree (degree 2), moderate entropy.
        - ``tree`` — Acyclic, branching. Moderate entropy, no triangles.
        - ``random`` — Erdős-Rényi-like. High entropy, low clustering.
        - ``scale_free`` — Power-law degree distribution. High entropy, hub-dominated.
        - ``unknown`` — Doesn't match any signature clearly.

        **Method:**
        Computes a set of structural indicators (degree variance, degree
        entropy, spectral entropy, triangle density, clustering coefficient)
        and matches them against characteristic profiles.

        Returns:
            Dict with:
            - ``type``: best-guess type string
            - ``confidence``: 0-1 (higher = more certain)
            - "scores": dict of type → similarity score
            - ``metrics``: underlying structural metrics used

            Returns ``None`` for < 3 nodes.
        """
        rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        n = len(rows)
        if n < 3:
            return None

        edges = self.conn.execute("SELECT source, target FROM edges").fetchall()
        m = len(edges)
        if m < 1:
            return {"type": "empty", "confidence": 1.0, "scores": {}, "metrics": {"nodes": n, "edges": 0}}

        # ── Compute structural metrics ──
        degrees: dict[str, int] = {}
        adj: dict[str, set[str]] = {}
        for r in rows:
            nid = str(r["id"])
            degrees[nid] = 0
            adj[nid] = set()
        for r in edges:
            s, t = str(r["source"]), str(r["target"])
            degrees[s] = degrees.get(s, 0) + 1
            degrees[t] = degrees.get(t, 0) + 1
            adj.setdefault(s, set()).add(t)
            adj.setdefault(t, set()).add(s)

        deg_values = list(degrees.values())
        mean_deg = sum(deg_values) / n
        var_deg = sum((d - mean_deg) ** 2 for d in deg_values) / n
        std_deg = var_deg ** 0.5
        cv_deg = std_deg / mean_deg if mean_deg > 0 else float("inf")
        max_deg = max(deg_values)
        min_deg = min(deg_values)

        # Degree entropy (Shannon on degree distribution)
        deg_counts: dict[int, int] = {}
        for d in deg_values:
            deg_counts[d] = deg_counts.get(d, 0) + 1
        deg_probs = [c / n for c in deg_counts.values()]
        deg_entropy = -sum(p * math.log(p) for p in deg_probs if p > 0)
        max_deg_entropy = math.log(n) if n > 1 else 1.0
        norm_deg_entropy = deg_entropy / max_deg_entropy if max_deg_entropy > 0 else 0.0

        # Spectral entropy (von Neumann)
        vne = self.von_neumann_entropy(normalized=True) or 0.0

        # Triangle count (for cycle/complete/tree detection)
        triangles = 0
        node_list = [str(r["id"]) for r in rows]
        for i, a in enumerate(node_list):
            for b in adj.get(a, set()):
                if b <= a:
                    continue
                for c in adj.get(a, set()):
                    if c <= b:
                        continue
                    if c in adj.get(b, set()):
                        triangles += 1
        # Each triangle counted exactly once (a < b < c ordering)

        # Max possible triangles
        max_tri = n * (n - 1) * (n - 2) // 6
        triangle_density = triangles / max_tri if max_tri > 0 else 0.0

        # Clustering coefficient (average local)
        clustering_sum = 0.0
        clustering_count = 0
        for nid in node_list:
            neighbors = adj.get(nid, set())
            k = len(neighbors)
            if k < 2:
                continue
            # Count edges among neighbors
            neighbor_list = list(neighbors)
            local_edges = 0
            for i, a in enumerate(neighbor_list):
                for b in neighbor_list[i + 1:]:
                    if b in adj.get(a, set()):
                        local_edges += 1
            clustering_sum += 2.0 * local_edges / (k * (k - 1))
            clustering_count += 1
        avg_clustering = clustering_sum / clustering_count if clustering_count > 0 else 0.0

        # Connectivity check
        visited: set[str] = set()
        component_sizes: list[int] = []
        for start in node_list:
            if start in visited:
                continue
            stack = [start]
            comp_size = 0
            while stack:
                node = stack.pop()
                if node in visited:
                    continue
                visited.add(node)
                comp_size += 1
                stack.extend(adj.get(node, set()) - visited)
            component_sizes.append(comp_size)
        n_components = len(component_sizes)
        is_connected = n_components == 1

        # ── Edge density ──
        max_edges = n * (n - 1) // 2
        density = m / max_edges if max_edges > 0 else 0.0

        # ── Type scoring ──
        # Each score in [0, 1], higher = more likely that type
        scores: dict[str, float] = {}

        # Complete: high density (>0.8), low cv_deg (all same degree), high clustering
        if density > 0.8 and cv_deg < 0.1 and avg_clustering > 0.8:
            scores["complete"] = 1.0
        else:
            scores["complete"] = max(0.0, min(1.0,
                (density - 0.5) * 2 * (1 - min(cv_deg, 1.0)) * avg_clustering
            ))

        # Star: one node has degree n-1, rest have degree 1
        if max_deg == n - 1 and min_deg == 1:
            hub_count = sum(1 for d in deg_values if d == n - 1)
            if hub_count == 1:
                scores["star"] = 1.0
            else:
                scores["star"] = 0.5
        else:
            # Partial star: high cv_deg, one dominant hub
            hub_ratio = max_deg / (2 * m) if m > 0 else 0
            scores["star"] = max(0.0, min(1.0, cv_deg * hub_ratio * 2))

        # Path: max degree ≤ 2, connected, exactly n-1 edges
        if is_connected and max_deg <= 2 and m == n - 1 and n > 2:
            scores["path"] = 1.0
        else:
            deg2_frac = sum(1 for d in deg_values if d <= 2) / n
            scores["path"] = max(0.0, min(1.0, deg2_frac * (1 - triangle_density * 5) * (1.0 - abs(m - n + 1) / n)))

        # Cycle: all degree 2, connected, edges == nodes
        if is_connected and max_deg == 2 and min_deg == 2 and m == n:
            scores["cycle"] = 1.0
        else:
            deg2_only = all(d == 2 for d in deg_values)
            scores["cycle"] = 1.0 if (deg2_only and m == n and is_connected) else 0.3 * (1.0 - abs(cv_deg) / 2)

        # Tree: connected, m = n-1, no triangles
        if is_connected and m == n - 1 and triangle_density < 0.01:
            scores["tree"] = max(scores.get("path", 0.0), 0.8)  # path is a special tree
        else:
            scores["tree"] = max(0.0, min(1.0,
                (1 - triangle_density * 3) * max(0.0, 1.0 - abs(m - (n - 1)) / n) * (1 if is_connected else 0.5)
            ))

        # Random: moderate entropy, moderate clustering, moderate density
        scores["random"] = max(0.0, min(1.0,
            norm_deg_entropy * (1 - avg_clustering) * (1 - abs(density - 0.3) * 2)
        ))

        # Scale-free: high cv_deg, hub-dominated, power-law-like
        # Use max-to-mean degree ratio as power-law indicator
        max_to_mean = max_deg / mean_deg if mean_deg > 0 else 0
        # Nodes at or below median degree (long tail indicator)
        sorted_degs = sorted(deg_values)
        median_deg = sorted_degs[n // 2] if n > 0 else 0
        low_deg_frac = sum(1 for d in deg_values if d <= median_deg) / n
        scores["scale_free"] = max(0.0, min(1.0,
            min(cv_deg, 1.0) * min(max_to_mean / 3.0, 1.0) * (1 - avg_clustering * 0.5)
        ))

        # ── Pick best type ──
        best_type = max(scores, key=scores.get)
        best_score = scores[best_type]

        # Confidence: ratio of best to second-best
        sorted_scores = sorted(scores.values(), reverse=True)
        if len(sorted_scores) > 1 and sorted_scores[1] > 0:
            confidence = 1.0 - (sorted_scores[1] / sorted_scores[0]) if sorted_scores[0] > 0 else 0.0
        else:
            confidence = 1.0 if best_score > 0 else 0.0

        # Round scores
        scores = {k: round(v, 4) for k, v in sorted(scores.items(), key=lambda x: -x[1])}

        return {
            "type":          best_type,
            "confidence":    round(confidence, 4),
            "scores":        scores,
            "metrics": {
                "nodes":           n,
                "edges":           m,
                "density":         round(density, 6),
                "degree_mean":     round(mean_deg, 4),
                "degree_std":      round(std_deg, 4),
                "degree_cv":       round(cv_deg, 4),
                "degree_entropy":  round(deg_entropy, 4),
                "norm_deg_entropy": round(norm_deg_entropy, 4),
                "von_neumann":     round(vne, 4),
                "triangles":       triangles,
                "triangle_density": round(triangle_density, 6),
                "avg_clustering":  round(avg_clustering, 4),
                "components":      n_components,
                "connected":       is_connected,
            },
        }

    # ── Cycle 314: Entropy fingerprint vector (graph feature vector) ──

    def entropy_fingerprint(self, indices: list[str] | None = None,
                           *, include_spectral: bool = True,
                           include_ego: bool = False,
                           ego_radius: int = 1) -> Optional[dict]:
        """Compact feature vector characterising a graph's entropy profile.

        Combines multiple entropy measures into a single numeric vector
        that serves as a **structural fingerprint**.  Two graphs with
        identical fingerprints have very similar topology; differing
        fingerprints indicate structural divergence.

        **Design** (Research #036):
        The fingerprint is a vector of normalised entropy values across:
        - Multiple degree-based indices (sombor, randic, etc.)
        - Spectral entropy (von Neumann) if *include_spectral*
        - Ego-local entropy statistics if *include_ego*

        **Use cases:**
        - Fast graph similarity: Euclidean distance between fingerprints
        - Graph clustering: k-means on fingerprint vectors
        - Anomaly detection: deviation from cluster centroid
        - Tracking evolution: fingerprint trajectory over time

        Args:
            indices: Degree-based indices to include.  Default:
                ``["sombor", "randic", "zagreb_m1", "abc"]``.
            include_spectral: Add von Neumann entropy + spectral profile
                summary statistics.
            include_ego: Add ego-entropy statistics (mean, std,
                field_uniformity) at *ego_radius*.
            ego_radius: Neighbourhood radius for ego statistics.

        Returns:
            Dict with:
            - ``vector``: list[float] — the fingerprint vector
            - ``labels``: list[str] — descriptive label per dimension
            - ``indices``: indices used
            - ``dimension``: len(vector)
            - ``include_spectral``: bool
            - ``include_ego``: bool

            Returns ``None`` if graph has < 2 nodes.
        """
        if indices is None:
            indices = ["sombor", "randic", "zagreb_m1", "abc"]

        all_nodes = self.conn.execute("SELECT id FROM nodes").fetchall()
        if len(all_nodes) < 2:
            return None

        vector: list[float] = []
        labels: list[str] = []

        # ── Degree-based Shannon entropy for each index ──
        _entropy_methods = {
            "sombor":           self.sombor_entropy,
            "reduced_sombor":   self.reduced_sombor_entropy,
            "randic":           self.randic_entropy,
            "zagreb_m1":        self.zagreb_m1_entropy,
            "abc":              self.abc_entropy,
            "ga":               self.ga_entropy,
            "augmented_zagreb": self.augmented_zagreb_entropy,
            "harary":           self.harary_entropy,
            "wiener":           self.wiener_entropy,
            "szeged":           self.szeged_entropy,
            "gutman":           self.gutman_entropy,
            "schultz":          self.schultz_entropy,
        }
        for idx in indices:
            method = _entropy_methods.get(idx)
            if method:
                h = method(normalized=True)
                vector.append(round(h, 8) if h is not None else 0.0)
            else:
                vector.append(0.0)
            labels.append(f"shannon_{idx}")

        # ── Spectral entropy ──
        if include_spectral:
            vne = self.von_neumann_entropy(normalized=True)
            if vne is not None:
                vector.append(round(vne, 8))
            else:
                vector.append(0.0)
            labels.append("von_neumann")

            # Spectral profile summary
            sp = self.spectral_entropy_profile()
            if sp:
                for key in ("algebraic_connectivity",
                            "spectral_gap",
                            "spectral_radius",
                            "complexity"):
                    val = sp.get(key)
                    if isinstance(val, (int, float)):
                        vector.append(round(float(val), 8))
                    else:
                        vector.append(0.0)
                    labels.append(key)
            else:
                for key in ("algebraic_connectivity",
                            "spectral_gap",
                            "spectral_radius",
                            "complexity"):
                    vector.append(0.0)
                    labels.append(key)

        # ── Ego-local entropy statistics ──
        if include_ego:
            ego = self.ego_entropy_profile(radius=ego_radius)
            if ego:
                vector.append(round(ego["mean"], 8))
                labels.append("ego_mean")
                vector.append(round(ego["std"], 8))
                labels.append("ego_std")
                vector.append(round(ego["field_uniformity"], 8))
                labels.append("ego_uniformity")
                # Fraction of isolated nodes
                frac_iso = len(ego["isolated"]) / ego["evaluated"] if ego["evaluated"] > 0 else 0.0
                vector.append(round(frac_iso, 8))
                labels.append("ego_frac_isolated")
            else:
                for lbl in ("ego_mean", "ego_std", "ego_uniformity", "ego_frac_isolated"):
                    vector.append(0.0)
                    labels.append(lbl)

        return {
            "vector":         vector,
            "labels":         labels,
            "indices":        indices,
            "dimension":      len(vector),
            "include_spectral": include_spectral,
            "include_ego":    include_ego,
        }

    def fingerprint_distance(self, other: "MemoryGraph",
                             indices: list[str] | None = None,
                             *, include_spectral: bool = True,
                             include_ego: bool = False,
                             ego_radius: int = 1) -> Optional[float]:
        """Euclidean distance between two graphs' entropy fingerprints.

        Convenience wrapper: computes ``entropy_fingerprint()`` on both
        graphs with identical parameters, then returns the L2 distance.

        This is much faster than full inter-graph divergence (JSD/CE/KL)
        because it avoids pairwise edge-contribution computation —
        each fingerprint is computed independently.

        Args:
            other: The other graph to compare against.
            indices, include_spectral, include_ego, ego_radius:
                Same as ``entropy_fingerprint()``.

        Returns:
            float ≥ 0 (0 = identical fingerprints), or ``None``
            if either graph is too small.
        """
        fp1 = self.entropy_fingerprint(indices, include_spectral=include_spectral,
                                       include_ego=include_ego,
                                       ego_radius=ego_radius)
        fp2 = other.entropy_fingerprint(indices, include_spectral=include_spectral,
                                        include_ego=include_ego,
                                        ego_radius=ego_radius)
        if fp1 is None or fp2 is None:
            return None

        v1, v2 = fp1["vector"], fp2["vector"]
        # Pad shorter vector with zeros
        n = max(len(v1), len(v2))
        v1 += [0.0] * (n - len(v1))
        v2 += [0.0] * (n - len(v2))

        return round(math.sqrt(sum((a - b) ** 2 for a, b in zip(v1, v2))), 8)

    # ── Cycle 318: Spectral classification against reference graphs ──

    def spectral_classification(self,
                                references: list["MemoryGraph"],
                                *,
                                method: str = "spectral",
                                measure: str = "jsd",
                                bins: int = 20,
                                include_quarantined: bool = False,
                               ) -> Optional[dict]:
        """Classify this graph against reference graphs using spectral
        or fingerprint-based similarity.

        Unlike ``graph_classification()`` (which uses degree-based
        JSD/CE/KL on edge contributions), this method operates in the
        **spectral domain** or uses compact **entropy fingerprint**
        vectors — capturing global topological shape rather than
        local edge-weight distributions.

        **Methods:**

        - ``"spectral"`` — pairwise ``spectral_divergence()`` between
          self and each reference.  Supports JSD/KL/CE measures on
          Laplacian eigenvalue histograms.  Size-invariant.
        - ``"spectral_scan"`` — pairwise ``spectral_divergence_scan()``
          mean divergence across Fibonacci resolutions [2,3,5,8,13,21,34,55].
          More robust than single-resolution: averages out bin-boundary
          artefacts.
        - ``"fingerprint"`` — pairwise ``fingerprint_distance()`` using
          entropy fingerprint vectors (12 indices + spectral features).
          Fastest method: O(n) per comparison vs O(n³) for spectral.

        **Returns:**

        Dict with:
        - ``"best_match"``: int — index of closest reference
        - ``"best_score"``: float — lowest distance/divergence
        - ``"rankings"``: list of ``{"index": int, "score": float, "label": str|None}`` sorted ascending
        - ``"method"``: str — classification method used
        - ``"measure"``: str — divergence measure (for spectral methods)
        - ``"confidence"``: float — separation ratio ``(2nd_best − best) / best``.
          Higher = more confident classification (>0.5 is strong).
        - ``"margin"``: float — absolute ``2nd_best − best`` gap.

        Args:
            references:          list of reference MemoryGraphs.
            method:              "spectral", "spectral_scan", or "fingerprint".
            measure:             divergence measure for spectral methods
                                  ("jsd", "kl", "ce").  Ignored for
                                  ``method="fingerprint"``.
            bins:                bin count for ``method="spectral"``.
                                  Ignored for other methods.
            include_quarantined: passed to spectral methods.

        Returns:
            Dict, or ``None`` if no valid comparisons could be made
            (e.g. empty references list or all degenerate graphs).
        """
        if not references:
            return None

        if method not in ("spectral", "spectral_scan", "fingerprint"):
            raise ValueError(
                f"unknown method '{method}'; "
                "choose from spectral/spectral_scan/fingerprint"
            )

        rankings = []
        for i, ref in enumerate(references):
            if method == "spectral":
                score = self.spectral_divergence(
                    ref, measure=measure, bins=bins,
                    include_quarantined=include_quarantined,
                )
            elif method == "spectral_scan":
                scan_result = self.spectral_divergence_scan(
                    ref, measure=measure,
                    include_quarantined=include_quarantined,
                )
                score = scan_result["mean"] if scan_result is not None else None
            else:  # fingerprint
                score = self.fingerprint_distance(ref)

            if score is not None:
                label = None
                # Try to extract a label from the reference graph
                try:
                    label = ref.graph_meta.get("label") if hasattr(ref, "graph_meta") else None
                except Exception:
                    pass
                rankings.append({
                    "index": i,
                    "score": round(score, 8),
                    "label": label,
                })

        if not rankings:
            return None

        rankings.sort(key=lambda x: x["score"])

        best = rankings[0]["score"]
        second = rankings[1]["score"] if len(rankings) > 1 else best
        margin = round(second - best, 8)
        confidence = round(margin / best, 8) if best > 1e-12 else float("inf") if margin > 0 else 0.0

        return {
            "best_match": rankings[0]["index"],
            "best_score": best,
            "rankings": rankings,
            "method": method,
            "measure": measure if method != "fingerprint" else "l2",
            "confidence": confidence,
            "margin": margin,
        }

    # ── Cycle 319: Hybrid ensemble classification ──

    def hybrid_classification(self,
                               references: list["MemoryGraph"],
                               *,
                               degree_method: str = "jsd",
                               degree_index: str = "sombor",
                               spectral_method: str = "spectral",
                               spectral_measure: str = "jsd",
                               bins: int = 20,
                               weights: tuple[float, float] | None = None,
                               include_quarantined: bool = False,
                              ) -> Optional[dict]:
        """Classify against reference graphs using a **weighted ensemble**
        of degree-based and spectral divergence scores.

        Combines two complementary topological domains:

        - **Degree-based** (local): JSD / CE / KL on edge-contribution
          distributions — captures *local* structural patterns.
        - **Spectral** (global): divergence on Laplacian eigenvalue
          histograms — captures *global* topological shape.

        Each modality's raw scores are **min-max normalised** to [0, 1]
        across the reference set, then combined with configurable
        weights to produce a single ensemble score per reference.

        **Why hybrid?**
        - Degree-based measures excel at distinguishing graphs with
          different edge-weight distributions but miss global shape.
        - Spectral measures excel at distinguishing global topology
          (path vs cycle vs star) but average over local details.
        - Combining them captures both axes of structural difference,
        producing more robust classifications than either alone.

        **Normalisation:**
        For each modality, scores are min-max normalised::

            norm_i = (score_i − min(scores)) / (max(scores) − min(scores))

        Best match (lowest raw score) → norm = 0; worst → norm = 1.
        If all scores in a modality are equal, all normals = 0
        (no discriminative power, effectively excluded).

        **Weights:**
        ``weights = (w_degree, w_spectral)`` — normalised to sum to 1.
        Default ``(0.5, 0.5)`` gives equal influence.  Use
        ``(0.7, 0.3)`` to favour local structure, or ``(0.3, 0.7)``
        to favour global topology.

        Args:
            references:          list of reference MemoryGraphs.
            degree_method:       degree-based measure ("jsd", "ce", "kl").
            degree_index:        degree-based index for edge contributions.
            spectral_method:     spectral measure ("spectral", "spectral_scan",
                                 "fingerprint").
            spectral_measure:    divergence measure for spectral methods
                                 ("jsd", "kl", "ce").  Ignored for
                                 ``spectral_method="fingerprint"``.
            bins:                bin count for ``spectral_method="spectral"``.
            weights:             ``(w_degree, w_spectral)`` tuple or None
                                 for equal weighting.
            include_quarantined: passed to spectral methods.

        Returns:
            Dict with:
            - ``best_match``: int — index of closest reference
            - ``best_score``: float — ensemble score (lower = better)
            - ``rankings``: list of dicts with keys ``index``, ``score``,
              ``degree_raw``, ``spectral_raw``, ``degree_norm``,
              ``spectral_norm``, ``label`` — sorted ascending by ensemble.
            - ``degree_method``: str
            - ``spectral_method``: str
            - ``weights``: tuple[float, float] — normalised weights used
            - ``confidence``: float — ``(2nd_best − best) / best``
            - ``margin``: float — ``2nd_best − best``
            or ``None`` if no valid comparisons could be made.
        """
        if not references:
            return None

        valid_degree = ("jsd", "ce", "kl")
        valid_spectral = ("spectral", "spectral_scan", "fingerprint")
        if degree_method not in valid_degree:
            raise ValueError(
                f"unknown degree_method '{degree_method}'; "
                f"choose from {valid_degree}"
            )
        if spectral_method not in valid_spectral:
            raise ValueError(
                f"unknown spectral_method '{spectral_method}'; "
                f"choose from {valid_spectral}"
            )

        # Normalise weights
        if weights is None:
            w_d, w_s = 0.5, 0.5
        else:
            if len(weights) != 2:
                raise ValueError("weights must be a 2-tuple (degree, spectral)")
            w_d, w_s = weights
            total = w_d + w_s
            if total <= 0:
                raise ValueError("weights must sum to a positive value")
            w_d, w_s = w_d / total, w_s / total

        # Degree-based scoring
        degree_compute = {
            "jsd": self.entropy_distance,
            "ce": self.cross_entropy_graph,
            "kl": self.kl_divergence_graph,
        }.get(degree_method)

        # Collect raw scores
        raw_degree: list[float | None] = []
        raw_spectral: list[float | None] = []
        for ref in references:
            d_score = degree_compute(ref, index=degree_index)
            raw_degree.append(d_score)

            if spectral_method == "spectral":
                s_score = self.spectral_divergence(
                    ref, measure=spectral_measure, bins=bins,
                    include_quarantined=include_quarantined,
                )
            elif spectral_method == "spectral_scan":
                scan_result = self.spectral_divergence_scan(
                    ref, measure=spectral_measure,
                    include_quarantined=include_quarantined,
                )
                s_score = scan_result["mean"] if scan_result is not None else None
            else:  # fingerprint
                s_score = self.fingerprint_distance(ref)
            raw_spectral.append(s_score)

        # Min-max normalise each modality
        def _min_max(values: list[float | None]) -> list[float | None]:
            valid_vals = [v for v in values if v is not None]
            if not valid_vals:
                return [None] * len(values)
            lo, hi = min(valid_vals), max(valid_vals)
            rng = hi - lo
            if rng < 1e-15:
                return [0.0 if v is not None else None for v in values]
            return [(v - lo) / rng if v is not None else None for v in values]

        norm_degree = _min_max(raw_degree)
        norm_spectral = _min_max(raw_spectral)

        # Compute ensemble scores
        rankings = []
        for i in range(len(references)):
            nd = norm_degree[i]
            ns = norm_spectral[i]
            # Skip if either modality completely failed for this ref
            if nd is None and ns is None:
                continue

            # Use available modality if one is None
            if nd is None:
                ensemble = w_s * (ns or 0.0)
                effective_d = raw_degree[i]
                effective_nd = None
            elif ns is None:
                ensemble = w_d * (nd or 0.0)
                effective_d = raw_degree[i]
                effective_nd = nd
            else:
                ensemble = w_d * nd + w_s * ns
                effective_nd = nd

            # Extract label
            label = None
            try:
                label = references[i].graph_meta.get("label") if hasattr(references[i], "graph_meta") else None
            except Exception:
                pass

            rankings.append({
                "index": i,
                "score": round(ensemble, 8),
                "degree_raw": round(raw_degree[i], 8) if raw_degree[i] is not None else None,
                "spectral_raw": round(raw_spectral[i], 8) if raw_spectral[i] is not None else None,
                "degree_norm": round(nd, 8) if nd is not None else None,
                "spectral_norm": round(ns, 8) if ns is not None else None,
                "label": label,
            })

        if not rankings:
            return None

        rankings.sort(key=lambda x: x["score"])

        best = rankings[0]["score"]
        second = rankings[1]["score"] if len(rankings) > 1 else best
        margin = round(second - best, 8)
        confidence = round(margin / best, 8) if best > 1e-12 else float("inf") if margin > 0 else 0.0

        return {
            "best_match": rankings[0]["index"],
            "best_score": best,
            "rankings": rankings,
            "degree_method": degree_method,
            "spectral_method": spectral_method,
            "weights": (round(w_d, 8), round(w_s, 8)),
            "confidence": confidence,
            "margin": margin,
        }

    # ------------------------------------------------------------------
    # Cycle 326: rrf_classification() — Reciprocal Rank Fusion
    # ------------------------------------------------------------------

    def rrf_classification(self, references: list["MemoryGraph"],
                           *,
                           k: int = 6,
                           degree_index: str = "sombor",
                           include_quarantined: bool = False,
                           ) -> Optional[dict]:
        """Classify against reference graphs using **Reciprocal Rank Fusion**.

        RRF is a parameter-free ensemble method from information retrieval.
        Instead of combining raw scores (which live on different scales),
        it combines **rankings**: each method ranks the references, and the
        fused score is the sum of reciprocal ranks.

        **Formula:**

        .. code-block:: text

            RRF(ref_i) = Σ_m  1 / (k + rank_m(ref_i))

        where ``rank_m(ref_i)`` is the rank (1-based) of reference *i*
        under method *m*, and *k* is a smoothing constant (default 6).

        **Why RRF?** (Research #038)

        - **Scale-invariant**: degree JSD ∈ [0, 0.8], spectral ∈ [0, 2.5],
          fingerprint ∈ [0, 15+]. RRF ignores all scale differences.
        - **Zero-tuning**: no weight configuration needed.
        - **Robust**: outlier scores from one method can't dominate.
        - **Proven**: standard in web search (Cormack et al. 2009).

        **Three ranking methods fused:**

        1. **Degree JSD** (local structure)
        2. **Spectral divergence** (global topology)
        3. **Fingerprint distance** (multi-dimensional shape)

        **k parameter:** k=60 was optimised for web search (hundreds of
        results). For amg's 5-20 reference graphs, k=5-10 is more
        discriminative. Default k=6 balances fusion smoothness and
        discrimination.

        Args:
            references: List of reference MemoryGraphs.
            k: RRF smoothing constant (default 6).
            degree_index: Degree index for degree JSD.
            include_quarantined: Include quarantined nodes.

        Returns:
            Dict with:
            - ``best_match``: index of best reference
            - ``best_score``: highest RRF score
            - ``rankings``: [{index, rrf_score, degree_rank, spectral_rank,
               fingerprint_rank, label}]
            - ``k``: k parameter used
            - ``methods_used``: list of methods that contributed
            - ``confidence``: separation ratio (best / second)
            - ``margin``: absolute gap
        """
        n = len(references)
        if n == 0:
            return None

        # ── Compute raw scores per method ──────────────────────────
        # Method 1: Degree-based entropy distance (JSD)
        degree_scores = []
        for ref in references:
            try:
                val = self.entropy_distance(ref, index=degree_index)
                if isinstance(val, dict):
                    val = val.get("distance", val.get("jsd", 0.0))
                degree_scores.append(float(val) if val is not None else float('inf'))
            except Exception:
                degree_scores.append(float('inf'))

        # Method 2: Spectral divergence
        spectral_scores = []
        for ref in references:
            try:
                val = self.spectral_divergence(ref, measure="jsd", bins=20,
                                                include_quarantined=include_quarantined)
                if isinstance(val, dict):
                    val = val.get("jsd", val.get("divergence", 0.0))
                spectral_scores.append(float(val) if val is not None else float('inf'))
            except Exception:
                spectral_scores.append(float('inf'))

        # Method 3: Fingerprint distance
        fp_scores = []
        for ref in references:
            try:
                val = self.fingerprint_distance(ref)
                if isinstance(val, dict):
                    val = val.get("distance", val.get("l2_distance", 0.0))
                fp_scores.append(float(val) if val is not None else float('inf'))
            except Exception:
                fp_scores.append(float('inf'))

        # ── Compute ranks (1-based, lower score = better = rank 1) ──
        def _rank(scores: list[float]) -> list[int]:
            """Return ranks where rank 1 = smallest score."""
            indexed = sorted(range(len(scores)), key=lambda i: scores[i])
            ranks = [0] * len(scores)
            for rank_pos, idx in enumerate(indexed, 1):
                ranks[idx] = rank_pos
            return ranks

        degree_ranks = _rank(degree_scores)
        spectral_ranks = _rank(spectral_scores)
        fp_ranks = _rank(fp_scores)

        # ── Check which methods are valid (not all inf) ────────────
        methods_used = []
        method_data = []
        if not all(s == float('inf') for s in degree_scores):
            methods_used.append("degree_jsd")
            method_data.append(("degree_rank", degree_ranks))
        if not all(s == float('inf') for s in spectral_scores):
            methods_used.append("spectral_divergence")
            method_data.append(("spectral_rank", spectral_ranks))
        if not all(s == float('inf') for s in fp_scores):
            methods_used.append("fingerprint_distance")
            method_data.append(("fingerprint_rank", fp_ranks))

        if not methods_used:
            return None

        # ── Compute RRF scores ─────────────────────────────────────
        rankings = []
        for i in range(n):
            rrf = 0.0
            entry: dict = {"index": i}
            for method_name, ranks in method_data:
                contribution = 1.0 / (k + ranks[i])
                rrf += contribution
                entry[method_name] = ranks[i]
            entry["rrf_score"] = round(rrf, 8)
            # Label
            try:
                ref_stats = references[i].stats()
                entry["label"] = f"ref_{i}"
            except Exception:
                entry["label"] = f"ref_{i}"
            # Raw scores for diagnostics
            entry["degree_raw"] = round(degree_scores[i], 8) if degree_scores[i] != float('inf') else None
            entry["spectral_raw"] = round(spectral_scores[i], 8) if spectral_scores[i] != float('inf') else None
            entry["fingerprint_raw"] = round(fp_scores[i], 8) if fp_scores[i] != float('inf') else None
            rankings.append(entry)

        # Sort by RRF score descending (higher = better)
        rankings.sort(key=lambda x: x["rrf_score"], reverse=True)

        best = rankings[0]["rrf_score"]
        second = rankings[1]["rrf_score"] if len(rankings) > 1 else 0.0
        margin = round(best - second, 8)
        confidence = round(best / second, 8) if second > 1e-12 else float('inf')

        return {
            "best_match":   rankings[0]["index"],
            "best_score":   best,
            "rankings":     rankings,
            "k":            k,
            "methods_used": methods_used,
            "confidence":   confidence,
            "margin":       margin,
        }

    # ------------------------------------------------------------------
    # Cycle 327: bayesian_classification() — confidence-weighted
    # adaptive ensemble (Research #038)
    # ------------------------------------------------------------------

    def bayesian_classification(self,
                                references: list["MemoryGraph"],
                                *,
                                degree_index: str = "sombor",
                                min_separation: float = 1e-6,
                                include_quarantined: bool = False,
                                ) -> Optional[dict]:
        """Classify against reference graphs using **Bayesian fusion**.

        Unlike RRF (rank-based, equal weight) or hybrid_classification
        (fixed weights), Bayesian fusion **adapts weights per query**
        based on how decisively each method separates the best match
        from the rest.

        **Core idea** (Research #038):

        Each of the three methods (degree JSD, spectral divergence,
        fingerprint distance) produces a *separation score* — how much
        the best reference stands out from the runner-up, relative to
        the full score range.  Methods that are more decisive for
        *this particular query* get more influence.

        **Algorithm:**

        1. Compute raw scores for each method across all references.
        2. Min-max normalise each method to [0, 1] (0 = best).
        3. Compute per-method **separation**::

               sep_m = (norm_second − norm_best) / (norm_max − norm_best)

           where best/second are the two smallest normalised scores.
           If all scores are identical, separation = 0 (no information).
        4. Normalise separations to sum to 1 → **adaptive weights**.
        5. Final score = Σ (w_m × norm_score_m).

        **Why Bayesian?**

        - **Self-adaptive**: a method that is ambiguous for one query
          but decisive for another automatically gets different weight.
        - **No tuning**: no free parameters (unlike hybrid's weight
          tuple or RRF's k).
        - **Per-method diagnostics**: return value includes each
          method's raw score, normalised score, separation, and weight
          — full transparency for triple-loop quality.
        - **Graceful degradation**: if a method fails (returns None
          or inf for all references), it's excluded and the remaining
          methods re-normalise.

        **Comparison with other strategies:**

        ===========  ==========  ==========  ==========
        Strategy     Weighting   Scale-inv?  Adaptive?
        ===========  ==========  ==========  ==========
        RRF          Equal rank  Yes         No
        Hybrid       Fixed       No (norm)   No
        **Bayesian** **Conf**    No (norm)   **Yes**
        Max Conf     Winner      Per-method  Yes
        ===========  ==========  ==========  ==========

        Args:
            references:          list of reference MemoryGraphs.
            degree_index:        degree index for entropy distance.
            min_separation:      floor to avoid div-by-zero when all
                                 separations are near zero.
            include_quarantined: passed to spectral methods.

        Returns:
            Dict with:
            - ``best_match``: int — index of closest reference
            - ``best_score``: float — ensemble score (lower = better)
            - ``rankings``: list of dicts per reference with:
              ``index``, ``score``, per-method ``_raw``/``_norm``/
              ``_weight`` values, ``label``
            - ``methods_used``: list of method names that contributed
            - ``method_info``: dict per method with ``separation``
              and ``weight`` — the key Bayesian diagnostic
            - ``confidence``: float — ``(2nd − best) / best``
            - ``margin``: float — ``2nd − best``
            or ``None`` if no valid comparisons.
        """
        n = len(references)
        if n == 0:
            return None

        # ── Step 1: Compute raw scores per method ──────────────────
        method_names = ["degree_jsd", "spectral_divergence", "fingerprint_distance"]
        raw_scores: dict[str, list[float | None]] = {}

        # Degree JSD
        deg: list[float | None] = []
        for ref in references:
            try:
                val = self.entropy_distance(ref, index=degree_index)
                deg.append(float(val) if val is not None else None)
            except Exception:
                deg.append(None)
        raw_scores["degree_jsd"] = deg

        # Spectral divergence
        spec: list[float | None] = []
        for ref in references:
            try:
                val = self.spectral_divergence(
                    ref, measure="jsd", bins=20,
                    include_quarantined=include_quarantined,
                )
                spec.append(float(val) if val is not None else None)
            except Exception:
                spec.append(None)
        raw_scores["spectral_divergence"] = spec

        # Fingerprint distance
        fp: list[float | None] = []
        for ref in references:
            try:
                val = self.fingerprint_distance(ref)
                fp.append(float(val) if val is not None else None)
            except Exception:
                fp.append(None)
        raw_scores["fingerprint_distance"] = fp

        # ── Step 2: Min-max normalise each method ──────────────────
        def _min_max(vals: list[float | None]) -> list[float | None]:
            valid = [v for v in vals if v is not None]
            if not valid:
                return [None] * len(vals)
            lo, hi = min(valid), max(valid)
            rng = hi - lo
            if rng < 1e-15:
                # All identical — no discriminative power
                return [0.0 if v is not None else None for v in vals]
            return [(v - lo) / rng if v is not None else None for v in vals]

        norm_scores = {m: _min_max(raw_scores[m]) for m in method_names}

        # ── Step 3: Compute per-method separation ──────────────────
        # separation = how decisively the best match stands out
        def _separation(norms: list[float | None]) -> float:
            valid = sorted(v for v in norms if v is not None)
            if len(valid) < 2:
                return 0.0
            best_val = valid[0]
            second_val = valid[1]
            max_val = valid[-1]
            denom = max_val - best_val
            if denom < min_separation:
                return 0.0
            return (second_val - best_val) / denom

        separations = {m: _separation(norm_scores[m]) for m in method_names}

        # Exclude methods with zero separation or all-None scores
        active_methods = [
            m for m in method_names
            if separations[m] > 0
            and any(v is not None for v in norm_scores[m])
        ]

        if not active_methods:
            # Fallback: if all methods have zero separation, use equal
            # weights among methods that produced valid scores
            active_methods = [
                m for m in method_names
                if any(v is not None for v in norm_scores[m])
            ]
            if not active_methods:
                return None
            for m in active_methods:
                separations[m] = 1.0  # equal weight

        # ── Step 4: Normalise separations → adaptive weights ───────
        total_sep = sum(separations[m] for m in active_methods)
        weights = {m: separations[m] / total_sep for m in active_methods}

        # ── Step 5: Compute ensemble scores ────────────────────────
        rankings = []
        for i in range(n):
            # Gather per-method normalised scores
            per_method_norm = {}
            available = []
            for m in active_methods:
                v = norm_scores[m][i]
                per_method_norm[m] = v
                if v is not None:
                    available.append(v)

            if not available:
                continue

            # If some methods are missing for this ref, redistribute
            # weight among available methods
            avail_methods = [
                m for m in active_methods
                if per_method_norm[m] is not None
            ]
            if len(avail_methods) < len(active_methods):
                avail_total = sum(separations[m] for m in avail_methods)
                if avail_total > 0:
                    avail_weights = {
                        m: separations[m] / avail_total for m in avail_methods
                    }
                else:
                    avail_weights = {m: 1.0 / len(avail_methods) for m in avail_methods}
            else:
                avail_weights = {m: weights[m] for m in avail_methods}

            score = sum(
                avail_weights[m] * per_method_norm[m]
                for m in avail_methods
            )

            entry = {
                "index": i,
                "score": round(score, 8),
            }
            for m in method_names:
                entry[f"{m}_raw"] = (
                    round(raw_scores[m][i], 8)
                    if raw_scores[m][i] is not None else None
                )
                entry[f"{m}_norm"] = (
                    round(norm_scores[m][i], 8)
                    if norm_scores[m][i] is not None else None
                )
                entry[f"{m}_weight"] = round(avail_weights.get(m, 0.0), 8)

            # Label
            try:
                label = (
                    references[i].graph_meta.get("label")
                    if hasattr(references[i], "graph_meta") else None
                )
            except Exception:
                label = None
            entry["label"] = label

            rankings.append(entry)

        if not rankings:
            return None

        rankings.sort(key=lambda x: x["score"])

        best = rankings[0]["score"]
        second = rankings[1]["score"] if len(rankings) > 1 else best
        margin = round(second - best, 8)
        confidence = (
            round(margin / best, 8) if best > 1e-12
            else float("inf") if margin > 0 else 0.0
        )

        # Method info diagnostic
        method_info = {}
        for m in method_names:
            method_info[m] = {
                "separation": round(separations.get(m, 0.0), 8),
                "weight": round(weights.get(m, 0.0), 8),
                "active": m in active_methods,
            }

        return {
            "best_match":    rankings[0]["index"],
            "best_score":    best,
            "rankings":      rankings,
            "methods_used":  active_methods,
            "method_info":   method_info,
            "confidence":    confidence,
            "margin":        margin,
        }

    # ------------------------------------------------------------------
    # Cycle 328: classification_compare() — multi-method consensus
    # report (capstone of classification suite)
    # ------------------------------------------------------------------

    def classification_compare(self,
                               references: list["MemoryGraph"],
                               *,
                               degree_index: str = "sombor",
                               include_quarantined: bool = False,
                               ) -> Optional[dict]:
        """Run **all classification methods** and produce a comparison
        report.

        This is the capstone of the classification suite.  Instead of
        choosing one method, run them all and see where they agree,
        where they disagree, and what the consensus says.

        **Methods executed:**

        1. ``graph_classification`` — degree-based entropy distance
        2. ``spectral_classification`` — spectral divergence
        3. ``hybrid_classification`` — fixed-weight ensemble
        4. ``rrf_classification`` — Reciprocal Rank Fusion
        5. ``bayesian_classification`` — adaptive-weight ensemble

        **Key outputs:**

        - **consensus_best**: the reference chosen by the majority of
          methods.  If all methods agree, confidence is high.
        - **agreement_score**: fraction of methods that chose the
          consensus best (0 to 1).
        - **per_method**: each method's best_match, score, and margin.
        - **per_reference**: how many methods picked each reference,
          and the average rank across methods.
        - **disagreement_flag**: True if < 50% of methods agree.

        **Production use:**

        Call ``classification_compare()`` first.  If ``agreement_score``
        is 1.0, trust the result.  If < 0.5, investigate *why* methods
        disagree — it may indicate a genuinely ambiguous query or a
        reference set that needs refinement.

        Args:
            references:          list of reference MemoryGraphs.
            degree_index:        degree index for entropy distance.
            include_quarantined: include quarantined nodes.

        Returns:
            Dict with:
            - ``consensus_best``: int — majority-vote best reference
            - ``agreement_score``: float — fraction agreeing
            - ``agreement_count``: str — "N/M methods"
            - ``disagreement_flag``: bool — True if agreement < 0.5
            - ``methods_run``: list of method names executed
            - ``methods_failed``: list of method names that errored
            - ``per_method``: dict → {method: {best_match, best_score,
              margin, confidence}}
            - ``per_reference``: dict → {ref_idx: {votes, avg_rank,
              methods_voted}}
            - ``recommendation``: str — human-readable summary
            or ``None`` if no methods succeeded.
        """
        n = len(references)
        if n == 0:
            return None

        method_names = [
            "graph_classification",
            "spectral_classification",
            "hybrid_classification",
            "rrf_classification",
            "bayesian_classification",
        ]

        # ── Run each method ────────────────────────────────────────
        per_method: dict[str, dict] = {}
        methods_run: list[str] = []
        methods_failed: list[str] = []

        for name in method_names:
            try:
                if name == "graph_classification":
                    result = self.graph_classification(
                        references, degree_index=degree_index)
                elif name == "spectral_classification":
                    result = self.spectral_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                elif name == "hybrid_classification":
                    result = self.hybrid_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                elif name == "rrf_classification":
                    result = self.rrf_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                elif name == "bayesian_classification":
                    result = self.bayesian_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                else:
                    continue

                if result is not None:
                    per_method[name] = {
                        "best_match": result.get("best_match"),
                        "best_score": result.get("best_score"),
                        "margin":     result.get("margin"),
                        "confidence": result.get("confidence"),
                    }
                    methods_run.append(name)
                else:
                    methods_failed.append(name)
            except Exception:
                methods_failed.append(name)

        if not methods_run:
            return None

        # ── Tally votes per reference ──────────────────────────────
        vote_counts: dict[int, list[str]] = {}
        for m, info in per_method.items():
            bm = info["best_match"]
            if bm is not None:
                vote_counts.setdefault(bm, []).append(m)

        if not vote_counts:
            return None

        # Consensus: reference with most votes (ties → lowest avg score)
        best_ref = max(vote_counts,
                       key=lambda r: (len(vote_counts[r]),
                                      -sum(per_method[m]["best_score"] or 0
                                           for m in vote_counts[r])))
        agreement = len(vote_counts[best_ref]) / len(methods_run)

        # ── Per-reference summary ──────────────────────────────────
        per_reference: dict[int, dict] = {}
        for i in range(n):
            voters = vote_counts.get(i, [])
            # Compute average rank across all methods
            ranks = []
            for m, info in per_method.items():
                bm = info["best_match"]
                if bm is None:
                    continue
                # Build a simple rank: 1 if this ref is the method's
                # best_match, else 2+ (we don't have full rankings
                # per method here, so approximate)
                ranks.append(1 if bm == i else 2)
            avg_rank = round(sum(ranks) / len(ranks), 4) if ranks else None
            per_reference[i] = {
                "votes":         len(voters),
                "vote_fraction": round(len(voters) / len(methods_run), 4),
                "methods_voted": voters,
                "avg_rank":      avg_rank,
            }

        # ── Recommendation text ────────────────────────────────────
        if agreement == 1.0:
            rec = (f"All {len(methods_run)} methods agree: "
                   f"reference #{best_ref} is the best match.")
        elif agreement >= 0.5:
            rec = (f"Majority ({len(vote_counts[best_ref])}/"
                   f"{len(methods_run)}) chose reference #{best_ref}.")
        else:
            rec = (f"Methods disagree — no majority. "
                   f"Leading reference #{best_ref} with "
                   f"{len(vote_counts[best_ref])}/{len(methods_run)} votes.")

        return {
            "consensus_best":     best_ref,
            "agreement_score":    round(agreement, 4),
            "agreement_count":    f"{len(vote_counts[best_ref])}/{len(methods_run)}",
            "disagreement_flag":  agreement < 0.5,
            "methods_run":        methods_run,
            "methods_failed":     methods_failed,
            "per_method":         per_method,
            "per_reference":      per_reference,
            "recommendation":     rec,
        }

    # ── Cycle 329: k-NN classification with distance-weighted voting ──

    def knn_classification(self,
                          references: list["MemoryGraph"],
                          *,
                          k: int = 3,
                          method: str = "hybrid",
                          degree_index: str = "sombor",
                          include_quarantined: bool = False,
                          ) -> Optional[dict]:
        """k-nearest reference graph classification with distance-
        weighted voting.

        Instead of returning only the single best match, this method
        considers the **top-k** nearest references and aggregates their
        votes weighted by inverse distance.  When multiple references
        share a label (via ``graph_meta["label"]``), votes pool per
        label — making the classifier robust when several prototypes
        represent the same category.

        **Motivation:**

        Single-match classification is fragile when the query sits near
        a decision boundary between two similar references.  A small
        perturbation can flip the best match.  k-NN voting smooths
        this out: the consensus of 3–5 neighbours is far more stable
        than a single point estimate.

        **Algorithm:**

        1. Compute scores for all references using the chosen base
           method (``hybrid``, ``graph``, ``spectral``, ``rrf``, or
           ``bayesian``).
        2. Sort ascending by score (lower = closer).
        3. Take top-``k`` references (``k`` is clamped to
           ``min(k, len(references))``).
        4. Weight each neighbour by ``1 / (score + ε)`` where
           ``ε = 1e-12`` prevents division by zero.
        5. If labels are available, pool weights per label.
        6. Return the label (or reference) with the highest pooled
           weight.

        **Weighting:**

        Inverse-distance weighting means the closest neighbour has
        the most influence, but the 2nd and 3rd neighbours still get
        a voice.  This is preferable to majority voting (which treats
        all k neighbours equally) when scores are well-separated.

        **When to use:**

        - **Multiple references per category** — the killer use case.
          If you have 3 prototypes for "star" and 2 for "path", k-NN
          pools their votes for a more robust decision.
        - **Noisy or ambiguous queries** — k=3 or 5 smooths out
          perturbations.
        - **Not needed** when references are perfectly distinct and
          well-separated — single-match from ``graph_classification``
          is sufficient and faster.

        Args:
            references:          list of reference MemoryGraphs.
            k:                   number of nearest neighbours (default 3).
            method:              base scoring method:
                                 ``"hybrid"``, ``"graph"``,
                                 ``"spectral"``, ``"rrf"``, or
                                 ``"bayesian"``.
            degree_index:        degree index for entropy distance.
            include_quarantined: include quarantined nodes.

        Returns:
            Dict with:
            - ``best_label``: str or int — consensus label (or ref
              index if no labels).
            - ``best_ref``: int — index of the single closest match.
            - ``best_score``: float — score of the closest match.
            - ``k_used``: int — actual k (min(k, len(refs))).
            - ``method``: str — base method name.
            - ``k_nearest``: list of dicts, each with:
              ``index``, ``label``, ``score``, ``vote_weight``,
              ``vote_fraction``.
            - ``label_votes``: dict → {label: total_weight}, sorted
              descending.
            - ``agreement``: float — winner's vote fraction.
            - ``tie``: bool — True if top-2 labels within 10%.
            - ``margin``: float — gap between top-2 vote weights.
            or ``None`` if scoring fails for all references.
        """
        if k <= 0:
            raise ValueError(
                f"k must be a positive integer, got {k}")

        n = len(references)
        if n == 0:
            return None

        k_actual = min(k, n)

        # ── Delegate to chosen base method for scoring ────────────
        if method == "hybrid":
            base = self.hybrid_classification(
                references, degree_index=degree_index,
                include_quarantined=include_quarantined)
        elif method == "graph":
            base = self.graph_classification(
                references, method="jsd", index=degree_index)
        elif method == "spectral":
            base = self.spectral_classification(
                references,
                include_quarantined=include_quarantined)
        elif method == "rrf":
            base = self.rrf_classification(
                references, degree_index=degree_index,
                include_quarantined=include_quarantined)
        elif method == "bayesian":
            base = self.bayesian_classification(
                references, degree_index=degree_index,
                include_quarantined=include_quarantined)
        else:
            raise ValueError(
                f"unknown method '{method}'; choose from "
                f"hybrid/graph/spectral/rrf/bayesian")

        if base is None:
            return None

        raw_rankings = base.get("rankings")
        if not raw_rankings:
            return None

        # ── Normalise ranking entries to {index, score} ascending ──
        # Different base methods use different score keys and sort
        # orders.  Normalise so the rest of k-NN logic is uniform.
        rankings = []
        for entry in raw_rankings:
            idx = entry.get("index")
            # graph/hybrid/bayesian use "score" (ascending).
            # rrf uses "rrf_score" (descending → negate).
            if "score" in entry:
                s = entry["score"]
            elif "rrf_score" in entry:
                s = -entry["rrf_score"]  # negate for ascending
            else:
                continue
            rankings.append({"index": idx, "score": s})

        if not rankings:
            return None

        # Sort ascending by normalised score (lower = closer)
        rankings.sort(key=lambda x: x["score"])

        # ── Extract labels for all references ──────────────────────
        labels: list = []
        for i in range(n):
            try:
                lbl = references[i].graph_meta.get("label") \
                    if hasattr(references[i], "graph_meta") else None
            except Exception:
                lbl = None
            labels.append(lbl if lbl is not None else i)

        # ── Build k-nearest with vote weights ─────────────────────
        eps = 1e-12
        k_nearest = []
        for entry in rankings[:k_actual]:
            idx = entry["index"]
            score = entry["score"]
            # For RRF (negative scores from negation), use absolute
            # value for distance weighting.
            dist = abs(score)
            weight = 1.0 / (dist + eps)
            k_nearest.append({
                "index":         idx,
                "label":         labels[idx],
                "score":         score,
                "vote_weight":   round(weight, 8),
            })

        total_weight = sum(e["vote_weight"] for e in k_nearest)
        for e in k_nearest:
            e["vote_fraction"] = round(e["vote_weight"] / total_weight,
                                        6) if total_weight > 0 else 0.0

        # ── Pool votes per label ──────────────────────────────────
        label_votes: dict = {}
        for e in k_nearest:
            label_votes[e["label"]] = round(
                label_votes.get(e["label"], 0.0) + e["vote_weight"], 8)

        sorted_labels = sorted(label_votes.items(),
                               key=lambda x: -x[1])
        best_label = sorted_labels[0][0]
        best_vote = sorted_labels[0][1]

        # Agreement = winner's share of total vote
        agreement = round(best_vote / total_weight, 6) \
            if total_weight > 0 else 0.0

        # Tie detection: top-2 within 10% of each other
        if len(sorted_labels) >= 2:
            second_vote = sorted_labels[1][1]
            margin = round(best_vote - second_vote, 8)
            tie = (second_vote / best_vote) >= 0.9 if best_vote > 0 \
                else True
        else:
            margin = round(best_vote, 8)
            tie = False

        return {
            "best_label":   best_label,
            "best_ref":      rankings[0]["index"],
            "best_score":    rankings[0]["score"],
            "k_used":        k_actual,
            "method":        method,
            "k_nearest":     k_nearest,
            "label_votes":   dict(sorted_labels),
            "agreement":     agreement,
            "tie":           tie,
            "margin":        margin,
        }

    # ------------------------------------------------------------------
    # Cycle 330: weighted_average_classification() — explicit weight
    # control over all 3 modalities (Research #038 strategy 3/4)
    # ------------------------------------------------------------------

    def weighted_average_classification(
        self,
        references: list["MemoryGraph"],
        *,
        degree_weight: float = 1.0,
        spectral_weight: float = 1.0,
        fingerprint_weight: float = 1.0,
        degree_index: str = "sombor",
        spectral_measure: str = "jsd",
        bins: int = 20,
        normalise: str = "minmax",
        include_quarantined: bool = False,
    ) -> Optional[dict]:
        """Classify against reference graphs using **user-controlled
        weighted average** of all three topological modalities.

        Unlike ``hybrid_classification`` (2 modalities) and
        ``rrf_classification`` (parameter-free rank fusion), this method
        gives the caller **explicit weight control** over all three
        comparison domains:

        1. **Degree-based** (local structure) — JSD on edge-contribution
           distributions.
        2. **Spectral** (global topology) — JSD on Laplacian eigenvalue
           histograms.
        3. **Fingerprint** (multi-dimensional shape) — L2 on entropy
           feature vectors.

        Each modality's raw scores are normalised to [0, 1] across the
        reference set, then combined as:

        .. code-block:: text

            score_i = w_d * norm_degree_i
                    + w_s * norm_spectral_i
                    + w_f * norm_fingerprint_i

        Weights are normalised to sum to 1. A weight of 0 excludes that
        modality entirely.

        **When to use this vs other ensemble methods?**

        - ``hybrid_classification``: 2 modalities, good default.
        - ``rrf_classification``: 3 modalities, parameter-free, robust.
        - ``bayesian_classification``: 3 modalities, self-adaptive weights.
        - **This method**: 3 modalities, **user decides** the emphasis.
          Use when you have domain knowledge about which modality
          matters more for your graph types.

        **Normalisation modes:**

        - ``"minmax"``: min-max scale to [0, 1]. Best match → 0.
        - ``"softmax"``: softmax with temperature τ=1 on negated scores.
          Produces probability-like distribution. Best match → highest.

        Args:
            references:          list of reference MemoryGraphs.
            degree_weight:       weight for degree-based modality (≥ 0).
            spectral_weight:     weight for spectral modality (≥ 0).
            fingerprint_weight:  weight for fingerprint modality (≥ 0).
            degree_index:        degree index for entropy distance.
            spectral_measure:    divergence measure for spectral method
                                 ("jsd", "kl", "ce").
            bins:                bin count for spectral histogram.
            normalise:           normalisation mode ("minmax" or "softmax").
            include_quarantined: include quarantined nodes.

        Returns:
            Dict with:
            - ``best_match``: int — index of closest reference
            - ``best_score``: float — ensemble score (lower = better for
              minmax, higher = better for softmax)
            - ``rankings``: list of dicts with per-modality breakdowns
            - ``weights``: tuple of normalised (degree, spectral, fingerprint)
            - ``normalise``: normalisation mode used
            - ``methods_used``: list of modalities that contributed
            - ``confidence``: float — separation ratio
            - ``margin``: float — absolute gap
            or ``None`` if no valid comparisons could be made.
        """
        if not references:
            return None

        # Validate weights
        for name, w in [("degree_weight", degree_weight),
                         ("spectral_weight", spectral_weight),
                         ("fingerprint_weight", fingerprint_weight)]:
            if w < 0:
                raise ValueError(f"{name} must be non-negative, got {w}")

        total_w = degree_weight + spectral_weight + fingerprint_weight
        if total_w <= 0:
            raise ValueError(
                "at least one weight must be positive")

        w_d = degree_weight / total_w
        w_s = spectral_weight / total_w
        w_f = fingerprint_weight / total_w

        if normalise not in ("minmax", "softmax"):
            raise ValueError(
                f"normalise must be 'minmax' or 'softmax', got '{normalise}'")

        n = len(references)

        # ── Compute raw scores per modality ──────────────────────
        raw_degree: list[float | None] = []
        raw_spectral: list[float | None] = []
        raw_fingerprint: list[float | None] = []

        for ref in references:
            # Degree-based
            try:
                d = self.entropy_distance(ref, index=degree_index)
                if isinstance(d, dict):
                    d = d.get("distance", d.get("jsd", 0.0))
                raw_degree.append(float(d) if d is not None else None)
            except Exception:
                raw_degree.append(None)

            # Spectral
            try:
                s = self.spectral_divergence(
                    ref, measure=spectral_measure, bins=bins,
                    include_quarantined=include_quarantined)
                if isinstance(s, dict):
                    s = s.get("jsd", s.get("divergence", 0.0))
                raw_spectral.append(float(s) if s is not None else None)
            except Exception:
                raw_spectral.append(None)

            # Fingerprint
            try:
                f = self.fingerprint_distance(ref)
                if isinstance(f, dict):
                    f = f.get("distance", f.get("l2_distance", 0.0))
                raw_fingerprint.append(float(f) if f is not None else None)
            except Exception:
                raw_fingerprint.append(None)

        # ── Determine which modalities are active ────────────────
        methods_used = []
        if w_d > 0 and any(v is not None for v in raw_degree):
            methods_used.append("degree")
        if w_s > 0 and any(v is not None for v in raw_spectral):
            methods_used.append("spectral")
        if w_f > 0 and any(v is not None for v in raw_fingerprint):
            methods_used.append("fingerprint")

        if not methods_used:
            return None

        # ── Normalise scores ─────────────────────────────────────
        def _normalise(values: list[float | None],
                       mode: str) -> list[float | None]:
            valid = [v for v in values if v is not None]
            if not valid:
                return [None] * len(values)
            if mode == "minmax":
                lo, hi = min(valid), max(valid)
                rng = hi - lo
                if rng < 1e-15:
                    return [0.0 if v is not None else None for v in values]
                return [(v - lo) / rng if v is not None else None
                        for v in values]
            else:  # softmax
                import math
                neg = [-v if v is not None else None for v in values]
                valid_neg = [v for v in neg if v is not None]
                if not valid_neg:
                    return [None] * len(values)
                max_neg = max(valid_neg)
                exps = [math.exp(v - max_neg) if v is not None else None
                        for v in neg]
                denom = sum(v for v in exps if v is not None)
                if denom < 1e-15:
                    return [0.0 if v is not None else None for v in values]
                return [v / denom if v is not None else None
                        for v in exps]

        norm_degree = _normalise(raw_degree, normalise)
        norm_spectral = _normalise(raw_spectral, normalise)
        norm_fingerprint = _normalise(raw_fingerprint, normalise)

        # ── Compute weighted ensemble scores ────────────────────
        rankings = []
        for i in range(n):
            nd = norm_degree[i]
            ns = norm_spectral[i]
            nf = norm_fingerprint[i]

            # Compute weighted score using available modalities
            score_parts: list[tuple[str, float, float]] = []  # (name, norm_val, weight)
            if nd is not None and w_d > 0:
                score_parts.append(("degree", nd, w_d))
            if ns is not None and w_s > 0:
                score_parts.append(("spectral", ns, w_s))
            if nf is not None and w_f > 0:
                score_parts.append(("fingerprint", nf, w_f))

            if not score_parts:
                continue

            # Renormalise weights for available modalities
            part_total = sum(w for _, _, w in score_parts)
            if part_total < 1e-15:
                continue

            if normalise == "minmax":
                ensemble = sum(w * v / part_total for _, v, w in score_parts)
            else:  # softmax: higher = better, so use as-is
                ensemble = sum(w * v / part_total for _, v, w in score_parts)

            # Extract label
            label = None
            try:
                label = references[i].graph_meta.get("label") \
                    if hasattr(references[i], "graph_meta") else None
            except Exception:
                pass

            rankings.append({
                "index": i,
                "score": round(ensemble, 8),
                "degree_raw": round(raw_degree[i], 8)
                    if raw_degree[i] is not None else None,
                "spectral_raw": round(raw_spectral[i], 8)
                    if raw_spectral[i] is not None else None,
                "fingerprint_raw": round(raw_fingerprint[i], 8)
                    if raw_fingerprint[i] is not None else None,
                "degree_norm": round(nd, 8) if nd is not None else None,
                "spectral_norm": round(ns, 8) if ns is not None else None,
                "fingerprint_norm": round(nf, 8) if nf is not None else None,
                "label": label,
            })

        if not rankings:
            return None

        # Sort: minmax → ascending (lower=better), softmax → descending
        reverse = (normalise == "softmax")
        rankings.sort(key=lambda x: x["score"], reverse=reverse)

        best = rankings[0]["score"]
        second = rankings[1]["score"] if len(rankings) > 1 else best
        margin = round(abs(second - best), 8)
        denom = abs(best) if abs(best) > 1e-12 else 1e-12
        confidence = round(margin / denom, 8)

        return {
            "best_match":   rankings[0]["index"],
            "best_score":   best,
            "rankings":     rankings,
            "weights":      (round(w_d, 8), round(w_s, 8), round(w_f, 8)),
            "normalise":    normalise,
            "methods_used": methods_used,
            "confidence":   confidence,
            "margin":       margin,
        }

    # ── Cycle 313: Ego-local entropy profile (VNEstruct-inspired) ──

    def ego_entropy_profile(self, index: str = "sombor",
                            radius: int = 1,
                            top_k: int = 0) -> Optional[dict]:
        """Per-node ego-network entropy at a given neighbourhood radius.

        Inspired by **VNEstruct** (Dasoulas et al., ICML 2020): ego-local
        entropy captures structural information that global entropy
        averages out.  Each node's *ego-network* is the induced subgraph
        on itself plus all neighbours within *radius* hops.

        **Why ego-local?**
        - Global entropy washes out local patterns (a hub in a sparse
          region is invisible to global measures).
        - Ego-entropy is O(n·k^2) where k = avg degree, vs O(n·m) for
          leave-one-out global entropy (``entropy_contribution``).
        - Nodes with anomalous local entropy are natural candidates for
          anomaly detection, consolidation, or gap analysis.

        **Interpretation:**
        - Low ego-entropy = node sits in a **homogeneous neighbourhood**
          (redundant, consolidation candidate).
        - High ego-entropy = node is in a **diverse neighbourhood**
          (structurally unique, should be preserved).
        - Nodes with zero ego-entropy (no edges in ego-network) are
          **isolated** — either orphan nodes or hubs whose neighbours
          have no inter-connections.

        Args:
            index: Degree-based entropy index (``sombor``, ``randic``,
                ``zagreb_m1``, ``abc``, ``ga``, ``reduced_sombor``,
                ``augmented_zagreb``).
            radius: Neighbourhood hop distance (1 = direct neighbours,
                2 = friends-of-friends, etc.).  Default 1.
            top_k: If > 0, only return the top-*k* nodes by ego-entropy.

        Returns:
            Dict with keys:

            * ``index``: entropy index used
            * ``radius``: neighbourhood radius
            * ``ego_entropy``: ``{node_id: entropy}`` for each node
            * ``ranked``: list of ``(node_id, entropy)`` sorted descending
            * ``mean``: average ego-entropy
            * ``std``: standard deviation
            * ``max``: highest ego-entropy (most diverse neighbourhood)
            * ``min``: lowest ego-entropy (most homogeneous)
            * ``range``: max − min
            * ``field_uniformity``: 1 − (std / mean) ∈ [0, 1]; high =
              uniform field, low = hotspots exist
            * ``hotspots``: nodes with ego-entropy > mean + std
              (diverse neighbourhoods, structurally unique)
            * ``coldspots``: nodes with ego-entropy < mean − std
              (homogeneous neighbourhoods, consolidation candidates)
            * ``isolated``: nodes with zero ego-entropy
            * ``evaluated``: number of nodes evaluated

            Returns ``None`` if the graph has fewer than 2 nodes.
        """
        # ── Contribution functions (reuse from entropy_contribution) ──
        def _sombor_contrib(du, dv):
            return math.sqrt(du * du + dv * dv)

        def _reduced_sombor_contrib(du, dv):
            rm_u, rm_v = max(du - 1, 0), max(dv - 1, 0)
            return math.sqrt(rm_u * rm_u + rm_v * rm_v)

        def _randic_contrib(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            return 1.0 / math.sqrt(du * dv)

        def _zagreb_m1_contrib(du, dv):
            return float(du * du + dv * dv)

        def _abc_contrib(du, dv):
            if du <= 1 or dv <= 1:
                return 0.0
            return math.sqrt((du + dv - 2.0) / (du * dv))

        def _ga_contrib(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            return 2.0 * math.sqrt(du * dv) / (du + dv)

        def _augmented_zagreb_contrib(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            ratio = (du * dv) / (du + dv)
            return ratio ** 3

        CONTRIB_MAP = {
            "sombor":           _sombor_contrib,
            "reduced_sombor":   _reduced_sombor_contrib,
            "randic":           _randic_contrib,
            "zagreb_m1":        _zagreb_m1_contrib,
            "abc":              _abc_contrib,
            "ga":               _ga_contrib,
            "augmented_zagreb": _augmented_zagreb_contrib,
        }
        if index not in CONTRIB_MAP:
            raise ValueError(
                f"Unknown index '{index}'. Valid: {list(CONTRIB_MAP)}"
            )
        contrib_fn = CONTRIB_MAP[index]

        # ── Helper: compute Shannon entropy from edge contributions ──
        def _shannon_entropy(contribs: list[float]) -> float:
            valid = [c for c in contribs if c > 0]
            if not valid:
                return 0.0
            total = sum(valid)
            probs = [c / total for c in valid]
            return -sum(p * math.log(p) for p in probs)

        # ── Collect all nodes ──
        all_nodes = [
            str(r["id"]) for r in self.conn.execute("SELECT id FROM nodes").fetchall()
        ]
        if len(all_nodes) < 2:
            return None

        # ── Pre-build adjacency for BFS ──
        adj: dict[str, set[str]] = {nid: set() for nid in all_nodes}
        for r in self.conn.execute("SELECT source, target FROM edges").fetchall():
            s, t = str(r["source"]), str(r["target"])
            adj.setdefault(s, set()).add(t)
            adj.setdefault(t, set()).add(s)

        # ── Global degree (for contribution calc) ──
        global_deg: dict[str, int] = {nid: len(adj.get(nid, set())) for nid in all_nodes}

        ego_entropy: dict[str, float] = {}

        for nid in all_nodes:
            # BFS to get ego-network node set at given radius
            ego_nodes = {nid}
            frontier = {nid}
            for _ in range(radius):
                next_frontier: set[str] = set()
                for fnid in frontier:
                    next_frontier.update(adj.get(fnid, set()))
                ego_nodes.update(next_frontier)
                frontier = next_frontier

            # Collect edges within ego-network (both endpoints in ego_nodes)
            ego_edges: list[tuple[str, str]] = []
            for s in ego_nodes:
                for t in adj.get(s, set()):
                    if t in ego_nodes and s < t:  # avoid duplicates
                        ego_edges.append((s, t))

            if not ego_edges:
                ego_entropy[nid] = 0.0
                continue

            # Compute contributions using ego-local degrees
            # (degree within the ego-network, not global)
            ego_deg: dict[str, int] = {n: 0 for n in ego_nodes}
            for s, t in ego_edges:
                ego_deg[s] = ego_deg.get(s, 0) + 1
                ego_deg[t] = ego_deg.get(t, 0) + 1

            contribs = [contrib_fn(ego_deg.get(s, 0), ego_deg.get(t, 0))
                        for s, t in ego_edges]
            ego_entropy[nid] = round(_shannon_entropy(contribs), 6)

        # ── Statistics ──
        values = list(ego_entropy.values())
        n_eval = len(values)
        mean_h = sum(values) / n_eval if n_eval else 0.0
        var_h = sum((v - mean_h) ** 2 for v in values) / n_eval if n_eval else 0.0
        std_h = var_h ** 0.5
        min_h = min(values) if values else 0.0
        max_h = max(values) if values else 0.0
        range_h = max_h - min_h
        uniformity = max(0.0, min(1.0, 1.0 - (std_h / mean_h if mean_h > 0 else 1.0)))

        # Hotspots / coldspots / isolated
        hotspots = [nid for nid, h in ego_entropy.items() if h > mean_h + std_h]
        coldspots = [nid for nid, h in ego_entropy.items() if h < max(0.0, mean_h - std_h)]
        isolated = [nid for nid, h in ego_entropy.items() if h == 0.0]

        ranked = sorted(ego_entropy.items(), key=lambda x: -x[1])
        if top_k > 0:
            ranked = ranked[:top_k]

        return {
            "index":            index,
            "radius":            radius,
            "ego_entropy":       ego_entropy,
            "ranked":            ranked,
            "mean":              round(mean_h, 6),
            "std":               round(std_h, 6),
            "max":               round(max_h, 6),
            "min":               round(min_h, 6),
            "range":             round(range_h, 6),
            "field_uniformity":  round(uniformity, 6),
            "hotspots":          hotspots,
            "coldspots":         coldspots,
            "isolated":          isolated,
            "evaluated":         n_eval,
        }

    # ── Cycle 307: Entropy stability under random perturbation ──

    def entropy_stability(self, index: str = "sombor",
                          *, trials: int = 50,
                          edge_fraction: float = 0.1,
                          mode: str = "remove",
                          seed: int | None = None) -> Optional[dict]:
        """Monte Carlo analysis of entropy stability under random perturbation.

        Repeatedly perturbs the graph by removing (or adding noise to)
        a fraction of edges, recomputing the degree-based Shannon entropy
        after each perturbation, and summarising the distribution of
        entropy values.

        **Why stability matters:**
        A graph whose entropy barely changes under perturbation is
        **structurally robust** — small changes in connectivity do not
        alter its information-theoretic properties.  Conversely, a graph
        with high entropy variance is **fragile** — its structural
        diversity depends on specific edges.

        **Perturbation modes:**
        - ``"remove"``: delete *edge_fraction* × *m* random edges
        - ``"rewire"``: rewire *edge_fraction* × *m* random edges
          (preserve degree sequence approximately)

        Args:
            index: Degree-based index (sombor, reduced_sombor, randic,
                zagreb_m1, abc, ga, augmented_zagreb).
            trials: Number of Monte Carlo iterations (default 50).
            edge_fraction: Fraction of *m* edges to perturb per trial
                (0.0–1.0, default 0.1 = 10%).
            mode: Perturbation mode: "remove" or "rewire".
            seed: RNG seed for reproducibility (default None = non-deterministic).

        Returns:
            Dict with:
            - ``baseline_entropy``: H(G) on the original graph
            - ``mean``: mean entropy across trials
            - ``std``: std deviation of entropy across trials
            - ``cv``: coefficient of variation (std/mean), a scale-free
              stability measure (lower = more stable)
            - ``min``: minimum entropy observed
            - ``max``: maximum entropy observed
            - ``range``: max - min
            - ``stability_score``: 1 - cv (clipped to [0, 1]);
              1.0 = perfectly stable, 0.0 = highly unstable
            - ``entropy_values``: list of per-trial entropy values
            - ``perturbed_edges``: number of edges perturbed per trial
            - ``trials``: number of successful trials
            - ``mode`` / ``index``: echoes of parameters

            Returns ``None`` if the graph has < 2 edges or < 3 nodes.
        """
        import random as _rng

        if seed is not None:
            _rng.seed(seed)

        if edge_fraction <= 0 or edge_fraction > 1:
            raise ValueError("edge_fraction must be in (0, 1]")
        if trials < 1:
            raise ValueError("trials must be >= 1")
        if mode not in ("remove", "rewire"):
            raise ValueError(f"Unknown mode '{mode}'; choose 'remove' or 'rewire'")

        # ── Contribution function ──
        def _sombor_c(du, dv):
            return math.sqrt(du * du + dv * dv)

        def _reduced_sombor_c(du, dv):
            return math.sqrt(max(du - 1, 0) ** 2 + max(dv - 1, 0) ** 2)

        def _randic_c(du, dv):
            return 1.0 / math.sqrt(du * dv) if du > 0 and dv > 0 else 0.0

        def _zagreb_m1_c(du, dv):
            return float(du * du + dv * dv)

        def _abc_c(du, dv):
            if du <= 0 or dv <= 0:
                return 0.0
            num = du + dv - 2.0
            if num <= 0:
                return 0.0
            return math.sqrt(num / (du * dv))

        def _ga_c(du, dv):
            return 2.0 * math.sqrt(du * dv) / (du + dv) if du > 0 and dv > 0 else 0.0

        def _aug_az_c(du, dv):
            return ((du * dv) / (du + dv)) ** 3 if du > 0 and dv > 0 else 0.0

        CONTRIB = {
            "sombor":           _sombor_c,
            "reduced_sombor":   _reduced_sombor_c,
            "randic":           _randic_c,
            "zagreb_m1":        _zagreb_m1_c,
            "abc":              _abc_c,
            "ga":               _ga_c,
            "augmented_zagreb": _aug_az_c,
        }
        if index not in CONTRIB:
            raise ValueError(f"Unknown index '{index}'. Valid: {list(CONTRIB)}")
        contrib_fn = CONTRIB[index]

        def _shannon(contribs: list[float]) -> Optional[float]:
            valid = [c for c in contribs if c > 0]
            if not valid:
                return 0.0 if contribs else None
            total = sum(valid)
            if total <= 0:
                return None
            m = len(valid)
            h = 0.0
            for c in valid:
                p = c / total
                if p > 0:
                    h -= p * math.log(p)
            if m > 1:
                h /= math.log(m)
            return h

        # ── Cache graph state ──
        node_rows = self.conn.execute("SELECT id FROM nodes").fetchall()
        all_node_ids = [str(r["id"]) for r in node_rows]
        edge_rows = self.conn.execute("SELECT source, target FROM edges").fetchall()
        all_edges = [(str(r["source"]), str(r["target"])) for r in edge_rows]

        n_nodes = len(all_node_ids)
        n_edges = len(all_edges)
        if n_nodes < 3 or n_edges < 2:
            return None

        # Compute original degrees
        orig_deg: dict[str, int] = {}
        for nid in all_node_ids:
            orig_deg[nid] = self.degree(nid)

        # Baseline entropy
        base_contribs = [
            contrib_fn(orig_deg.get(s, 0), orig_deg.get(t, 0))
            for s, t in all_edges
        ]
        baseline = _shannon(base_contribs)
        if baseline is None:
            return None

        # Number of edges to perturb per trial
        n_perturb = max(1, int(n_edges * edge_fraction))

        # Adjacency for rewire mode
        if mode == "rewire":
            adjacency: dict[str, set[str]] = {nid: set() for nid in all_node_ids}
            for s, t in all_edges:
                adjacency.setdefault(s, set()).add(t)
                adjacency.setdefault(t, set()).add(s)

        entropy_values: list[float] = []

        for _trial in range(trials):
            # Copy current state
            trial_deg = dict(orig_deg)
            trial_edges = list(all_edges)

            if mode == "remove":
                # Remove n_perturb random edges
                indices_to_remove = set(
                    _rng.sample(range(len(trial_edges)), min(n_perturb, len(trial_edges)))
                )
                kept_edges = [
                    e for i, e in enumerate(trial_edges)
                    if i not in indices_to_remove
                ]
                # Update degrees
                for idx in indices_to_remove:
                    s, t = trial_edges[idx]
                    trial_deg[s] = max(0, trial_deg.get(s, 0) - 1)
                    trial_deg[t] = max(0, trial_deg.get(t, 0) - 1)
                trial_edges = kept_edges

            elif mode == "rewire":
                # Rewire n_perturb random edges: pick an edge, detach one
                # endpoint, reconnect to a random different node
                for _ in range(n_perturb):
                    if len(trial_edges) == 0:
                        break
                    ei = _rng.randrange(len(trial_edges))
                    s, t = trial_edges[ei]
                    # Choose which endpoint to rewire
                    if _rng.random() < 0.5:
                        # Rewire target
                        new_t = _rng.choice(all_node_ids)
                        if new_t == s or new_t == t or new_t in adjacency.get(s, set()):
                            continue
                        trial_edges[ei] = (s, new_t)
                        trial_deg[t] = max(0, trial_deg.get(t, 0) - 1)
                        trial_deg[new_t] = trial_deg.get(new_t, 0) + 1
                    else:
                        # Rewire source
                        new_s = _rng.choice(all_node_ids)
                        if new_s == s or new_s == t or new_s in adjacency.get(t, set()):
                            continue
                        trial_edges[ei] = (new_s, t)
                        trial_deg[s] = max(0, trial_deg.get(s, 0) - 1)
                        trial_deg[new_s] = trial_deg.get(new_s, 0) + 1

            # Compute entropy on perturbed graph
            perturbed_contribs = [
                contrib_fn(trial_deg.get(s, 0), trial_deg.get(t, 0))
                for s, t in trial_edges
            ]
            h = _shannon(perturbed_contribs)
            if h is not None:
                entropy_values.append(h)

        if not entropy_values:
            return None

        n_val = len(entropy_values)
        mean_h = sum(entropy_values) / n_val
        var_h = sum((v - mean_h) ** 2 for v in entropy_values) / n_val
        std_h = var_h ** 0.5
        min_h = min(entropy_values)
        max_h = max(entropy_values)
        cv = std_h / mean_h if mean_h > 0 else float("inf")
        stability = max(0.0, min(1.0, 1.0 - cv))

        return {
            "baseline_entropy":  round(baseline, 6),
            "mean":              round(mean_h, 6),
            "std":               round(std_h, 6),
            "cv":                round(cv, 6),
            "min":               round(min_h, 6),
            "max":               round(max_h, 6),
            "range":             round(max_h - min_h, 6),
            "stability_score":   round(stability, 6),
            "entropy_values":    [round(v, 6) for v in entropy_values],
            "perturbed_edges":   n_perturb,
            "trials":            n_val,
            "mode":              mode,
            "index":             index,
        }

    # ── Cycle 308: Spectral divergence ─────────────────────────────

    def spectral_divergence(
        self,
        other: "MemoryGraph",
        *,
        measure: str = "jsd",
        bins: int = 20,
        include_quarantined: bool = False,
    ) -> Optional[float]:
        r"""Information-theoretic divergence between the Laplacian
        eigenvalue **distributions** of two graphs.

        Unlike ``quantum_jensen_shannon_distance()`` (which compares
        eigenvalue vectors elementwise after zero-padding), this method
        bins eigenvalues into a **common histogram** on ``[0, λ_max]``
        and then computes the chosen divergence on the normalised
        bin probabilities.

        **Why histogram-based spectral comparison?**

        - **Size-invariant**: graphs with different node counts share
          the same binning grid, so the comparison is meaningful.
        - **Shape-sensitive**: captures the overall *form* of the
          spectrum (e.g.\ uniform vs peaked vs bimodal) rather than
          individual eigenvalue positions.
        - **Robust**: small perturbations to graph topology shift
          eigenvalues slightly but rarely move them across bin
          boundaries, producing stable divergence values.

        **Binning:**

        Both spectra are binned on ``[0, λ_max]`` where
        ``λ_max = max(λ_max_A, λ_max_B)``.  Each eigenvalue is placed
        into ``⌊k · λᵢ / λ_max⌋`` (clamped to ``bins−1``).  The
        histograms are normalised to sum to 1.

        **Measures:**

        - ``"jsd"`` — Jensen-Shannon distance: √(½KL(P‖M)+½KL(Q‖M)),
          M = ½(P+Q).  Symmetric, bounded [0, √ln2].
        - ``"kl"`` — KL divergence: Σ p·ln(p/q), p>0.
          Asymmetric: KL(P‖Q) ≠ KL(Q‖P).
          Returns KL(self ‖ other).
        - ``"ce"`` — Cross-entropy: −Σ p·ln(q), p>0.
          Asymmetric: H(self, other).

        Zero-probability bins where the other distribution has mass
        are clamped to ``q = 1e-12`` to prevent infinite KL/CE.

        Args:
            other:               Graph to compare against.
            measure:             "jsd", "kl", or "ce".
            bins:                Number of histogram bins (default 20).
            include_quarantined: Include quarantined nodes.

        Returns:
            float, or ``None`` if either graph has < 2 nodes or
            < 1 edge.
        """
        evals_a = self._laplacian_eigenvalues(
            include_quarantined=include_quarantined
        )
        evals_b = other._laplacian_eigenvalues(
            include_quarantined=include_quarantined
        )
        if evals_a is None or evals_b is None:
            return None

        sum_a = sum(evals_a)
        sum_b = sum(evals_b)
        if sum_a <= 0 or sum_b <= 0:
            return None

        if measure not in ("jsd", "kl", "ce"):
            raise ValueError(
                f"unknown measure '{measure}'; choose from jsd/kl/ce"
            )
        if bins < 2:
            raise ValueError("bins must be >= 2")

        # ── Common binning grid ──
        lam_max = max(max(evals_a), max(evals_b))
        if lam_max <= 0:
            return None

        def _histogram(evals: list[float]) -> list[float]:
            counts = [0.0] * bins
            for e in evals:
                idx = int(e / lam_max * bins)
                if idx >= bins:
                    idx = bins - 1
                counts[idx] += 1.0
            total = sum(counts)
            if total > 0:
                counts = [c / total for c in counts]
            return counts

        p = _histogram(evals_a)
        q = _histogram(evals_b)
        eps = 1e-12

        if measure == "jsd":
            m = [(p[i] + q[i]) / 2.0 for i in range(bins)]
            s_pm = 0.0
            s_qm = 0.0
            for i in range(bins):
                if p[i] > eps and m[i] > eps:
                    s_pm += p[i] * (math.log(p[i]) - math.log(m[i]))
                if q[i] > eps and m[i] > eps:
                    s_qm += q[i] * (math.log(q[i]) - math.log(m[i]))
            jsd = 0.5 * s_pm + 0.5 * s_qm
            if jsd < 0:
                jsd = 0.0
            return math.sqrt(jsd)

        elif measure == "kl":
            total = 0.0
            for i in range(bins):
                if p[i] > eps:
                    q_i = q[i] if q[i] > eps else eps
                    total += p[i] * (math.log(p[i]) - math.log(q_i))
            return total

        else:  # ce
            total = 0.0
            for i in range(bins):
                if p[i] > eps:
                    q_i = q[i] if q[i] > eps else eps
                    total -= p[i] * math.log(q_i)
            return total

    # ----------------------------------------------------------------
    # Cycle 309: Multi-resolution spectral divergence scan
    # ----------------------------------------------------------------
    def spectral_divergence_scan(
        self,
        other: "MemoryGraph",
        *,
        measure: str = "jsd",
        resolutions: list[int] | None = None,
        include_quarantined: bool = False,
    ) -> Optional[dict]:
        r"""Multi-resolution spectral divergence scan.

        Computes :meth:`spectral_divergence` at multiple histogram
        resolutions to reveal **at which frequency scales** two graphs
        differ most.

        **Why multi-resolution?**

        A single ``spectral_divergence()`` call at ``bins=20`` gives
        one number.  But different resolutions expose different
        structural contrasts:

        - **Few bins** (2-5) — coarse spectral *shape*: how much
          total spectral weight is in low vs high frequencies.
          Sensitive to global topology (community count, diameter).
        - **Medium bins** (8-21) — mesoscale structure: average
          degree, clustering coefficient.
        - **Many bins** (34-55) — fine spectral detail: individual
          eigenvalue positions, local motifs.

        A graph pair that differs only in local structure will show
        low divergence at coarse resolutions but high divergence at
        fine resolutions.  A pair that differs in community structure
        will show high divergence even at coarse resolutions.

        **Default resolutions:** ``[2, 3, 5, 8, 13, 21, 34, 55]`` —
        Fibonacci-like progression providing approximately logarithmic
        coverage from ultra-coarse to ultra-fine.

        **Returns a dict:**

        - ``resolutions``       — list of bin counts used
        - ``divergences``       — divergence value at each resolution
        - ``peak_resolution``   — bin count with max divergence
        - ``peak_divergence``   — max divergence value
        - ``min_resolution``    — bin count with min divergence
        - ``min_divergence``    — min divergence value
        - ``mean``              — average divergence across resolutions
        - ``std``               — standard deviation
        - ``cv``                — coefficient of variation (std/mean)
        - ``converged``         — ``True`` if last 3 values have
          CV < 0.05 (divergence stabilises at fine resolution)
        - ``monotonic``         — ``True`` if divergence is strictly
          increasing or decreasing with resolution
        - ``direction``         — ``"increasing"``, ``"decreasing"``,
          or ``"non-monotonic"``
        - ``measure``           — the measure used (jsd/kl/ce)

        Args:
            other:               Graph to compare against.
            measure:             "jsd", "kl", or "ce".
            resolutions:         List of bin counts (default
                                  ``[2, 3, 5, 8, 13, 21, 34, 55]``).
            include_quarantined: Include quarantined nodes.

        Returns:
            dict, or ``None`` if either graph has < 2 nodes or
            < 1 edge.
        """
        if resolutions is None:
            resolutions = [2, 3, 5, 8, 13, 21, 34, 55]

        # Validate resolutions
        if not resolutions or len(resolutions) < 2:
            raise ValueError(
                "resolutions must contain at least 2 values"
            )
        if any(b < 2 for b in resolutions):
            raise ValueError(
                "all resolutions must be >= 2"
            )

        # Compute divergence at each resolution
        divergences: list[float] = []
        for bins in resolutions:
            val = self.spectral_divergence(
                other,
                measure=measure,
                bins=bins,
                include_quarantined=include_quarantined,
            )
            if val is None:
                return None
            divergences.append(val)

        # Statistics
        n = len(divergences)
        mean_div = sum(divergences) / n
        variance = sum(
            (d - mean_div) ** 2 for d in divergences
        ) / n
        std_div = math.sqrt(variance)
        cv = std_div / mean_div if mean_div > 0 else 0.0

        # Peak / trough
        max_idx = max(range(n), key=lambda i: divergences[i])
        min_idx = min(range(n), key=lambda i: divergences[i])

        # Convergence: CV of last 3 values
        if n >= 3:
            last3 = divergences[-3:]
            m3 = sum(last3) / 3.0
            v3 = sum((d - m3) ** 2 for d in last3) / 3.0
            s3 = math.sqrt(v3)
            cv3 = s3 / m3 if m3 > 0 else 0.0
            converged = cv3 < 0.05
        else:
            converged = False

        # Monotonicity
        if n >= 2:
            diffs = [
                divergences[i + 1] - divergences[i]
                for i in range(n - 1)
            ]
            all_inc = all(d > 0 for d in diffs)
            all_dec = all(d < 0 for d in diffs)
            monotonic = all_inc or all_dec
            if all_inc:
                direction = "increasing"
            elif all_dec:
                direction = "decreasing"
            else:
                direction = "non-monotonic"
        else:
            monotonic = False
            direction = "insufficient"

        return {
            "resolutions":     list(resolutions),
            "divergences":     divergences,
            "peak_resolution": resolutions[max_idx],
            "peak_divergence": divergences[max_idx],
            "min_resolution":  resolutions[min_idx],
            "min_divergence":  divergences[min_idx],
            "mean":            mean_div,
            "std":             std_div,
            "cv":              cv,
            "converged":       converged,
            "monotonic":       monotonic,
            "direction":       direction,
            "measure":         measure,
        }

    # ------------------------------------------------------------------
    # Cycle 323: graph_health_score() — composite health metric
    # ------------------------------------------------------------------

    def graph_health_score(self, *, weights: dict[str, float] | None = None,
                           verbose: bool = False) -> dict:
        """Composite 0-100 health score for the memory graph.

        Combines six orthogonal signals into a single dashboard metric:

        ============  =====  ===================================================
        Component     Wt     What it measures
        ============  =====  ===================================================
        connectivity   25%  Inverse orphan fraction + component cohesion
        density        20%  Information density (edges per node, normalised)
        diversity      20%  Entropy profile spread (mean normalised entropy)
        spectral       15%  Von Neumann spectral entropy (global topology)
        redundancy     10%  Inverse redundancy ratio (less dup = healthier)
        stability      10%  Entropy stability under perturbation
        ============  =====  ===================================================

        **Design principles:**

        - Each component normalised to [0, 1] before weighting.
        - Missing components (e.g. empty graph → no spectral entropy)
          contribute 0 and their weight is redistributed.
        - **score** = round(sum(component × weight) × 100, 1).
        - **grade**: A (≥90), B (≥75), C (≥60), D (≥40), F (<40).

        Args:
            weights: Override default weights.  Keys: ``connectivity``,
                ``density``, ``diversity``, ``spectral``, ``redundancy``,
                ``stability``.  Values need not sum to 1 (auto-normalised).
            verbose: If True, include raw values in the output.

        Returns:
            Dict with:
            - ``score``: 0-100 float
            - ``grade``: A/B/C/D/F
            - ``status``: excellent/good/fair/poor/critical
            - ``components``: {name: {score, weight, raw}}
            - ``weakest``: name of lowest-scoring component
            - ``recommendations``: list[str] of actionable advice
        """
        default_weights = {
            "connectivity": 0.25,
            "density":      0.20,
            "diversity":    0.20,
            "spectral":     0.15,
            "redundancy":   0.10,
            "stability":    0.10,
        }
        w = dict(default_weights)
        if weights:
            for k, v in weights.items():
                if k in w:
                    w[k] = v
        # Normalise weights
        wsum = sum(w.values())
        if wsum <= 0:
            w = dict(default_weights)
            wsum = sum(w.values())
        w = {k: v / wsum for k, v in w.items()}

        stats = self.stats()
        n_nodes = stats.get("nodes", 0)
        n_edges = stats.get("edges", 0)

        # ── Component 1: Connectivity (from gap_score) ────────────
        conn_score = 0.0
        conn_raw = None
        if n_nodes > 0:
            gap = self.knowledge_gap_report()
            conn_raw = gap.get("gap_score", 50.0)
            conn_score = max(0.0, min(1.0, conn_raw / 100.0))

        # ── Component 2: Density ──────────────────────────────────
        dens_score = 0.0
        dens_raw = None
        if n_nodes > 1:
            max_edges = n_nodes * (n_nodes - 1)
            dens_raw = (2.0 * n_edges) / max_edges if max_edges > 0 else 0.0
            # Log-scale normalisation: raw density of 0.1 → ~0.5, 0.3 → ~0.8
            import math
            dens_score = min(1.0, math.log1p(dens_raw * 10) / math.log1p(10))

        # ── Component 3: Diversity (entropy profile mean) ─────────
        div_score = 0.0
        div_raw = None
        if n_edges > 0:
            prof = self.entropy_profile()
            if prof is not None:
                div_raw = prof.get("mean", 0.0)
                div_score = max(0.0, min(1.0, div_raw))

        # ── Component 4: Spectral (von Neumann normalised) ────────
        spec_score = 0.0
        spec_raw = None
        if n_edges > 0:
            spec_raw = self.von_neumann_entropy(normalized=True)
            if spec_raw is not None:
                spec_score = max(0.0, min(1.0, spec_raw))

        # ── Component 5: Redundancy (inverse of redundancy_score) ──
        red_score = 1.0  # default: no redundancy = full health
        red_raw = None
        if n_nodes > 1:
            red = self.redundancy_detect()
            if isinstance(red, dict):
                red_raw = red.get("redundancy_score", 0)
                # redundancy_score: 0=no redundancy, 100=highly redundant
                # Invert: health = 1 - redundancy/100
                red_score = max(0.0, 1.0 - red_raw / 100.0)

        # ── Component 6: Stability ────────────────────────────────
        stab_score = 0.0
        stab_raw = None
        if n_edges >= 2:
            try:
                stab = self.entropy_stability(
                    trials=20, mode="rewire", index="sombor")
                if stab is not None:
                    stab_raw = stab.get("stability_score")
                    if stab_raw is not None:
                        stab_score = max(0.0, min(1.0, stab_raw))
            except Exception:
                pass  # stability may fail on tiny graphs

        # ── Aggregate ─────────────────────────────────────────────
        components = {
            "connectivity": {"score": conn_score, "weight": w["connectivity"], "raw": conn_raw},
            "density":      {"score": dens_score, "weight": w["density"],      "raw": dens_raw},
            "diversity":    {"score": div_score, "weight": w["diversity"],    "raw": div_raw},
            "spectral":     {"score": spec_score, "weight": w["spectral"],     "raw": spec_raw},
            "redundancy":   {"score": red_score, "weight": w["redundancy"],   "raw": red_raw},
            "stability":    {"score": stab_score, "weight": w["stability"],    "raw": stab_raw},
        }

        score = sum(c["score"] * c["weight"] for c in components.values()) * 100
        score = round(score, 1)

        # Grade
        if score >= 90:
            grade, status = "A", "excellent"
        elif score >= 75:
            grade, status = "B", "good"
        elif score >= 60:
            grade, status = "C", "fair"
        elif score >= 40:
            grade, status = "D", "poor"
        else:
            grade, status = "F", "critical"

        # Weakest component
        weakest = min(components, key=lambda k: components[k]["score"])

        # Recommendations
        recs: list[str] = []
        if conn_score < 0.5:
            recs.append(
                f"Connectivity is low ({conn_score:.0%}). "
                "Add edges between isolated clusters — see knowledge_gap_report()."
            )
        if dens_score < 0.3 and n_nodes > 5:
            recs.append(
                f"Edge density is low ({dens_score:.0%}). "
                "Consider adding relational edges between loosely connected memories."
            )
        if div_score < 0.3:
            recs.append(
                "Entropy diversity is low. "
                "Graph structure is too uniform — add varied relationship types."
            )
        if spec_score < 0.3 and n_edges > 0:
            recs.append(
                "Spectral entropy is low. "
                "Graph may be fragmented — consolidate disconnected components."
            )
        if red_score < 0.7:
            recs.append(
                f"Redundancy detected ({red_raw} redundant edges). "
                "Run auto_consolidate() to merge duplicate connections."
            )
        if stab_score < 0.5 and n_edges >= 2:
            recs.append(
                "Entropy stability is low. "
                "Graph structure is fragile under perturbation — strengthen hub connections."
            )
        if not recs:
            recs.append("All components within healthy range. ✅")

        result: dict = {
            "score":         score,
            "grade":         grade,
            "status":        status,
            "components":    components,
            "weakest":       weakest,
            "recommendations": recs,
        }
        if verbose:
            result["node_count"] = n_nodes
            result["edge_count"] = n_edges

        return result

    # ------------------------------------------------------------------
    # Cycle 325: entropy_dashboard() — unified entropy overview
    # ------------------------------------------------------------------

    def entropy_dashboard(self, *, top_n: int = 5) -> Optional[dict]:
        """One-call comprehensive entropy overview.

        Aggregates all entropy-related signals into a single structured
        dashboard — the ``stats()`` equivalent for the entropy toolkit.

        **Sections:**

        - **degree_entropy**: entropy_profile summary (15 indices)
        - **spectral_entropy**: von Neumann + spectral profile highlights
        - **fingerprint**: compact 12+ dim feature vector
        - **health**: graph_health_score() summary
        - **top_contributors**: top-N nodes by entropy contribution
        - **density**: graph_information_density() summary
        - **stats**: basic graph statistics

        Each section is a compact dict with key metrics only.
        Use the individual APIs for full detail.

        Args:
            top_n: Number of top contributor nodes to list.

        Returns:
            Dict with the sections above, or None if graph is empty.
        """
        stats = self.stats()
        n_nodes = stats.get("nodes", 0)
        n_edges = stats.get("edges", 0)
        if n_nodes == 0:
            return None

        dashboard: dict = {
            "stats": {"nodes": n_nodes, "edges": n_edges, **stats},
        }

        # ── Degree entropy ─────────────────────────────────────────
        if n_edges > 0:
            prof = self.entropy_profile()
            if prof is not None:
                dashboard["degree_entropy"] = {
                    "mean":       prof.get("mean"),
                    "std":        prof.get("std"),
                    "range":      prof.get("range"),
                    "most_heterogeneous": prof.get("most_heterogeneous"),
                    "most_homogeneous":   prof.get("most_homogeneous"),
                    "indices":    len(prof.get("values", {})),
                }
        else:
            dashboard["degree_entropy"] = None

        # ── Spectral entropy ───────────────────────────────────────
        if n_edges > 0:
            vn = self.von_neumann_entropy(normalized=True)
            try:
                spec_prof = self.spectral_entropy_profile()
            except Exception:
                spec_prof = None
            dashboard["spectral_entropy"] = {
                "von_neumann_normalized": vn,
                "profile_available":     spec_prof is not None,
            }
            if spec_prof is not None:
                dashboard["spectral_entropy"]["von_neumann_raw"] = (
                    spec_prof.get("von_neumann", {}).get("value")
                )
        else:
            dashboard["spectral_entropy"] = None

        # ── Fingerprint ────────────────────────────────────────────
        if n_edges > 0:
            try:
                fp = self.entropy_fingerprint()
                if fp is not None:
                    vec = fp.get("vector", [])
                    dashboard["fingerprint"] = {
                        "vector":      vec,
                        "dimensions":  len(vec),
                        "indices":     fp.get("indices", []),
                    }
                else:
                    dashboard["fingerprint"] = None
            except Exception:
                dashboard["fingerprint"] = None
        else:
            dashboard["fingerprint"] = None

        # ── Health ─────────────────────────────────────────────────
        try:
            health = self.graph_health_score()
            dashboard["health"] = {
                "score":    health["score"],
                "grade":    health["grade"],
                "status":   health["status"],
                "weakest":  health["weakest"],
            }
        except Exception:
            dashboard["health"] = None

        # ── Top contributors ───────────────────────────────────────
        if n_edges > 0:
            try:
                contrib = self.entropy_contribution()
                if contrib is not None and isinstance(contrib, dict):
                    ranked = contrib.get("ranked", [])
                    if isinstance(ranked, list):
                        dashboard["top_contributors"] = ranked[:top_n]
                    else:
                        dashboard["top_contributors"] = []
                else:
                    dashboard["top_contributors"] = []
            except Exception:
                dashboard["top_contributors"] = []
        else:
            dashboard["top_contributors"] = []

        # ── Density ───────────────────────────────────────────────
        if n_edges > 0:
            try:
                dens = self.graph_information_density()
                if dens is not None and isinstance(dens, dict):
                    dashboard["density"] = {
                        k: v for k, v in dens.items()
                        if isinstance(v, (int, float, str, bool))
                    }
                else:
                    dashboard["density"] = None
            except Exception:
                dashboard["density"] = None
        else:
            dashboard["density"] = None

        return dashboard

    # ------------------------------------------------------------------
    # Cycle 331: conditioned_traverse() — query-conditioned BFS (Research #040)
    # ------------------------------------------------------------------

    DEFAULT_RELATION_WEIGHTS = {
        "causes": 1.0,
        "depends_on": 0.9,
        "enables": 0.8,
        "relates_to": 0.5,
        "similar_to": 0.4,
        "derived_from": 0.7,
        "part_of": 0.6,
        "instance_of": 0.6,
        "temporal_before": 0.3,
        "contradicts": 0.1,
    }

    def conditioned_traverse(self, entry_id: str,
                              intent_profile: dict = None,
                              max_depth: int = 5,
                              min_weight: float = 0.0,
                              top_k: int = 20) -> dict:
        """Query-conditioned BFS with per-relation traversal weights.

        Inspired by HAGE (2605.09942): different query intents should
        traverse different edge types. A causal query follows ``causes``
        and ``depends_on`` edges; a similarity query follows ``similar_to``
        and ``relates_to`` edges.

        Each edge type has a traversal weight (0–1). At each BFS step,
        edges with ``traversal_weight < min_weight`` are pruned. The
        accumulated node score decays with depth and is multiplied by
        the edge traversal weight, so nodes reached via high-weight
        edges rank higher.

        Args:
            entry_id: Starting node ID.
            intent_profile: Override or extend default relation weights.
                Keys are relation names, values are floats in [0, 1].
                Pass ``{"causes": 1.0, "depends_on": 1.0}`` to traverse
                only causal/dependency edges.
            max_depth: Maximum BFS depth.
            min_weight: Prune edges with traversal weight below this.
            top_k: Return at most this many nodes (sorted by score).

        Returns:
            Dict with ``entry``, ``visited`` (list of {node_id, depth,
            score, path}), ``edge_types_used`` (set of relations
            traversed), and ``stats`` (nodes_visited, edges_traversed,
            max_depth_reached).
        """
        if not self.has_node(entry_id):
            return {"entry": entry_id, "visited": [], "edge_types_used": set(),
                    "stats": {"nodes_visited": 0, "edges_traversed": 0,
                              "max_depth_reached": 0}}

        # Merge default weights with user overrides
        weights = dict(self.DEFAULT_RELATION_WEIGHTS)
        if intent_profile:
            weights.update(intent_profile)

        visited = {}  # node_id → (depth, score, path)
        visited[entry_id] = (0, 1.0, [entry_id])
        edge_types_used = set()
        edges_traversed = 0
        queue = [(entry_id, 0, 1.0, [entry_id])]

        while queue:
            current_id, depth, score, path = queue.pop(0)
            if depth >= max_depth:
                continue

            # Get outgoing edges
            rows = self.conn.execute(
                "SELECT target, relation, weight FROM edges WHERE source=?",
                (current_id,)
            ).fetchall()

            for r in rows:
                relation = r["relation"]
                target = r["target"]
                edge_w = weights.get(relation, 0.3)  # unknown relations get low weight

                if edge_w < min_weight:
                    continue

                edges_traversed += 1
                edge_types_used.add(relation)

                # Score decays with depth, boosted by edge weight
                new_score = score * edge_w * 0.85  # depth decay
                new_path = path + [target]

                if target not in visited or new_score > visited[target][1]:
                    visited[target] = (depth + 1, new_score, new_path)
                    queue.append((target, depth + 1, new_score, new_path))

        # Build result sorted by score
        result_nodes = []
        for nid, (dep, sc, pth) in visited.items():
            if nid == entry_id:
                continue
            result_nodes.append({
                "node_id": nid,
                "depth": dep,
                "score": round(sc, 4),
                "path": pth,
            })
        result_nodes.sort(key=lambda x: x["score"], reverse=True)
        result_nodes = result_nodes[:top_k]

        max_depth_reached = max((v[0] for v in visited.values()), default=0)

        return {
            "entry": entry_id,
            "visited": result_nodes,
            "edge_types_used": sorted(edge_types_used),
            "stats": {
                "nodes_visited": len(visited),
                "edges_traversed": edges_traversed,
                "max_depth_reached": max_depth_reached,
            },
        }

    # ------------------------------------------------------------------
    # Cycle 332: project_graph() — relation-specific subgraph projection
    # ------------------------------------------------------------------

    def project_graph(self, relation_type: str,
                      include_metadata: bool = True) -> 'MemoryGraph':
        """Project graph onto a single relation type, returning a new MemoryGraph.

        Inspired by HAGE (2605.09942): relation-specific views enable
        multi-perspective retrieval. A temporal query projects to
        temporal edges; a causal query projects to causal edges.

        Unlike ``subgraph_by_edge_type()`` (which returns a dict), this
        returns a proper ``MemoryGraph`` instance that supports all
        graph algorithms (entropy, centrality, classification, etc.).

        The projected graph contains:
        - All nodes that participate in at least one edge of the given
          relation type (or all nodes if the relation doesn't exist).
        - Only edges of the specified relation type.

        Args:
            relation_type: Edge relation to project onto.
            include_metadata: If True, copy node data/kind/tags.

        Returns:
            New MemoryGraph instance with filtered edges.
        """
        projected = MemoryGraph()

        # Find all edges of this relation type
        edge_rows = self.conn.execute(
            "SELECT source, target, relation, weight FROM edges WHERE relation=?",
            (relation_type,)
        ).fetchall()

        if not edge_rows:
            return projected  # empty graph

        # Collect node IDs that participate in these edges
        node_ids = set()
        for r in edge_rows:
            node_ids.add(r["source"])
            node_ids.add(r["target"])

        # Copy nodes
        placeholders = ",".join("?" for _ in node_ids)
        node_rows = self.conn.execute(
            f"SELECT * FROM nodes WHERE id IN ({placeholders})",
            list(node_ids)
        ).fetchall()

        id_map = {}  # original_id → new_id (in case add() generates different IDs)
        for r in node_rows:
            data = json.loads(r["data"]) if r["data"] else {}
            if not include_metadata:
                data = {}
            node = projected.add(
                label=r["label"],
                kind=r["kind"] if include_metadata else "fact",
                data=data,
                category=data.get("category") if include_metadata else None,
            )
            id_map[r["id"]] = node.id
            # Preserve weight
            if include_metadata and r["weight"] != 1.0:
                projected.conn.execute(
                    "UPDATE nodes SET weight=? WHERE id=?",
                    (r["weight"], node.id)
                )

        # Copy edges
        for r in edge_rows:
            src = id_map.get(r["source"])
            tgt = id_map.get(r["target"])
            if src and tgt:
                projected.link(src, tgt, r["relation"], r["weight"])

        projected.conn.commit()
        return projected

    # ------------------------------------------------------------------
    # Cycle 333: multi_perspective_analysis() — comparative relation views
    # ------------------------------------------------------------------

    def multi_perspective_analysis(self, node_id: str = None,
                                    max_depth: int = 3) -> dict:
        """Multi-perspective graph analysis via per-relation projections.

        Inspired by HAGE (2605.09942): different edge types reveal different
        structural dimensions. This API analyzes each relation type
        independently and returns a comparative report.

        For each relation type found in the graph:
        - Computes node_count, edge_count, density, avg_degree.
        - If ``node_id`` is provided, runs ``conditioned_traverse`` from
          that node using the relation as the dominant intent.

        Args:
            node_id: Optional focal node for per-relation traversal scores.
            max_depth: Traversal depth per perspective.

        Returns:
            Dict with ``perspectives``, ``relation_ranking``,
            ``dominant_relation``, and ``cross_perspective_nodes``.
        """
        rel_rows = self.conn.execute(
            "SELECT DISTINCT relation FROM edges"
        ).fetchall()
        relations = [r["relation"] for r in rel_rows]

        if not relations:
            return {
                "perspectives": {},
                "relation_ranking": [],
                "dominant_relation": None,
                "cross_perspective_nodes": [],
                "total_relations": 0,
            }

        perspectives = {}
        node_in_views = {}  # original node_id → set of relations

        for rel in relations:
            # Count edges of this relation
            edge_count = self.conn.execute(
                "SELECT COUNT(*) as c FROM edges WHERE relation=?",
                (rel,)
            ).fetchone()["c"]

            # Find nodes participating in this relation
            node_rows = self.conn.execute(
                "SELECT DISTINCT source AS id FROM edges WHERE relation=? "
                "UNION SELECT DISTINCT target FROM edges WHERE relation=?",
                (rel, rel)
            ).fetchall()
            node_ids = {r["id"] for r in node_rows}
            n_nodes = len(node_ids)
            density = (2 * edge_count / (n_nodes * (n_nodes - 1))) if n_nodes > 1 else 0.0
            avg_degree = (2 * edge_count / n_nodes) if n_nodes > 0 else 0.0

            view = {
                "relation": rel,
                "node_count": n_nodes,
                "edge_count": edge_count,
                "density": round(density, 4),
                "avg_degree": round(avg_degree, 2),
            }

            for nid in node_ids:
                if nid not in node_in_views:
                    node_in_views[nid] = set()
                node_in_views[nid].add(rel)

            if node_id and node_id in node_ids:
                trav = self.conditioned_traverse(
                    node_id,
                    intent_profile={rel: 1.0},
                    max_depth=max_depth,
                    min_weight=0.5,
                    top_k=10,
                )
                view["traversal"] = {
                    "reachable": trav["stats"]["nodes_visited"],
                    "max_depth_reached": trav["stats"]["max_depth_reached"],
                    "top_nodes": [
                        {"id": v["node_id"], "score": v["score"]}
                        for v in trav["visited"][:5]
                    ],
                }

            perspectives[rel] = view

        ranking = sorted(relations, key=lambda r: perspectives[r]["edge_count"], reverse=True)

        cross_nodes = [
            {"node_id": nid, "perspectives": sorted(rels),
             "perspective_count": len(rels)}
            for nid, rels in node_in_views.items()
            if len(rels) > 1
        ]
        cross_nodes.sort(key=lambda x: x["perspective_count"], reverse=True)

        return {
            "perspectives": perspectives,
            "relation_ranking": ranking,
            "dominant_relation": ranking[0] if ranking else None,
            "cross_perspective_nodes": cross_nodes[:20],
            "total_relations": len(relations),
        }

    # ------------------------------------------------------------------
    # Cycle 334: classification_benchmark() — standardized evaluation
    # ------------------------------------------------------------------

    @staticmethod
    def _bench_build_topology(topology: str, n: int, label: str = "") -> "MemoryGraph":
        """Build a canonical graph of the given topology type."""
        mg = MemoryGraph()
        nodes = [mg.add(f"{topology}_{label}_{i}", "bench", {"topology": topology}) for i in range(n)]
        if topology == "star":
            for i in range(1, n):
                mg.link(nodes[0].id, nodes[i].id, "rel", 1.0)
        elif topology == "path":
            for i in range(n - 1):
                mg.link(nodes[i].id, nodes[i + 1].id, "rel", 1.0)
        elif topology == "cycle":
            for i in range(n):
                mg.link(nodes[i].id, nodes[(i + 1) % n].id, "rel", 1.0)
        elif topology == "complete":
            for i in range(n):
                for j in range(i + 1, n):
                    mg.link(nodes[i].id, nodes[j].id, "rel", 1.0)
        elif topology == "bipartite":
            half = n // 2
            left, right = nodes[:half], nodes[half:]
            for a in left:
                for b in right:
                    mg.link(a.id, b.id, "rel", 1.0)
        elif topology == "tree":
            for i in range(1, n):
                parent = (i - 1) // 2
                mg.link(nodes[parent].id, nodes[i].id, "rel", 1.0)
        else:
            raise ValueError(f"Unknown topology: {topology}")
        mg.graph_meta = {"topology": topology, "label": label or topology, "n": n}
        return mg

    # ── Cycle 335: Max-confidence meta-classification ──

    def max_confidence_classification(
        self,
        references: list["MemoryGraph"],
        *,
        degree_index: str = "sombor",
        include_quarantined: bool = False,
        confidence_metric: str = "margin",
        min_methods: int = 2,
    ) -> Optional[dict]:
        """Select the classification result from whichever method
        has the **highest confidence** for this specific query.

        Unlike ``classification_compare()`` (majority voting across
        methods), this meta-classifier trusts the method that is most
        *confident* for the current query.  Different query/reference
        combinations favour different modalities — a star graph might
        be easiest to classify by degree entropy, while a cycle is
        easier by spectral analysis.

        **Methods executed:**

        1. ``graph_classification`` — degree-based entropy distance
        2. ``spectral_classification`` — spectral divergence
        3. ``hybrid_classification`` — fixed-weight ensemble
        4. ``rrf_classification`` — Reciprocal Rank Fusion
        5. ``bayesian_classification`` — adaptive-weight ensemble

        **Confidence metrics:**

        - ``"margin"`` (default): absolute gap ``2nd_best − best``.
          Robust across methods since all produce distance scores.
        - ``"confidence"``: relative separation ``(2nd-best − best)/best``.
          Can be ``inf`` when best score ≈ 0.
        - ``"z_score"``: ``(best − mean_others) / std_others``.
          Measures how many standard deviations the best score is
          below the rest.  Naturally normalised across methods with
          different scales.

        **When to use this vs ``classification_compare()``?

        - ``classification_compare``: you want *consensus* — the
          answer trusted by the majority of methods.
        - ``max_confidence_classification``: you want *conviction* —
          the answer from the method most sure of itself for this
          query, even if it's a minority of one.

        Practical guidance: use ``classification_compare`` when methods
        tend to agree (high-signal regime).  Use
        ``max_confidence_classification`` when methods disagree but one
        has a clear, dominant separation (low-signal regime where one
        modality captures structure the others miss).

        Args:
            references:          list of reference MemoryGraphs.
            degree_index:        degree index for entropy distance.
            include_quarantined: include quarantined nodes.
            confidence_metric:   how to rank method confidence
                                 ("margin", "confidence", "z_score").
            min_methods:         minimum methods that must succeed
                                 (default 2). If fewer succeed, returns
                                 the single best available.

        Returns:
            Dict with:
            - ``best_match``: int — index of closest reference
            - ``best_score``: float — score from winning method
            - ``winning_method``: str — name of most-confident method
            - ``winning_confidence``: float — confidence value that won
            - ``confidence_metric``: str — metric used for selection
            - ``per_method``: dict → {method: {best_match, best_score,
              margin, confidence, z_score}}
            - ``methods_run``: list of method names executed
            - "methods_failed": list of method names that errored
            - "agreement": float — fraction of methods agreeing with
              the winner (0 to 1)
            - "margin_of_victory": float — confidence gap between
              best and 2nd-best method
            - "recommendation": str — human-readable summary
            or ``None`` if no methods succeeded.
        """
        if not references:
            return None

        if confidence_metric not in ("margin", "confidence", "z_score"):
            raise ValueError(
                f"confidence_metric must be 'margin', 'confidence', "
                f"or 'z_score', got '{confidence_metric}'")

        method_names = [
            "graph_classification",
            "spectral_classification",
            "hybrid_classification",
            "rrf_classification",
            "bayesian_classification",
        ]

        # ── Run each method and collect results ────────────────────
        per_method: dict[str, dict] = {}
        methods_run: list[str] = []
        methods_failed: list[str] = []

        for name in method_names:
            try:
                if name == "graph_classification":
                    result = self.graph_classification(
                        references, degree_index=degree_index)
                elif name == "spectral_classification":
                    result = self.spectral_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                elif name == "hybrid_classification":
                    result = self.hybrid_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                elif name == "rrf_classification":
                    result = self.rrf_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                elif name == "bayesian_classification":
                    result = self.bayesian_classification(
                        references, degree_index=degree_index,
                        include_quarantined=include_quarantined)
                else:
                    continue

                if result is not None:
                    entry = {
                        "best_match":  result.get("best_match"),
                        "best_score":  result.get("best_score"),
                        "margin":      result.get("margin"),
                        "confidence":  result.get("confidence"),
                    }

                    # ── Compute z_score from rankings if available ──
                    rankings = result.get("rankings", [])
                    if rankings and len(rankings) >= 2:
                        scores = [
                            r.get("score", r.get("rrf_score", 0.0))
                            for r in rankings
                        ]
                        if len(scores) >= 2:
                            best_s = min(scores)
                            rest = [s for s in scores if s != best_s]
                            if rest:
                                mean_rest = sum(rest) / len(rest)
                                var_rest = sum(
                                    (s - mean_rest) ** 2 for s in rest
                                ) / len(rest)
                                std_rest = math.sqrt(var_rest)
                                z = ((best_s - mean_rest) / std_rest
                                     if std_rest > 1e-12 else 0.0)
                                entry["z_score"] = round(z, 8)
                            else:
                                entry["z_score"] = 0.0
                        else:
                            entry["z_score"] = 0.0
                    else:
                        entry["z_score"] = 0.0

                    per_method[name] = entry
                    methods_run.append(name)
                else:
                    methods_failed.append(name)
            except Exception:
                methods_failed.append(name)

        if not methods_run:
            return None

        # ── If only 1 method succeeded, return its result directly ─
        if len(methods_run) < min_methods:
            name = methods_run[0]
            info = per_method[name]
            return {
                "best_match":          info["best_match"],
                "best_score":          info["best_score"],
                "winning_method":      name,
                "winning_confidence": info.get(confidence_metric, 0.0),
                "confidence_metric":   confidence_metric,
                "per_method":          per_method,
                "methods_run":         methods_run,
                "methods_failed":      methods_failed,
                "agreement":           1.0,
                "margin_of_victory":   0.0,
                "recommendation":      (
                    f"Only {len(methods_run)} method succeeded; "
                    f"using {name}."
                ),
            }

        # ── Rank methods by chosen confidence metric ──────────────
        def _conf_val(info: dict) -> float:
            v = info.get(confidence_metric, 0.0)
            if v is None:
                return 0.0
            # For 'confidence', inf means best≈0 with positive margin —
            # treat as very high confidence
            if v == float("inf"):
                return 1e18
            return float(v)

        # For margin and confidence: higher = more confident → max wins
        # For z_score: lower (more negative) = more confident → min wins
        if confidence_metric == "z_score":
            ranked = sorted(
                methods_run,
                key=lambda m: _conf_val(per_method[m]),
            )
        else:
            ranked = sorted(
                methods_run,
                key=lambda m: _conf_val(per_method[m]),
                reverse=True,
            )

        winner = ranked[0]
        runner_up = ranked[1] if len(ranked) > 1 else None
        winner_conf = _conf_val(per_method[winner])
        runner_conf = (_conf_val(per_method[runner_up])
                        if runner_up else 0.0)
        victory_margin = round(winner_conf - runner_conf, 8)

        # ── Agreement: how many methods picked the same best_match ─
        winner_best = per_method[winner]["best_match"]
        agree_count = sum(
            1 for m in methods_run
            if per_method[m]["best_match"] == winner_best
        )
        agreement = round(agree_count / len(methods_run), 4)

        # ── Recommendation text ────────────────────────────────────
        if agreement == 1.0:
            rec = (f"{winner} is most confident "
                   f"({confidence_metric}={winner_conf:.6g}) and all "
                   f"{len(methods_run)} methods agree on #{winner_best}.")
        elif agree_count > 1:
            rec = (f"{winner} has highest {confidence_metric} "
                   f"({winner_conf:.6g}), and {agree_count}/"
                   f"{len(methods_run)} methods agree on #{winner_best}.")
        else:
            rec = (f"{winner} is most confident "
                   f"({confidence_metric}={winner_conf:.6g}) but "
                   f"disagrees with other methods. "
                   f"Only this method chose #{winner_best}.")

        return {
            "best_match":          winner_best,
            "best_score":          per_method[winner]["best_score"],
            "winning_method":      winner,
            "winning_confidence": round(winner_conf, 8),
            "confidence_metric":   confidence_metric,
            "per_method":          per_method,
            "methods_run":         methods_run,
            "methods_failed":      methods_failed,
            "agreement":           agreement,
            "margin_of_victory":  victory_margin,
            "recommendation":      rec,
        }

    def classification_benchmark(
        self,
        *,
        topologies: list[str] = None,
        sizes: list[int] = None,
        num_references_per_category: int = 2,
        num_queries: int = 1,
        methods: list[str] = None,
        include_quarantined: bool = False,
    ) -> dict:
        """Standardized classification benchmark suite.

        Generates canonical graph topologies (star, path, cycle,
        complete, bipartite, tree) as reference and query graphs, then
        runs all available classification methods and reports
        per-method accuracy, precision, recall, and F1.

        This is the capstone evaluation tool for the classification
        suite — it answers "which method works best for which topology?"

        Args:
            topologies: Graph types to test. Default: all 6.
            sizes: Node counts to generate. Default: [8, 12].
            num_references_per_category: Reference graphs per topology
                type. More = harder classification.
            num_queries: Query graphs per topology type.
            methods: Classification methods to evaluate. Default: all 9.
            include_quarantined: Whether to include quarantined refs.

        Returns:
            Dict with per-method results, confusion data, best method
            per topology, and overall rankings.
        """
        if topologies is None:
            topologies = ["star", "path", "cycle", "complete", "bipartite", "tree"]
        if sizes is None:
            sizes = [8, 12]
        if methods is None:
            methods = [
                "graph", "spectral", "hybrid", "rrf", "bayesian",
                "knn", "weighted_average", "compare",
            ]

        # --- Build reference set ---
        references = []
        category_labels = []  # parallel list: expected topology per ref
        for topo in topologies:
            for sz in sizes:
                for r in range(num_references_per_category):
                    ref = self._bench_build_topology(topo, sz, label=f"r{r}")
                    ref.graph_meta = {"topology": topo, "label": topo, "n": sz}
                    references.append(ref)
                    category_labels.append(topo)

        # --- Build queries ---
        queries = []
        expected = []
        for topo in topologies:
            for sz in sizes:
                for q in range(num_queries):
                    qi = self._bench_build_topology(topo, sz, label=f"q{q}")
                    queries.append(qi)
                    expected.append(topo)

        if not queries or not references:
            return {
                "methods_evaluated": methods or [],
                "topologies_tested": topologies,
                "sizes": sizes,
                "num_references": len(references),
                "num_queries": len(queries),
                "method_results": {},
                "overall_best": None,
                "overall_best_accuracy": 0.0,
                "best_per_topology": {},
                "confusion": {},
            }

        # --- Dispatch classification ---
        method_results = {}

        for method in methods:
            predictions = []
            confidences = []
            for query in queries:
                try:
                    if method == "graph":
                        r = query.graph_classification(references, include_quarantined=include_quarantined)
                    elif method == "spectral":
                        r = query.spectral_classification(references, include_quarantined=include_quarantined)
                    elif method == "hybrid":
                        r = query.hybrid_classification(references, include_quarantined=include_quarantined)
                    elif method == "rrf":
                        r = query.rrf_classification(references, include_quarantined=include_quarantined)
                    elif method == "bayesian":
                        r = query.bayesian_classification(references, include_quarantined=include_quarantined)
                    elif method == "knn":
                        r = query.knn_classification(references, include_quarantined=include_quarantined)
                    elif method == "weighted_average":
                        r = query.weighted_average_classification(references, include_quarantined=include_quarantined)
                    elif method == "compare":
                        r = query.classification_compare(references, include_quarantined=include_quarantined)
                    else:
                        predictions.append(None)
                        confidences.append(0.0)
                        continue

                    if r is None:
                        predictions.append(None)
                        confidences.append(0.0)
                    else:
                        idx = r.get("best_ref_index", r.get("consensus_best", {}).get("index", 0))
                        if isinstance(idx, dict):
                            idx = idx.get("index", 0)
                        if isinstance(idx, str):
                            # Try to extract numeric index
                            try:
                                idx = int(idx)
                            except (ValueError, TypeError):
                                idx = 0
                        idx = min(idx, len(category_labels) - 1)
                        predictions.append(category_labels[idx])
                        confidences.append(r.get("confidence", r.get("agreement_score", 0.0)))
                except Exception:
                    predictions.append(None)
                    confidences.append(0.0)

            # --- Score ---
            correct = sum(1 for pred, exp in zip(predictions, expected) if pred == exp)
            total = len(expected)
            accuracy = correct / total if total > 0 else 0.0

            # Per-topology accuracy
            per_topo = {}
            for topo in topologies:
                topo_mask = [e == topo for e in expected]
                topo_correct = sum(1 for p, e, m in zip(predictions, expected, topo_mask) if m and p == e)
                topo_total = sum(topo_mask)
                per_topo[topo] = {
                    "correct": topo_correct,
                    "total": topo_total,
                    "accuracy": round(topo_correct / topo_total, 4) if topo_total > 0 else 0.0,
                }

            # Precision / Recall / F1 (macro-averaged)
            tp = fp = fn = 0
            for topo in topologies:
                for pred, exp in zip(predictions, expected):
                    if pred == topo and exp == topo:
                        tp += 1
                    elif pred == topo and exp != topo:
                        fp += 1
                    elif pred != topo and exp == topo:
                        fn += 1
            precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
            recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
            f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0

            avg_conf = sum(confidences) / len(confidences) if confidences else 0.0

            method_results[method] = {
                "accuracy": round(accuracy, 4),
                "correct": correct,
                "total": total,
                "precision": round(precision, 4),
                "recall": round(recall, 4),
                "f1": round(f1, 4),
                "avg_confidence": round(avg_conf, 4),
                "per_topology": per_topo,
                "predictions": predictions,
            }

        # --- Rank methods ---
        ranked = sorted(method_results.items(), key=lambda x: x[1]["accuracy"], reverse=True)

        # --- Best method per topology ---
        best_per_topo = {}
        for topo in topologies:
            scored = [(m, method_results[m]["per_topology"][topo]["accuracy"]) for m in methods]
            best_method, best_acc = max(scored, key=lambda x: x[1]) if scored else (None, 0.0)
            best_per_topo[topo] = {
                "best_method": best_method,
                "accuracy": best_acc,
            }

        # --- Confusion summary (which topologies get confused) ---
        confusion = {}
        best_method = ranked[0][0] if ranked else None
        if best_method:
            preds = method_results[best_method]["predictions"]
            for exp_topo in topologies:
                for pred_topo in topologies:
                    if exp_topo == pred_topo:
                        continue
                    count = sum(1 for p, e in zip(preds, expected) if e == exp_topo and p == pred_topo)
                    if count > 0:
                        key = f"{exp_topo}→{pred_topo}"
                        confusion[key] = count

        return {
            "methods_evaluated": methods,
            "topologies_tested": topologies,
            "sizes": sizes,
            "num_references": len(references),
            "num_queries": len(queries),
            "method_results": dict(ranked),
            "overall_best": ranked[0][0] if ranked else None,
            "overall_best_accuracy": ranked[0][1]["accuracy"] if ranked else 0.0,
            "best_per_topology": best_per_topo,
            "confusion": dict(sorted(confusion.items(), key=lambda x: x[1], reverse=True)),
        }


def demo():
    print("🧪 Agent Memory Graph Demo\n")
    mg = MemoryGraph()

    # 添加记忆
    user = mg.add("罗嵩", "person", {"timezone": "Asia/Shanghai"})
    catalyst = mg.add("Catalyst - 数字精灵", "person", {"vibe": "sharp & fast"})
    project = mg.add("OpenClaw Agent", "concept", {"lang": "TypeScript"})
    python_skill = mg.add("Python 快速原型", "skill")
    rust_interest = mg.add("Rust 嵌入式AI", "concept")

    # 建立关系
    mg.link(user.id, catalyst.id, "created")
    mg.link(user.id, project.id, "works_on")
    mg.link(catalyst.id, project.id, "assists_with")
    mg.link(user.id, python_skill.id, "skilled_in")
    mg.link(user.id, rust_interest.id, "interested_in")
    mg.link(rust_interest.id, project.id, "relevant_to")

    # 添加一些事件
    e1 = mg.add("深夜debug session", "event", {"hours": 3})
    mg.link(e1.id, project.id, "about")
    mg.link(user.id, e1.id, "experienced")

    print(mg.visualize_ascii())
    print()

    # 召回
    print("🔍 Recalling 'Python':")
    for r in mg.recall("Python"):
        print(f"  ✓ {r.label} (weight={r.weight:.2f})")
    print()

    # 关联记忆
    print(f"🔗 Neighbors of '{user.label}':")
    for n in mg.neighbors(user.id):
        print(f"  → {n.label} [{n.kind}]")
    print()

    # 统计
    print(f"📈 Stats: {json.dumps(mg.stats(), ensure_ascii=False, indent=2)}")

    # 模拟遗忘
    print("\n⏳ Simulating 7-day decay...")
    # 手动模拟：降低 accessed 时间
    mg.conn.execute("UPDATE nodes SET accessed = accessed - 604800")
    mg.conn.commit()
    mg.decay_all()
    print(mg.visualize_ascii())


# ------------------------------------------------------------------
# Temporal Entropy Tracker (Cycle 293)
# ------------------------------------------------------------------

class TemporalEntropyTracker:
    """Track spectral entropy of a MemoryGraph over time to detect
    phase transitions in the knowledge graph.

    Records snapshots of Von Neumann entropy (and optionally other
    indices) at regular intervals, then computes first and second
    derivatives to classify the graph's current **phase**:

    - ``growth``       — H increasing, nodes increasing (expanding)
    - ``consolidation``— H plateau, nodes stable (stable/healthy)
    - ``forgetting``   — H decreasing, nodes decreasing (pruning)
    - ``transition``   — sign change in second derivative (phase shift)
    - ``insufficient`` — < 2 snapshots (not enough data)

    Usage::

        tracker = TemporalEntropyTracker(mg)
        tracker.snapshot()           # record current state
        # ... add/remove nodes ...
        tracker.snapshot()           # record new state
        report = tracker.report()    # get trajectory analysis
    """

    def __init__(self, graph: "MemoryGraph", index: str = "von_neumann"):
        self.graph = graph
        self.index = index
        self.snapshots: list[dict] = []

    def snapshot(self, *, label: str = "") -> dict:
        """Record current entropy and graph statistics.

        Args:
            label:  Optional label for this snapshot.

        Returns:
            The recorded snapshot dict.
        """
        entropy_fn = {
            "von_neumann":      self.graph.von_neumann_entropy,
            "sombor":           self.graph.sombor_entropy,
            "randic":           self.graph.randic_entropy,
            "tsallis":           lambda normalized=True, **kw: self.graph.tsallis_entropy(q=2.0, normalized=normalized, **kw),
            "renyi":             lambda normalized=True, **kw: self.graph.renyi_entropy(alpha=2.0, normalized=normalized, **kw),
            "augmented_zagreb":  self.graph.augmented_zagreb_entropy,
            "edge_betweenness":  self.graph.edge_betweenness_entropy,
        }.get(self.index)
        if entropy_fn is None:
            raise ValueError(
                f"Unknown entropy index '{self.index}'. "
                f"Choose from: {', '.join(['von_neumann', 'sombor', 'randic', 'tsallis', 'renyi', 'augmented_zagreb', 'edge_betweenness'])}"
            )
        entropy = entropy_fn(normalized=False)
        entropy_norm = entropy_fn(normalized=True)
        stats = self.graph.stats()
        snap = {
            "seq":             len(self.snapshots),
            "label":           label,
            "entropy":         entropy if entropy is not None else 0.0,
            "entropy_norm":    entropy_norm if entropy_norm is not None else 0.0,
            "node_count":      stats.get("nodes", 0),
            "edge_count":      stats.get("edges", 0),
        }
        self.snapshots.append(snap)
        return snap

    def first_derivative(self) -> Optional[list[float]]:
        """Rate of change of entropy between consecutive snapshots."""
        if len(self.snapshots) < 2:
            return None
        derivs = []
        for i in range(1, len(self.snapshots)):
            d = self.snapshots[i]["entropy"] - self.snapshots[i - 1]["entropy"]
            derivs.append(d)
        return derivs

    def second_derivative(self) -> Optional[list[float]]:
        """Acceleration of entropy change (curvature)."""
        d1 = self.first_derivative()
        if d1 is None or len(d1) < 2:
            return None
        return [d1[i] - d1[i - 1] for i in range(1, len(d1))]

    def phase(self) -> str:
        """Classify the current phase of the knowledge graph.

        Returns one of: ``growth``, ``consolidation``, ``forgetting``
        ``transition``, ``insufficient``.
        """
        if len(self.snapshots) < 2:
            return "insufficient"
        d1 = self.first_derivative()
        d2 = self.second_derivative()
        last = self.snapshots[-1]
        prev = self.snapshots[-2]
        node_delta = last["node_count"] - prev["node_count"]
        rate = d1[-1] if d1 else 0.0
        eps = 1e-9
        # Check for transition (sign change in acceleration)
        if d2 and len(d2) >= 1:
            if abs(d2[-1]) > eps and len(d2) >= 2:
                # Sign flip in second derivative
                if d2[-1] * d2[-2] < -eps:
                    return "transition"
        # Classify based on rate and node_delta
        if rate > eps:
            return "growth"
        elif rate < -eps:
            if node_delta < 0:
                return "forgetting"
            return "forgetting"  # entropy declining regardless
        else:
            return "consolidation"

    def report(self) -> dict:
        """Full trajectory analysis report."""
        d1 = self.first_derivative()
        d2 = self.second_derivative()
        ents = [s["entropy"] for s in self.snapshots]
        nodes = [s["node_count"] for s in self.snapshots]
        return {
            "snapshots":         len(self.snapshots),
            "index":             self.index,
            "entropy_values":    ents,
            "entropy_normalized":[s["entropy_norm"] for s in self.snapshots],
            "node_counts":       nodes,
            "edge_counts":       [s["edge_count"] for s in self.snapshots],
            "first_derivative":  d1 if d1 else [],
            "second_derivative": d2 if d2 else [],
            "current_phase":     self.phase(),
            "mean_rate":         (sum(d1) / len(d1)) if d1 else 0.0,
            "volatility":        (sum(x * x for x in d1) / len(d1)) if d1 else 0.0,
            "labels":            [s["label"] for s in self.snapshots],
        }


if __name__ == "__main__":
    demo()
